    ["-1455461060924709239"] = "ǥƾễǃǦƷƾệǉǦǂọƾǦǃƼườƾ",
    ["-3527533844716990262"] = "ǥƾễǃǦƷƾệǉǦǂọƾǦǃƼườƾ",
    ["4770822488881685539"] = "ƩƼươƾǦƸũǃƼǦǂǊốǃ",
    ["-7650289877247075013"] = "ĐƾǦƢƾƶǃƼǦƩƶǂ",
    ["5880414972494840175"] = "ǥỷǦǉỷǦǂǊốǃǦǀƽǊƇǃǦǂặǉǦƸủƶǦǂǊộƾ",
    ["-6306951939809426590"] = "ƨǊộƾǦǋǊƾǦǁắǂ",
    ["6799135257949226543"] = "ƩƼươƾǦǃƚƾǦǍƺǂ",
    ["-4110582413193767802"] = "ƩếǊǦđứƶǦǉǇẻǦđƚǦǃƽƔǃǦǉƽấǓǦǀƽǊƇǃǦǂặǉǦǃƐǓ",
    ["4620015662440602503"] = "ƦƽƾǦǃƐǃƼǦǉǊốǉǦǀƾếǂ",
    ["-1342619632646891852"] = "ƧƾệǊǦƸƚǦƷƾếǉǦǀƽƇǃƼ",
    ["-8640307787950208648"] = "ǥƶǦƸƽƓǃƽǦǁƐǦǉƽƓƸƽ",
    ["74885671111029884"] = "ǥƶǦƸƽƓǃƽǦǁƐǦǉƽƓƸƽǦƸƑƾǦǤƑǃƼǦǋẻǦǃƐǓǦƸủƶǦǃƼươƾ",
    ["8353775994204822148"] = "ƩƼươƾǦǉǇướƸǦǃƶǓǦđềǊ",
    ["-8038304465702826928"] = "ǥǊǓệǉǦǉƔǃƽǦǃƽưǦǋậǓ",
    ["-246111586243068748"] = "ƱẫǃǦƸƛǃǦǈốǃƼǦǈƶǄ",
    ["-6112989498462748142"] = "ǥƶǦƸƛǃǦǉưởǃƼ",
    ["-2166671309502837591"] = "ƞǊốƾǦƸƖǃƼǦƸũǃƼǦƸƚǦǉƽểǦǤƖǃƼǦĐốǃƼǦǥửǦƞốǉǦƸƽǄǦǃƼươƾǦǇồƾ",
    ["-7066208506713243785"] = "ƳƺǂǦǇƶǦǃƼươƾǦǅƽảƾǦǉƽấǉǦǋọǃƼǦǇồƾ",
    ["-8325697168917840183"] = "ƩƽờǦǅƽƕƸǦƸủƶǦǃƐǃƼ",
    ["-7323319584855641164"] = "ǥƁǂǦƸủƶǦǉƶǦǀƽƇǃƼǦƸƛǃǦởǦđƁǓǦǃữƶ",
    ["-1683694159050703355"] = "ƴếǃǦƽƾềǂǦǉƁǃǦǅƽǄǃƼǦǁƶƾ",
    ["6758082210473550683"] = "ǝướƾǦǈựǦƼƾƕǅǦđỡǦƸủƶǦǂọƾǦǃƼườƾ,ǦƸƇǃƼǦǉƑƸǦǉƑƾǦǉƽƾếǉǦƸơǦƷảǃǦđƃǦƽǄƐǃǦǉƽƐǃƽ.ǦƣƇǂǦǃƶǓǦǁƐǦǂộǉǦǃƼƐǓǦđẹǅǦǉǇờƾ,ǦǂọƾǦǃƼườƾǦđềǊǦƽộƾǦǉụǦǉạƾǦǃơƾǦǃƐǓ.",
    ["把它放在城里，你不怕有人无意动了它？"] = "ĐặǉǦǃƚǦởǦǉǇǄǃƼǦǉƽƐǃƽ,ǦǃƼươƾǦǀƽƇǃƼǦǈợǦƸƚǦǀẻǦǋƇǦƈǦđộǃƼǦǋƐǄǦǈƶǄ?",
    ["……不会。配方已毁，器具封存。"] = "...ǦƦƽƇǃƼǦđƁǊ.ǦƫƽốƾǦǅƽươǃƼǦđƃǦƽủǓ,ǦǀƽƓǦƸụǦđƃǦǅƽǄǃƼǦǉồǃ.",
    ["什么时候封存的？"] = "ƫƽǄǃƼǦǉồǃǦǉừǦǀƽƾǦǃƐǄ?",
    ["父亲，将死。无法指引。令 tôi 停下，封存，等待。"] = "ƫƽụǦǉƽƁǃ,ǦǁƁǂǦƸƽǊǃƼ.ǦƦƽƇǃƼǦǉƽểǦƸƽỉǦǤẫǃ.ǦƧệǃƽǦǉƶǦǤừǃƼǦǁạƾ,ǦǅƽǄǃƼǦǉồǃ,ǦƸƽờǦđợƾ.",
    ["隼。"] = "ƞƽǊẩǃ.",
    ["乌金炼制，需待时机。或停或启，皆询于他。"] = "ƧǊǓệǃǦƸƽếǦƆǦƦƾǂ,ǦǅƽảƾǦđợƾǦǉƽờƾǦƸơ.ǦǝừǃƼǦƽƶǓǦǂở,ǦđềǊǦǅƽảƾǦƽỏƾǦƈǦǃƼườƾ.",
    ["但……他走了。"] = "ƩƽưǃƼ...ǦǃƼườƾǦđƃǦđƾǦǇồƾ.",
    ["走了？……我是说，从今以后， I 来代替他——"] = "ĐƾǦǇồƾǦǈƶǄ?...ǦÝǦǉƶǦǁƐ,ǦǉừǦǃƶǓǦǋềǦǈƶǊ,ǦǉƶǦǈẽǦǉƽƶǓǦǉƽếǦǃƼườƾ——",
    ["向前。"] = "ǥƾếǃǦǋềǦǅƽƓƶǦǉǇướƸ.",
    ["……谢谢爷爷。"] = "...ǦǥạǦơǃǦƼƾƶǦƼƾƶ.",
    ["你——你怎么跑到那上面去了！？"] = "ƞǄǃ——ǦǈƶǄǦƸǄǃǦǁạƾǦƸƽạǓǦǁƙǃǦǉǇƙǃǦđƚǦǉƽếǦǀƾƶ!?",
    ["我看到坏蛋了！是发粮食的时候推大姐姐、教张牛改锯子的坏蛋——坏蛋避着人，但我看见了！"] = "ƞǄǃǦǉƽấǓǦǀẻǦǍấǊǦǇồƾ!ǦƧƐǦǀẻǦđƃǦđẩǓǦđạƾǦǉỷǦǉỷǦǁƕƸǦǅƽƑǉǦǁươǃƼǦǉƽựƸ,ǦǀẻǦđƃǦǤạǓǦǥǇươǃƼǦƩƼưǊǦǈửƶǦƸưƶǦđƚ——ǦǀẻǦǍấǊǦǁẩǃǦǉǇƑǃƽǦǂọƾǦǃƼườƾ,ǦǃƽưǃƼǦƸǄǃǦđƃǦǃƽƔǃǦǉƽấǓ!",
    ["你一个小孩！嗨！……你，你……快随他们下去吧。"] = "ƞǄǃǦǉƽậǉǦǁƐ,ǦǉǇẻǦƸǄǃǦǉǇẻǦƸƑƾ!ǦƣƶƾǏ!...ǦƞǄǃ,ǦƸǄǃ...ǦǂƶǊǦǉƽƺǄǦƽọǦǍǊốǃƼǦǤướƾǦđƾ.",
    ["小桃宝看见的那人怕就是之前潜伏在墨门中的奸细……看来不是千夜。"] = "ƦẻǦǂƐǦǥƾểǊǦĐƐǄǦƝảǄǦǃƽƔǃǦǉƽấǓǦƺǦǇằǃƼǦƸƽƓǃƽǦǁƐǦƼƾƶǃǦǉếǦẩǃǦǃấǅǦǉǇǄǃƼǦƨặƸǦǂƇǃǦƷấǓǦǁƁǊǦǃƶǓ...ǦǍƺǂǦǇƶǦǀƽƇǃƼǦǅƽảƾǦǥƽƾƙǃǦǝạ.",
    ["但那人一定在启动飞天城的这些人里……"] = "ƩƽưǃƼǦǀẻǦđƚǦƸƽắƸǦƸƽắǃǦǃằǂǦǉǇǄǃƼǦǈốǦǃƽữǃƼǦǃƼườƾǦđƶǃƼǦǀƽởƾǦđộǃƼǦƫƽƾǦǥƽƾƙǃǦǥƽƐǃƽ...",
    ["奸细，启动……"] = "ƢƾƶǃǦǉế,ǦǀƽởƾǦđộǃƼ...",
    ["要炸城？"] = "ĐịǃƽǦǃổǦǉƽƐǃƽǦǈƶǄ?",
    ["金乌窠，失败品。点燃，则炉炸城毁。三年前，便是如此。"] = "ƦƾǂǦƆǦƮƐǄ,ǦǅƽếǦǅƽẩǂ.ǦĐƾểǂǦƽỏƶ,ǦắǉǦǁƛǦǃổǦǉƽƐǃƽǦǉƶǃ.ǦƝƶǦǃăǂǦǉǇướƸ,ǦƸƽƓǃƽǦǁƐǦǃƽưǦǋậǓ.",
    ["那、那鸰儿，城里的这群孩子……！"] = "ƱậǓ,ǦǋậǓǦƧƾǃƽǦǃƽƾ,ǦđƑǂǦǉǇẻǦǉǇǄǃƼǦǉƽƐǃƽǦǉƽƔǦǈƶǄ...!",
    ["阻止他们。"] = "ƩƼăǃǦƷọǃǦƸƽƕǃƼǦǁạƾ.",
    ["但也要咱们上得去啊！"] = "ƩƽưǃƼǦƸũǃƼǦǅƽảƾǦǁƙǃǦđượƸǦǉǇƙǃǦđƚǦđƃǦƸƽứ!",
    ["通路刚被炸毁，我们怎么过去，凭空——"] = "ƧốƾǦđƾǦǋừƶǦƷịǦǃổǦǈậǅǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦǆǊƶǦđƚǦƷằǃƼǦƸƑƸƽǦǃƐǄ,ǦƸƽẳǃƼǦǁẽǦđạǅǦǀƽƇǃƼ——",
    ["飞过去。"] = "ƝƶǓǦǆǊƶǦđƚ.",
    ["墨门弟子，以身逐天。"] = "ĐệǦǉửǦƨặƸǦǂƇǃ,ǦǁấǓǦǉƽƁǃǦđǊổƾǦǉǇờƾ.",
    ["弟子入门都要造机关鸟以示逐天之意。但能带人的鸟甚是难得，连大匠也未必都造得出。得去找鹭……"] = "ĐệǦǉửǦǃƽậǅǦǂƇǃǦđềǊǦǅƽảƾǦƸƽếǦǉạǄǦƸơǦǆǊƶǃǦđƾểǊǦđểǦƷƾểǊǦǉƽịǦƈǦƸƽƓǦđǊổƾǦǉǇờƾ.ǦƩƽưǃƼǦǁǄƐƾǦđƾểǊǦƸƚǦǉƽểǦƸƽởǦǃƼườƾǦƸựƸǦǀỳǦƽƾếǂǦǉƽấǓ,ǦǃƼƶǓǦƸảǦđạƾǦǉượǃƼǦƸũǃƼǦƸƽưƶǦƸƽắƸǦǉạǄǦǇƶǦđượƸ.ǦƫƽảƾǦđƾǦǉƔǂǦƧộ...",
    ["无需巧器。众鸟聚合，以身为桥，助我登天。"] = "ƦƽƇǃƼǦƸầǃǦǍảǄǦǀƽƓ.ǦƞƽƕǃƼǦđƾểǊǦǉụǦǁạƾ,ǦǁấǓǦǉƽƁǃǦǁƐǂǦƸầǊ,ǦǉǇợǦǉƶǦđăǃƼǦǉƽƾƙǃ.",
    ["靠小弟子们造着玩的……木鸟？这也太离奇……"] = "ǝựƶǦǋƐǄǦǂấǓǦƸǄǃ...ǦǂộƸǦđƾểǊǦđồǦƸƽơƾǦƸủƶǦđƑǂǦǉƾểǊǦđệǦǉửǦǈƶǄ?ǦƞƽǊǓệǃǦǃƐǓǦǆǊƑǦǂứƸǦǁǓǦǀỳǦǇồƾ...",
    ["以鸟为阶，踏而奔之。成者，百五十。"] = "ƧấǓǦđƾểǊǦǁƐǂǦƷậƸ,ǦđạǅǦƷướƸǦǂƐǦƽƐǃƽ.ǦǥỷǦǁệǦǉƽƐǃƽǦƸƇǃƼ,ǦđượƸǦǅƽƁǃǦǃửƶ.",
    ["就这么办！你想不出法子来就让有法子的人上！燕，你这就去跟弟子们说——"] = "ƞứǦǆǊǓếǉǦđịǃƽǦǉƽếǦđƾ!ǦƣǊǓǃƽǦǀƽƇǃƼǦǃƼƽĩǦǇƶǦƸƑƸƽǦǉƽƔǦđểǦǃƼườƾǦƸƚǦƸƑƸƽǦǁƐǂ!Ǧƴếǃ,ǦƸƇǦǂƶǊǦđƾǦǃƚƾǦǋớƾǦƸƑƸǦđệǦǉửǦđƾ——",
    ["我不可。"] = "ǥƶǦǀƽƇǃƼǦǉƽể.",
    ["出面之人，需有威信。懂原理。聚人心。诸位……"] = "ƩƼườƾǦđứǃƼǦǇƶ,ǦƸầǃǦƸƚǦǊǓǦǉƓǃ.ǦƣƾểǊǦǃƼǊǓƙǃǦǁƈ.ǦǥụǦǃƽƁǃǦǉƁǂ.ǦƞƽưǦǋị...",
    ["……巨子。"] = "...ǦƞựǦǥử.",
    ["巨子方才所为，正是“巨子”之事。"] = "ƩƽữǃƼǦƼƔǦƞựǦǥửǦǋừƶǦǁƐǂ,ǦƸƽƓǃƽǦǁƐǦǋƾệƸǦƸủƶǦǂộǉǦ\"ƞựǦǥử\".",
    ["我与弟子们，只认巨子。"] = "ǥƶǦǋƐǦƸƑƸǦđệǦǉử,ǦƸƽỉǦƸƇǃƼǦǃƽậǃǦƞựǦǥử.",
    ["飞天城怎么启动了？是谁启动的？长老？巨子？"] = "ƮƶǄǦƫƽƾǦǥƽƾƙǃǦǥƽƐǃƽǦǁạƾǦǀƽởƾǦđộǃƼǦǇồƾ?ǦƧƐǦƶƾǦǁƐǂǦǉƽế?ǦǥǇưởǃƼǦǁƃǄ?ǦƣƶǓǦƞựǦǥử?",
    ["我乃……燕。有人，启动飞天城。"] = "ǥƶǦǁƐ...Ǧƴếǃ.ǦƞƚǦǀẻǦđƶǃƼǦǀƽởƾǦđộǃƼǦƫƽƾǦǥƽƾƙǃǦǥƽƐǃƽ.",
    ["飞天城核心，金乌窠，有缺。启动，则炸毁。坠天夜，真相如此。"] = "ƞốǉǦǁƅƾǦƫƽƾǦǥƽƾƙǃǦǥƽƐǃƽ,ǦƦƾǂǦƆǦƮƐǄ,ǦƸƚǦƸƽỗǦǉƽƾếǊǦǈƚǉ.ǦƦƽởƾǦđộǃƼ,ǦắǉǦǈẽǦǃổǦǉǊǃƼ.ǦĐƙǂǦǥƽƾƙǃǦǥǇụǓ,ǦƸƽƁǃǦǉướǃƼǦƸƽƓǃƽǦǁƐǦǃƽưǦǋậǓ.",
    ["……可操金乌窠者，唯 I 一人。"] = "...ǦƩƼườƾǦƸƚǦǉƽểǦǉƽƶǄǦǉƕǃƼǦƦƾǂǦƆǦƮƐǄ,ǦƸƽỉǦƸƚǦǂƔǃƽǦǉƶ.",
    ["如今，需入门木鸟三百，架为天桥，助 I 登城。"] = "ƩƶǓ,ǦƸầǃǦƷƶǦǉǇăǂǦǂộƸǦđƾểǊǦǃƽậǅǦǂƇǃ,ǦƷắƸǦǉƽƐǃƽǦǉƽƾƙǃǦǀƾềǊ,ǦǉǇợǦǉƶǦđăǃƼǦǉƽƐǃƽ.",
    ["天桥之成，百之五十。熄金乌窠，不足四十。"] = "ǥƽƾƙǃǦǀƾềǊǦƷắƸǦǍǄǃƼ,ǦǉƽƐǃƽǦƷạƾǦǃăǂǦǅƽƁǃ.ǦǝậǅǦǉắǉǦƦƾǂǦƆǦƮƐǄ,ǦƸơǦƽộƾǦƸƽưƶǦǉớƾǦƷốǃǦǅƽầǃ.",
    ["鸟是，朋友。"] = "ĐƾểǊǦǃƽƾǦǁƐ,ǦƷằǃƼǦƽữǊ.",
    ["诸位之友，将赴火海，十死无生。"] = "ƝằǃƼǦƽữǊǦƸủƶǦƸƽưǦǋị,ǦǈắǅǦǅƽảƾǦǤấǃǦǉƽƁǃǦǋƐǄǦƷƾểǃǦǁửƶ,ǦǂườƾǦǅƽầǃǦƸƽếǉǦǀƽƇǃƼǦǅƽầǃǦǈốǃƼ.",
    ["我就知道她一开口就坏事……"] = "ǥƶǦƷƾếǉǦǃƼƶǓǦǂƐ,ǦƸƇǦǉƶǦƸứǦǂởǦǂƾệǃƼǦǁƐǦƽỏǃƼǦǋƾệƸ...",
    ["……只怕，也是唯一可试之法了。"] = "...ǦǑǦǇằǃƼ,ǦđƁǓǦƸũǃƼǦǁƐǦƸƑƸƽǦǤǊǓǦǃƽấǉǦƸƚǦǉƽểǦǉƽửǦǇồƾ.",
    ["以上。是全部。我已言明。"] = "ǥǇƙǃǦđƁǓ.ǦƧƐǦǉǄƐǃǦƷộ.ǦǥƶǦđƃǦǃƚƾǦǇƅ.",
    ["诸位，助 I 登城。"] = "ƞƽưǦǋị,ǦǉǇợǦǉƶǦđăǃƼǦǉƽƐǃƽ.",
    ["意思就是就算上去也可能熄不了咯？"] = "ÝǦǁƐǦǤẫǊǦƸƚǦǁƙǃǦđượƸǦƸũǃƼǦƸƽưƶǦƸƽắƸǦǤậǅǦǉắǉǦđượƸǦǈƶǄ?",
    ["弟子甲"] = "ĐệǦǉửǦƢƾƑǅ",
    ["我、我虽愚钝，但师父待我好。我……——巨子，我来助你。"] = "Đệ...ǦđệǦǉǊǓǦǃƼǊǦǂǊộƾ,ǦǃƽưǃƼǦǈưǦǅƽụǦđốƾǦǍửǦǋớƾǦđệǦǇấǉǦǉốǉ.ǦĐệ...——ǦƞựǦǥử,ǦđệǦǉớƾǦǉǇợǦǃƼườƾ.",
    ["……去吧。"] = "...ǦĐƾǦđƾ.",
    ["弟子乙"] = "ĐệǦǉửǦẤǉ",
    ["你做什么！你没听她说吗！是她害死了隼——"] = "ƣǊǓǃƽǦǁƐǂǦƸƑƾǦƼƔǦǉƽế!ǦƣǊǓǃƽǦǀƽƇǃƼǦǃƼƽƺǦƸƇǦǉƶǦǃƚƾǦǈƶǄ!ǦƞƽƓǃƽǦƸƇǦǉƶǦđƃǦƽạƾǦƸƽếǉǦƞƽǊẩǃ——",
    ["她今日是去救人。"] = "ƣƇǂǦǃƶǓǦƸƇǦấǓǦđƾǦƸứǊǦǃƼườƾ.",
    ["那也是徒劳！烧到一半的炉子怎么熄！"] = "ĐƚǦƸũǃƼǦǁƐǦǊổǃƼǦƸƇǃƼǦǉƽƇƾ!ǦƧƛǦđƶǃƼǦƸƽƑǓǦǤởǦǁƐǂǦǈƶǄǦǂƐǦǤậǅ!",
    ["……就算徒劳，我也想试试。"] = "...ǦǝẫǊǦǁƐǦǊổǃƼǦƸƇǃƼ,ǦđệǦƸũǃƼǦǂǊốǃǦǉƽửǦǂộǉǦǁầǃ.",
    ["我也来！我相信巨子，她本可以骗我们，说些漂亮话……"] = "ǥƶǦƸũǃƼǦǉớƾ!ǦǥƶǦǉƾǃǦǉưởǃƼǦƞựǦǥử,ǦǃƼườƾǦǋốǃǦǤĩǦƸƚǦǉƽểǦǁừƶǦƼạǉǦƸƽƕǃƼǦǉƶ,ǦǃƚƾǦǃƽữǃƼǦǁờƾǦƽǄƶǦǂỹ...",
    ["巨子——巨子——我们等你回来——"] = "ƞựǦǥử——ǦƞựǦǥử——ǦƸƽƕǃƼǦǉƶǦđợƾǦǃƼườƾǦǉǇởǦǋề——",
    ["墨子为木鸢，飞一日而败。"] = "ƨặƸǦǥửǦǉạǄǦǂộƸǦǤƾƙǊ,ǦƷƶǓǦǂộǉǦǃƼƐǓǦǁƐǦƽỏǃƼ.",
    ["公输造木鹊，三日不下。然墨子言，利于人谓之巧，不利人谓之拙。"] = "ƞƇǃƼǦǥƽƕǦǉạǄǦǂộƸǦǉướƸ,ǦƷƶǦǃƼƐǓǦǀƽƇǃƼǦǍǊốǃƼ.ǦƩƽưǃƼǦƨặƸǦǥửǦǃƚƾ,ǦƸƚǦǁợƾǦƸƽǄǦǃƼườƾǦƼọƾǦǁƐǦƦƽƗǄǦ(ƳảǄ),ǦǀƽƇǃƼǦǁợƾǦƸƽǄǦǃƼườƾǦƼọƾǦǁƐǦƱụǃƼǦ(ƞƽǊǓếǉ).",
    ["老东西，你要当个巧物，还是个拙物？"] = "ƧƃǄǦƼƾƐǦǀƾƶ,ǦǃƼươƾǦǂǊốǃǦǁƐǂǦǂộǉǦǋậǉǦǀƽƗǄ,ǦƽƶǓǦǁƐǦǂộǉǦǋậǉǦǋụǃƼ?",
    ["去吧，去吧……"] = "ĐƾǦđƾ,ǦđƾǦđƾ...",
    ["杀了他们！"] = "ƢƾếǉǦƸƽƕǃƼǦƸƽǄǦǉƶ!",
    ["这里也有穷奇师？"] = "ỞǦđƁǓǦƸũǃƼǦƸƚǦƞƖǃƼǦƦỳǦƮưǦǈƶǄ?",
    ["金乌窠在下，扶桑舵在上。若要飞天，需一人执辔——"] = "ƦƾǂǦƆǦƮƐǄǦởǦǤướƾ,ǦƫƽƖǦǥƶǃƼǦĐƐǦởǦǉǇƙǃ.ǦƩếǊǦǂǊốǃǦǅƽƾǦǉƽƾƙǃ,ǦƸầǃǦǂộǉǦǃƼườƾǦƸầǂǦǁƑƾ——",
    ["一人一个是吧！你去金乌窠，我去找那什么舵——"] = "ƨỗƾǦǃƼườƾǦǂộǉǦǃơƾǦƸƽứǦƼƔ!ǦƩƼươƾǦđếǃǦƦƾǂǦƆǦƮƐǄ,ǦǉƶǦđƾǦǉƔǂǦƸƑƾǦƷƑǃƽǦǁƑƾǦƼƔǦđƚ——",
    ["城中有穷奇师，此地危险，你们快走！"] = "ǥǇǄǃƼǦǉƽƐǃƽǦƸƚǦƞƖǃƼǦƦỳǦƮư,ǦǃơƾǦǃƐǓǦǃƼǊǓǦƽƾểǂ,ǦƸƑƸǦǃƼươƾǦǂƶǊǦđƾǦđƾ!",
    ["放心，他们奈何不了我。"] = "ƴƙǃǦǉƁǂ,ǦƸƽƕǃƼǦǀƽƇǃƼǦǁƐǂǦƼƔǦđượƸǦǉƶǦđƁǊ.",
    ["因为他们根本就是你的人吧。"] = "ƝởƾǦǋƔǦƸƽƕǃƼǦƸăǃǦƷảǃǦđềǊǦǁƐǦǃƼườƾǦƸủƶǦƇǃƼǦǂƐ.",
    ["鹏长老，我一直有个疑惑——"] = "ƝằǃƼǦǉǇưởǃƼǦǁƃǄ,ǦǉƶǦǋẫǃǦǁǊƇǃǦƸƚǦǂộǉǦđƾềǊǦǃƼƽƾǦƽǄặƸ——",
    ["为何那“司南剑客”能藏在我们中间却无人发觉？"] = "ƱƔǦǈƶǄǦǉƙǃǦ\"ǥưǦƩƶǂǦǀƾếǂǦǀƽƑƸƽ\"ǦǀƾƶǦƸƚǦǉƽểǦẩǃǦǂƔǃƽǦƼƾữƶǦƸƽƕǃƼǦǉƶǦǂƐǦǀƽƇǃƼǦƶƾǦǅƽƑǉǦƼƾƑƸ?",
    ["为什么穷奇师对墨门秘辛知之甚详，神出鬼没——"] = "ƱƔǦǈƶǄǦƞƖǃƼǦƦỳǦƮưǦǁạƾǦǉườǃƼǦǉậǃǦƷƓǦǂậǉǦƨặƸǦǂƇǃǦđếǃǦǉƽế,ǦƽƐǃƽǦǉǊǃƼǦǁạƾǦǉƽầǃǦǍǊấǉǦǆǊỷǦǃƽậǅ——",
    ["什么伪装，能让这么多人藏得天衣无缝？"] = "ƧǄạƾǦǃƼụǓǦǉǇƶǃƼǦǃƐǄǦƸƚǦǉƽểǦǀƽƾếǃǦǃƼầǃǦấǓǦǃƼườƾǦẩǃǦƼƾấǊǦǉƽƾƙǃǦǓǦǋƇǦǅƽƖǃƼ?",
    ["或许，他们其实不需要伪装，因为他们根本就是，或曾经是，墨山道的人。"] = "ƞƚǦǁẽ,ǦƸƽƕǃƼǦǉƽựƸǦƸƽấǉǦǀƽƇǃƼǦƸầǃǦǃƼụǓǦǉǇƶǃƼ,ǦǋƔǦƸƽƕǃƼǦǋốǃǦǤĩǦƸƽƓǃƽǦǁƐ,ǦƽǄặƸǦǉừǃƼǦǁƐǦǃƼườƾǦƸủƶǦƨặƸǦƮơǃǦđạǄ.",
    ["你说对吗，鹏长老。"] = "ǥƶǦǃƚƾǦƸƚǦđƕǃƼǦǀƽƇǃƼ,ǦƝằǃƼǦǉǇưởǃƼǦǁƃǄ.",
    ["燕，你怎么想。"] = "ƴếǃ,ǦǃƼươƾǦǃƼƽĩǦǉƽếǦǃƐǄ.",
    ["……为什么。这么做。"] = "...ǦǥạƾǦǈƶǄ.ǦƧạƾǦǁƐǂǦǉƽế.",
    ["因为墨门。"] = "ƱƔǦƨặƸǦǂƇǃ.",
    ["墨门？"] = "ƨặƸǦǂƇǃ?",
    ["从墨门退至山中时，便注定有今日之争了。"] = "ǥừǦǀƽƾǦƨặƸǦǂƇǃǦǁǊƾǦǋềǦǉǇǄǃƼǦǃƕƾ,ǦđƃǦđịǃƽǦǈẵǃǦƸƚǦƸǊộƸǦǉǇƶǃƽǦƸƽấǅǦǃƼƐǓǦƽƇǂǦǃƶǓ.",
    ["墨者同心同德死不旋踵，又有世所罕见的机巧，"] = "ƨặƸǦƼƾảǦđồǃƼǦǉƁǂǦđồǃƼǦđứƸ,ǦƸƽếǉǦǀƽƇǃƼǦǁƖƾǦƷướƸ,ǦǁạƾǦƸƚǦƸơǦǍảǄǦƽƾếǂǦǉƽấǓǦǉǇƙǃǦđờƾ,",
    ["却从“天下之言不归杨则归墨”的兴盛，沦落到只能寻一孤地落脚，又是因何而起，巨子想过吗？"] = "ǥƽếǦǃƽưǃƼǦǉừǦǉƽǊởǦƽưǃƼǦǉƽịǃƽǦ\"ǁờƾǦǉƽƾƙǃǦƽạǦǀƽƇǃƼǦǉƽƺǄǦǝươǃƼǦǉấǉǦǉƽƺǄǦƨặƸ\",ǦǁạƾǦǈƶǦǈƕǉǦđếǃǦǂứƸǦƸƽỉǦƸƚǦǉƽểǦǉƔǂǦǃơƾǦƽẻǄǦǁƑǃƽǦđặǉǦƸƽƁǃ,ǦǃƼǊǓƙǃǦǤǄǦǉừǦđƁǊǦǂƐǦǇƶ,ǦƞựǦǥửǦđƃǦǉừǃƼǦǃƼƽĩǦǆǊƶǦƸƽưƶ?",
    ["巨子可还记得，墨经除去兼爱非攻，还讲了什么？"] = "ƞựǦǥửǦƸƛǃǦǃƽớ,ǦƨặƸǦǀƾǃƽǦǃƼǄƐƾǦƦƾƙǂǦƑƾǦƫƽƾǦƸƇǃƼǦǇƶ,ǦƸƛǃǦƼƾảǃƼǦǃƽữǃƼǦƼƔǦǀƽƇǃƼ?",
    ["尚同，节用，明鬼……"] = "ǥƽượǃƼǦđồǃƼ,ǦǥƾếǉǦǤụǃƼ,ǦƨƾǃƽǦǆǊỷ...",
    ["这便是了。"] = "ƞƽƓǃƽǦǁƐǦǃƚǦǋậǓ.",
    ["墨家之弊，不在器不够巧，不在侠不够勇，在墨经，在无人重读墨经啊。"] = "ƞƑƾǦǉệǦƸủƶǦƨặƸǦƼƾƶ,ǦǀƽƇǃƼǦǅƽảƾǦởǦǀƽƓǦƸụǦǀƽƇǃƼǦđủǦǀƽƗǄ,ǦǀƽƇǃƼǦǅƽảƾǦởǦƽƾệǅǦǀƽƑƸƽǦǀƽƇǃƼǦđủǦǤũǃƼ,ǦǂƐǦởǦƨặƸǦǀƾǃƽ,ǦởǦƸƽỗǦǀƽƇǃƼǦƶƾǦđọƸǦǁạƾǦƨặƸǦǀƾǃƽǦǋậǓ.",
    ["为何。"] = "ƱƔǦǈƶǄ.",
    ["因为兼爱，须在节用后。节用，又在尚同后。"] = "ƝởƾǦǋƔǦƦƾƙǂǦƑƾǦǅƽảƾǦđặǉǦǈƶǊǦǥƾếǉǦǤụǃƼ.ǦǥƾếǉǦǤụǃƼǦǁạƾǦđặǉǦǈƶǊǦǥƽượǃƼǦđồǃƼ.",
    ["人生于世，于牛羊刍狗本无异。古仁人食树果，饮清泉，足以终余年。"] = "ƩƼườƾǦǈƾǃƽǦǉạƾǦǉƽế,ǦǋốǃǦƸƽẳǃƼǦǀƽƑƸǦƼƔǦǉǇƁǊǦǤƙǦǈƐǃƽǦƸƽƚ.ǦƩƽƁǃǦǈĩǦƸổǦđạƾǦăǃǦǆǊảǦƸƁǓ,ǦǊốǃƼǦǈǊốƾǦǉǇǄǃƼ,ǦƸũǃƼǦđủǦǈốǃƼǦǉǇọǃǦđờƾ.",
    ["但人食树果，便想窝头，食饱窝头，便想米面。食饱米面，便想酒肉……"] = "ƩƽưǃƼǦǃƼườƾǦăǃǦǆǊảǦƸƁǓǦǁạƾǦǉƽƘǂǦƷƑǃƽǦƷộǉ,ǦăǃǦǃǄǦƷƑǃƽǦƷộǉǦǁạƾǦǃƼƽĩǦđếǃǦƸơǂǦƼạǄ.ǦĂǃǦǃǄǦƸơǂǦƼạǄǦǁạƾǦǂǊốǃǦƸƚǦǇượǊǦǉƽịǉ...",
    ["人心不足，难以节用，是灾祸之根。"] = "ƧƛǃƼǦǃƼườƾǦǀƽƇǃƼǦđƑǓ,ǦǀƽƚǦƷềǦǉƾếǉǦǤụǃƼ,ǦđƚǦƸƽƓǃƽǦǁƐǦƸăǃǦǃƼǊǓƙǃǦƸủƶǦǉƶƾǦƽọƶ.",
    ["人心不足，墨者喂之。"] = "ƧƛǃƼǦǃƼườƾǦǀƽƇǃƼǦđủ,ǦƨặƸǦƼƾảǦǁấǅǦđầǓ.",
    ["人求米面，墨者铸铁犁造木牛，以养天下；"] = "ƩƼườƾǦƸầǊǦƸơǂǦƼạǄ,ǦƨặƸǦƼƾảǦđƕƸǦƸƐǓǦǈắǉǦƸƽếǦǂộƸǦǃƼưǊǦđểǦǃǊƇƾǦǉƽƾƙǃǦƽạ;",
    ["人求酒肉，墨者酿美酒养肥豕，以飨众生。"] = "ƩƼườƾǦƸầǊǦǇượǊǦǉƽịǉ,ǦƨặƸǦƼƾảǦǃấǊǦǇượǊǦǃƼǄǃǦǃǊƇƾǦǁợǃǦƷƗǄǦđểǦǉƽếǉǦđƃƾǦƸƽƕǃƼǦǈƾǃƽ.",
    ["好久没听到了，这可笑的宏愿。"] = "ƧƁǊǦǇồƾǦǂớƾǦđượƸǦǃƼƽƺǦǁạƾǦƸƑƾǦƽồǃƼǦǃƼǊǓệǃǦǃựƸǦƸườƾǦǃƐǓ.",
    ["可这节用之上，还有一层。"] = "ǥƽếǦǃƽưǃƼǦǉǇƙǃǦǥƾếǉǦǤụǃƼ,ǦǋẫǃǦƸƛǃǦǂộǉǦǉầǃƼǦǃữƶ.",
    ["巨子怎知现在世上的米面，就不够人吃饱呢？"] = "ƞựǦǥửǦǈƶǄǦƷƾếǉǦƸơǂǦƼạǄǦǉǇƙǃǦǉƽếǦƼƾƶǃǦƽƾệǃǦǃƶǓǦǀƽƇǃƼǦđủǦƸƽǄǦǃƼườƾǦǉƶǦăǃǦǃǄ?",
    ["或许这世上的米面早已够吃了。"] = "ƞƚǦǁẽǦƸơǂǦƼạǄǦǉǇƙǃǦđờƾǦǃƐǓǦǈớǂǦđƃǦđủǦăǃǦǇồƾ.",
    ["只是这些米面并未变成冻死骨的口中食，而是成了朱门后的酒肉臭……"] = "ƞƽỉǦǁƐǦǃƽữǃƼǦƽạǉǦƼạǄǦấǓǦǀƽƇǃƼǦƷƾếǃǦǉƽƐǃƽǦǉƽứƸǦăǃǦǉǇǄǃƼǦǂƾệǃƼǦǀẻǦǈắǅǦƸƽếǉǦđƚƾ,ǦǂƐǦǁạƾǦǉǇởǦǉƽƐǃƽǦǂƖƾǦǇượǊǦǉƽịǉǦǉƽốƾǦǈƶǊǦƸƑǃƽǦƸửƶǦǈǄǃ...",
    ["若不尚同，墨门纵是造出金山银海，又如何够分呢。"] = "ƩếǊǦǀƽƇǃƼǦǥƽượǃƼǦđồǃƼ,ǦƨặƸǦǂƇǃǦǤẫǊǦƸƚǦǉạǄǦǇƶǦǃƕƾǦǋƐǃƼǦƷƾểǃǦƷạƸ,ǦǉƽƔǦƸƽƾƶǦǉƽếǦǃƐǄǦƸƽǄǦđủ.",
    ["一个馒头，让出去便死，抢到手就活。每当尸骨又多起来，义庄中堆满的往往先是善人残躯。"] = "ƨộǉǦƸƽƾếƸǦǂƐǃǦǉƽầǊ,ǦǃƽườǃƼǦǇƶǦǉƽƔǦƸƽếǉ,ǦƸướǅǦǁấǓǦǉƽƔǦǈốǃƼ.ǦƨỗƾǦǀƽƾǦǍươǃƼǦǉǇắǃƼǦƸƽấǉǦƸƶǄ,ǦǃơƾǦǃƼƽĩƶǦǉǇƶǃƼǦƸƽấǉǦđầǓǦǉƽườǃƼǦǁǊƇǃǦǁƐǦǉƽƾǦǉƽểǦƸủƶǦǀẻǦǉƽƾệǃǦǁươǃƼ.",
    ["善人食尽，才会有恶人躺在这里……"] = "ƦẻǦǉƽƾệǃǦƷịǦăǃǦǈạƸƽǦǇồƾ,ǦǂớƾǦđếǃǦǁượǉǦǀẻǦƑƸǦǃằǂǦǍǊốǃƼǦđƁǓ...",
    ["人有分别心，有贪婪性。诸国众生人人相食，如何能均？"] = "ƞǄǃǦǃƼườƾǦƸƚǦǁƛǃƼǦǅƽƁǃǦƷƾệǉ,ǦƸƚǦǉƓǃƽǦǉƽƶǂǦǁƶǂ.ǦƞƽƕǃƼǦǈƾǃƽǦƸƑƸǦǃướƸǦǉƐǃǦǈƑǉǦǁẫǃǦǃƽƶǊ,ǦǁƐǂǦǈƶǄǦƸƚǦǉƽểǦǆǊƁǃǦƷƔǃƽ?",
    ["唯有墨者。"] = "ǝǊǓǦƸƽỉǦƸƚǦƨặƸǦƼƾả.",
    ["墨门正路，不该是一群痴儿盯着高天之上，做清白聪慧事，而在天之下，在污秽和愚鲁间。"] = "ƞƽƓǃƽǦđạǄǦƨặƸǦǂƇǃǦǀƽƇǃƼǦǃƙǃǦǁƐǦǂộǉǦǁũǦđầǃǦđộǃǦǃƽƔǃǦƸƽăǂǦƸƽằǂǦǁƙǃǦǉǇờƾǦƸƶǄǦǁƐǂǦǃƽữǃƼǦǋƾệƸǦǉƽƶǃƽǦƸƶǄǦǉǇƓǦǉǊệ,ǦǂƐǦǅƽảƾǦởǦǤướƾǦƼầǂǦǉǇờƾ,ǦƼƾữƶǦƸƽốǃǦƇǦǊếǦǋƐǦǃƼǊǦǂǊộƾ.",
    ["以乌金荡涤天下，以墨经规矩万古。"] = "ƧấǓǦƆǦƦƾǂǦƼộǉǦǇửƶǦǉƽƾƙǃǦƽạ,ǦǁấǓǦƨặƸǦǀƾǃƽǦǁậǅǦǆǊǓǦƸủǦǋạǃǦđờƾ.",
    ["使苍天之下，无人不同。厚土之上，众鸟一声。"] = "ƦƽƾếǃǦǤướƾǦǉǇờƾǦǍƶǃƽ,ǦǀƽƇǃƼǦƶƾǦǀƽƑƸǦƷƾệǉ.ǦǥǇƙǃǦđấǉǦǤƐǓ,ǦǋạǃǦđƾểǊǦđồǃƼǦǉƽƶǃƽ.",
    ["到那时，才能谈用者节之，兼而爱之，自然非攻。"] = "ĐếǃǦǁƕƸǦđƚ,ǦǂớƾǦƸƚǦǉƽểǦƷƐǃǦǉớƾǦƸƽǊǓệǃǦǃƼườƾǦǤƖǃƼǦƷƾếǉǦǉƾếǉǦƸƽế,ǦǀƾƙǂǦƑƾǦǁẫǃǦǃƽƶǊ,ǦǉựǦǀƽắƸǦǈẽǦǅƽƾǦƸƇǃƼ.",
    ["……谁是墨者。"] = "...ǦƜƾǦǁƐǦƨặƸǦƼƾả.",
    ["我们。"] = "ƞƽƕǃƼǦǉƶ.",
    ["谁是众生。"] = "ƣọ.",
    ["咳咳……阴阳二气……伏火秘诀，竟是如此。"] = "ƦƽụǦǀƽụ...ǦǃƽịǦǀƽƓǦƁǂǦǤươǃƼ...ǦƷƓǦǆǊǓếǉǦǅƽụƸǦƽỏƶ,ǦƽƚƶǦǇƶǦǁƐǦǃƽưǦǋậǓ.",
    ["呼……哈……"] = "ƫƽƖ...ǦƽƐ...",
    ["孩子，秀才公说了，咱村里要是能把石炭炼出来，以后就再也不用四处奔波讨生活了……你看，你这是不是……"] = "ƞǄǃǦƐ,ǦǥƕǦǥƐƾǦƸƇǃƼǦǃƚƾǦǇồƾ,ǦǃếǊǦǁƐǃƼǦǉƶǦǁǊǓệǃǦđượƸǦǉƽạƸƽǦǉƽƶǃ,ǦǈƶǊǦǃƐǓǦǀƽƇǃƼǦƸƛǃǦǅƽảƾǦƷƇǃǦƷƶǦǀƽắǅǦǃơƾǦǀƾếǂǦǈốǃƼǦǃữƶ...ǦƸǄǃǦǍƺǂ,ǦƸƚǦǅƽảƾǦƸǄǃǦǃƙǃ...",
    ["小磊要回家吗？你不求学了吗？"] = "ǥƾểǊǦƧỗƾǦǂǊốǃǦǋềǦǃƽƐǦǈƶǄ?ǦƞǄǃǦǀƽƇǃƼǦƸầǊǦƽọƸǦǃữƶǦƐ?",
    ["我......我和妈妈逃荒出来遇到强盗失散，是路过的墨家弟子救了我。我醒来后入了墨门才知道，原来世间万物背后竟都有道理……"] = "ƞǄǃ...ǦƸǄǃǦǋƐǦǂẹǦƸƽạǓǦǃạǃǦƼặǅǦǅƽảƾǦƸườǃƼǦđạǄǦǇồƾǦǁạƸǦǂấǉǦǃƽƶǊ,ǦǂƶǓǦǃƽờǦđệǦǉửǦƨặƸǦƼƾƶǦđƾǦǃƼƶǃƼǦǆǊƶǦƸứǊǦǂạǃƼ.ǦƮƶǊǦǀƽƾǦǉỉǃƽǦǁạƾǦƼƾƶǦǃƽậǅǦƨặƸǦǂƇǃǦƸǄǃǦǂớƾǦƷƾếǉ,ǦƽƚƶǦǇƶǦǋạǃǦǋậǉǦǉƽếǦƼƾƶǃǦđềǊǦƸƚǦđạǄǦǁƈǦƸủƶǦǃƚ...",
    ["只是我一想到我坐在这干净的屋里读书，妈妈妹妹却可能在另一个地方受苦，就如坐针毡。"] = "ƞƽỉǦǁƐǦƸứǦǃƼƽĩǦđếǃǦǋƾệƸǦǂƔǃƽǦǃƼồƾǦǉǇǄǃƼǦƸăǃǦǅƽƛǃƼǦǈạƸƽǦǈẽǦǃƐǓǦđọƸǦǈƑƸƽ,ǦƸƛǃǦǂẹǦǋƐǦǂǊộƾǦǂǊộƾǦƸƚǦǁẽǦđƶǃƼǦƸƽịǊǦǀƽổǦởǦǃơƾǦǃƐǄǦđƚ,ǦƸǄǃǦǁạƾǦǃƽưǦǃƼồƾǦǉǇƙǃǦƷƐǃǦƸƽƇǃƼ.",
    ["这次我要先回家，把煅炭炉建好。等妈妈妹妹靠自己便能过得很好的时候……到那时，我、我再回到墨门。"] = "ƧầǃǦǃƐǓǦƸǄǃǦǅƽảƾǦǋềǦǃƽƐǦǉǇướƸ,ǦǍƁǓǦǍǄǃƼǦǁƛǦǁǊǓệǃǦǉƽƶǃ.ǦĐợƾǦđếǃǦǀƽƾǦǂẹǦǋƐǦǂǊộƾǦǂǊộƾǦƸƚǦǉƽểǦǉựǦǈốǃƼǦǉốǉ...ǦǁƕƸǦđƚ,ǦƸǄǃ...ǦƸǄǃǦǈẽǦǆǊƶǓǦǁạƾǦƨặƸǦǂƇǃ.",
    ["哥哥，我若是想你呢——"] = "ƞƶǦƸƶ,ǦǃếǊǦǂǊộƾǦǃƽớǦƽǊǓǃƽǦǉƽƔǦǈƶǄ——",
    ["小桃宝想我了，随时可以来看我. 我问过长老了，墨山道准许探亲的。"] = "ǥƾểǊǦĐƐǄǦƝảǄǦǃƽớǦƽǊǓǃƽǦǉƽƔǦƸƚǦǉƽểǦđếǃǦǉƽăǂǦƷấǉǦƸứǦǁƕƸǦǃƐǄ.ǦƣǊǓǃƽǦƽỏƾǦǉǇưởǃƼǦǁƃǄǦǇồƾ,ǦƨặƸǦƮơǃǦđạǄǦƸƽǄǦǅƽƗǅǦǆǊǓếǃǦǉƽǊộƸǦǉƽăǂǦǃǄǂ.",
    ["小桃宝探亲时可要当心，我看许多长老都看中了你，想将你收入门下呢！"] = "ǥƾểǊǦĐƐǄǦƝảǄǦǀƽƾǦđƾǦǉƽăǂǦǅƽảƾǦƸẩǃǦǉƽậǃǦđấǓ,ǦǉƶǦǉƽấǓǦǃƽƾềǊǦǉǇưởǃƼǦǁƃǄǦƸƽấǂǦƸǄǃǦǇồƾ,ǦǂǊốǃǦǉƽǊǦƸǄǃǦǁƐǂǦǂƇǃǦƽạǦđƚ!",
    ["……承你们这么大情，我这一回泽州去，不知何时才能报答……"] = "...ǦĐắƸǦǉộƾǦǃƽậǃǦƁǃǦǉƔǃƽǦǁớǃǦǉƽếǦǃƐǓ,ǦǁầǃǦǃƐǓǦǉƶǦǋềǦǥǇạƸƽǦƞƽƁǊ,ǦǀƽƇǃƼǦƷƾếǉǦǀƽƾǦǃƐǄǦǂớƾǦƷƑǄǦđƑǅǦđượƸ...",
    ["你们放心，这个会烧石炭的小仙人我们一定给当宝贝疙瘩供起来！"] = "ƞƑƸǦǋịǦƸứǦǓƙǃǦǉƁǂ,ǦǋịǦǉƾểǊǦǉƾƙǃǦǃƽƁǃǦƷƾếǉǦđốǉǦǉƽạƸƽǦǉƽƶǃǦǃƐǓǦƸƽƕǃƼǦǉƇƾǦǃƽấǉǦđịǃƽǦǈẽǦƸǊǃƼǦǅƽụǃƼǦǃƽưǦƷƑǊǦǋậǉ!",
    ["不必不必，我不是仙人！"] = "ƦƽƇǃƼǦƸầǃǦǀƽƇǃƼǦƸầǃ,ǦǉƇƾǦǀƽƇǃƼǦǅƽảƾǦǉƾƙǃǦǃƽƁǃ!",
    ["我去泽州除了帮大家炼炭，也是想研究石炭种类，看能不能找到找到能让箭飞的更远的……"] = "ǥƇƾǦǋềǦǥǇạƸƽǦƞƽƁǊǦǃƼǄƐƾǦƼƾƕǅǦǂọƾǦǃƼườƾǦǁǊǓệǃǦǉƽƶǃ,ǦƸƛǃǦǂǊốǃǦǃƼƽƾƙǃǦƸứǊǦƸƑƸǦǁǄạƾǦǉƽạƸƽǦǉƽƶǃ,ǦǍƺǂǦƸƚǦǉƽểǦǉƔǂǦđượƸǦǁǄạƾǦǃƐǄǦǀƽƾếǃǦǉƙǃǦƷắǃǦǍƶǦƽơǃǦǀƽƇǃƼ...",
    ["不是仙人。是恩人。"] = "ƦƽƇǃƼǦǅƽảƾǦǉƾƙǃǦǃƽƁǃ.ǦƧƐǦƁǃǦǃƽƁǃ.",
    ["小姑娘，你怎么打算，留在这儿还是回乡？"] = "ƞƇǦǃươǃƼ,ǦƸƇǦđịǃƽǦǉƽếǦǃƐǄ,ǦởǦǁạƾǦđƁǓǦƽƶǓǦǋềǦǆǊƙ?",
    ["你别嫌我倚老卖老好说嘴，这人啊，年轻时候走四方，临到头还是觉着家里好。"] = "ƞƇǦđừǃƼǦǉǇƑƸƽǦǁƃǄǦƼƾƐǦǃƐǓǦǉƽƓƸƽǦǤạǓǦđờƾ,ǦƸǄǃǦǃƼườƾǦǉƶǦấǓǦǂƐ,ǦǁƕƸǦǉǇẻǦđƾǦǀƽắǅǦƷốǃǦǅƽươǃƼ,ǦđếǃǦƸǊốƾǦƸƖǃƼǦǋẫǃǦǉƽấǓǦǃƽƐǦǁƐǦǉốǉǦǃƽấǉ.",
    ["……还不能回去。我还要去江湖上找人。"] = "...ǦƱẫǃǦƸƽưƶǦǉƽểǦǋềǦđượƸ.ǦǥƶǦƸƛǃǦǅƽảƾǦđƾǦǉƔǂǦǃƼườƾǦǉǇƙǃǦƼƾƶǃƼǦƽồ.",
    ["跑江湖啊……也好、也好……"] = "ƣƐǃƽǦǉẩǊǦƼƾƶǃƼǦƽồǦƐ...ǦƸũǃƼǦǉốǉ,ǦƸũǃƼǦǉốǉ...",
    ["以后要是打相州过，来找我们，我管你饭. "] = "ƮƶǊǦǃƐǓǦǃếǊǦƸƚǦđƾǦǃƼƶǃƼǦǆǊƶǦǥươǃƼǦƞƽƁǊ,ǦƸứǦđếǃǦǉƔǂǦƷọǃǦǉƶ,ǦǉƶǦƷƶǄǦƸơǂ.",
    ["好好好，以后我就去相州打听——有没有见过一个倔老头。"] = "ĐượƸǦđượƸ,ǦǈƶǊǦǃƐǓǦǉƶǦǈẽǦđếǃǦǥươǃƼǦƞƽƁǊǦǃƼƽƺǦǃƼƚǃƼǦǍƺǂ——ǦƸƚǦƶƾǦǉừǃƼǦǉƽấǓǦǂộǉǦǁƃǄǦƼƾƐǦƼƐǃǦǤởǦǀƽƇǃƼ.",
    ["嘿，你这小孩。下次来，恐怕我就不只是个老秀才咯。"] = "ƣắƸ,ǦƸƑƾǦƸǄǃǦƷƗǦǃƐǓ.ǦƧầǃǦǉớƾǦđếǃ,ǦƺǦǁƐǦǉƶǦǀƽƇǃƼǦƸƽỉǦƸƛǃǦǁƐǦǂộǉǦǁƃǄǦǉƕǦǉƐƾǦđƁǊ.",
    ["哦？秀才公有打算？"] = "Ồ?ǦǥƕǦǥƐƾǦƸƇǃƼǦƸƚǦǤựǦǉƓǃƽǦƼƔǦǈƶǄ?",
    ["这不是芸香家的小磊找着了嘛。那伏火的炉子啊，窑啊……小磊捯饬得好着呐。"] = "ƞƽẳǃƼǦǅƽảƾǦǁƐǦǉƔǂǦđượƸǦǥƾểǊǦƧỗƾǦǃƽƐǦƱƁǃǦƣươǃƼǦǇồƾǦǈƶǄ.ǦƞƑƾǦǁƛǦǅƽụƸǦƽỏƶǦđƚ,ǦǇồƾǦƸảǦǁƛǦǃǊǃƼǦǃữƶ...ǦǥƾểǊǦƧỗƾǦǉƽǊǦǍếǅǦổǃǦǉƽỏƶǦǁắǂ.",
    ["我想着等这次回去，叫小磊带着十里八乡的人把这炉子一修，嘿嘿……"] = "ǥƶǦđƶǃƼǦǉƓǃƽǦǁầǃǦǃƐǓǦǋề,ǦƷảǄǦǥƾểǊǦƧỗƾǦǤẫǃǦǤƁǃǦǁƐǃƼǦǂườƾǦǤặǂǦǉƑǂǦǍƃǦǈửƶǦǁạƾǦƸƑƾǦǁƛǦǃƐǓ,ǦƽắƸǦƽắƸ...",
    ["这炼石炭的事儿要是能成，我怕是能当个里正！"] = "ƞƽǊǓệǃǦǁǊǓệǃǦǉƽạƸƽǦǉƽƶǃǦǃƐǓǦǂƐǦǉƽƐǃƽ,ǦƺǦǁƐǦǉƶǦƸƚǦǉƽểǦǁƐǂǦđếǃǦƸƽứƸǦƧƈǦƸƽƓǃƽ!",
    ["好了，话都说完了吧。说完话，收拾好东西，我们就该告辞了。"] = "ĐượƸǦǇồƾ,ǦǃƚƾǦǍǄǃƼǦƸảǦǇồƾǦƸƽứ.ǦƩƚƾǦǍǄǃƼǦǇồƾǦǉƽƔǦǉƽǊǦǤọǃǦđồǦđạƸ,ǦƸƽƕǃƼǦǉƶǦǃƙǃǦƸƑǄǦǉừǦǉƽƇƾ.",
    ["这么说，你们都愿回乡去？"] = "ƩƚƾǦǋậǓ,ǦƸƑƸǦǋịǦđềǊǦǂǊốǃǦǋềǦǆǊƙǦǈƶǄ?",
    ["是啊。我们泽州山里的石炭都不用挖，有的地方弯腰就能从地上捡，"] = "ƫƽảƾǦđƚ.ǦǥƽạƸƽǦǉƽƶǃǦǉǇǄǃƼǦǃƕƾǦǥǇạƸƽǦƞƽƁǊǦƸƽƕǃƼǦǉƇƾǦƸƽẳǃƼǦƸầǃǦđƐǄ,ǦƸƚǦǃơƾǦƸƽỉǦƸầǃǦƸƕƾǦǃƼườƾǦǁƐǦǃƽặǉǦđượƸǦǉǇƙǃǦđấǉ,",
    ["之前那东西有毒气不值钱，如今这几个小仙人研究出了去毒的法子，这不就有用处了嘛！"] = "ǥǇướƸǦǀƾƶǦǉƽứǦđƚǦƸƚǦđộƸǦǀƽƓǦƸƽẳǃƼǦđƑǃƼǦǉƾềǃ,ǦǃƶǓǦǂấǓǦǋịǦǉƾểǊǦǉƾƙǃǦǃƽƁǃǦǃƐǓǦǃƼƽƾƙǃǦƸứǊǦǇƶǦƸƑƸƽǦǀƽửǦđộƸ,ǦƸƽẳǃƼǦǅƽảƾǦǁƐǦƸƚǦǤụǃƼǦǋƅǦđạǄǦǇồƾǦǈƶǄ!",
    ["既然如此，我给婶子和秀才公指条销路。如今开封人多地少，这地一少，砍柴就是个难事。开封城里，舍得花钱的富户颇多……"] = "ĐƃǦǃƽưǦǋậǓ,ǦǉƶǦƸƽỉǦƸƽǄǦǉƽẩǂǦǉửǦǋƐǦǥƕǦǥƐƾǦƸƇǃƼǦǂộǉǦƸǄǃǦđườǃƼǦǉƾƙǊǦǉƽụ.ǦƩƶǓǦƦƽƶƾǦƫƽǄǃƼǦǃƼườƾǦđƇǃƼǦđấǉǦƽẹǅ,ǦƸủƾǦǁửƶǦǁƐǦƸƽǊǓệǃǦǃƶǃǦƼƾảƾ.ǦǥǇǄǃƼǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼ,ǦǅƽƕǦƽộǦƸƽịǊǦƸƽƾǦǉƾềǃǦǇấǉǦǃƽƾềǊ...",
    ["诶？诶！是这个理！我们鹤壁离开封近得很！这不冒烟的石炭可是稀奇玩意儿，要我说，给它起个风流的名儿，八百文一斤……不，一两！卖给开封的大官儿财主！诶呀，嘿嘿诶呀……我这本事，当个里正是不是大材小用了……"] = "ƣả?ǦÁƾǦƸƽƐ!ǦĐƕǃƼǦǁƐǦǁƈǦǃƐǓǦǇồƾ!ǦƣạƸǦƝƓƸƽǦƷọǃǦǉƇƾǦƸƑƸƽǦƦƽƶƾǦƫƽǄǃƼǦƼầǃǦǁắǂ!ǦƧǄạƾǦǉƽạƸƽǦǉƽƶǃǦǀƽƇǃƼǦǀƽƚƾǦǃƐǓǦđƕǃƼǦǁƐǦǂƚǃǦǁạ,ǦǉƽƺǄǦǉƇƾǦǉƽấǓ,ǦƸứǦđặǉǦƸƽǄǦǃƚǦƸƑƾǦǉƙǃǦǉƽậǉǦǅƽǄǃƼǦǃƽƃ,ǦǉƑǂǦǉǇăǂǦǋăǃǦǂộǉǦƸƁǃ...ǦǀƽƇǃƼ,ǦǂộǉǦǁạǃƼ!ǦƝƑǃǦƸƽǄǦǁũǦǆǊƶǃǦǉǄǦǉƐƾǦƸƽủǦởǦƦƽƶƾǦƫƽǄǃƼ!ǦÁƾǦƸƽƐ,ǦƽắƸǦƽắƸ...ǦƸƑƾǦƷảǃǦǁĩǃƽǦǃƐǓǦƸủƶǦǉƇƾǦǂƐǦǁƐǂǦƧƈǦƸƽƓǃƽǦǉƽƔǦƸƚǦǅƽảƾǦǁƐǦđạƾǦǉƐƾǦǉƾểǊǦǤụǃƼǦǀƽƇǃƼǦǃƽỉ...",
    ["诶诶小伙子小伙子，你帮我们也想想出路呗！老话说百里不贩樵，我们泽州离开封几百里，一路上都是打仗的兵匪，想过去只能往太行山上钻。山路不好走，这咋卖啊……"] = "ƩƐǓǦǃƐǓǦǉƾểǊǦǉử,ǦƸậǊǦƼƾƕǅǦƷọǃǦǉƇƾǦǃƼƽĩǦƸƑƸƽǦǋớƾ!ǦƩƼạǃǦǃƼữǦƸƚǦƸƁǊǦ\"ǉǇăǂǦǤặǂǦǀƽƇǃƼǦƷǊƇǃǦƸủƾ\",ǦǥǇạƸƽǦƞƽƁǊǦƸƽƕǃƼǦǉƇƾǦƸƑƸƽǦƦƽƶƾǦƫƽǄǃƼǦǂấǓǦǉǇăǂǦǤặǂ,ǦǉǇƙǃǦđườǃƼǦǉǄƐǃǦƷƾǃƽǦǉặƸǦǁǄạǃǦǁạƸ,ǦǂǊốǃǦǆǊƶǦƸƽỉǦƸƚǦǃướƸǦƸƽǊƾǦǋƐǄǦǃƕƾǦǥƽƑƾǦƣƐǃƽ.ǦĐườǃƼǦǃƕƾǦǀƽƚǦđƾ,ǦƷƑǃǦǉƽếǦǃƐǄǦđượƸǦđƁǓ...",
    ["以后就好走了。"] = "ƮƶǊǦǃƐǓǦǈẽǦǤễǦđƾǦǉƽƇƾ.",
    ["以后？"] = "ƮƶǊǦǃƐǓ?",
    ["嗯。仗打完了。以后能从天井关走了。"] = "Ừǂ.ǦƢƾặƸǦƼƾƃǦǉƶǃǦǇồƾ.ǦƮƶǊǦǃƐǓǦƸƚǦǉƽểǦđƾǦǉừǦǥƽƾƙǃǦǥỉǃƽǦƬǊƶǃ.",
    ["那，那俺也八百文一两卖给城里人？俺们路远，怕是卖不过那老秀才……"] = "ƱậǓ,ǦǋậǓǦǉƇƾǦƸũǃƼǦƷƑǃǦǉƑǂǦǉǇăǂǦǋăǃǦǂộǉǦǁạǃƼǦƸƽǄǦǃƼườƾǦǉǇǄǃƼǦǉƽƐǃƽ?ǦĐườǃƼǦǍƑǦǍƶǦǍƇƾ,ǦƺǦǁƐǦƷƑǃǦǀƽƇǃƼǦǁạƾǦǁƃǄǦǉƕǦǉƐƾǦǀƾƶ...",
    ["婶子多虑。如今稀罕的是伏火法，并非石炭本身。初时伏火之术难学，炼炭物稀价高，自然可以按秀才公的法子卖. 等伏火术传开去，炼炭便要走量大多销的路子了。"] = "ǥƽẩǂǦǉửǦđƶǦǁựǦǇồƾ.ǦƩƶǓǦǉƽứǦǆǊƈǦƼƾƑǦǁƐǦƫƽụƸǦƽỏƶǦǅƽƑǅ,ǦƸƽứǦǀƽƇǃƼǦǅƽảƾǦƷảǃǦǉƽƁǃǦǉƽạƸƽǦǉƽƶǃ.ǦƝƶǃǦđầǊǦǉƽǊậǉǦǅƽụƸǦƽỏƶǦǀƽƚǦƽọƸ,ǦǉƽƶǃǦǁǊǓệǃǦǇƶǦƽƾếǂǦǃƙǃǦƼƾƑǦƸƶǄ,ǦǉựǦǃƽƾƙǃǦƸƚǦǉƽểǦƷƑǃǦǉƽƺǄǦƸƑƸƽǦƸủƶǦǥƕǦǥƐƾǦƸƇǃƼ.ǦƞƽờǦǉƽǊậǉǦǅƽụƸǦƽỏƶǦǉǇǊǓềǃǦǇộǃƼǦǇƶ,ǦǁǊǓệǃǦǉƽƶǃǦǅƽảƾǦđƾǦǉƽƺǄǦƽướǃƼǦǈốǦǁượǃƼǦǁớǃǦƼƾƑǦǇẻǦǇồƾ.",
    ["按你所说，泽州石炭俯拾皆是，那这炼炭除了花些功夫，几乎是无本生意……怎会没得挣。"] = "ǥƽƺǄǦǁờƾǦƷƐǦǃƚƾ,ǦǉƽạƸƽǦǉƽƶǃǦǥǇạƸƽǦƞƽƁǊǦǃƽặǉǦđƁǊǦƸũǃƼǦƸƚ,ǦǋậǓǦǁǊǓệǃǦǉƽƶǃǦǃƐǓǦǃƼǄƐƾǦƷỏǦƸƽƕǉǦƸƇǃƼǦǈứƸǦǉƽƔǦƽầǊǦǃƽưǦǁƐǦǋốǃǦǀƽƇǃƼǦǁờƾǦǃƽƾềǊ...ǦǈƶǄǦǁạƾǦǀƽƇǃƼǦƸƚǦǉƾềǃǦǁƃƾ.",
    ["那、那俺们不是要发财了？老天爷啊，这是真点石成金啊！"] = "ƱậǓ,ǦǋậǓǦƸƽẳǃƼǦǅƽảƾǦƸƽƕǃƼǦǉƇƾǦǈắǅǦǅƽƑǉǦǉƐƾǦǇồƾǦǈƶǄ?ǦǥǇờƾǦđấǉǦơƾ,ǦđƕǃƼǦǁƐǦđƾểǂǦǉƽạƸƽǦǉƽƐǃƽǦǀƾǂǦǂƐ!",
    ["又不是你不舍得走的时候了？"] = "ƞƽẳǃƼǦǅƽảƾǦǁƕƸǦǃƃǓǦƷƐǦƸƛǃǦǁưǊǦǁǊǓếǃǦǀƽƇǃƼǦǂǊốǃǦđƾǦǈƶǄ?",
    ["哎呦呦，一听这银子响，只想快些回家去，将炉子搭起来哩！"] = "ÁƾǦƸƽƐǦƸƽƐ,ǦǋừƶǦǃƼƽƺǦǉƾếǃƼǦƷạƸǦǀƙǊǦǁƐǦƸƽỉǦǂǊốǃǦǂƶǊǦǂƶǊǦǋềǦǃƽƐǦǤựǃƼǦƸƑƾǦǁƛǦǁƙǃǦǃƼƶǓǦǉƽƇƾ!",
    ["马上要出山了，燕，就到这里……"] = "ƮắǅǦǇƶǦǀƽỏƾǦǃƕƾǦǇồƾ,Ǧƴếǃ,ǦđếǃǦđƁǓǦǉƽƇƾ...",
    ["嗯。不送。"] = "Ừǂ.ǦƦƽƇǃƼǦǉƾễǃ.",
    ["……虽然我是这个意思但你也不必这么干脆吧！好歹给点面子犹豫一下？"] = "...ǦǝẫǊǦǉƶǦƸƚǦƈǦđƚǦǃƽưǃƼǦǃƼươƾǦƸũǃƼǦǀƽƇǃƼǦƸầǃǦǤứǉǦǀƽǄƑǉǦǋậǓǦƸƽứ!ǦǝƖǦƼƔǦƸũǃƼǦǃểǦǂặǉǦǃƽƶǊǦǂƐǦǤǄǦǤựǦǂộǉǦƸƽƕǉǦǀƽƇǃƼǦđượƸǦǈƶǄ?",
    ["长老，教的。"] = "ǥǇưởǃƼǦǁƃǄ,ǦǤạǓ.",
    ["长老们教你这个？"] = "ƞƑƸǦǋịǦǉǇưởǃƼǦǁƃǄǦǤạǓǦǃƼươƾǦƸƑƾǦǃƐǓ?",
    ["长老，教教我，我学会，能当巨子。"] = "ǥǇưởǃƼǦǁƃǄǦǤạǓǦǉƶ,ǦǉƶǦƽọƸǦđượƸ,ǦƸƚǦǉƽểǦǁƐǂǦƞựǦǥử.",
    ["哈哈，你学得好快！"] = "ƣƶǦƽƶ,ǦǃƼươƾǦƽọƸǦǃƽƶǃƽǦǉƽậǉǦđấǓ!",
    ["最近学，离别。"] = "ƢầǃǦđƁǓǦđƶǃƼǦƽọƸ,ǦƸƑƸƽǦǁǓǦƷƾệǉ.",
    ["巨子，我……"] = "ƞựǦǥử,Ǧǉƶ...",
    ["巨子，我们不是那忘恩负义的人。"] = "ƞựǦǥử,ǦƸƽƕǃƼǦǉƶǦǀƽƇǃƼǦǅƽảƾǦƽạǃƼǦǃƼườƾǦǋǄǃƼǦơǃǦǅƽụǦǃƼƽĩƶ.",
    ["我和春花挨家挨户找了这次进山的人，叫他们发誓：这次进山，谁都没找着桃源。"] = "ǥƶǦǋƐǦƳǊƁǃǦƣǄƶǦđƃǦđếǃǦǉừǃƼǦǃƽƐǦǉƔǂǦǃƽữǃƼǦǃƼườƾǦǋƐǄǦǃƕƾǦǁầǃǦǃƐǓ,ǦƷắǉǦƽọǦǉƽềǦǇằǃƼ:ǦƞƽǊǓếǃǦǋƐǄǦǃƕƾǦǃƐǓ,ǦǀƽƇǃƼǦƶƾǦǉƔǂǦǉƽấǓǦĐƐǄǦƩƼǊǓƙǃǦƸả.",
    ["不必。"] = "ƦƽƇǃƼǦƸầǃ.",
    ["我们真的——"] = "ƞƽƕǃƼǦǉƶǦǉƽựƸǦǈự——",
    ["长老。"] = "ǥǇưởǃƼǦǁƃǄ.",
    ["墨门承二位的情，只是如今闹了这么一回，封山一事已是行不通了。"] = "ƨặƸǦǂƇǃǦƼƽƾǦǃƽậǃǦǉấǂǦǁƛǃƼǦƸủƶǦƽƶƾǦǋị,ǦƸƽỉǦǁƐǦǃƶǓǦđƃǦǍảǓǦǇƶǦƸƽǊǓệǃǦǉƽếǦǃƐǓ,ǦǋƾệƸǦǅƽǄǃƼǦǈơǃǦđƃǦǀƽƇǃƼǦƸƛǃǦǀƽảǦǉƽƾǦǃữƶ.",
    ["如何开山，虽还需从长计议，但墨门已有了些想法。所以二位大可不必记挂。"] = "ƞƽǊǓệǃǦǀƽƶƾǦǈơǃǦǇƶǦǈƶǄǦǤẫǊǦƸƛǃǦƸầǃǦƷƐǃǦƷạƸǦǀỹǦǁưỡǃƼ,ǦǃƽưǃƼǦƨặƸǦǂƇǃǦđƃǦƸƚǦǋƐƾǦƈǦǉưởǃƼǦǇồƾ.ǦǥƽếǦǃƙǃǦƽƶƾǦǋịǦǀƽƇǃƼǦƸầǃǦƷậǃǦǁƛǃƼ.",
    ["外头不还在打仗吗？墨门这就要开山？"] = "ƝƙǃǦǃƼǄƐƾǦƸƽẳǃƼǦǅƽảƾǦǋẫǃǦđƶǃƼǦđƑǃƽǦǃƽƶǊǦǈƶǄ?ǦƨặƸǦǂƇǃǦđịǃƽǦǀƽƶƾǦǈơǃǦǁƕƸǦǃƐǓ?",
    ["是啊。先前墨门封山，就是怕为征战诸国所利用。"] = "ƫƽảƾǦǋậǓ.ǦǥǇướƸǦǀƾƶǦƨặƸǦǂƇǃǦǅƽǄǃƼǦǈơǃǦǁƐǦǋƔǦǈợǦƷịǦƸƑƸǦǃướƸǦđƶǃƼǦƼƾƶǄǦƸƽƾếǃǦǁợƾǦǤụǃƼ.",
    ["如今藏是藏不住，还是要早日出去寻些可靠的助力……"] = "ƩƶǓǦǂǊốǃǦƼƾấǊǦƸũǃƼǦǀƽƇǃƼǦƼƾấǊǦđượƸ,ǦǋẫǃǦǃƙǃǦǈớǂǦǇƶǦǃƼǄƐƾǦǉƔǂǦǀƾếǂǦǉǇợǦǁựƸǦđƑǃƼǦǉƾǃǦƸậǓ...",
    ["只是可信之人，实在不多……嗨，我说这个干什么。"] = "ƞƽỉǦǁƐǦǃƼườƾǦǀƽảǦǉƓǃǦǉƽựƸǦǈựǦǀƽƇǃƼǦǃƽƾềǊ...ǦƣƶƾǏ,ǦǉƶǦǃƚƾǦƸƽǊǓệǃǦǃƐǓǦǁƐǂǦƼƔǦǀƽƇǃƼǦƷƾếǉ.",
    ["我听闻墨门曾有弟子混入了司天监？"] = "ǥƶǦǃƼƽƺǦǃƚƾǦđệǦǉửǦƨặƸǦǂƇǃǦǉừǃƼǦƸƚǦǃƼườƾǦǉǇƐǦǉǇộǃǦǋƐǄǦǥưǦǥƽƾƙǃǦƢƾƑǂ?",
    ["诶，我那小徒弟嫌门中星图记载不全，听孤云来的王师侄说司天监里有全乎的，不吭一声俩人偷偷就去了，"] = "ÁƾǦƸƽƐ,ǦǉƙǃǦǉƾểǊǦđồǦđệǦƸủƶǦǉƶǦƸƽƙǦǉƾǃƽǦđồǦǉǇǄǃƼǦǂƇǃǦƼƽƾǦƸƽƗǅǦǀƽƇǃƼǦđủ,ǦǃƼƽƺǦƱươǃƼǦǈưǦđƾệǉǦǉừǦƞƇǦƱƁǃǦđếǃǦǃƚƾǦǉǇǄǃƼǦǥưǦǥƽƾƙǃǦƢƾƑǂǦƸƚǦƷảǃǦđầǓǦđủ,ǦǉƽếǦǁƐǦƽƶƾǦđứƶǦƾǂǦƽơƾǦǁặǃƼǦǉƾếǃƼǦǁƗǃǦǁƕǉǦđƾǦǁǊƇǃ,",
    ["幸好官府没发现他俩另有身份……哎！"] = "ƞũǃƼǦǂƶǓǦǆǊƶǃǦǅƽủǦǀƽƇǃƼǦǅƽƑǉǦƽƾệǃǦǇƶǦǉƽƁǃǦǅƽậǃǦǀƽƑƸǦƸủƶǦƸƽƕǃƼ...ǦƆƾ!",
    ["真是胆大心细！墨门有此智勇双全的麒麟儿，何愁不兴啊。"] = "ĐƕǃƼǦǁƐǦđảǂǦđạƾǦǉƁǂǦǉế!ǦƨặƸǦǂƇǃǦƸƚǦđượƸǦǀỳǦǁƁǃǦǃƽƾǦǉǇƓǦǤũǃƼǦǈǄǃƼǦǉǄƐǃǦǃƽưǦǉƽế,ǦǁǄǦƼƔǦǀƽƇǃƼǦƽưǃƼǦǉƽịǃƽ.",
    ["嗐，小孩子懂什么。"] = "ƣạƾ,ǦǁũǦǉǇẻǦƸǄǃǦǉƽƔǦƷƾếǉǦƸƑƾǦƼƔ.",
    ["长老谬矣。听闻墨子曾止楚攻宋，以墨者之力左右朝堂决议。"] = "ǥǇưởǃƼǦǁƃǄǦǈƶƾǦǇồƾ.ǦƩƼƽƺǦǤƶǃƽǦƨặƸǦǥửǦǃăǂǦǍưƶǦǉừǃƼǦǃƼăǃǦƮởǦƸƇǃƼǦǥốǃƼ,ǦǁấǓǦǈứƸǦƨặƸǦƼƾảǦđểǦǍǄƶǓǦƸƽǊǓểǃǦǆǊǓếǉǦǃƼƽịǦǉǇƾềǊǦđƔǃƽ.",
    ["每每思及此处，不禁心生向往。我看长老这弟子就颇有古墨之风。"] = "ƨỗƾǦǀƽƾǦǃƼƽĩǦđếǃǦđƁǓ,ǦǉƶǦǀƽƇǃƼǦǀƽỏƾǦǈƾǃƽǦǁƛǃƼǦƽướǃƼǦǋọǃƼ.ǦǥƶǦǉƽấǓǦǋịǦđệǦǉửǦǃƐǓǦƸủƶǦǉǇưởǃƼǦǁƃǄǦǇấǉǦƸƚǦǅƽǄǃƼǦǉƽƑƾǦƸủƶǦƸổǦƨặƸ.",
    ["说到此处，我倒有个异想天开的想法……唉，说出来贻笑大方了。算了算了。"] = "ƩƽắƸǦđếǃǦđƁǓ,ǦǉƶǦǁạƾǦƸƚǦǂộǉǦƈǦǉưởǃƼǦǀƽƇǃƼǦǉưởǃƼ...ǦƣƶƾǏ,ǦǃƚƾǦǇƶǦƺǦǁƐǦǀƽƾếǃǦǂọƾǦǃƼườƾǦƸƽƙǦƸườƾ.ǦǥƽƇƾǦƷỏǦđƾ.",
    ["贵客但言无妨。只是随意聊聊，哪就这么拘束了。"] = "ƬǊƈǦǀƽƑƸƽǦƸứǦǃƚƾǦđừǃƼǦǃƼạƾ.ǦƞƽỉǦǁƐǦǉƖǓǦƈǦǉǇƛǦƸƽǊǓệǃ,ǦǁƐǂǦƼƔǦǂƐǦƼƛǦƷƚǦǉƽế.",
    ["我只是想，若多几个长老弟子这样的人隐瞒身份去各国官府中，明面上研究些水利农具，实则利用官府之力，反为墨门依仗……"] = "ǥƶǦƸƽỉǦǃƼƽĩ,ǦǃếǊǦƸƚǦǉƽƙǂǦǋƐƾǦǃƼườƾǦǃƽưǦđệǦǉửǦƸủƶǦǉǇưởǃƼǦǁƃǄǦẩǃǦƼƾấǊǦǉƽƁǃǦǅƽậǃǦǋƐǄǦǆǊƶǃǦǅƽủǦƸƑƸǦǃướƸ,ǦƷềǦǃƼǄƐƾǦǃƼƽƾƙǃǦƸứǊǦǉƽủǓǦǁợƾǦǃƇǃƼǦƸụ,ǦǉƽựƸǦƸƽấǉǦǁƐǦǂượǃǦǁựƸǦǆǊƶǃǦǅƽủǦđểǦǁƐǂǦƸƽỗǦǤựƶǦƸƽǄǦƨặƸǦǂƇǃ...",
    ["难道只叫他们利用我们？若我们弟子有出息，怎么就不敢利用他们了？"] = "ƞƽẳǃƼǦǁẽǦƸứǦđểǦƽọǦǁợƾǦǤụǃƼǦƸƽƕǃƼǦǉƶǦǈƶǄ?ǦƩếǊǦđệǦǉửǦƸƽƕǃƼǦǉƶǦƸƚǦǉƾềǃǦđồ,ǦǈƶǄǦǁạƾǦǀƽƇǃƼǦǤƑǂǦǁợƾǦǤụǃƼǦǃƼượƸǦǁạƾǦƽọ?",
    ["贵客这胆子可真大……不过若真机灵些，倒也……唔……要说怎么混进去……"] = "ƬǊƈǦǀƽƑƸƽǦǁƑǦƼƶǃǦǉƽậǉǦǁớǃ...ǦǃƽưǃƼǦǃếǊǦǉƽựƸǦǈựǦǁƶǃƽǦǁợƾǦǉƽƔǦƸũǃƼ...Ǧừǂ...ǦǅƽảƾǦǃƚƾǦǁƐǦǁƐǂǦǈƶǄǦđểǦǉǇƐǦǉǇộǃǦǋƐǄ...",
    ["还是走乡野遗贤那一套？弄个奇人什么的…得找个重视水利农具，招人看本事，不查出身的地方……"] = "ƣƶǓǦǁƐǦǋẫǃǦǤƖǃƼǦƷƐƾǦ\"ǋịǦƽƾềǃǦǉƐƾǦǃơƾǦǉƽƇǃǦǤƃ\"?ǦǥạǄǦǇƶǦǂộǉǦǀỳǦǃƽƁǃǦƼƔǦđƚ...ǦǅƽảƾǦǉƔǂǦǃơƾǦǃƐǄǦƸǄƾǦǉǇọǃƼǦǉƽủǓǦǁợƾǦǃƇǃƼǦƸụ,ǦǉǊǓểǃǦǃƼườƾǦǤựƶǦǋƐǄǦƷảǃǦǁĩǃƽ,ǦǀƽƇǃƼǦǍƗǉǦǃƗǉǦǍǊấǉǦǉƽƁǃ...",
    ["天下诸国，哪个不想招贤，哪个不想安民？"] = "ǥƽƾƙǃǦƽạǦƸƑƸǦǃướƸ,ǦǀẻǦǃƐǄǦƸƽẳǃƼǦǂǊốǃǦƸƽƾƙǊǦƽƾềǃ,ǦǀẻǦǃƐǄǦƸƽẳǃƼǦǂǊốǃǦƶǃǦǤƁǃ?",
    ["墨门弟子俱是人中龙凤，若有此心，有的是机会。"] = "ĐệǦǉửǦƨặƸǦǂƇǃǦđềǊǦǁƐǦǃƽƁǃǦǉǇǊǃƼǦǁǄǃƼǦǅƽượǃƼ,ǦǃếǊǦƸƚǦǁƛǃƼǦǃƐǓ,ǦǉƽƾếǊǦƼƔǦƸơǦƽộƾ.",
    ["诶，事关弟子安危，哪能轻易就定下。你不懂，外头这些大国小国也不都是好的。"] = "ẤǓ,ǦƸƽǊǓệǃǦǁƾƙǃǦǆǊƶǃǦđếǃǦƶǃǦǃƼǊǓǦđệǦǉử,ǦǈƶǄǦƸƚǦǉƽểǦǉƖǓǦǉƾệǃǦǆǊǓếǉǦđịǃƽ.ǦƩƼươƾǦǀƽƇǃƼǦƽƾểǊǦđƁǊ,ǦǃƼǄƐƾǦǀƾƶǦǃướƸǦǁớǃǦǃướƸǦǃƽỏǦǀƽƇǃƼǦǅƽảƾǦǃơƾǦǃƐǄǦƸũǃƼǦǉốǉǦǁƐǃƽ.",
    ["有些地方，荒唐得很！"] = "ƞƚǦǃƽữǃƼǦǃơƾ,ǦƽǄƶǃƼǦđườǃƼǦƸựƸǦǀỳ!",
    ["竟有此事，是小子想的浅了。"] = "ƧạƾǦƸƚǦƸƽǊǓệǃǦđƚǦǈƶǄ,ǦǁƐǦǉƾểǊǦǉửǦǃƼƽĩǦǃƇǃƼǦƸạǃǦǇồƾ.",
    ["嘶……倒是该跟那皮猴儿写信了。不知他们在建隆观过得如何……"] = "ǥƙ...ǦǆǊảǦǁƐǦǃƙǃǦǋƾếǉǦǉƽưǦƸƽǄǦǂấǓǦđứƶǦǀƽỉǦƸǄǃǦđƚǦǇồƾ.ǦƦƽƇǃƼǦƷƾếǉǦƸƽƕǃƼǦởǦƦƾếǃǦƧǄǃƼǦƬǊƶǃǦǈốǃƼǦǇƶǦǈƶǄ...",
    ["你怎么看起来这么高兴？发生什么好事了，与说说呗？"] = "ƩƼươƾǦǁƐǂǦǈƶǄǦǂƐǦǉǇƇǃƼǦǋǊƾǦǋẻǦǉƽế?ǦƞƚǦƸƽǊǓệǃǦƼƔǦǉốǉǦǁƐǃƽ,ǦǀểǦǉƶǦǃƼƽƺǦƸƽƕǉǦǃƐǄ?",
    ["观景的内侍"] = "ƩộƾǦǉƽịǦǃƼắǂǦƸảǃƽ",
    ["方才我在这儿观景，一低头，嘿，那你猜怎么着？我居然发现了个钱袋！我赶忙把它藏#Y前头的石头缝里#E去了！"] = "ƱừƶǦǃƃǓǦǉƶǦởǦƸƽỗǦǃƐǓǦǃƼắǂǦƸảǃƽ,ǦǋừƶǦƸƕƾǦđầǊ,ǦƽƔ,ǦǃƼươƾǦđǄƑǃǦǍƺǂǦǈƶǄ?ǦǥƶǦƸưǦǃƽƾƙǃǦǅƽƑǉǦƽƾệǃǦǂộǉǦƸƑƾǦǉƕƾǦǉƾềǃ!ǦǥƶǦǋộƾǦǋƐǃƼǦđƺǂǦǃƚǦƼƾấǊǦǋƐǄǦ#YǦǀƽƺǦđƑǦǅƽƓƶǦǉǇướƸǦ#EǦǇồƾ!",
    ["兴奋观景的内侍"] = "ƩộƾǦǉƽịǦđƶǃƼǦƽưǃƼǦǅƽấǃǦǃƼắǂǦƸảǃƽ",
    ["你就这么告诉我了，不怕我偷了去？"] = "ƩƼươƾǦƸứǦǉƽếǦǂƐǦǃƚƾǦƸƽǄǦǉƶǦƷƾếǉ,ǦǀƽƇǃƼǦǈợǦǉƶǦǉǇộǂǦǂấǉǦǈƶǄ?",
    ["诶呀，我又没说哪边是前，哪边是后，更没说是哪块石头。你怎么可能找得到嘛！"] = "ẤǓǦƸƽƐ,ǦǉƶǦđƃǦǃƚƾǦƷƙǃǦǃƐǄǦǁƐǦǉǇướƸ,ǦƷƙǃǦǃƐǄǦǁƐǦǈƶǊǦđƁǊ,ǦƸƐǃƼǦƸƽưƶǦǃƚƾǦǁƐǦƽƛǃǦđƑǦǃƐǄ.ǦƧƐǂǦǈƶǄǦǃƼươƾǦƸƚǦǉƽểǦǉƔǂǦǉƽấǓǦđượƸǦƸƽứ!",
    ["金满箱，银满箱，金银满箱送爹娘……"] = "ƱƐǃƼǦđầǓǦǇươǃƼ,ǦƷạƸǦđầǓǦǇươǃƼ,ǦǋƐǃƼǦƷạƸǦđầǓǦǇươǃƼǦƼửƾǦǂẫǊǦǉƽƁǃǦǅƽụǦǉƽƁǃ...",
    ["乌帽戴，当差忙，明日就登天子堂……"] = "ĐộƾǦǂũǦƇǦǈƶ,ǦƷậǃǦǇộǃǦđươǃƼǦǈƶƾ,ǦǃƼƐǓǦǂƶƾǦǁƾềǃǦǁƙǃǦđƾệǃǦǥƽƾƙǃǦǥử...",
    ["信我的，天子脚下，龙气最足！"] = "ǥƾǃǦǉƶǦđƾ,ǦǤướƾǦƸƽƁǃǦǥƽƾƙǃǦǥử,ǦǁǄǃƼǦǀƽƓǦǁƐǦǤồƾǦǤƐǄǦǃƽấǉ!",
    ["等今儿这差事交了，我想去买点药膏，顺道吃碗老张家的羊肉面。"] = "ĐợƾǦǍǄǃƼǦǍǊƇƾǦƸƇǃƼǦǋƾệƸǦƽƇǂǦǃƶǓ,ǦǉƶǦǂǊốǃǦđƾǦǂǊƶǦƓǉǦƸƶǄǦǤượƸ,ǦǉƾệǃǦđườǃƼǦăǃǦƷƑǉǦǂƔǦǉƽịǉǦǤƙǦǃƽƐǦǁƃǄǦǥǇươǃƼ.",
    ["言之有理，还应多多尝试，三思后行。"] = "ƩƼƇǃǦƸƽƾǦƽữǊǦǁƈ,ǦǋẫǃǦǃƙǃǦǉƽửǦǃƼƽƾệǂǦǃƽƾềǊǦƽơǃ,ǦǉƶǂǦǉưǦƽậǊǦƽƐǃƽ.",
    ["左右为难，想不到进宫遇到如此难题！"] = "ǥảǦƽữǊǦǋƾǦǃƶǃ,ǦǀƽƇǃƼǦǃƼờǦǉƾếǃǦƸǊǃƼǦǁạƾǦƼặǅǦǅƽảƾǦǃƶǃǦđềǦǃƽưǦǋậǓ!",
    ["狸云熙"] = "ƧǓǦƱƁǃǦƣǓ",
    ["海宁冰心"] = "ƣảƾǦƩƾǃƽǦƝăǃƼǦǥƁǂ",
    ["你觉得是白日的冰灯好看，还是夜里的冰灯好看？"] = "ƩƼươƾǦǉƽấǓǦƷăǃƼǦđăǃƼǦƷƶǃǦǃƼƐǓǦđẹǅǦƽơǃ,ǦƽƶǓǦǁƐǦƷăǃƼǦđăǃƼǦƷƶǃǦđƙǂǦđẹǅǦƽơǃ?",
    ["当然是夜里亮起来的好看！"] = "ǝĩǦǃƽƾƙǃǦǁƐǦƷƶǃǦđƙǂǦǉƽắǅǦǈƑǃƼǦǁƙǃǦǉƽƔǦđẹǅǦƽơǃǦǇồƾ!",
    ["我倒觉得，白日里不亮的冰灯，更能看出它本来的美！"] = "ǥƶǦǁạƾǦǉƽấǓ,ǦƷăǃƼǦđăǃƼǦǁƕƸǦǀƽƇǃƼǦǉƽắǅǦǈƑǃƼǦǋƐǄǦƷƶǃǦǃƼƐǓ,ǦƸƐǃƼǦƸƚǦǉƽểǦǃƽƔǃǦǇƶǦǋẻǦđẹǅǦǃƼǊǓƙǃǦƷảǃǦƸủƶǦǃƚ!",
    ["新面孔？你也是来参加娘子们的冰嬉游赏的？"] = "ƢươǃƼǦǂặǉǦǂớƾǦǈƶǄ?ǦƩƼươƾǦƸũǃƼǦđếǃǦǉƽƶǂǦƼƾƶǦƷǊổƾǦǤǊǦǉƽưởǃƼǦƝăǃƼǦƣƾǦƸủƶǦƸƑƸǦǃươǃƼǦǃươǃƼǦƐ?",
    ["冰嬉游赏？宫里人都不上工了吗？"] = "ǝǊǦǉƽưởǃƼǦƝăǃƼǦƣƾ?ǦƩƼườƾǦǉǇǄǃƼǦƸǊǃƼǦǀƽƇǃƼǦƸầǃǦǁƐǂǦǋƾệƸǦǈƶǄ?",
    ["军士怎么能这么说呢，这叫劳逸结合！"] = "ƬǊƁǃǦǈĩǦǈƶǄǦǁạƾǦǃƚƾǦǋậǓ,ǦđƁǓǦƼọƾǦǁƐǦǀếǉǦƽợǅǦƼƾữƶǦǁƐǂǦǋƾệƸǦǋƐǦǃƼƽỉǦǃƼơƾ!",
    ["娘子们体恤大家冬日诸事无聊，当差又辛苦，便特设了这个冰嬉的活动，鼓鼓士气！"] = "ƞƑƸǦǃươǃƼǦǃươǃƼǦǉƽểǦǉấǉǦǂọƾǦǃƼườƾǦǂƖƶǦđƇǃƼǦƷǊồǃǦƸƽƑǃ,ǦǁƐǂǦǋƾệƸǦǁạƾǦǋấǉǦǋả,ǦǃƙǃǦǂớƾǦđặƸǦƷƾệǉǦǉổǦƸƽứƸǦƽǄạǉǦđộǃƼǦƝăǃƼǦƣƾǦǃƐǓǦđểǦǀƽƓƸƽǦǁệǦǈĩǦǀƽƓ!",
    ["你看，又是溜冰又是起舞的，光是看着就叫人心情好！其中佼佼者，还能得到娘子们的嘉奖呢！"] = "ƩƼươƾǦǍƺǂ,ǦǋừƶǦǉǇượǉǦƷăǃƼǦǋừƶǦǃƽảǓǦǂƕƶ,ǦƸƽỉǦǃƽƔǃǦǉƽƇƾǦƸũǃƼǦǀƽƾếǃǦǁƛǃƼǦǃƼườƾǦǋǊƾǦǋẻ!ǦƩƽữǃƼǦǃƼườƾǦǍǊấǉǦǈắƸǦǉǇǄǃƼǦđƚǦƸƛǃǦǃƽậǃǦđượƸǦǅƽầǃǦǉƽưởǃƼǦƸủƶǦƸƑƸǦǃươǃƼǦǃươǃƼǦǃữƶǦđấǓ!",
    ["什么嘉奖？怎么拿到？"] = "ƫƽầǃǦǉƽưởǃƼǦƼƔ?ǦƧƐǂǦǈƶǄǦđểǦǃƽậǃ?",
    ["这就要说到咱们冰嬉游赏的规矩啦！娘子们以“瑞雪兆丰年”为彩头，叫人在这冰湖上丢掷了不少雪，冰嬉的宫人取到的瑞雪越多，就越吉利。"] = "ƞƽǊǓệǃǦǃƐǓǦǅƽảƾǦǃƚƾǦđếǃǦǆǊǓǦƸủǦǤǊǦǉƽưởǃƼǦƝăǃƼǦƣƾǦƸủƶǦƸƽƕǃƼǦǉƶ!ǦƞƑƸǦǃươǃƼǦǃươǃƼǦǁấǓǦƈǦ\"ǥǊǓếǉǦǁƐǃƽǦƷƑǄǦǃăǂǦǉốǉ\"ǦǁƐǂǦđƾềǂǦǂƶǓ,ǦƸƽǄǦǃƼườƾǦǃƗǂǦǇấǉǦǃƽƾềǊǦǉǊǓếǉǦǁƙǃǦǂặǉǦƽồǦƷăǃƼǦǃƐǓ,ǦƸǊǃƼǦǃƽƁǃǦǉƽƶǂǦƼƾƶǦƝăǃƼǦƣƾǦǁấǓǦđượƸǦƸƐǃƼǦǃƽƾềǊǦǉǊǓếǉǦǁƐǃƽǦǉƽƔǦƸƐǃƼǦƸƑǉǦǉườǃƼ.",
    ["不过嘛，你知道的，虽说是彩头，但有了奖赏，玩乐就不纯粹了！娘子们还设了一重名目——冰上舞！"] = "ƞƚǦđƾềǊ,ǦǃƼươƾǦƷƾếǉǦđấǓ,ǦǉǊǓǦǃƚƾǦǁƐǦđƾềǂǦǂƶǓ,ǦǃƽưǃƼǦđƃǦƸƚǦǉƽưởǃƼǦǉƽƔǦǋƾệƸǦǋǊƾǦƸƽơƾǦǀƽƇǃƼǦƸƛǃǦđơǃǦǉƽǊầǃǦǃữƶ!ǦƞƑƸǦǃươǃƼǦǃươǃƼǦƸƛǃǦđặǉǦǇƶǦǂộǉǦǤƶǃƽǦǂụƸǦǀƽƑƸǦ—ǦƝăǃƼǦǥƽượǃƼǦƱũ!",
    ["若是有技艺高超者，能一面收集瑞雪一面于冰上起舞，就能得到更多的赏赐。"] = "ƩếǊǦǁƐǦǃƼườƾǦƸƚǦǀỹǦǃƼƽệǦƸƶǄǦǈƾƙǊ,ǦƸƚǦǉƽểǦǋừƶǦǉƽǊǦǉƽậǅǦǉǊǓếǉǦǁƐǃƽǦǋừƶǦǃƽảǓǦǂƕƶǦǉǇƙǃǦƷăǃƼ,ǦǉƽƔǦǈẽǦǃƽậǃǦđượƸǦǃƽƾềǊǦǅƽầǃǦǉƽưởǃƼǦƽơǃ.",
    ["也就是玩得开心，玩得高兴了，赏赐就是你的，不必拘于形式！"] = "ƞứǦƸƽơƾǦƸƽǄǦǉƽǄảƾǦǂƑƾ,ǦƸƽơƾǦƸƽǄǦǋǊƾǦǋẻ,ǦǅƽầǃǦǉƽưởǃƼǦǈẽǦǉƽǊộƸǦǋềǦǃƼươƾ,ǦǀƽƇǃƼǦƸầǃǦƼƛǦƷƚǦǋƐǄǦƽƔǃƽǦǉƽứƸ!",
    ["听起来有点意思，我也能参加吗？"] = "ƩƼƽƺǦƸƚǦǋẻǦǉƽƕǦǋị,ǦǉƶǦƸũǃƼǦƸƚǦǉƽểǦǉƽƶǂǦƼƾƶǦƸƽứ?",
    ["问得好！等的就是军士您这句话！"] = "ƣỏƾǦƽƶǓǦǁắǂ!ǦĐợƾǦƸƽƓǃƽǦǁƐǦƸƁǊǦǃƐǓǦƸủƶǦǆǊƁǃǦǈĩǦǃƼƐƾ!",
    ["方才十里开外我就看出了您身手不凡，和寻常武德司大不一样，来，拿着我的腰牌，去了就说你是我特别推荐的。"] = "ƱừƶǦǇồƾǦǉừǦƸƑƸƽǦǍƶǦǂườƾǦǤặǂǦǉƶǦđƃǦǃƽậǃǦǇƶǦǃƼƐƾǦǉƽƁǃǦǉƽủǦƷấǉǦǅƽƐǂ,ǦđạƾǦƷấǉǦđồǃƼǦǈǄǦǋớƾǦƱƅǦĐứƸǦǥǓǦǉƽƇǃƼǦǉƽườǃƼ,ǦǃƐǄ,ǦƸầǂǦǁấǓǦǓƙǊǦƷƐƾǦƸủƶǦǉƶ,ǦđếǃǦđƚǦƸứǦǃƚƾǦǃƼươƾǦǁƐǦǃƼườƾǦǉƶǦđặƸǦƷƾệǉǦǉƾếǃǦƸử.",
    ["到时候你滑好了，除开本来就归你的奖励，娘子们还会看我推举有功，另外给我笔赏钱——咱们二一添作五，一起分了！"] = "ĐếǃǦǁƕƸǦđƚǦǃƼươƾǦǉǇượǉǦƸƽǄǦǉốǉ,ǦǃƼǄƐƾǦǅƽầǃǦǉƽưởǃƼǦǋốǃǦǉƽǊộƸǦǋềǦǃƼươƾ,ǦƸƑƸǦǃươǃƼǦǃươǃƼǦǉƽấǓǦǉƶǦƸƚǦƸƇǃƼǦǉƾếǃǦƸửǦƸũǃƼǦǈẽǦƷƶǃǦǉƽưởǃƼǦǉƽƙǂǦƸƽǄǦǉƶǦ—ǦƸƽƕǃƼǦǉƶǦƸƽƾƶǦđƇƾ,ǦƸƖǃƼǦƽưởǃƼ!",
    ["这冰靴归你了，好好发挥！我俩能不能飞黄腾达，就看你的了！"] = "ĐƇƾǦƼƾƐǓǦǉǇượǉǦǃƐǓǦǉƽǊộƸǦǋềǦǃƼươƾ,ǦƸốǦƼắǃƼǦǉƽểǦƽƾệǃ!ǦƣƶƾǦǉƶǦƸƚǦǉƽểǦǉƽăǃƼǦǆǊƶǃǦǉƾếǃǦƸƽứƸǦƽƶǓǦǀƽƇǃƼ,ǦđềǊǦǉǇƇǃƼǦƸậǓǦǋƐǄǦǃƼươƾǦƸả!",
    ["射箭真是太有意思了，左拈弓，右搭箭，看我箭无虚发！"] = "ƳạǦǉƾễǃǦǉƽậǉǦǁƐǦǉƽƕǦǋị,ǦǉƶǓǦǉǇƑƾǦƼƾươǃƼǦƸǊǃƼ,ǦǉƶǓǦǅƽảƾǦđặǉǦǉƾễǃ,ǦǍƺǂǦǉƶǦǉƾễǃǦǋƇǦƽưǦǅƽƑǉ!",
    ["刚刚那箭似乎有点歪了，还有进步的余地……"] = "ƨũƾǦǉƾễǃǦǋừƶǦǇồƾǦƽƔǃƽǦǃƽưǦƽơƾǦǁệƸƽ,ǦǋẫǃǦƸƛǃǦƸƽỗǦƸầǃǦǉƾếǃǦƷộ...",
    ["你这射箭的本事看着长进了不少。"] = "ƝảǃǦǁĩǃƽǦǍạǦǉƾễǃǦǃƐǓǦƸủƶǦǃƼươƾǦǍƺǂǦǇƶǦđƃǦǉƾếǃǦƷộǦǀƽƇǃƼǦƓǉ.",
    ["那当然，我这些时日早射箭，晚射箭，除开吃饭休息便是在射箭，箭术自然进步飞快。"] = "ĐƚǦǁƐǦđươǃƼǦǃƽƾƙǃ,ǦǉƶǦǤạǄǦƼầǃǦđƁǓǦǈƑǃƼǦǍạǦǉƾễǃ,ǦǉốƾǦǍạǦǉƾễǃ,ǦǃƼǄƐƾǦǉǇừǦăǃǦƸơǂǦǃƼƽỉǦǃƼơƾǦǇƶǦǉƽƔǦđềǊǦǁƐǦǍạǦǉƾễǃ,ǦǉƾễǃǦǉƽǊậǉǦǉựǦǃƽƾƙǃǦǉƾếǃǦƷộǦǉƽầǃǦǉốƸ.",
    ["那你当时的心上人呢？"] = "ƱậǓǦƸƛǃǦǃƼườƾǦǉǇǄǃƼǦǂộǃƼǦǀƽƾǦđƚǦƸủƶǦǃƼươƾǦǉƽƔǦǈƶǄ?",
    ["心上人？……哦！是还有这么一回事。"] = "ƩƼườƾǦǉǇǄǃƼǦǂộǃƼ?...ǦỒ!ǦĐƕǃƼǦǁƐǦƸƛǃǦƸƚǦƸƽǊǓệǃǦǃƽưǦǉƽế.",
    ["我每日都忙着射箭，忙着忙着就忘了此事了，嘿嘿……"] = "ǥƶǦǂỗƾǦǃƼƐǓǦđềǊǦƷậǃǦǍạǦǉƾễǃ,ǦƷậǃǦǆǊƑǦǃƙǃǦǆǊƙǃǦǂấǉǦǉƾƙǊǦǇồƾ,ǦƽƔǦƽƔ...",
    ["不说了，手感来了，我要再来十箭！看我箭无虚发！"] = "ƦƽƇǃƼǦǃƚƾǦǃữƶ,ǦǉƔǂǦđượƸǦƸảǂǦƼƾƑƸǦǇồƾ,ǦǉƶǦǅƽảƾǦƷắǃǦǉƽƙǂǦǂườƾǦǉƾễǃǦǃữƶ!ǦƳƺǂǦǉƶǦǉƾễǃǦǋƇǦƽưǦǅƽƑǉ!",
    ["这个侍卫射箭的准头越来越好了，不错。"] = "ǥƙǃǦǉƽịǦǋệǦǃƐǓǦƷắǃǦǉƙǃǦǃƼƐǓǦƸƐǃƼǦƸƽǊẩǃǦǍƑƸ,ǦǀƽƑǦǁắǂ.",
    ["我现在一上午能拎十趟水了，我也很不错！"] = "ǥƶǦƷƁǓǦƼƾờǦǂộǉǦƷǊổƾǦǈƑǃƼǦƸƚǦǉƽểǦǍƑƸƽǦđượƸǦǂườƾǦƸƽǊǓếǃǦǃướƸ,ǦǉƶǦƸũǃƼǦǇấǉǦƸừǦǀƽƇƾ!",
    ["哇，那还是你比较厉害！"] = "ƪƶ,ǦǋậǓǦǉƽƔǦǋẫǃǦǁƐǦǃƼươƾǦǁợƾǦƽạƾǦƽơǃ!",
    ["过往咱们营里就数你身手最好，打的仗最多，如今你又求学若渴，想来升迁有望啊。"] = "ǥǇướƸǦǀƾƶǦǉǇǄǃƼǦǤǄƶǃƽǦƸƽƕǃƼǦǉƶǦƸƽỉǦƸƚǦǃƼươƾǦǉƽƁǃǦǉƽủǦǉốǉǦǃƽấǉ,ǦđƑǃƽǦǉǇậǃǦǃƽƾềǊǦǃƽấǉ,ǦǃƶǓǦǃƼươƾǦǁạƾǦƸầǊǦƽọƸǦǃƽượƸǦǀƽƑǉ,ǦǍƺǂǦǇƶǦǉƽăǃƼǦǉƽƾƙǃǦƸƚǦƽǓǦǋọǃƼǦǇồƾ.",
    ["一天天的总爱拍我马屁！我读这书不为钱财，也不为那些名头，只为有用而已。"] = "ƩƼƐǓǦǃƐǄǦƸũǃƼǦǉƽƓƸƽǦǃịǃƽǦƽƚǉǦǉƶ!ǦǥƶǦđọƸǦǈƑƸƽǦǃƐǓǦǀƽƇǃƼǦǋƔǦǉƾềǃǦǉƐƾ,ǦƸũǃƼǦƸƽẳǃƼǦǋƔǦǤƶǃƽǦǉƾếǃƼ,ǦƸƽỉǦǋƔǦƸƚǦƓƸƽǦǂƐǦǉƽƇƾ.",
    ["文武兼备，难道不是一件好事吗？"] = "ƱăǃǦǋƅǦǈǄǃƼǦǉǄƐǃ,ǦƽƑǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǂộǉǦƸƽǊǓệǃǦǉốǉǦǈƶǄ?",
    ["说是好事，也算吧……但归根结底，官家要的不是你识几个大字，而是要你算得明白为臣忠义这本账。"] = "ƩƚƾǦǁƐǦƸƽǊǓệǃǦǉốǉǦǉƽƔǦƸũǃƼǦđƕǃƼ...ǦǃƽưǃƼǦǈǊǓǦƸƽǄǦƸƖǃƼ,ǦƬǊƶǃǦƢƾƶǦƸầǃǦǀƽƇǃƼǦǅƽảƾǦǁƐǦǃƼươƾǦƷƾếǉǦǋƐƾǦǂặǉǦƸƽữ,ǦǂƐǦǁƐǦǂǊốǃǦǃƼươƾǦǉƓǃƽǦǉǄƑǃǦƸƽǄǦǇƅǦǇƐǃƼǦƸƑƾǦđạǄǦǃƼƽĩƶǦǉǇǊǃƼǦǆǊƁǃǦƸủƶǦǀẻǦǁƐǂǦǉƽầǃǦǉử.",
    ["剧剧剧，老吕，士别三日，真是刮目相看呀。"] = "ƞƽậƸǦƸƽậƸǦƸƽậƸ,ǦƧƃǄǦƧƃǦǋấǉǦǋảǦǇồƾ,ǦǈĩǦƷƾệǉǦǉƶǂǦǃƽậǉ,ǦǆǊảǦǉƽựƸǦǀƽƾếǃǦǉƶǦǅƽảƾǦǁƶǊǦǂắǉǦǂƐǦǃƽƔǃ.",
    ["这雪墩墩的形状，怎么总是与昨日有差呢？"] = "ƣƔǃƽǦǤƑǃƼǦƸủƶǦđốǃƼǦǉǊǓếǉǦǃƐǓ,ǦǈƶǄǦƸứǦǀƽƑƸǦǋớƾǦƽƇǂǦǆǊƶǦǉƽếǦǃƽỉ?",
    ["这雪太厚了，扫起来真费劲！"] = "ǥǊǓếǉǦǃƐǓǦǤƐǓǦǆǊƑ,ǦǆǊƗǉǦǤọǃǦǉƽậǉǦǉốǃǦǈứƸ!",
    ["好可爱的雪人！"] = "ƩƼườƾǦǉǊǓếǉǦđƑǃƼǦǓƙǊǦǆǊƑ!",
    ["等到夜里没人了，便来悄悄摸上一摸！"] = "ĐợƾǦđếǃǦđƙǂǦǋắǃƼǦǃƼườƾ,ǦǈẽǦǁƗǃǦđếǃǦǈờǦǂộǉǦƸƑƾ!",
    ["嗯？那边是不是有个白色的影子飘过去了？"] = "ƣửǂ?ǦĐằǃƼǦǀƾƶǦƸƚǦǅƽảƾǦƸƚǦƷƚǃƼǦǉǇắǃƼǦǃƐǄǦǋừƶǦǁướǉǦǆǊƶǦǀƽƇǃƼ?",
    ["好大的一场雪！"] = "ƨộǉǦǉǇậǃǦǉǊǓếǉǦǉƽậǉǦǁớǃ!",
    ["想必是天老爷开恩，明年家里能得个好收成了. "] = "ƞƽắƸǦƽẳǃǦǁƐǦƆǃƼǦǥǇờƾǦǀƽƶƾǦƁǃ,ǦǈƶǃƼǦǃăǂǦǃƽƐǦǉƶǦǈẽǦƸƚǦǂộǉǦǂƖƶǦǂƐǃƼǦƷộƾǦǉƽǊ.",
    ["其实我只是一只猴子，大家都是这假山上的猴子，终日奔波劳碌，都只是为了摘点桃子吃吃。"] = "ǥƽựƸǦǇƶǦǉƶǦƸƽỉǦǁƐǦǂộǉǦƸǄǃǦǀƽỉ,ǦǂọƾǦǃƼườƾǦđềǊǦǁƐǦǀƽỉǦǉǇƙǃǦƽƛǃǦǃǄǃǦƷộǦǃƐǓǦƸảǦǉƽƇƾ,ǦǈǊốǉǦǃƼƐǓǦƷƇǃǦƷƶǦǁƶǄǦǁựƸǦƸũǃƼǦƸƽỉǦǋƔǦƽƑƾǦƸƽƕǉǦđƐǄǦđểǦăǃ.",
    ["加把劲！"] = "ƞốǦƼắǃƼǦǉƽƙǂǦƸƽƕǉǦǃữƶ!",
    ["这——不应当是管事的给我们拿么？怎么成了自己拿了，这里的人可真清闲。"] = "ƱƾệƸǦǃƐǓ——ǦƸƽẳǃƼǦǅƽảƾǦǃƙǃǦǤǄǦǆǊảǃǦǈựǦđưƶǦƸƽǄǦƸƽƕǃƼǦǉƶǦǈƶǄ?ǦƮƶǄǦǁạƾǦǉƽƐǃƽǦǉựǦǂƔǃƽǦđƾǦǁấǓǦǉƽếǦǃƐǓ,ǦǃƼườƾǦởǦđƁǓǦǉƽậǉǦǁƐǦǉƽƶǃƽǦǃƽƐǃǦǆǊƑǦđƾ.",
    ["嘘，别说了，小心让人给听见了。"] = "ƮǊỵǉ,ǦđừǃƼǦǃƚƾǦǃữƶ,ǦƸẩǃǦǉƽậǃǦǀẻǄǦƷịǦǃƼườƾǦǉƶǦǃƼƽƺǦǉƽấǓ.",
    ["米面就在这边取用，一应调味品在隔壁架子，取的时候看着点，别碰倒了罐子。"] = "ƢạǄǦǂƔǦǉƽƔǦǁấǓǦởǦƷƙǃǦǃƐǓ,ǦƸƑƸǦǁǄạƾǦƼƾƶǦǋịǦởǦǀệǦƷƙǃǦƸạǃƽ,ǦǁƕƸǦǁấǓǦƸƽƕǦƈǦǂộǉǦƸƽƕǉ,ǦđừǃƼǦǁƐǂǦđổǦǋƛǦǃƽƗ.",
    ["大人您这是在演练吗？小的可不敢做这个靶子。"] = "ĐạƾǦǃƽƁǃǦǃƼƐƾǦđƶǃƼǦǤƾễǃǦǁǊǓệǃǦǈƶǄ?ǦǥƾểǊǦǃƽƁǃǦǀƽƇǃƼǦǤƑǂǦǁƐǂǦƷƾƶǦđỡǦđạǃǦđƁǊ.",
    ["今年天灾多，冬菜都少了好些。得仔细清点这些菜，若是数量不足，还得抓紧时间报上去，免得过冬不够用了。"] = "ƩăǂǦǃƶǓǦǉƽƾƙǃǦǉƶƾǦǃƽƾềǊ,ǦǇƶǊǦǂƖƶǦđƇǃƼǦƓǉǦđƾǦƽẳǃ.ǦƫƽảƾǦǀƾểǂǦǀƙǦǀỹǦǈốǦǇƶǊǦǃƐǓ,ǦǃếǊǦǀƽƇǃƼǦđủǦǈốǦǁượǃƼǦǉƽƔǦǅƽảƾǦǀƽẩǃǦǉǇươǃƼǦƷƑǄǦƸƑǄǦǁƙǃǦǉǇƙǃ,ǦǉǇƑǃƽǦđểǦǂƖƶǦđƇǃƼǦǀƽƇǃƼǦđủǦǤƖǃƼ.",
    ["我看看，姜豉够数……哟，这还有螃蟹呢！真难得。"] = "ĐểǦǉƶǦǍƺǂ,ǦƼừǃƼǦǂǊốƾǦđủǦǈố...ǦƇ,ǦởǦđƁǓǦƸƛǃǦƸƚǦƸǊƶǦǃữƶǦǃƐǓ!ǦǥƽậǉǦƽƾếǂǦǉƽấǓ.",
    ["虽说官家不喜铺张，今年收成也不好，但像样的酒醴还是少不了……对了，菜干、灶糖也要开始准备了。"] = "ǝẫǊǦǇằǃƼǦƬǊƶǃǦƢƾƶǦǀƽƇǃƼǦǉƽƓƸƽǦǅƽƇǦǉǇươǃƼ,ǦǉƽǊǦƽǄạƸƽǦǃăǂǦǃƶǓǦƸũǃƼǦǀƽƇǃƼǦǉốǉ,ǦǃƽưǃƼǦǇượǊǦǃƼǄǃǦđƕǃƼǦǂựƸǦǉƽƔǦǋẫǃǦǀƽƇǃƼǦǉƽểǦǉƽƾếǊ...ǦĐƕǃƼǦǇồƾ,ǦǇƶǊǦǀƽƇ,ǦǀẹǄǦǉƑǄǦƸũǃƼǦǅƽảƾǦƷắǉǦđầǊǦƸƽǊẩǃǦƷịǦǇồƾ.",
    ["清单是先前早就定下的，明日一早我再去清点核对，保管这年末大典办得稳妥。"] = "ǝƶǃƽǦǈƑƸƽǦđƃǦđịǃƽǦǉừǦǉǇướƸǦǇồƾ,ǦǈƑǃƼǦǈớǂǦǂƶƾǦǉƶǦǈẽǦđƾǦǀƾểǂǦǀƙǦđốƾǦǈǄƑǉǦǁạƾǦǁầǃǦǃữƶ,ǦƷảǄǦđảǂǦđạƾǦđƾểǃǦƸǊốƾǦǃăǂǦǈẽǦǤƾễǃǦǇƶǦổǃǦǉƽỏƶ.",
    ["真是越到年关越忙活。冬至、除夕，好些大日子……也就现在这时候，还能跟你们说说话。"] = "ĐƕǃƼǦǁƐǦƸƐǃƼǦđếǃǦƸǊốƾǦǃăǂǦƸƐǃƼǦƷậǃǦǇộǃ.ǦĐƇǃƼǦƞƽƓ,ǦǥǇừǦǥịƸƽ,ǦƷƶǄǦǃƽƾƙǊǦǃƼƐǓǦđạƾǦǁễ...ǦƸũǃƼǦƸƽỉǦƸƚǦǁƕƸǦǃƐǓǦǂớƾǦƸƚǦǉƽểǦǃƚƾǦƸƽǊǓệǃǦǋớƾǦƸƑƸǦǃƼươƾǦǋƐƾǦƸƁǊ.",
    ["忙碌的宫女"] = "ƞǊǃƼǦǃữǦƷậǃǦǇộǃ",
    ["听说为了大典，那些车马都要提前好久演练呢。岁末还有傩仪，诸班直戴上傩面！真想见识见识……"] = "ƩƼƽƺǦǃƚƾǦđểǦƸƽǊẩǃǦƷịǦđạƾǦđƾểǃ,ǦǍƺǦǃƼựƶǦđềǊǦǅƽảƾǦǤƾễǃǦǁǊǓệǃǦǉừǦǈớǂ.ǦƞǊốƾǦǃăǂǦƸƛǃǦƸƚǦǁễǦƩƶ,ǦƞƽưǦƝƶǃǦǥǇựƸǦđềǊǦđƺǄǦǂặǉǦǃạǦƩƶ!ǦǥƽậǉǦǂǊốǃǦǂởǦǂƶǃƼǦǉầǂǦǂắǉǦǆǊƑ...",
    ["消息灵通的宫女"] = "ƞǊǃƼǦǃữǦǉƽạǄǦǉƾǃ",
    ["嘘……我听说到时候还有许多使臣来！那些异邦使臣，会同我们长得很不一样吗？"] = "ƮǊỵǉ...ǦǥƶǦǃƼƽƺǦǃƚƾǦǀƽƾǦđƚǦƸƛǃǦƸƚǦǇấǉǦǃƽƾềǊǦǈứǦǉƽầǃǦđếǃ!ǦƩƽữǃƼǦǈứǦǉƽầǃǦǤịǦƷƶǃƼǦđƚ,ǦǁƾệǊǦƸƚǦǉǇƇǃƼǦǀƽƑƸǦƽẳǃǦƸƽƕǃƼǦǉƶǦǀƽƇǃƼǦǃƽỉ?",
    ["好奇的宫女"] = "ƞǊǃƼǦǃữǦǉƛǦǂƛ",
    ["听说这边不干净……哼，有的人自己怕沾上啥不敢过来，就使唤我们这些新来的……"] = "ƩƼƽƺǦǃƚƾǦƸƽỗǦǃƐǓǦǀƽƇǃƼǦǈạƸƽǦǈẽ...Ǧƣừ,ǦƸƚǦǃƼườƾǦǉựǦǂƔǃƽǦǈợǦǤƓǃƽǦǅƽảƾǦƸƑƾǦƼƔǦđƚǦǀƽƇǃƼǦǤƑǂǦǆǊƶǦđƁǓ,ǦǃƙǃǦǂớƾǦǈƶƾǦƷảǄǦƷọǃǦǂớƾǦǉớƾǦǃƽưǦƸƽƕǃƼǦǉƶ...",
    ["尚食局取粳米两升，白面一袋，以供日常餐食。"] = "ǥƽượǃƼǦǥƽựƸǦƞụƸǦǁấǓǦƽƶƾǦǉƽăǃƼǦƼạǄǦǉẻ,ǦǂộǉǦƷƶǄǦƷộǉǦǂƔ,ǦđểǦƸǊǃƼǦứǃƼǦƷữƶǦăǃǦƽƐǃƼǦǃƼƐǓ.",
    ["我也听说，那些宫里的老人就爱欺负新来的！"] = "ǥƶǦƸũǃƼǦǃƼƽƺǦǃƚƾ,ǦǂấǓǦǃƼườƾǦƸũǦǉǇǄǃƼǦƸǊǃƼǦƸƽỉǦǉƽƓƸƽǦƷắǉǦǃạǉǦǃƼườƾǦǂớƾǦǉƽƇƾ!",
    ["登记好了，跟着前头人走，别走错了啊。"] = "ĐăǃƼǦǀƈǦǍǄǃƼǦǇồƾ,ǦđƾǦǉƽƺǄǦǃƼườƾǦǅƽƓƶǦǉǇướƸ,ǦđừǃƼǦđƾǦǈƶƾǦđấǓ.",
    ["这最近来的人，都是一下子取用好些米面啥的，难道你们那又来新人了？"] = "ǝạǄǦƼầǃǦđƁǓǦǃƼườƾǦđếǃǦđềǊǦǂộǉǦƽơƾǦǁấǓǦđƾǦƷƶǄǦǃƽƾƙǊǦƼạǄǦǂƔ,ǦǁẽǦǃƐǄǦƷƙǃǦƸƽỗǦƸƑƸǦǃƼươƾǦǁạƾǦƸƚǦǉƽƙǂǦǃƼườƾǦǂớƾǦƐ?",
    ["也不全是因为这个，主要是大家都知道这边不干净，能一下取完的就一次取回去，少来几趟呗。"] = "ƞũǃƼǦǀƽƇǃƼǦƽǄƐǃǦǉǄƐǃǦǁƐǦǋƔǦǉƽế,ǦƸƽủǦǓếǊǦǁƐǦǂọƾǦǃƼườƾǦđềǊǦƷƾếǉǦƸƽỗǦǃƐǓǦǀƽƇǃƼǦǈạƸƽǦǈẽ,ǦƸƑƾǦƼƔǦǁấǓǦƽếǉǦđượƸǦǂộǉǦǁầǃǦǉƽƔǦǁấǓǦǁǊƇǃ,ǦđểǦǀƽỏƾǦǅƽảƾǦđƾǦǁạƾǦǃƽƾềǊǦƸƽǊǓếǃ.",
    ["哎哟，到底是年纪小，胆子也小，我在宫里头干了这么些年，啥事没见过啊，要说这次这个鬼，还不如先前我见的那个……"] = "ÁƾǦƸƽƐ,ǦđƕǃƼǦǁƐǦǉǊổƾǦƸƛǃǦǃƽỏǦǃƙǃǦǃƽƑǉǦƼƶǃ,ǦǉƶǦǁƐǂǦǋƾệƸǦǉǇǄǃƼǦƸǊǃƼǦƷƶǄǦǃƽƾƙǊǦǃăǂǦǃƶǓ,ǦƸƽǊǓệǃǦƼƔǦǂƐǦƸƽưƶǦǉừǃƼǦǉƽấǓǦǆǊƶǦƸƽứ,ǦǃếǊǦǃƚƾǦǋềǦƸǄǃǦǆǊỷǦǁầǃǦǃƐǓ,ǦƸƛǃǦƸƽẳǃƼǦƷằǃƼǦƸǄǃǦǉƶǦƼặǅǦƽồƾǦǉǇướƸ...",
    ["哪个？您给说说呗！"] = "ƞǄǃǦǃƐǄǦƸơ?ǦƝƐǦǀểǦƸƽǄǦƸƽƕǃƼǦƸǄǃǦǃƼƽƺǦđƾ!",
    ["那是我刚入宫的时候……哎哟，你这丫头，要是想听故事，待不当值再来，别耽误后头人取东西。"] = "ĐƚǦǁƐǦƽồƾǦǉƶǦǂớƾǦǋƐǄǦƸǊǃƼ...ǦÁƾǦƸƽƐ,ǦƸƑƾǦƸǄǃǦƷƗǦǃƐǓ,ǦǃếǊǦǂǊốǃǦǃƼƽƺǦǀểǦƸƽǊǓệǃǦǉƽƔǦđợƾǦǁƕƸǦǀƽƇǃƼǦǉǇựƸǦƽƃǓǦđếǃ,ǦđừǃƼǦǁƐǂǦǁỡǦǋƾệƸǦǁấǓǦđồǦƸủƶǦǃƼườƾǦǅƽƓƶǦǈƶǊ.",
    ["一年到头，扫完落叶，还有扫不完的雪。"] = "ƬǊƶǃƽǦǃăǂǦǈǊốǉǦǉƽƑǃƼ,ǦǆǊƗǉǦǍǄǃƼǦǁƑǦǇụǃƼǦǁạƾǦđếǃǦǉǊǓếǉǦǆǊƗǉǦǂƃƾǦǀƽƇǃƼǦƽếǉ.",
    ["白天数一回，晚上还数，我说差不多得了！"] = "ƝƶǃǦǃƼƐǓǦđếǂǦǂộǉǦǁầǃ,ǦƷƶǃǦđƙǂǦǁạƾǦđếǂ,ǦǉƶǦǃƚƾǦǉƽếǦǁƐǦđủǦǇồƾǦđấǓ!",
    ["老了老了该享福了，我却还在这干活，看谁都觉得欠我一点钱！"] = "ƢƾƐǦǇồƾǦƼƾƐǦǇồƾǦǁẽǦǇƶǦǅƽảƾǦđượƸǦƽưởǃƼǦǅƽƕƸ,ǦǋậǓǦǂƐǦǉƶǦǋẫǃǦǅƽảƾǦởǦđƁǓǦǁƐǂǦǁụǃƼ,ǦǃƽƔǃǦƶƾǦƸũǃƼǦǉƽấǓǦǃƽưǦƽọǦǃợǦǉƾềǃǦǉƶǦǋậǓ!",
    ["我的钱……我的钱全没了！我辛辛苦苦勤勤恳恳兢兢业业攒的那么多银子铜钱，全没了啊！"] = "ǥƾềǃǦƸủƶǦǉƶ...ǦǉƾềǃǦƸủƶǦǉƶǦǂấǉǦǈạƸƽǦǇồƾ!ǦƝƶǄǦǃƽƾƙǊǦƷạƸǦǁẻǦđồǃƼǦǉƾềǃǦǉƶǦǋấǉǦǋảǦƸầǃǦƸƖ,ǦǉậǃǦǉụǓǦǉƓƸƽǦƸƚǅǦƷấǓǦǁƁǊǦǃƶǓ,ǦǂấǉǦǈạƸƽǦǈƐǃƽǦǈƶǃƽǦǇồƾ!",
    ["钱宿莱"] = "ǥƾềǃǦǥƕƸǦƧƶƾ",
    ["军士您消消火，您武功高强，小的可受不住啊！"] = "ƬǊƁǃǦǈĩǦǃƼƐƾǦƷớǉǦƼƾậǃ,ǦǃƼƐƾǦǋƅǦƸƇǃƼǦƸƶǄǦƸườǃƼ,ǦǉƾểǊǦǃƽƁǃǦǀƽƇǃƼǦƸƽịǊǦǉƽấǊǦđƁǊ!",
    ["我的钱回来了！终于回来了！啊，我的钱！我想死你们了！"] = "ǥƾềǃǦƸủƶǦǉƶǦǆǊƶǓǦǁạƾǦǇồƾ!ǦƞǊốƾǦƸƖǃƼǦƸũǃƼǦǆǊƶǓǦǁạƾǦǇồƾ!ǦƆƾ,ǦǉƾềǃǦƸủƶǦǉƶǦơƾ!ǦǥƶǦǃƽớǦƸƑƸǦǃƼươƾǦƸƽếǉǦđƾǦđượƸ!",
    ["唉，年末了，我却连这本书都没看完，惭愧惭愧。"] = "ƣầǓ,ǦƸǊốƾǦǃăǂǦǇồƾǦǂƐǦǉƶǦđếǃǦƸǊốǃǦǈƑƸƽǦǃƐǓǦƸũǃƼǦƸƽưƶǦđọƸǦǍǄǃƼ,ǦƽổǦǉƽẹǃ,ǦƽổǦǉƽẹǃǦǆǊƑ.",
    ["写这书的究竟是谁，要是让我知道了，我饶不了这人！"] = "ƭốǉǦƸǊộƸǦǀẻǦǃƐǄǦǋƾếǉǦƸǊốǃǦǈƑƸƽǦǃƐǓ,ǦǃếǊǦđểǦǉƶǦƷƾếǉǦđượƸ,ǦǉƶǦǈẽǦǀƽƇǃƼǦǉƽƶǦƸƽǄǦƽắǃǦđƁǊ!",
    ["老哥，你也快五十了，你就不着急？要是我让人给撵出去了，想想就觉得丢脸啊。"] = "ƧƃǄǦƸƶ,ǦƽǊǓǃƽǦƸũǃƼǦƼầǃǦǃăǂǦǂươƾǦǇồƾ,ǦƽǊǓǃƽǦǀƽƇǃƼǦǈốǉǦǇǊộǉǦǈƶǄ?ǦƩếǊǦǂƐǦƷịǦǃƼườƾǦǉƶǦđǊổƾǦǇƶǦǃƼǄƐƾ,ǦǃƼƽĩǦǉƽƇƾǦđƃǦǉƽấǓǦǂấǉǦǂặǉǦǇồƾ.",
    ["有啥丢脸的，回家垦荒也一样能活！"] = "ƞƚǦƼƔǦǂƐǦǂấǉǦǂặǉ,ǦǋềǦǆǊƙǦǀƽƶƾǦƽǄƶǃƼǦƸũǃƼǦǈốǃƼǦđượƸǦǋậǓ!",
    ["二位，何出此言？"] = "ƣƶƾǦǋị,ǦǈƶǄǦǁạƾǦǃƚƾǦǋậǓ?",
    ["你武德司的自然不会懂了，如今官家要裁撤殿前司兵将，只余精兵，我都这个岁数了，哪里争得过那些年轻的？"] = "ƩƼươƾǦởǦƱũǦĐứƸǦǥǓǦǉựǦǃƽƾƙǃǦǈẽǦǀƽƇǃƼǦƽƾểǊǦđƁǊ,ǦǃƶǓǦƬǊƶǃǦƢƾƶǦǂǊốǃǦǉƾǃƽǦƼƾảǃǦƷƾǃƽǦǉướǃƼǦĐƾệǃǦǥƾềǃǦǥǓ,ǦƸƽỉǦƼƾữǦǁạƾǦǉƾǃƽǦƷƾǃƽ,ǦǉƶǦđƃǦởǦƸƑƾǦǉǊổƾǦǃƐǓǦǇồƾ,ǦǈƶǄǦǉǇƶǃƽǦǃổƾǦǋớƾǦđƑǂǦǉǇẻǦǉǊổƾǦǀƾƶǦƸƽứ?",
    ["这话我可不赞成啊，年轻的有精力，咱这个岁数的有阅历嘛，你咋就确定走的一定是你？"] = "ƧờƾǦǃƐǓǦǉƶǦǀƽƇǃƼǦǉƑǃǦǉƽƐǃƽǦđƁǊǦǃƽƗ,ǦǃƼườƾǦǉǇẻǦƸƚǦǈứƸǦǁựƸ,ǦǃƽưǃƼǦƸƑƾǦǉǊổƾǦǃƽưǦƸƽƕǃƼǦǉƶǦǉƽƔǦƸƚǦǀƾǃƽǦǃƼƽƾệǂǦǂƐ,ǦǈƶǄǦǃƼươƾǦƸƽắƸǦƸƽắǃǦǃƼườƾǦǅƽảƾǦđƾǦǃƽấǉǦđịǃƽǦǁƐǦǃƼươƾ?",
    ["唉，前头吴老哥走了以后，孙勇哥也得了风寒告假……世事无常呀，不知道哪天就轮到咱哥俩了。"] = "ƣầǓ,ǦǈƶǊǦǀƽƾǦƩƼƇǦǁƃǄǦƸƶǦǅƽƓƶǦǉǇướƸǦđƾǦǇồƾ,ǦǥƇǃǦǝũǃƼǦƸƶǦƸũǃƼǦƷịǦǅƽǄǃƼǦƽƐǃǦǍƾǃǦǃƼƽỉ...ǦǉƽếǦǈựǦǋƇǦǉƽườǃƼ,ǦǀƽƇǃƼǦƷƾếǉǦǃƼƐǓǦǃƐǄǦǈẽǦđếǃǦǁượǉǦƶǃƽǦƺǂǦǂƔǃƽǦǃữƶ.",
    ["川蜀一带乌头，若适量取用可散寒止痛，超量生用则会引起中毒。且将其捣作汁，煎成膏，再看是否仍留存毒性。"] = "ƆǦđầǊǦǋƖǃƼǦƳǊǓƙǃǦǥƽụƸ,ǦǃếǊǦǤƖǃƼǦǁượǃƼǦǋừƶǦǅƽảƾǦƸƚǦǉƽểǦǉƑǃǦƽƐǃǦƸƽỉǦǉƽốǃƼ,ǦǤƖǃƼǦǈốǃƼǦǆǊƑǦǁƾềǊǦǈẽǦƼƁǓǦǃƼộǦđộƸ.ǦƣƃǓǦƼƾƃǦǁấǓǦǃướƸ,ǦǈắƸǦǉƽƐǃƽǦƸƶǄ,ǦǇồƾǦǍƺǂǦǁƾệǊǦƸƚǦƸƛǃǦǉồǃǦǤưǦđộƸǦǉƓǃƽǦƽƶǓǦǀƽƇǃƼ.",
    ["今天听姑姑说，咱们是这几年来第一批进宫的，上面的人都盯着呢，可得好好表现，千万不能出岔子。"] = "ƣƇǂǦǃƶǓǦǃƼƽƺǦƸƇǦƸƇǦǃƚƾ,ǦƸƽƕǃƼǦǉƶǦǁƐǦđợǉǦđầǊǦǉƾƙǃǦǋƐǄǦƸǊǃƼǦǉǇǄǃƼǦǂấǓǦǃăǂǦǉǇởǦǁạƾǦđƁǓ,ǦǃƼườƾǦƷƙǃǦǉǇƙǃǦđềǊǦđƶǃƼǦđểǦǂắǉǦǉớƾǦđƚ,ǦǅƽảƾǦƷƾểǊǦƽƾệǃǦƸƽǄǦǉốǉ,ǦǋạǃǦǁầǃǦǀƽƇǃƼǦđượƸǦđểǦǍảǓǦǇƶǦǈƶƾǦǈƚǉ.",
    ["可我听老宫女说，咱们这批人名额可少了，最后能留下的没几个。诶，你们说这新人期到底要做些什么啊？"] = "ƩƽưǃƼǦǉƶǦǃƼƽƺǦǁƃǄǦƸǊǃƼǦǃữǦǃƚƾ,ǦƸƽỉǦǉƾƙǊǦƸƽǄǦđợǉǦƸƽƕǃƼǦǉƶǦƓǉǦǁắǂ,ǦƸǊốƾǦƸƖǃƼǦǃƼườƾǦƸƚǦǉƽểǦởǦǁạƾǦƸƽẳǃƼǦđượƸǦǂấǓǦƶƾ.ǦƩƐǓ,ǦƸƑƸǦǃƼươƾǦǃƚƾǦǍƺǂǦǉƽờƾǦƼƾƶǃǦǉƽửǦǋƾệƸǦǃƐǓǦǇốǉǦƸǊộƸǦǅƽảƾǦǁƐǂǦǃƽữǃƼǦƼƔǦǉƽế?",
    ["咱们先约法三章，不许内斗，不许互相使绊子！有事一起扛，有错一起担！"] = "ƞƽƕǃƼǦǉƶǦƽƃǓǦướƸǦǅƽƑǅǦǉƶǂǦƸƽươǃƼ,ǦǀƽƇǃƼǦđượƸǦǃộƾǦđấǊ,ǦǀƽƇǃƼǦđượƸǦǃƼƑǃƼǦƸƽƁǃǦǃƽƶǊ!ǦƞƚǦƸƽǊǓệǃǦƸƖǃƼǦƼƑǃƽ,ǦƸƚǦǁỗƾǦƸƖǃƼǦƸƽịǊ!",
    ["不成……"] = "ƦƽƇǃƼǦǉƽƐǃƽ...",
    ["问题。"] = "ǋấǃǦđề.",
    ["内廷和事佬，知道不？不知道也没关系，横竖是个当官的。"] = "ƣƛƶǦǈựǦǁƃǄǦǉǇǄǃƼǦǃộƾǦđƔǃƽ,ǦƷƾếǉǦǀƽƇǃƼ?ǦƦƽƇǃƼǦƷƾếǉǦƸũǃƼǦƸƽẳǃƼǦǈƶǄ,ǦǤƖǦƼƔǦƸũǃƼǦǁƐǦǂộǉǦƸƽứƸǦǆǊƶǃ.",
    ["入宫女史，十不存一……"] = "ƩữǦǈửǦǋƐǄǦƸǊǃƼ,ǦǂườƾǦǀƽƇǃƼǦƸƛǃǦǂộǉ...",
    ["一人多岗，一岗多能，竟也勉强可以运转……"] = "ƨộǉǦǃƼườƾǦǃƽƾềǊǦǋịǦǉǇƓ,ǦǂộǉǦǋịǦǉǇƓǦǃƽƾềǊǦǃăǃƼǦǁựƸ,ǦǉƽếǦǂƐǦƸũǃƼǦƸƚǦǉƽểǦǂƾễǃǦƸưỡǃƼǦǋậǃǦƽƐǃƽ...",
    ["只是苦了各位姐妹们了……撑过这个冬日，再招些人来便能好上不少。"] = "ƞƽỉǦǁƐǦǀƽổǦƸƽǄǦƸƑƸǦǉỷǦǂǊộƾǦǇồƾ...ǦƼắǃƼǦƼượǃƼǦǆǊƶǦǂƖƶǦđƇǃƼǦǃƐǓ,ǦƸƽƾƙǊǦǂộǦǉƽƙǂǦǃƼườƾǦǉƽƔǦǈẽǦǀƽƑǦƽơǃǦǃƽƾềǊ.",
    ["军士饶命！小的什么都没做啊！"] = "ƬǊƁǃǦǈĩǦǉƽƶǦǂạǃƼ!ǦǥƾểǊǦǃƽƁǃǦƸƽưƶǦǁƐǂǦƼƔǦƸả!",
    ["哎哟！军士您这是要杀谁啊？小的腿都要吓软了。"] = "ÁƾǦƸƽƐ!ǦƬǊƁǃǦǈĩǦǃƼƐƾǦđịǃƽǦƼƾếǉǦƶƾǦǉƽế?ǦƞƽƁǃǦǉƾểǊǦǃƽƁǃǦǈắǅǦǃƽũǃǦǇƶǦǋƔǦǈợǦǇồƾ.",
    ["咦？方才是看到哪里了？嗨呀，无妨无妨，随处看之！"] = "Ơ?ǦƱừƶǦǃƃǓǦǍƺǂǦđếǃǦđƁǊǦǇồƾǦǃƽỉ?ǦƣƶƾǏ,ǦǀƽƇǃƼǦǈƶǄǦǀƽƇǃƼǦǈƶǄ,ǦƸứǦǍƺǂǦǉƖǓǦƈǦǉƽƇƾ!",
    ["不必从书中寻得参详之处，只是寻常读书、看字，可真是享受啊……"] = "ƦƽƇǃƼǦƸầǃǦǉƔǂǦǀƾếǂǦƸƽỗǦǉƽƶǂǦǀƽảǄǦǉǇǄǃƼǦǈƑƸƽ,ǦƸƽỉǦǁƐǦđọƸǦǈƑƸƽ,ǦǍƺǂǦƸƽữǦƷƔǃƽǦǉƽườǃƼǦǉƽƇƾ,ǦǆǊảǦǉƽựƸǦǁƐǦǂộǉǦǈựǦƽưởǃƼǦǉƽụǦǂƐ...",
    ["你也不妨坐下来，任翻一页，便如此过一冬日……"] = "ƩƼươƾǦƸũǃƼǦǃƙǃǦǃƼồƾǦǍǊốǃƼ,ǦǁậǉǦđạƾǦǂộǉǦǉǇƶǃƼ,ǦƸứǦǉƽếǦǂƐǦǆǊƶǦǂộǉǦǃƼƐǓǦǂƖƶǦđƇǃƼ...",
    ["我就不了，你且慢慢享受。"] = "ǥƶǦǉƽƔǦǉƽƇƾǦǋậǓ,ǦǃƼươƾǦƸứǦǉƽǄǃƼǦǉƽảǦǂƐǦǉậǃǦƽưởǃƼ.",
    ["这一卷总算是校对完了……你说咱们这般没日没夜的熬，等到书成之日，能赏多少？"] = "ƬǊǓểǃǦǃƐǓǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦƽƾệǊǦđốƾǦǍǄǃƼǦǇồƾ...ǦƩƼươƾǦǃƚƾǦǍƺǂǦƸƽƕǃƼǦǉƶǦǉƽứƸǦđƙǂǦǉƽứƸǦƽƇǂǦǉƽếǦǃƐǓ,ǦđợƾǦđếǃǦǃƼƐǓǦǈƑƸƽǦƽǄƐǃǦǉƽƐǃƽ,ǦǈẽǦđượƸǦƷƶǃǦǉƽưởǃƼǦƷƶǄǦǃƽƾƙǊ?",
    ["想这些，不如先把这行“断罪无正条” của 注疏补上，天亮前还得呈上去呢。"] = "ƩƼƽĩǦǂấǓǦǉƽứǦđƚ,ǦƸƽẳǃƼǦƷằǃƼǦǂƶǊǦƸƽƚǃƼǦƷổǦǈǊǃƼǦǤƛǃƼǦƸƽƕǦƼƾảƾǦ\"đǄạǃǦǉộƾǦǋƇǦƸƽƓǃƽǦđƾềǊ\"ǦǃƐǓǦđƾ,ǦǉǇướƸǦǀƽƾǦǉǇờƾǦǈƑǃƼǦƸƛǃǦǅƽảƾǦǉǇƔǃƽǦǁƙǃǦđấǓ.",
    ["军士莫不是眼花了？把我当成歹人了？"] = "ƬǊƁǃǦǈĩǦƸƽẳǃƼǦǁẽǦƽǄƶǦǂắǉǦǇồƾ?ǦƧạƾǦƸǄƾǦǉƶǦǉƽƐǃƽǦǀẻǦƼƾƶǃǦǈƶǄ?",
    ["武德司虽有职责，但对我等动武，恐怕不合规矩吧？"] = "ƱũǦĐứƸǦǥǓǦǉǊǓǦƸƚǦƸƽứƸǦǉǇƑƸƽ,ǦǃƽưǃƼǦđộǃƼǦǋƅǦǋớƾǦƷọǃǦǉƶ,ǦƺǦǁƐǦǀƽƇǃƼǦƽợǅǦǆǊǓǦƸủǦđƁǊǦǃƽỉ?",
    ["宫门已闭，若无手谕，禁止入内！"] = "ƞǊǃƼǦǂƇǃǦđƃǦđƚǃƼ,ǦǃếǊǦǀƽƇǃƼǦƸƚǦǉƽủǦǤụ,ǦƸấǂǦđượƸǦǋƐǄǦǉǇǄǃƼ!",
    ["大雪兆丰年……好兆头，好兆头啊！"] = "ĐạƾǦǉǊǓếǉǦǉǇƾệǊǦǅƽǄǃƼǦǃƾƙǃ...ǦđƾềǂǦǁƐǃƽ,ǦđƕǃƼǦǁƐǦđƾềǂǦǁƐǃƽ!",
    ["殿门已闭，若无手谕，禁止入内！"] = "ĐƾệǃǦǂƇǃǦđƃǦđƚǃƼ,ǦǃếǊǦǀƽƇǃƼǦƸƚǦǉƽủǦǤụ,ǦƸấǂǦđượƸǦǋƐǄǦǉǇǄǃƼ!",
    ["自然，你的精神头，定能感染这些姑娘们。"] = "ǥựǦǃƽƾƙǃǦǇồƾ,ǦǉƾǃƽǦǉƽầǃǦƸủƶǦǃƼươƾǦǃƽấǉǦđịǃƽǦƸƚǦǉƽểǦǁƁǓǦǁƶǃǦǈƶǃƼǦđƑǂǦƸƇǦǃươǃƼǦǃƐǓ.",
    ["宫女们&主角"] = "ƞƑƸǦƸǊǃƼǦǃữǦ&ǦƞƽủǦǃƽƁǃ",
    ["不错，我果然没看错，你确实是最关键的一声。"] = "ƦƽƑǦǁắǂ,ǦǉƶǦǆǊảǦǃƽƾƙǃǦǀƽƇǃƼǦǃƽƔǃǦǁầǂ,ǦǃƼươƾǦđƕǃƼǦǁƐǦǉƾếǃƼǦƽƇǦǂấǊǦƸƽốǉǦǃƽấǉ.",
    ["何止啊……我看这宫里头，每个人的一声都很关键！"] = "ĐƁǊǦƸƽỉǦƸƚǦǉƽế...ǦǥƶǦǉƽấǓǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓ,ǦǉƾếǃƼǦƽƇǦƸủƶǦǂỗƾǦǃƼườƾǦđềǊǦǇấǉǦǂấǊǦƸƽốǉ!",
    ["哎，大哥，里面这是在准备什么宴会啊？"] = "ƩƐǓ,ǦđạƾǦƸƶ,ǦƷƙǃǦǉǇǄǃƼǦđƶǃƼǦƸƽǊẩǃǦƷịǦǓếǃǦǉƾệƸǦƼƔǦǉƽế?",
    ["这事说来就长了，那天，俺就在这儿转悠，哦不，巡逻！正正好见着官家在前头门口，好似同什么人说话，哎呀，那可是官家！我这好奇心，挠地一下……"] = "ƞƽǊǓệǃǦǃƐǓǦǃƚƾǦǇƶǦǉƽƔǦǤƐƾǦǁắǂ,ǦƽƇǂǦđƚ,ǦǉƶǦđƶǃƼǦǁượǃǦǁờǦởǦđƁǓ,ǦƐǦǀƽƇǃƼ,ǦǉǊầǃǦǉǇƶ!ǦƱừƶǦǋặǃǦǉǇƇǃƼǦǉƽấǓǦƬǊƶǃǦƢƾƶǦởǦƸửƶǦǅƽƓƶǦǉǇướƸ,ǦƽƔǃƽǦǃƽưǦđƶǃƼǦǃƚƾǦƸƽǊǓệǃǦǋớƾǦƶƾǦđƚ,ǦƑƾǦƸƽƐ,ǦđƚǦǁƐǦƬǊƶǃǦƢƾƶǦđấǓ!ǦƞƑƾǦǉƓǃƽǦǉƛǦǂƛǦƸủƶǦǉƶǦǃƚǦƸứǦƸƐǄǦǍƗ...",
    ["等等等等，大哥，前面的咱先跳过，这到底是个什么宴？"] = "ƦƽǄƶǃǦǀƽǄƶǃǦǀƽǄƶǃ,ǦđạƾǦƸƶ,ǦǅƽầǃǦǉǇướƸǦƸƽƕǃƼǦǉƶǦƷỏǦǆǊƶǦđƾ,ǦđƁǓǦǇốǉǦƸǊộƸǦǁƐǦǓếǃǦǉƾệƸǦƼƔ?",
    ["恁咋比俺还心急，中中中，俺说俺说，就那天俺偷偷听着勒，叫、叫什么曲宴！"] = "ƮƶǄǦǃƼươƾǦƸƛǃǦǃƇǃǦǃƚǃƼǦƽơǃǦƸảǦǉƶǦǉƽế,ǦđượƸǦđượƸǦđượƸ,ǦǉƶǦǃƚƾǦǉƶǦǃƚƾ,ǦƽƇǂǦđƚǦǉƶǦǃƼƽƺǦǁƗǃǦđượƸ,ǦƼọƾǦǁƐ...ǦƼọƾǦǁƐǦƦƽƕƸǦǓếǃ!",
    ["说是给俺老大们读读书，认认字开滴。"] = "ƩƚƾǦǁƐǦđểǦƸƽǄǦǂấǓǦđạƾǦƸƶǦƸủƶǦǉƶǦđọƸǦǈƑƸƽ,ǦǃƽậǃǦǂặǉǦƸƽữǦđấǓ.",
    ["就是不知道为啥，老大几个看着都不得劲……"] = "ƞƽỉǦǁƐǦǀƽƇǃƼǦƷƾếǉǦǉạƾǦǈƶǄ,ǦǂấǓǦǋịǦđạƾǦƸƶǦǉǇƇǃƼǦƸứǦǃƽưǦǀƽƇǃƼǦđượƸǦǉƽǄảƾǦǂƑƾǦƸƽǄǦǁắǂ...",
    ["你也要帮他练练手？"] = "ƩƼươƾǦƸũǃƼǦǂǊốǃǦƼƾƕǅǦƽắǃǦǁǊǓệǃǦǉƶǓǦǃƼƽềǦǈƶǄ?",
    ["快来快来，教他些技巧诀窍，好让此人在曲宴里大展身手。"] = "ƨƶǊǦđếǃǦđƁǓ,ǦǤạǓǦƽắǃǦƸƽƕǉǦǀỹǦǍảǄǦƷƓǦǆǊǓếǉ,ǦđểǦǃƼườƾǦǃƐǓǦƸƚǦǉƽểǦđạƾǦǉǇƾểǃǦǉƽƁǃǦǉƽủǦǉǇǄǃƼǦƦƽƕƸǦǓếǃ.",
    ["人啊，果然得多做做活。"] = "ƞǄǃǦǃƼườƾǦǉƶǦđƕǃƼǦǁƐǦǅƽảƾǦǁƐǂǦǋƾệƸǦǃƽƾềǊǦǂộǉǦƸƽƕǉ.",
    ["平日里大家怎地就闲得住呢？"] = "ƩƼƐǓǦǉƽườǃƼǦǈƶǄǦǂọƾǦǃƼườƾǦǁạƾǦƸƚǦǉƽểǦǃƼồƾǦǀƽƇǃƼǦđượƸǦǃƽỉ?",
    ["这么晚了，你还不回去休息么？"] = "ƨǊộǃǦǉƽếǦǃƐǓǦǇồƾ,ǦǃƼươƾǦƸƛǃǦƸƽưƶǦǋềǦǃƼƽỉǦǃƼơƾǦǈƶǄ?",
    ["哈欠……我得抓紧把这段时间在庆寿殿算的章子重新过一遍，免得到时候递上去又被判官一顿批……"] = "ƪƑǅ...ǦǥƶǦǅƽảƾǦǂƶǊǦƸƽƚǃƼǦǍƺǂǦǁạƾǦƸƑƸǦǉấǊǦƸƽươǃƼǦđƃǦǉƓǃƽǦǉǄƑǃǦởǦƦƽƑǃƽǦǥƽọǦĐƾệǃǦǉƽờƾǦƼƾƶǃǦǆǊƶ,ǦǉǇƑǃƽǦđểǦǁƕƸǦǉǇƔǃƽǦǁƙǃǦǁạƾǦƷịǦǅƽƑǃǦǆǊƶǃǦǆǊởǦǉǇƑƸƽǦǂộǉǦǉǇậǃ...",
    ["哈欠……四百八十三……这儿是，七百二……那就是……一千，一千二……"] = "ƪƑǅ...ǦƷốǃǦǉǇăǂǦǉƑǂǦǂươƾǦƷƶ...ǦƸƽỗǦǃƐǓǦǁƐǦƷảǓǦǉǇăǂǦƽƶƾ...ǦǋậǓǦǁƐ...ǦǂộǉǦǃƼƐǃ,ǦǂộǉǦǃƼƐǃǦƽƶƾ...",
    ["天下之生灵，虽终归尘土，然皆有盛若夏花之时。今吾所择，虽不足撼千秋，犹可易旦夕。"] = "ƮƾǃƽǦǁƾǃƽǦǉǇǄǃƼǦǉƽƾƙǃǦƽạ,ǦǉǊǓǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦǋềǦǋớƾǦƸƑǉǦƷụƾ,ǦǃƽưǃƼǦđềǊǦƸƚǦǁƕƸǦǇựƸǦǇỡǦǃƽưǦƽǄƶǦǂƖƶǦƽạ.ǦƩƽữǃƼǦƼƔǦǉƶǦƸƽọǃǦƽƇǂǦǃƶǓ,ǦǉǊǓǦǀƽƇǃƼǦđủǦǁƐǂǦǁƶǓǦƸƽǊǓểǃǦǉƽƾƙǃǦǉƽǊ,ǦǃƽưǃƼǦǋẫǃǦƸƚǦǉƽểǦǉƽƶǓǦđổƾǦǉǇǄǃƼǦǈớǂǦǉốƾ.",
    ["唉……本来识文断字的也不多，进出的宫人也请遍了，写不出就是写不出，实在没法子……"] = "ƣầǓ...ǦǋốǃǦǤĩǦǃƼườƾǦƷƾếǉǦƸƽữǦƸũǃƼǦǀƽƇǃƼǦǃƽƾềǊ,ǦƸǊǃƼǦǃƽƁǃǦǇƶǦǋƐǄǦƸũǃƼǦđƃǦǉƽỉǃƽǦƸầǊǦƽếǉǦǁượǉǦǇồƾ,ǦǋƾếǉǦǀƽƇǃƼǦđượƸǦǁƐǦǀƽƇǃƼǦđượƸ,ǦǉƽậǉǦǈựǦƽếǉǦƸƑƸƽǦǇồƾ...",
    ["这么多桃符，究竟何时才能写完交差？"] = "ƝƶǄǦǃƽƾƙǊǦđƐǄǦǅƽƖǦǉƽếǦǃƐǓ,ǦǇốǉǦƸǊộƸǦƷƶǄǦƼƾờǦǂớƾǦǋƾếǉǦǍǄǃƼǦđểǦƷƐǃǦƼƾƶǄǦđƁǓ?",
    ["这儿，就是这些桃符——都得一句句接上才行！"] = "ĐƁǓ,ǦƸƽƓǃƽǦǁƐǦǃƽữǃƼǦđƐǄǦǅƽƖǦǃƐǓǦ——ǦđềǊǦǅƽảƾǦǃốƾǦǉƾếǅǦǉừǃƼǦƸƁǊǦǂớƾǦđượƸ!",
    ["汪汪侠"] = "ǕƇǃƼǦǕƇǃƼǦƣƾệǅ",
    ["秘史……诶嘿嘿……"] = "ƝƓǦǈử...ǦƽƙǦƽƙǦƽƙ...",
    ["他们这样这样……不知天地为何物了……"] = "ƣọǦƸứǦǉƽếǦǃƐǓǦǉƽếǦǃƐǓ...ǦƸƽẳǃƼǦƸƛǃǦƷƾếǉǦǉǇờƾǦđấǉǦǁƐǦƼƔǦǃữƶǦǇồƾ...",
    ["……怎么是斗蛐蛐！"] = "...ǦƮƶǄǦǁạƾǦǁƐǦƸƽọƾǦǤế!",
    ["秘史总是这样，但我又忍不住看下去……嘿嘿，香蒲真厉害呀！"] = "ƝƓǦǈửǦǁƕƸǦǃƐǄǦƸũǃƼǦǋậǓ,ǦǃƽưǃƼǦǉƶǦǁạƾǦǀƽƇǃƼǦǀƔǂǦđượƸǦǂƐǦǍƺǂǦǉƾếǅ...ǦƽƔǦƽƔ,ǦƣươǃƼǦƝồǦǉƽậǉǦǁợƾǦƽạƾǦǆǊƑǦđƾ!",
    ["宫廷秘史，密不外传！香蒲这几年在宫中遇到的奇人奇事，全记在上面了！"] = "ƞǊǃƼǦđƔǃƽǦƷƓǦǈử,ǦǂậǉǦǀƽƇǃƼǦǉǇǊǓềǃǦǇƶǦǃƼǄƐƾ!ǦƩƽữǃƼǦƸƽǊǓệǃǦǀỳǦǁạǦǂƐǦƣươǃƼǦƝồǦƼặǅǦǉǇǄǃƼǦƸǊǃƼǦǂấǓǦǃăǂǦǃƶǓǦđềǊǦƼƽƾǦƽếǉǦởǦǉǇƙǃǦđƚǦǇồƾ!",
    ["不过听说香蒲已经在写下一个故事了，也不知道什么时候能写好，真想看啊！"] = "ƩƽưǃƼǦǃƼƽƺǦǃƚƾǦƣươǃƼǦƝồǦđƶǃƼǦǋƾếǉǦƸƁǊǦƸƽǊǓệǃǦǉƾếǅǦǉƽƺǄǦǇồƾ,ǦƸũǃƼǦǀƽƇǃƼǦƷƾếǉǦƷƶǄǦƼƾờǦǂớƾǦǋƾếǉǦǍǄǃƼ,ǦǉƽậǉǦǂǊốǃǦǍƺǂǦǆǊƑ!",
    ["缩减预算，人力不足……如何是好……"] = "ƞắǉǦƼƾảǂǦǤựǦǉǄƑǃ,ǦǃƽƁǃǦǁựƸǦǉƽƾếǊǦƽụǉ...ǦǅƽảƾǦǁƐǂǦǈƶǄǦđƁǓ...",
    ["风声鹤唳！草木皆兵！确有此事！"] = "ƫƽǄǃƼǦǉƽƶǃƽǦƽạƸǦǁệ!ǦǥƽảǄǦǂộƸǦƼƾƶƾǦƷƾǃƽ!ǦƬǊảǦƸƚǦƸƽǊǓệǃǦǃƐǓ!",
    ["……不过前朝宫女数目众多，若是能趁此机会，让宫中宫女自愿出宫、了却心愿……"] = "...ǦǥǊǓǦǃƽƾƙǃǦƸǊǃƼǦǃữǦǉƾềǃǦǉǇƾềǊǦǈốǦǁượǃƼǦđƇǃƼǦđảǄ,ǦǃếǊǦƸƚǦǉƽểǦǃƽƁǃǦƸơǦƽộƾǦǃƐǓ,ǦđểǦƸǊǃƼǦǃữǦǉǇǄǃƼǦƸǊǃƼǦǉựǦǃƼǊǓệǃǦǍǊấǉǦƸǊǃƼ,ǦƽǄƐǃǦǉƽƐǃƽǦǉƁǂǦǃƼǊǓệǃ...",
    ["原来，真的饿极了的时候，前胸，真的能贴到后背……"] = "ƣƚƶǦǇƶ,ǦǁƕƸǦǉƽậǉǦǈựǦđƚƾǦđếǃǦƸựƸǦđƾểǂ,ǦǃƼựƸǦƑǄǦǉƽậǉǦǈựǦƸƚǦǉƽểǦǤƑǃǦǈƑǉǦǋƐǄǦǁưǃƼ...",
    ["是食物的香气！啊！哪路神仙给我送饭来了！太好了，我不会被饿死了！"] = "ƧƐǦƽươǃƼǦǉƽơǂǦƸủƶǦǉƽứƸǦăǃ!ǦƜ!ǦƱịǦǉƽầǃǦǉƾƙǃǦǅƽươǃƼǦǃƐǄǦǂƶǃƼǦƸơǂǦđếǃǦƸƽǄǦǉƶǦǋậǓ!ǦǥốǉǦǆǊƑǦǇồƾ,ǦǉƶǦǈẽǦǀƽƇǃƼǦƷịǦƸƽếǉǦđƚƾǦǃữƶ!",
    ["刚坐了一趟观光鸡，既稳当，又方便，还有烟花看咧，大伙快去试试看！"] = "ƱừƶǦǃƼồƾǦǉƽửǦƢƐǦǥƽƶǂǦƬǊƶǃǦǂộǉǦƸƽǊǓếǃ,ǦǋừƶǦǋữǃƼǦǋƐǃƼǦǋừƶǦǉƽǊậǃǦǉƾệǃ,ǦǁạƾǦƸƛǃǦđượƸǦǍƺǂǦǅƽƑǄǦƽǄƶǦǃữƶ,ǦǂọƾǦǃƼườƾǦǂƶǊǦđƾǦǉƽửǦǍƺǂ!",
    ["刘骋"] = "ƧưǊǦƮƓǃƽ",
    ["你方才许愿了吗？听闻在烟花之下许的愿望……都会实现的。"] = "ƩƼươƾǦǋừƶǦǇồƾǦđƃǦƽứƶǦǃƼǊǓệǃǦƸƽưƶ?ǦƩƼƽƺǦǃƚƾǦđƾềǊǦướƸǦǃƼǊǓệǃǦǤướƾǦƑǃƽǦǅƽƑǄǦƽǄƶ...ǦđềǊǦǈẽǦǉƽƐǃƽǦƽƾệǃǦǉƽựƸ.",
    ["张驰"] = "ǥǇươǃƼǦǥǇƔ",
    ["大家快看……有什么东西从天上飞过去了！好厉害……"] = "ƨọƾǦǃƼườƾǦǂƶǊǦǃƽƔǃǦǀƔƶ...ǦƸƚǦƸƑƾǦƼƔǦđƚǦǋừƶǦƷƶǓǦǆǊƶǦǉǇƙǃǦǉǇờƾ!ǦƧợƾǦƽạƾǦǉƽậǉ...",
    ["陈骐"] = "ǥǇầǃǦƦỳ",
    ["我瞅这马也不是真的啊……咋也能动起来呢？真是奇了怪了，莫非真有神通不成？"] = "ǥƶǦǉƽấǓǦƸǄǃǦǃƼựƶǦǃƐǓǦƸũǃƼǦƸƽẳǃƼǦǅƽảƾǦđồǦǉƽậǉ...ǦǈƶǄǦǂƐǦƸũǃƼǦƸửǦđộǃƼǦđượƸǦǃƽỉ?ǦĐƕǃƼǦǁƐǦǀỳǦǆǊƑƾ,ǦƸƽẳǃƼǦǁẽǦƸƚǦǉƽầǃǦǉƽƇǃƼǦǉƽậǉǦǈƶǄ?",
    ["葛骥"] = "ƞƑǉǦƦƈ",
    ["今天出来玩不用着急，坐稳当点，可别摔着了。"] = "ƣƇǂǦǃƶǓǦđƾǦƸƽơƾǦǀƽƇǃƼǦƸầǃǦǋộƾǦǋƐǃƼ,ǦǃƼồƾǦƸƽǄǦǋữǃƼǦǋƐǄ,ǦǀẻǄǦƷịǦǃƼƃǦđấǓ.",
    ["姚发财"] = "ƴƙǊǦƫƽƑǉǦǥƐƾ",
    ["烟花，有烟花！大家快往上头看哇！"] = "ƫƽƑǄǦƽǄƶ,ǦƸƚǦǅƽƑǄǦƽǄƶǦǀƔƶ!ǦƨọƾǦǃƼườƾǦǂƶǊǦǃƽƔǃǦǁƙǃǦǉǇƙǃǦđƾ!",
    ["俞骁"] = "ǝǊǦƦƾƙǊ",
    ["咳……咳……出来逛一逛，看看新鲜玩意，心里头也舒坦了不少。"] = "Ʀƽụ...Ǧǀƽụ...ǦǇƶǦǃƼǄƐƾǦǤạǄǦǂộǉǦƸƽƕǉ,ǦǍƺǂǦǂấǓǦǂƚǃǦđồǦǂớƾǦǁạǦǃƐǓ,ǦǉǇǄǃƼǦǁƛǃƼǦƸũǃƼǦǉƽấǓǦǉƽưǦǉƽƑƾǦƽơǃǦǃƽƾềǊ.",
    ["丁胜意"] = "ĐƾǃƽǦǥƽắǃƼǦÝ",
    ["爹爹快看，我要坐这个！"] = "ĐƾƙǦđƾƙǦǂƶǊǦǃƽƔǃǦǀƔƶ,ǦƸǄǃǦǂǊốǃǦǃƼồƾǦƸƑƾǦǃƐǓ!",
    ["小新"] = "ǥƾểǊǦǥƁǃ",
    ["大姐姐，是我先来的，可以让我先坐吗？"] = "ĐạƾǦǉỷǦǉỷ,ǦǁƐǦƺǂǦđếǃǦǉǇướƸ,ǦƸƚǦǉƽểǦđểǦƺǂǦǃƼồƾǦǉǇướƸǦǀƽƇǃƼ?",
    ["小岁"] = "ǥƾểǊǦǥǊế",
    ["好听好听，就是空气里好像有股奇怪的味道……"] = "ƣƶǓǦǆǊƑǦƽƶǓǦǆǊƑ,ǦƸƚǦđƾềǊǦǉǇǄǃƼǦǀƽƇǃƼǦǀƽƓǦƽƔǃƽǦǃƽưǦƸƚǦǂƖƾǦǋịǦƼƔǦđƚǦǀỳǦǁạ...",
    ["不要急不要急，一个个来。"] = "ĐừǃƼǦǋộƾǦđừǃƼǦǋộƾ,ǦǉừǃƼǦǃƼườƾǦǂộǉǦǃƐǄ.",
    ["博乐"] = "ƝƑƸǦƧạƸ",
    ["希望坐一趟千里马，娘亲的病可以快些好起来。"] = "ƣǓǦǋọǃƼǦǃƼồƾǦǥƽƾƙǃǦƧƈǦƨƃǦǂộǉǦƸƽǊǓếǃ,ǦƷệǃƽǦƸủƶǦǂẫǊǦǉƽƁǃǦƸƚǦǉƽểǦǂƶǊǦƸƽƚǃƼǦƷƔǃƽǦǅƽụƸ.",
    ["小快"] = "ǥƾểǊǦƦƽǄƑƾ",
    ["等我长大以后，我也要发明这样好玩的机关！"] = "ĐợƾǦǈƶǊǦǀƽƾǦƺǂǦǁớǃǦǁƙǃ,ǦƺǂǦƸũǃƼǦǈẽǦǅƽƑǉǦǂƾǃƽǦǇƶǦǃƽữǃƼǦƸơǦǆǊƶǃǦǋǊƾǦǃƽộǃǦǃƽưǦǉƽếǦǃƐǓ!",
    ["小乐"] = "ǥƾểǊǦƧạƸ",
    ["我没看错吧？彩虹，是彩虹！平日只有下雨天能见到的彩虹，这儿能看到好多回！"] = "ǥƶǦǀƽƇǃƼǦǃƽƔǃǦǃƽầǂǦƸƽứ?ǦƞầǊǦǋồǃƼ,ǦǁƐǦƸầǊǦǋồǃƼǦǀƔƶ!ǦƝƔǃƽǦǉƽườǃƼǦƸƽỉǦǉƽấǓǦǁƕƸǦǉǇờƾǦǂưƶ,ǦǂƐǦởǦđƁǓǦǁạƾǦđượƸǦǉƽấǓǦƷƶǄǦǃƽƾƙǊǦǁầǃ!",
    ["齐骅"] = "ǥềǦƣǄƶ",
    ["这彩虹毯走得那叫一个畅快……一边走红毯，一边还有音乐响起，真是不可思议……"] = "ĐƾǦǉǇƙǃǦƸƑƾǦǉƽảǂǦƸầǊǦǋồǃƼǦǃƐǓǦǉƽậǉǦǁƐǦǈảǃƼǦǀƽǄƑƾ...ǦǋừƶǦƷướƸǦđƾǦǉǇƙǃǦǉƽảǂǦđỏ,ǦǋừƶǦƸƚǦƁǂǦǃƽạƸǦǋƶǃƼǦǁƙǃ,ǦđƕǃƼǦǁƐǦǀƽƇǃƼǦǉƽểǦǉƾǃǦǃổƾ...",
    ["韩骧"] = "ƣƐǃǦǥươǃƼ",
    ["这一匹，叫发财，坐上去就是马上发财。"] = "ƞǄǃǦǃƐǓǦǉƙǃǦǁƐǦƫƽƑǉǦǥƐƾ,ǦǃƼồƾǦǁƙǃǦǁƐǦǂƃǦǉƽượǃƼǦǅƽƑǉǦǉƐƾǦ(ƼƾƐǊǦǃƼƶǓǦǁậǅǦǉứƸ).",
    ["这一匹，叫成功，坐上去就是……"] = "ƞǄǃǦǃƐǓǦǉƙǃǦǁƐǦǥƽƐǃƽǦƞƇǃƼ,ǦǃƼồƾǦǁƙǃǦǁƐ...",
    ["马上成功！对吧？"] = "ƨƃǦǉƽượǃƼǦǉƽƐǃƽǦƸƇǃƼǦ(ǉƽƐǃƽǦƸƇǃƼǦǃƼƶǓ)!ǦĐƕǃƼǦǀƽƇǃƼ?",
    ["那这一匹上面，是……一对象？马上有……对象？"] = "ƱậǓǦǉǇƙǃǦƸǄǃǦǃƐǓǦǁƐ...ǦǂộǉǦđốƾǦǉượǃƼǦ(ǂộǉǦđƇƾǦǋǄƾ)?ǦƨƃǦǉƽượǃƼǦƽữǊ...ǦđốƾǦǉượǃƼǦ(ƸƚǦǃƼườƾǦǓƙǊǦǃƼƶǓ)?",
    ["咦，对象是何物？我原本想的是，马上立象来着……哎，我的研究能不能立项啊。"] = "Ủƶ,ǦđốƾǦǉượǃƼǦǁƐǦƸƑƾǦƼƔ?ǦƱốǃǦǤĩǦǉƶǦđịǃƽǦƷụǃƼǦǁƐǦǂƃǦǉƽượǃƼǦǁậǅǦǉượǃƼǦ(đặǉǦƸǄǃǦǋǄƾǦǁƙǃǦǃƼựƶ)...ǦƜƾǦǤƶ,ǦǃƼƽƾƙǃǦƸứǊǦƸủƶǦǉƶǦǁƾệǊǦƸƚǦǉƽểǦǁậǅǦƽạǃƼǦ(ǅƽƙǦǤǊǓệǉǦǤựǦƑǃ)ǦǀƽƇǃƼǦđƁǓ.",
    ["墨、墨门千机，童叟无欺——"] = "ƨặƸ...ǦƨặƸǦƨƇǃǦǥƽƾƙǃǦƞơ,ǦƼƾƐǦǉǇẻǦǀƽƇǃƼǦƼạǉ——",
    ["兼爱非攻，不用……上、上工？"] = "ƦƾƙǂǦƑƾǦǅƽƾǦƸƇǃƼ,ǦǀƽƇǃƼǦƸầǃ...ǦǉƽượǃƼ...ǦǉƽượǃƼǦƸƇǃƼǦ(đƾǦǁƐǂ)?",
    ["冯大哥！你也来开封了？新岁快乐啊！"] = "ƫƽƖǃƼǦđạƾǦƸƶ!ǦƣǊǓǃƽǦƸũǃƼǦđếǃǦƦƽƶƾǦƫƽǄǃƼǦǈƶǄ?ǦǥƁǃǦǍǊƁǃǦǋǊƾǦǋẻ!",
    ["游侠，新岁好啊！我……我也没想到，刚在山里忙完一阵，长老又把我派下山了。"] = "ǝǊǦƽƾệǅ,ǦǃăǂǦǂớƾǦǉốǉǦǁƐǃƽ!Ǧǥƶ...ǦǉƶǦƸũǃƼǦǀƽƇǃƼǦǃƼờǦǉớƾ,ǦǋừƶǦǂớƾǦƷậǃǦǇộǃǦǉǇǄǃƼǦǃƕƾǦǍǄǃƼǦǂộǉǦƽồƾ,ǦǥǇưởǃƼǦǁƃǄǦǁạƾǦǅƽƑƾǦǉƶǦǍǊốǃƼǦǃƕƾ.",
    ["怎么只有你一个人来山外过年？"] = "ƮƶǄǦƸƽỉǦƸƚǦǂƔǃƽǦƽǊǓǃƽǦǇƶǦǃƼǄƐƾǦǃƕƾǦăǃǦǥếǉ?",
    ["本来是有许多人报名的，但……大家年末都忙着写研究报告……"] = "ƱốǃǦǤĩǦƸƚǦǇấǉǦǃƽƾềǊǦǃƼườƾǦđăǃƼǦǀƈ,ǦǃƽưǃƼ...ǦƸǊốƾǦǃăǂǦƶƾǦǃấǓǦđềǊǦƷậǃǦǋƾếǉǦƷƑǄǦƸƑǄǦǃƼƽƾƙǃǦƸứǊ...",
    ["结果就只有我与另一位精通摇摇马的同道……幸好还有些在外游历的山门弟子，和这些机巧。"] = "ƦếǉǦǆǊảǦƸƽỉǦƸƚǦǉƶǦǋƐǦǂộǉǦǋịǦđồǃƼǦđạǄǦǉƾǃƽǦǉƽƇǃƼǦǃƼựƶǦƷậǅǦƷƙǃƽ...ǦƨƶǓǦǂƐǦǋẫǃǦƸƛǃǦǂộǉǦǈốǦđệǦǉửǦǈơǃǦǂƇǃǦđƶǃƼǦǤǊǦǁịƸƽǦƷƙǃǦǃƼǄƐƾ,ǦƸƖǃƼǦǋớƾǦǃƽữǃƼǦǂƑǓǦǂƚƸǦƸơǦǍảǄǦǃƐǓ.",
    ["这不还有我呢吗？对了，这些机巧看着新鲜……冯大哥，给我介绍介绍呗？"] = "ƞƽẳǃƼǦǅƽảƾǦƸƛǃǦƸƚǦđệǦƸảǦǈƶǄ?ǦĐƕǃƼǦǇồƾ,ǦǂấǓǦǂƚǃǦƸơǦǍảǄǦǃƐǓǦǉǇƇǃƼǦǂớƾǦǁạǦǆǊƑ...ǦƫƽƖǃƼǦđạƾǦƸƶ,ǦƼƾớƾǦǉƽƾệǊǦƸƽǄǦđệǦǂộǉǦƸƽƕǉǦđƾ?",
    ["啊，好，太好了……我正担心没人来问呢……你想听哪一个？我给你说！"] = "Ɯ,Ǧǉốǉ,ǦǉốǉǦǆǊƑ...ǦǥƶǦđƶǃƼǦǁǄǦǀƽƇǃƼǦƸƚǦƶƾǦđếǃǦƽỏƾǦđƁǓ...ǦĐệǦǂǊốǃǦǃƼƽƺǦƸƑƾǦǃƐǄ?ǦǥƶǦǃƚƾǦƸƽǄǦđệǦǃƼƽƺ!",
    ["嘿嘿……这是观光鸡。你认出来了吗，这可是我从咱们的继升鸡得来的灵感！"] = "ƣƔǦƽƔ...ǦđƁǓǦǁƐǦƢƐǦǥƽƶǂǦƬǊƶǃ.ǦĐệǦǃƽậǃǦǇƶǦǀƽƇǃƼ,ǦđƁǓǦƸƽƓǃƽǦǁƐǦǁƾǃƽǦƸảǂǦǉƶǦǁấǓǦđượƸǦǉừǦƸǄǃǦƢƐǦƦếǦǥƽăǃƼǦƸủƶǦƸƽƕǃƼǦǉƶǦđƚ!",
    ["只要一坐上去，它就能自己飞起来，还能带你看烟花呢！去樊楼那看可贵，来咱们这……不、不要钱！"] = "ƞƽỉǦƸầǃǦǃƼồƾǦǁƙǃ,ǦǃƚǦƸƚǦǉƽểǦǉựǦǂƔǃƽǦƷƶǓǦǁƙǃ,ǦƸƛǃǦđưƶǦđệǦđƾǦǍƺǂǦǅƽƑǄǦƽǄƶǦǃữƶ!ǦĐếǃǦƫƽƐǃǦƧƁǊǦǍƺǂǦǉƽƔǦđắǉǦǁắǂ,ǦđếǃǦƸƽỗǦƸƽƕǃƼǦǉƶ...ǦǀƽƇǃƼ...ǦǀƽƇǃƼǦǁấǓǦǉƾềǃ!",
    ["雀前辈，你也来啦？新岁快乐！"] = "ǥướƸǦǉƾềǃǦƷốƾ,ǦǃƼƐƾǦƸũǃƼǦǉớƾǦǈƶǄ?ǦǥƁǃǦǍǊƁǃǦǋǊƾǦǋẻ!",
    ["游侠，新岁好。我在开封游历许久，听闻今年有同道下山，便来瞧一瞧。"] = "ǝǊǦƽƾệǅ,ǦǃăǂǦǂớƾǦǉốǉǦǁƐǃƽ.ǦǥƶǦǤǊǦǃƼǄạǃǦởǦƦƽƶƾǦƫƽǄǃƼǦđƃǦǁƁǊ,ǦǃƼƽƺǦǃƚƾǦǃăǂǦǃƶǓǦƸƚǦđồǃƼǦđạǄǦǍǊốǃƼǦǃƕƾ,ǦƷƘǃǦǉớƾǦǍƺǂǦǉƽử.",
    ["山门的研究速度……比我想得还要再快一些。这些新奇物件，与我平日所见的奇物相比，也大有不同。"] = "ǥốƸǦđộǦǃƼƽƾƙǃǦƸứǊǦƸủƶǦǈơǃǦǂƇǃ...ǦƸƛǃǦǃƽƶǃƽǦƽơǃǦǉƶǦǉưởǃƼ.ǦƩƽữǃƼǦǂƚǃǦđồǦǉƁǃǦǀỳǦǃƐǓ,ǦǈǄǦǋớƾǦǀỳǦǋậǉǦǉƶǦǉƽườǃƼǦǉƽấǓ,ǦǆǊảǦǉƽựƸǦƸƚǦǈựǦǀƽƑƸǦƷƾệǉǦǇấǉǦǁớǃ.",
    ["奇物监的宝物胜在一个“奇”字，四海珍宝，无奇不有，令我眼界大开。"] = "ƝảǄǦǋậǉǦƸủƶǦƦỳǦƱậǉǦƢƾƑǂǦǉƽắǃƼǦởǦƸƽữǦ\"Ʀỳ\",ǦǉǇƁǃǦƷảǄǦƷốǃǦǅƽươǃƼ,ǦǀƽƇǃƼǦƼƔǦǀƽƇǃƼǦƸƚ,ǦǀƽƾếǃǦǉƶǦǂởǦǂƶǃƼǦǉầǂǦǂắǉ.",
    ["而我墨山道的发明则以“巧”为先，机关精巧，严丝合缝，一试便觉妙趣横生。"] = "ƨƐǦǅƽƑǉǦǂƾǃƽǦƸủƶǦƨặƸǦƮơǃǦĐạǄǦƸƽƕǃƼǦǉƶǦǁấǓǦƸƽữǦ\"ƳảǄ\"ǦǁƐǂǦđầǊ,ǦƸơǦǆǊƶǃǦǉƾǃƽǦǍảǄ,ǦǀƽớǅǦǃốƾǦǀƽƓǉǦǀƽƶǄ,ǦǉƽửǦǆǊƶǦǁƾềǃǦǉƽấǓǦǉƽƕǦǋịǦǋƇǦƸƖǃƼ.",
    ["哎呀，方才这红狮的“出洞”之势，略显急躁了。"] = "ÁƾǦƸƽƐ,ǦǉƽếǦ\"ǍǊấǉǦđộǃƼ\"ǦƸủƶǦƸǄǃǦǈưǦǉửǦđỏǦǋừƶǦǇồƾǦƸƚǦǅƽầǃǦƽơƾǦǃƇǃǦǃƚǃƼ.",
    ["甄昊学"] = "ƞƽƁǃǦƣạǄǦƣọƸ",
    ["古法讲究“三进三退”，以此示疑，红狮太急，少了韵味。"] = "ƞổǦǅƽƑǅǦƸƽƕǦǉǇọǃƼǦ\"ƷƶǦǉƾếǃǦƷƶǦǁƖƾ\"ǦđểǦƷƾểǊǦǉƽịǦǈựǦǃƼƽƾǦƽǄặƸ,ǦǈưǦǉửǦđỏǦǆǊƑǦƼấǅ,ǦǉƽƾếǊǦđƾǦǋậǃǦǋị.",
    ["甄兄所言极是，这狮舞八态，无一不是文章啊！"] = "ƞƽƁǃǦƽǊǓǃƽǦǃƚƾǦƸƽƓǦǅƽảƾ,ǦǉƑǂǦǉǇạǃƼǦǉƽƑƾǦƸủƶǦǂƕƶǦǈưǦǉửǦǃƐǓ,ǦǉǇạǃƼǦǉƽƑƾǦǃƐǄǦƸũǃƼǦđềǊǦǁƐǦǃƼƽệǦǉƽǊậǉǦƸả!",
    ["贾有文"] = "ƢƾảǦƣữǊǦƱăǃ",
    ["娘，以往舞狮都是一头，今年怎么成了两头，还打起来了？"] = "ƨẫǊǦǉƽƁǃ,ǦǉǇướƸǦǀƾƶǦǂƕƶǦǈưǦǉửǦƸƽỉǦƸƚǦǂộǉǦƸǄǃ,ǦǃăǂǦǃƶǓǦǈƶǄǦǁạƾǦǉƽƐǃƽǦƽƶƾǦƸǄǃ,ǦƸƛǃǦđƑǃƽǦǃƽƶǊǦǃữƶ?",
    ["小桃"] = "ǥƾểǊǦĐƐǄ",
    ["这定是有高人指点啊！若是平平淡淡地舞，大伙儿看一会就走了。"] = "ĐƁǓǦƸƽắƸǦƸƽắǃǦǁƐǦƸƚǦƸƶǄǦǃƽƁǃǦƸƽỉǦđƾểǂǦǇồƾ!ǦƩếǊǦƸƽỉǦǂƕƶǦƷƔǃƽǦǉƽườǃƼ,ǦǂọƾǦǃƼườƾǦǍƺǂǦǂộǉǦǁƑǉǦǁƐǦƼƾảƾǦǉƑǃǦǃƼƶǓ.",
    ["分两队，男女老少们都来看，人人击鼓，那才热闹呢！"] = "ƞƽƾƶǦǁƐǂǦƽƶƾǦđộƾ,ǦƼƾƐǦǉǇẻǦƼƑƾǦǉǇƶƾǦđềǊǦđếǃǦǍƺǂ,ǦǃƼườƾǦǃƼườƾǦđƑǃƽǦǉǇốǃƼ,ǦǉƽếǦǂớƾǦǃƑǄǦǃƽƾệǉǦƸƽứ!",
    ["嗯……我觉得红狮子那招更帅，我得去给它敲两下！"] = "Ừǂ...ǦƸǄǃǦǉƽấǓǦƸƽƾƙǊǦǀƾƶǦƸủƶǦƸǄǃǦǈưǦǉửǦđỏǦǃƼầǊǦƽơǃ,ǦƸǄǃǦǅƽảƾǦđƾǦƼƅǦƸƽǄǦǃƚǦǂấǓǦƸƑƾ!",
    ["老爷，咱家要押注这喜红狮啊，还是黄金犼啊？"] = "ƧƃǄǦƼƾƶ,ǦǃƽƐǦǂƔǃƽǦǃƙǃǦđặǉǦƸượƸǦǋƐǄǦƸǄǃǦƣỷǦƣồǃƼǦƮưǦǃƐǓ,ǦƽƶǓǦǁƐǦƣǄƐǃƼǦƦƾǂǦƣốǃƼǦđƁǓ?",
    ["董冬东"] = "ĐổǃƼǦĐƇǃƼǦĐƇǃƼ",
    ["哇！哥哥你看，狮子的眼珠子还会动！好凶啊，珠儿害怕！"] = "ƪƶ!ǦƞƶǦƸƶǦǃƽƔǃǦǀƔƶ,ǦǂắǉǦƸủƶǦǈưǦǉửǦƸƛǃǦƸửǦđộǃƼǦđượƸ!ǦƣǊǃƼǦǤữǦǆǊƑ,ǦƞƽƁǊǦƩƽƾǦǈợ!",
    ["小珠儿"] = "ǥƾểǊǦƞƽƁǊǦƩƽƾ",
    ["全要！红的赢了就是红红火火，黄的赢了就是金银万贯，这就叫双押！]"] = "ƧấǓǦƽếǉ!ǦƨƐǊǦđỏǦǉƽắǃƼǦǉƽƔǦƽồǃƼǦƽồǃƼǦƽỏƶǦƽỏƶǦ(ǇựƸǦǇỡ),ǦǂƐǊǦǋƐǃƼǦǉƽắǃƼǦǉƽƔǦǀƾǂǦǃƼƁǃǦǋạǃǦǆǊƑǃǦ(ǉƾềǃǦǉƐƾǦđầǓǦǃƽƐ),ǦƸƑƾǦǃƐǓǦƼọƾǦǁƐǦđặǉǦƸượƸǦƸảǦđƇƾ!",
    ["全都宥"] = "ǥǄƐǃǦĐƇǦƣựǊ",
    ["小妹不怕。狮子可是瑞兽，它们是来吓唬“年”兽的。"] = "ǥƾểǊǦǂǊộƾǦđừǃƼǦǈợ.ǦƮưǦǉửǦǁƐǦǉƽụǓǦǉƽƕ,ǦƸƽƕǃƼǦđếǃǦđểǦƽƖǦǤọƶǦƸǄǃǦǉƽƕǦ\"Ʃƾƙǃ\"Ǧđƚ.",
    ["小鼎儿"] = "ǥƾểǊǦĐỉǃƽǦƩƽƾ",
    ["听起来像是什么迷人的表演技巧……"] = "ƩƼƽƺǦƸƚǦǋẻǦƼƾốǃƼǦǃƽưǦǂộǉǦǀỹǦǉƽǊậǉǦƷƾểǊǦǤƾễǃǦǂƙǦƽǄặƸǦǃƐǄǦđƚ...",
    ["把凶兽吓跑，咱这儿就能“生财”，大家明年才有肉吃！"] = "ǝọƶǦƽǊǃƼǦǉƽƕǦƸƽạǓǦǂấǉ,ǦƸƽỗǦƸƽƕǃƼǦǉƶǦǂớƾǦƸƚǦǉƽểǦ\"ǈƾǃƽǦǉƐƾ\",ǦǈƶǃƼǦǃăǂǦǂọƾǦǃƼườƾǦǂớƾǦƸƚǦǉƽịǉǦăǃ!",
    ["就你话多，来啊敲啊，给大家再添点热闹！"] = "ƞứǦǁƐǦǃƼươƾǦǁắǂǦǁờƾ,ǦđếǃǦđƁǓǦǃƐǄǦƼƅǦđƾ,ǦǉạǄǦǉƽƙǂǦƸƽƕǉǦǃƑǄǦǃƽƾệǉǦƸƽǄǦǂọƾǦǃƼườƾ!",
    ["董强镪"] = "ĐổǃƼǦƞườǃƼǦƞườǃƼ",
    ["你瞧那狮尾，可真是个练家子！马步扎得，那叫一个稳。"] = "ƩƼươƾǦǍƺǂǦƸƑƾǦđǊƇƾǦǈưǦǉửǦǀƔƶ,ǦđƕǃƼǦǁƐǦǃƼườƾǦƸƚǦǃƼƽề!ǦǥấǃǦƷộǦǍǊốǃƼǦǉƽậǉǦǁƐǦǋữǃƼǦǋƐǃƼ.",
    ["张泰"] = "ǥǇươǃƼǦǥƽƑƾ",
    ["狮子加油！我要吃肉！"] = "ƮưǦǉửǦƸốǦǁƙǃ!ǦƞǄǃǦǂǊốǃǦăǃǦǉƽịǉ!",
    ["可不是嘛，落桩的时候，下盘一下就立住了，纹丝不动。"] = "ƞƽẳǃƼǦǉƽếǦǈƶǄ,ǦǁƕƸǦđƑǅǦǍǊốǃƼǦƸọƸ,ǦƽạǦƷƐǃǦǁậǅǦǉứƸǦđứǃƼǦǋữǃƼ,ǦǀƽƇǃƼǦƽềǦǁƶǓǦđộǃƼ.",
    ["王诺林"] = "ƱươǃƼǦƩặƸǦƧƁǂ",
    ["这才是硬桥硬马的真功夫！"] = "ĐƁǓǦǂớƾǦǁƐǦƸƽƁǃǦƸƇǃƼǦǅƽǊǦǃƼạǃƽǦǀƾềǊǦǃƼạǃƽǦǂƃ!",
    ["这大侠的眼神，杀气腾腾，看得让人发怵！"] = "ÁǃƽǦǂắǉǦƸủƶǦǋịǦđạƾǦƽƾệǅǦǃƐǓǦǈƑǉǦǀƽƓǦđằǃƼǦđằǃƼ,ǦǃƽƔǃǦǂƐǦǉƽấǓǦǅƽƑǉǦǀƽƾếǅ!",
    ["管半槐"] = "ƬǊảǃǦƝƑǃǦƣǄƐƾ",
    ["爹，我也要学剑！我也要去雨夜行侠仗义！"] = "ƞƽƶ,ǦƸǄǃǦƸũǃƼǦǂǊốǃǦƽọƸǦǀƾếǂ!ǦƞǄǃǦƸũǃƼǦǂǊốǃǦđƾǦƽƐǃƽǦƽƾệǅǦǉǇượǃƼǦǃƼƽĩƶǦǉǇǄǃƼǦđƙǂǦǂưƶ!",
    ["郑三郎"] = "ǥǇịǃƽǦǥƶǂǦƧƶǃƼ",
    ["先生安排的课业都写完了？"] = "ƝƐƾǦǋởǦǉƾƙǃǦǈƾǃƽǦƼƾƶǄǦđƃǦǋƾếǉǦǍǄǃƼǦƸƽưƶ?",
    ["郑爹爹"] = "ǥǇịǃƽǦđƾƙǦđƾƙ",
    ["啧，你这人就不懂戏！这眼神分明是三分慈悲，四分坚勇……尽在不言中啊！"] = "ƞƽậƸ,ǦǃƼườƾǦǃƽưǦǃƼươƾǦƸƽẳǃƼǦƽƾểǊǦǍƺǂǦǀịƸƽǦƼƔǦƸả!ǦÁǃƽǦǂắǉǦǃƐǓǦǇƅǦǇƐǃƼǦǁƐǦƷƶǦǅƽầǃǦǉừǦƷƾ,ǦƷốǃǦǅƽầǃǦǀƾƙǃǦǤũǃƼ...ǦǉấǉǦƸảǦđềǊǦƼƚƾǦƼọǃǦǉǇǄǃƼǦƽưǦǀƽƇǃƼ!",
    ["慕容骄"] = "ƨộǦǝǊǃƼǦƦƾƙǊ",
    ["……还没。"] = "...ǦƱẫǃǦƸƽưƶ.",
    ["字都没学会还想学剑！"] = "ƞƽữǦƸƛǃǦƸƽưƶǦƽọƸǦǍǄǃƼǦǂƐǦđƃǦđƛƾǦƽọƸǦǀƾếǂ!",
    ["是我眼花了吗？你看，大侠怀里抱着的是啥？"] = "ƧƐǦǉƶǦƽǄƶǦǂắǉǦǈƶǄ?ǦƩƼươƾǦǃƽƔǃǦǀƔƶ,ǦđạƾǦƽƾệǅǦđƶǃƼǦƇǂǦƸƑƾǦƼƔǦǉǇǄǃƼǦǁƛǃƼǦǋậǓ?",
    ["魏飞兰"] = "ƩƼụǓǦƫƽƾǦƧƶǃ",
    ["当然是他救下的娃娃啦！"] = "ǝĩǦǃƽƾƙǃǦǁƐǦđứƶǦǃƽỏǦǂƐǦǋịǦấǓǦƸứǊǦđượƸǦǇồƾ!",
    ["不是个瓜嘛？"] = "ƞƽẳǃƼǦǅƽảƾǦǁƐǦǂộǉǦǆǊảǦǤưƶǦǈƶǄ?",
    ["哎呀，演戏罢了，总不能真的抱个娃娃上台……"] = "ÁƾǦƸƽƐ,ǦǤƾễǃǦǀịƸƽǦǉƽƇƾǦǂƐ,ǦƸũǃƼǦǀƽƇǃƼǦǉƽểǦƷếǦǂộǉǦđứƶǦǉǇẻǦǉƽậǉǦǁƙǃǦđƐƾǦđượƸ...",
    ["为啥就这么……原地踏步？"] = "ƮƶǄǦƸứ...ǦƼƾậǂǦƸƽƁǃǦǉạƾǦƸƽỗǦǉƽếǦǃƐǓ?",
    ["崔笛"] = "ǥƽƇƾǦĐịƸƽ",
    ["《负责操作鼓风机>吹啊吹啊！"] = "<ƫƽụǦǉǇƑƸƽǦǋậǃǦƽƐǃƽǦǂƑǓǦǉƽổƾǦƼƾƚ>ǦǥƽổƾǦđƾǦǉƽổƾǦđƾ!",
    ["罗古"] = "ƧƶǦƞổ",
    ["我不管，就是个瓜！"] = "ǥƶǦǀƽƇǃƼǦǆǊƶǃǦǉƁǂ,ǦǇƅǦǇƐǃƼǦǁƐǦǂộǉǦǆǊảǦǤưƶ!",
    ["你懂什么，班主要的就是这种感觉！"] = "ƩƼươƾǦǉƽƔǦƷƾếǉǦƸƑƾǦƼƔ,ǦƷƶǃǦƸƽủǦǂǊốǃǦƸƽƓǃƽǦǁƐǦƸảǂǦƼƾƑƸǦǃƐǓ!",
    ["乔洛"] = "ƦƾềǊǦƧạƸ",
    ["让风雨来得再猛烈些！"] = "ƣƃǓǦđểǦǅƽǄǃƼǦƷƶǦƷƃǄǦǉƑǅǦđếǃǦǤữǦǤộƾǦƽơǃǦǃữƶǦđƾ!",
    ["……这么演真行吗？"] = "...ǦǝƾễǃǦǃƽưǦǋậǓǦǉƽậǉǦǈựǦổǃǦƸƽứ?",
    ["真好看啊！这亮晶晶的，可真闪啊！"] = "ĐẹǅǦǆǊƑǦđƾ!ǦƩƽữǃƼǦǉƽứǦǁấǅǦǁƑǃƽǦǃƐǓǦǉƽậǉǦǁƐǦǉỏƶǦǈƑǃƼ!",
    ["哇！这火花炸开真壮观呀..."] = "ƪƶ!ǦƣǄƶǦǁửƶǦǃƐǓǦƷǊǃƼǦǃởǦǉƽậǉǦǉǇƑǃƼǦǁệǦǆǊƑ...",
    ["可不是呢！这一击一打的，可了不得啊！鲤娘你劲儿大，打出来又大又亮！"] = "ƞƽẳǃƼǦǉƽếǦǈƶǄ!ǦƞứǦǂộǉǦǀƓƸƽǦǂộǉǦđảǦǉƽếǦǃƐǓ,ǦǉƽậǉǦǀƽƇǃƼǦǉầǂǦǉƽườǃƼǦđƁǊ!ǦƧƈǦǃươǃƼǦǃƼươƾǦǀƽỏƺǦǉƶǓ,ǦđƑǃƽǦǇƶǦƽǄƶǦǁửƶǦǋừƶǦǉǄǦǋừƶǦǈƑǃƼ!",
    ["哇哇！是星点点！好美 ah！田姑田姑，你快看，你快看！"] = "ƪƶǦǄƶ!ǦƧƐǦǃƽữǃƼǦđốǂǦǈƶǄǦǃƽỏ!ǦĐẹǅǦǆǊƑ!ǦĐƾềǃǦƸƇǦĐƾềǃǦƸƇ,ǦƸƇǦǂƶǊǦǃƽƔǃǦǀƔƶ,ǦǂƶǊǦǃƽƔǃǦǀƔƶ!",
    ["哎呦莫莫，我看见了！你可小心着点啊！"] = "ÁƾǦƸƽƐǦƨạƸǦƨạƸ,ǦǉƶǦǉƽấǓǦǇồƾ!ǦƞǄǃǦǅƽảƾǦƸẩǃǦǉƽậǃǦǂộǉǦƸƽƕǉǦđƚ!",
    ["知道啦田姑！快看，开花啦开花啦！火焰大树开花啦！"] = "ƝƾếǉǦǇồƾǦǉƽưƶǦĐƾềǃǦƸƇ!ǦƨƶǊǦǃƽƔǃǦǀƔƶ,ǦǃởǦƽǄƶǦǇồƾǦǃởǦƽǄƶǦǇồƾ!ǦƞƁǓǦǁửƶǦǁớǃǦǃởǦƽǄƶǦǇồƾ!",
    ["是啊，开花了！还是天上开的花！"] = "ĐƕǃƼǦǋậǓ,ǦǃởǦƽǄƶǦǇồƾ!ǦƧạƾǦƸƛǃǦǁƐǦƽǄƶǦǃởǦǉǇƙǃǦǉǇờƾǦǃữƶ!",
    ["喵~（新年妙妙妙虽然我只喵了一声但是新年快乐福如东海新年吉祥！）"] = "ƨƺǄ~Ǧ(ƩăǂǦǂớƾǦǉǊǓệǉǦǉǊǓệǉǦǉǊǓệǉ,ǦǉǊǓǦǉƶǦƸƽỉǦǀƙǊǦǂộǉǦǉƾếǃƼǦǂƺǄǦǃƽưǃƼǦƸƽƕƸǦǃăǂǦǂớƾǦƽạǃƽǦǅƽƕƸ,ǦǅƽƕƸǦǃƽưǦĐƇǃƼǦƣảƾ,ǦǃăǂǦǂớƾǦƸƑǉǦǉườǃƼ!)",
    ["花旋风"] = "ƣǄƶǦǥǄƐǃǦƫƽǄǃƼ",
    ["新年好！"] = "ƩăǂǦǂớƾǦǉốǉǦǁƐǃƽ!",
    ["喵喵！喵，喵喵喵！（新年好！去打漂亮的大花吧！）"] = "ƨƺǄǦǂƺǄ!ǦƨƺǄ,ǦǂƺǄǦǂƺǄǦǂƺǄ!Ǧ(ƩăǂǦǂớƾǦǉốǉǦǁƐǃƽ!ǦĐƾǦđƑǃƽǦƽǄƶǦǁớǃǦǉƽậǉǦđẹǅǦǃƐǄ!)",
    ["汪汪汪！嗷！汪汪汪！（人，善良可爱的人，新年好嗷嗷！）"] = "ƢƁǊǦƼƁǊǦƼƁǊ!ǦƜǄ!ǦƢƁǊǦƼƁǊǦƼƁǊ!Ǧ(ƩƼườƾ,ǦǃƼườƾǦǁươǃƼǦǉƽƾệǃǦđƑǃƼǦǓƙǊǦơƾ,ǦǃăǂǦǂớƾǦǉốǉǦǁƐǃƽǦƼƁǊǦƼƁǊ!)",
    ["你也好！"] = "ƩƼươƾǦƸũǃƼǦǋậǓ!",
    ["汪汪汪汪汪汪！（这里会有好美丽的大花！漂亮嗷呜漂亮！）"] = "ƢƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊǦƼƁǊ!Ǧ(ỞǦđƁǓǦǈẽǦƸƚǦƽǄƶǦǁớǃǦƸựƸǦǀỳǦǂỹǦǁệ!ǦĐẹǅǦǁắǂǦƶǄǦǊǦđẹǅǦǁắǂ!)",
    ["...老金？你怎么在这？"] = "...ǦƧƃǄǦƦƾǂ?ǦƮƶǄǦƇǃƼǦǁạƾǦởǦđƁǓ?",
    ["哎呦，这不是我们少东家吗？要不要打个铁花瞧瞧？美得很啊！新的一年搞点金色的讨个彩头！"] = "ÁƾǦƸƽƐ,ǦđƁǓǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǥƽƾếǊǦđƇǃƼǦƼƾƶǦƸủƶǦƸƽƕǃƼǦǉƶǦǈƶǄ?ǦƞƚǦǂǊốǃǦđƑǃƽǦǂộǉǦǉǇậǃǦƽǄƶǦǈắǉǦǍƺǂǦǉƽửǦǀƽƇǃƼ?ǦĐẹǅǦǁắǂǦđƚǦǃƽƶ!ǦƩăǂǦǂớƾǦǁƐǂǦƸƽƕǉǦǈắƸǦǋƐǃƼǦƸầǊǦǂƶǓǦǂắǃǦǃƐǄ!",
    ["这是你新的生财大计？"] = "ĐƁǓǦǁƐǦđạƾǦǀếǦǈƾǃƽǦǉƐƾǦǂớƾǦƸủƶǦƇǃƼǦƐ?",
    ["嗨呀，是啊！少东家要不要打一个？今天这火树银花啊，我老金就不收钱啦！"] = "ƣƶǦǤƶ,ǦđƕǃƼǦǋậǓ!ǦǥƽƾếǊǦđƇǃƼǦƼƾƶǦǂǊốǃǦđƑǃƽǦǂộǉǦǉǇậǃǦǀƽƇǃƼ?ǦƣǄƶǦǁửƶǦǇựƸǦǇỡǦƽƇǂǦǃƶǓ,ǦƧƃǄǦƦƾǂǦǉƶǦǀƽƇǃƼǦǉƽǊǦǉƾềǃǦđƁǊ!",
    ["真的？还有这种好事？"] = "ǥƽậǉǦǈƶǄ?ǦƧạƾǦƸƚǦƸƽǊǓệǃǦǉốǉǦǉƽếǦǃƐǓǦƐ?",
    ["过年，图个吉利！保佑来年发个大财！我老金今天就放话在这，分文不取！免费打铁花！"] = "ĂǃǦǥếǉǦǂƐ,ǦƸốǉǦǁƐǦǉƔǂǦƸƑƾǦƸƑǉǦǁợƾ!ǦƝảǄǦƽộǦǈƶǃƼǦǃăǂǦǅƽƑǉǦđạƾǦǉƐƾ!ǦƧƃǄǦƦƾǂǦǉƶǦƽƇǂǦǃƶǓǦǉǊǓƙǃǦƷốǦǉạƾǦđƁǓ,ǦǅƽƁǃǦǋăǃǦƷấǉǦǉƽủ!ǦĐƑǃƽǦƽǄƶǦǈắǉǦǂƾễǃǦǅƽƓ!",
    ["好，那我就来打一打铁花！"] = "ĐượƸ,ǦǋậǓǦǉƶǦǈẽǦđƑǃƽǦƽǄƶǦǈắǉǦǂộǉǦǅƽƺǃ!",
    ["哎，真不给呀..."] = "ƜƾǦǤƶ,ǦǉƽậǉǦǈựǦǀƽƇǃƼǦđưƶǦǉƾềǃǦǈƶǄ...",
    ["你不是分文不取吗？"] = "ƞƽẳǃƼǦǅƽảƾǦƇǃƼǦǃƚƾǦǅƽƁǃǦǋăǃǦƷấǉǦǉƽủǦǈƶǄ?",
    ["是，是...来，少东家！你多打一打，就算为我这项目讨个好彩头了！"] = "ƫƽảƾ,Ǧǅƽảƾ...ǦĐếǃǦđƁǓ,ǦǥƽƾếǊǦđƇǃƼǦƼƾƶ!ǦƩƼƐƾǦđƑǃƽǦǉƽƙǂǦǋƐƾǦƸƑƾǦđƾ,ǦƸǄƾǦǃƽưǦǁƐǦǁấǓǦƸƽƕǉǦǂƶǓǦǂắǃǦƸƽǄǦǤựǦƑǃǦǃƐǓǦƸủƶǦǉƶ!",
    ["该给的还是给，这也是对你的支持！"] = "ƞầǃǦđưƶǦǉƽƔǦǋẫǃǦǅƽảƾǦđưƶ,ǦđƁǓǦƸũǃƼǦǁƐǦđểǦủǃƼǦƽộǦƇǃƼ!",
    ["这怎么好意思呐！这可让我老金无地自容呀！这里头有多少呀？"] = "ǥƽếǦǃƐǓǦǈƶǄǦǂƐǦǃƼạƾǦǆǊƑ!ǦǥƽậǉǦǀƽƾếǃǦƧƃǄǦƦƾǂǦǉƶǦǋƇǦđịƶǦǉựǦǤǊǃƼǦǂƐ!ǦǥǇǄǃƼǦǃƐǓǦƸƚǦƷƶǄǦǃƽƾƙǊǦǋậǓǦǃƽỉ?",
    ["是，是...哎你瞧我这手！习惯、习惯..."] = "ƫƽảƾ,Ǧǅƽảƾ...ǦÁƾǦƸƽƐǦǃƼƐƾǦǍƺǂǦƸƑƾǦǉƶǓǦǃƐǓǦƸủƶǦǉƶ!ǦǥƽƚƾǦǆǊƺǃ,ǦǉƽƚƾǦǆǊƺǃǦǉƽƇƾ...",
    ["给你的，收着！新的一年，要发财呀老金！"] = "ƞƽǄǦƇǃƼǦđƚ,ǦǃƽậǃǦǁấǓǦđƾ!ǦƩăǂǦǂớƾǦǅƽảƾǦǅƽƑǉǦǉƐƾǦǃƽƗǦƧƃǄǦƦƾǂ!",
    ["好好好！谢谢少东家！也祝您新的一年财源滚滚，每天躺钱堆上笑醒！"] = "ǥốǉǦǉốǉǦǉốǉ!ǦĐƶǦǉạǦǥƽƾếǊǦđƇǃƼǦƼƾƶ!ǦƞũǃƼǦƸƽƕƸǦǃƼƐƾǦǃăǂǦǂớƾǦǉƐƾǦǃƼǊǓƙǃǦǆǊảǃƼǦǉƾếǃ,ǦǂỗƾǦǃƼƐǓǦǃằǂǦǉǇƙǃǦđốǃƼǦǉƾềǃǦǂƐǦƸườƾǦǉỉǃƽ!",
    ["嗨，你看这都是人，估计都是被吸引来的呢！你瞧你瞧，还有不同模样呢！"] = "ƣƶ,ǦǃƼươƾǦǍƺǂǦǉǄƐǃǦǁƐǦǃƼườƾ,ǦƸƽắƸǦđềǊǦƷịǦǉƽǊǦƽƕǉǦđếǃǦđƁǓǦǇồƾ!ǦƩƽƔǃǦǀƔƶǦǃƽƔǃǦǀƔƶ,ǦƸƛǃǦƸƚǦđủǦǁǄạƾǦǤƑǃƼǦǋẻǦǀƽƑƸǦǃƽƶǊǦǃữƶ!",
    ["是啊！可真漂亮啊！"] = "ĐƕǃƼǦǋậǓ!ǦǥƽậǉǦǁƐǦđẹǅǦǆǊƑǦđƾ!",
    ["财神显灵了！"] = "ǥƽầǃǦǥƐƾǦƽƾểǃǦǁƾǃƽǦǇồƾ!",
    ["终于放贾先生"] = "ƞƽǊǃƼǦƱǊǦƫƽƚǃƼǦƢƾảǦǉƾƙǃǦǈƾǃƽ",
    ["什么什么！财神怎么显灵的？！"] = "ƞƑƾǦƼƔǦƸƑƾǦƼƔ!ǦǥƽầǃǦǥƐƾǦƽƾểǃǦǁƾǃƽǦǉƽếǦǃƐǄǦƸơ?!",
    ["早日暴富娘子"] = "ǥảǄǦƩƽậǉǦƝạǄǦƫƽƕǦǃươǃƼǦǉử",
    ["昨天我变财神了！"] = "ƣƇǂǦǆǊƶǦǉƶǦđƃǦƷƾếǃǦǉƽƐǃƽǦǥƽầǃǦǥƐƾǦđƚ!",
    ["怎么现在才勾芡？瞧那汁收的……"] = "ƮƶǄǦƷƁǓǦƼƾờǦǂớƾǦǍǊốǃƼǦƷộǉǦǃăǃƼ?ǦƩƽƔǃǦǃướƸǦǈốǉǦƸƇǦǁạƾǦǀƔƶ...",
    ["你们...在聊什么变财神？"] = "ƨọƾǦǃƼườƾ...ǦđƶǃƼǦǉƑǃǦƼẫǊǦƸƽǊǓệǃǦƷƾếǃǦǉƽƐǃƽǦǥƽầǃǦǥƐƾǦƼƔǦǋậǓ?",
    ["哎，我前天晚上做梦，梦里财神和我说，年底了，他的活做不完了，所以正在招工呢！"] = "Ɯƾ,ǦǉốƾǦƽƇǂǦǀƾƶǦǉƶǦǃằǂǦǂơ,ǦǉǇǄǃƼǦǂộǃƼǦǥƽầǃǦǥƐƾǦǃƚƾǦǋớƾǦǉƶǦǇằǃƼ,ǦƸǊốƾǦǃăǂǦǇồƾ,ǦǋƾệƸǦƸủƶǦǃƼƐƾǦǁƐǂǦǀƽƇǃƼǦǍǊể,ǦǃƙǃǦđƶǃƼǦǉǊǓểǃǦǃƼườƾǦǁƐǂǦđƚ!",
    ["招工？招什么工？"] = "ǥǊǓểǃǦǃƼườƾ?ǦǥǊǓểǃǦǋƾệƸǦƼƔǦƸơ?",
    ["哎呀，就是找些品性得到财神认可的人，代财神为祈祷的人完成心愿！"] = "ÁƾǦƸƽƐ,ǦƸƽƓǃƽǦǁƐǦǉƔǂǦǃƽữǃƼǦǃƼườƾǦƸƚǦǅƽẩǂǦƽạǃƽǦđượƸǦǥƽầǃǦǥƐƾǦƸƇǃƼǦǃƽậǃ,ǦǉƽƶǓǦǥƽầǃǦǥƐƾǦƽǄƐǃǦǉƽƐǃƽǦǉƁǂǦǃƼǊǓệǃǦƸƽǄǦǃƽữǃƼǦǃƼườƾǦƸầǊǦǀƽấǃ!",
    ["这样一来，被认可的人就能变身财神了！"] = "ƩƽưǦǋậǓ,ǦǃƼườƾǦđượƸǦƸƇǃƼǦǃƽậǃǦƸƚǦǉƽểǦƷƾếǃǦǉƽƁǃǦǉƽƐǃƽǦǥƽầǃǦǥƐƾ!",
    ["这是不是····有些太过儿戏？"] = "ƞƽǊǓệǃǦǃƐǓ...ǦƸƽẳǃƼǦǅƽảƾǦƸƚǦƸƽƕǉǦǆǊƑǦđƖƶǦƼƾỡǃǦǈƶǄ?",
    ["不儿戏！完全不儿戏！你可知道，年底了，众人皆在冲刺，祈愿之人海海，求的又都是发财，财神来不及也是情有可原..."] = "ƦƽƇǃƼǦđƖƶǦđƁǊ!ǦƣǄƐǃǦǉǄƐǃǦǀƽƇǃƼǦđƖƶ!ǦƩƼươƾǦƸƚǦƷƾếǉǦǀƽƇǃƼ,ǦƸǊốƾǦǃăǂǦǇồƾ,ǦƶƾǦǃấǓǦđềǊǦđƶǃƼǦǤốƸǦǈứƸ,ǦǃƼườƾǦƸầǊǦǃƼǊǓệǃǦđƇǃƼǦǃƽưǦƷƾểǃ,ǦǂƐǦƶƾǦƸũǃƼǦƸầǊǦǅƽƑǉǦǉƐƾ,ǦǥƽầǃǦǥƐƾǦǁƐǂǦǀƽƇǃƼǦǀịǅǦƸũǃƼǦǁƐǦǁẽǦǉƽườǃƼǦǉƔǃƽ...",
    ["是啊...年底了...忙...都忙...忙点好啊..."] = "ĐƕǃƼǦǋậǓ...ǦƸǊốƾǦǃăǂǦǇồƾ...ǦƷậǃ...ǦƶƾǦƸũǃƼǦƷậǃ...ǦƷậǃǦƸƽƕǉǦƸũǃƼǦǉốǉ...",
    ["你们怎么还感慨上了...听着都有几分苦涩。"] = "ƮƶǄǦǂọƾǦǃƼườƾǦǁạƾǦƸảǂǦǉƽƑǃǦǇồƾ...ǦǃƼƽƺǦǇƶǦƸƚǦǋƐƾǦǅƽầǃǦđắǃƼǦƸƶǓ.",
    ["嗨，不谈这些！所以说，只要得到财神认可，就能变身财神，享受撒钱的快乐！"] = "ƣƶ,ǦǀƽƇǃƼǦƷƐǃǦƸƽǊǓệǃǦđƚǦǃữƶ!ǦǥƚǂǦǁạƾǦǁƐ,ǦƸƽỉǦƸầǃǦđượƸǦǥƽầǃǦǥƐƾǦƸƇǃƼǦǃƽậǃǦǁƐǦƸƚǦǉƽểǦƷƾếǃǦǉƽƁǃǦǥƽầǃǦǥƐƾ,ǦǉậǃǦƽưởǃƼǦǃƾềǂǦǋǊƾǦǇảƾǦǉƾềǃ!",
    ["这样每撒一次钱，财神能算一次劳绩，自己也能享受挥金如土的感觉！"] = "ƞứǦǂỗƾǦǁầǃǦǇảƾǦǉƾềǃǦǃƽưǦǋậǓ,ǦǥƽầǃǦǥƐƾǦǈẽǦǉƓǃƽǦǂộǉǦǁầǃǦƸƇǃƼǦǉǇạǃƼ,ǦǂƐǦƷảǃǦǉƽƁǃǦƸũǃƼǦđượƸǦǉậǃǦƽưởǃƼǦƸảǂǦƼƾƑƸǦǋǊǃƼǦǉƾềǃǦǃƽưǦǇƑƸ!",
    ["没错！无穷无尽的钱，想撒多少撒多少，想撒给谁撒给谁！"] = "ƞƽƓǃƽǦǍƑƸ!ǦǥƾềǃǦƷạƸǦǋƇǦƷƾƙǃǦǋƇǦǉậǃ,ǦǂǊốǃǦǇảƾǦƷƶǄǦǃƽƾƙǊǦǉƽƔǦǇảƾ,ǦǂǊốǃǦǇảƾǦƸƽǄǦƶƾǦǉƽƔǦǇảƾ!",
    ["这可是真正的暴富！没有任何不利之症，堪称居家旅行必备之良术！"] = "ĐƁǓǦǂớƾǦƸƽƓǃƽǦǁƐǦƷạǄǦǅƽƕǦǉƽựƸǦǈự!ǦƦƽƇǃƼǦƸƚǦƷấǉǦǀỳǦǉƑƸǦǤụǃƼǦǅƽụǦǃƐǄ,ǦǍứǃƼǦǤƶǃƽǦǁƐǦǁươǃƼǦǉƽǊậǉǦƸốǉǦǓếǊǦǀƽƾǦƽƐǃƽǦǉẩǊ!",
    ["我看你骨骼清奇，内心纯良，是个好人呐！你想不想变身财神，感受一把成为财富的主人的快乐？"] = "ǥƶǦǉƽấǓǦǃƼươƾǦƸốǉǦƸƑƸƽǦǉƾǃƽǦƶǃƽ,ǦǃộƾǦǉƁǂǦǉƽǊầǃǦƽậǊ,ǦđƕǃƼǦǁƐǦǂộǉǦǃƼườƾǦǉốǉ!ǦƩƼươƾǦƸƚǦǂǊốǃǦƷƾếǃǦǉƽƁǃǦǥƽầǃǦǥƐƾ,ǦƸảǂǦǃƽậǃǦǂộǉǦǁầǃǦǃƾềǂǦǋǊƾǦǁƐǂǦƸƽủǦǉƾềǃǦǉƐƾǦǀƽƇǃƼ?",
    ["我吗？可以是我吗？虽然，我确实想感受一下..."] = "ǥƶǦǈƶǄ?ǦƞƚǦǉƽểǦǁƐǦǉƶǦǈƶǄ?ǦǥǊǓǦǇằǃƼ,ǦǉƶǦǆǊảǦǉƽựƸǦƸũǃƼǦǂǊốǃǦƸảǂǦǃƽậǃǦǂộǉǦƸƽƕǉ...",
    ["好！那你就是财神钦点了！"] = "ǥốǉ!ǦƱậǓǦǃƼươƾǦđƃǦđượƸǦǥƽầǃǦǥƐƾǦǀƽƁǂǦđƾểǂǦǇồƾ!",
    ["欢迎光临……"] = "ƣǄƶǃǦǃƼƽƙǃƽǦǆǊƶǃƼǦǁƁǂ……",
    ["道主小福"] = "ĐạǄǦƸƽủǦǥƾểǊǦƫƽƕƸ",
    ["游侠，想吃点什么？菜单上有的都能炒！"] = "ǝǊǦƽƾệǅ,ǦǂǊốǃǦăǃǦƸƽƕǉǦƼƔǦǀƽƇǃƼ?ǦƩƽữǃƼǦǂƚǃǦǉǇƙǃǦǉƽựƸǦđơǃǦđềǊǦƸƚǦǉƽểǦǍƐǄǦǃấǊ!",
    ["道主小禄"] = "ĐạǄǦƸƽủǦǥƾểǊǦƧộƸ",
    ["菜单上没有的，我们也想办法给您做出来！"] = "ƨƚǃǦǃƐǄǦǀƽƇǃƼǦƸƚǦǉǇƙǃǦǉƽựƸǦđơǃ,ǦƸƽƕǃƼǦǉƶǦƸũǃƼǦǈẽǦǃƼƽĩǦƸƑƸƽǦǁƐǂǦƸƽǄǦǆǊƈǦǀƽƑƸƽ!",
    ["道主小寿"] = "ĐạǄǦƸƽủǦǥƾểǊǦǥƽọ",
    ["嚯！这火苗子窜得有一人高！"] = "ƣƇ!ǦƩƼọǃǦǁửƶǦǃƐǓǦƷốƸǦƸƶǄǦǉớƾǦǉậǃǦǂộǉǦǃƼườƾ!",
    ["哪里不合口味，客官只管说！"] = "ƞƽỗǦǃƐǄǦǀƽƇǃƼǦƽợǅǦǀƽẩǊǦǋị,ǦǀƽƑƸƽǦǆǊƶǃǦƸứǦǋƾệƸǦǃƚƾ!",
    ["看样子要跟灶台拼命啊！"] = "ƳƺǂǦƷộǦǤạǃƼǦǃƐǓǦǁƐǦđịǃƽǦǁƾềǊǦǂạǃƼǦǋớƾǦƷếǅǦǁƛǦǇồƾ!",
    ["吴兴娘"] = "ƩƼƇǦƣưǃƼǦƩươǃƼ",
    ["好强的颠勺！一招‘神龙摆尾’，竟将锅中食材翻得滴油不漏！"] = "ƦỹǦǉƽǊậǉǦđƾƙǃǦǉƽượƸǦ(đảǄǦǂǊƇƾ)ǦǉƽậǉǦǂạǃƽ!ǦƨộǉǦƸƽƾƙǊǦ'ǥƽầǃǦƧǄǃƼǦƝƑƾǦƱĩ',ǦǋậǓǦǂƐǦǀƽƾếǃǦǉƽứƸǦăǃǦǉǇǄǃƼǦǃồƾǦđảǄǦǁƙǃǦǀƽƇǃƼǦǁọǉǦǂộǉǦƼƾọǉǦǤầǊ!",
    ["张连"] = "ǥǇươǃƼǦƧƾƙǃ",
    ["一般一般，不如我家娘子！"] = "ǥƽườǃƼǦǉƽƇƾǦǉƽườǃƼǦǉƽƇƾ,ǦǀƽƇǃƼǦƷằǃƼǦǃươǃƼǦǉửǦǃƽƐǦǉƶ!",
    ["喵喵喵！喵喵！喵喵喵喵！喵喵！《猫大厨看向你，在推荐菜肴拍下一爪，似极力推荐，盛情难却。>"] = "ƨƺǄǦǂƺǄǦǂƺǄ!ǦƨƺǄǦǂƺǄ!ǦƨƺǄǦǂƺǄǦǂƺǄǦǂƺǄ!ǦƨƺǄǦǂƺǄ!Ǧ<ƨƾƙǊǦđạƾǦđầǊǦƷếǅǦǃƽƔǃǦǋềǦǅƽƓƶǦǃƼươƾ,ǦấǃǦǂộǉǦǤấǊǦƸƽƁǃǦǁƙǃǦǂƚǃǦăǃǦđềǦƸử,ǦǉựƶǦǃƽưǦƸựƸǦǁựƸǦđềǦƸử,ǦǉƽịǃƽǦǉƔǃƽǦǀƽƚǦǀƽướƸǦǉừ.>",
    ["米酿"] = "ƨễǦƩươǃƼ",
    ["“吃这个，这个！非常好吃，推荐！”——或许是这个意思吧。"] = "\"ĂǃǦƸƑƾǦǃƐǓ,ǦƸƑƾǦǃƐǓǦđƾ!ǦƞựƸǦǀỳǦǃƼǄǃ,ǦđềǦƸửǦđƚ!\"Ǧ——ǦƞƚǦǁẽǦǁƐǦƈǦǃƐǓǦƸƽăǃƼ.",
    ["汪呜呜汪，汪，汪汪唔汪！《狗大厨摇摇耳朵，盯着一道菜，吐着舌头盼望你打包带走，眼神恳切。>"] = "ƢƁǊǦǊǦǊǦƼƁǊ,ǦƼƁǊ,ǦƼƁǊǦƼƁǊǦưǦƼƁǊ!Ǧ<ǕƇǃƼǦđạƾǦđầǊǦƷếǅǦǋẫǓǦǋẫǓǦǉƶƾ,ǦƸƽằǂǦƸƽằǂǦǃƽƔǃǦǋƐǄǦǂộǉǦǂƚǃǦăǃ,ǦǉƽƘǦǁưỡƾǦǂǄǃƼǦđợƾǦǃƼươƾǦƼƚƾǦǂƶǃƼǦđƾ,ǦƑǃƽǦǂắǉǦǀƽẩǃǦǉƽƾếǉ.>",
    ["酱豆"] = "ǥươǃƼǦĐậǊ",
    ["“吃这个吧，人，多吃一点！”——或许是这个意思吧。"] = "\"ĂǃǦƸƑƾǦǃƐǓǦđƾ,ǦǃƼườƾǦơƾ,ǦăǃǦǃƽƾềǊǦǂộǉǦƸƽƕǉ!\"Ǧ——ǦƞƚǦǁẽǦǁƐǦƈǦǃƐǓǦƸƽăǃƼ.",
    ["这两位大厨，究竟是哪路神仙？"] = "ƣƶƾǦǋịǦđạƾǦđầǊǦƷếǅǦǃƐǓǦǇốǉǦƸǊộƸǦǁƐǦǉƽầǃǦǉƽƑǃƽǦǅƽươǃƼǦǃƐǄ?",
    ["能把开封s的猫儿狗儿都招呼来……莫不是幻术吧？"] = "ƞƚǦǉƽểǦǀƙǊǦƼọƾǦƽếǉǦǂƘǄǦƸƽƚǦởǦƦƽƶƾǦƫƽǄǃƼǦđếǃǦđƁǓ...ǦƸƽẳǃƼǦǁẽǦǁƐǦảǄǦǉƽǊậǉǦǈƶǄ?",
    ["讨猫狗喜欢有什么难的？也就你，贼眉鼠眼，猫狗见你都绕道走。"] = "ƧấǓǦǁƛǃƼǦǂƘǄǦƸƽƚǦƸƚǦƼƔǦǀƽƚ?ǦƞƽỉǦƸƚǦǃƼươƾ,ǦǂặǉǦǤơƾǦǉƶƾǦƸƽǊộǉ,ǦǂƘǄǦƸƽƚǦǉƽấǓǦǃƼươƾǦđềǊǦǅƽảƾǦđƾǦđườǃƼǦǋƛǃƼ.",
    ["朋友，你骂人好脏啊……"] = "ƝằǃƼǦƽữǊǦƐ,ǦǃƼươƾǦǂắǃƼǦǃƼườƾǦǀƽƚǦǃƼƽƺǦǆǊƑǦđƾ...",
    ["数到三，我就冲进去！一……二……一……二……一……"] = "ĐếǂǦđếǃǦƷƶ,ǦǉƶǦǈẽǦǍƇǃƼǦǋƐǄ!Ǧƨộǉ...Ǧƽƶƾ...Ǧǂộǉ...Ǧƽƶƾ...Ǧǂộǉ...",
    ["嘤嘤嘤，呜呜呜，嘤呜嘤呜嘤呜……"] = "ƜǃƽǦƶǃƽǦƶǃƽ,ǦƽǊǦƽǊǦƽǊ,ǦƶǃƽǦǊǦƶǃƽǦǊǦƶǃƽǦǊ……",
    ["完了，丢了“身轻大力丸”，万一“那天”真的来了，我要怎么带着大家逃出宫啊？"] = "ƣỏǃƼǦǇồƾ,ǦǂấǉǦ\"ǥƽƁǃǦƦƽƾǃƽǦĐạƾǦƧựƸǦƣǄƐǃ\"ǦǇồƾ,ǦǋạǃǦǃƽấǉǦ\"ǃƼƐǓǦđƚ\"ǦǉƽựƸǦǈựǦǉớƾ,ǦǉƶǦǅƽảƾǦǁƐǂǦǈƶǄǦđưƶǦǂọƾǦǃƼườƾǦǉǇốǃǦǉƽǄƑǉǦǀƽỏƾǦƸǊǃƼǦđƁǓ?",
    ["干活的时候能听到娘子美妙的歌声，果然特别有劲！"] = "ƧƕƸǦǁƐǂǦǋƾệƸǦđượƸǦǃƼƽƺǦǉƾếǃƼǦƽƑǉǦǂỹǦǤƾệǊǦƸủƶǦǃươǃƼǦǉử,ǦǆǊảǦǃƽƾƙǃǦǉƽấǓǦƽăǃƼǦƽƑƾǦƽẳǃǦǁƙǃ!",
    ["这么显眼的药葫芦，我分明记得把它挂在腰上了……"] = "ƞƑƾǦƽồǦǁƇǦǉƽǊốƸǦƷắǉǦǂắǉǦǉƽếǦǃƐǓ,ǦǉƶǦǃƽớǦǇƅǦǇƐǃƼǦǁƐǦđƃǦǉǇƺǄǦởǦǃƼƶǃƼǦƽƇǃƼǦǇồƾǦǂƐ...",
    ["没了这药丸，我还怎么身轻如燕，翻墙出宫？"] = "ƦƽƇǃƼǦƸƚǦǋƾƙǃǦǉƽǊốƸǦǃƐǓ,ǦǈƶǄǦǉƶǦƸƚǦǉƽểǦǉƽƁǃǦǀƽƾǃƽǦǃƽưǦǓếǃ,ǦǋượǉǦǉườǃƼǦǇƶǦǀƽỏƾǦƸǊǃƼǦđƁǓ?",
    ["身轻如燕？什么宝贝药丸，神成这样？"] = "ǥƽƁǃǦǀƽƾǃƽǦǃƽưǦǓếǃ?ǦƧǄạƾǦǤượƸǦƽǄƐǃǦƷảǄǦƷốƾǦƼƔǦǂƐǦǉƽầǃǦǀỳǦđếǃǦǋậǓ?",
    ["啊，是武德司的军士——没有丢，谁丢东西了？！宫中怎么会有贼人呢……哈哈哈，是吧？"] = "Ɯ,ǦǁƐǦǆǊƁǃǦǈĩǦƸủƶǦƱƅǦĐứƸǦǥǓǦ——ǦǀƽƇǃƼǦƸƚǦǂấǉ,ǦƶƾǦǂấǉǦđồǦƸơǦƸƽứ?!ǦǥǇǄǃƼǦƸǊǃƼǦǈƶǄǦƸƚǦǉƽểǦƸƚǦǉặƸǦǃƽƁǃǦđượƸ...ǦƽƶǦƽƶǦƽƶ,ǦǅƽảƾǦǀƽƇǃƼ?",
    ["这武德司的，耳朵怎么这么灵……"] = "ƩƼườƾǦƸủƶǦƱƅǦĐứƸǦǥǓǦǃƐǓ,ǦǈƶǄǦǉƶƾǦǁạƾǦǉƽƓǃƽǦǉƽếǦǀƽƇǃƼǦƷƾếǉ...",
    ["那道雕花梅球儿可备妥了？娘子午后惯要用的，莫误了时辰。"] = "ƨƚǃǦĐƾƙǊǦƽǄƶǦǂƶƾǦƸầǊǦǃƽƾǦǀƾƶǦđƃǦƸƽǊẩǃǦƷịǦǍǄǃƼǦƸƽưƶ?ǦƩươǃƼǦǉửǦǉƽườǃƼǦǤƖǃƼǦǋƐǄǦƷǊổƾǦƸƽƾềǊ,ǦđừǃƼǦđểǦǁỡǦǉƽờƾǦǉƽầǃ.",
    ["眼下她们最喜食用的是雕花蜜煎，但日后是什么，却不好说了。"] = "ƣƾệǃǦǉạƾǦƸƑƸǦǃƐǃƼǦǉƽƓƸƽǦǤƖǃƼǦǃƽấǉǦǁƐǦĐƾƙǊǦƽǄƶǦǂậǉǦǉƾễǃ,ǦǃƽưǃƼǦǈƶǊǦǃƐǓǦǁƐǦƼƔǦǉƽƔǦǀƽƚǦǃƚƾǦǉǇướƸǦđượƸ.",
    ["娘子们的口味各不相同，喜好也时时在变，什么时辰备什么点心，用什么器皿，配什么茶，向来都得我们用心去揣摩。"] = "ƦƽẩǊǦǋịǦƸủƶǦƸƑƸǦǃươǃƼǦǉửǦǂỗƾǦǃƼườƾǦǂộǉǦǀƽƑƸ,ǦǈởǦǉƽƓƸƽǦƸũǃƼǦǉƽƶǓǦđổƾǦǁƾƙǃǦǉụƸ,ǦƼƾờǦǃƐǄǦƸƽǊẩǃǦƷịǦđƾểǂǦǉƁǂǦƼƔ,ǦǤƖǃƼǦǀƽƓǦǂƃǃƽǦǃƐǄ,ǦǅƽƶǦǉǇƐǦƼƔ,ǦǉừǦǉǇướƸǦđếǃǦǃƶǓǦđềǊǦǅƽảƾǦđểǦƸƽƕǃƼǦǉƶǦǤụǃƼǦǉƁǂǦǈǊǓǦđǄƑǃ.",
    ["诶，听雨才赢了一把，怎的就不回来了，难道掉进净房了？"] = "Ơ,ǦǥƽƓǃƽǦƱũǦǂớƾǦǉƽắǃƼǦǂộǉǦǋƑǃ,ǦǈƶǄǦǂƃƾǦǀƽƇǃƼǦǉƽấǓǦǋề,ǦƸƽẳǃƼǦǁẽǦǇơƾǦǍǊốǃƼǦǉịǃƽǦǅƽƛǃƼǦǇồƾ?",
    ["诶，武德司的大人！要不要来一局叶子行饮？"] = "Ơ,ǦđạƾǦǃƽƁǃǦƱƅǦĐứƸǦǥǓ!ǦƞƚǦǂǊốǃǦǁƐǂǦǂộǉǦǋƑǃǦǝƾệǅǦǥửǦƣƐǃƽǦẨǂǦǀƽƇǃƼ?",
    ["你……宝慈宫内，这不合礼数！"] = "ƩƼươƾ...ǦǥǇǄǃƼǦƸǊǃƼǦƝảǄǦǥừ,ǦđƾềǊǦǃƐǓǦǀƽƇǃƼǦƽợǅǦǁễǦǈố!",
    ["咳，按理不该如此，但情形特殊，倒也……可以通融。"] = "Ʀƽụ,ǦǉƽƺǄǦǁƈǦǉƽƔǦǀƽƇǃƼǦǃƙǃǦǃƽưǦǋậǓ,ǦǃƽưǃƼǦǉƔǃƽǦƽƔǃƽǦđặƸǦǉƽƖ,ǦƸũǃƼ...ǦƸƚǦǉƽểǦǉƽƇǃƼǦǤǄǃƼ.",
    ["来，动起来！跟我一起，学五禽戏，练好身体。"] = "ĐếǃǦđƁǓ,ǦǋậǃǦđộǃƼǦǃƐǄ!ǦƞƖǃƼǦǉƶǦƽọƸǦƩƼũǦƞầǂǦƣƓ,ǦǇƘǃǦǁǊǓệǃǦǉƽƁǃǦǉƽể.",
    ["你们倒是养生。"] = "ƞƑƸǦǃƼươƾǦƸũǃƼǦƷƾếǉǦǤưỡǃƼǦǈƾǃƽǦđấǓǦǃƽỉ.",
    ["不是养生，是壮胆。你不觉得宫里有时候，有些地方阴森森的吗？"] = "ƦƽƇǃƼǦǅƽảƾǦǤưỡǃƼǦǈƾǃƽ,ǦǁƐǦǉǇƑǃƼǦđảǂǦ(ǁấǓǦƸƶǃǦđảǂ).ǦƩƼươƾǦǀƽƇǃƼǦǉƽấǓǦǉǇǄǃƼǦƸǊǃƼǦđƇƾǦǀƽƾǦƸƚǦǃƽữǃƼǦǃơƾǦƁǂǦǊǦđƑǃƼǦǈợǦǈƶǄ?",
    ["前些日子闹鬼呢……咱们沾了范娘子的光，能跟着红娘习武。"] = "ƨấǓǦǃƼƐǓǦǉǇướƸǦƸƚǦǂƶǦđấǓ...ǦƸƽƕǃƼǦǉƶǦǃƽờǦǅƽƕƸǦƸủƶǦƫƽạǂǦǃươǃƼǦǉử,ǦǂớƾǦđượƸǦǉƽƺǄǦƣồǃƼǦǃươǃƼǦǉậǅǦǋƅ.",
    ["守夜的时候多了，练好了，咱们夜里走在宫里，心里也踏实些。"] = "ǥƽờƾǦƼƾƶǃǦǉƽủǦǤạǦǃƽƾềǊǦǇồƾ,ǦǁǊǓệǃǦǉốǉǦǇồƾ,ǦđƙǂǦƽƇǂǦđƾǦǁạƾǦǉǇǄǃƼǦƸǊǃƼǦƸƽƕǃƼǦǉƶǦƸũǃƼǦǉƽấǓǦǋữǃƼǦǉƁǂǦƽơǃ.",
    ["新春伊始，都来写桃符啊，祛灾纳吉，辟邪安宅，走过路过不要错过——"] = "ǥƁǃǦǍǊƁǃǦǤƾǦǉƽấǉǦ(đầǊǦǍǊƁǃǦǃăǂǦǂớƾ),ǦǂọƾǦǃƼườƾǦđếǃǦǋƾếǉǦđƐǄǦǅƽƖǦđƾ,ǦǀƽứǦǉƶƾǦǃạǅǦƸƑǉ,ǦǉịƸƽǦǉƐǦƶǃǦǉǇạƸƽ,ǦđƾǦǆǊƶǦđƾǦǁạƾǦǍƾǃǦđừǃƼǦƷỏǦǁỡǦ——",
    ["这么多人，怎么都挤在一处去了？"] = "ĐƇǃƼǦǃƼườƾǦǉƽếǦǃƐǓ,ǦǈƶǄǦđềǊǦƸƽƺǃǦƸƽƕƸǦǋƐǄǦǂộǉǦƸƽỗǦǋậǓ?",
    ["都写得不错！这是你的，这是你的，拿回去挂门口——哎别走啊，你也来写几句，图个吉祥如意嘛。"] = "ĐềǊǦǋƾếǉǦǇấǉǦǉốǉ!ǦĐƁǓǦǁƐǦƸủƶǦǃƼươƾ,ǦđƁǓǦǁƐǦƸủƶǦǃƼươƾ,ǦǂƶǃƼǦǋềǦǉǇƺǄǦǉǇướƸǦƸửƶǦ——ǦǀƔƶǦđừǃƼǦđƾǦƸƽứ,ǦǃƼươƾǦƸũǃƼǦǁạƾǦđƁǓǦǋƾếǉǦǋƐƾǦƸƁǊ,ǦƸầǊǦƸƽǄǦƸƑǉǦǉườǃƼǦǃƽưǦƈǦđƾ.",
    ["来，这是你的！"] = "ĐếǃǦđƁǓ,ǦđƁǓǦǁƐǦƸủƶǦǃƼươƾ!",
    ["啧啧啧，老吕，士别三日，真是刮目相看呀。"] = "ƞƽậƸǦƸƽậƸǦƸƽậƸ,ǦƧƃǄǦƧữ,ǦǈĩǦƷƾệǉǦǉƶǂǦǃƽậǉ,ǦǆǊảǦǃƽƾƙǃǦǅƽảƾǦǆǊạǉǦǂụƸǦǉươǃƼǦǀƽƑǃǦ(ǃƽƔǃǦƷằǃƼǦƸǄǃǦǂắǉǦǀƽƑƸ)Ǧǃƽƶ.",
    ["全要！红的赢了就是红红火火，黄的赢l了就是金银万贯，这就叫双押！"] = "ƧấǓǦƽếǉ!ǦƨƐǊǦđỏǦǉƽắǃƼǦǁƐǦƽồǃƼǦƽồǃƼǦƽỏƶǦƽỏƶ,ǦǂƐǊǦǋƐǃƼǦǉƽắǃƼǦǁƐǦǀƾǂǦǃƼƁǃǦǋạǃǦǆǊƑǃ,ǦđƁǓǦƼọƾǦǁƐǦǈǄǃƼǦƑǅ!",
    ["鹅？"] = "ƩƼƶ?",
    ["嘎嘎嘎嘎嘎嘎嘎嘎嘎（我！村霸！不要拦我！让我和这么些个玉米粒儿好好较量一番！！）"] = "ƞạǅǦƸạǅǦƸạǅǦƸạǅǦƸạǅǦƸạǅǦƸạǅǦ(ǥƶ!ǦǥƽƇǃǦƷƑ!ǦĐừǃƼǦƸảǃǦǉƶ!ǦĐểǦǉƶǦƸƖǃƼǦđƑǂǦƽạǉǦǃƼƇǦǃƐǓǦƽảǄǦƽảǄǦǈǄǦǉƐƾǦǂộǉǦǉǇậǃ!!)",
    ["什么玉米粒？！"] = "ƣạǉǦǃƼƇǦƼƔǦƸơ?!",
    ["嘎嘎！嘎嘎！嘎嘎！嘎嘎！（原来是打出来的铁花！欻欻欻全是火花！美哉美哉！不是玉米粒儿！）"] = "ƞạǅǦƸạǅ!ǦƞạǅǦƸạǅ!ǦƞạǅǦƸạǅ!ǦƞạǅǦƸạǅ!Ǧ(ƣƚƶǦǇƶǦǁƐǦǥƽƾếǉǦƣǄƶǦđƑǃƽǦǇƶ!ǦƳǄẹǉǦǍǄẹǉǦǍǄẹǉǦǉǄƐǃǦǁƐǦƽỏƶǦƽǄƶ!ǦƨỹǦǉƶƾǦǂỹǦǉƶƾ!ǦƦƽƇǃƼǦǅƽảƾǦƽạǉǦǃƼƇ!)",
    ["铲子都要冒火星子啦！"] = "ƳẻǃƼǦǈắǅǦǉƚƺǦǁửƶǦǁǊƇǃǦǇồƾ!",
    ["能把开封的猫儿狗儿都招呼来……莫不是幻术吧？"] = "ƞƚǦǉƽểǦƼọƾǦƽếǉǦǂƘǄǦƸƽƚǦởǦƦƽƶƾǦƫƽǄǃƼǦđếǃ...ǦǀƽƇǃƼǦǁẽǦǁƐǦƽǊǓễǃǦǉƽǊậǉǦǈƶǄ?",
    ["刚才...这是怎么回事？"] = "ƱừƶǦǇồƾ...ǦƸƽǊǓệǃǦǃƐǓǦǁƐǦǉƽếǦǃƐǄ?",
    ["你被财神选中了！所以接下来这段时间，你可以变身财神，到处撒钱了！"] = "ƩƼươƾǦđƃǦđượƸǦǥƽầǃǦǥƐƾǦƸƽọǃǦǉǇƕǃƼ!ǦƞƽǄǦǃƙǃǦǉƽờƾǦƼƾƶǃǦǉớƾ,ǦǃƼươƾǦƸƚǦǉƽểǦƷƾếǃǦǉƽƁǃǦǥƽầǃǦǥƐƾ,ǦđƾǦǀƽắǅǦǃơƾǦǅƽƑǉǦǉƾềǃǦǇồƾ!",
    ["就这样选中了吗？是不是有些草率了？如此说来，那你们是...?"] = "ƞứǦǉƽếǦǂƐǦƸƽọǃǦǈƶǄ?ǦƞƚǦǅƽảƾǦƽơƾǦǉƽảǄǦǈǊấǉǦǆǊƑǦǀƽƇǃƼ?ǦƩƚƾǦǃƽưǦǋậǓ,ǦƸƑƸǦǃƼươƾǦǁƐ...?",
    ["别问，我们也只是财富的搬运工。"] = "ĐừǃƼǦƽỏƾ,ǦƸƽƕǃƼǦǉƶǦƸũǃƼǦƸƽỉǦǁƐǦǃƼườƾǦǀƽǊƁǃǦǋƑƸǦǉƐƾǦǅƽƕǦǂƐǦǉƽƇƾ.",
    ["哎，人呢！"] = "Ơ,ǦǃƼườƾǦđƁǊǦǇồƾ!",
    ["还得是你有办法...让刚那个人替我们撒钱，嘿嘿！"] = "ƱẫǃǦǁƐǦǃƼươƾǦƸƚǦƸƑƸƽ...ǦđểǦǃƼườƾǦǋừƶǦǃƃǓǦǉƽƶǓǦƸƽƕǃƼǦǉƶǦǅƽƑǉǦǉƾềǃ,ǦƽƾǦƽƾ!",
    ["那可不，财神交给童子，童子交给善人，福气这就轮转起来啦！"] = "ƞƽứǦǁị,ǦǥƽầǃǦǥƐƾǦƼƾƶǄǦƸƽǄǦĐồǃƼǦǥử,ǦĐồǃƼǦǥửǦƼƾƶǄǦƸƽǄǦǉƽƾệǃǦǃƽƁǃ,ǦǅƽƕƸǦǀƽƓǦƸứǦǉƽếǦǂƐǦǁǊƁǃǦƸƽǊǓểǃǦǉƽƇƾ!",
    ["就这么办！今年听福福的，这个计划准能行！"] = "ƞứǦǆǊǓếǉǦǉƽếǦđƾ!ǦƩăǂǦǃƶǓǦǃƼƽƺǦǁờƾǦƫƽƕƸǦƫƽƕƸ,ǦǀếǦƽǄạƸƽǦǃƐǓǦƸƽǊẩǃǦǁƐǦǉƽƐǃƽǦƸƇǃƼ!",
    ["咱们九流门一出手，就像炮仗一样，嘭——惊天动地！"] = "ƞửǊǦƧưǊǦƨƇǃǦƸƽƕǃƼǦǉƶǦǂộǉǦǀƽƾǦǇƶǦǉƶǓ,ǦǁƾềǃǦƼƾốǃƼǦǃƽưǦǅƽƑǄǦǃổ,ǦđǄƐǃƼǦ——ǦǀƾǃƽǦǉƽƾƙǃǦđộǃƼǦđịƶ!",
    ["嘭什么嘭，照你的主意来，事儿没办完年都过完了。"] = "ĐǄƐǃƼǦƸƑƾǦƼƔǦǂƐǦđǄƐǃƼ,ǦƸứǦǉƽƺǄǦƈǦǃƼươƾǦǉƽƔǦǋƾệƸǦƸƽưƶǦǍǄǃƼǦǥếǉǦđƃǦƽếǉǦǇồƾ.",
    ["那你说个主意出来！"] = "ǥƽếǦǃƼươƾǦđưƶǦǇƶǦƸƽủǦƈǦǍƺǂǦǃƐǄ!",
    ["我这不正在想嘛！还是得找个靠谱的冤大……啊不，帮手！"] = "ǥƶǦƸƽẳǃƼǦǅƽảƾǦđƶǃƼǦǃƼƽĩǦǈƶǄ!ǦƱẫǃǦǁƐǦǃƙǃǦǉƔǂǦǂộǉǦǄƶǃǦđạƾ...ǦƐǦǀƽƇǃƼ,ǦǂộǉǦǉǇợǦǉƽủǦđƑǃƼǦǉƾǃǦƸậǓ!",
    ["又吵起来了……帮手、帮手……哎，阿禄想到了一个人。"] = "ƧạƾǦƸƃƾǦǃƽƶǊǦǇồƾ...ǦǉǇợǦǉƽủ,ǦǉǇợǦǉƽủ...ǦƑƾ,ǦƜǦƧộƸǦǃƼƽĩǦǇƶǦǂộǉǦǃƼườƾ.",
    ["诶，你是说——"] = "Ê,ǦƈǦǃƼươƾǦǁƐǦ——",
    ["这是什么鬼画符？九流门掌门亲笔……三只耗子……偷米缸……还要炸城门？"] = "ĐƁǓǦǁƐǦƷƖƶǦƸƽƕǦǆǊƑƾǦǆǊỷǦƼƔ?ǦƞƽưởǃƼǦǂƇǃǦƞửǊǦƧưǊǦƨƇǃǦǉƽƁǃǦƷƕǉ...ǦƷƶǦƸǄǃǦƸƽǊộǉ...ǦǉǇộǂǦƽũǦƼạǄ...ǦƸƛǃǦǂǊốǃǦǉạƸǦǉƽƐǃƽǦǂƇǃ?",
    ["今夜子时速来相见！共谋大业！口令——鼠鼠生威！"] = "ĐƙǂǦǃƶǓǦƼƾờǦǥƈǦǂƶǊǦđếǃǦǉươǃƼǦǀƾếǃ!ǦƞộǃƼǦǂưǊǦđạƾǦǃƼƽƾệǅ!ǦƦƽẩǊǦǁệǃƽǦ——ǦǥƽửǦǥƽửǦƮƾǃƽǦǕǓ!",
    ["不知道葫芦里卖的什么药……罢了，还是去一趟吧。"] = "ƦƽƇǃƼǦƷƾếǉǦǉǇǄǃƼǦƽồǦǁƇǦƷƑǃǦǉƽǊốƸǦƼƔ...ǦǉƽƇƾǦǋậǓ,ǦƸứǦđƾǦǂộǉǦƸƽǊǓếǃǦǍƺǂǦǈƶǄ.",
    ["游侠，口令？"] = "ǝǊǦƽƾệǅ,ǦǀƽẩǊǦǁệǃƽ?",
    ["对上了！嘿嘿，这口令喊得真有气势！掌门就在里面，快请进！"] = "ƦƽớǅǦǇồƾ!ǦƣƾǦƽƾ,ǦǀƽẩǊǦǁệǃƽǦǃƐǓǦƽƇǦǉƽậǉǦƸƚǦǀƽƓǦǉƽế!ǦƞƽưởǃƼǦǂƇǃǦởǦǃƼƶǓǦƷƙǃǦǉǇǄǃƼ,ǦǂờƾǦǋƐǄ!",
    ["掌门等您多时了，说是这回过年要搞个把天捅破的大动静！"] = "ƞƽưởǃƼǦǂƇǃǦđợƾǦǃƼƐƾǦđƃǦǁƁǊ,ǦǃƚƾǦǁƐǦǅƽƺǃǦǃƐǓǦăǃǦǥếǉǦǅƽảƾǦǁƐǂǦǂộǉǦƸƽǊǓệǃǦđộǃƼǦǉǇờƾ!",
    ["……该不会真要炸皇宫吧？"] = "...ƦƽƇǃƼǦǁẽǦđịǃƽǦǉạƸǦƽǄƐǃƼǦƸǊǃƼǦǉƽậǉǦƸƽứ?",
    ["……钱不够，粮也不够！福福挨个米缸看过了，比我的脸都干净！"] = "...ǥƾềǃǦǀƽƇǃƼǦđủ,ǦǁươǃƼǦƸũǃƼǦǀƽƇǃƼǦđủ!ǦƫƽƕƸǦƫƽƕƸǦđƃǦǍƺǂǦǆǊƶǦǉừǃƼǦƽũǦƼạǄǦǇồƾ,ǦƸƛǃǦǈạƸƽǦƽơǃǦƸảǦǂặǉǦǂǊộƾǦǃữƶ!",
    ["早说过了还不信……唉，我和小禄可是到城里仔细打探了一番！"] = "ĐƃǦǃƚƾǦǇồƾǦǂƐǦǀƽƇǃƼǦǉƾǃ...ǦƽƶƾǏǏ,ǦǉƶǦǋƐǦǥƾểǊǦƧộƸǦđƃǦǋƐǄǦǉƽƐǃƽǦǉƽƑǂǦǉƽƓǃƽǦǂộǉǦǅƽƺǃǦǇồƾ!",
    ["猜猜，这开封城里哪儿油水最多？"] = "ĐǄƑǃǦǍƺǂ,ǦǉǇǄǃƼǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦǃƐǓǦǃơƾǦǃƐǄǦǃƽƾềǊǦǤầǊǦǂỡǦǃƽấǉ?",
    ["……反正不是咱家。"] = "...ǝƖǦǈƶǄǦƸũǃƼǦǀƽƇǃƼǦǅƽảƾǦǃƽƐǦǉƶ.",
    ["城里都在传，皇帝打了好几场胜仗，拿到好多好多宝贝。"] = "ǥǇǄǃƼǦǉƽƐǃƽǦđềǊǦǉǇǊǓềǃǦǉƶƾǦǃƽƶǊ,ǦƽǄƐǃƼǦđếǦđƑǃƽǦǉƽắǃƼǦǂấǓǦǉǇậǃǦǁƾềǃ,ǦǉƽǊǦđượƸǦǇấǉǦǃƽƾềǊǦƷảǄǦƷốƾ.",
    ["宝贝多得放不下了……就在宫里盖个大宝库，全是金银财宝呢。"] = "ƝảǄǦƷốƾǦǃƽƾềǊǦđếǃǦǂứƸǦǀƽƇǃƼǦƸƛǃǦƸƽỗǦđể...ǦƷƘǃǦǍƁǓǦǂộǉǦđạƾǦƷảǄǦǀƽốǦǉǇǄǃƼǦƸǊǃƼ,ǦǉǄƐǃǦǁƐǦǀƾǂǦǃƼƁǃǦǉƐƾǦƷảǄǦǉƽƇƾ.",
    ["宝库！宝库好啊，咱们要是能……嘿嘿……"] = "ƝảǄǦǀƽố!ǦƝảǄǦǀƽốǦǉốǉǦǃƽƶ,ǦƸƽƕǃƼǦǉƶǦǃếǊǦƸƚǦǉƽể...ǦƽƾǦƽƾ...",
    ["《屋内>真是个好主意……"] = "<ǥǇǄǃƼǦǃƽƐ>ǦĐƕǃƼǦǁƐǦǂộǉǦƸƽủǦƈǦƽƶǓ...",
    ["道主约我前来，有何指教？"] = "ĐạǄǦƸƽủǦƽẹǃǦǉƶǦđếǃǦđƁǓ,ǦƸƚǦƼƔǦƸƽỉǦƼƾƑǄ?",
    ["说帮手，帮手到，你可来了！"] = "ƩƽắƸǦǉǇợǦǉƽủ,ǦǉǇợǦǉƽủǦđếǃ,ǦǃƼươƾǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦǉớƾǦǇồƾ!",
    ["哪来的帮手……现在天下刚太平几天，这就要造反啦？"] = "ǥǇợǦǉƽủǦởǦđƁǊǦǇƶ...ǦǉƽƾƙǃǦƽạǦǂớƾǦǉƽƑƾǦƷƔǃƽǦđượƸǦǂấǓǦǃƼƐǓ,ǦđƁǓǦǁƐǦǂǊốǃǦǉạǄǦǅƽảǃǦǈƶǄ?",
    ["……造反？我们没有……"] = "...ǥạǄǦǅƽảǃ?ǦƞƽƕǃƼǦǉƶǦǀƽƇǃƼǦƸƚ...",
    ["你们寄来的信件，图上画得明明白白——"] = "ǥƽưǦƸƑƸǦǃƼươƾǦƼửƾǦđếǃ,ǦǉǇƙǃǦƽƔǃƽǦǋẽǦǇƐǃƽǦǇƐǃƽǦǇƶǦđƚǦ——",
    ["火树银花图，我画得真好！"] = "ƣỏƶǦǥƽụǦƩƼƁǃǦƣǄƶǦđồ,ǦǂǊộƾǦǋẽǦđẹǅǦǉƽậǉǦđấǓ!",
    ["画得不像嘛？……都是小寿画的！"] = "ƱẽǦǀƽƇǃƼǦƼƾốǃƼǦǈƶǄ?Ǧ...ĐềǊǦǁƐǦǥƾểǊǦǥƽọǦǋẽǦđƚ!",
    ["原来是年画啊？"] = "ƣƚƶǦǇƶǦǁƐǦǉǇƶǃƽǦǥếǉǦƐ?",
    ["你行你画！好了，大个子，我们是喊你帮忙筹粮的。"] = "ƣǊǓǃƽǦƼƾỏƾǦǉƽƔǦƽǊǓǃƽǦǋẽǦđƾ!ǦĐượƸǦǇồƾ,ǦĐạƾǦƸƑǦǉử,ǦƸƽƕǃƼǦǉƶǦƼọƾǦƽǊǓǃƽǦđếǃǦǁƐǦđểǦƼƾƕǅǦƼǄǂǦǁươǃƼǦǉƽựƸ.",
    ["如今不打仗了，日子也好过些了，可城里还是有揭不开锅的人。"] = "ƩƶǓǦǀƽƇǃƼǦƸƛǃǦđƑǃƽǦǉǇậǃ,ǦǃƼƐǓǦǉƽƑǃƼǦƸũǃƼǦǤễǦǉƽởǦƽơǃ,ǦǃƽưǃƼǦǉǇǄǃƼǦǉƽƐǃƽǦǋẫǃǦƸƛǃǦǃƽữǃƼǦǃƼườƾǦƸơǂǦǀƽƇǃƼǦđủǦăǃ.",
    ["平日里也就算了……饿肚子过大年，光是想想，福福都难受得很。"] = "ƩƼƐǓǦǉƽườǃƼǦǉƽƔǦǉƽƇƾǦđƾ...ǦǃƽưǃƼǦǃƽịǃǦđƚƾǦǆǊƶǦǃăǂǦǂớƾ,ǦƸƽỉǦǃƼƽĩǦǉƽƇƾǦƫƽƕƸǦƫƽƕƸǦđƃǦǉƽấǓǦǇấǉǦǀƽƚǦƸƽịǊǦǇồƾ.",
    ["俗话说得好，一只耗子易被逮，一群耗子能移山！"] = "ǥụƸǦǃƼữǦƸƚǦƸƁǊ,ǦǂộǉǦƸǄǃǦƸƽǊộǉǦǤễǦƷịǦǉƚǂ,ǦǂộǉǦđƐǃǦƸƽǊộǉǦƸƚǦǉƽểǦǤờƾǦǃƕƾ!",
    ["与其各家冷冷清清，不如大伙凑在一起，有钱出钱，有力出力，过个饱年！"] = "ǥƽƶǓǦǋƔǦǃƽƐǦǃƐǄǦǃƽƐǦǃấǓǦǁạǃƽǦǁẽǄ,ǦƸƽẳǃƼǦǉƽƐǦǂọƾǦǃƼườƾǦǉụǦƽọǅǦǁạƾ,ǦƸƚǦǉƾềǃǦƼƚǅǦǉƾềǃ,ǦƸƚǦǁựƸǦƼƚǅǦǁựƸ,ǦăǃǦǂộǉǦƸƑƾǦǥếǉǦǉƽậǉǦǃǄǦǃƙ!",
    ["幸好只是办年集，真把我吓了一跳。"] = "ƨƶǓǦǂƐǦƸƽỉǦǁƐǦǉổǦƸƽứƸǦƸƽợǦǥếǉ,ǦǉƽậǉǦǁƐǂǦǉƶǦƽƕǦǋƓƶ.",
    ["等等，去皇宫“借”粮，又是怎么回事？"] = "ƦƽǄƶǃǦđƃ,ǦđƾǦƽǄƐǃƼǦƸǊǃƼǦ\"ǂượǃ\"ǦǁươǃƼ,ǦǁạƾǦǁƐǦƸƽǊǓệǃǦƼƔǦǉƽế?",
    ["嘿嘿，皇帝那么多财宝，少一点点，不会被发现啦。"] = "ƣƾǦƽƾ,ǦƽǄƐǃƼǦđếǦǃƽƾềǊǦǉƐƾǦƷảǄǦǃƽưǦǋậǓ,ǦǉƽƾếǊǦǂộǉǦƸƽƕǉǦǍƓǊǦǈẽǦǀƽƇǃƼǦƷịǦǅƽƑǉǦƽƾệǃǦđƁǊ.",
    ["我们溜进去，就偷……不是，就借一点点嘛。有借有还……等大伙过好这个年了，慢慢还给皇帝。"] = "ƞƽƕǃƼǦǉƶǦǁẻǃǦǋƐǄ,ǦǉǇộǂ...ǦǀƽƇǃƼǦǅƽảƾ,ǦǂượǃǦǂộǉǦƸƽƕǉǦǍƓǊǦǉƽƇƾǦǂƐ.ǦƞƚǦǂượǃǦƸƚǦǉǇả...ǦđợƾǦǂọƾǦǃƼườƾǦăǃǦǥếǉǦǍǄǃƼǦǇồƾ,ǦǈẽǦǉừǦǉừǦǉǇảǦǁạƾǦƸƽǄǦƽǄƐǃƼǦđế.",
    ["去皇宫偷……别拿命开玩笑。"] = "ƱƐǄǦƽǄƐǃƼǦƸǊǃƼǦǉǇộǂ...ǦđừǃƼǦđƺǂǦǉƓǃƽǦǂạǃƼǦǇƶǦđƖƶ.",
    ["那、我们要怎么做才好…………"] = "ƱậǓ,ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦǁƐǂǦǈƶǄǦǂớƾǦǉốǉǦđƁǓ............",
    ["既然是做好事，咱们就正大光明地办！"] = "ĐƃǦǁƐǦǁƐǂǦǋƾệƸǦǉƽƾệǃ,ǦƸƽƕǃƼǦǉƶǦƸứǦǤƶǃƽǦƸƽƓǃƽǦǃƼƇǃǦǉƽǊậǃǦǂƐǦǁƐǂ!",
    ["第一步，做计划。既然缺钱粮，我倒想了一些生财的门道，只是需要不少人手。"] = "ƝướƸǦđầǊǦǉƾƙǃ,ǦǁậǅǦǀếǦƽǄạƸƽ.ǦĐƃǦǉƽƾếǊǦǉƾềǃǦǁươǃƼ,ǦǉƶǦƸƚǦǃƼƽĩǦǇƶǦǋƐƾǦđườǃƼǦǁốƾǦǈƾǃƽǦǉƐƾ,ǦƸƽỉǦǁƐǦƸầǃǦǀƽƇǃƼǦƓǉǦǃƽƁǃǦǉƽủ.",
    ["其次嘛……既然是九流门要做，那就发挥特长——诶！可不是让你们发挥那个特长，不许偷，不许骗，也不许上街要。"] = "ƦếǦđếǃ...ǦđƃǦǁƐǦƞửǊǦƧưǊǦƨƇǃǦǁƐǂ,ǦǋậǓǦǉƽƔǦǅƽƑǉǦƽǊǓǦđặƸǦǉǇườǃƼǦ——Ǧƙ!ǦƦƽƇǃƼǦǅƽảƾǦƷảǄǦƸƑƸǦǃƼươƾǦǅƽƑǉǦƽǊǓǦƸƑƾǦđặƸǦǉǇườǃƼǦǀƾƶ,ǦǀƽƇǃƼǦđượƸǦǉǇộǂ,ǦǀƽƇǃƼǦđượƸǦǁừƶ,ǦƸũǃƼǦǀƽƇǃƼǦđượƸǦǇƶǦđườǃƼǦǍƾǃǦǍỏ.",
    ["九流门的特长……"] = "ĐặƸǦǉǇườǃƼǦƸủƶǦƞửǊǦƧưǊǦƨƇǃ...",
    ["我知道！人手多，对不对？——找人的事情，包在我们身上！大个子，你还有什么计划，快说！"] = "ƨǊộƾǦƷƾếǉ!ǦƩƽƁǃǦǉƽủǦđƇǃƼ,ǦđƕǃƼǦǀƽƇǃƼ?Ǧ——ǦƱƾệƸǦǉƔǂǦǃƼườƾǦƸứǦƼƾƶǄǦƸƽǄǦǉụƾǦǂǊộƾ!ǦĐạƾǦƸƑǦǉử,ǦƽǊǓǃƽǦƸƛǃǦǀếǦƽǄạƸƽǦƼƔǦǃữƶ,ǦǂƶǊǦǃƚƾǦđƾ!",
    ["快说快说！"] = "ƨƶǊǦǃƚƾǦǂƶǊǦǃƚƾ!",
    ["大个子，你看这地段，是不是最适合办集市？"] = "ĐạƾǦƸƑǦǉử,ǦƽǊǓǃƽǦǍƺǂǦđịƶǦđǄạǃǦǃƐǓ,ǦƸƚǦǅƽảƾǦǁƐǦǃơƾǦǉƽƓƸƽǦƽợǅǦǃƽấǉǦđểǦǂởǦǉậǅǦǉƽịǦǀƽƇǃƼ?",
    ["我们已经跟九流门的兄弟姐妹打好招呼了，和附近住户聊聊，租下空地来办集市。"] = "ƞƽƕǃƼǦǉƶǦđƃǦđƑǃƽǦǉƾếǃƼǦǋớƾǦƽǊǓǃƽǦđệǦǉỷǦǂǊộƾǦƞửǊǦƧưǊǦƨƇǃǦǇồƾ,ǦǈẽǦǉƽươǃƼǦǁượǃƼǦǋớƾǦƸƑƸǦƽộǦǤƁǃǦǍǊǃƼǦǆǊƶǃƽǦđểǦǉƽǊƙǦđấǉǦǉǇốǃƼǦǂởǦǉậǅǦǉƽị.",
    ["不收租金的话，免费送好地段的摊位，可以卖卖年货。"] = "ƩếǊǦǀƽƇǃƼǦǉƽǊǦǉƾềǃǦǉƽǊƙ,ǦǉặǃƼǦǀƽƇǃƼǦƸƑƸǦǈạǅǦƽƐǃƼǦởǦǋịǦǉǇƓǦǉốǉ,ǦƸƚǦǉƽểǦƷƑǃǦƓǉǦđồǦǥếǉ.",
    ["这地方不错啊……我就提一嘴大过年的，最挣钱的莫过于开集赶集，没想到你们小小年纪还挺有办法，这就筹备起来了。"] = "ƞƽỗǦǃƐǓǦǀƽƇǃƼǦǉồƾǦǃƽƶ...ǦǉƶǦƸƽỉǦǉƽǊậǃǦǂƾệǃƼǦǃƚƾǦǥếǉǦǃƽấǉǦǉƽƔǦǀƾếǂǦǉƾềǃǦǃƽấǉǦǀƽƇǃƼǦƼƔǦƷằǃƼǦǂởǦƸƽợǦƽọǅǦƸƽợ,ǦǀƽƇǃƼǦǃƼờǦƸƑƸǦǃƼươƾǦǉǊổƾǦƸƛǃǦǃƽỏǦǂƐǦǀƽƑǦƸƚǦƸƑƸƽ,ǦđƃǦƷắǉǦđầǊǦƸƽǊẩǃǦƷịǦǇồƾ.",
    ["鉴于大个子慷慨相助，咱们三合计了一下，决定封你为百味集之主——简称“集主”！"] = "ƳƗǉǦǉƽấǓǦĐạƾǦƸƑǦǉửǦǀƽẳǃƼǦǀƽƑƾǦǉươǃƼǦǉǇợ,ǦƷƶǦǃƼườƾǦǉụƾǦǂǊộƾǦđƃǦƷƐǃǦƷạƸ,ǦǆǊǓếǉǦđịǃƽǦǅƽǄǃƼǦƽǊǓǃƽǦǁƐǂǦƝƑƸƽǦƱịǦǥậǅǦƸƽƾǦƸƽủǦ——ǦƼọƾǦǉắǉǦǁƐǦ\"ǥậǅǦƸƽủ\"!",
    ["能不能换个更威风的？"] = "ƞƚǦǉƽểǦđổƾǦƸƑƾǦǃƐǄǦǄƶƾǦǅƽǄǃƼǦƽơǃǦǀƽƇǃƼ?",
    ["威风……那就叫“话事人”，霸气！一听就是道上的，官军看了都要绕道走！"] = "ƪƶƾǦǅƽǄǃƼ...ǦǋậǓǦƼọƾǦǁƐǦ\"ǥƽǄạƾǦǈựǦǃƽƁǃ\",ǦƷƑǦǀƽƓ!ǦƩƼƽƺǦǂộǉǦƸƑƾǦǁƐǦƷƾếǉǦǃƼườƾǦǉǇǄǃƼǦƼƾớƾ,ǦǆǊƶǃǦǆǊƁǃǦǉƽấǓǦƸũǃƼǦǅƽảƾǦđƾǦǋƛǃƼ!",
    ["……道上的？"] = "...ƩƼườƾǦǉǇǄǃƼǦƼƾớƾ?",
    ["头衔不重要。既然接了这活儿，咱们就得按规矩来。在我清河老家，这时候乡亲们早忙活起来了。"] = "ĐầǊǦƽƐǂǦǀƽƇǃƼǦǆǊƶǃǦǉǇọǃƼ.ǦĐƃǦǃƽậǃǦǋƾệƸǦǃƐǓ,ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦǉƽƺǄǦǆǊǓǦƸủ.ǦỞǦǆǊƙǦǃƽƐǦǥƽƶǃƽǦƣƐǦƸủƶǦǉƶ,ǦǉầǂǦǃƐǓǦƷƐǦƸǄǃǦǁốƾǦǍƚǂǦđƃǦƷậǃǦǇộǃǦƸảǦǇồƾ.",
    ["地段定好了，可摆摊设市的地方，还全空着呢。得把江湖上的朋友都叫上，各展所长。"] = "ĐịƶǦđǄạǃǦđịǃƽǦǍǄǃƼǦǇồƾ,ǦǃƽưǃƼǦƸƽỗǦƷƐǓǦǈạǅǦƽọǅǦƸƽợǦǋẫǃǦƸƛǃǦǉǇốǃƼǦǀƽƇǃƼ.ǦƫƽảƾǦƼọƾǦƷằǃƼǦƽữǊǦǉǇƙǃǦƼƾƶǃƼǦƽồǦđếǃ,ǦǂỗƾǦǃƼườƾǦǉǇổǦǂộǉǦǉƐƾǦǇƾƙǃƼ.",
    ["有道理！那、我去写信……"] = "ƞƚǦǁƈ!ǦƱậǓ,ǦǂǊộƾǦđƾǦǋƾếǉǦǉƽư...",
    ["要再画出一幅“耗子炸街图”，得把人都吓跑……无妨，还是我跑一趟吧。"] = "ƩếǊǦǁạƾǦǋẽǦǇƶǦǂộǉǦƷứƸǦ\"ƞƽǊộǉǦǉạƸǦǅƽốǦđồ\",ǦƸƽắƸǦǤọƶǦǃƼườƾǦǉƶǦƸƽạǓǦǈạƸƽ...ǦǀƽƇǃƼǦǈƶǄ,ǦđểǦǉƶǦđƾǦǂộǉǦƸƽǊǓếǃǦǋậǓ.",
    ["那个……有几封信，我们已经送出去了……"] = "ƞƑƾǦđƚ...ǦƸƚǦǂấǓǦǅƽǄǃƼǦǉƽư,ǦǉụƾǦǂǊộƾǦđƃǦƼửƾǦđƾǦǇồƾ...",
    ["……送去哪里了？"] = "...ƢửƾǦđƾǦđƁǊǦǇồƾ?",
    ["她们仨也是机灵。最该邀请的，可不是同在开封城的醉花阴嘛。"] = "ƝƶǦđứƶǦǉụƾǦǃƚǦƸũǃƼǦǉƽậǉǦǁƶǃƽǦǁợƾ.ǦƩƼườƾǦƸầǃǦǂờƾǦǃƽấǉ,ǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǥƕǓǦƣǄƶǦƀǂǦƸũǃƼǦởǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦǈƶǄ.",
    ["哼……向醉花阴下战书？这倒有趣。"] = "ƣừ...ǦƼửƾǦƸƽƾếǃǦǉƽưǦƸƽǄǦǥƕǓǦƣǄƶǦƀǂ?ǦƞƽǊǓệǃǦǃƐǓǦǉƽƕǦǋịǦđƁǓ.",
    ["信封上还有好几朵墨点子，难道……"] = "ǥǇƙǃǦǅƽǄǃƼǦǉƽưǦƸƛǃǦƸƚǦǂấǓǦǋếǉǦǂựƸǦǁǄƶǃƼ,ǦǁẽǦǃƐǄ...",
    ["辛夷姐姐，信……你已收到了？"] = "ǥƁǃǦǝƾǦǉỷǦǉỷ,Ǧǉƽư...ǦǉỷǦđƃǦǃƽậǃǦđượƸǦƸƽưƶ?",
    ["红绡坊的生意向来好，每天订单不计其数，寄给我的花笺也有不少……你说的信，又是哪一封？"] = "ƧƐǂǦăǃǦởǦƣồǃƼǦǥƾƙǊǦƫƽườǃƼǦǍưƶǦǃƶǓǦǁǊƇǃǦǉốǉ,ǦǂỗƾǦǃƼƐǓǦđơǃǦđặǉǦƽƐǃƼǦǃƽƾềǊǦǀƽƇǃƼǦđếǂǦǍǊể,ǦƽǄƶǦǉƾƙǃǦƼửƾǦƸƽǄǦǉƶǦƸũǃƼǦǀƽƇǃƼǦƓǉ...ǦǉƽưǦǃƼươƾǦǃƚƾǦǁƐǦǅƽǄǃƼǦǃƐǄ?",
    ["就是眼前让姐姐不快的这封了。"] = "ƞƽƓǃƽǦǁƐǦǅƽǄǃƼǦđƶǃƼǦǁƐǂǦǉỷǦǉỷǦǀƽƇǃƼǦǋǊƾǦǉǇướƸǦǂắǉǦđƁǓ.",
    ["看来梨园有人先向你走漏了风声。这次他们主动发难，你知道多少？"] = "ƳƺǂǦǇƶǦƸƚǦǃƼườƾǦởǦƧƙǦƱƾƙǃǦđƃǦǇƛǦǇỉǦǉƾǃǦǉứƸǦƸƽǄǦǃƼươƾǦǉǇướƸǦǇồƾ.ǦƧầǃǦǃƐǓǦƷọǃǦƽọǦƸƽủǦđộǃƼǦƼƁǓǦƽấǃ,ǦǃƼươƾǦƷƾếǉǦƷƶǄǦǃƽƾƙǊ?",
    ["前些日子梨园兴办争籁大会，声势浩大，引得我醉花阴不少弟子心生向往。"] = "ƨấǓǦǃƼƐǓǦǉǇướƸǦƧƙǦƱƾƙǃǦǉổǦƸƽứƸǦǥǇƶǃƽǦƧạƾǦđạƾǦƽộƾ,ǦǉƽƶǃƽǦǉƽếǦǋƶǃƼǦǤộƾ,ǦǀƽƾếǃǦǀƽƇǃƼǦƓǉǦđệǦǉửǦǥƕǓǦƣǄƶǦƀǂǦƸủƶǦǉƶǦǈƾǃƽǦǁƛǃƼǦƽướǃƼǦǋọǃƼ.",
    ["更有甚者，抛却红尘情缘，毅然投奔梨园追求乐舞之道。"] = "ǥƽậǂǦƸƽƓǦƸƚǦǀẻǦƸƛǃǦǤứǉǦƷỏǦƽồǃƼǦǉǇầǃǦǉƔǃƽǦǤǊǓƙǃ,ǦǤứǉǦǀƽǄƑǉǦđầǊǦǆǊƁǃǦƸƽǄǦƧƙǦƱƾƙǃǦđểǦǉƽƺǄǦđǊổƾǦđạǄǦǃƽạƸǦǂƕƶ.",
    ["天地之大，情起情灭，本是来去自由。"] = "ǥƽƾƙǃǦđịƶǦƷƶǄǦǁƶ,ǦǉƔǃƽǦǀƽởƾǦǉƔǃƽǦǤƾệǉ,ǦǋốǃǦǁƐǦđếǃǦđƾǦǉựǦǤǄ.",
    ["我们若多言半句，倒显得醉花阴气量狭小，容不下人了。"] = "ƞƽƕǃƼǦǉƶǦǃếǊǦǃƚƾǦǉƽƙǂǦǃửƶǦǁờƾ,ǦǁạƾǦƽƚƶǦǇƶǦǥƕǓǦƣǄƶǦƀǂǦǀƽƓǦǁượǃƼǦƽẹǅǦƽƛƾ,ǦǀƽƇǃƼǦǤǊǃƼǦǃổƾǦǃƼườƾ.",
    ["这些日子我们忙着准备春日花馔，分赠邻里。没想到梨园还不罢休，特意送来这般图画羞辱。"] = "ƨấǓǦǃƼƐǓǦǆǊƶǦƸƽƕǃƼǦǉƶǦƷậǃǦǇộǃǦƸƽǊẩǃǦƷịǦǍǊƁǃǦǃƽậǉǦƽǄƶǦǈǄạǃǦđểǦǉặǃƼǦǍƚǂǦƼƾềǃƼ.ǦƦƽƇǃƼǦǃƼờǦƧƙǦƱƾƙǃǦǋẫǃǦƸƽưƶǦƸƽịǊǦǉƽƇƾ,ǦƸƛǃǦđặƸǦƷƾệǉǦƼửƾǦǁǄạƾǦƽƔǃƽǦǋẽǦǃƐǓǦđếǃǦǃƽụƸǦǂạ.",
    ["你且看这封信，醉花阴和梨园两门弟子怒目而视，岂非宣战之意？"] = "ƩƼươƾǦǍƺǂǦǅƽǄǃƼǦǉƽưǦǃƐǓ,ǦđệǦǉửǦƽƶƾǦǂƇǃǦǅƽƑƾǦǥƕǓǦƣǄƶǦƀǂǦǋƐǦƧƙǦƱƾƙǃǦǉǇợǃǦǂắǉǦǃƽƔǃǦǃƽƶǊ,ǦƸƽẳǃƼǦǅƽảƾǦǁƐǦƈǦǉǊǓƙǃǦƸƽƾếǃǦǈƶǄ?",
    ["这信上的画风如此……豪放，怎么看也不像是梨园的手笔啊。"] = "ƫƽǄǃƼǦƸƑƸƽǦǋẽǦǉǇƙǃǦǉƽưǦǃƐǓǦǉƽậǉǦǁƐ...ǦƽƐǄǦǅƽƚǃƼ,ǦǃƽƔǃǦǉƽếǦǃƐǄǦƸũǃƼǦǀƽƇǃƼǦƼƾốǃƼǦǉƽủǦƷƕǉǦƸủƶǦƧƙǦƱƾƙǃ.",
    ["特意寻来这般孩童涂鸦，这其中的讽刺之意，难道还不够明显吗？"] = "ĐặƸǦƷƾệǉǦǉƔǂǦǁǄạƾǦǉǇƶǃƽǦǉǇẻǦƸǄǃǦǋẽǦƷậǓǦǉƽếǦǃƐǓ,ǦƈǦƸƽƁǂǦƷƾếǂǦǉǇǄǃƼǦđƚǦǁẽǦǃƐǄǦƸƛǃǦƸƽưƶǦđủǦǇƅǦǇƐǃƼǦǈƶǄ?",
    ["况且……送信的孩童放下战书就走了，步伐轻盈，可不是普通娃娃能有的身手。"] = "ƣǊốǃƼǦƽồ...ǦđứƶǦǉǇẻǦđưƶǦǉƽưǦđặǉǦƸƽƾếǃǦǉƽưǦǍǊốǃƼǦǁƐǦđƾǦǃƼƶǓ,ǦƷộǦǅƽƑǅǦǃƽẹǦǃƽƐǃƼ,ǦǀƽƇǃƼǦǅƽảƾǦǁƐǦǉƽƁǃǦǉƽủǦǂƐǦǂộǉǦđứƶǦǉǇẻǦƷƔǃƽǦǉƽườǃƼǦƸƚǦǉƽểǦƸƚ.",
    ["既然战书已下，会会他们也好。"] = "ĐƃǦƽạǦƸƽƾếǃǦǉƽư,ǦƼặǅǦǂặǉǦƷọǃǦƽọǦǂộǉǦǅƽƺǃǦƸũǃƼǦǉốǉ.",
    ["哎！别冲动——！"] = "Áƾ!ǦĐừǃƼǦǂƶǃƽǦđộǃƼǦ——!",
    ["哇！漂亮姐姐！你终于来啦！"] = "ƪƶ!ǦǥỷǦǉỷǦǍƾǃƽǦđẹǅ!ǦƞǊốƾǦƸƖǃƼǦǉỷǦƸũǃƼǦǉớƾǦǇồƾ!",
    ["是你……送信的小娃娃？你家大人呢？梨园的主事在哪里？"] = "ƧƐǦǃƼươƾ...ǦđứƶǦǃƽỏǦđưƶǦǉƽư?ǦƩƼườƾǦǁớǃǦǃƽƐǦǃƼươƾǦđƁǊ?ǦƞƽủǦǈựǦƸủƶǦƧƙǦƱƾƙǃǦởǦđƁǊ?",
    ["什么梨园？福福我就是来找姐姐的呀！"] = "ƧƙǦƱƾƙǃǦƼƔǦƸơ?ǦƫƽƕƸǦƫƽƕƸǦǁƐǦđếǃǦǉƔǂǦǉỷǦǉỷǦǂƐ!",
    ["福福上回路过樊楼，姐姐们正在给街坊送花糕。甜甜的，香香的，我们头一回吃到这么好吃的糕点！"] = "ƫƽƕƸǦƫƽƕƸǦǁầǃǦǉǇướƸǦđƾǦǃƼƶǃƼǦǆǊƶǦƫƽƐǃǦƧầǊ,ǦǉƽấǓǦƸƑƸǦǉỷǦǉỷǦđƶǃƼǦǉặǃƼǦƷƑǃƽǦƽǄƶǦƸƽǄǦǁốƾǦǍƚǂ.ǦƩƼọǉǦǃƼọǉ,ǦǉƽơǂǦǉƽơǂ,ǦǉụƾǦƺǂǦǁầǃǦđầǊǦǉƾƙǃǦđượƸǦăǃǦƷƑǃƽǦǃƼǄǃǦǃƽưǦǋậǓ!",
    ["姐姐……能不能教教我们怎么做呀？"] = "ǥỷǦǉỷ...ǦƸƚǦǉƽểǦǤạǓǦǉụƾǦƺǂǦǁƐǂǦǉƽếǦǃƐǄǦǀƽƇǃƼ?",
    ["教你们……做花糕？那这封信上的……"] = "ǝạǓǦƸƑƸǦǃƼươƾ...ǦǁƐǂǦƷƑǃƽǦƽǄƶ?ǦƱậǓǦƸƛǃǦǉǇƙǃǦǅƽǄǃƼǦǉƽưǦǃƐǓ...",
    ["这个圆圈是梨园的甜豆。这朵花花是醉花阴的花糕！"] = "ƞƑƾǦǋƛǃƼǦǉǇƛǃǦǃƐǓǦǁƐǦđậǊǦǃƼọǉǦƸủƶǦƧƙǦƱƾƙǃ.ǦƝƇǃƼǦƽǄƶǦǃƐǓǦǁƐǦƷƑǃƽǦƽǄƶǦƸủƶǦǥƕǓǦƣǄƶǦƀǂ!",
    ["左手拿一个，右手拿一个……我们都想学……"] = "ǥƶǓǦǉǇƑƾǦƸầǂǦǂộǉǦƸƑƾ,ǦǉƶǓǦǅƽảƾǦƸầǂǦǂộǉǦƸƑƾ...ǦǉụƾǦƺǂǦđềǊǦǂǊốǃǦƽọƸ...",
    ["辛夷姐姐！都说了是误会！"] = "ǥƁǃǦǝƾǦǉỷǦǉỷ!ǦĐƃǦƷảǄǦǁƐǦƽƾểǊǦǁầǂǦǂƐ!",
    ["原来是办集市……这画技，当真是……别具一格。"] = "ƣƚƶǦǇƶǦǁƐǦǉổǦƸƽứƸǦǉậǅǦǉƽị...ǦƽọƶǦǀỹǦǃƐǓǦđƕǃƼǦǁƐ...ǦđộƸǦǃƽấǉǦǋƇǦǃƽị.",
    ["这事 I 先应了，你且放心回去，我自会禀报掌门。"] = "ƞƽǊǓệǃǦǃƐǓǦǉƶǦǃƽậǃǦǁờƾǦǉǇướƸ,ǦǃƼươƾǦƸứǦǓƙǃǦǉƁǂǦǆǊƶǓǦǋề,ǦǉƶǦǉựǦƸƚǦƸƑƸƽǦƷẩǂǦƷƑǄǦƸƽưởǃƼǦǂƇǃ.",
    ["只是……我门中菜肴制作费时，花糕工艺繁复，年集上人来人往，怕是供不应求，反倒扫了大家的兴致。"] = "ƞƽỉǦǁƐ...ǦǂƚǃǦăǃǦǉǇǄǃƼǦǂƇǃǦǅƽƑƾǦǉƶǦƸƽếǦƷƾếǃǦǉốǃǦǉƽờƾǦƼƾƶǃ,ǦƸƇǃƼǦǃƼƽệǦƷƑǃƽǦƽǄƶǦǅƽứƸǦǉạǅ,ǦƸƽợǦǥếǉǦǃƼườƾǦǆǊƶǦǀẻǦǁạƾǦđƇǃƼǦđƕƸ,ǦƺǦǁƐǦƸǊǃƼǦǀƽƇǃƼǦđủǦƸầǊ,ǦǃƼượƸǦǁạƾǦǁƐǂǦǂấǉǦƽứǃƼǦǂọƾǦǃƼườƾ.",
    ["樊楼如今的冬令鲜花美不胜收，倒不如我们改卖鲜花，赠人玫瑰，手有余香。"] = "ƫƽƐǃǦƧầǊǦƽƾệǃǦƼƾờǦƽǄƶǦǉươƾǦǂƖƶǦđƇǃƼǦđẹǅǦǀƽƇǃƼǦǈƶǄǦǉảǦǍƾếǉ,ǦƽƶǓǦǁƐǦƸƽƕǃƼǦǉƶǦƸƽǊǓểǃǦǈƶǃƼǦƷƑǃǦƽǄƶǦǉươƾ,ǦǉặǃƼǦǃƼườƾǦƽǄƶǦƽồǃƼ,ǦǉƶǓǦƸƛǃǦǋươǃƼǦƽươǃƼ.",
    ["卖花？这主意不错，年节里大家都愿讨个好彩头。"] = "ƝƑǃǦƽǄƶ?ǦƞƽủǦƈǦǃƐǓǦǀƽƇǃƼǦǉồƾ,ǦǃƼƐǓǦǥếǉǦƶƾǦƸũǃƼǦǂǊốǃǦǉƔǂǦƸƽƕǉǦđƾềǂǦǁƐǃƽ.",
    ["那就这么定了。对了，既然这画里的“黑圆圈”代表梨园……你们该不会……"] = "ƱậǓǦǆǊǓếǉǦđịǃƽǦǉƽếǦđƾ.ǦĐƕǃƼǦǇồƾ,ǦđƃǦǁƐǦ\"ǋƛǃƼǦǉǇƛǃǦđƺǃ\"ǦǉǇǄǃƼǦǉǇƶǃƽǦđạƾǦǤƾệǃǦƸƽǄǦƧƙǦƱƾƙǃ...ǦǀƽƇǃƼǦǁẽǦƸƑƸǦǃƼươƾ...",
    ["等等……你们还把画送给谁了？"] = "ƦƽǄƶǃǦđƃ...ǦƸƑƸǦǃƼươƾǦƸƛǃǦƼửƾǦǉǇƶǃƽǦƸƽǄǦƶƾǦǃữƶ?",
    ["嘿嘿，人多热闹嘛，我们画了两张一模一样的！另一张，已经送到飞花渡的“乐迷小铺”去啦！"] = "ƣƾǦƽƾ,ǦđƇǃƼǦǃƼườƾǦǂớƾǦǃƑǄǦǃƽƾệǉǦƸƽứ,ǦǉụƾǦǂǊộƾǦǋẽǦƽƶƾǦƷứƸǦǓǦƽệǉǦǃƽƶǊ!ǦƝứƸǦǀƾƶǦđƃǦƼửƾǦđếǃǦ\"ƩƽạƸǦƨƙǦǉƾểǊǦǉƾệǂ\"ǦởǦƫƽƾǦƣǄƶǦĐộǦǇồƾ!",
    ["算算时间，哥哥姐姐们应该快赶过来了吧？"] = "ǥƓǃƽǦǉǄƑǃǦǉƽờƾǦƼƾƶǃ,ǦƸƽắƸǦƸƑƸǦƸƶǦƸƶǦǉỷǦǉỷǦǈắǅǦǈửƶǦǀƗǄǦđếǃǦđƁǓǦǇồƾǦǃƽỉ?",
    ["呵，看来梨园那边也免不了一场“热闹”了。"] = "ƣơ,ǦǍƺǂǦǇƶǦǅƽƓƶǦƧƙǦƱƾƙǃǦƸũǃƼǦǀƽƇǃƼǦǉǇƑǃƽǦǀƽỏƾǦǂộǉǦǅƽƺǃǦ\"ǃƑǄǦǃƽƾệǉ\"ǦǇồƾ.",
    ["这解释的差事，就留给集主吧。我得回去准备鲜花了，恕不奉陪。"] = "ƱƾệƸǦƼƾảƾǦǉƽƓƸƽǦǃƐǓǦƸứǦđểǦǁạƾǦƸƽǄǦǥậǅǦƸƽủǦđƾ.ǦǥƶǦǅƽảƾǦǋềǦƸƽǊẩǃǦƷịǦƽǄƶǦǉươƾǦđƁǓ,ǦǍƾǃǦǁỗƾǦǀƽƇǃƼǦǉƽểǦǉƾếǅǦƸƽǊǓệǃǦǉƾếǅ.",
    ["……这下糟了……"] = "...ƫƽƺǃǦǃƐǓǦƽỏǃƼǦǇồƾ...",
    ["小福想邀附近的摊贩来百味集，非得说我是集主，得我露面。"] = "ǥƾểǊǦƫƽƕƸǦǂǊốǃǦǂờƾǦƸƑƸǦǉƾểǊǦǉƽươǃƼǦƼầǃǦđƁǓǦđếǃǦƝƑƸƽǦƱịǦǥậǅ,ǦƸứǦǃƽấǉǦǆǊǓếǉǦƷảǄǦǉƶǦǁƐǦǥậǅǦƸƽủ,ǦǅƽảƾǦđểǦǉƶǦǇƶǦǂặǉ.",
    ["还挺会使唤人的。这集主可真不好当啊……"] = "ƞũǃƼǦǀƽƗǄǦǈƶƾǦƷảǄǦǃƼườƾǦǉƽậǉ.ǦƞƑƾǦƸƽứƸǦǥậǅǦƸƽủǦǃƐǓǦǆǊảǦǁƐǦǀƽƇǃƼǦǤễǦǁƐǂǦǂƐ...",
    ["唉……这一天天的，煮了一锅又一锅，连个回头客都没有。"] = "ƣƶƾǏǏ...ǦǃƼƐǓǦǆǊƶǦǃƼƐǓ,ǦǃấǊǦƽếǉǦǃồƾǦǃƐǓǦđếǃǦǃồƾǦǀƽƑƸ,ǦǂƐǦƸƽẳǃƼǦƸƚǦǁấǓǦǂộǉǦǋịǦǀƽƑƸƽǦǆǊƶǓǦǁạƾ.",
    ["摊主老王"] = "ƞƽủǦǈạǅǦƧƃǄǦƱươǃƼ",
    ["老板，叹什么气呢？我们正筹办新春集市，人多热闹，要不要去摆个摊赚笔大的？"] = "ƧƃǄǦƷảǃ,ǦǈƶǄǦǁạƾǦǉƽởǦǃƼắǃǦǉƽƶǃǦǤƐƾǦǉƽế?ǦƞƽƕǃƼǦǉƶǦđƶǃƼǦǉổǦƸƽứƸǦǉậǅǦǉƽịǦǉƁǃǦǍǊƁǃ,ǦǃƼườƾǦđƇǃƼǦǃƑǄǦǃƽƾệǉ,ǦƸƚǦǂǊốǃǦđƾǦƷƐǓǦǈạǅǦǀƾếǂǦǂộǉǦǂớǦǀƽƇǃƼ?",
    ["您看看我这摊子，冷冷清清，凄凄惨惨. 这其中的酸楚……唉，不说也罢！"] = "ƩƼƐƾǦǍƺǂǦƸƑƾǦǈạǅǦǃƐǓǦƸủƶǦǉƶǦǍƺǂ,ǦǁạǃƽǦǁẽǄǦǆǊạǃƽǦǆǊẽ,ǦǉƽƙǦǉƽƙǦǉƽảǂǦǉƽảǂ.ǦƩỗƾǦƸƽǊƶǦǍƚǉǦǉǇǄǃƼǦđƚ...ǦƽƶƾǏǏ,ǦǀƽƇǃƼǦǃƚƾǦƸũǃƼǦđượƸ!",
    ["有什么难处，老板不妨讲讲？"] = "ƞƚǦǀƽƚǦǀƽăǃǦƼƔ,ǦǁƃǄǦƷảǃǦƸứǦǃƚƾǦǇƶǦǍƺǂǦǈƶǄ?",
    ["从哪说起呢……来，您先尝尝这饺子。"] = "ƝƾếǉǦƷắǉǦđầǊǦǉừǦđƁǊǦđƁǓ...ǦǃƐǄ,ǦǃƼƐƾǦƽƃǓǦǃếǂǦǉƽửǦǂƚǃǦǈủƾǦƸảǄǦǃƐǓǦǉǇướƸǦđƾ.",
    ["皮薄馅大，肉质鲜美，挺好啊。"] = "ƱỏǦǂỏǃƼǦǃƽƁǃǦǃƽƾềǊ,ǦǉƽịǉǦǉươƾǦǃƼǄǃ,ǦǇấǉǦǉốǉǦǂƐ.",
    ["一般一般。您不觉得……这饺子虽好，却缺了点“魂儿”？"] = "ƝƔǃƽǦǉƽườǃƼǦǉƽƇƾ.ǦƩƼƐƾǦǀƽƇǃƼǦǉƽấǓ...ǦǈủƾǦƸảǄǦǃƐǓǦǉǊǓǦǉốǉ,ǦǃƽưǃƼǦǁạƾǦǉƽƾếǊǦđƾǦǂộǉǦƸƽƕǉǦ\"ƽồǃ\"ǦǈƶǄ?",
    ["汴京城里的人嘴刁，吃惯了精细吃食。我这饺子也就是混口饭吃，真上了集市，肯定赔本！"] = "ƩƼườƾǦǉǇǄǃƼǦǉƽƐǃƽǦƝƾệǃǦƦƾǃƽǦǂồǂǦǂƾệǃƼǦǉƾǃƽǦǁắǂ,ǦăǃǦǆǊƺǃǦđồǦǉƾǃƽǦǉếǦǇồƾ.ǦƮủƾǦƸảǄǦǃƐǓǦƸủƶǦǉƶǦƸũǃƼǦƸƽỉǦǁƐǦǀƾếǂǦǂƾếǃƼǦƸơǂǦǉƽƇƾ,ǦǂƶǃƼǦǇƶǦǉậǅǦǉƽịǦǉƽậǉǦƸƽắƸǦƸƽắǃǦǁỗǦǋốǃ!",
    ["嗯……经你这么一说，似乎确实差点儿什么. "] = "Ừǂ...ǦǃƼƽƺǦǃƼươƾǦǃƚƾǦǋậǓ,ǦƽƔǃƽǦǃƽưǦđƕǃƼǦǁƐǦǉƽƾếǊǦƸƽƕǉǦƼƔǦđƚǦǉƽậǉ.",
    ["差在哪里，我心里跟明镜似的。就在这醋上啊！"] = "ǥƽƾếǊǦởǦđƁǊ,ǦǁƛǃƼǦǉƶǦǇƅǦǃƽưǦƼươǃƼǦǈƑǃƼǦǋậǓ.ǦƞƽƓǃƽǦǁƐǦởǦƸƽỗǦǤấǂǦǃƐǓǦǃƐǓ!",
    ["要怪就怪……我常进货的那家酱料铺子没了！"] = "ƞƽỉǦǉǇƑƸƽ...ǦƸƑƾǦǉƾệǂǦǃướƸǦƸƽấǂǦǉƶǦƽƶǓǦǃƽậǅǦƽƐǃƼǦǀƽƇǃƼǦƸƛǃǦǃữƶ!",
    ["没了……是经营不善关门了吗？"] = "ƦƽƇǃƼǦƸƛǃ...ǦǁƐǦǤǄǦǀƾǃƽǦǤǄƶǃƽǦǀƽƇǃƼǦǉốǉǦǃƙǃǦđƚǃƼǦƸửƶǦǈƶǄ?",
    ["是生意太好，赚够了钱回乡养老去咯！老何啊老何，你就这样把我丢在这苦海里……"] = "ƧƐǦǤǄǦǁƐǂǦăǃǦǆǊƑǦǉốǉ,ǦǀƾếǂǦđủǦǉƾềǃǦǇồƾǦǋềǦǆǊƙǦǤưỡǃƼǦǁƃǄǦǇồƾ!ǦƧƃǄǦƣƐǦơƾǦǁƃǄǦƣƐ,ǦƇǃƼǦƸứǦǉƽếǦǂƐǦƷỏǦǉƇƾǦǁạƾǦǉǇǄǃƼǦƷƾểǃǦǀƽổǦǃƐǓ...",
    ["谁不想养老呢！我何尝不想当一个终日吃喝玩乐的闲人呢！您说是不是？"] = "ƜƾǦǂƐǦƸƽẳǃƼǦǂǊốǃǦǤưỡǃƼǦǁƃǄǦƸƽứ!ǦǥƶǦƽƑǦǁạƾǦǀƽƇǃƼǦǂǊốǃǦǁƐǂǦǂộǉǦǀẻǦǃƽƐǃǦƽạǦǈǊốǉǦǃƼƐǓǦƸƽỉǦƷƾếǉǦăǃǦǊốǃƼǦƸƽơƾǦƷờƾǦǈƶǄ!ǦƩƼƐƾǦǃƚƾǦƸƚǦđƕǃƼǦǀƽƇǃƼ?",
    ["唉，一说起这个就收不住。我这生意一天不如一天……"] = "ƣƶƾǏǏ,ǦǃƽắƸǦđếǃǦƸƽǊǓệǃǦǃƐǓǦǁƐǦǀƽƇǃƼǦƸầǂǦǁƛǃƼǦđượƸ.ǦƱƾệƸǦǁƐǂǦăǃǦƸủƶǦǉƶǦǃƼƐǓǦǂộǉǦǈƶǦǈƕǉ...",
    ["倒是听说城西有个胡家醋坊，那儿的醋味儿正，货真价实。可我这成天守着摊子，分身乏术啊……"] = "ƩƽưǃƼǦǃƼƽƺǦǃƚƾǦǅƽƓƶǦǉƁǓǦǉƽƐǃƽǦƸƚǦƣồǦƢƾƶǦƢƾấǂǦƫƽườǃƼ,ǦǤấǂǦởǦđƚǦǋịǦǇấǉǦƸƽǊẩǃ,ǦƽƐǃƼǦǉƽậǉǦƼƾƑǦǉƽậǉ.ǦƩƽưǃƼǦǉƶǦǃƼƐǓǦǃƼƐǓǦǅƽảƾǦǉǇƇǃƼǦǈạǅ,ǦǅƽƁǃǦǉƽƁǃǦƷấǉǦǁựƸ...",
    ["这好办，交给我，我去帮你进货。"] = "ƱƾệƸǦǃƐǓǦǤễǦǉƽƇƾ,ǦƸứǦƼƾƶǄǦƸƽǄǦǉƶ,ǦǉƶǦđƾǦǃƽậǅǦƽƐǃƼǦƼƾƕǅǦǃƼươƾ.",
    ["哎哎哎！轻拿轻放！这可是陈酿，手脚轻点！"] = "ÁƾǦƑƾǦƑƾ!ǦƩƽẹǦǉƶǓǦǃƽẹǦǉƶǓ!ǦĐƁǓǦǁƐǦǇượǊǦủǦǁƁǊǦǃăǂǦđấǓ,ǦǉƶǓǦƸƽƁǃǦǃƽẹǦǃƽƐǃƼǦƸƽƕǉ!",
    ["老板生意兴隆！可有余货？我想定一批醋送到城南去. "] = "ƞƽƕƸǦǁƃǄǦƷảǃǦǁƐǂǦăǃǦǅƽƑǉǦđạǉ!ǦƞƚǦƸƛǃǦƽƐǃƼǦǤưǦǀƽƇǃƼ?ǦǥƶǦǂǊốǃǦđặǉǦǂộǉǦǁƇǦǤấǂǦƸƽǊǓểǃǦđếǃǦǅƽƓƶǦǃƶǂǦǉƽƐǃƽ.",
    ["好啊。我这可是太原老法酿的醋，祖传下来的手艺，“蒸、酵、熏、淋、晒”，步步精细，包您满意！"] = "ĐượƸǦƸƽứ.ǦĐƁǓǦǁƐǦǤấǂǦđượƸǦủǦǉƽƺǄǦǅƽươǃƼǦǅƽƑǅǦƸổǦƸủƶǦǥƽƑƾǦƩƼǊǓƙǃ,ǦǉƽủǦǃƼƽệǦƼƾƶǦǉǇǊǓềǃ,Ǧ\"ƞƽưǃƼ,ǦƣƾệǊ,ǦƣǊƁǃ,ǦƧƁǂ,ǦƮƑƾ\",ǦǉừǃƼǦƷướƸǦđềǊǦǉƾǃƽǦǉế,ǦƷảǄǦđảǂǦǃƼƐƾǦǈẽǦƽƐƾǦǁƛǃƼ!",
    ["您是打太原来的？"] = "ƩƼƐƾǦǁƐǦǉừǦǥƽƑƾǦƩƼǊǓƙǃǦđếǃǦǈƶǄ?",
    ["老家在太原。当年刘家作乱，又是打仗又是抓壮丁。"] = "ƧƃǄǦƼƾƶǦởǦǥƽƑƾǦƩƼǊǓƙǃ.ǦƩăǂǦđƚǦƧưǊǦƼƾƶǦǉƑƸǦǁǄạǃ,ǦǋừƶǦđƑǃƽǦǉǇậǃǦǋừƶǦƷắǉǦǉǇƑǃƼǦđƾǃƽ.",
    ["我家那口子被带走了，一去没回音。我这就一路逃难到了开封。"] = "ƩƽƐǦǉƶǦǋịǦǀƾƶǦƷịǦƷắǉǦđƾ,ǦǂộǉǦđƾǦǀƽƇǃƼǦǉƾǃǦǉứƸ.ǦǥƶǦđƐǃƽǦǂộǉǦđườǃƼǦƸƽạǓǦǃạǃǦđếǃǦƦƽƶƾǦƫƽǄǃƼ.",
    ["这么多年，还没消息吗？"] = "ĐƃǦƷƶǄǦǃƽƾƙǊǦǃăǂǦǇồƾ,ǦǋẫǃǦƸƽưƶǦƸƚǦǉƾǃǦǉứƸǦǈƶǄ?",
    ["没消息就是好消息！他在的时候我烦他，整天跟我顶嘴，没个消停。"] = "ƦƽƇǃƼǦƸƚǦǉƾǃǦǉứƸǦƸƽƓǃƽǦǁƐǦǉƾǃǦǉốǉ!ǦƧƕƸǦƇǃƼǦấǓǦởǦǃƽƐǦǉƶǦǅƽƾềǃǦƸƽếǉǦđƾǦđượƸ,ǦǈǊốǉǦǃƼƐǓǦƸƃƾǦƸƽƐǓǦƸƃƾǦƸốƾ,ǦƸƽẳǃƼǦǁƕƸǦǃƐǄǦǓƙǃ.",
    ["自打逃难来到开封，打拼多年，好不容易站稳了脚跟，没多余工夫想他。"] = "ǥừǦǀƽƾǦƸƽạǓǦǃạǃǦđếǃǦƦƽƶƾǦƫƽǄǃƼ,ǦƷƇǃǦƷƶǦǃƽƾềǊǦǃăǂ,ǦǀƽƚǦǀƽăǃǦǁắǂǦǂớƾǦđứǃƼǦǋữǃƼǦƼƚǉǦƸƽƁǃ,ǦƸƽẳǃƼǦƸƚǦǉƽờƾǦƼƾƶǃǦǇảǃƽǦǂƐǦǃƽớǦƇǃƼǦấǓ.",
    ["只是……少了人跟我吵架，有时候怪冷清的。"] = "ƞƽỉǦǁƐ...ǦǉƽƾếǊǦǃƼườƾǦƸƃƾǦǃƽƶǊǦǋớƾǦǂƔǃƽ,ǦđƇƾǦǀƽƾǦǉƽấǓǦǆǊạǃƽǦǆǊẽǦǁạǦǉƽườǃƼ.",
    ["嗨，跟您提这些陈芝麻烂谷子干嘛！送货的地儿留好了？我差伙计给你送去。"] = "ƣƶƾǏ,ǦǃƽắƸǦǁạƾǦƸƽǊǓệǃǦƸũǦǇƓƸƽǦǃƐǓǦǋớƾǦǃƼƐƾǦǁƐǂǦƼƔǦƸƽứ!ǦƞƽỗǦƼƾƶǄǦƽƐǃƼǦđƃǦđểǦǉǇốǃƼǦƸƽưƶ?ǦǥƶǦǈƶƾǦƽỏƶǦǀếǦǂƶǃƼǦǆǊƶǦƸƽǄǦǃƼƐƾ.",
    ["这一坛您先带回去试试，滋味不好，包退！"] = "ƱƛǦǃƐǓǦǃƼƐƾǦƸứǦǂƶǃƼǦǋềǦǤƖǃƼǦǉƽử,ǦƽươǃƼǦǋịǦǀƽƇǃƼǦǃƼǄǃ,ǦƷƶǄǦǉǇảǦƽƐǃƼ!",
    ["太好了！这香味，钻鼻子的酸爽，我一闻就知道准没错！正好来了位客官。"] = "ǥốǉǦǆǊƑ!ǦƨƖƾǦƽươǃƼǦǃƐǓ,ǦƸƽǊƶǦǈảǃƼǦǀƽǄƑƾǦǍộƸǦǋƐǄǦǂũƾ,ǦǉƶǦǃƼửƾǦǂộǉǦƸƑƾǦǁƐǦƷƾếǉǦƸƽǊẩǃǦǀƽƇǃƼǦǈƶƾ!ǦƱừƶǦǋặǃǦƸƚǦǋịǦǀƽƑƸƽǦǆǊƶǃǦǉớƾ.",
    ["客官，您尝尝这刚出锅的饺子，蘸着这新醋！"] = "ƦƽƑƸƽǦǆǊƶǃ,ǦǂờƾǦǃƼƐƾǦǃếǂǦǉƽửǦǈủƾǦƸảǄǦǋừƶǦǇƶǦǁƛ,ǦƸƽấǂǦǋớƾǦǁǄạƾǦǤấǂǦǂớƾǦǃƐǓ!",
    ["大哥怎么了？有……有这么难吃吗？"] = "ĐạƾǦƸƶǦǈƶǄǦǉƽế?Ǧƞƚ...ǦƸƚǦđếǃǦǂứƸǦǀƽƚǦăǃǦǋậǓǦǈƶǄ?",
    ["客官，别哭啊！这醋太酸了？还是饺子没熟？"] = "ƦƽƑƸƽǦǆǊƶǃ,ǦđừǃƼǦǀƽƚƸǦǂƐ!ǦǝấǂǦǃƐǓǦƸƽǊƶǦǆǊƑǦǈƶǄ?ǦƣƶǓǦǁƐǦǈủƾǦƸảǄǦƸƽưƶǦƸƽƓǃ?",
    ["不……不是难吃。这醋味……酸里带着点回甘，是并州老家的酿法！"] = "ƦƽƇǃƼ...ǦǀƽƇǃƼǦǅƽảƾǦǀƽƚǦăǃ.ǦƱịǦǤấǂǦǃƐǓ...ǦǉǇǄǃƼǦƸƽǊƶǦƸƚǦƸƽƕǉǦƽậǊǦǃƼọǉ,ǦǁƐǦƸƑƸƽǦủǦƸủƶǦǁƃǄǦƼƾƶǦǥịǃƽǦƞƽƁǊ!",
    ["您是并州来的……？"] = "ƩƼƐƾǦǁƐǦǉừǦǥịǃƽǦƞƽƁǊǦǉớƾ...?",
    ["我当兵十几年，刚从北边退下来。回老家发现人去楼空，一路寻到开封……"] = "ǥƶǦđƾǦǁƓǃƽǦǂườƾǦǂấǓǦǃăǂ,ǦǋừƶǦǉừǦǅƽươǃƼǦƝắƸǦƼƾảƾǦǃƼũ.ǦƱềǦǁƃǄǦƼƾƶǦǉƽƔǦǉƽấǓǦǃƼườƾǦđƾǦǃƽƐǦǉǇốǃƼ,ǦǂộǉǦđườǃƼǦǉƔǂǦđếǃǦƦƽƶƾǦƫƽǄǃƼ...",
    ["找了这么久，终于能尝上一口家乡的滋味了。"] = "ǥƔǂǦǁƁǊǦǃƽưǦǋậǓ,ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦđượƸǦǃếǂǦǂộǉǦǃƼụǂǦƽươǃƼǦǋịǦǆǊƙǦǃƽƐ.",
    ["胡娘子这招牌够硬啊，果然是地道的山西陈酿。"] = "ƝảǃƼǦƽƾệǊǦƸủƶǦƣồǦǃươǃƼǦǉửǦǉƽậǉǦǤƶǃƽǦƷấǉǦƽưǦǉǇǊǓềǃ,ǦǆǊảǦǃƽƾƙǃǦǁƐǦƮơǃǦǥƁǓǦǉǇầǃǦǃươǃƼǦƸƽƓǃƽǦǉƇǃƼ.",
    ["好，那下回咱就从城西醋坊进货了！"] = "ĐượƸ,ǦǋậǓǦǁầǃǦǈƶǊǦƸƽƕǃƼǦǉƶǦǈẽǦǃƽậǅǦƽƐǃƼǦǉừǦƼƾấǂǦǅƽườǃƼǦǅƽƓƶǦǥƁǓǦǉƽƐǃƽ!",
    ["胡……胡娘子？这醋坊的老板姓胡？"] = "ƣồ...ǦƣồǦǃươǃƼǦǉử?ǦƧƃǄǦƷảǃǦƸủƶǦƼƾấǂǦǅƽườǃƼǦǃƐǓǦƽọǦƣồǦǈƶǄ?",
    ["阿馨，是阿馨，她还在！"] = "ƜǦƣƾǃƽ,ǦǁƐǦƜǦƣƾǃƽ,ǦǃƐǃƼǦấǓǦǋẫǃǦƸƛǃ!",
    ["哎！客官！您还没给钱呢！……算了算了，我看这醋，不仅味正，还有故事。"] = "Ê!ǦƦƽƑƸƽǦǆǊƶǃ!ǦƩƼƐƾǦƸƛǃǦƸƽưƶǦǉǇảǦǉƾềǃǦǂƐ!...ǦǥƽƇƾǦƷỏǦđƾ,ǦǉƶǦǉƽấǓǦǤấǂǦǃƐǓǦǀƽƇǃƼǦƸƽỉǦǋịǦƸƽǊẩǃ,ǦǂƐǦƸƛǃǦƸƚǦƸảǦƸƁǊǦƸƽǊǓệǃ.",
    ["古话说醋能消食，亦解千忧，言之有理啊！"] = "ƞổǦǃƽƁǃǦǃƚƾǦǤấǂǦƸƚǦǉƽểǦǉƾƙǊǦǉƽựƸ,ǦƸũǃƼǦƼƾảƾǦǉƽƾƙǃǦǈầǊ,ǦǆǊảǦǃƽƾƙǃǦƸƚǦǁƈ!",
    ["这顿饺子的钱我来出。老板，这集市摆摊的事情，再考虑一下？"] = "ǥƾềǃǦƷữƶǦǈủƾǦƸảǄǦǃƐǓǦđểǦǉƶǦǉǇả.ǦƧƃǄǦƷảǃ,ǦǋƾệƸǦƷƐǓǦǈạǅǦởǦǉậǅǦǉƽị,ǦǃƼƐƾǦƽƃǓǦƸƁǃǦǃƽắƸǦǁạƾǦƸƽƕǉǦǃƽƗ?",
    ["您还真别说！有了这一口“酸后回甘” of 醋，这生意，能做！"] = "ƩƼƐƾǦđừǃƼǦǃƚƾǦǃữƶ!ǦƞƚǦđượƸǦǃƼụǂǦǤấǂǦ\"ƸƽǊƶǦǈƶǊǦǃƼọǉǦƽậǊ\"ǦǃƐǓ,ǦǋụǦǁƐǂǦăǃǦǃƐǓ,ǦǁƐǂǦđượƸ!",
    ["百味集……来来来，您跟我详细讲讲？"] = "ƝƑƸƽǦƱịǦǥậǅ...ǦǁạƾǦđƁǓǦǁạƾǦđƁǓ,ǦǃƼƐƾǦǀểǦƸƽƾǦǉƾếǉǦƸƽǄǦǉƶǦǃƼƽƺǦǍƺǂ?",
    ["听说附近有不少好吃的路边摊，再转转看，没准能拉几个摊主来百味集。"] = "ƩƼƽƺǦǃƚƾǦƼầǃǦđƁǓǦƸƚǦǀƽƇǃƼǦƓǉǦǈạǅǦƽƐǃƼǦǁềǦđườǃƼǦǃƼǄǃ,ǦđƾǦǤạǄǦǉƾếǅǦǍƺǂǦǈƶǄ,ǦƷƾếǉǦđƁǊǦǁạƾǦǀƗǄǦđượƸǦǋƐƾǦǈạǅǦƸƽủǦđếǃǦƝƑƸƽǦƱịǦǥậǅ.",
    ["咦，那边吵吵嚷嚷的，怎么回事？"] = "Ơ,ǦƷƙǃǦǀƾƶǦồǃǦƐǄǦǆǊƑ,ǦƸƚǦƸƽǊǓệǃǦƼƔǦǋậǓ?",
    ["……所以我就和那个怪人说——大侠才不是你写的那样！"] = "...ƞƽǄǦǃƙǃǦǉƶǦǂớƾǦǃƚƾǦǋớƾǦǉƙǃǦǆǊƑƾǦǃƽƁǃǦđƚǦ——ǦđạƾǦƽƾệǅǦǂớƾǦǀƽƇǃƼǦƼƾốǃƼǦǃƽưǦǃƽữǃƼǦƼƔǦǃƼươƾǦǋƾếǉ!",
    ["我老去瓦舍听书，那些豪侠传记，我都能倒背如流了！真正的大侠，要飞天遁地，无所不能！"] = "ǥƶǦǉƽườǃƼǦǍǊǓƙǃǦđếǃǦǃƼƚƾǦǍƑǦǃƼƽƺǦǀểǦƸƽǊǓệǃ,ǦǂấǓǦƸǊốǃǦƽƐǄǦƽƾệǅǦǉǇǊǓệǃǦǀƈǦđƚǦǉƶǦđềǊǦǉƽǊộƸǦǁƐǊǦǁƐǊǦǇồƾ!ǦĐạƾǦƽƾệǅǦǉƽựƸǦǉƽụǦǅƽảƾǦǅƽƾǦǉƽƾƙǃǦđộǃǦđịƶ,ǦǀƽƇǃƼǦƼƔǦǀƽƇǃƼǦǁƐǂǦđượƸ!",
    ["我……我听见过。"] = "ǥƶ...ǦǉƶǦǉừǃƼǦǃƼƽƺǦǆǊƶǦǇồƾ.",
    ["大侠的脚步轻飘飘的……就像落叶。说话的声音清清亮亮，小河淌水似的。"] = "ƝướƸǦƸƽƁǃǦđạƾǦƽƾệǅǦǃƽẹǦǉƙǃƽ...ǦǃƽưǦǁƑǦǇụǃƼ.ǦƢƾọǃƼǦǃƚƾǦǉǇǄǃƼǦǉǇẻǄ,ǦǃƽưǦǉƾếǃƼǦǈǊốƾǦƸƽảǓǦǋậǓ.",
    ["我知道我知道！大侠就是真人不露相，出手非凡人！"] = "ǥƶǦƷƾếǉǦǉƶǦƷƾếǉ!ǦĐạƾǦƽƾệǅǦƸƽƓǃƽǦǁƐǦƸƽƁǃǦǃƽƁǃǦƷấǉǦǁộǦǉướǃƼ,ǦǇƶǦǉƶǓǦǅƽƾǦǅƽƐǂǦǃƽƁǃ!",
    ["告诉你们个秘密，我可是有个大侠师父的！"] = "ƩƚƾǦƸƽǄǦƸƑƸǦǃƼươƾǦǂộǉǦƷƓǦǂậǉ,ǦǉƶǦƸƚǦǂộǉǦǋịǦđạƾǦƽƾệǅǦǈưǦǅƽụǦđấǓ!",
    ["阿宗，别吹牛了，你那师父我们连影儿都没见过。快回去吧，再溜出来，被你爹抓到了打屁股！"] = "ƜǦǥƇǃƼ,ǦđừǃƼǦƷốƸǦǅƽƗǉǦǃữƶ,ǦǈưǦǅƽụǦƸủƶǦƽǊǓǃƽǦǉụƾǦǃƐǓǦƸƛǃǦƸƽẳǃƼǦǉƽấǓǦƷƚǃƼǦǤƑǃƼǦđƁǊ.ǦƨƶǊǦǋềǦđƾ,ǦƸƛǃǦǁẻǃǦǇƶǦǃƼǄƐƾǦǃữƶǦǁƐǦƷịǦƸƽƶǦƽǊǓǃƽǦƷắǉǦđượƸǦđƑǃƽǦđƛǃǦđấǓ!",
    ["我跟你们说，话本里都写了，大侠最厉害的招数就是——铜头铁臂！这就叫，忍常人所不能忍！"] = "ǥƶǦǃƚƾǦƸƽǄǦƸƑƸǦǃƼươƾǦƽƶǓ,ǦǉǇǄǃƼǦǉƽǄạƾǦƷảǃǦđềǊǦǋƾếǉǦǇồƾ,ǦƸƽƾƙǊǦǉƽứƸǦǁợƾǦƽạƾǦǃƽấǉǦƸủƶǦđạƾǦƽƾệǅǦƸƽƓǃƽǦǁƐǦ——ǦĐồǃƼǦĐầǊǦǥƽƾếǉǦǥƈ!ǦĐƁǓǦƼọƾǦǁƐ,ǦǃƽẫǃǦđƾềǊǦǃƼườƾǦǉƽườǃƼǦǀƽƇǃƼǦǉƽểǦǃƽẫǃ!",
    ["忍……？原来是这样！我能忍我爹唠叨一个时辰，看来我天生就是要做大侠的……诶，你怎么不说话？"] = "Ʃƽẫǃ...?ǦƣƚƶǦǇƶǦǁƐǦǋậǓ!ǦǥƶǦƸƚǦǉƽểǦǃƽẫǃǦǃƽịǃǦƸƽƶǦǉƶǦǁảƾǦǃƽảƾǦƸảǦǂộǉǦƸƶǃƽǦƼƾờ,ǦǍƺǂǦǇƶǦǉƶǦǉƽƾƙǃǦǈƾǃƽǦǁƐǦđểǦǁƐǂǦđạƾǦƽƾệǅǦǇồƾ...Ǧƙ,ǦǈƶǄǦǃƼươƾǦǀƽƇǃƼǦǃƚƾǦƼƔ?",
    ["……哦……没。"] = "...Ồ...ǦǀƽƇǃƼǦƸƚǦƼƔ.",
    ["这娃娃是从外地新搬来的，怪得很，老不理人。"] = "ĐứƶǦǃƽỏǦǃƐǓǦǁƐǦǉừǦǃơƾǦǀƽƑƸǦǂớƾǦǤọǃǦđếǃ,ǦǆǊƑƾǦǁạǦǁắǂ,ǦƸƽẳǃƼǦƷƶǄǦƼƾờǦǉƽƘǂǦđểǦƈǦđếǃǦƶƾ.",
    ["对了对了，想当大侠，看这个——我刚从城北胡商那儿淘来的“烈火丹”！"] = "ĐƕǃƼǦǇồƾǦđƕǃƼǦǇồƾ,ǦǂǊốǃǦǁƐǂǦđạƾǦƽƾệǅǦǉƽƔǦǍƺǂǦƸƑƾǦǃƐǓǦ——ǦǉƶǦǂớƾǦđƐǄǦđượƸǦ\"ƧƾệǉǦƣỏƶǦĐƶǃ\"ǦǉừǦƸƽỗǦƣồǦǉƽươǃƼǦǅƽƓƶǦƝắƸǦǉƽƐǃƽǦđấǓ!",
    ["这……看着像普通的炒蚕豆……不过怎么是红色的？"] = "ƞƑƾǦǃƐǓ...ǦǃƽƔǃǦƼƾốǃƼǦđậǊǦǉằǂǦǇƶǃƼǦƷƔǃƽǦǉƽườǃƼ...ǦǃƽưǃƼǦǈƶǄǦǁạƾǦƸƚǦǂƐǊǦđỏ?",
    ["味道有点冲鼻子，像烧焦的树皮……"] = "ƨƖƾǦǋịǦƽơƾǦǃồǃƼǦǍộƸǦǋƐǄǦǂũƾ,ǦƼƾốǃƼǦǃƽưǦǋỏǦƸƁǓǦƷịǦƸƽƑǓǦǋậǓ...",
    ["这可不是普通的豆子。吃了以后，嘴巴就像着火一样，舌头也没知觉了！"] = "ĐƁǓǦǀƽƇǃƼǦǅƽảƾǦƽạǉǦđậǊǦƷƔǃƽǦǉƽườǃƼǦđƁǊ.ǦĂǃǦǋƐǄǦǇồƾ,ǦǂƾệǃƼǦǈẽǦǃƽưǦƷốƸǦƽỏƶ,ǦǁưỡƾǦƸũǃƼǦǂấǉǦǈạƸƽǦǉǇƾǦƼƾƑƸǦǁǊƇǃ!",
    ["大侠就是要百毒不侵，忍痛熬毒！敢不敢试试？"] = "ĐạƾǦƽƾệǅǦǁƐǦǅƽảƾǦƷƑƸƽǦđộƸǦƷấǉǦǍƁǂ,ǦǃƽẫǃǦǉƽốǃƼǦǃƼạǄǦđộƸ!ǦƞƚǦǤƑǂǦǉƽửǦǀƽƇǃƼ?",
    ["嘶……哈……怎么样！厉害吧！这就叫……忍耐痛苦！"] = "ƳƔ...ǦƽƐ...ǦǉƽếǦǃƐǄ!ǦƧợƾǦƽạƾǦƸƽưƶ!ǦĐƁǓǦƼọƾǦǁƐ...ǦǃƽẫǃǦǃạƾǦǉƽốǃƼǦǀƽổ!",
    ["哼，谁怕谁！给我来——两颗！"] = "ƣừ,ǦƶƾǦǈợǦƶƾǦƸƽứ!ǦƞƽǄǦǉƶǦ——ǦƽƶƾǦƽạǉ!",
    ["唔……斯哈斯哈斯哈……呜呜……怎么样？我才是……才是大侠……"] = "Ưǂ...ǦǍƔǦƽƐǦǍƔǦƽƐǦǍƔǦƽƐ...ǦƽǊǦƽǊ...ǦǉƽếǦǃƐǄ?ǦǥƶǦǂớƾǦǁƐ...ǦǂớƾǦǁƐǦđạƾǦƽƾệǅ...",
    ["几位大侠，佩服佩服！"] = "ƨấǓǦǋịǦđạƾǦƽƾệǅ,ǦƷƑƾǦǅƽụƸǦƷƑƾǦǅƽụƸ!",
    ["这声音……是……大侠！"] = "ƢƾọǃƼǦǃƚƾǦǃƐǓ...ǦǁƐ...ǦđạƾǦƽƾệǅ!",
    ["师……师父！这就是我师父！"] = "Ʈư...ǦƮưǦǅƽụ!ǦĐƁǓǦƸƽƓǃƽǦǁƐǦǈưǦǅƽụǦƸủƶǦǉƶ!",
    ["大侠师父，你也来吃烈火丹！真大侠一定比我们都厉害！"] = "ĐạƾǦƽƾệǅǦǈưǦǅƽụ,ǦǃƼườƾǦƸũǃƼǦǉớƾǦăǃǦƧƾệǉǦƣỏƶǦĐƶǃǦđƾ!ǦĐạƾǦƽƾệǅǦǉƽựƸǦǈựǦƸƽắƸǦƸƽắǃǦǅƽảƾǦǁợƾǦƽạƾǦƽơǃǦǉụƾǦƸǄǃǦǃƽƾềǊ!",
    ["……这味道……果然……非同凡响……！"] = "...ƨƖƾǦǋịǦǃƐǓ...ǦǆǊảǦǃƽƾƙǃ...ǦǅƽƾǦđồǃƼǦǅƽƐǂǦƽưởǃƼ...!",
    ["……全，全吃了？！"] = "...Ăǃ,ǦăǃǦƽếǉǦǈạƸƽǦǇồƾ?!",
    ["这点儿麻味算啥子嘛！"] = "ƞƽƕǉǦǋịǦǉƙǦǃƐǓǦǉƽƔǦǉƓǃƽǦǁƐǦƸƑƾǦƼƔǦƸƽứ!",
    ["我是从巴蜀来的！这怪味豆在我们老家，这只能算是个零嘴儿！"] = "ǥƶǦǁƐǦǉừǦƝƶǦǥƽụƸǦǉớƾ!ǦƧǄạƾǦđậǊǦǆǊƑƾǦǋịǦǃƐǓǦởǦǁƃǄǦƼƾƶǦǉƶǦƸƽỉǦđượƸǦǉƓǃƽǦǁƐǦǂƚǃǦăǃǦǋặǉǦǉƽƇƾ!",
    ["太厉害了！师父，这回我是心服口服了！"] = "ƬǊƑǦǁợƾǦƽạƾ!ǦƮưǦǅƽụ,ǦǅƽƺǃǦǃƐǓǦƸǄǃǦǉƁǂǦǅƽụƸǦǀƽẩǊǦǅƽụƸǦǇồƾ!",
    ["诶，你之前怎么不说话啊？"] = "Ê,ǦǈƶǄǦǁƕƸǦǃƃǓǦǃƼươƾǦǀƽƇǃƼǦǃƚƾǦƼƔǦǉƽế?",
    ["我……我怕我说的话，你们听不懂，笑话我……"] = "ǥƶ...ǦǉƶǦǈợǦǁờƾǦǉƶǦǃƚƾǦǇƶǦƸƑƸǦǃƼươƾǦǃƼƽƺǦǀƽƇǃƼǦƽƾểǊ,ǦǁạƾǦƸườƾǦǃƽạǄǦǉƶ...",
    ["嗐，我是从北边来的，刚来的时候，啥都听不懂，现在不也好好的？"] = "ƣạƾ,ǦǉƶǦǁƐǦǉừǦǅƽươǃƼǦƝắƸǦǉớƾ,ǦǁƕƸǦǂớƾǦđếǃǦƸƑƾǦƼƔǦƸũǃƼǦǀƽƇǃƼǦƽƾểǊ,ǦƼƾờǦƸƽẳǃƼǦǅƽảƾǦǋẫǃǦǉốǉǦđƚǦǈƶǄ?",
    ["多跟我们玩，多听多说，很快就懂啦……"] = "ƞƽơƾǦǋớƾǦǉụƾǦǃƐǓǦǃƽƾềǊǦǋƐǄ,ǦǃƼƽƺǦǃƽƾềǊǦǃƚƾǦǃƽƾềǊǦǁƐǦǈẽǦƽƾểǊǦǃƽƶǃƽǦǉƽƇƾ...",
    ["嗯……要得！……中！"] = "Ừǂ...ǦǓƙǊǦđắƸ!...ǦǥǇƕǃƼ!",
    ["“风云起，少侠聚，小小豆儿定乾坤……妙啊，妙啊……”"] = "\"ƫƽǄǃƼǦǋƁǃǦǀƽởƾ,ǦǉƽƾếǊǦƽƾệǅǦǉụ,ǦǉƾểǊǦǉƾểǊǦđậǊǦǃƽƾǦđịǃƽǦƸƐǃǦǀƽƇǃ...ǦǝƾệǊǦǉƶƾ,ǦǤƾệǊǦǉƶƾ...\"",
    ["罗小古"] = "ƧƶǦǥƾểǊǦƞổ",
    ["写什么呢？这么入神？"] = "ĐƶǃƼǦǋƾếǉǦƼƔǦǂƐǦǃƽậǅǦǉƁǂǦǉƽế?",
    ["哎哟，是集主啊！我在写戏文呢！"] = "ÁƾǦƸƽƐ,ǦǁƐǦǥậǅǦƸƽủǦƐ!ǦǥƶǦđƶǃƼǦǋƾếǉǦƽƓǦǋăǃǦđƁǓ!",
    ["九流门什么时候改行写戏文了？这可是头一回听说。"] = "ƞửǊǦƧưǊǦƨƇǃǦǉừǦǀƽƾǦǃƐǄǦđổƾǦǃƼƽềǦǋƾếǉǦƽƓǦǋăǃǦǋậǓ?ǦĐƁǓǦǁƐǦǁầǃǦđầǊǦǉƶǦǃƼƽƺǦǉƽấǓǦđấǓ.",
    ["这不是为了百味集嘛！消息散布出去后，参加的门派越来越多。"] = "ƞƽẳǃƼǦǅƽảƾǦǁƐǦǋƔǦƝƑƸƽǦƱịǦǥậǅǦǈƶǄ!ǦƮƶǊǦǀƽƾǦǉƾǃǦǉứƸǦǉǇǊǓềǃǦđƾ,ǦƸƑƸǦǂƇǃǦǅƽƑƾǦǉƽƶǂǦƼƾƶǦǃƼƐǓǦƸƐǃƼǦǃƽƾềǊ.",
    ["春水阁那也收到了消息，天泉的兄弟姐妹放话说：铁子必到！"] = "ƝƙǃǦƳǊƁǃǦǥƽủǓǦƞƑƸǦƸũǃƼǦǃƽậǃǦđượƸǦǉƾǃǦǇồƾ,ǦƽǊǓǃƽǦđệǦǉỷǦǂǊộƾǦǥƽƾƙǃǦǥǊǓềǃǦƷắǃǦǉƾǃǦǇằǃƼ:ǦǥƽƾếǉǦǉửǦǉấǉǦđƑǄ!",
    ["咱们本地帮派绝不能输了阵势！除了筹备场地，还得来点新花样！"] = "ƝƶǃƼǦǅƽƑƾǦƷảǃǦđịƶǦƸƽƕǃƼǦǉƶǦǉǊǓệǉǦđốƾǦǀƽƇǃƼǦǉƽểǦǉƽǊƶǦǈƕǉǦǉǇậǃǦǉƽế!ǦƩƼǄƐƾǦƸƽǊẩǃǦƷịǦđịƶǦđƾểǂ,ǦƸƛǃǦǅƽảƾǦƸƚǦǉƽƙǂǦǂấǓǦǉǇƛǦǂớƾǦǁạ!",
    ["所以我就想挑战一下……写个戏文助助兴！"] = "ƞƽǄǦǃƙǃǦǉƶǦǂǊốǃǦǉƽửǦǉƽƑƸƽǦǂộǉǦƸƽƕǉ...ǦǋƾếǉǦǂộǉǦƷảǃǦƽƓǦǋăǃǦđểǦǉǇợǦƽứǃƼ!",
    ["这是我想了好久的故事！某天夜里，我梦见风雨交加，一位侠客在雷电中亮相！"] = "ĐƁǓǦǁƐǦƸƁǊǦƸƽǊǓệǃǦǉƶǦđƃǦǃƼƽĩǦǇấǉǦǁƁǊ!ǦƨộǉǦđƙǂǦǃọ,ǦǉƶǦǂơǦǉƽấǓǦƼƾƚǦǂưƶǦǋầǃǦǋũ,ǦǂộǉǦǋịǦƽƾệǅǦǀƽƑƸƽǦǍǊấǉǦƽƾệǃǦƼƾữƶǦǈấǂǦƸƽớǅ!",
    ["醒来以后……就像真的被雷击中了一样！"] = "ƮƶǊǦǀƽƾǦǉỉǃƽǦǤậǓ...ǦƸảǂǦƼƾƑƸǦǃƽưǦǉƽựƸǦǈựǦƷịǦǈƗǉǦđƑǃƽǦǉǇƕǃƼǦǋậǓ!",
    ["于是我就到处打听侠客的故事，想好好编一出戏。"] = "ǥƽếǦǁƐǦǉƶǦđƾǦǀƽắǅǦǃơƾǦǃƼƽƺǦǃƼƚǃƼǦƸƽǊǓệǃǦǋềǦƽƾệǅǦǀƽƑƸƽǦđểǦƷƾƙǃǦǂộǉǦǋởǦǀịƸƽǦǉƽậǉǦƽƶǓ.",
    ["所以你就来这儿寻些巧思？"] = "ƞƽǄǦǃƙǃǦǃƼươƾǦđếǃǦđƁǓǦđểǦǉƔǂǦƸƽƕǉǦǍảǄǦǉứǦǈƶǄ?",
    ["对啊！梨园的朋友教导我说：“要想写好戏，就得多看多记，真听真看真感受！”"] = "ĐƕǃƼǦǋậǓ!ǦƝằǃƼǦƽữǊǦƷƙǃǦƧƙǦƱƾƙǃǦǤạǓǦǉƶǦǇằǃƼ:Ǧ\"ƨǊốǃǦǋƾếǉǦǀịƸƽǦƽƶǓ,ǦǅƽảƾǦǍƺǂǦǃƽƾềǊǦǃƽớǦǃƽƾềǊ,ǦǉƽựƸǦǉƽƓǃƽǦǉƽựƸǦǀƽƑǃǦǉƽựƸǦƸảǂǦǉƽụ!\"",
    ["这不，我就来听听城里的“大侠传奇”，接接地气嘛！"] = "ǥƽếǦǃƙǃǦǉƶǦǂớƾǦđếǃǦǃƼƽƺǦ\"đạƾǦƽƾệǅǦǉǇǊǓềǃǦǀỳ\"ǦǉǇǄǃƼǦǉƽƐǃƽǦƸƽǄǦƼầǃǦƼũƾǦǉƽựƸǦǉếǦđƁǓ!",
    ["那我就拭目以待，等你的开年大戏！"] = "ƱậǓǦǉƶǦǈẽǦǂỏƾǦǂắǉǦƸƽờǦǂǄǃƼǦǋởǦđạƾǦǀịƸƽǦǀƽƶƾǦǃƾƙǃǦƸủƶǦǃƼươƾ!",
    ["定不负集主厚望！这出戏，定能博个满堂彩！"] = "ĐịǃƽǦǀƽƇǃƼǦǅƽụǦƽậǊǦǋọǃƼǦƸủƶǦǥậǅǦƸƽủ!ǦƱởǦǀịƸƽǦǃƐǓǦƸƽắƸǦƸƽắǃǦǈẽǦǃƽậǃǦđượƸǦǈựǦǉƑǃǦǉƽưởǃƼǦǃồǃƼǦǃƽƾệǉ!",
    ["集主，好消息！咱这百味集，怕是要成今年腊月最热闹的去处了！"] = "ǥậǅǦƸƽủ,ǦǉƾǃǦǉốǉ!ǦƝƑƸƽǦƱịǦǥậǅǦƸủƶǦƸƽƕǃƼǦǉƶǦƺǦǁƐǦǈẽǦǉǇởǦǉƽƐǃƽǦǃơƾǦǃƑǄǦǃƽƾệǉǦǃƽấǉǦǉƽƑǃƼǦƞƽạǅǦǃăǂǦǃƶǓǦǇồƾ!",
    ["艾小燃"] = "ƩƼảƾǦǥƾểǊǦƩƽƾƙǃ",
    ["听说百味集义卖的钱，能给穷人家筹冬衣，各大门派都动了真格。"] = "ƩƼƽƺǦǃƚƾǦǉƾềǃǦǃƼƽĩƶǦǂạƾǦởǦƝƑƸƽǦƱịǦǥậǅǦƸƚǦǉƽểǦǤƖǃƼǦđểǦǁǄǦƑǄǦǂƖƶǦđƇǃƼǦƸƽǄǦǃƼườƾǦǃƼƽƘǄ,ǦƸƑƸǦđạƾǦǂƇǃǦǅƽƑƾǦđềǊǦđƃǦǇƶǦǉƶǓǦǉƽậǉǦǈự.",
    ["冬日苦寒，青溪弟子准备了药膳，贫者分文不取。狂澜弟子推荐了百年酒铺。"] = "ƨƖƶǦđƇǃƼǦƼƾƑǦǇƗǉ,ǦđệǦǉửǦǥƽƶǃƽǦƦƽƙǦđƃǦƸƽǊẩǃǦƷịǦǤượƸǦǉƽƾệǃ,ǦǃƼườƾǦǃƼƽƘǄǦǀƽƇǃƼǦǉƽǊǦǂộǉǦǍǊ.ǦĐệǦǉửǦƞǊồǃƼǦƧƶǃǦǉƽƔǦđềǦƸửǦǉửǊǦǉƾệǂǦǉǇăǂǦǃăǂ.",
    ["可是……唉，美中不足啊！"] = "ƩƽưǃƼǦǂƐ...ǦƽƶƾǏǏ,ǦǂỹǦǉǇǊǃƼǦƷấǉǦǉƕƸǦǃƽƶ!",
    ["别故意卖关子啦，有话便说。"] = "ĐừǃƼǦƸốǦǉƔǃƽǦǁấǅǦǁửǃƼǦǃữƶ,ǦƸƚǦǁờƾǦǉƽƔǦǃƚƾǦđƾ.",
    ["瞒不过您。这集市一天天搭起来了，热闹归热闹，可还缺点东西。"] = "ƞƽẳǃƼǦƼƾấǊǦđượƸǦǃƼƐƾ.ǦǥậǅǦǉƽịǦǃƐǓǦǃƼƐǓǦǂộǉǦǉƽƐǃƽǦƽƔǃƽ,ǦǃƑǄǦǃƽƾệǉǦǉƽƔǦƸƚǦǃƑǄǦǃƽƾệǉ,ǦǃƽưǃƼǦǋẫǃǦƸƛǃǦǉƽƾếǊǦƸƽƕǉǦƼƔǦđƚ.",
    ["缺了什么？"] = "ǥƽƾếǊǦƸƑƾǦƼƔ?",
    ["缺了让人一眼就能记住，看到就挪不动脚的！"] = "ǥƽƾếǊǦǉƽứǦƼƔǦđƚǦǀƽƾếǃǦǃƼườƾǦǉƶǦǋừƶǦǃƽƔǃǦǁƐǦǃƽớǦǃƼƶǓ,ǦǉƽấǓǦǇồƾǦǁƐǦǀƽƇǃƼǦǃỡǦǇờƾǦƷướƸ!",
    ["哦！是想要“噱头”，对吧？"] = "Ồ!ǦƧƐǦǂǊốǃǦǉƔǂǦ\"ƽƐǄǦǃƽǄƑǃƼ\"ǦđểǦǉƽǊǦƽƕǉ,ǦđƕǃƼǦǀƽƇǃƼ?",
    ["对对对！文津馆、墨山道、孤云都点头要参加这百味集了。可是……噱头不嫌少啊！多招揽点客人，就能多筹钱捐冬衣！"] = "ĐƕǃƼǦđƕǃƼǦđƕǃƼ!ǦƱăǃǦǥƁǃǦƬǊƑǃ,ǦƨặƸǦƮơǃǦĐạǄ,ǦƞƇǦƱƁǃǦđềǊǦđƃǦƼậǉǦđầǊǦǉƽƶǂǦƼƾƶǦƝƑƸƽǦƱịǦǥậǅǦǇồƾ.ǦƩƽưǃƼǦǂƐ...ǦƽƐǄǦǃƽǄƑǃƼǦƷƶǄǦǃƽƾƙǊǦƸũǃƼǦǀƽƇǃƼǦđủ!ǦƞƽƾƙǊǦǂộǦđượƸǦǉƽƙǂǦǃƽƾềǊǦǀƽƑƸƽǦǉƽƔǦǂớƾǦƼǄǂǦđượƸǦǉƽƙǂǦǉƾềǃǦǆǊǓƙǃǦƑǄǦấǂ!",
    ["我刚打听到个独家消息！有位神厨，今年带着两名高徒来了汴京。这人是个怪脾气，给穷人做饭不要钱，给富人做饭要半副身家。"] = "ǥƶǦǋừƶǦǃƼƽƺǦǃƼƚǃƼǦđượƸǦǂộǉǦǉƾǃǦđộƸǦǆǊǓềǃ!ǦƞƚǦǋịǦǥƽầǃǦǉǇƖǦǃăǂǦǃƶǓǦǤẫǃǦǉƽƺǄǦƽƶƾǦǋịǦƸƶǄǦđồǦđếǃǦƝƾệǃǦƦƾǃƽ.ǦƩƼườƾǦǃƐǓǦǉƓǃƽǦǉƔǃƽǦǆǊƑƾǦƼở,ǦǁƐǂǦƸơǂǦƸƽǄǦǃƼườƾǦǃƼƽƘǄǦǉƽƔǦǀƽƇǃƼǦǁấǓǦǉƾềǃ,ǦǁƐǂǦƸƽǄǦǃƼườƾǦƼƾƐǊǦǉƽƔǦđƛƾǦǃửƶǦƼƾƶǦǈảǃ.",
    ["更怪的是——他们下厨的时候，异香扑鼻，人喜欢，小动物也喜欢，猫狗环绕，跟变戏法似的！"] = "ƬǊƑƾǦǁạǦƽơǃǦǁƐǦ——ǦǀƽƾǦƽọǦǍǊốǃƼǦƷếǅ,ǦƽươǃƼǦǉƽơǂǦǁạǦǀỳǦǃứƸǦǂũƾ,ǦǃƼườƾǦǉƽƓƸƽǦǂƐǦǉƾểǊǦđộǃƼǦǋậǉǦƸũǃƼǦǉƽƓƸƽ,ǦǂƘǄǦƸƽƚǦǋƁǓǦǆǊƶǃƽǦǃƽưǦđƶǃƼǦƷƾếǃǦảǄǦǉƽǊậǉǦǋậǓ!",
    ["吃着美食，还能和小猫小狗玩耍，这谁能抗拒得住？"] = "ƱừƶǦđượƸǦăǃǦǂƚǃǦǃƼǄǃ,ǦǋừƶǦđượƸǦƸƽơƾǦǋớƾǦǂƘǄǦǃƽỏǦƸƽƚǦǃƽỏ,ǦƶƾǦǂƐǦƸưỡǃƼǦǁạƾǦđượƸǦƸƽứ?",
    ["可我听说，集主也对招猫逗狗颇有心得呢……"] = "ƩƽưǃƼǦǉƶǦǃƼƽƺǦǃƚƾ,ǦǥậǅǦƸƽủǦƸũǃƼǦǇấǉǦƸƚǦǉƁǂǦđắƸǦǉǇǄǃƼǦǋƾệƸǦǉǇƙǊǦǂƘǄǦƸƽọƸǦƸƽƚǦđấǓ...",
    ["既然如此，为何不邀请神厨出手？"] = "ĐƃǦǃƽưǦǋậǓ,ǦǉạƾǦǈƶǄǦǀƽƇǃƼǦǂờƾǦǥƽầǃǦǉǇƖǦǇƶǦǉƶǓ?",
    ["这就是令我发愁的地方咯！神厨师父呢，神龙见首不见尾。"] = "ĐƁǓǦƸƽƓǃƽǦǁƐǦƸƽỗǦǁƐǂǦǉƶǦǅƽƑǉǦǈầǊǦđƁǓ!ǦǥƽầǃǦǉǇƖǦǈưǦǅƽụǦǉƽƔǦǉƽầǃǦǁǄǃƼǦǀƾếǃǦǉƽủǦƷấǉǦǀƾếǃǦǋĩ.",
    ["俩徒弟更愁——师门规矩严，不出师就不能开铺子。听说他们被那道出师菜难住了半个月！"] = "ƣƶƾǦǉƙǃǦđồǦđệǦƸƛǃǦǈầǊǦƽơǃǦ——ǦǆǊǓǦƸủǦǈưǦǂƇǃǦǃƼƽƾƙǂǦǃƼặǉ,ǦƸƽưƶǦǍǊấǉǦǈưǦǉƽƔǦǀƽƇǃƼǦđượƸǦǂởǦǉƾệǂ.ǦƩƼƽƺǦǃƚƾǦƽọǦƷịǦǂƚǃǦăǃǦǍǊấǉǦǈưǦđƚǦǁƐǂǦǀƽƚǦǈǊốǉǦǃửƶǦǉƽƑǃƼǦǇồƾ!",
    ["神厨的出师菜，定是要煎炒烹炸样样精通，或是寻什么山珍海味吧？"] = "ƨƚǃǦăǃǦǍǊấǉǦǈưǦƸủƶǦǥƽầǃǦǉǇƖǦƸƽắƸǦƸƽắǃǦǅƽảƾǦǉƾǃƽǦǉƽƇǃƼǦđủǦǁǄạƾǦƸƽƾƙǃǦǍƐǄǦǃấǊǦǃướǃƼ,ǦƽǄặƸǦǁƐǦǉƔǂǦǈơǃǦƽƐǄǦƽảƾǦǋịǦƼƔǦđƚǦƸƽứ?",
    ["哎，这话就另说了。我托人打听过，那题目简单得很——就做一道“老人想吃的菜”。"] = "ƀǓ,ǦƸƽǊǓệǃǦǃƐǓǦǁạƾǦǃƚƾǦǀƽƑƸǦǇồƾ.ǦǥƇƾǦƸƚǦǃƽờǦǃƼườƾǦǤƛǦƽỏƾ,ǦđềǦƷƐƾǦđƚǦđơǃǦƼƾảǃǦǁắǂǦ——ǦƸƽỉǦǁƐǂǦǂộǉǦǂƚǃǦ\"ǂƚǃǦăǃǦǃƼườƾǦƼƾƐǦǂǊốǃǦăǃ\".",
    ["这有何难？"] = "ƱƾệƸǦǃƐǓǦƸƚǦƼƔǦǀƽƚ?",
    ["难就难在“想吃”二字！那位老人姓陆，如今已经百岁了，还能写字算账，是位出名的人瑞。这菜要入她的眼，可没那么容易。"] = "ƦƽƚǦǁƐǦởǦƽƶƾǦƸƽữǦ\"ǂǊốǃǦăǃ\"!ǦƱịǦǁƃǄǦǃƽƁǃǦđƚǦƽọǦƧụƸ,ǦǃƶǓǦđƃǦƷƑƸƽǦǉǊếǦǇồƾǦǂƐǦǋẫǃǦƸƛǃǦƸƚǦǉƽểǦǋƾếǉǦƸƽữǦǉƓǃƽǦǉǄƑǃ,ǦǁƐǦǂộǉǦƷậƸǦǃƽƁǃǦǉƽụǓǦǁừǃƼǦǤƶǃƽ.ǦƨƚǃǦăǃǦǃƐǓǦǂǊốǃǦǁọǉǦǋƐǄǦǂắǉǦƷƐǦấǓǦǉƽƔǦǀƽƇǃƼǦƽềǦǤễǦǤƐǃƼ.",
    ["集主见多识广，要不你去瞅瞅？若是能解了这难题，神厨出马，冬衣钱怕是能多筹出三成！"] = "ǥậǅǦƸƽủǦǀƾếǃǦđƶǦǉƽứƸǦǆǊảǃƼ,ǦƽƶǓǦǁƐǦǃƼƐƾǦđếǃǦǍƺǂǦǉƽửǦǍƺǂ?ǦƩếǊǦƼƾảƾǦđượƸǦǃƶǃǦđềǦǃƐǓ,ǦǥƽầǃǦǉǇƖǦǍǊấǉǦǂƃ,ǦǉƾềǃǦƑǄǦấǂǦƺǦǁƐǦƸƚǦǉƽểǦƼǄǂǦǉƽƙǂǦđượƸǦƷƶǦǉƽƐǃƽǦđấǓ!",
    ["嗯……左右今日无事，我尽力而为吧。"] = "Ừǂ...ǦđằǃƼǦǃƐǄǦƽƇǂǦǃƶǓǦƸũǃƼǦǇảǃƽǦǇỗƾ,ǦǉƶǦǈẽǦƸốǦƽếǉǦǈứƸǦǋậǓ.",
    ["……这账不对，再算！咳咳……咱们陆家几十年前迁来开封，铺子里的账从没错过半文。"] = "...ƮổǦǈƑƸƽǦǃƐǓǦǀƽƇǃƼǦđƕǃƼ,ǦǉƓǃƽǦǁạƾǦđƾ!ǦƦƽụǦǀƽụ...ǦƧụƸǦƼƾƶǦƸƽƕǃƼǦǉƶǦǂấǓǦƸƽụƸǦǃăǂǦǉǇướƸǦǤờƾǦđếǃǦƦƽƶƾǦƫƽǄǃƼ,ǦǈổǦǈƑƸƽǦǉǇǄǃƼǦǉƾệǂǦƸƽưƶǦƷƶǄǦƼƾờǦǈƶƾǦǈƚǉǦǃửƶǦǍǊ.",
    ["陆太奶奶"] = "ƧụƸǦǥƽƑƾǦǃƃƾǦǃƃƾ",
    ["太奶奶，歇歇吧，该吃药了。这还有道甜品，是特地给您的。"] = "ǥƽƑƾǦǃƃƾǦǃƃƾ,ǦǃƼƽỉǦǃƼơƾǦƸƽƕǉǦđƾ,ǦđếǃǦƼƾờǦǊốǃƼǦǉƽǊốƸǦǇồƾ.ǦỞǦđƁǓǦƸƛǃǦƸƚǦǂƚǃǦđồǦǃƼọǉ,ǦǁƐǦđặƸǦƷƾệǉǦǁƐǂǦƸƽǄǦǃƼườƾǦđấǓ.",
    ["陆十弟"] = "ƧụƸǦǥƽậǅǦĐệ",
    ["拿走……都拿走。我这嘴里啊，跟含了二斤黄连似的，吃龙肉也是苦的，喝蜜水也是涩的。"] = "ƨƶǃƼǦđƾ...ǦǂƶǃƼǦđƾǦƽếǉǦđƾ.ǦǥǇǄǃƼǦǂƾệǃƼǦǉƶǦƼƾờǦǃƽưǦđƶǃƼǦǃƼậǂǦƽƶƾǦƸƁǃǦƽǄƐǃƼǦǁƾƙǃǦǋậǓ,ǦăǃǦǉƽịǉǦǇồǃƼǦƸũǃƼǦǉƽấǓǦđắǃƼ,ǦǊốǃƼǦǃướƸǦǂậǉǦƸũǃƼǦǉƽấǓǦƸƽƑǉ.",
    ["别折腾我这把老骨头了……"] = "ĐừǃƼǦǤƐǓǦǋƛǦƸƑƾǦǉƽƁǃǦƼƾƐǦǃƐǓǦǃữƶ...",
    ["怎么办，师姐。杏仁酪、蜜煎金橘，都试过了，老人家连筷子都没动过。"] = "ƫƽảƾǦǁƐǂǦǈƶǄǦđƁǓǦǈưǦǉỷ.ǦƣạǃƽǦǃƽƁǃǦǁạƸ,ǦǂậǉǦǉƾễǃǦǀƾǂǦǆǊấǉǦđềǊǦǉƽửǦǆǊƶǦƸảǦǇồƾ,ǦǁƃǄǦǃƽƁǃǦƼƾƶǦđếǃǦđũƶǦƸũǃƼǦƸƽẳǃƼǦƷǊồǃǦđộǃƼǦǋƐǄ.",
    ["徐吉祥"] = "ǥừǦƞƑǉǦǥườǃƼ",
    ["师父当年落魄汴京，差点饿死，是这位老人家给了一碗饭，才有咱们这一门。这道菜做不出来，咱们就别想着出师了。"] = "ƮưǦǅƽụǦǃăǂǦđƚǦǈƶǦƸơǦǁỡǦǋậǃǦởǦƝƾệǃǦƦƾǃƽ,ǦǈǊƈǉǦƸƽƕǉǦǉƽƔǦƸƽếǉǦđƚƾ,ǦǃƽờǦǁƃǄǦǃƽƁǃǦƼƾƶǦǃƐǓǦƸƽǄǦǂộǉǦƷƑǉǦƸơǂǦǂớƾǦƸƚǦǂƇǃǦǅƽƑƾǦƸƽƕǃƼǦǉƶǦǃƼƐǓǦǃƶǓ.ǦƨƚǃǦăǃǦǃƐǓǦǂƐǦǀƽƇǃƼǦǁƐǂǦđượƸ,ǦƸƽƕǃƼǦǉƶǦđừǃƼǦƽƛǃƼǦǃƼƽĩǦđếǃǦƸƽǊǓệǃǦǍǊấǉǦǈư.",
    ["宋如意"] = "ǥốǃƼǦƩƽưǦÝ",
    ["年轻人啊，我没几年活头了。别为我这老骨头费心。"] = "ƩƼườƾǦǉǇẻǦǉǊổƾǦƐ,ǦǉƶǦƸƽẳǃƼǦƸƛǃǦǈốǃƼǦđượƸǦǂấǓǦǃăǂǦǃữƶǦđƁǊ.ǦĐừǃƼǦǅƽƓǦǉƁǂǦǋƔǦƸƑƾǦǉƽƁǃǦƼƾƐǦǃƐǓ.",
    ["你们做的点心，好，像花儿一样好看，可吃到嘴里……没滋味。我想吃……山。"] = "ĐƾểǂǦǉƁǂǦƸƑƸǦǃƼươƾǦǁƐǂǦǉốǉǦǁắǂ,ǦđẹǅǦǃƽưǦƽǄƶǦǋậǓ,ǦǃƽưǃƼǦăǃǦǋƐǄǦǉǇǄǃƼǦǂƾệǃƼ...ǦƸƽẳǃƼǦƸƚǦǋịǦƼƔ.ǦǥƶǦǂǊốǃǦăǃ...Ǧǃƕƾ.",
    ["老人家说的山是……？"] = "ƩƕƾǦǂƐǦǁƃǄǦǃƽƁǃǦƼƾƶǦǃƚƾǦǁƐ...?",
    ["山啊，是用冰雪堆出来的，甜丝丝的山……"] = "ƩƕƾǦđƚǦƐ,ǦǁƐǦǤƖǃƼǦƷăǃƼǦǉǊǓếǉǦđắǅǦǉƽƐǃƽ,ǦǂộǉǦǃƼọǃǦǃƕƾǦǃƼọǉǦǁịǂ...",
    ["小时候在凉州尝过，那以后就一直惦记着……"] = "ƧƕƸǦǃƽỏǦǉƶǦǉừǃƼǦǃếǂǦǆǊƶǦởǦƧươǃƼǦƞƽƁǊ,ǦǉừǦđƚǦǋềǦǈƶǊǦƸứǦǃƽớǦǂƃƾǦǀƽƇǃƼǦǆǊƙǃ...",
    ["真对不住，太奶奶要午休了，几位……还请改天再来。"] = "ǥƽậǉǦǍƾǃǦǁỗƾ,ǦǉƽƑƾǦǃƃƾǦǃƃƾǦƸầǃǦǃƼƽỉǦǉǇưƶǦǇồƾ,ǦǂấǓǦǋị...ǦǂờƾǦƽƇǂǦǀƽƑƸǦǁạƾǦđếǃ.",
    ["“装彩树而形绮，杂红花而色斑，吮其味则峰峦入口，玩其象则琼瑶在颜。”"] = "\"ǥǇƶǃƼǦǉƽƑƾǦǉƽụǦǃƽƾǦƽƔǃƽǦǀƽởƾ,ǦǉạǅǦƽồǃƼǦƽǄƶǦǃƽƾǦǈắƸǦƷƶǃ,ǦǋẫǃǦǀỳǦǋịǦǉắƸǦǅƽǄǃƼǦǁǄƶǃǦǃƽậǅǦǀƽẩǊ,ǦǃƼǄạǃǦǀỳǦǉượǃƼǦǉắƸǦǆǊỳǃƽǦǤƶǄǦǉạƾǦǃƽƶǃ.\"",
    ["这是唐时的甜点，师父教过咱们……原来老奶奶想吃的是这个！"] = "ĐƁǓǦǁƐǦǂƚǃǦđồǦǃƼọǉǦǉƽờƾǦĐườǃƼ,ǦǈưǦǅƽụǦǉừǃƼǦǤạǓǦƸƽƕǃƼǦǉƶ...ǦƽƚƶǦǇƶǦǉƽƑƾǦǃƃƾǦǃƃƾǦǂǊốǃǦăǃǦƸƽƓǃƽǦǁƐǦƸƑƾǦǃƐǓ!",
    ["带牛乳的甜品，咱们试过许多，老人家还是说苦。这道酥山，恐怕没这么简单。"] = "ĐồǦǃƼọǉǦƸƚǦǈữƶǦƷƛǦƸƽƕǃƼǦǉƶǦđƃǦǉƽửǦǆǊƶǦǃƽƾềǊǦǇồƾ,ǦǁƃǄǦǃƽƁǃǦƼƾƶǦǋẫǃǦǀƙǊǦđắǃƼ.ǦƨƚǃǦǥƇǦƮơǃǦǃƐǓǦƺǦǁƐǦǀƽƇǃƼǦđơǃǦƼƾảǃǦǃƽưǦǋậǓ.",
    ["二位，我想老人家忘不了的，恐怕不是酥山，而是儿时的滋味。儿时的酥山如何做成，或许是破题之法？"] = "ƣƶƾǦǋị,ǦǉƶǦǃƼƽĩǦǉƽứǦǁƃǄǦǃƽƁǃǦƼƾƶǦǀƽƇǃƼǦǆǊƙǃǦđượƸǦƺǦǀƽƇǃƼǦǅƽảƾǦǥƇǦƮơǃ,ǦǂƐǦǁƐǦƽươǃƼǦǋịǦǉƽờƾǦǉƽơǦấǊ.ǦƞƑƸƽǦǁƐǂǦǥƇǦƮơǃǦǉƽǊởǦǃƽỏǦǃƽưǦǉƽếǦǃƐǄ,ǦƸƚǦǁẽǦƸƽƓǃƽǦǁƐǦƸƑƸƽǦƼƾảƾǦđề?",
    ["……这位是？"] = "...ƱịǦǃƐǓǦǁƐ?",
    ["莫要说笑！"] = "ĐừǃƼǦƸƚǦđƖƶǦƼƾỡǃ!",
    ["我在南门大街物色食材时见过你，是新春百味集集主，久仰！"] = "ǥƶǦǉừǃƼǦƼặǅǦǃƼƐƾǦǀƽƾǦđƶǃƼǦǉƔǂǦǀƾếǂǦǉƽựƸǦǉƐƾǦởǦđạƾǦǁộǦƩƶǂǦƨƇǃ,ǦǁƐǦǥậǅǦƸƽủǦƝƑƸƽǦƱịǦǥậǅǦǉƁǃǦǍǊƁǃ,ǦƸửǊǦǃƼưỡǃƼ!",
    ["……呃，好说，好说。"] = "...À,ǦǆǊƑǦǀƽƺǃ,ǦǆǊƑǦǀƽƺǃ.",
    ["集主所言颇有道理。一方水土一方菜肴，换了地方，滋味全变了。人……也变了。"] = "ƧờƾǦǥậǅǦƸƽủǦǃƚƾǦǇấǉǦƸƚǦǁƈ.ǦƨỗƾǦǋƖǃƼǦđấǉǦǂộǉǦǂƚǃǦăǃǦǇƾƙǃƼ,ǦđổƾǦǃơƾǦƸƽốǃǦǁƐǦƽươǃƼǦǋịǦƷƾếǃǦđổƾǦǈạƸƽ.ǦƩƼườƾ...ǦƸũǃƼǦđổƾǦǉƽƶǓ.",
    ["师弟，我们去买一趟食材。对了，再要一份太奶奶的药方来！"] = "ƮưǦđệ,ǦƸƽƕǃƼǦǉƶǦđƾǦǂǊƶǦǉƽựƸǦǉƐƾǦǂộǉǦƸƽǊǓếǃ.ǦĐƕǃƼǦǇồƾ,ǦǁấǓǦǉƽƙǂǦǂộǉǦƷảǃǦǤượƸǦǅƽươǃƼǦƸủƶǦǉƽƑƾǦǃƃƾǦǃƃƾǦǃữƶ!",
    ["两位喊我过来，可是有了头绪？"] = "ƣƶƾǦǋịǦƼọƾǦǉƶǦǆǊƶǦđƁǓ,ǦǁƐǦđƃǦƸƚǦǂƶǃƽǦǂốƾǦǇồƾǦǈƶǄ?",
    ["当日集主一语点醒梦中人。老人家常年服药，口中发苦，寻常的糖只能遮盖一时，过后更涩。"] = "ƣƇǂǦđƚǦǥậǅǦƸƽủǦǂộǉǦǁờƾǦǉƽứƸǦǉỉǃƽǦǃƼườƾǦǉǇǄǃƼǦǂộǃƼ.ǦƧƃǄǦǃƽƁǃǦƼƾƶǦǊốǃƼǦǉƽǊốƸǦǆǊƶǃƽǦǃăǂǦǃƙǃǦǂƾệǃƼǦƷịǦđắǃƼ,ǦđườǃƼǦǉƽƇǃƼǦǉƽườǃƼǦƸƽỉǦƸƽƺǦđậǓǦđượƸǦǃƽấǉǦǉƽờƾ,ǦǈƶǊǦđƚǦǁạƾǦƸƐǃƼǦƸƽƑǉǦƽơǃ.",
    ["想要化解这苦，得用食材去“和”。我们之前的甜品，用的牛乳太淡。得用凉州的牦牛奶，奶味更醇厚、更野！"] = "ƨǊốǃǦƽƚƶǦƼƾảƾǦƸƑƾǦđắǃƼǦǃƐǓ,ǦǅƽảƾǦǤƖǃƼǦǉƽựƸǦǉƐƾǦđểǦ\"ƽƛƶ\".ǦĐồǦǃƼọǉǦǉǇướƸǦđƁǓǦƸƽƕǃƼǦǉƶǦǁƐǂǦǤƖǃƼǦǈữƶǦƷƛǦǆǊƑǦǃƽạǉ.ǦƫƽảƾǦǤƖǃƼǦǈữƶǦƷƛǦǉƚǉǦƸủƶǦƧươǃƼǦƞƽƁǊ,ǦǋịǦǈữƶǦǂớƾǦǉƽǊầǃǦƽậǊǦǋƐǦǃƼǊǓƙǃǦƷảǃǦƽơǃ!",
    ["多亏有你帮忙，青溪弟子送来了陈皮粉，能中和奶腥，用焦糖盖住药苦。"] = "ƩƽờǦƸƚǦǃƼƐƾǦƼƾƕǅǦđỡ,ǦđệǦǉửǦǥƽƶǃƽǦƦƽƙǦđƃǦƼửƾǦƷộǉǦǉǇầǃǦƷƔǦđếǃ,ǦƸƚǦǉƽểǦǉǇǊǃƼǦƽƛƶǦǋịǦǉƶǃƽǦƸủƶǦǈữƶ,ǦǤƖǃƼǦđườǃƼǦƸƶǇƶǂƺǁǦđểǦǁấǅǦđƾǦǋịǦđắǃƼǦƸủƶǦǉƽǊốƸ.",
    ["狂澜给的酒，还能把坚果去腥提鲜，把烈味逼出来！"] = "ƭượǊǦƞǊồǃƼǦƧƶǃǦƸƽǄǦƸƛǃǦƸƚǦǉƽểǦǀƽửǦǉƶǃƽǦǉăǃƼǦǉươƾǦƸƽǄǦƸƑƸǦǁǄạƾǦƽạǉ,ǦƗǅǦǋịǦǃồǃƼǦǇƶǦǃƼǄƐƾ!",
    ["孩童的舌头灵，一尝就能记住酸甜苦辣。而如今这道酥山，我们找不到凉州的雪，但还能努力凑齐一点“甜”。"] = "ƧưỡƾǦǉǇẻǦƸǄǃǦǇấǉǦǃƽạǓ,ǦǃếǂǦǂộǉǦƸƑƾǦǁƐǦǃƽớǦđượƸǦƸƽǊƶǦƸƶǓǦǂặǃǦđắǃƼ.ǦƨƐǦǂƚǃǦǥƇǦƮơǃǦƽƇǂǦǃƶǓ,ǦƸƽƕǃƼǦǉƶǦǀƽƇǃƼǦǉƔǂǦđượƸǦǉǊǓếǉǦƧươǃƼǦƞƽƁǊ,ǦǃƽưǃƼǦǋẫǃǦƸƚǦǉƽểǦǃỗǦǁựƸǦƼǄǂǦƼƚǅǦǁạƾǦǂộǉǦƸƽƕǉǦ\"ǃƼọǉ\".",
    ["底层是凿碎的冰雪，中间是牦牛乳冻，上面有琥珀色的焦糖。这道菜，图一个“苦尽甘来”。"] = "ƧớǅǦǤướƾǦƸƖǃƼǦǁƐǦƷăǃƼǦǉǊǓếǉǦđụƸǦǋụǃ,ǦởǦƼƾữƶǦǁƐǦǉƽạƸƽǦǈữƶǦƷƛǦǉƚǉ,ǦƷƙǃǦǉǇƙǃǦƸƚǦđườǃƼǦƸƶǇƶǂƺǁǦǂƐǊǦƽổǦǅƽƑƸƽ.ǦƨƚǃǦăǃǦǃƐǓǦƸƽƓǃƽǦǁƐǦǂǄǃƼǦƸầǊǦǂộǉǦƸƽữǦ\"ǀƽổǦǉậǃǦƸƶǂǦǁƶƾ\".",
    ["来，这一碗给你。集主尝尝，可还喜欢？"] = "ƩƐǄ,ǦƷƑǉǦǃƐǓǦƸƽǄǦǃƼƐƾ.ǦǥậǅǦƸƽủǦǃếǂǦǉƽửǦǍƺǂ,ǦƸƚǦǉƽƓƸƽǦǀƽƇǃƼ?",
    ["这美味……似曾相识。或许是梦中吃过吧。"] = "ƱịǦǃƼǄǃǦǃƐǓ...ǦǤườǃƼǦǃƽưǦđƃǦǉừǃƼǦƼặǅǦởǦđƁǊǦđƚ.ǦƞƚǦǁẽǦǁƐǦđƃǦǉừǃƼǦăǃǦǉǇǄǃƼǦǂơǦƸƽăǃƼ.",
    ["甜的……是甜的！"] = "ƩƼọǉ...ǦǁƐǦǋịǦǃƼọǉ!",
    ["这股子烈劲儿……是我小时候吃到的味儿！"] = "ƞƑƾǦǋịǦǃồǃƼǦđậǂǦǃƐǓ...ǦƸƽƓǃƽǦǁƐǦƽươǃƼǦǋịǦǉƶǦǉừǃƼǦăǃǦǁƕƸǦǃƽỏ!",
    ["还记得……当年阿爹做成了第一笔生意，带着我去集市玩耍。"] = "ƱẫǃǦƸƛǃǦǃƽớ...ǦǃăǂǦđƚǦƜǦƸƽƶǦǁƐǂǦǉƽƐǃƽǦǉƽươǃƼǦǋụǦđầǊǦǉƾƙǃ,ǦǤắǉǦǉƶǦđƾǦǉậǅǦǉƽịǦƸƽơƾǦđƖƶ.",
    ["我还是个六岁的娃娃，躲在爹的皮袄里……"] = "ǥƶǦǀƽƾǦđƚǦǂớƾǦǁƐǦđứƶǦǉǇẻǦǈƑǊǦǉǊổƾ,ǦǉǇốǃǦǉǇǄǃƼǦƑǄǦǤƶǦƸủƶǦƸƽƶ...",
    ["家师说，今日这碗酥山，是替那个穷小子还愿的。"] = "ƢƾƶǦǈưǦǃƚƾ,ǦƷƑǉǦǥƇǦƮơǃǦǃƼƐǓǦƽƇǂǦǃƶǓǦǁƐǦđểǦƽǄƐǃǦǃƼǊǓệǃǦǉƽƶǓǦƸƽǄǦǉƾểǊǦǉửǦǃƼƽƘǄǦǃăǂǦđƚ.",
    ["您要是“想吃”，我们师姐弟就算是做了道好菜。"] = "ƩƼườƾǦǃếǊǦ\"ǂǊốǃǦăǃ\",ǦǉỷǦđệǦƸƽƕǃƼǦƸǄǃǦƸǄƾǦǃƽưǦđƃǦǁƐǂǦđượƸǦǂộǉǦǂƚǃǦǃƼǄǃǦǇồƾ.",
    ["太奶奶……您……"] = "ǥƽƑƾǦǃƃƾǦǃƃƾ...ǦǃƼườƾ...",
    ["想吃，怎么不想吃！"] = "ƨǊốǃǦăǃ,ǦǈƶǄǦǁạƾǦǀƽƇǃƼǦǂǊốǃǦăǃǦƸƽứ!",
    ["孩子，你也来尝一口，这是咱们老家的味道。"] = "ƞǄǃǦƐ,ǦƸǄǃǦƸũǃƼǦǁạƾǦǃếǂǦǂộǉǦǃƼụǂǦđƾ,ǦđƁǓǦǁƐǦƽươǃƼǦǋịǦǁƃǄǦƼƾƶǦƸƽƕǃƼǦǉƶǦđấǓ.",
    ["一晃眼……这上次吃到甜味，已过了一百年啊。"] = "ǥƽǄắǉǦƸƑƾ...ǦǁầǃǦƸǊốƾǦƸƖǃƼǦǃếǂǦđượƸǦǋịǦǃƼọǉǦǃƐǓ,ǦđƃǦǆǊƶǦǂộǉǦǉǇăǂǦǃăǂǦǇồƾ.",
    ["集主！集主！这边！"] = "ǥậǅǦƸƽủ!ǦǥậǅǦƸƽủ!ǦƝƙǃǦǃƐǓ!",
    ["这人挤人的，差点没看到你们。"] = "ƩƼườƾǦđƇǃƼǦǃƼƽịǉǦǉƽếǦǃƐǓ,ǦǈǊƈǉǦǃữƶǦǉƽƔǦǀƽƇǃƼǦǉƽấǓǦƸƑƸǦǃƼươƾǦǇồƾ.",
    ["来了好多好多人啊！跟做梦一样……"] = "ĐếǃǦǉƽậǉǦǃƽƾềǊǦǉƽậǉǦǃƽƾềǊǦǃƼườƾǦǁǊƇǃ!ǦƢƾốǃƼǦǃƽưǦđƶǃƼǦǃằǂǦǂơǦǋậǓ...",
    ["哥哥姐姐们说啦，今晚生意可红火了！"] = "ƞƑƸǦƸƶǦƸƶǦǉỷǦǉỷǦǃƚƾǦǇồƾ,ǦǉốƾǦǃƶǓǦǁƐǂǦăǃǦƽồǃƼǦƽỏƶǦǁắǂ!",
    ["赚到的钱，都要换成白米白面，送给吃不上饭的人。"] = "ǥƾềǃǦǀƾếǂǦđượƸǦđềǊǦǅƽảƾǦđổƾǦǉƽƐǃƽǦƼạǄǦǉǇắǃƼǦǂƔǦǉǇắǃƼ,ǦǉặǃƼǦƸƽǄǦǃƽữǃƼǦǃƼườƾǦǀƽƇǃƼǦƸƚǦƸơǂǦăǃ.",
    ["要是还有剩的，就给受冻的人家送棉袄、送褥子！"] = "ƩếǊǦƸƛǃǦǤưǦǉƽƔǦǈẽǦǉặǃƼǦƑǄǦƷƇǃƼ,ǦǉặǃƼǦƸƽăǃǦǃệǂǦƸƽǄǦǃƽữǃƼǦǃƽƐǦđƶǃƼǦƷịǦǁạǃƽ!",
    ["嘿嘿，多亏了集主，这件大事真的办成了！"] = "ƣƾǦƽƾ,ǦǃƽờǦƸƚǦǥậǅǦƸƽủǦǂƐǦđạƾǦǈựǦǃƐǓǦǉƽựƸǦǈựǦđƃǦǉƽƐǃƽǦƸƇǃƼǦǇồƾ!",
    ["大侠师父！"] = "ĐạƾǦƽƾệǅǦǈưǦǅƽụ!",
    ["我娘交给我一个秘密任务……为了百姓的安危，我要不着痕迹地潜伏在人群中……"] = "ƩươǃƼǦƼƾƶǄǦƸƽǄǦƸǄǃǦǂộǉǦǃƽƾệǂǦǋụǦƷƓǦǂậǉ...ǦǋƔǦǈựǦƶǃǦǃƼǊǓǦƸủƶǦƷƑƸƽǦǉƓǃƽ,ǦƸǄǃǦǅƽảƾǦǂƶƾǦǅƽụƸǦǉǇǄǃƼǦđƑǂǦđƇǃƼǦǂƐǦǀƽƇǃƼǦđểǦǁộǦǤấǊǦǋếǉ...",
    ["遇到危急情况，就立刻出手！"] = "ƢặǅǦǉƔǃƽǦƽǊốǃƼǦǃƼǊǓǦƸấǅǦǁƐǦǁậǅǦǉứƸǦǇƶǦǉƶǓ!",
    ["你这么小，能出什么手？"] = "ƞǄǃǦǃƽỏǦǉƽếǦǃƐǓǦǉƽƔǦǇƶǦǉƶǓǦđượƸǦƼƔǦƸƽứ?",
    ["娘说，要是遇到需要帮忙的事儿，无论是抓贼还是救人，都立刻去告诉她！"] = "ƩươǃƼǦǃƚƾ,ǦǃếǊǦƼặǅǦƸƽǊǓệǃǦƸầǃǦƼƾƕǅǦđỡ,ǦƷấǉǦǀểǦǁƐǦƷắǉǦǉǇộǂǦƽƶǓǦƸứǊǦǃƼườƾ,ǦđềǊǦǅƽảƾǦǁậǅǦǉứƸǦđƾǦƷƑǄǦƸƽǄǦǃươǃƼ!",
    ["她说我的轻功和伪装功夫好，这事儿只能交给我办，大人们都不如我！"] = "ƩươǃƼǦƷảǄǦǀƽƾǃƽǦƸƇǃƼǦǋƐǦƸƇǃƼǦǅƽǊǦǃƼụǓǦǉǇƶǃƼǦƸủƶǦƸǄǃǦǉốǉ,ǦǋƾệƸǦǃƐǓǦƸƽỉǦƸƚǦǉƽểǦƼƾƶǄǦƸƽǄǦƸǄǃǦǁƐǂ,ǦǃƼườƾǦǁớǃǦđềǊǦǀƽƇǃƼǦƷằǃƼǦƸǄǃ!",
    ["魏姨这管孩子的本事也太厉害了。"] = "ƝảǃǦǈựǦǆǊảǃǦǤạǓǦƸǄǃǦƸƑƾǦƸủƶǦƩƼụǓǦǤƾǦƸũǃƼǦǆǊƑǦǁợƾǦƽạƾǦǇồƾ.",
    ["好啦好啦，大侠也不能光顾着行侠仗义。"] = "ĐượƸǦǇồƾǦđượƸǦǇồƾ,ǦđạƾǦƽƾệǅǦƸũǃƼǦǀƽƇǃƼǦǉƽểǦƸƽỉǦǂảƾǦǂƙǦƽƐǃƽǦƽƾệǅǦǉǇượǃƼǦǃƼƽĩƶ.",
    ["大过年的，吃得开心，玩得尽兴，也是大侠的职责。"] = "ƩƼƐǓǦǥếǉǦǂƐ,ǦăǃǦǊốǃƼǦǋǊƾǦǋẻ,ǦƸƽơƾǦƷờƾǦƽếǉǦǂƔǃƽǦƸũǃƼǦǁƐǦƸƽứƸǦǉǇƑƸƽǦƸủƶǦđạƾǦƽƾệǅ.",
    ["办集市可真有趣！大个子说得对，比进皇宫偷东西好多了！"] = "ǥổǦƸƽứƸǦǉậǅǦǉƽịǦǉƽậǉǦǉƽƕǦǋị!ǦĐạƾǦƸƑǦǉửǦǃƚƾǦđƕǃƼ,ǦǉốǉǦƽơǃǦǃƽƾềǊǦǈǄǦǋớƾǦǋƾệƸǦǋƐǄǦƽǄƐǃƼǦƸǊǃƼǦǉǇộǂǦđồ!",
    ["嘘，可别再提偸皇宫啦！"] = "ƮǊỵǉ,ǦđừǃƼǦƸƚǦǃƽắƸǦǁạƾǦƸƽǊǓệǃǦǉǇộǂǦƽǄƐǃƼǦƸǊǃƼǦǃữƶ!",
    ["对了大个子，下回记得帮我们多谢那个胖叔叔！"] = "ĐƕǃƼǦǇồƾǦĐạƾǦƸƑǦǉử,ǦǁầǃǦǈƶǊǦǃƽớǦƼƾƕǅǦǉụƾǦǂǊộƾǦƸảǂǦơǃǦǉƽƕƸǦǉƽƕƸǦƷƗǄǦđƚǦǃƽƗ!",
    ["要不是他送来的一大车银钱和米粮，咱们这花灯架子都搭不起来呢。"] = "ƩếǊǦǀƽƇǃƼǦǃƽờǦǍƺǦǉƾềǃǦƷạƸǦǋƐǦǁươǃƼǦǂễǦǁớǃǦǂƐǦǉƽƕƸǦấǓǦƼửƾǦđếǃ,ǦƸƑƾǦƼƾƐǃǦƽǄƶǦđăǃƼǦǃƐǓǦƸủƶǦǉụƾǦǂǊộƾǦƸƛǃǦƸƽẳǃƼǦǤựǃƼǦǁƙǃǦǃổƾǦđƁǊ.",
    ["嗯，就是那天领头送东西来的胖叔叔……笑起来眼睛眯成一条缝的那个！"] = "Ừǂ,ǦƸƽƓǃƽǦǁƐǦǋịǦǉƽƕƸǦǉƽƕƸǦƷƗǄǦǤẫǃǦđầǊǦđǄƐǃǦƸƽởǦđồǦđếǃǦƽƇǂǦđƚǦđƚ...ǦǁƕƸǦƸườƾǦǂắǉǦƽƓǅǦǁạƾǦǉƽƐǃƽǦǂộǉǦđườǃƼǦƸƽỉǦấǓ!",
    ["我们问他是谁，他只说是您的江湖朋友。"] = "ǥụƾǦǂǊộƾǦƽỏƾǦǉƽƕƸǦấǓǦǁƐǦƶƾ,ǦǉƽƕƸǦấǓǦƸƽỉǦƷảǄǦǁƐǦƷằǃƼǦƽữǊǦƼƾƶǃƼǦƽồǦƸủƶǦƽǊǓǃƽ.",
    ["嘿嘿，肯定也是位了不起的大侠！就是……肚子稍微大了点儿！"] = "ƣƾǦƽƾ,ǦƸƽắƸǦƸƽắǃǦƸũǃƼǦǁƐǦǂộǉǦǋịǦđạƾǦƽƾệǅǦǁừǃƼǦǁẫǓ!ǦƞƽỉǦǁƐ...ǦƷụǃƼǦƽơƾǦǉǄǦǂộǉǦƸƽƕǉ!",
    ["……原来是他……"] = "...ƣƚƶǦǇƶǦǁƐǦƇǃƼǦǉƶ...",
    ["嗯，这份谢意，我一定带到。"] = "Ừǂ,ǦǁƛǃƼǦǉƽƐǃƽǦǃƐǓǦǉƶǦǃƽấǉǦđịǃƽǦǈẽǦƸƽǊǓểǃǦǁờƾ.",
    ["小掌柜！这盏花灯怎么卖？"] = "ǥƾểǊǦƸƽưởǃƼǦǆǊỹ!ǦƞƽƾếƸǦƽǄƶǦđăǃƼǦǃƐǓǦƷƑǃǦǉƽếǦǃƐǄ?",
    ["来啦来啦！大个子，生意上门，我们先去忙啦。"] = "ĐếǃǦđƁǓǦđếǃǦđƁǓ!ǦĐạƾǦƸƑǦǉử,ǦƸƚǦǀƽƑƸƽǦǇồƾ,ǦǉụƾǦǂǊộƾǦđƾǦƷậǃǦǋƾệƸǦđƁǓ.",
    ["对了，我们给你留了好东西，一会儿别忘了来拿！"] = "ĐƕǃƼǦǇồƾ,ǦǉụƾǦǂǊộƾǦƸƚǦđểǦǤƐǃƽǦđồǦǉốǉǦƸƽǄǦƽǊǓǃƽǦđấǓ,ǦǁƑǉǦǃữƶǦđừǃƼǦǆǊƙǃǦǆǊƶǦǁấǓǦǃƽƗ!",
    ["嗯，去吧。"] = "Ừǂ,ǦđƾǦđƾ.",
    ["哇哇！是星点点！好美啊！田姑田姑，你快看，你快看！"] = "ƪƶǦǄƶ!ǦƧƐǦǉƾǃƽǦđƾểǂǦđƾểǂ!ǦĐẹǅǦǆǊƑ!ǦĐƾềǃǦƸƇǦĐƾềǃǦƸƇ,ǦǉỷǦǂƶǊǦǍƺǂ,ǦǉỷǦǂƶǊǦǍƺǂ!",
    ["是啊，自己打个铁花感觉就是不一样！你要不要上去试试？"] = "ĐƕǃƼǦǋậǓ,ǦǉựǦǂƔǃƽǦđƑǃƽǦǥƽƾếǉǦƣǄƶǦƸảǂǦƼƾƑƸǦđƕǃƼǦǁƐǦǀƽƑƸǦƷƾệǉ!ǦƨǊộƾǦƸƚǦǂǊốǃǦǁƙǃǦǉƽửǦƸƽƕǉǦǀƽƇǃƼ?",
    ["好啊，等会我就试试！打个铁花，保佑来年都顺顺利利！"] = "ĐượƸǦạ,ǦǁƑǉǦǃữƶǦǂǊộƾǦǈẽǦǉƽử!ǦĐƑǃƽǦǂộǉǦǉǇậǃǦǥƽƾếǉǦƣǄƶ,ǦƸầǊǦƸƽǄǦǃăǂǦǈƶǊǦđềǊǦǉƽǊậǃǦǉƽǊậǃǦǁợƾǦǁợƾ!",
    ["都试试！自己打出来的感觉就是不一样！莫莫，来这！别被挤着了！"] = "ǥƽửǦƽếǉǦđƾ!ǦǥựǦǂƔǃƽǦđƑǃƽǦǇƶǦƸảǂǦƼƾƑƸǦƽǄƐǃǦǉǄƐǃǦǀƽƑƸǦđấǓ!ǦƨạƸǦƨạƸ,ǦǁạƾǦđƁǓ!ǦĐừǃƼǦđểǦƷịǦƸƽƺǃǦǁấǃ!",
    ["瓜果备齐，豆馅拌好……再把这桂花蜜酿着……"] = "ƬǊảǦǉươƾǦƸƽǊẩǃǦƷịǦđủ,ǦǃƽƁǃǦđậǊǦđƃǦǉǇộǃǦǍǄǃƼ...ǦǁạƾǦủǦǉƽƙǂǦƸƽỗǦǂậǉǦƽǄƶǦǆǊếǦǃƐǓǦǃữƶ...",
    ["嗯，我这手艺啊，一点都没落下！"] = "Ừǂ,ǦǉƽủǦǃƼƽệǦǃƐǓǦƸủƶǦǉƶǦƸƽẳǃƼǦƽềǦǂƶƾǦǂộǉǦƸƽƕǉǦǃƐǄ!",
    ["游侠，可是还想了解什么发明？"] = "ǝǊǦƽƾệǅ,ǦǅƽảƾǦƸƽăǃƼǦǋẫǃǦǂǊốǃǦǉƔǂǦƽƾểǊǦǉƽƙǂǦǋềǦǅƽƑǉǦǂƾǃƽǦǃƐǄ?",
    ["这个，这个我记得小八给了我一张口诀，让我找找……"] = "ƞƑƾǦǃƐǓ,ǦƸƑƾǦǃƐǓǦǉƶǦǃƽớǦǥƾểǊǦƝƑǉǦƸƚǦđưƶǦƸƽǄǦǉƶǦǂộǉǦǉờǦǀƽẩǊǦǆǊǓếǉ,ǦđểǦǉƶǦǉƔǂǦǍƺǂ...",
    ["吾父之父，何以呼之？耶耶……耶耶？吾母之母，何以呼之？婆婆……婆婆？"] = "ƞƽƶǦƸủƶǦƸƽƶǦǉƶ,ǦƼọƾǦǁƐǦƼƔ?ǦƢƾƶǦƼƾƶ...ǦƼƾƶǦƼƾƶ?ǦƨẹǦƸủƶǦǂẹǦǉƶ,ǦƼọƾǦǁƐǦƼƔ?ǦƝƐǦǃƼǄạƾ...ǦƷƐǦǃƼǄạƾ?",
    ["这纸条好像拿错了……不要紧，一会去找师妹问问！"] = "ƨảǃƽǦƼƾấǓǦǃƐǓǦƽƔǃƽǦǃƽưǦǁấǓǦǃƽầǂǦǇồƾ...ǦǀƽƇǃƼǦǈƶǄ,ǦǁƑǉǦǃữƶǦđƾǦǉƔǂǦǈưǦǂǊộƾǦƽỏƾǦǍƺǂ!",
    ["转运楼在二层，游侠只要上去转一转，今年定能时来运转，鸿运当头！"] = "ƞƽǊǓểǃǦƱậǃǦƧầǊǦởǦǉầǃƼǦƽƶƾ,ǦǤǊǦƽƾệǅǦƸƽỉǦƸầǃǦǁƙǃǦđƚǦǤạǄǦǂộǉǦǋƛǃƼ,ǦǃăǂǦǃƶǓǦǃƽấǉǦđịǃƽǦǈẽǦǉƽờƾǦǁƶƾǦǋậǃǦƸƽǊǓểǃ,ǦƽồǃƼǦǋậǃǦđươǃƼǦđầǊ!",
    ["呃……这彩虹毯嘛，是小八最新的研究成果，看上去不错，听着也很悦耳……"] = "Ờ...ǦǉấǂǦǉƽảǂǦƸầǊǦǋồǃƼǦǃƐǓǦƐ,ǦǁƐǦǉƽƐǃƽǦǆǊảǦǃƼƽƾƙǃǦƸứǊǦǂớƾǦǃƽấǉǦƸủƶǦǥƾểǊǦƝƑǉ,ǦǃƽƔǃǦǆǊƶǦǉƽƔǦǀƽƇǃƼǦǉệ,ǦǃƼƽƺǦƸũǃƼǦǇấǉǦƙǂǦǉƶƾ...",
    ["但我总觉得此物……有些蹊跷，你走上去的时候小心些。"] = "ƩƽưǃƼǦǉƶǦƸứǦǉƽấǓǦǋậǉǦǃƐǓ...ǦƸƚǦƸƽƕǉǦǀỳǦǆǊặƸ,ǦǁƕƸǦǃƼươƾǦƷướƸǦǁƙǃǦǃƽớǦƸẩǃǦǉƽậǃǦǂộǉǦƸƽƕǉ.",
    ["欸，冯大哥，你来看看，这又是什么？"] = "Ê,ǦƫƽƖǃƼǦđạƾǦƸƶ,ǦƽǊǓǃƽǦǁạƾǦđƁǓǦǍƺǂ,ǦđƁǓǦǁƐǦƸƑƾǦƼƔǦǉƽế?",
    ["咦？我记得都介绍完了啊……是我漏掉什么了吗？"] = "Ơ?ǦǥƶǦǃƽớǦǁƐǦƼƾớƾǦǉƽƾệǊǦƽếǉǦǇồƾǦǂƐ...ǦǁƐǦǉƶǦƷỏǦǈƚǉǦƼƔǦǈƶǄ?",
    ["停，冯大哥，就站在这，对对，就这个角度！冯大哥，我观你这气势，这样貌，来日定成巨子啊！"] = "ǝừǃƼ,ǦƫƽƖǃƼǦđạƾǦƸƶ,ǦƸứǦđứǃƼǦởǦđƁǓ,ǦđƕǃƼǦđƕǃƼ,ǦƼƚƸǦđộǦǃƐǓǦǃƐǓ!ǦƫƽƖǃƼǦđạƾǦƸƶ,ǦǉƶǦǆǊƶǃǦǈƑǉǦǀƽƓǦǉƽếǦǃƐǓ,ǦǉướǃƼǦǂạǄǦǃƐǓǦƸủƶǦƽǊǓǃƽ,ǦǉươǃƼǦǁƶƾǦƸƽắƸǦƸƽắǃǦǈẽǦǉǇởǦǉƽƐǃƽǦƞựǦǉửǦđấǓ!",
    ["一、二、三——巨子——"] = "ƨộǉ,Ǧƽƶƾ,ǦƷƶǦ——ǦƞựǦǉửǦ——",
    ["天干物燥——小心火烛——！新春大吉——！"] = "ǥƽƾƙǃǦƸƶǃǦǋậǉǦǉƑǄǦ——ǦƞẩǃǦǉƽậǃǦƽỏƶǦƸƽƕƸǦ——!ǦǥƁǃǦǍǊƁǃǦđạƾǦƸƑǉǦ——!",
    ["哎唷老陈，一年不见，越活越年轻啦！"] = "ÁƾǦƸƽƐǦƧƃǄǦǥǇầǃ,ǦǂộǉǦǃăǂǦǀƽƇǃƼǦƼặǅ,ǦƸƐǃƼǦǈốǃƼǦƸƐǃƼǦǉǇẻǦǇƶǦđấǓ!",
    ["在外跑生意，昨个刚回来！还是咱汴京城好啊！"] = "ƞƽạǓǦǋẩǓǦƷƙǃǦǃƼǄƐƾǦǁƐǂǦăǃ,ǦƽƇǂǦǆǊƶǦǂớƾǦǋề!ǦƱẫǃǦǁƐǦǉƽƐǃƽǦƝƾệǃǦƦƾǃƽǦƸƽƕǃƼǦǉƶǦǉốǉǦǃƽấǉ!",
    ["打扰一下，请问您可是郝娘子？"] = "ƨạǄǦǂǊộƾǦǁƐǂǦǅƽƾềǃ,ǦǍƾǃǦƽỏƾǦǃƼƐƾǦƸƚǦǅƽảƾǦǁƐǦƣƑƸƽǦǃươǃƼǦǉử?",
    ["小福她们三个跟我念叨了大半天，说有位手艺一绝的摊主，要参加百味集义卖……"] = "ǥƾểǊǦƫƽƕƸǦƷƶǦđứƶǦǉụƾǦǃƚǦǁảƾǦǃƽảƾǦǋớƾǦǉƶǦǃửƶǦǃƼƐǓǦǉǇờƾ,ǦƷảǄǦƸƚǦǂộǉǦǋịǦǈạǅǦƸƽủǦǉƽủǦǃƼƽệǦǉǊǓệǉǦđỉǃƽǦǂǊốǃǦǉƽƶǂǦƼƾƶǦǃƼƽĩƶǦǂạƾǦởǦƝƑƸƽǦƱịǦǥậǅ...",
    ["哎呀，想必您就是集主了！您来得正好，快来看看我这备菜区。"] = "ÁƾǦƸƽƐ,ǦƸƽắƸǦƽẳǃǦǃƼƐƾǦǁƐǦǥậǅǦƸƽủǦǇồƾ!ǦƩƼƐƾǦđếǃǦđƕǃƼǦǁƕƸǦǁắǂ,ǦǂƶǊǦǁạƾǦǍƺǂǦǀƽǊǦƸƽǊẩǃǦƷịǦǉƽứƸǦăǃǦƸủƶǦǉƶǦǃƐǓ.",
    ["寻常摊子只卖几种吃食……可您这摊位的食材分外多啊？"] = "ƮạǅǦƽƐǃƼǦǉƽƇǃƼǦǉƽườǃƼǦƸƽỉǦƷƑǃǦǋƐƾǦǁǄạƾǦǉƽứƸǦăǃ...ǦǂƐǦǉƽựƸǦǉƐƾǦởǦǈạǅǦƸủƶǦǃƼƐƾǦǁạƾǦđặƸǦƷƾệǉǦǃƽƾềǊǦǃƽỉ?",
    ["您说对了，我这小吃摊的招牌就是【好又多，多又快]，啥都能做，做好就拿，边走边吃！"] = "ƩƼƐƾǦǃƚƾǦđƕǃƼǦǇồƾ,ǦƷảǃƼǦƽƾệǊǦǈạǅǦđồǦăǃǦǋặǉǦǃƐǓǦƸủƶǦǉƶǦƸƽƓǃƽǦǁƐǦ[ƣảǄǦƣựǊǦĐƶ,ǦĐƶǦƣựǊǦƦƽǄƑƾ],ǦƸƑƾǦƼƔǦƸũǃƼǦǁƐǂǦđượƸ,ǦǁƐǂǦǍǄǃƼǦǁƐǦǁấǓǦǃƼƶǓ,ǦǋừƶǦđƾǦǋừƶǦăǃ!",
    ["这集市人山人海，新奇玩意儿多，还有那么多地方要逛呢，客官们都不想久等。"] = "ǥậǅǦǉƽịǦǃƐǓǦǃƼườƾǦđƇǃƼǦǃườǂǦǃượǅ,ǦđồǦƸƽơƾǦǂớƾǦǁạǦǉƽƔǦǃƽƾềǊ,ǦǁạƾǦƸƛǃǦƷƶǄǦǃƽƾƙǊǦƸƽỗǦǅƽảƾǦǤạǄ,ǦǀƽƑƸƽǦǆǊƶǃǦƶƾǦǃấǓǦđềǊǦǀƽƇǃƼǦǂǊốǃǦƸƽờǦǁƁǊ.",
    ["所以我灵机一动，把这几百斤原料都切好、腌好、分装在这一小碗一小碗里。客官一来，哗啦往锅里一倒，三下五除二，立马出锅！"] = "ƞƽǄǦǃƙǃǦǉƶǦǃảǓǦǇƶǦƈǦƽƶǓ,ǦđƺǂǦǂấǓǦǉǇăǂǦƸƁǃǦǃƼǊǓƙǃǦǁƾệǊǦǃƐǓǦǉƽƑƾǦǈẵǃ,ǦướǅǦǈẵǃ,ǦƸƽƾƶǦǋƐǄǦǉừǃƼǦƷƑǉǦǃƽỏǦǉƽếǦǃƐǓ.ǦƦƽƑƸƽǦǆǊƶǃǦǋừƶǦđếǃ,ǦƐǄǦǂộǉǦƸƑƾǦđổǦǋƐǄǦǃồƾ,ǦǁǄƑǃƼǦǂộǉǦƸƑƾǦǁƐǦǇƶǦǁƛǦǃƼƶǓ!",
    ["唔，预先备好，加热即食……那不就是……预、制？"] = "Ưǂ,ǦƸƽǊẩǃǦƷịǦǈẵǃ,ǦǁƐǂǦǃƚǃƼǦǁƐǦăǃǦđượƸǦǃƼƶǓ...ǦđƚǦƸƽẳǃƼǦǅƽảƾǦǁƐ...ǦǤự,ǦƸƽếǦǈƶǄ?",
    ["唉！这可不兴说啊，集主！您看这梨、桃，都还带着露水呢，面也是今早刚和的！我只是把功夫花在了前头，锅气那是足足的！"] = "ƣƶƾǏǏ!ǦƞƑƾǦǃƐǓǦǀƽƇǃƼǦđượƸǦǃƚƾǦƷừƶǦđƁǊǦǃƽƶǦǥậǅǦƸƽủ!ǦƩƼƐƾǦǍƺǂǦǁƙǦǃƐǓ,ǦđƐǄǦǃƐǓ,ǦǋẫǃǦƸƛǃǦđọǃƼǦǈươǃƼǦđƁǓǦǃƐǓ,ǦƷộǉǦƸũǃƼǦǁƐǦǂớƾǦǃƽƐǄǦǈƑǃƼǦǃƶǓǦǉƽƇƾ!ǦǥƶǦƸƽỉǦǁƐǦƷỏǦƸƇǃƼǦǈứƸǦƸƽǊẩǃǦƷịǦǉǇướƸ,ǦƸƽứǦƽỏƶǦƽầǊǦǃồƾǦǃƾƙǊǦǁƐǦƸựƸǦǀỳǦđầǓǦđủǦđấǓ!",
    ["绝对现炒，绝无预制！我这摊位别的不敢多说，就这现炒的诚意敢摸着良心保证！"] = "ǥǊǓệǉǦđốƾǦǍƐǄǦǉươƾ,ǦǉǊǓệǉǦǀƽƇǃƼǦǤựǦƸƽế!ǦƮạǅǦƽƐǃƼǦǃƐǓǦƸủƶǦǉƶǦǃƽữǃƼǦǉƽứǦǀƽƑƸǦǀƽƇǃƼǦǤƑǂǦǃƚƾǦǃƽƾềǊ,ǦƸƽứǦǇƾƙǃƼǦƸƑƾǦǉƽƐǃƽǦƈǦǍƐǄǦǉươƾǦǃƐǓǦǁƐǦǤƑǂǦǈờǦǉƶǓǦǁƙǃǦǁươǃƼǦǉƁǂǦǂƐǦƷảǄǦđảǂ!",
    ["玩笑，玩笑！我看着食材确实新鲜得很。"] = "ĐƖƶǦǉƽƇƾ,ǦđƖƶǦǉƽƇƾ!ǦǥƶǦǉƽấǓǦǉƽựƸǦǉƐƾǦđƕǃƼǦǁƐǦǇấǉǦǉươƾǦǃƼǄǃ.",
    ["眼下我唯一发愁的就是……生意太好怎么办？我只有两只手，炒得过来，却递不过去啊。"] = "ƣƾệǃǦƼƾờǦđƾềǊǦǤǊǓǦǃƽấǉǦǉƶǦǁǄǦǁắǃƼǦƸƽƓǃƽǦǁƐ...ǦǁƐǂǦăǃǦǉốǉǦǆǊƑǦǉƽƔǦǅƽảƾǦǁƐǂǦǈƶǄ?ǦǥƶǦƸƽỉǦƸƚǦƽƶƾǦƷƐǃǦǉƶǓ,ǦǍƐǄǦǉƽƔǦǀịǅǦǂƐǦđưƶǦƸƽǄǦǀƽƑƸƽǦǉƽƔǦǀƽƇǃƼǦǍǊể.",
    ["郝娘子多虑了。不瞒您说，我自小就在顾客盈门的馆子长大。人再多，菜一样样出锅，哪有顾不顾来的时候？"] = "ƣƑƸƽǦǃươǃƼǦǉửǦǁǄǦǍƶǦǇồƾ.ǦƦƽƇǃƼǦƼƾấǊǦƼƔǦǃƼƐƾ,ǦǉƶǦǉừǦǃƽỏǦđƃǦǁớǃǦǁƙǃǦǉǇǄǃƼǦǆǊƑǃǦǍƑǦǀƽƑƸƽǦǀƽứƶǦđầǓǦǃƽƐ.ǦƩƼườƾǦƸƚǦđƇǃƼǦđếǃǦđƁǊ,ǦǂƚǃǦăǃǦƸứǦǁầǃǦǁượǉǦǇƶǦǁƛ,ǦǁƐǂǦƼƔǦƸƚǦƸƽǊǓệǃǦǀƽƇǃƼǦǆǊƑǃǦǍǊǓếǃǦǃổƾ?",
    ["哟？看来集主是行家啊！您要愿意搭把手，这摊子上的小吃点心，随您吃到饱！"] = "Ồ?ǦƳƺǂǦǇƶǦǥậǅǦƸƽủǦǁƐǦǃƼườƾǦǉǇǄǃƼǦǃƼƽềǦǇồƾ!ǦƩếǊǦǃƼƐƾǦǈẵǃǦǁƛǃƼǦƼƾƕǅǦǂộǉǦǉƶǓ,ǦđồǦăǃǦǋặǉǦđƾểǂǦǉƁǂǦǉǇƙǃǦǈạǅǦǃƐǓǦǉƖǓǦǃƼƐƾǦăǃǦđếǃǦǃǄǦǉƽƔǦǉƽƇƾ!",
    ["听您这么一说，我还真有些心动。不如……试试！"] = "ƩƼƽƺǦǃƼƐƾǦǃƚƾǦǋậǓ,ǦǉƶǦǉƽựƸǦǈựǦƸƚǦƸƽƕǉǦđộǃƼǦǁƛǃƼǦǇồƾ.ǦƣƶǓǦǁƐ...ǦǉƽửǦǍƺǂ!",
    ["幸运的是，聪明兔子也有一群相信它的伙伴。于是它带着也想上月亮的兔子们，一起努力。"] = "ƨƶǓǦǂắǃǦǉƽƶǓ,ǦǉƽỏǦǉƽƇǃƼǦǂƾǃƽǦƸũǃƼǦƸƚǦǂộǉǦǃƽƚǂǦđồǃƼǦđộƾǦǉƾǃǦǉưởǃƼǦǂƔǃƽ.ǦǥƽếǦǁƐǦǃƚǦǤẫǃǦǉƽƺǄǦǃƽữǃƼǦƸƽƕǦǉƽỏǦƸũǃƼǦǂǊốǃǦǁƙǃǦǂặǉǦǉǇăǃƼ,ǦƸƖǃƼǦǃƽƶǊǦǃỗǦǁựƸ.",
    ["它们有的负责设计图纸，有的做工匠，有的种田研究萝卜种子……就这样过了一千年。"] = "ƞƽƕǃƼǦƸǄǃǦǉƽƔǦǅƽụǦǉǇƑƸƽǦǉƽƾếǉǦǀếǦƷảǃǦǋẽ,ǦƸǄǃǦǉƽƔǦǁƐǂǦǉƽợǦǉƽủǦƸƇǃƼ,ǦƸǄǃǦǉƽƔǦǁƐǂǦǇǊộǃƼǦǃƼƽƾƙǃǦƸứǊǦƽạǉǦƼƾốǃƼǦƸủǦƸảƾ...ǦƸứǦǉƽếǦǉǇƇƾǦǆǊƶǦǂộǉǦǃƼƽƔǃǦǃăǂ.",
    ["不错！正是小友你与冯师弟造的飞鸡啊！此等创意实在大胆！老朽、咳咳、兔子们也想看看，嘿嘿……小友可不能藏私啊。"] = "ƦƽƇǃƼǦǉồƾ!ǦƞƽƓǃƽǦǁƐǦǅƽƾǦǀƙǦǂƐǦǉƾểǊǦƽữǊǦǋƐǦƫƽƖǃƼǦǈưǦđệǦǉạǄǦǇƶǦđƚ!ǦƮƑǃƼǦǀƾếǃǦǃƐǓǦǉƽựƸǦǈựǦǉƑǄǦƷạǄ!ǦƧƃǄǦƽủ,ǦǀƽụǦǀƽụ,ǦđƑǂǦǉƽỏǦƸũǃƼǦǂǊốǃǦǍƺǂǦǉƽử,ǦƽƾǦƽƾ...ǦǉƾểǊǦƽữǊǦǀƽƇǃƼǦđượƸǦƼƾấǊǦǃƼƽềǦđƁǊǦǃƽƗ.",
    ["慢、慢点！别掉下去！"] = "ƞƽậǂ,ǦƸƽậǂǦƸƽƕǉ!ǦĐừǃƼǦđểǦǃƼƃǦǍǊốǃƼ!",
    ["飞鸡，飞咯！"] = "ƫƽƾǦǀƙ,ǦƷƶǓǦǉƽƇƾ!",
    ["再快些，再快些！"] = "ƩƽƶǃƽǦƽơǃǦƸƽƕǉǦǃữƶ,ǦǃƽƶǃƽǦƽơǃǦƸƽƕǉǦǃữƶ!",
    ["哇，我们飞上天啦——"] = "ƪƶ,ǦƸƽƕǃƼǦǉƶǦƷƶǓǦǁƙǃǦǉǇờƾǦǇồƾǦ——",
    ["胖叔叔？"] = "ǥƽƕƸǦǉƽƕƸǦƷƗǄǦư?",
    ["还没好吗？"] = "ƱẫǃǦƸƽưƶǦǍǄǃƼǦǈƶǄ?",
    ["快了快了！"] = "ƮắǅǦǍǄǃƼǦǇồƾ,ǦǈắǅǦǍǄǃƼǦǇồƾ!",
    ["大个子，你看！"] = "ĐạƾǦƸƑǦǉử,ǦǃƽƔǃǦǀƔƶ!",
    ["前面有捏面人的摊子，好耶！"] = "ƫƽƓƶǦǉǇướƸǦƸƚǦǈạǅǦǃặǃǦǉƛǦƽƺǦǀƔƶ,ǦƽƶǓǦǆǊƑ!",
    ["慢些跑，唉，老骨头追不上咯……"] = "ƞƽạǓǦƸƽậǂǦǉƽƇƾ,ǦƑƾǦƸƽƐ,ǦƸƑƾǦǉƽƁǃǦƼƾƐǦǃƐǓǦǉƽƺǄǦǀƽƇǃƼǦǀịǅǦǇồƾ...",
    ["全要！红的赢了就是红红火火，黄的赢了就是金银万贯，这就叫双押！"] = "ƧấǓǦƽếǉ!ǦĐộƾǦđỏǦǉƽắǃƼǦǁƐǦƽồǃƼǦƽồǃƼǦƽỏƶǦƽỏƶ,ǦđộƾǦǋƐǃƼǦǉƽắǃƼǦǁƐǦǉƾềǃǦƷạƸǦǂǊƇǃǦǋƐǃ,ǦƸƑƾǦǃƐǓǦƼọƾǦǁƐǦǁưỡǃƼǦǉǄƐǃǦǀỳǦǂỹ!",
    ["嘘！近日宫里进贼……这事儿没这么简单！"] = "ƮǊỵǉ!ǦƢầǃǦđƁǓǦǉǇǄǃƼǦƸǊǃƼǦƸƚǦǉǇộǂ...ǦƸƽǊǓệǃǦǃƐǓǦǀƽƇǃƼǦđơǃǦƼƾảǃǦǉƽếǦđƁǊ!",
    ["李卫宋"] = "ƧƈǦƱệǦǥốǃƼ",
    ["寻常贼人哪能进宫，这背后……水深得很！"] = "ǥặƸǦǃƽƁǃǦǉầǂǦǉƽườǃƼǦǈƶǄǦǋƐǄǦđượƸǦƽǄƐǃƼǦƸǊǃƼ,ǦƸƽǊǓệǃǦǃƐǓǦǅƽƓƶǦǈƶǊ...ǦǉƽƁǂǦǈƁǊǦǁắǂ!",
    ["确实！依我看，南唐人一肚子坏水，肯定是他们从中作梗！"] = "ƬǊảǦǉƽựƸ!ǦǥƽƺǄǦǉƶǦǉƽấǓ,ǦǃƼườƾǦƩƶǂǦĐườǃƼǦđầǓǦƷụǃƼǦƈǦǍấǊ,ǦƸƽắƸǦƸƽắǃǦǁƐǦƷọǃǦƸƽƕǃƼǦƼƾởǦǉǇƛ!",
    ["张恨堂"] = "ǥǇươǃƼǦƣậǃǦĐườǃƼ",
    ["你懂什么！南唐那么远，哪管得了皇宫，定 is 契丹狗贼干的！"] = "ƩƼươƾǦǉƽƔǦƽƾểǊǦƸƑƾǦƼƔ!ǦƩƶǂǦĐườǃƼǦǍƶǦǍƇƾǦǃƽưǦǉƽế,ǦǈƶǄǦǆǊảǃǦǉớƾǦđượƸǦƽǄƐǃƼǦƸǊǃƼ,ǦǃƽấǉǦđịǃƽǦǁƐǦǁũǦƸẩǊǦǉặƸǦƦƽƾếǉǦĐƶǃǦǁƐǂ!",
    ["南唐！南唐！南唐！"] = "ƩƶǂǦĐườǃƼ!ǦƩƶǂǦĐườǃƼ!ǦƩƶǂǦĐườǃƼ!",
    ["李卫宋：契丹！契丹！契丹！"] = "ƧƈǦƱệǦǥốǃƼ:ǦƦƽƾếǉǦĐƶǃ!ǦƦƽƾếǉǦĐƶǃ!ǦƦƽƾếǉǦĐƶǃ!",
    ["打起来！打起来！"] = "ĐƑǃƽǦǃƽƶǊǦđƾ!ǦĐƑǃƽǦǃƽƶǊǦđƾ!",
    ["你是谁？在这儿挑拨离间……好哇，我看，你就是南唐的间谍！"] = "ƩƼươƾǦǁƐǦƶƾ?ǦỞǦđƁǓǦǀƽƓƸƽǦƷƑƸǦǁǓǦƼƾƑǃ...ǦǥốǉǦǁắǂ,ǦǉƶǦǉƽấǓǦǃƼươƾǦƸƽƓǃƽǦǁƐǦƼƾƑǃǦđƾệǅǦƸủƶǦƩƶǂǦĐườǃƼ!",
    ["你懂什么！$T(5037)这么壮……定是契丹的！"] = "ƩƼươƾǦƽƾểǊǦƸƑƾǦƼƔ!Ǧ$T(5037)ǦƸườǃƼǦǉǇƑǃƼǦǉƽếǦǃƐǓ...ǦƸƽắƸǦƸƽắǃǦǁƐǦǃƼườƾǦƦƽƾếǉǦĐƶǃ!",
    ["抓间谍——！干死$T(5037)——！"] = "ƝắǉǦƼƾƑǃǦđƾệǅ——!ǦĐƑǃƽǦƸƽếǉǦ$T(5037)——!",
    ["张恨堂&李卫宋"] = "ǥǇươǃƼǦƣậǃǦĐườǃƼǦ&ǦƧƈǦƱệǦǥốǃƼ",
    ["诶，等等！二打一？"] = "Ê,ǦǀƽǄƶǃǦđƃ!ǦƣƶƾǦđƑǃƽǦǂộǉǦǈƶǄ?",
    ["你们不要再打啦！这里是皇宫！怎么可能有宫外势力渗透！"] = "ƞƑƸǦǃƼươƾǦđừǃƼǦđƑǃƽǦǃữƶ!ǦĐƁǓǦǁƐǦƽǄƐǃƼǦƸǊǃƼ!ǦƧƐǂǦǈƶǄǦƸƚǦǉƽểǦƸƚǦǉƽếǦǁựƸǦƷƙǃǦǃƼǄƐƾǦǍƁǂǦǃƽậǅ!",
    ["你是谁？替南唐说话……好哇，我看， you 就是南唐的间谍！"] = "ƩƼươƾǦǁƐǦƶƾ?ǦƩƚƾǦƼƾƕǅǦƸƽǄǦƩƶǂǦĐườǃƼ...ǦǥốǉǦǁắǂ,ǦǉƶǦǉƽấǓǦǃƼươƾǦƸƽƓǃƽǦǁƐǦƼƾƑǃǦđƾệǅǦƸủƶǦƩƶǂǦĐườǃƼ!",
    ["我断不可……止步于此……南唐阔土，等我伐之！"] = "ǥƶǦǆǊǓếǉǦǀƽƇǃƼǦǉƽể...ǦǤừǃƼǦƷướƸǦǉạƾǦđƁǓ...ǦĐấǉǦǇộǃƼǦƩƶǂǦĐườǃƼ,ǦƸƽờǦǉƶǦđếǃǦǅƽạǉ!",
    ["你懂、懂……什么！打契丹……才、才需要保留体力……"] = "ƩƼươƾǦƽƾể...ǦƽƾểǊ...ǦƸƑƾǦƼƔ!ǦĐƑǃƽǦƦƽƾếǉǦĐƶǃ...Ǧǂớ...ǦǂớƾǦƸầǃǦƼƾữǦǈứƸ...",
    ["二位大哥说得都对！眼下不如好好休整，来日再战真正的敌人！"] = "ƣƶƾǦǋịǦđạƾǦƸƶǦǃƚƾǦđềǊǦđƕǃƼ!ǦƞƽƾǦƷằǃƼǦƽƾệǃǦǉạƾǦƽƃǓǦǃƼƽỉǦǃƼơƾǦđƾềǊǦǤưỡǃƼ,ǦǃƼƐǓǦǈƶǊǦǂớƾǦƸƽƾếǃǦđấǊǦǋớƾǦǀẻǦǉƽƖǦǉƽựƸǦǈự!",
    ["……中！"] = "...ĐượƸ!",
    ["春恨生"] = "ƳǊƁǃǦƣậǃǦƮƾǃƽ",
    ["这……这后面是谁写的词，我记得出来前还不长这样啊……难道是、是被小八偷偷改了？"] = "ĐƁǓ...ǦđǄạǃǦǈƶǊǦǃƐǓǦǁƐǦƶƾǦǋƾếǉǦǉừǦǉƽếǦǃƐǓ,ǦǉƶǦǃƽớǦǁƕƸǦǉǇướƸǦǀƽƾǦǇƶǦǃƼǄƐƾǦđƁǊǦƸƚǦǉƽếǦǃƐǓ...ǦƞƽẳǃƼǦǁẽǦǁƐ...ǦǁƐǦƷịǦǥƾểǊǦƝƑǉǦǁƗǃǦǈửƶǦǇồƾ?",
    ["嘿，就是开封城里闹贼那回事嘛。人聚在这里，就是因为贼也聚在这里~"] = "ƣƔ,ǦƸƽƓǃƽǦǁƐǦƸƽǊǓệǃǦǃƑǄǦǁǄạǃǦǋƔǦǉǇộǂǦǉǇǄǃƼǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦđƚǦǂƐ.ǦƩƼườƾǦǉụǦǉậǅǦởǦđƁǓ,ǦǁƐǦƷởƾǦǋƔǦǉƙǃǦǉǇộǂǦƸũǃƼǦǉụǦǉậǅǦởǦđƁǓǦđƚ~",
    ["喵！喵！"] = "ƨƶǄ!ǦƨƶǄ!",
    ["喵！嗬——"] = "ƨƶǄ!ǦƣắƸǦ——",
    ["呵，你是何人？"] = "ƣừ,ǦǃƼươƾǦǁƐǦƽạǃƼǦǃƼườƾǦǃƐǄ?",
    ["武德司重地，闲人免进！"] = "ƱƅǦĐứƸǦǥǓǦǉǇọǃƼǦđịƶ,ǦǃƽƐǃǦǃƽƁǃǦǂƾễǃǦǉƾếǃ!",
    ["给你！嘿嘿，这就叫——路在脚下！"] = "ƞƽǄǦǃƼươƾǦǃƐǓ!ǦƣƔǦƽƔ,ǦđƁǓǦƼọƾǦǁƐǦ——ǦđườǃƼǦởǦǤướƾǦƸƽƁǃ!",
    ["……知道了。放了吧，正好用她。"] = "...ǦĐƃǦǇƅ.ǦǥƽảǦđƾ,ǦǋừƶǦǋặǃǦǤƖǃƼǦđếǃǦƸƇǦǉƶ.",
    ["帮苦主寻窃贼可是义举。此事关联重大，又牵连江湖。你不是最好打抱不平？"] = "ƢƾƕǅǦǀƽổǦƸƽủǦǉƔǂǦǉặƸǦǉửǦǋốǃǦǁƐǦǃƼƽĩƶǦƸử.ǦƞƽǊǓệǃǦǃƐǓǦƸƶǃǦƽệǦǉǇọǃƼǦđạƾ,ǦǁạƾǦǁƾƙǃǦǁụǓǦđếǃǦƼƾƶǃƼǦƽồ.ǦƩƼươƾǦƸƽẳǃƼǦǅƽảƾǦǉƽƓƸƽǦǃƽấǉǦǁƐǦƽƐǃƽǦƽƾệǅǦǉǇượǃƼǦǃƼƽĩƶ,ǦǇƶǦǉƶǓǦƷấǉǦƷƔǃƽǦǈƶǄ?",
    ["就是因为新来的，才不会被某些神神鬼鬼的东西唬住。"] = "ƞƽƓǃƽǦǋƔǦǁƐǦǃƼườƾǦǂớƾǦƼƺǁǦǃƙǃǦǂớƾǦǀƽƇǃƼǦƷịǦǂấǓǦǉƽứǦǉƽầǃǦǉƽầǃǦǆǊỷǦǆǊỷǦđƚǦǤọƶǦƸƽǄǦǀƽƾếǅǦǈợ.",
    ["要真是鬼……那这鬼能喊出这么大动静，也算是……中气十足，哈哈。"] = "ƩếǊǦǉƽậǉǦǈựǦǁƐǦǆǊỷ...ǦǉƽƔǦƸǄǃǦǆǊỷǦǃƐǓǦƸƚǦǉƽểǦƽƗǉǦǇƶǦǉƾếǃƼǦđộǃƼǦǁớǃǦǃƽưǦǋậǓ,ǦƸũǃƼǦƸǄƾǦǃƽưǦǁƐ...ǦǉǇǊǃƼǦǀƽƓǦǉƽậǅǦǉƕƸ,ǦƽƶǦƽƶ.",
    ["里面的快点！一早上就占着不出来，还让不让人活了！"] = "ƩƼườƾǦƷƙǃǦǉǇǄǃƼǦǃƽƶǃƽǦǁƙǃǦƸƽƕǉ!ǦƞảǦƷǊổƾǦǈƑǃƼǦƸứǦƸƽƾếǂǦƸƽỗǦǀƽƇǃƼǦǇƶ,ǦƸƛǃǦđểǦǃƼườƾǦǉƶǦǈốǃƼǦǃữƶǦǀƽƇǃƼ!",
    ["奇怪……我分明留手了，没叫她们输得太惨，怎么还是没人和我凑局？"] = "ƦỳǦǁạ...ǦǉƶǦǇƅǦǇƐǃƼǦđƃǦǃươǃƼǦǉƶǓ,ǦǀƽƇǃƼǦđểǦƷọǃǦƽọǦǉƽǊƶǦǆǊƑǦǉƽảǂ,ǦǈƶǄǦǋẫǃǦǀƽƇǃƼǦƸƚǦƶƾǦƸƽịǊǦǁậǅǦǈƛǃƼǦǋớƾǦǉƶǦǃƽỉ?",
    ["别催别催，还要一会儿！心急吃不了热豆腐，也拉不出热乎的……"] = "ĐừǃƼǦƼƾụƸǦđừǃƼǦƼƾụƸ,ǦƸƛǃǦǅƽảƾǦǂộǉǦǁƑǉǦǃữƶ!ǦǥƁǂǦƸấǅǦăǃǦǀƽƇǃƼǦđượƸǦđậǊǦǅƽụǦǃƚǃƼ,ǦƸũǃƼǦƸƽẳǃƼǦƽƐǃƽǦǈựǦǍǄǃƼǦđượƸǦđƁǊ...",
    ["姐姐，我照着你教我的次序干活，果然做得又快又好！怪道你每日瞧着清闲，又能多玩一会儿……"] = "ǥỷǦǉỷ,ǦđệǦǁƐǂǦǋƾệƸǦǉƽƺǄǦǉƽứǦǉựǦǉỷǦǤạǓ,ǦǆǊảǦǃƽƾƙǃǦǋừƶǦǃƽƶǃƽǦǋừƶǦǉốǉ!ǦǥǇƑƸƽǦǀƽƇǃƼǦđượƸǦǂỗƾǦǃƼƐǓǦǉǇƇǃƼǦǉỷǦǉƽǄǃƼǦǉƽả,ǦǁạƾǦƸƛǃǦƸƚǦǉƽểǦƸƽơƾǦǉƽƙǂǦǂộǉǦǁƑǉ...",
    ["少贫嘴！"] = "ƝớǉǦǤẻǄǦǂồǂǦđƾ!",
    ["我又没有占着茅坑不拉屎，骂我干啥。"] = "ĐệǦƸũǃƼǦđƁǊǦƸƚǦƸƽƾếǂǦƽốǦǍƓǦǂƐǦǀƽƇǃƼǦƽƐǃƽǦǈự,ǦǂắǃƼǦđệǦǁƐǂǦƼƔ.",
    ["嘘——学归学，不可显摆到人眼前去！这地方僻静，玩起来不易被发现……"] = "ƮǊỵǉǦ——ǦƣọƸǦǉƽƔǦƽọƸ,ǦǀƽƇǃƼǦđượƸǦǀƽǄƺǦǀƽǄƶǃƼǦǉǇướƸǦǂặǉǦǃƼườƾǦǀƽƑƸ!ǦƩơƾǦǃƐǓǦƽẻǄǦǁƑǃƽ,ǦƸƽơƾǦƷờƾǦǀƽƇǃƼǦǤễǦƷịǦǅƽƑǉǦƽƾệǃ...",
    ["何况啊，世界就是一个巨大的茅厕坑子，不是你坑我就是我坑你。被坑了，也很常见嘛！"] = "ƣǊốǃƼǦƽồǦƸƽƾ,ǦǉƽếǦƼƾƶǃǦǃƐǓǦƸƽƓǃƽǦǁƐǦǂộǉǦƸƑƾǦƽốǦǍƓǦǀƽổǃƼǦǁồ,ǦǀƽƇǃƼǦǅƽảƾǦǃƼươƾǦƽốǦǉƶǦǉƽƔǦǁƐǦǉƶǦƽốǦǃƼươƾ.ǦƝịǦƽốǦǇồƾ,ǦƸũǃƼǦǁƐǦƸƽǊǓệǃǦǉƽườǃƼǦǉƔǃƽǦǉƽƇƾ!",
    ["我晓得！姐姐，你能不能…… ye教教我算牌？"] = "ĐệǦƷƾếǉǦǇồƾ!ǦǥỷǦǉỷ,ǦǉỷǦƸƚǦǉƽể...ǦǤạǓǦđệǦƸƑƸƽǦǉƓǃƽǦƷƐƾǦǁǊƇǃǦǀƽƇǃƼ?",
    ["我还仙难救呢！莫名其妙，赶紧滚蛋。"] = "ǥƶǦƸƛǃǦǥƾƙǃǦƩƶǃǦƞứǊǦđƁǓǦǃƐǓ!ǦǥƽậǉǦǁƐǦǂậǅǦǂờǦǀỳǦǆǊặƸ,ǦǂƶǊǦƸƕǉǦǍƗǄǦƸƽǄǦǉƶ.",
    ["《这反应……不像有假。难道，我找错人了？还是说，此人城府极深，在跟我演戏？>"] = "<ƫƽảǃǦứǃƼǦǃƐǓ...ǦǀƽƇǃƼǦƼƾốǃƼǦǃƽưǦƼƾảǦǋờ.ǦƞƽẳǃƼǦǁẽ,ǦǉƶǦǉƔǂǦǃƽầǂǦǃƼườƾǦǇồƾ?ǦƣƶǓǦǁƐǦǃƚƾ,ǦǃƼườƾǦǃƐǓǦǉƽƐǃƽǦǅƽủǦƸựƸǦǈƁǊ,ǦđƶǃƼǦǤƾễǃǦǀịƸƽǦǋớƾǦǂƔǃƽ?>",
    ["入局之前，我得去后苑捉只好蛐蛐来！"] = "ǥǇướƸǦǀƽƾǦǋƐǄǦƸǊộƸ,ǦǉƶǦǅƽảƾǦđếǃǦƽậǊǦǊǓểǃǦƷắǉǦǂộǉǦƸǄǃǦǤếǦǉƽậǉǦǉốǉǦǂớƾǦđượƸ!",
    ["竟有此事？将军原是女儿身？！"] = "ƧạƾǦƸƚǦƸƽǊǓệǃǦǃƐǓǦǈƶǄ?ǦǥướǃƼǦǆǊƁǃǦƽƚƶǦǇƶǦǁƐǦǉƽƁǃǦǃữǦǃƽƾ?!",
    ["朝会要时，未着官服，未携笏者，不可入殿！"] = "ƧƕƸǦǉǇƾềǊǦƽộƾǦǆǊƶǃǦǉǇọǃƼ,ǦǃƼườƾǦǀƽƇǃƼǦǂặƸǦǆǊƶǃǦǅƽụƸ,ǦǀƽƇǃƼǦǂƶǃƼǦƽốǉ,ǦǀƽƇǃƼǦđượƸǦǋƐǄǦđƾệǃ!",
    ["京畿诸县禁伐后，已组织百姓种树，预估来岁可增树三千株。然陈留县有报，自组织种树起，耕牛伤树案件频发，迄今已有二十七起……"] = "ƮƶǊǦǀƽƾǦƸƑƸǦƽǊǓệǃǦǀƾǃƽǦǀỳǦƸấǂǦƸƽặǉǦǅƽƑ,ǦđƃǦǉổǦƸƽứƸǦƸƽǄǦƷƑƸƽǦǉƓǃƽǦǉǇồǃƼǦƸƁǓ,ǦǤựǦǀƾếǃǦǃăǂǦǉớƾǦƸƚǦǉƽểǦǉăǃƼǦǉƽƙǂǦƷƶǦǃƼƐǃǦƸƁǓ.ǦǥǊǓǦǃƽƾƙǃǦƽǊǓệǃǦǥǇầǃǦƧưǊǦƸƚǦƷƑǄǦƸƑǄ,ǦǉừǦǀƽƾǦǉổǦƸƽứƸǦǉǇồǃƼǦƸƁǓ,ǦƸƑƸǦǋụǦǋƾệƸǦǉǇƁǊǦƸƐǓǦǁƐǂǦƽỏǃƼǦƸƁǓǦǍảǓǦǇƶǦǁƾƙǃǦǉƾếǅ,ǦđếǃǦǃƶǓǦđƃǦƸƚǦƽƶƾǦǂươƾǦƷảǓǦǋụ...",
    ["边判官"] = "ƝƾƙǃǦƫƽƑǃǦƬǊƶǃ",
    ["可是县尉玩忽职守，规划有误？洛阳百姓已种树近万株，并未见牛损树之事。好好查一查。"] = "ƣƶǓǦǁƐǦǤǄǦƣǊǓệǃǦƕǓǦǁơǦǁƐǦƸƽứƸǦǉǇƑƸƽ,ǦǆǊǓǦƽǄạƸƽǦǈƶƾǦǈƚǉ?ǦƝƑƸƽǦǉƓǃƽǦƧạƸǦǝươǃƼǦđƃǦǉǇồǃƼǦƼầǃǦǋạǃǦƸƁǓ,ǦƸũǃƼǦǀƽƇǃƼǦǉƽấǓǦƸƽǊǓệǃǦǉǇƁǊǦǁƐǂǦƽỏǃƼǦƸƁǓ.ǦƣƃǓǦǉǇƶǦƸƽǄǦǀỹǦǋƐǄ.",
    ["今日来得最迟的大人会是哪一位呢？"] = "ƱịǦđạƾǦǃƽƁǃǦđếǃǦǂǊộǃǦǃƽấǉǦƽƇǂǦǃƶǓǦǈẽǦǁƐǦƶƾǦđƁǓ?",
    ["殿前司禁卫"] = "ĐƾệǃǦǥƾềǃǦǥǓǦƞấǂǦƱệ",
    ["呵呵，我还和谁一起采过湖边的花，是谁来着……是银绣吧？"] = "ƣƔǦƽƔ,ǦǂƔǃƽǦƸƛǃǦƸƖǃƼǦƶƾǦđƾǦƽƑƾǦƽǄƶǦƷƙǃǦƽồǦǃữƶǦǃƽỉ,ǦǁƐǦƶƾǦấǓǦǃƽỉ...ǦǁƐǦƩƼƁǃǦǥƕǦǅƽảƾǦǀƽƇǃƼ?",
    ["唉，娘子已经十天未曾展露笑颜了……"] = "ƣƶƾǏǏ,ǦǃươǃƼǦǉửǦđƃǦǂườƾǦǃƼƐǓǦǇồƾǦƸƽưƶǦǃởǦǃụǦƸườƾǦǃƐǄ...",
    ["唉，怎么办才好呢……"] = "ƣƶƾǏǏ,ǦǅƽảƾǦǁƐǂǦǈƶǄǦǂớƾǦǉốǉǦđƁǓ...",
    ["娘子郁郁寡欢，你们在这儿唉声叹气什么呢？"] = "ƩươǃƼǦǉửǦǊǦǊấǉǦǀƽƇǃƼǦǋǊƾ,ǦƸƑƸǦǃƼườƾǦởǦđƁǓǦǉƽởǦǃƼắǃǦǉƽƶǃǦǤƐƾǦƸƑƾǦƼƔǦǉƽế?",
    ["我们这些人都是在娘子手底下做事的，娘子不开心，我们怎么好过嘛！"] = "ƝọǃǦǉƶǦđềǊǦǁƐǦǃƼườƾǦǁƐǂǦǋƾệƸǦǤướƾǦǉƶǓǦǃươǃƼǦǉử,ǦǃươǃƼǦǉửǦǀƽƇǃƼǦǋǊƾ,ǦƷọǃǦǉƶǦǈƶǄǦǈốǃƼǦǓƙǃǦổǃǦđượƸǦƸƽứ!",
    ["姑姑让我们种些花样供娘子赏玩，可是我们也没什么好主意……"] = "ƞƇǦƸƇǦƷảǄǦƷọǃǦǉƶǦǉǇồǃƼǦǂấǓǦǂẫǊǦƽǄƶǦƸƽǄǦǃươǃƼǦǉửǦǉƽưởǃƼǦǃƼǄạǃ,ǦǃƽưǃƼǦƷọǃǦǉƶǦƸũǃƼǦƸƽẳǃƼǦƸƚǦƈǦǀƾếǃǦƼƔǦƽƶǓ...",
    ["越想越发愁，越发愁越想不出来，唉……"] = "ƞƐǃƼǦǃƼƽĩǦƸƐǃƼǦǈầǊ,ǦƸƐǃƼǦǈầǊǦƸƐǃƼǦǃƼƽĩǦǀƽƇǃƼǦǇƶ,ǦƽƶƾǏǏ...",
    ["你们娘子平素都喜欢做些什么事情？"] = "ƩươǃƼǦǉửǦǃƽƐǦƸƑƸǦǃƼườƾǦƷƔǃƽǦǉƽườǃƼǦǉƽƓƸƽǦǁƐǂǦǃƽữǃƼǦǋƾệƸǦƼƔ?",
    ["看书，写字……啊，还有就是在后苑赏玩！娘子偶尔会临水远眺，观赏观赏那些异兽奇珍。"] = "ĐọƸǦǈƑƸƽ,ǦǋƾếǉǦƸƽữ...ǦÀ,ǦƸƛǃǦƸƚǦǤạǄǦƸƽơƾǦởǦƽậǊǦǊǓểǃǦǃữƶ!ǦƩươǃƼǦǉửǦǉƽỉǃƽǦǉƽǄảǃƼǦǈẽǦđứǃƼǦƷƙǃǦƽồǦǃƽƔǃǦǍƶǦǍăǂ,ǦǃƼắǂǦǃƽƔǃǦǃƽữǃƼǦǤịǦǉƽƕǦǀỳǦǉǇƁǃǦđƚ.",
    ["嗯……如此说来……"] = "Ừǂ...ǦǃƚƾǦǋậǓǦǉƽƔ...",
    ["所谓“白毛浮绿水，红掌拨清波”，种一只胖胖的大鹅如何！"] = "ƞƑƾǦƼọƾǦǁƐǦ\"ƧƇǃƼǦǉǇắǃƼǦǃổƾǦǃướƸǦǍƶǃƽ,ǦƸƽƘǄǦƽồǃƼǦǀƽǊƶǦǈƚǃƼǦƷƾếƸ\",ǦǉǇồǃƼǦǂộǉǦƸǄǃǦǃƼỗǃƼǦǁớǃǦǂậǅǦǂạǅǦǉƽƔǦǈƶǄ!",
    ["正巧！我们这儿有些#ffc89c兰紫、姚黄、桃粉#E色花卉的花种可用！"] = "ǥƽậǉǦđƕǃƼǦǁƕƸ!ǦƞƽỗǦƸƽƕǃƼǦǉƇƾǦƸƚǦǈẵǃǦǂộǉǦƓǉǦƽạǉǦƼƾốǃƼǦƽǄƶǦǂƐǊǦ#ffc89cƧƶǃǦǥử,ǦǝƾƙǊǦƣǄƐǃƼ,ǦĐƐǄǦƫƽấǃ#EǦƸƚǦǉƽểǦǤƖǃƼǦđượƸ!",
    ["只不过……我二人自幼在开封城中长大，未曾亲见过这鹅长什么样……"] = "ƞƽỉǦƸƚǦđƾềǊ...ǦƽƶƾǦǃƼườƾǦƸƽƕǃƼǦǉƇƾǦǉừǦǃƽỏǦǁớǃǦǁƙǃǦǉǇǄǃƼǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼ,ǦƸƽưƶǦǉừǃƼǦǉậǃǦǂắǉǦǉƽấǓǦƸǄǃǦǃƼỗǃƼǦǉǇƇǃƼǦǉƽếǦǃƐǄ...",
    ["没事，这我熟！此事尽可以放心地交给我！"] = "ƦƽƇǃƼǦǈƶǄ,ǦǋƾệƸǦǃƐǓǦǉƶǦǇƐǃƽ!ǦƞứǦǓƙǃǦǉƁǂǦƼƾƶǄǦƸƽǄǦǉƶ!",
    ["哎哟！怎么在你手里？！快给我！"] = "ÁƾǦƸƽƐ!ǦƮƶǄǦǃƚǦǁạƾǦởǦǉǇǄǃƼǦǉƶǓǦǃƼươƾ?!ǦƨƶǊǦđưƶǦƸƽǄǦǉƶ!",
    ["哎，慢点儿。这上面白纸黑字写得精彩，我还没读够呢。"] = "ƦƔƶ,ǦǉƽǄǃƼǦǉƽảǦǉƽƇƾ.ǦǥǇƙǃǦǃƐǓǦƼƾấǓǦǉǇắǃƼǦǂựƸǦđƺǃǦǋƾếǉǦǁƑƸƽǦđặƸǦǈắƸǦǆǊƑ,ǦǉƶǦđọƸǦǋẫǃǦƸƽưƶǦđƃǦđƁǓ.",
    ["小大人，这东西是咱家的私物！你们武德司的手伸得再长，也不该管到我头上来吧？小心引火烧身！"] = "ǥƾểǊǦđạƾǦǃƽƁǃ,ǦǉƽứǦǃƐǓǦǁƐǦǋậǉǦǇƾƙǃƼǦƸủƶǦǉạǅǦƼƾƶ!ǦǥƶǓǦƸủƶǦƱƅǦĐứƸǦǥǓǦƸƑƸǦǃƼươƾǦƸƚǦǋươǃǦǤƐƾǦđếǃǦǂấǓ,ǦƸũǃƼǦǀƽƇǃƼǦǃƙǃǦǆǊảǃǦđếǃǦđầǊǦǉƶǦƸƽứ?ǦƞẩǃǦǉƽậǃǦǇướƸǦƽọƶǦǋƐǄǦǉƽƁǃ!",
    ["嗯？看来是不肯老实交代了，那不如把那边的侍卫一起喊来，看看这上面的贾大人，到底是哪位大人？"] = "ƣửǂ?ǦƳƺǂǦǇƶǦǁƐǦǀƽƇǃƼǦƸƽịǊǦǉƽƐǃƽǦǉƽậǉǦǀƽƶƾǦƷƑǄǦǇồƾ,ǦǋậǓǦƸƽƾǦƷằǃƼǦƼọƾǦđƑǂǦǉƽịǦǋệǦđằǃƼǦǀƾƶǦǁạƾǦđƁǓ,ǦǍƺǂǦǉƽửǦǋịǦƢƾảǦđạƾǦǃƽƁǃǦǉǇƙǃǦǃƐǓ,ǦǇốǉǦƸǊộƸǦǁƐǦǋịǦđạƾǦǃƽƁǃǦǃƐǄ?",
    ["大家都在这宫里混口饭吃，何必把路走绝了？"] = "ƨọƾǦǃƼườƾǦđềǊǦởǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦǀƾếǂǦǂƾếǃƼǦƸơǂǦăǃ,ǦƽƐǦǉấǉǦǅƽảƾǦǤồǃǦǃƽƶǊǦǋƐǄǦđườǃƼǦƸƖǃƼ?",
    ["这些田契，你拿一半去！这可是汝州的上好田产，几辈子都吃不完的富贵！只要把那封信还给咱家……"] = "ƨấǓǦǉờǦđƾềǃǦǀƽếǦǃƐǓ,ǦǃƼươƾǦƸầǂǦǁấǓǦǂộǉǦǃửƶǦđƾ!ǦĐƁǓǦǁƐǦđƾềǃǦǈảǃǦǉƽượǃƼǦƽạǃƼǦởǦƩƽữǦƞƽƁǊ,ǦǅƽƕǦǆǊƈǦǂấǓǦđờƾǦăǃǦǀƽƇǃƼǦƽếǉ!ǦƞƽỉǦƸầǃǦǉǇảǦǁạƾǦƷứƸǦǉƽưǦđƚǦƸƽǄǦǉạǅǦƼƾƶ...",
    ["一半啊……听着是不错。"] = "ƨộǉǦǃửƶǦǈƶǄ...ǦǃƼƽƺǦƸũǃƼǦƷƖƾǦǉƶƾǦđấǓ.",
    ["是吧！识时务者为俊杰……"] = "ƫƽảƾǦǀƽƇǃƼ!ǦƦẻǦǉƽứƸǦǉƽờƾǦǂớƾǦǁƐǦǉǊấǃǦǀƾệǉ...",
    ["可惜啊，我这人胆子小。怕 those 被你们害了的百姓晚上来索命！"] = "ǥƾếƸǦǉƽƶǓ,ǦǉƶǦđƁǓǦǃƽƑǉǦƼƶǃǦǁắǂ.ǦƞƽỉǦǈợǦđƑǂǦƷƑƸƽǦǉƓǃƽǦƷịǦƸƑƸǦǃƼườƾǦƽạƾǦƸƽếǉǦđƙǂǦđƙǂǦǋềǦđƛƾǦǂạǃƼ!",
    ["你！你别敬酒不吃吃罚酒！你以为咱家在宫里是白干的？"] = "ƩƼươƾ!ǦƩƼươƾǦđừǃƼǦƸƚǦǇượǊǦǂờƾǦǀƽƇǃƼǦǊốǃƼǦǂǊốǃǦǊốǃƼǦǇượǊǦǅƽạǉ!ǦƩƼươƾǦǉưởǃƼǦǉạǅǦƼƾƶǦởǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦǁƐǦǀẻǦăǃǦǀƽƇǃƼǦǃƼồƾǦǇồƾǦƸƽắƸ?",
    ["省省吧。留着这些话，去武德司的大牢里跟刑官慢慢聊。"] = "ǝẹǅǦđƾ.ǦƢƾữǦǁấǓǦǂấǓǦǁờƾǦǃƐǓ,ǦǋƐǄǦđạƾǦǁƶǄǦƱƅǦĐứƸǦǥǓǦǂƐǦǉƽǄǃƼǦǉƽảǦǉǇƛǦƸƽǊǓệǃǦǋớƾǦƽƔǃƽǦǆǊƶǃ.",
    ["听说他们最近新研制了几套刑具，正愁没人试呢。"] = "ƩƼƽƺǦǃƚƾǦǤạǄǦǃƐǓǦƽọǦǂớƾǦǃƼƽƾƙǃǦƸứǊǦǇƶǦǂấǓǦƷộǦƽƔǃƽǦƸụ,ǦđƶǃƼǦǇầǊǦǀƽƇǃƼǦƸƚǦǃƼườƾǦǉƽửǦđƁǓ.",
    ["不……冤枉啊！大人！冤枉啊！！"] = "ƦƽƇǃƼ...ǦǄƶǃǦǊổǃƼǦǆǊƑ!ǦĐạƾǦǃƽƁǃ!ǦƪƶǃǦǊổǃƼǦǆǊƑ!!",
    ["多谢同僚检举，此处我已勘察完毕，先告辞了。"] = "ĐƶǦǉạǦđồǃƼǦǁƾƙǊǦđƃǦǉốǦƼƾƑƸ,ǦǃơƾǦǃƐǓǦǉƶǦđƃǦǀƽƑǂǦǍƗǉǦǍǄǃƼ,ǦǍƾǃǦƸƑǄǦǉừǦǉǇướƸ.",
    ["谈谈谈谈个没完，今日谈成长，明日谈心得，后日谈感悟，大后日又要谈总结，真是没完没了了！"] = "ƝƐǃǦƷƐǃǦƷƐǃ,ǦƷƐǃǦǂƃƾǦǀƽƇǃƼǦǍǄǃƼ,ǦƽƇǂǦǃƶǓǦƷƐǃǦǋềǦǉǇưởǃƼǦǉƽƐǃƽ,ǦǃƼƐǓǦǂƶƾǦƷƐǃǦǋềǦǉƁǂǦđắƸ,ǦǃƼƐǓǦǀƾƶǦƷƐǃǦǋềǦƸảǂǦǃƼộ,ǦǃƼƐǓǦǀƔƶǦǁạƾǦƷƐǃǦǋềǦǉổǃƼǦǀếǉ,ǦđƕǃƼǦǁƐǦǅƽƾềǃǦǅƽứƸǦǋƇǦǉậǃ!",
    ["晨起要报告，睡前要反思，忙得我都该没上工的时间了，还是负责带你的姑姑好，没这么多琐事。"] = "ƮƑǃƼǦǤậǓǦǅƽảƾǦƷƑǄǦƸƑǄ,ǦǉǇướƸǦǀƽƾǦǃƼủǦǅƽảƾǦǅƽảǃǦǅƽảǃǦǉỉǃƽ,ǦƷậǃǦđếǃǦǂứƸǦǉƶǦƸƽẳǃƼǦƸƛǃǦǉƽờƾǦƼƾƶǃǦǁƐǂǦǋƾệƸǦǃữƶ,ǦǋẫǃǦǁƐǦƸƇǦƸƇǦǅƽụǦǉǇƑƸƽǦǤẫǃǦǤắǉǦǃƼươƾǦǉốǉǦƽơǃ,ǦǀƽƇǃƼǦƸƚǦǃƽƾềǊǦƸƽǊǓệǃǦǋụǃǦǋặǉǦǉƽếǦǃƐǓ.",
    ["她面上虽然看不出来，但私底下可一点不手软，裁没了好几个手底下的小宫女呢。"] = "ƝƐǦǉƶǦƷềǦǃƼǄƐƾǦǉǊǓǦǀƽƇǃƼǦǁộǦǇƶ,ǦǃƽưǃƼǦǈƶǊǦǁưǃƼǦǉƽƔǦƸƽẳǃƼǦǃươǃƼǦǉƶǓǦƸƽƕǉǦǃƐǄǦđƁǊ,ǦđƃǦǈƶǦǉƽảƾǦǀƽƇǃƼǦƓǉǦƸǊǃƼǦǃữǦǃƽỏǦǤướƾǦǉƶǓǦǇồƾǦđấǓ.",
    ["唉，这差事可是我千辛万苦谋来的，家里人都指着我在开封混出头争口气呢……"] = "ƣƶƾǏǏ,ǦƸƇǃƼǦǋƾệƸǦǃƐǓǦǉƶǦǅƽảƾǦǋấǉǦǋảǦǁắǂǦǂớƾǦǀƾếǂǦđượƸ,ǦǃƼườƾǦǃƽƐǦđềǊǦǉǇƇǃƼǦƸậǓǦǋƐǄǦǉƶǦởǦƦƽƶƾǦƫƽǄǃƼǦǁƐǂǦǃƙǃǦƸƽǊǓệǃǦđểǦǃởǦǂƐǓǦǃởǦǂặǉǦđƁǓ...",
    ["别谈了行吗，要谈几次啊怎么没完没了了……"] = "ĐừǃƼǦƷƐǃǦǃữƶǦđượƸǦǀƽƇǃƼ,ǦđịǃƽǦƷƐǃǦƷƶǄǦǃƽƾƙǊǦǁầǃǦǃữƶǦđƁǓ,ǦǈƶǄǦƸứǦǁảƾǦǃƽảƾǦǂƃƾǦǉƽế...",
    ["噫吁嚱！如此良辰美景，真是令小女子仰天长笑——"] = "ƴǦƽưǦƽƾ!ǦƧươǃƼǦǉƽầǃǦǂỹǦƸảǃƽǦǉƽếǦǃƐǓ,ǦǉƽậǉǦǀƽƾếǃǦǉƾểǊǦǃữǦǉửǦǂǊốǃǦǃƼửƶǦǂặǉǦǁƙǃǦǉǇờƾǦƸườƾǦǤƐƾǦ——",
    ["何意味？"] = "ƞƚǦƈǦƼƔ?",
    ["哦，她这两天不知道哪看了些古旧的话本，现在说话就这样了。"] = "Ồ,ǦƸƇǦấǓǦƽƶƾǦǃƼƐǓǦǃƶǓǦƸƽẳǃƼǦƷƾếǉǦđọƸǦǂấǓǦǆǊǓểǃǦǉƽǄạƾǦƷảǃǦƸũǦǀỹǦởǦđƁǊ,ǦƼƾờǦǃƚƾǦǃăǃƼǦƸứǦǃƽưǦǋậǓǦđấǓ.",
    ["没事，她看话本比较沉浸，上个月是魔尊现世，上上个月是龙王归来，过两天再看本说人话的就好了。"] = "ƦƽƇǃƼǦǈƶǄǦđƁǊ,ǦƸƇǦấǓǦđọƸǦǉƽǄạƾǦƷảǃǦƽơƾǦǃƽậǅǦǉƁǂǦǆǊƑǦǉƽƇƾ,ǦǉƽƑǃƼǦǉǇướƸǦǁƐǦƨƶǦǥƇǃǦƼƾƑǃƼǦǉƽế,ǦǉƽƑǃƼǦǉǇướƸǦǃữƶǦǁƐǦƧǄǃƼǦƱươǃƼǦǆǊǓǦǁƶƾ,ǦǆǊƶǦǋƐƾǦǃƼƐǓǦǃữƶǦđọƸǦǆǊǓểǃǦǃƐǄǦǃƚƾǦǉƾếǃƼǦǃƼườƾǦǁƐǦổǃǦǃƼƶǓǦấǓǦǂƐ.",
    ["快哉快哉，见姑娘出口成章，文采斐然，看来也是博学广识之人呀！"] = "ƦƽǄƑƾǦǉƽƶǓǦǀƽǄƑƾǦǉƽƶǓ,ǦǉƽấǓǦƸƇǦǃươǃƼǦǍǊấǉǦǀƽẩǊǦǉƽƐǃƽǦƸƽươǃƼ,ǦǋăǃǦǉƐƾǦǇựƸǦǇỡ,ǦǍƺǂǦǇƶǦƸũǃƼǦǁƐǦǃƼườƾǦƽọƸǦǇộǃƼǦǉƐƾǦƸƶǄǦǃƽƶ!",
    ["小女子不才，幸得军士青睐，日后若是有缘，不如一起在湖上泛舟悠悠！"] = "ǥƾểǊǦǃữǦǉửǦƷấǉǦǉƐƾ,ǦǂƶǓǦǂắǃǦđượƸǦǆǊƁǃǦǈĩǦưǊǦƑƾ,ǦǈƶǊǦǃƐǓǦǃếǊǦƸƚǦǤǊǓƙǃ,ǦƸƽƾǦƷằǃƼǦƸƖǃƼǦǃƽƶǊǦƸƽƘǄǦǉƽǊǓềǃǦǤǊǦǃƼǄạǃǦǉǇƙǃǦƽồ!",
    ["哎呀，咱们宫里这么多盘子，少了这一个不碍事的。"] = "ÁƾǦƸƽƐ,ǦǉǇǄǃƼǦƸǊǃƼǦǂƔǃƽǦǃƽƾềǊǦđĩƶǦǉƽếǦǃƐǓ,ǦǉƽƾếǊǦǂộǉǦƸƑƾǦƸũǃƼǦƸƽẳǃƼǦǈƶǄǦđƁǊ.",
    ["你看，我穿得可多了，我不冷！"] = "ƩƼươƾǦǍƺǂ,ǦǉƶǦǂặƸǦǃƽƾềǊǦǁắǂ,ǦǀƽƇǃƼǦǁạǃƽǦđƁǊ!",
    ["当然，我压在被褥底下了，保准瞧不出来。"] = "ǝĩǦǃƽƾƙǃǦǇồƾ,ǦǉƶǦƼƾấǊǦǤướƾǦǃệǂǦǇồƾ,ǦƷảǄǦđảǂǦǀƽƇǃƼǦǃƽƔǃǦǇƶǦđƁǊ.",
    ["树下和石头缝里，都得仔细扫才行！上回就因为这个挨骂了……"] = "ǝướƾǦƼốƸǦƸƁǓǦǋƐǦǀẽǦđƑǦđềǊǦǅƽảƾǦǆǊƗǉǦǉƽậǉǦǀỹǦǂớƾǦđượƸ!ǦƧầǃǦǉǇướƸǦƸũǃƼǦǋƔǦƸƽǊǓệǃǦǃƐǓǦǂƐǦƷịǦǂắǃƼǦđấǓ...",
    ["胳膊好酸……腿也沉，呼哧……这起码得两个人一起端吧？"] = "ƨỏƾǦǉƶǓǦǆǊƑ...ǦƸƽƁǃǦƸũǃƼǦǃặǃƼǦǃữƶ,ǦǅƽƖ...ǦƸƑƾǦǃƐǓǦƓǉǦǃƽấǉǦǅƽảƾǦƽƶƾǦǃƼườƾǦƸƖǃƼǦƷƙǦƸƽứ?",
    ["紫的，粉的，还有……娘子说的四色花是哪四色来着……"] = "ƨƐǊǦǉƓǂ,ǦǂƐǊǦƽồǃƼ,ǦƸƛǃǦƸƚ...ǦƷốǃǦǂƐǊǦƽǄƶǦǃươǃƼǦǉửǦǃƚƾǦǁƐǦƷốǃǦǂƐǊǦǃƐǄǦấǓǦǃƽỉ...",
    ["一花四色？宫里还有这种奇花名卉？"] = "ƨộǉǦƽǄƶǦƷốǃǦǂƐǊ?ǦǥǇǄǃƼǦƸǊǃƼǦƸƛǃǦƸƚǦǁǄạƾǦǤƶǃƽǦƽǄƶǦǀỳǦǁạǦǃƐǓǦǈƶǄ?",
    ["没有没有，只是娘子想在这花圃里种#ffc89c兰紫、梅红、姚黄、桃粉#E四种颜色的花卉。"] = "ƦƽƇǃƼǦƸƚǦǀƽƇǃƼǦƸƚ,ǦƸƽỉǦǁƐǦǃươǃƼǦǉửǦǂǊốǃǦǉǇồǃƼǦƷốǃǦǁǄạƾǦƽǄƶǦǂƐǊǦ#ffc89cƧƶǃǦǥử,ǦƨƶƾǦƣồǃƼ,ǦǝƾƙǊǦƣǄƐǃƼ,ǦĐƐǄǦƫƽấǃ#EǦǉǇǄǃƼǦǋườǃǦƽǄƶǦǃƐǓǦǉƽƇƾ.",
    ["按着这纹样种，旁人远远看着就好像是一朵四色之花。"] = "ǥǇồǃƼǦǉƽƺǄǦǂẫǊǦǃƐǓ,ǦǃƼườƾǦǃƼǄƐƾǦǃƽƔǃǦǉừǦǍƶǦƸứǦǃƼỡǦǃƽưǦǁƐǦǂộǉǦđƚƶǦƽǄƶǦƷốǃǦǂƐǊǦǋậǓ.",
    ["想法是好的，只是苦了我们下面这些干活的宫女，这七七八八的各种花，咋种得过来嘛……"] = "ÝǦǉưởǃƼǦǉƽƔǦƽƶǓǦđấǓ,ǦƸƽỉǦǀƽổǦǉƽƁǃǦđƑǂǦƸǊǃƼǦǃữǦǁƐǂǦǋƾệƸǦǃƽưǦƷọǃǦǉƶǦǉƽƇƾ,ǦđủǦǉƽứǦǁǄạƾǦƽǄƶǦǉƽếǦǃƐǓ,ǦǈƶǄǦǂƐǦǉǇồǃƼǦƸƽǄǦǍǊểǦƸƽứ...",
    ["还非要#ffc89c从我站的这地块开始种紫色#E，按次序种……这些规矩快把我的头都绕晕了！"] = "ƞƛǃǦǃƽấǉǦǆǊǓếǉǦƷắǉǦ#ffc89cƷắǉǦđầǊǦǉǇồǃƼǦǂƐǊǦǉƓǂǦǉừǦǂảǃƽǦđấǉǦǉƶǦđƶǃƼǦđứǃƼ#E,ǦǇồƾǦǉƽƺǄǦǉƽứǦǉựǦǂƐǦǉǇồǃƼ...ǦǂấǓǦƸƑƾǦǆǊǓǦǉắƸǦǃƐǓǦǁƐǂǦǉƶǦƸƽƚǃƼǦƽếǉǦƸảǦǂặǉǦǇồƾ!",
    ["诶……不过，军士，看你这身量，这气度，一看就是习武的高手！"] = "Ê...ǦǃƽưǃƼǦǂƐǦǆǊƁǃǦǈĩǦđạƾǦƽǊǓǃƽ,ǦǃƽƔǃǦǋƚƸǦǤƑǃƼǦǃƐǓ,ǦǀƽƓǦƸƽấǉǦǃƐǓ,ǦǃƽƔǃǦǂộǉǦƸƑƾǦǁƐǦƷƾếǉǦǃƼƶǓǦƸƶǄǦǉƽủǦǋƅǦǁƁǂǦǇồƾ!",
    ["对呀对呀，看这轮廓，看这线条！每天不练 ta 四五个时辰哪练得出来呀！"] = "ĐƕǃƼǦǉƽếǦđƕǃƼǦǉƽế,ǦǃƽƔǃǦƸơǦƷắǅǦǃƐǓ,ǦǃƽƔǃǦđườǃƼǦǃƗǉǦǃƐǓ!ǦƨỗƾǦǃƼƐǓǦǀƽƇǃƼǦǁǊǓệǃǦǉậǅǦƷốǃǦǃăǂǦƸƶǃƽǦƼƾờǦǉƽƔǦǈƶǄǦǂƐǦƸƚǦđượƸǦƸƽứ!",
    ["要是奴婢有你这般的好体魄，真是做梦都要笑醒了！"] = "ƩếǊǦǃƇǦǉỳǦǂƐǦƸƚǦǉƽƁǃǦƽƔǃƽǦǉǇƑǃƼǦǀƾệǃǦǃƽưǦƽǊǓǃƽ,ǦƸƽắƸǦǃằǂǦǂơǦƸũǃƼǦƸườƾǦǉỉǃƽǦǂấǉ!",
    ["哎呀，哪有你们说得这么夸张……"] = "ÁƾǦƸƽƐ,ǦǁƐǂǦƼƔǦǂƐǦǀƽǄƶǦǉǇươǃƼǦǃƽưǦƸƑƸǦǂǊộƾǦǃƚƾǦƸƽứ...",
    ["我们娘子说了，过去宫女们玩闹时，在这片花圃埋了些前朝的旧物什，相约未来一同重返故地，再次启封。只是现在人走茶凉，当年的人都不在了。"] = "ƩươǃƼǦǉửǦǃƽƐǦǉƶǦǃƚƾ,ǦǃƼƐǓǦǉǇướƸǦƸƑƸǦƸǊǃƼǦǃữǦǁƕƸǦǃƇǦđƖƶǦđƃǦƸƽƇǃǦǂộǉǦƓǉǦǀỷǦǋậǉǦǉƽờƾǦǉƾềǃǦǉǇƾềǊǦởǦǋườǃǦƽǄƶǦǃƐǓ,ǦƽẹǃǦǃƼƐǓǦǈƶǊǦƸƖǃƼǦǆǊƶǓǦǁạƾǦƸƽốǃǦƸũ,ǦǂởǦǇƶǦǁầǃǦǃữƶ.ǦƞƽỉǦǁƐǦƼƾờǦđƁǓǦǋậǉǦđổƾǦǈƶǄǦǤờƾ,ǦǃƼườƾǦǃăǂǦǍưƶǦƸƽẳǃƼǦƸƛǃǦƶƾǦǃữƶ.",
    ["要是奴婢们运气好，能翻出 those 前朝旧物，都可以自己带走，做个添头呢！"] = "ƩếǊǦǃƇǦǉỳǦƷọǃǦǉƶǦǂƶǓǦǂắǃǦđƐǄǦđượƸǦǃƽữǃƼǦǂƚǃǦđồǦƸũǦǉƽờƾǦǉƾềǃǦǉǇƾềǊǦđƚ,ǦđềǊǦƸƚǦǉƽểǦǉựǦǂƔǃƽǦǂƶǃƼǦđƾ,ǦƸǄƾǦǃƽưǦǂƚǃǦƽờƾǦđấǓ!",
    ["$T(19001)，这片花圃我们实在是浇不过来了……你看……"] = "$T(19001),ǦǋườǃǦƽǄƶǦǃƐǓǦƷọǃǦǉƶǦǉƽựƸǦǈựǦǉướƾǦǀƽƇǃƼǦǍǊểǦǇồƾ...ǦǃƼươƾǦǍƺǂ...",
    ["若是军士您愿意伸出援手，帮帮小忙……像您这么好的运气，一定能找到 those 前朝旧物!"] = "ƩếǊǦǆǊƁǃǦǈĩǦđạƾǦƽǊǓǃƽǦǈẵǃǦǁƛǃƼǦǇƶǦǉƶǓǦƼƾƕǅǦđỡǦƸƽƕǉǦǋƾệƸǦǃƽỏ...ǦǋớƾǦǋậǃǦǂƶǓǦǉốǉǦǃƽưǦƽǊǓǃƽ,ǦǃƽấǉǦđịǃƽǦǈẽǦǉƔǂǦǉƽấǓǦǃƽữǃƼǦǂƚǃǦđồǦƸũǦǉƽờƾǦǉƾềǃǦǉǇƾềǊǦđƚǦǉƽƇƾ!",
    ["多谢军士！奴婢一眼就看出来了，军士是这全皇宫里最厉害、最热心肠的人！！"] = "ĐƶǦǉạǦǆǊƁǃǦǈĩ!ǦƩƇǦǉỳǦǃƽƔǃǦǂộǉǦƸƑƾǦǁƐǦƷƾếǉǦǃƼƶǓ,ǦǆǊƁǃǦǈĩǦǁƐǦǃƼườƾǦǁợƾǦƽạƾǦǃƽấǉ,ǦǃƽƾệǉǦǉƔǃƽǦǃƽấǉǦǉǇǄǃƼǦƸảǦƽǄƐǃƼǦƸǊǃƼǦǃƐǓǦǁǊƇǃ!!",
    ["王兄，依浑天仪测算，勾陈六星的星度与书中旧图偏差半度有余，不知是何处疏漏？"] = "ƱươǃƼǦƽǊǓǃƽ,ǦǉƽƺǄǦƣỗǃǦǥƽƾƙǃǦƩƼƽƾǦđǄǦđạƸ,ǦǉƾǃƽǦđộǦƸủƶǦǈƑǊǦǈƶǄǦƞƁǊǦǥǇầǃǦǁệƸƽǦǈǄǦǋớƾǦƷảǃǦđồǦƸũǦǉǇǄǃƼǦǈƑƸƽǦƽơǃǦǃửƶǦđộ,ǦǀƽƇǃƼǦƷƾếǉǦǁƐǦǈƶƾǦǈƚǉǦởǦƸƽỗǦǃƐǄ?",
    ["此非你测算之过，实乃旧图沿用前代数据，未顾及岁差之变。"] = "ĐƁǓǦǀƽƇǃƼǦǅƽảƾǦǁỗƾǦǤǄǦđệǦđǄǦđạƸ,ǦǂƐǦǉƽựƸǦƸƽấǉǦǁƐǦƷảǃǦđồǦƸũǦǋẫǃǦǤƖǃƼǦǈốǦǁƾệǊǦǉừǦǉƾềǃǦđạƾ,ǦƸƽưƶǦǉƓǃƽǦđếǃǦǈựǦǉƽƶǓǦđổƾǦƸủƶǦǉǊếǦǈƶƾ.",
    ["岁差约七十一年余偏移一度，前代星图距今已逾百年，偏差半度实属正常。"] = "ǥǊếǦǈƶƾǦƸứǦǀƽǄảǃƼǦƽơǃǦƷảǓǦǂươƾǦǂốǉǦǃăǂǦǁạƾǦǁệƸƽǦǂộǉǦđộ,ǦƷảǃǦđồǦǈƶǄǦđờƾǦǉǇướƸǦƸƑƸƽǦǃƶǓǦđƃǦƽơǃǦǉǇăǂǦǃăǂ,ǦǁệƸƽǦǃửƶǦđộǦƸũǃƼǦǁƐǦƸƽǊǓệǃǦƷƔǃƽǦǉƽườǃƼ.",
    ["我等编纂《应天历>时，正欲修正此弊。"] = "ƝọǃǦǉƶǦǀƽƾǦƷƾƙǃǦǈǄạǃǦ<ỨǃƼǦǥƽƾƙǃǦƧịƸƽ>,ǦƸƽƓǃƽǦǁƐǦǂǊốǃǦǈửƶǦđổƾǦƸƑƾǦǈƶƾǦǁầǂǦǃƐǓ.",
    ["原来如此！晚辈此前仅凭旧星经进行推演，未曾想到实测校准，有所疏漏。"] = "ƣƚƶǦǇƶǦǁƐǦǋậǓ!ǦƱƃǃǦƷốƾǦǉǇướƸǦđƁǓǦƸƽỉǦǤựƶǦǋƐǄǦǉƾǃƽǦǀƾǃƽǦƸũǦđểǦǈǊǓǦǁǊậǃ,ǦǀƽƇǃƼǦǃƼờǦđếǃǦǋƾệƸǦđǄǦđạƸǦǉƽựƸǦǉếǦđểǦƽƾệǊǦƸƽǊẩǃ,ǦǉƽậǉǦǁƐǦƸƚǦƸƽỗǦǉƽƾếǊǦǈƚǉ.",
    ["墨山道弟子擅以观星稽古，孤云弟子观星，则素来重实测而轻旧说，你可将两者心法相融，将这星图再校准一番。"] = "ĐệǦǉửǦƨặƸǦƮơǃǦĐạǄǦƼƾỏƾǦǆǊƶǃǦǉƾǃƽǦǀƙǦƸổ,ǦđệǦǉửǦƞƇǦƱƁǃǦǆǊƶǃǦǉƾǃƽǦǉƽƔǦǍưƶǦǃƶǓǦǉǇọǃƼǦǉƽựƸǦǉǇắƸǦǂƐǦǀƽƾǃƽǦƸựǊǦǉƽǊǓếǉ,ǦđệǦƸƚǦǉƽểǦǤǊǃƼǦƽợǅǦǉƁǂǦǅƽƑǅǦƸủƶǦƸảǦƽƶƾ,ǦƽƾệǊǦƸƽǊẩǃǦǁạƾǦƷảǃǦđồǦǈƶǄǦǃƐǓǦǂộǉǦǁầǃǦǃữƶ.",
    ["王兄，晚辈近日研习《甘石星经>，有一惑不解……"] = "ƱươǃƼǦƽǊǓǃƽ,ǦǋƃǃǦƷốƾǦƼầǃǦđƁǓǦǃƼƽƾƙǃǦƸứǊǦ<ƞƶǂǦǥƽạƸƽǦǥƾǃƽǦƦƾǃƽ>,ǦƸƚǦǂộǉǦđƾềǊǦǉƽắƸǦǂắƸǦƸƽưƶǦƼƾảƾǦđượƸ...",
    ["造历之法，必先立元，元正然后定日法，法定然后度周天以定分至。"] = "ƫƽƗǅǦǁƐǂǦǁịƸƽ,ǦǉấǉǦǅƽảƾǦǁậǅǦƩƼǊǓƙǃǦǉǇướƸ,ǦƩƼǊǓƙǃǦđƕǃƼǦǇồƾǦǈƶǊǦđƚǦǂớƾǦđịǃƽǦƩƽậǉǦǅƽƑǅ,ǦǅƽƑǅǦđịǃƽǦǇồƾǦǈƶǊǦđƚǦǂớƾǦđǄǦƞƽǊǦǉƽƾƙǃǦđểǦđịǃƽǦƫƽƁǃǦƸƽƓ.",
    ["不应该啊，怎么算出来会不一样呢……"] = "ƦƽƇǃƼǦǁẽǦǃƐǄ,ǦǈƶǄǦǉƓǃƽǦǉǄƑǃǦǇƶǦǁạƾǦǀƽƇǃƼǦƼƾốǃƼǦǃƽƶǊǦđượƸǦƸƽứ...",
    ["视这箕星的亮度共方位，三日内分明应有小雨。"] = "ƳƺǂǦđộǦǈƑǃƼǦǋƐǦǅƽươǃƼǦǋịǦƸủƶǦǈƶǄǦƞơǦǃƐǓ,ǦǉǇǄǃƼǦǋƛǃƼǦƷƶǦǃƼƐǓǦǇƅǦǇƐǃƼǦǃƙǃǦƸƚǦǂưƶǦǃƽỏ.",
    ["不对不对，看这圭表的影长，该是七日之后才有雨。"] = "ƦƽƇǃƼǦđƕǃƼǦǀƽƇǃƼǦđƕǃƼ,ǦǍƺǂǦđộǦǤƐƾǦƷƚǃƼǦƸủƶǦƦƽǊƙǦƝƾểǊǦǃƐǓ,ǦǅƽảƾǦƷảǓǦǃƼƐǓǦǈƶǊǦǂớƾǦƸƚǦǂưƶ.",
    ["听说昨儿有人在池子里，看到了一条三尺长的锦鲤王！"] = "ƩƼƽƺǦǃƚƾǦƽƇǂǦǆǊƶǦƸƚǦǃƼườƾǦởǦǉǇǄǃƼǦƽồ,ǦǉƽấǓǦǂộǉǦƸǄǃǦƞẩǂǦƧƈǦƱươǃƼǦǤƐƾǦǉớƾǦƷƶǦǉƽướƸ!",
    ["真的假的？还有这么大的鱼？"] = "ǥƽậǉǦƽƶǓǦƼƾảǦǋậǓ?ǦƞƛǃǦƸƚǦƸǄǃǦƸƑǦǁớǃǦǃƽưǦǉƽếǦǈƶǄ?",
    ["不需要大场地，不需要长兵器，只要有手掌就能打个来回。既能提神醒脑，又能强身健体，现在就试试吧！"] = "ƦƽƇǃƼǦƸầǃǦǈƁǃǦƷƃƾǦǁớǃ,ǦǀƽƇǃƼǦƸầǃǦƷƾǃƽǦǀƽƓǦǤƐƾ,ǦƸƽỉǦƸầǃǦƸƚǦƷƐǃǦǉƶǓǦǁƐǦƸƚǦǉƽểǦđƑǃƽǦǂộǉǦǋƛǃƼ.ǦƱừƶǦƸƚǦǉƽểǦđềǦǉƽầǃǦǉỉǃƽǦǃƃǄ,ǦǋừƶǦƸƚǦǉƽểǦƸườǃƼǦǉƽƁǃǦǀƾệǃǦǉƽể,ǦƽƾệǃǦǉạƾǦǉƽửǦǃƼƶǓǦđƾ!",
    ["典仪赞再拜，百官舞蹈、班首奏万福，分东西立……得好好记下。"] = "ĐƾểǃǦǃƼƽƾǦǉƑǃǦǉƑƾǦƷƑƾ,ǦƷƑƸƽǦǆǊƶǃǦǋũǦđạǄ,ǦƷƶǃǦǉƽủǦǉấǊǦǋạǃǦǅƽƕƸ,ǦǅƽƁǃǦđƇǃƼǦǉƁǓǦǁậǅ...ǦǅƽảƾǦƼƽƾǦǃƽớǦƸƽǄǦǀỹ.",
    ["说起仙逝的皇太后……那可真是位奇女子。当年官家称帝后，百官朝贺，只有太后满面愁容，直言“为君难”。"] = "ƩƽắƸǦđếǃǦƣǄƐǃƼǦǉƽƑƾǦƽậǊǦđƃǦǉƾƙǃǦǉƽệ...ǦđƚǦǆǊảǦǉƽựƸǦǁƐǦǂộǉǦǀỳǦǃữǦǉử.ǦƩăǂǦđƚǦǈƶǊǦǀƽƾǦƬǊƶǃǦƼƾƶǦǍưǃƼǦđế,ǦƷƑƸƽǦǆǊƶǃǦǉǇƾềǊǦƽạ,ǦƸƽỉǦƸƚǦǥƽƑƾǦƽậǊǦǋẻǦǂặǉǦǈầǊǦƸǊǃƼ,ǦǃƚƾǦǉƽẳǃƼǦ\"ǋƾǦǆǊƁǃǦǃƶǃ\".",
    ["上公进酒啊……礼直官引上公升东阶，东上阁门官接引至御座前，上公跪奏。可记清楚了？"] = "ǥƽượǃƼǦƸƇǃƼǦǉƾếǃǦǉửǊǦǃƽƶ...ǦƧễǦǉǇựƸǦǆǊƶǃǦǤẫǃǦǥƽượǃƼǦƸƇǃƼǦǉƽăǃƼǦđƇǃƼǦƼƾƶƾ,ǦĐƇǃƼǦǉƽượǃƼǦƸƑƸǦǂƇǃǦǆǊƶǃǦǉƾếǅǦǤẫǃǦđếǃǦǉǇướƸǦǃƼựǦǉọƶ,ǦǥƽượǃƼǦƸƇǃƼǦǆǊỳǦǉấǊ.ǦĐƃǦǃƽớǦǇƅǦƸƽưƶ?",
    ["别偷懒，等老朽作古了，看谁还能这么仔细教你。"] = "ĐừǃƼǦǁườƾǦƷƾếǃƼ,ǦđợƾǦǁƃǄǦƽủǦǉƑƸǦƸổǦǇồƾ,ǦǍƺǂǦƶƾǦƸƛǃǦƸƚǦǉƽểǦǤạǓǦǃƼươƾǦǉỉǦǂỉǦǃƽưǦǋậǓ.",
    ["学生记下了。"] = "ƣọƸǦǉǇƛǦđƃǦƼƽƾǦǃƽớ.",
    ["梅大人，早劝过你了，献上那种舞蹈，没挨板子已是万幸……"] = "ƨƶƾǦđạƾǦǃƽƁǃ,ǦǈớǂǦđƃǦǀƽǊǓƙǃǦǃƼƐƾǦǇồƾ,ǦƽƾếǃǦǤƁǃƼǦǁǄạƾǦǋũǦđạǄǦđƚ,ǦǀƽƇǃƼǦƷịǦăǃǦƼậǓǦđƃǦǁƐǦǋạǃǦƽạǃƽ...",
    ["幸亏只是被乐正责罚，若是御前献舞，恐怕人头落地啊！"] = "ƨƶǓǦǂƐǦƸƽỉǦƷịǦƩƽạƸǦƸƽƓǃƽǦǉǇƑƸƽǦǅƽạǉ,ǦǃếǊǦǁƐǦƽƾếǃǦǋũǦǉǇướƸǦǃƼựǦǉƾềǃ,ǦƺǦǁƐǦđầǊǦǁƔƶǦǀƽỏƾǦƸổǦđƚ!",
    ["在山峨峨，在水汤汤。世间少见的妙舞，为何就没人能懂呢？"] = "ǥạƾǦǈơǃǦǃƼƶǦǃƼƶ,ǦǉạƾǦǉƽủǓǦǉƽƶǃƼǦǉƽƶǃƼ.ǦǝƾệǊǦǋũǦƽƾếǂǦǉƽấǓǦǉǇƙǃǦđờƾ,ǦǉạƾǦǈƶǄǦǁạƾǦǀƽƇǃƼǦƶƾǦƸƚǦǉƽểǦƽƾểǊǦƸƽứ?",
    ["唉……雪意飘零，知音何处？那扭曲的舞姿，真想再见一次啊……"] = "ƜƾǏ...ǦǉǊǓếǉǦƈǦǅƽƾƙǊǦǁƾǃƽ,ǦǉǇƾǦƁǂǦƽƐǦǍứ?ǦƱũǦǉưǦǊốǃǦǁượǃǦđƚ,ǦǉƽậǉǦǂǊốǃǦđượƸǦǉƽấǓǦǁạƾǦǂộǉǦǁầǃǦǃữƶ...",
    ["瞧一瞧，这三仙进洞的把戏！"] = "ƳƺǂǦǉƽửǦđƾ,ǦǉǇƛǦƽƶǓǦǥƶǂǦǥƾƙǃǦǥƾếǃǦĐộǃƼǦđƁǓ!",
    ["以揖让得天下者，先奏文舞；以征伐得天下者，先奏武舞……此为舞礼。"] = "ǝƖǃƼǦǁễǦǃƽượǃƼǦǂƐǦđắƸǦǉƽƾƙǃǦƽạ,ǦǉǇướƸǦǉấǊǦƱăǃǦǋũ;ǦǤƖǃƼǦƸƽƾǃƽǦǅƽạǉǦǂƐǦđắƸǦǉƽƾƙǃǦƽạ,ǦǉǇướƸǦǉấǊǦƱƅǦǋũ...ǦđƁǓǦƸƽƓǃƽǦǁƐǦƱũǦǁễ.",
    ["不……这不可能……"] = "ƦƽƇǃƼ...ǦƸƽǊǓệǃǦǃƐǓǦǀƽƇǃƼǦǉƽểǦǃƐǄ...",
    ["夫鱼者，大而肥之，鲜而美之！"] = "ƫƽƐǂǦǁƐǦƸƑ,ǦƸǄǃǦǉǄǦǉƽƔǦƷƗǄ,ǦƸǄǃǦǉươƾǦǉƽƔǦǃƼǄǃ!",
    ["知道为什么宫里的鱼都这么鲜……肥美吗？"] = "ƝƾếǉǦǉạƾǦǈƶǄǦƸƑǦǉǇǄǃƼǦƸǊǃƼǦđềǊǦǉươƾ...ǦƷƗǄǦǂỡǦǉƽếǦǃƐǓǦǀƽƇǃƼ?",
    ["正是因为有我这样的小宫女在没日没夜地辛勤喂鱼！"] = "ƞƽƓǃƽǦǁƐǦǋƔǦƸƚǦǉƾểǊǦƸǊǃƼǦǃữǦǃƽưǦǉƶǦđƁǓǦǃƼƐǓǦđƙǂǦƸầǃǦǂẫǃǦƸƽǄǦƸƑǦăǃǦđƚ!",
    ["想来试试吗？随便喂，这么多鱼呢，不会吃撑的。"] = "ƨǊốǃǦǉớƾǦǉƽửǦǀƽƇǃƼ?ǦƞứǦƸƽǄǦăǃǦǉƖǓǦǉƽƓƸƽ,ǦǃƽƾềǊǦƸƑǦǉƽếǦǃƐǓ,ǦǀƽƇǃƼǦǈợǦƸƽƕǃƼǦăǃǦǃǄǦǆǊƑǦđƁǊ.",
    ["汪汪汪~~~"] = "ƢƁǊǦƼƁǊǦƼƁǊ~~~",
    ["这怨鬼之说我还真有点兴趣，这位小兄弟说来听听？"] = "ƞƽǊǓệǃǦǄƑǃǦǆǊỷǦǃƐǓǦǉƶǦǉƽựƸǦǈựǦƸƚǦƸƽƕǉǦƽứǃƼǦǉƽƕ,ǦǋịǦǉƾểǊǦƽǊǓǃƽǦđệǦǃƐǓǦǃƚƾǦǃƼƽƺǦǉƽửǦǍƺǂ?",
    ["是吧是吧！我也觉得，世上哪有空穴来风？自打用了这前朝祭师，这段时日可不少……"] = "ƫƽảƾǦǀƽƇǃƼ,ǦǅƽảƾǦǀƽƇǃƼ!ǦĐệǦƸũǃƼǦǉƽấǓǦǋậǓ,ǦǉǇƙǃǦđờƾǦǁƐǂǦƼƔǦƸƚǦƸƽǊǓệǃǦǀƽƇǃƼǦƽǊǓệǉǦǁƶƾǦǅƽǄǃƼ?ǦǥừǦǀƽƾǦǤƖǃƼǦǥếǦǈưǦǉƾềǃǦǉǇƾềǊǦǃƐǓ,ǦǤạǄǦƼầǃǦđƁǓǦǍảǓǦǇƶǦǀƽƇǃƼǦƓǉǦƸƽǊǓệǃ...",
    ["闭嘴吧！回去加练！这……哈哈大人，这小子尽说胡话，我们这儿从无怪事发生！"] = "ƞƁǂǦǂƾệǃƼ!ǦƬǊƶǓǦǋềǦǁǊǓệǃǦǉƽƙǂǦƸƽǄǦǉƶ!ǦƞƽǊǓệǃǦǃƐǓ...ǦƽƶǦƽƶǦđạƾǦǃƽƁǃ,ǦǉƾểǊǦǉửǦǃƐǓǦǉǄƐǃǦǃƚƾǦƽồǦđồ,ǦƸƽỗǦƸƽƕǃƼǦǉƶǦǉừǦǉǇướƸǦǉớƾǦǃƶǓǦƸƽưƶǦǉừǃƼǦǍảǓǦǇƶǦǆǊƑƾǦǈựǦƼƔ!",
    ["今日能遇到大人，已是走运了。"] = "ƣƇǂǦǃƶǓǦƸƚǦǉƽểǦƼặǅǦđượƸǦđạƾǦǃƽƁǃ,ǦǆǊảǦǁƐǦǋậǃǦǂƶǓǦǇồƾ.",
    ["到了到了，祭师大人就在此处，烦请大人诊治。"] = "ĐếǃǦǇồƾǦđếǃǦǇồƾ,ǦǥếǦǈưǦđạƾǦǃƽƁǃǦởǦǃƼƶǓǦƸƽỗǦǃƐǓ,ǦǅƽƾềǃǦđạƾǦǃƽƁǃǦƸƽẩǃǦǉǇị.",
    ["游侠真喜欢说笑，咱穷得叮当响，不向您讨红包都算好了！不过掌门在里面，您找他要去！！"] = "ǝǊǦƽƾệǅǦǉƽậǉǦǀƽƗǄǦǃƚƾǦđƖƶ,ǦƷọǃǦǉƶǦǃƼƽƘǄǦǇớǉǦǂồǃƼǦǉơƾ,ǦǀƽƇǃƼǦǍƾǃǦǃƼƐƾǦƽồǃƼǦƷƶǄǦđƃǦǁƐǦǉốǉǦǁắǂǦǇồƾ!ǦƞƚǦđƾềǊǦƸƽưởǃƼǦǂƇǃǦởǦƷƙǃǦǉǇǄǃƼ,ǦǃƼƐƾǦǉƔǂǦƇǃƼǦấǓǦǂƐǦđƛƾ!!",
    ["你猜，这开封城里哪儿油水最多？"] = "ƩƼươƾǦđǄƑǃǦǍƺǂ,ǦǉǇǄǃƼǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦǃƐǓǦǃơƾǦǃƐǄǦǃƽƾềǊǦǤầǊǦǂỡǦǃƽấǉ?",
    ["《屋内>不知道$T(5037)什么时候来"] = "<ǥǇǄǃƼǦǃƽƐ>ǦƦƽƇǃƼǦƷƾếǉǦǀƽƾǦǃƐǄǦ$T(5037)ǦǂớƾǦǉớƾ",
    ["一月初五......要回去看看。"] = "ƨƖǃƼǦ5ǦǉƽƑǃƼǦƢƾƙǃƼ......ǦǅƽảƾǦǆǊƶǓǦǋềǦǍƺǂǦǈƶǄ.",
    ["历莲"] = "ƧịƸƽǦƧƾƙǃ",
    ["您看看我这摊子，冷冷清清，凄凄惨惨。这其中的酸楚……唉，不说也罢！"] = "ƩƼƐƾǦǍƺǂǦǈạǅǦƽƐǃƼǦǃƐǓǦƸủƶǦǉƇƾ,ǦǁạǃƽǦǁạǃƽǦǁẽǄǦǁẽǄ,ǦǉƽƙǦǉƽảǂǦǋƇǦƸƖǃƼ.ǦƩỗƾǦƸƽǊƶǦǍƚǉǦǉǇǄǃƼǦđƚ...ǦƶƾǏ,ǦǀƽƇǃƼǦǃƚƾǦƸũǃƼǦđượƸ!",
    ["嗯……经你这么一说，似乎确实差点儿什么。"] = "Ừǂ...ǦǃƼƽƺǦǃƼươƾǦǃƚƾǦǋậǓ,ǦƽƔǃƽǦǃƽưǦđƕǃƼǦǁƐǦǉƽƾếǊǦǉƽƾếǊǦƸƑƾǦƼƔǦđƚ.",
    ["老板生意兴隆！可有余货？我想定一批醋送到城南去。"] = "ƆǃƼǦƸƽủǦǁƐǂǦăǃǦǅƽƑǉǦǉƐƾ!ǦƞƛǃǦǤưǦƽƐǃƼǦǀƽƇǃƼ?ǦǥƶǦǂǊốǃǦđặǉǦǂộǉǦđợǉǦƼƾấǂǦƸƽǊǓểǃǦǉớƾǦǉƽƐǃƽǦǃƶǂ.",
    ["您还真别说！有了这一口“酸后回甘”的醋，这生意，能做！"] = "ƩƼƐƾǦđừǃƼǦǃƚƾǦǉƽếǦǉƽậǉ!ǦƞƚǦđượƸǦǃƼụǂǦƼƾấǂǦ\"ƸƽǊƶǦǈƶǊǦƽƚƶǦǃƼọǉ\"ǦǃƐǓ,ǦǋƾệƸǦǁƐǂǦăǃǦǃƐǓ,ǦǁƐǂǦđượƸ!",
    ["我小时候在凉州尝过，那以后就一直惦记着……"] = "ƧƕƸǦǃƽỏǦǉƇƾǦđƃǦǉừǃƼǦǃếǂǦǆǊƶǦởǦƧươǃƼǦƞƽƁǊ,ǦǉừǦđƚǦǋềǦǈƶǊǦƸứǦǃƽớǦǂƃƾǦǀƽƇǃƼǦǆǊƙǃ...",
    ["我还记得……当年阿爹做成了第一笔生意，带着我去集市玩耍。"] = "ǥƇƾǦƸƛǃǦǃƽớ...ǦǃăǂǦđƚǦƜǦƸƽƶǦǁƐǂǦǉƽƐǃƽǦǅƽƾǦǋụǦǁƐǂǦăǃǦđầǊǦǉƾƙǃ,ǦđƃǦǤẫǃǦǉƇƾǦđƾǦƽộƾǦƸƽợǦǋǊƾǦƸƽơƾ.",
    ["嗯，听大伙儿说……有位叔叔托人送了东西来，只说是你的江湖朋友，表表心意。"] = "Ừǂ,ǦǃƼƽƺǦǂọƾǦǃƼườƾǦǃƚƾ...ǦƸƚǦǂộǉǦǋịǦǉƽƕƸǦǉƽƕƸǦǃƽờǦǃƼườƾǦƼửƾǦđồǦǉớƾ,ǦƸƽỉǦǃƚƾǦǁƐǦƷằǃƼǦƽữǊǦƼƾƶǃƼǦƽồǦƸủƶǦǃƼươƾ,ǦƷƐǓǦǉỏǦƸƽƕǉǦǉƁǂǦƈ.",
    ["我们还没来得及道谢呢！"] = "ƞƽƕǃƼǦǉƶǦƸƛǃǦƸƽưƶǦǀịǅǦǃƚƾǦǁờƾǦƸảǂǦơǃǦǃữƶ!",
    ["嘿嘿，肯定也是位了不起的大侠！"] = "ƣƔǦƽƔ,ǦƸƽắƸǦƸƽắǃǦƸũǃƼǦǁƐǦǂộǉǦǋịǦđạƾǦƽƾệǅǦǁỗƾǦǁạƸ!",
    ["面色脱泽，眼下无神。"] = "ƮắƸǦǂặǉǦǀƗǂǦǉươƾ,ǦǤướƾǦǂắǉǦǋƇǦǉƽầǃ.",
    ["你看着面容疲态，气湿色浊......干什么去了？"] = "ƩƼươƾǦǃƽƔǃǦǤƾệǃǦǂạǄǦǂệǉǦǂỏƾǦǃƐǓ,ǦǀƽƓǦǉƽấǅǦǈắƸǦǉǇọƸ......ǦđƾǦǁƐǂǦƼƔǦǇồƾ?",
    ["最近——打了熊揍了狼，还要和猴子斗智斗勇......"] = "ƢầǃǦđƁǓǦ——ǦđƑǃƽǦƼấǊǦǉẩǃǦǈƚƾ,ǦƸƛǃǦǅƽảƾǦđấǊǦǉǇƓǦđấǊǦǤũǃƼǦǋớƾǦǁũǦǀƽỉ......",
    ["哎，那你要不去里面躺躺？"] = "ƀǓ,ǦǋậǓǦǃƼươƾǦƸƚǦǂǊốǃǦǋƐǄǦǉǇǄǃƼǦǃằǂǦǃƼƽỉǦƸƽƕǉǦǀƽƇǃƼ?",
    ["这香今早我翻出来了一份，正好给你用了。"] = "ƣươǃƼǦǃƐǓǦǈƑǃƼǦǃƶǓǦǉƶǦǂớƾǦǁụƸǦǇƶǦǂộǉǦǅƽầǃ,ǦǋừƶǦƽƶǓǦǤƖǃƼǦƸƽǄǦǃƼươƾ.",
    ["这味道......哪儿闻过..."] = "ƨƖƾǦƽươǃƼǦǃƐǓ......ǦđƃǦǃƼửƾǦǉƽấǓǦởǦđƁǊǦǇồƾ...",
    ["没有脸...呜呜...寒姨...没有脸的人......"] = "ƦƽƇǃƼǦƸƚǦǂặǉ...ǦƽǊǦƽǊ...ǦƣƐǃǦǤƾ...ǦǃƼườƾǦǀƽƇǃƼǦƸƚǦǂặǉ......",
    ["别怕，他们不是坏人。他们不是有意吓你的......"] = "ĐừǃƼǦǈợ,ǦƽọǦǀƽƇǃƼǦǅƽảƾǦǃƼườƾǦǍấǊ.ǦƣọǦǀƽƇǃƼǦƸốǦƈǦǤọƶǦƸǄǃǦđƁǊ......",
    ["睡吧，睡着了，就忘了，就不怕了。"] = "ƩƼủǦđƾ,ǦǃƼủǦǈƶǓǦǇồƾ,ǦǈẽǦǆǊƙǃǦǉƽƇƾ,ǦǈẽǦǀƽƇǃƼǦǈợǦǃữƶ.",
    ["……寒姨"] = "……ƣƐǃǦǤƾ",
    ["推磨嘎嘎响，舂米沙沙扬。暖香飘过三道岗，瞌睡来得晃荡荡..."] = "ƳǄƶǓǦƸốƾǦǍƶǓǦǀƙǊǦǀƘǃǦǀẹǉ,ǦƼƾƃǦƼạǄǦǃƽịǅǦǃƽƐǃƼǦǍƶǦǍƶ.ǦƣươǃƼǦấǂǦƷƶǓǦǆǊƶǦƷƶǦǃƼọǃǦđồƾ,ǦƸơǃǦƷǊồǃǦǃƼủǦđếǃǦǂơǦǂƐǃƼ...",
    ["少司命，绿衣裳，举长剑，护小秧……"] = "ǥƽƾếǊǦǥƾǦƨệǃƽ,ǦƑǄǦǍƶǃƽǦǍƶǃƽ,ǦǉƶǓǦƸầǂǦǉǇườǃƼǦǀƾếǂ,ǦƷảǄǦǋệǦǂầǂǦǍƶǃƽ……",
    ["猫不喵，狗不汪，让我家满崽，睡到天透光......"] = "ƨƘǄǦǀƽƇǃƼǦǀƙǊ,ǦƸƽƚǦǀƽƇǃƼǦǈủƶ,ǦđểǦƨƃǃǦǃƽƾǦǃƽƐǦǉƶ,ǦǃƼủǦđếǃǦǁƕƸǦƷƔǃƽǦǂƾǃƽǦǇạǃƼǦǇỡ......",
    ["醒啦？你感觉好点了吗？"] = "ǥỉǃƽǦǇồƾǦƐ?ǦƩƼươƾǦƸảǂǦǉƽấǓǦǀƽỏƺǦƽơǃǦƸƽƕǉǦǃƐǄǦƸƽưƶ?",
    ["我...我梦见寒姨了。"] = "ǥƶ...ǦǉƶǦǂơǦǉƽấǓǦƣƐǃǦǤƾ.",
    ["她的手好暖，轻轻哼着歌。"] = "ǥƶǓǦƷƐǦấǓǦǉƽậǉǦấǂ,ǦǀƽẽǦǀƽƐǃƼǦƽƑǉǦǇǊ.",
    ["还是在活人医馆睡觉好，睡得神清气爽。"] = "ƱẫǃǦǁƐǦǃƼủǦởǦƣǄạǉǦƩƽƁǃǦǓǦǆǊƑǃǦǉốǉ,ǦǃƼủǦǍǄǃƼǦǉƾǃƽǦǉƽầǃǦǈảǃƼǦǀƽǄƑƾ.",
    ["是施婆婆的青灵香好。反正她送来也是给……给你用也一样。"] = "ƧƐǦǥƽƶǃƽǦƧƾǃƽǦƣươǃƼǦƸủƶǦǥƽƾǦƷƐǦƷƐǦǉốǉ.ǦǝƖǦǈƶǄǦƷƐǦấǓǦƼửƾǦǉớƾǦƸũǃƼǦǁƐǦđể......ǦƸƽǄǦǃƼươƾǦǤƖǃƼǦƸũǃƼǦǋậǓǦǉƽƇƾ.",
    ["妙手回春啊姚大夫，走啦！"] = "ǝƾệǊǦǉƽủǦƽồƾǦǍǊƁǃǦǃƽƶǦǝƾƙǊǦđạƾǦǅƽǊ,ǦǉƶǦđƾǦđƁǓ!",
    ["许久未见这般热闹的景象了……今日，便弹些欢快的曲子吧。"] = "ĐƃǦǁƁǊǦǀƽƇǃƼǦǉƽấǓǦƸảǃƽǦǉượǃƼǦǃƑǄǦǃƽƾệǉǦǉƽếǦǃƐǓ...ǦƣƇǂǦǃƶǓ,ǦƽƃǓǦđƐǃǦǋƐƾǦǀƽƕƸǦǃƽạƸǦǋǊƾǦǉươƾǦǋậǓ.",
    ["去年亏了不少，今年我要转大运，赚大财，我转，我赚……给我转哪来了……好晕……"] = "ƩăǂǦǃƼǄƑƾǦǁỗǦǀƽƇǃƼǦƓǉ,ǦǃăǂǦǃƶǓǦǉƶǦǅƽảƾǦƸƽǊǓểǃǦđạƾǦǋậǃ,ǦǅƽƑǉǦđạƾǦǉƐƾ,ǦǉƶǦǍǄƶǓ,ǦǉƶǦǀƾếǂ...ǦƳǄƶǓǦǉƶǦđƾǦđƁǊǦǉƽếǦǃƐǓ...ǦƞƽƚǃƼǦǂặǉǦǆǊƑ...",
    ["不讲不讲！转晕了，就是转运了！"] = "ƦƽƇǃƼǦǃƚƾǦǀƽƇǃƼǦǃƚƾ!ǦƳǄƶǓǦđếǃǦƸƽƚǃƼǦǂặǉ,ǦƸƽƓǃƽǦǁƐǦƸƽǊǓểǃǦǋậǃǦǇồƾ!",
    ["有段时间没回去看过了……方才试/了试，山门的研究果真不一般……"] = "ƞũǃƼǦǂộǉǦǉƽờƾǦƼƾƶǃǦǇồƾǦƸƽưƶǦǋềǦǉƽăǂ...ǦƱừƶǦǃƃǓǦǉƽửǦǂộǉǦƸƽƕǉ,ǦǃƼƽƾƙǃǦƸứǊǦƸủƶǦǈơǃǦǂƇǃǦǆǊảǦǃƽƾƙǃǦǀƽƇǃƼǦǉầǂǦǉƽườǃƼ...",
    ["在丹崖独坐许久，听闻开封来了山门中人，我便也来抚一抚琴。"] = "ƩƼồƾǦǂộǉǦǂƔǃƽǦởǦĐƶǃǦƩƽƶƾǦđƃǦǁƁǊ,ǦǃƼƽƺǦǉƾǃǦƦƽƶƾǦƫƽǄǃƼǦƸƚǦǃƼườƾǦƸủƶǦǈơǃǦǂƇǃǦǉớƾ,ǦǉƶǦƸũǃƼǦđếǃǦƼảǓǦǂộǉǦǀƽƕƸǦƸầǂ.",
    ["这一曲……愿新岁吉祥如意，万事顺遂。"] = "ƦƽƕƸǦǃƽạƸǦǃƐǓ...ǦƩƼǊǓệǃǦǃăǂǦǂớƾǦƸƑǉǦǉườǃƼǦǃƽưǦƈ,ǦǋạǃǦǈựǦǉƽǊậǃǦǁợƾ.",
    ["越着急，越是练本事的时候。留神，该出锅了！"] = "ƞƐǃƼǦǃƇǃǦǃƚǃƼ,ǦƸƐǃƼǦǁƐǦǁƕƸǦǇƘǃǦǁǊǓệǃǦƷảǃǦǁĩǃƽ.ǦƞƽƕǦƈ,ǦƸƽǊẩǃǦƷịǦǇƶǦǂƚǃǦǇồƾ!",
    ["从没试过同时炒这么多道菜！越着急，越是练本事的时候。留神，该出锅了！"] = "ƞƽưƶǦƷƶǄǦƼƾờǦǉƽửǦǍƐǄǦǃƽƾềǊǦǂƚǃǦƸƖǃƼǦǁƕƸǦǉƽếǦǃƐǓ!ǦƞƐǃƼǦǃƇǃǦǃƚǃƼ,ǦƸƐǃƼǦǁƐǦǁƕƸǦǇƘǃǦǁǊǓệǃǦƷảǃǦǁĩǃƽ.ǦƞƽƕǦƈ,ǦƸƽǊẩǃǦƷịǦǇƶǦǂƚǃǦǇồƾ!",
    ["闭逍斯"] = "ƝếǦǥƾƙǊǦǥư",
    ["哎......还要走多远才到头啊！"] = "ƞƽƶǄǦƇƾ...ǦƞƛǃǦǅƽảƾǦđƾǦƷƶǄǦǍƶǦǃữƶǦǂớƾǦǉớƾǦǃơƾǦđƁǓ!",
    ["我们师门，正是为支援王清师叔而来。我脚程快些，就在这镇戍仓多呆了几日。"] = "ƮưǦǂƇǃǦƸƽƕǃƼǦǉƶǦƸƽƓǃƽǦǁƐǦǋƔǦƸƽƾǦǋƾệǃǦƸƽǄǦƱươǃƼǦǥƽƶǃƽǦǈưǦǉƽƕƸǦǂƐǦđếǃ.ǦƞướƸǦǉǇƔǃƽǦƸủƶǦǉƶǦǃƽƶǃƽǦƽơǃǦǂộǉǦƸƽƕǉ,ǦǃƙǃǦđƃǦởǦǁạƾǦǥǇấǃǦǥƽƕǦǥƽươǃƼǦǃƐǓǦǉƽƙǂǦǂấǓǦǃƼƐǓ.",
    ["应是不会，咱再等等吧。"] = "ƞƽắƸǦǁƐǦǀƽƇǃƼǦđƁǊ,ǦƸƽƕǃƼǦǉƶǦđợƾǦǉƽƙǂǦƸƽƕǉǦǃữƶǦǍƺǂǦǈƶǄ.",
    ["……嗯，确是个兵痞，写满了他搜刮民财、草菅人命的罪证。"] = "...ǦỪǂ,ǦđƕǃƼǦǁƐǦǂộǉǦǉƙǃǦƷƾǃƽǦƷƑǂ,ǦǋƾếǉǦđầǓǦǃƽữǃƼǦǉộƾǦƸƽứǃƼǦǋơǦǋƗǉǦǉƾềǃǦƸủƶǦǤƁǃ,ǦƸǄƾǦǂạǃƼǦǃƼườƾǦǃƽưǦƸỏǦǇƑƸǦƸủƶǦƽắǃ.",
    ["这年头，一个人才最安全呢！"] = "ǥƽờƾǦƷǊổƾǦǃƐǓ,ǦǂộǉǦǂƔǃƽǦǂớƾǦǁƐǦƶǃǦǉǄƐǃǦǃƽấǉ!",
    ["还不如一个人待着呢，我一个人……不也遇见师父你了嘛！"] = "ǥƽƐǦƸứǦởǦǂộǉǦǂƔǃƽǦƸƛǃǦƽơǃ,ǦƸǄǃǦǂộǉǦǂƔǃƽ...ǦƸƽẳǃƼǦǅƽảƾǦƸũǃƼǦƼặǅǦđượƸǦǈưǦǅƽụǦǃƼườƾǦǈƶǄ!",
    ["剑诀风"] = "ƦƾếǂǦƬǊǓếǉǦƫƽǄǃƼ",
    ["异常挂载"] = "ǝịǦǉƽườǃƼǦǆǊảƾǦǉƑƾ",
    ["都杀了，一个也不许放跑！"] = "ƢƾếǉǦǈạƸƽǦƷọǃǦƸƽƕǃƼ,ǦǂộǉǦǉƙǃǦƸũǃƼǦǀƽƇǃƼǦđượƸǦǉƽảǦƸƽạǓ!",
    ["契丹兵"] = "ƦƽƾếǉǦĐƶǃǦƷƾǃƽ",
    ["官爷，饶命啊！饶命啊！"] = "ƬǊƶǃǦƼƾƶ,ǦǉƽƶǦǂạǃƼ!ǦǥƽƶǦǂạǃƼ!",
    ["年老百姓"] = "ƧƃǄǦƷƑƸƽǦǉƓǃƽ",
    ["哈哈哈哈哈，中原人，都是软骨头的玩意儿！"] = "ƣƶǦƽƶǦƽƶǦƽƶǦƽƶ,ǦǃƼườƾǦǥǇǊǃƼǦƩƼǊǓƙǃǦǉǄƐǃǦǁƐǦǁũǦƽƘǃǦǃƽƑǉǦǃƽǊǦǃƽượƸ!",
    ["什么人？找死！"] = "ƦẻǦǃƐǄ?ǦǥƔǂǦƸƽếǉ!",
    ["暂时没事了，你们快些跑吧。"] = "ǥạǂǦǉƽờƾǦǀƽƇǃƼǦǈƶǄǦǇồƾ,ǦƸƑƸǦǃƼươƾǦǂƶǊǦƸƽạǓǦđƾ.",
    ["多谢大侠救命之恩，多谢大侠！"] = "ĐƶǦǉạǦđạƾǦƽƾệǅǦƸứǊǦǂạǃƼ,ǦđƶǦǉạǦđạƾǦƽƾệǅ!",
    ["走，快走……"] = "Đƾ,ǦǂƶǊǦđƾ……",
    ["爷爷……我不想走了，我的脚好疼……"] = "ƢƾƶǦƼƾƶ……ǦƸǄǃǦǀƽƇǃƼǦǂǊốǃǦđƾǦǃữƶ,ǦƸƽƁǃǦƸǄǃǦđƶǊǦǆǊƑ……",
    ["幼童"] = "ẤǊǦđồǃƼ",
    ["又又乖啊，娘背着你，到南边去就好了……"] = "ƣựǊǦƣựǊǦǃƼǄƶǃǦǃƐǄ,ǦǃươǃƼǦƸƅǃƼǦƸǄǃ,ǦđếǃǦǅƽƓƶǦƩƶǂǦǁƐǦổǃǦǇồƾ……",
    ["家？没家了，没家了……唉……"] = "ƩƽƐ?ǦƞƽẳǃƼǦƸƛǃǦǃƽƐǦǃữƶ,ǦƸƽẳǃƼǦƸƛǃǦǃƽƐǦǃữƶ……ǦƆƾ……",
    ["爹，听说朝廷大军全败了，咱们，咱们还能指望谁啊？"] = "ƞƽƶ,ǦǃƼƽƺǦǃƚƾǦđạƾǦǆǊƁǃǦǉǇƾềǊǦđƔǃƽǦƷạƾǦǉǇậǃǦƽếǉǦǇồƾ,ǦƸƽƕǃƼǦǉƶ,ǦƸƽƕǃƼǦǉƶǦƸƛǃǦƸƚǦǉƽểǦǉǇƇǃƼǦƸậǓǦǋƐǄǦƶƾǦđƁǓ?",
    ["中年人"] = "ǥǇǊǃƼǦǃƾƙǃǦǃƽƁǃ",
    ["原说这山顶上住着厉害人物，使着什么机关术，一人能抵百人，咱们才来投奔……"] = "ƱốǃǦǃƼƽƺǦǃƚƾǦǉǇƙǃǦđỉǃƽǦǃƕƾǦǃƐǓǦƸƚǦǋịǦǁợƾǦƽạƾǦǃƽƁǃǦǋậǉ,ǦǈửǦǤụǃƼǦƸƑƾǦƼƔǦƸơǦǆǊƶǃǦǉƽǊậǉ,ǦǂộǉǦǃƼườƾǦƸƚǦǉƽểǦđịƸƽǦǉǇăǂǦǃƼườƾ,ǦƸƽƕǃƼǦǉƶǦǂớƾǦǉớƾǦđầǊǦǆǊƁǃ……",
    ["……可结果呢？满山的虏人！"] = "……ǦƩƽưǃƼǦǀếǉǦǆǊảǦǉƽƔǦǈƶǄ?ǦƦƽắǅǦǃƕƾǦǉǄƐǃǦǁƐǦǆǊƁǃǦƼƾặƸ!",
    ["怕不是也像那杜什么，投了契丹了……"] = "ƮợǦǁƐǦƸũǃƼǦƼƾốǃƼǦǃƽưǦǉƙǃǦĐỗǦƼƔǦđƚ,ǦƽƐǃƼǦƦƽƾếǉǦĐƶǃǦǇồƾ……",
    ["死得死，降的降，能指望啥？指望自己这两条腿罢！"] = "ƦẻǦƸƽếǉǦǃƼườƾǦƽƐǃƼ,ǦƸƛǃǦǉǇƇǃƼǦǂǄǃƼǦƼƔǦđượƸ?ǦǥǇƇǃƼǦƸậǓǦǋƐǄǦđƇƾǦƸƽƁǃǦǃƐǓǦǉƽƇƾ!",
    ["契丹人骑马，咱们两条腿怎么跑得过四条腿……"] = "ƩƼườƾǦƦƽƾếǉǦĐƶǃǦƸưỡƾǦǃƼựƶ,ǦƽƶƾǦƸƽƁǃǦƸƽƕǃƼǦǉƶǦǈƶǄǦƸƽạǓǦǁạƾǦƷốǃǦƸƽƁǃǦǃƼựƶ……",
    ["那怎么办？留在这里，让虏狗把我们当猪猡赶，当猪猡杀？"] = "ƱậǓǦǅƽảƾǦǁƐǂǦǈƶǄ?ǦƧẽǦǃƐǄǦởǦǁạƾǦđƁǓ,ǦđểǦǁũǦƸƽƚǦƼƾặƸǦǁƖƶǦƸƽƕǃƼǦǉƶǦǃƽưǦǁƖƶǦƽƺǄ,ǦƼƾếǉǦǃƽưǦƼƾếǉǦǁợǃǦǈƶǄ?",
    ["大侠，这北边……唉……你功夫好，腿脚快，早些南下吧……"] = "ĐạƾǦƽƾệǅ,ǦǅƽƓƶǦƝắƸǦǃƐǓ……ǦƇƾ……ǦƸƇǃƼǦǅƽǊǦƸủƶǦǃƼƐƾǦƸƶǄǦƸườǃƼ,ǦǉƽƁǃǦǅƽƑǅǦǉậǉǦƽƐǃƽ,ǦƽƃǓǦǈớǂǦǃƶǂǦƽạǦđƾ……",
    ["你们往西南走三里左右，有一个江湖人的营地，可在那儿歇息，随他们南下。"] = "ƞƑƸǦǃƼươƾǦđƾǦǋềǦƽướǃƼǦǥƁǓǦƩƶǂǦǀƽǄảǃƼǦƷƶǦǤặǂ,ǦƸƚǦǂộǉǦǤǄƶǃƽǦǉǇạƾǦƸủƶǦǃƼườƾǦƼƾƶǃƼǦƽồ,ǦƸƚǦǉƽểǦởǦđƚǦǃƼƽỉǦǃƼơƾǦǇồƾǦǉƽƺǄǦƽọǦǃƶǂǦƽạ.",
    ["多谢大侠、多谢大侠！"] = "ĐƶǦǉạǦđạƾǦƽƾệǅ,ǦđƶǦǉạǦđạƾǦƽƾệǅ!",
    ["又又，等到了营地，咱们好好歇会儿……"] = "ƣựǊǦƣựǊ,ǦđợƾǦđếǃǦǤǄƶǃƽǦǉǇạƾ,ǦƸƽƕǃƼǦǉƶǦǈẽǦǃƼƽỉǦǃƼơƾǦǂộǉǦƸƽƕǉ……",
    ["嗯？那边……"] = "ƣử?ǦĐằǃƼǦǀƾƶ……",
    ["好些虏人的尸首。"] = "ƞƚǦǀƽƇǃƼǦƓǉǦǉƽƾǦǉƽểǦǆǊƁǃǦƼƾặƸ.",
    ["有人在此设伏……"] = "ƞƚǦǀẻǦǂƶƾǦǅƽụƸǦởǦđƁǓ……",
    ["是机关术，墨山道弟子的手笔？"] = "ƧƐǦƸơǦǆǊƶǃǦǉƽǊậǉ,ǦǉƽủǦƷƕǉǦƸủƶǦđệǦǉửǦƨặƸǦƮơǃǦĐạǄǦǈƶǄ?",
    ["血迹向林中去了，难道还有活口？"] = "ƱếǉǦǂƑǊǦǤẫǃǦǋƐǄǦǉǇǄǃƼǦǇừǃƼ,ǦǁẽǦǃƐǄǦǋẫǃǦƸƛǃǦǃƼườƾǦǈốǃƼ?",
    ["得去看看"] = "ƫƽảƾǦđƾǦǍƺǂǦǉƽử",
    ["……无天命……不自降天之哉得之……嘶……"] = "……ǦƦƽƇǃƼǦƸƚǦǉƽƾƙǃǦǂệǃƽ……ǦƞƽẳǃƼǦǉựǦƼƾƑǃƼǦǉừǦǉǇờƾǦǈƶǄǦƸƚǦđượƸ……ǦƳǊƈǉ……",
    ["马屏山"] = "ƨƃǦƝƔǃƽǦƮơǃ",
    ["那边的契丹人， đều là ngươi giết?"] = "ĐƑǂǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦđằǃƼǦǀƾƶ,ǦđềǊǦǁƐǦǃƼươƾǦƼƾếǉǦǈƶǄ?",
    ["……顺手。"] = "……ǦǥƽǊậǃǦǉƶǓǦǉƽƇƾ.",
    ["顺手？阁下倒是好本事。看阁下所用机关，是墨门弟子？"] = "ǥƽǊậǃǦǉƶǓ?ǦƞƑƸǦƽạǦǉƽậǉǦƽảǄǦƷảǃǦǈự.ǦƳƺǂǦƸơǦǆǊƶǃǦƸƑƸǦƽạǦǤƖǃƼ,ǦǁƐǦđệǦǉửǦƨặƸǦƨƇǃǦǈƶǄ?",
    ["与你何干？"] = "ƧƾƙǃǦǆǊƶǃǦƼƔǦđếǃǦǃƼươƾ?",
    ["行事这样张扬——契丹那边，墨门弟子的脑袋，价格可不低……"] = "ƣƐǃƽǦǈựǦǉǇươǃƼǦǤươǃƼǦǉƽếǦǃƐǓǦ—ǦƫƽƓƶǦƦƽƾếǉǦĐƶǃ,ǦƸƑƾǦđầǊǦƸủƶǦđệǦǉửǦƨặƸǦƨƇǃǦƼƾƑǦǀƽƇǃƼǦƽềǦǉƽấǅǦđƁǊ……",
    ["哼，我当是什么人物，原是战场上刨食的腌臜货色？"] = "ƣừ,ǦǉƶǦƸứǦǉưởǃƼǦǁƐǦƷậƸǦǃƽƁǃǦǋậǉǦǃƐǄ,ǦƽƚƶǦǇƶǦǁƐǦƽạǃƼǦǤơǦƷẩǃǦǀƾếǂǦăǃǦǉǇƙǃǦƸƽƾếǃǦǉǇườǃƼǦǈƶǄ?",
    ["我能杀他们，自然就可杀你！"] = "ǥƶǦƼƾếǉǦđượƸǦƸƽƕǃƼ,ǦǉựǦǃƽƾƙǃǦƸũǃƼǦƼƾếǉǦđượƸǦǃƼươƾ!",
    ["算了，这时候还来北边赶着送死，你这脑袋，我看也值不了许多钱。"] = "ƝỏǦđƾ,ǦǉầǂǦǃƐǓǦƸƛǃǦđếǃǦǅƽươǃƼǦƝắƸǦǉƔǂǦƸƑƾǦƸƽếǉ,ǦƸƑƾǦđầǊǦǃƐǓǦƸủƶǦǃƼươƾǦǉƶǦǉƽấǓǦƸũǃƼǦƸƽẳǃƼǦđƑǃƼǦƼƾƑǦƷƶǄǦǃƽƾƙǊ.",
    ["怎的又帮我？"] = "ƮƶǄǦǁạƾǦƼƾƕǅǦǉƶǦǃữƶ?",
    ["你嘴巴虽臭，但还算是好汉。"] = "ƞƑƾǦǂƾệǃƼǦǃƼươƾǦǉǊǓǦǉƽốƾ,ǦǃƽưǃƼǦǋẫǃǦđượƸǦƸǄƾǦǁƐǦƽảǄǦƽƑǃ.",
    ["好汉？那你高看我了，我是来寻仇的。"] = "ƣảǄǦƽƑǃ?ǦƱậǓǦǃƼươƾǦđƑǃƽǦƼƾƑǦǉƶǦǆǊƑǦƸƶǄǦǇồƾ,ǦǉƶǦđếǃǦđểǦƷƑǄǦǉƽƖ.",
    ["这时候来北边寻仇？天大的仇怨？"] = "ƧƕƸǦǃƐǓǦǁạƾǦđếǃǦǅƽươǃƼǦƝắƸǦƷƑǄǦǉƽƖ?ǦƪƑǃǦǉƽƖǦǉƽƾƙǃǦđạƾǦǈƶǄ?",
    ["杀父之仇，够不够大？"] = "ƮƑǉǦǅƽụǦƸƽƾǦǉƽƖ,ǦđƃǦđủǦǁớǃǦƸƽưƶ?",
    ["他就在这座山上，可这些虏狗盘踞不去，碍事得很……咳咳……"] = "ƣắǃǦđƶǃƼǦởǦǉǇƙǃǦǃƕƾǦǃƐǓ,ǦǃƽưǃƼǦǁũǦƸƽƚǦƼƾặƸǦǃƐǓǦƸứǦƷƐǃǦƸứǦǀƽƇǃƼǦđƾ,ǦǉƽậǉǦǋướǃƼǦƸƽƁǃǦǋướǃƼǦǉƶǓ……ǦƦƽụǦǀƽụ……",
    ["杀父之仇，我自不能拦你。只是契丹人马未去，以你现在的伤势想上山，怕是死路一条。"] = "ƮƑǉǦǅƽụǦƸƽƾǦǉƽƖ,ǦǉƶǦǉựǦǃƽƾƙǃǦǀƽƇǃƼǦǉƽểǦǃƼăǃǦǃƼươƾ.ǦƞƚǦđƾềǊǦƷƾǃƽǦǂƃǦƦƽƾếǉǦĐƶǃǦƸƽưƶǦđƾ,ǦǋớƾǦǉƽươǃƼǦǉƽếǦƽƾệǃǦƼƾờǦƸủƶǦǃƼươƾǦǂƐǦđƛƾǦǁƙǃǦǃƕƾ,ǦƺǦǁƐǦđườǃƼǦƸƽếǉ.",
    ["你那仇人究竟是谁？就冲你杀了那么多契丹人，我可替你去探这一遭。"] = "ƦẻǦǉƽƖǦƸủƶǦǃƼươƾǦǇốǉǦƸǊộƸǦǁƐǦƶƾ?ǦƩểǦǉƔǃƽǦǃƼươƾǦƼƾếǉǦǃƽƾềǊǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦǃƽưǦǋậǓ,ǦǉƶǦƸƚǦǉƽểǦǉƽƶǓǦǃƼươƾǦđƾǦǉƽƑǂǦǉƽƓǃƽǦǂộǉǦƸƽǊǓếǃ.",
    ["哼，江湖人都叫他——“鹤”。"] = "ƣừ,ǦƼƾƶǃƼǦƽồǦƼọƾǦƽắǃǦǁƐǦ—Ǧ\"ƣạƸ\".",
    ["鹤……"] = "ƣạƸ……",
    ["你知道他？"] = "ƩƼươƾǦƷƾếǉǦƽắǃ?",
    ["曾听闻他是墨门长老，为人宽和，江湖上也流传有他的诸多轶事。"] = "ǥừǃƼǦǃƼƽƺǦǤƶǃƽǦƽắǃǦǁƐǦǉǇưởǃƼǦǁƃǄǦƨặƸǦƨƇǃ,ǦǉƓǃƽǦǉƔǃƽǦǀƽǄƶǃǦƽƛƶ,ǦǉǇƙǃǦƼƾƶǃƼǦƽồǦƸũǃƼǦǁưǊǦǉǇǊǓềǃǦǃƽƾềǊǦǤậǉǦǈựǦǋềǦƽắǃ.",
    ["呵，沽名钓誉之辈罢了。你可知，他已投靠了虏人？"] = "ƣừ,ǦƽạǃƼǦƸƇǦǤƶǃƽǦƸƁǊǦǤựǦǂƐǦǉƽƇƾ.ǦƩƼươƾǦƸƚǦƷƾếǉ,ǦƽắǃǦđƃǦđầǊǦǆǊƁǃǦƸƽǄǦǁũǦƼƾặƸǦǇồƾǦǀƽƇǃƼ?",
    ["怎会？钱帛，地位，命，总有能打动他的。都说他手握机关重器，若真想和虏人决一死战，又怎会拖到现在？"] = "ƮƶǄǦƸƚǦǉƽể?ǦǥƾềǃǦƷạƸ,ǦđịƶǦǋị,ǦǂạǃƼǦǈốǃƼ,ǦǀƾểǊǦƼƔǦƸũǃƼǦƸƚǦǉƽứǦǁƐǂǦƽắǃǦđộǃƼǦǁƛǃƼ.ǦĐềǊǦǃƚƾǦƽắǃǦǃắǂǦƼƾữǦƸơǦǆǊƶǃǦǉǇọǃƼǦǀƽƓ,ǦǃếǊǦǉƽậǉǦǈựǦǂǊốǃǦƸƖǃƼǦǁũǦƼƾặƸǦǆǊǓếǉǦǉửǦǃƽấǉǦƸƽƾếǃ,ǦǈƶǄǦƸƚǦǉƽểǦǀƗǄǦǤƐƾǦđếǃǦƼƾờ?",
    ["虏人早就想招降他，连那耶律屋质都亲自来了，如今书院被重兵把守，进出不得。怕是他们连南下的勾当都谈好了！"] = "ƧũǦƼƾặƸǦǈớǂǦđƃǦǂǊốǃǦƸƽƾƙǊǦƽƐǃƼǦƽắǃ,ǦǃƼƶǓǦƸảǦǝƶǦƧǊậǉǦỐƸǦƞƽấǉǦƸũǃƼǦđƓƸƽǦǉƽƁǃǦǉớƾǦǇồƾ,ǦǃƶǓǦǉƽưǦǋƾệǃǦƷịǦǉǇọǃƼǦƷƾǃƽǦƸƶǃƽǦƼƾữ,ǦǃộƾǦƷấǉǦǍǊấǉǦǃƼǄạƾǦƷấǉǦǃƽậǅ.ǦǑǦǁƐǦƷọǃǦƸƽƕǃƼǦǃƼƶǓǦƸảǦƼƾƶǄǦǀƘǄǦǃƶǂǦƽạǦƸũǃƼǦđƃǦƷƐǃǦǍǄǃƼǦǍǊƇƾ!",
    ["只可惜有些人……执迷不悟，本已逃出生天，却还要巴巴地回来救他……呵，真是……蠢货……"] = "ƞƽỉǦǉƾếƸǦƸƚǦǀẻ……ǦƸƽấǅǦǂƙǦƷấǉǦǃƼộ,ǦǋốǃǦđƃǦđƐǄǦǉƽǄƑǉǦǈƾǃƽǦǉƽƾƙǃ,ǦǁạƾǦƸƛǃǦƽớǉǦƽảƾǦǆǊƶǓǦǋềǦƸứǊǦƽắǃ……Ǧƣừ,ǦǉƽậǉǦǁƐ……ǦđồǦǃƼǊ……",
    ["你……似与墨门颇有渊源？一身墨门本事，又有杀父之仇……令尊是墨门旧徒？"] = "ƩƼươƾ……ǦǤườǃƼǦǃƽưǦƸƚǦǉƽƁǂǦƼƾƶǄǦǋớƾǦƨặƸǦƨƇǃ?ǦƨƶǃƼǦǉǇƙǃǦǂƔǃƽǦƷảǃǦǁĩǃƽǦƨặƸǦƨƇǃ,ǦǁạƾǦƸƚǦǈƑǉǦǅƽụǦƸƽƾǦǉƽƖ……ǦƧệǃƽǦǉƇǃǦǁƐǦƸựǊǦđồǦƨặƸǦƨƇǃǦǈƶǄ?",
    ["不必胡猜，我父亲与墨门无关……我这一身本事，是我这仇人所授。"] = "ĐừǃƼǦƸƚǦđǄƑǃǦƷừƶ,ǦǅƽụǦǉƽƁǃǦǉƶǦǀƽƇǃƼǦǁƾƙǃǦǆǊƶǃǦƼƔǦđếǃǦƨặƸǦƨƇǃ……ǦƝảǃǦǁĩǃƽǦǃƐǓǦƸủƶǦǉƶ,ǦƸƽƓǃƽǦǁƐǦǤǄǦǉƙǃǦǉƽƖǦǃƽƁǃǦǀƾƶǦǉǇǊǓềǃǦǉƽụ.",
    ["杀了他后，我自会废掉功夫，不欠他什么。"] = "ƮƶǊǦǀƽƾǦƼƾếǉǦƽắǃ,ǦǉƶǦǉựǦǈẽǦǅƽếǦƷỏǦǋƅǦƸƇǃƼ,ǦǀƽƇǃƼǦǃợǦƽắǃǦđƾềǊǦƼƔ.",
    ["对了，这里有枚印章，是他昔日所留……"] = "ĐƕǃƼǦǇồƾ,ǦởǦđƁǓǦƸƚǦǂộǉǦƸǄǃǦấǃ,ǦǁƐǦǤǄǦƽắǃǦđểǦǁạƾǦǃăǂǦǍưƶ……",
    ["若你真能见到他，将此物给他，他便知道马屏山如约来取他性命了。"] = "ƩếǊǦǃƼươƾǦǉƽựƸǦǈựǦƼặǅǦđượƸǦƽắǃ,ǦƽƃǓǦđưƶǦǋậǉǦǃƐǓǦƸƽǄǦƽắǃ,ǦƽắǃǦǈẽǦƷƾếǉǦƨƃǦƝƔǃƽǦƮơǃǦǃƽưǦướƸǦƽẹǃǦǉớƾǦǁấǓǦǂạǃƼǦƽắǃǦǇồƾ.",
    ["从这后边走安全些，只是山路陡峭，或要费些功夫。"] = "ĐƾǦǁốƾǦǅƽƓƶǦǈƶǊǦǃƐǓǦƶǃǦǉǄƐǃǦƽơǃ,ǦƸƚǦđƾềǊǦđườǃƼǦǃƕƾǦƽƾểǂǦǉǇở,ǦƺǦǁƐǦǅƽảƾǦǉốǃǦƸƽƕǉǦƸƇǃƼǦǅƽǊ.",
    ["这印章.…是封龙书院的弟子令？与马屏山的印章，形制倒很相似......"] = "ƞǄǃǦấǃǦǃƐǓ……ǦǁƐǦĐệǦǉửǦǁệǃƽǦƸủƶǦƫƽǄǃƼǦƧǄǃƼǦǥƽưǦƱƾệǃǦǈƶǄ?ǦƮǄǦǋớƾǦấǃǦƸƽươǃƼǦƸủƶǦƨƃǦƝƔǃƽǦƮơǃ,ǦƽƔǃƽǦƸƽếǦǆǊảǦǉƽậǉǦǇấǉǦǉươǃƼǦđồǃƼ……",
    ["有箭伤，腿骨折断……像是高处跌落的……"] = "ƞƚǦǉƾễǃǦǉƽươǃƼ,ǦǍươǃƼǦƸƽƁǃǦƷịǦƼƃǓ……ǦƼƾốǃƼǦǃƽưǦƷịǦǇơƾǦǉừǦǉǇƙǃǦƸƶǄǦǍǊốǃƼ……",
    ["墨山道的机关？断了根构件，里头还有些未燃尽的松脂……"] = "ƞơǦǆǊƶǃǦƸủƶǦƨặƸǦƮơǃǦĐạǄǦǈƶǄ?ǦƝịǦƼƃǓǦǂộǉǦǉƽƶǃƽǦƸấǊǦǀƾệǃ,ǦƷƙǃǦǉǇǄǃƼǦǋẫǃǦƸƛǃǦƸƽƕǉǦǉƖǃƼǦƸƽỉǦƸƽưƶǦƸƽƑǓǦƽếǉ……",
    ["若是修复，倒可借此稍微升起些高度，越过这山崖……"] = "ƩếǊǦǃƽưǦǉǊǦǅƽụƸ,ǦƸƚǦǉƽểǦǃƽờǦđƚǦǂƐǦƷƶǓǦǁƙǃǦǂộǉǦƸƽƕǉ,ǦǋượǉǦǆǊƶǦǈơǃǦǃƽƶƾǦǃƐǓ……",
    ["那人有些本事，结阵、机关、守城术，真是麻烦……你见他那鱼竿没？打起架来变化真多。"] = "ƦẻǦđƚǦƸƚǦƸƽƕǉǦƷảǃǦǈự,ǦǀếǉǦǉǇậǃ,ǦƸơǦǆǊƶǃ,ǦǉƽủǦǉƽƐǃƽǦǉƽǊậǉ,ǦǉƽậǉǦǁƐǦǅƽƾềǃǦǅƽứƸ……ǦƩƼươƾǦǉƽấǓǦƸƑƾǦƸầǃǦƸƁǊǦƸủƶǦƽắǃǦƸƽưƶ?ǦƦƽƾǦđƑǃƽǦǃƽƶǊǦƷƾếǃǦƽƚƶǦǉƽậǉǦǃƽƾềǊ.",
    [" 契丹兵卒"] = "ǦƦƽƾếǉǦĐƶǃǦƷƾǃƽǦǉốǉ",
    ["那老家伙的机关术，真有这么厉害？连将军都忌惮，真想看看那个“万人敌”到底是什么样的……"] = "ƞơǦǆǊƶǃǦǉƽǊậǉǦƸủƶǦǁƃǄǦƼƾƐǦđƚǦǉƽựƸǦǈựǦǁợƾǦƽạƾǦǋậǓǦǈƶǄ?ǦĐếǃǦǉướǃƼǦǆǊƁǃǦƸũǃƼǦǅƽảƾǦǀƾƙǃƼǦǤƘ,ǦǉƽậǉǦǂǊốǃǦǍƺǂǦǉƽửǦƸƑƾǦ\"ƱạǃǦƩƽƁǃǦĐịƸƽ\"ǦđƚǦǇốǉǦƸǊộƸǦǁƐǦǃƽưǦǉƽếǦǃƐǄ...",
    ["耶律花子"] = "ǝƶǦƧǊậǉǦƣǄƶǦǥử",
    ["那种金贵东西，是你能看的？守好你的门！"] = "ǥƽứǦǆǊƈǦƼƾƑǦđƚǦǂƐǦƽạǃƼǦǃƽưǦǃƼươƾǦƸũǃƼǦđƛƾǦǍƺǂǦǈƶǄ?ǦǥǇƇǃƼǦǀỹǦƸƑƾǦƸửƶǦƸủƶǦǃƼươƾǦđƾ!",
    ["萧恫"] = "ǥƾƙǊǦĐốǃƼ",
    ["“万人敌”……就是先前马屏山提到的……机关重器么？"] = "\"ƱạǃǦǃƽƁǃǦđịƸƽ\"……ǦƸƽƓǃƽǦǁƐǦƸơǦǆǊƶǃǦǉǇọǃƼǦǀƽƓǦǂƐǦǁƕƸǦǃƃǓǦƨƃǦƝƔǃƽǦƮơǃǦǃƽắƸǦǉớƾǦǈƶǄ?",
    ["嫌命多，就这么硬闯？"] = "ƞƽƙǦǂạǃƼǦǆǊƑǦǤƐƾǦƽƶǓǦǈƶǄǦǂƐǦǤƑǂǦǃƼạǃƽǦǈƶǃƼǦǃƽưǦǉƽế?",
    ["还说我呢，那你又为何跟来？"] = "ƞƛǃǦǃƚƾǦǉƶ,ǦǋậǓǦǈƶǄǦǃƼươƾǦǁạƾǦđƾǦǉƽƺǄ?",
    ["咳咳咳……想了想，我马屏山无权无势，名不见经传；那老东西却最擅沽名钓誉，很有些虚名。你若见了他，怕不是要站他那一边去？"] = "ƦƽụǦǀƽụǦǀƽụ……ǦǥƶǦǃƼƽĩǦǇồƾ,ǦƨƃǦƝƔǃƽǦƮơǃǦǉƶǦǋƇǦǆǊǓềǃǦǋƇǦǉƽế,ǦǤƶǃƽǦƷấǉǦǀƾếǃǦǀƾǃƽǦǉǇǊǓềǃ;ǦƸƛǃǦǁƃǄǦƼƾƐǦđƚǦǁạƾǦƼƾỏƾǦǃƽấǉǦǉǇƛǦƸƇǦǤƶǃƽǦƸƁǊǦǤự,ǦƸƚǦƸƽƕǉǦƽưǦǤƶǃƽ.ǦƩếǊǦǃƼươƾǦƼặǅǦƽắǃ,ǦǀƽƇǃƼǦƸƽừǃƼǦǁạƾǦđứǃƼǦǋềǦǅƽƓƶǦƽắǃǦǈƶǄ?",
    ["我站在道义一边。"] = "ǥƶǦđứǃƼǦǋềǦǅƽƓƶǦđạǄǦǃƼƽĩƶ.",
    ["哼，道义……你这人真好笑，我马屏山就站在你面前，也不肯说站在我这一边？"] = "ƣừ,ǦđạǄǦǃƼƽĩƶ……ǦǃƼươƾǦǉƽậǉǦǃựƸǦƸườƾ,ǦƨƃǦƝƔǃƽǦƮơǃǦǉƶǦđứǃƼǦǃƼƶǓǦǉǇướƸǦǂặǉǦǃƼươƾ,ǦǂƐǦǃƼươƾǦƸũǃƼǦǀƽƇǃƼǦƸƽịǊǦǃƚƾǦǁƐǦđứǃƼǦǋềǦǅƽƓƶǦǉƶǦǈƶǄ?",
    ["屏山兄不站在道义一边么？"] = "ƝƔǃƽǦƮơǃǦƽǊǓǃƽǦǀƽƇǃƼǦđứǃƼǦǋềǦǅƽƓƶǦđạǄǦǃƼƽĩƶǦǈƶǄ?",
    ["此处机关呈三才之阵，有三处枢纽控制着火油喷口，不能硬闯。"] = "ƞơǦǆǊƶǃǦǃơƾǦǃƐǓǦƷƐǓǦǉƽƺǄǦǥƶǂǦǥƐƾǦǥǇậǃ,ǦƸƚǦƷƶǦƸƽỗǦǍǊǦǃữǊǦǀƽốǃƼǦƸƽếǦǋƛƾǦǅƽǊǃǦƽỏƶǦǤǊ,ǦǀƽƇǃƼǦǉƽểǦǃƼạǃƽǦǈƶǃƼ.",
    ["有位书院弟子告诉我的，她原指望我进来能帮鹤……哼，真是个傻子。咳、咳咳……"] = "ƨộǉǦǋịǦđệǦǉửǦǉƽưǦǋƾệǃǦđƃǦǃƚƾǦƸƽǄǦǉƶǦƷƾếǉ,ǦƸƇǦǉƶǦǋốǃǦǉǇƇǃƼǦƸƽờǦǉƶǦǋƐǄǦđƁǓǦƼƾƕǅǦƣạƸ……Ǧƣừ,ǦǉƽậǉǦǁƐǦđồǦǃƼốƸ.ǦƦƽụ,ǦǀƽụǦǀƽụ……",
    ["虏人在此烧过狼毒草，屏住内息，不然这残烟会令你伤势更重。"] = "ƬǊƁǃǦƼƾặƸǦǉừǃƼǦđốǉǦƧƶǃƼǦĐộƸǦǥƽảǄǦởǦđƁǓ,ǦƽƃǓǦƷếǦǃộƾǦǉứƸ,ǦǃếǊǦǀƽƇǃƼǦǁƐǃǦǀƽƚƾǦǉƐǃǦǃƐǓǦǈẽǦǀƽƾếǃǦǉƽươǃƼǦǉƽếǦƸủƶǦǃƼươƾǦǉǇầǂǦǉǇọǃƼǦƽơǃ.",
    ["……解开三处枢纽，需要三枚书院弟子令。给你。"] = "……ǦƢƾảƾǦǀƽƶƾǦƷƶǦƸƽỗǦǍǊǦǃữǊǦƸầǃǦƸƚǦƷƶǦǉấǂǦĐệǦǉửǦǁệǃƽǦƸủƶǦǉƽưǦǋƾệǃ.ǦƞƽǄǦǃƼươƾǦǃƐǓ.",
    ["百草堂、天工坊、碑林，三处枢纽连环，需要依次解开。"] = "ƝƑƸƽǦǥƽảǄǦĐườǃƼ,ǦǥƽƾƙǃǦƞƇǃƼǦƫƽườǃƼ,ǦƝƾƶǦƧƁǂ,ǦƷƶǦƸƽỗǦǍǊǦǃữǊǦǃƐǓǦǁƾƙǃǦƽǄƐǃǦǋớƾǦǃƽƶǊ,ǦƸầǃǦǁầǃǦǁượǉǦƼƾảƾǦǀƽƶƾ.",
    ["隋瑛……她是谁？弟子令怎会在你手中？"] = "ǥƖǓǦƜǃƽ……ǦƞƇǦǉƶǦǁƐǦƶƾ?ǦƮƶǄǦĐệǦǉửǦǁệǃƽǦǁạƾǦởǦǉǇǄǃƼǦǉƶǓǦǃƼươƾ?",
    ["一个多管闲事的人……像你一样多管闲事，令人……讨厌。"] = "ƨộǉǦǀẻǦǉƽƓƸƽǦǆǊảǃǦƸƽǊǓệǃǦƷƶǄǦđồǃƼ……ǦƸũǃƼǦƼƾốǃƼǦǃƽưǦǃƼươƾǦǋậǓ,ǦǉƽậǉǦǀƽƾếǃǦǃƼườƾǦǉƶ……ǦƼƽƗǉǦƷỏ.",
    ["如何了？咳咳咳……那人最擅守备，又最狡猾，此地想必遍布机关，你莫要着了他的道。"] = "ǥƽếǦǃƐǄǦǇồƾ?ǦƦƽụǦǀƽụǦǀƽụ……ǦƦẻǦđƚǦƼƾỏƾǦǃƽấǉǦǁƐǦǉƽủǦƷị,ǦǁạƾǦǋƇǦƸƖǃƼǦƼƾảǄǦƽǄạǉ,ǦǃơƾǦǃƐǓǦắǉǦƽẳǃǦƼƾăǃƼǦđầǓǦƸơǦǆǊƶǃ,ǦǃƼươƾǦƸƽớǦđểǦǉǇƕǃƼǦǀếǦƸủƶǦƽắǃ.",
    ["我省得。"] = "ǥƶǦƷƾếǉǦǇồƾ.",
    ["变化之中藏有杀机，看来是为伏杀虏人的。"] = "ǥǇǄǃƼǦƷƾếǃǦƽƚƶǦẩǃǦǉƐǃƼǦǈƑǉǦƸơ,ǦǍƺǂǦǇƶǦǁƐǦđểǦǂƶƾǦǅƽụƸǦƼƾếǉǦǆǊƁǃǦƼƾặƸ.",
    ["急则出错，得看清变化再行事……"] = "ǝụƸǦǉốƸǦƷấǉǦđạǉ,ǦǅƽảƾǦǃƽƔǃǦǇƅǦƷƾếǃǦƽƚƶǦǇồƾǦǂớƾǦƽƐǃƽǦǈự……",
    ["嗯？此处似乎有诈……"] = "ƣử?ǦƞƽỗǦǃƐǓǦǤườǃƼǦǃƽưǦƸƚǦǉǇƑ……",
    ["种地先生、种地先生，我来看你啦！"] = "ƞƽủǃƼǦĐịƶǦǉƾƙǃǦǈƾǃƽ,ǦƞƽủǃƼǦĐịƶǦǉƾƙǃǦǈƾǃƽ,ǦƸǄǃǦđếǃǦǉƽăǂǦǃƼườƾǦǃƘ!",
    ["呦，小萝卜，是来看我，还是来看我的秧秧饼啊？"] = "Ồ,ǦǥƾểǊǦƧƶǦƝặƸ,ǦǁƐǦđếǃǦǉƽăǂǦǉƶ,ǦƽƶǓǦǁƐǦđếǃǦǉƽăǂǦǂƚǃǦƷƑǃƽǦǂầǂǦƸủƶǦǉƶǦđƁǓ?",
    ["刘思农"] = "ƧưǊǦǥưǦƩƇǃƼ",
    ["在炕头搁着呢，自己拿去吧！"] = "ĐểǦởǦđầǊǦƼƾườǃƼǦǁƛǦđấǓ,ǦǉựǦǇƶǦǂƐǦǁấǓǦđƾ!",
    ["种地先生，大姐头说过了腊八，她就要回曲阳去了！还有远哥、昉哥，也都要走！"] = "ƞƽủǃƼǦĐịƶǦǉƾƙǃǦǈƾǃƽ,ǦĐạƾǦǉỷǦđầǊǦǃƚƾǦǆǊƶǦǉếǉǦƧạǅǦƝƑǉǦǁƐǦǉỷǦấǓǦǅƽảƾǦǋềǦƦƽƕƸǦǝươǃƼǦǇồƾ!ǦƞƛǃǦƸƚǦƱƾễǃǦƸƶ,ǦƫƽưởǃƼǦƸƶǦƸũǃƼǦđềǊǦǅƽảƾǦđƾǦǃữƶ!",
    ["符姐姐说，他们学成了，叫什么“卒业”……要去别的地方生活呀，帮忙呀。种地先生，你也要走吗？你走了，我想吃秧秧饼怎么办呀……"] = "ƫƽƖǦǉỷǦǉỷǦǃƚƾǦƷọǃǦƽọǦƽọƸǦǉƽƐǃƽǦǇồƾ,ǦƼọƾǦǁƐǦƼƔǦǂƐǦ\"ǉốǉǦǃƼƽƾệǅ\"……ǦǅƽảƾǦđƾǦǃơƾǦǀƽƑƸǦǈƾǃƽǦǈốǃƼ,ǦƼƾƕǅǦđỡǦǃƼườƾǦǉƶ.ǦƞƽủǃƼǦĐịƶǦǉƾƙǃǦǈƾǃƽ,ǦǃƼườƾǦƸũǃƼǦđƾǦǈƶǄ?ǦƩƼườƾǦđƾǦǇồƾ,ǦƸǄǃǦǂǊốǃǦăǃǦƷƑǃƽǦǂầǂǦǉƽƔǦƷƾếǉǦǁƐǂǦǉƽếǦǃƐǄ……",
    ["我不走，不走，一把年纪了，像草扎了根，走不动啦……"] = "ǥƶǦǀƽƇǃƼǦđƾ,ǦǀƽƇǃƼǦđƾǦđƁǊ,ǦǉừǃƼǦǃƐǓǦǉǊổƾǦǇồƾ,ǦǃƽưǦǃƼọǃǦƸỏǦđƃǦƸắǂǦǇễ,ǦƸƽẳǃƼǦđƾǦđƁǊǦǃổƾǦǃữƶ……",
    ["可是你不走，别处的人就吃不到秧秧饼了，也怪可惜的……"] = "ƩƽưǃƼǦǃếǊǦǃƼườƾǦǀƽƇǃƼǦđƾ,ǦǃƼườƾǦǅƽươǃƼǦǀƽƑƸǦǈẽǦǀƽƇǃƼǦđượƸǦăǃǦƷƑǃƽǦǂầǂ,ǦƸũǃƼǦǉƽậǉǦđƑǃƼǦǉƾếƸ……",
    ["嘿，那让大家伙儿帮我把怎么做秧秧饼画下来，带出去，教别人，好不好呀？"] = "ƣƔ,ǦǋậǓǦđểǦǂọƾǦǃƼườƾǦƼƾƕǅǦǉƶǦǋẽǦǁạƾǦƸƑƸƽǦǁƐǂǦƷƑǃƽǦǂầǂ,ǦǂƶǃƼǦǇƶǦǃƼǄƐƾǦǤạǓǦƸƽǄǦǃƼườƾǦǀƽƑƸ,ǦđượƸǦǀƽƇǃƼǦǃƐǄ?",
    ["好欸！"] = "ƣƶǓǦǆǊƑǦạ!",
    ["那小萝卜何时也来书院，帮我们一起画呀？"] = "ƱậǓǦǥƾểǊǦƧƶǦƝặƸǦǀƽƾǦǃƐǄǦđếǃǦǉƽưǦǋƾệǃǦƼƾƕǅǦƸƽƕǃƼǦǉƶǦƸƖǃƼǦǋẽǦđƁǓ?",
    ["唔……等我吃完这个……明天，明天再来学吧！"] = "Ưǂ……ǦđợƾǦƸǄǃǦăǃǦǍǄǃƼǦƸƑƾǦǃƐǓǦđƃ……ǦƩƼƐǓǦǂƶƾ,ǦǃƼƐǓǦǂƶƾǦƸǄǃǦǁạƾǦǉớƾǦƽọƸǦǃƽƗ!",
    ["不愧是墨山道的机关偃偶，已经受损，还这样厉害……"] = "ƦƽƇǃƼǦƽổǦǁƐǦƴểǃǦǃƼẫǊǦƸơǦǆǊƶǃǦƸủƶǦƨặƸǦƮơǃǦĐạǄ,ǦđƃǦƽưǦƽạƾǦǂƐǦǋẫǃǦǁợƾǦƽạƾǦǉƽếǦǃƐǓ……",
    ["只是这偃偶，怎么说也算不上“万人敌”，那“重器”应该是指别的？"] = "ƞƚǦđƾềǊǦƴểǃǦǃƼẫǊǦǃƐǓǦǤƖǦǉƽếǦǃƐǄǦƸũǃƼǦǀƽƇǃƼǦđượƸǦƸǄƾǦǁƐǦ\"ƱạǃǦǃƽƁǃǦđịƸƽ\",ǦƸƽẳǃƼǦǁẽǦ\"ǉǇọǃƼǦǀƽƓ\"ǦǀƾƶǦǁƐǦƸƽỉǦǉƽứǦǀƽƑƸ?",
    ["看见没！都看见没！小爷今天连胜三场！"] = "ǥƽấǓǦƸƽưƶ!ǦǥƽấǓǦƸảǦƸƽưƶ!ǦǥƾểǊǦƼƾƶǦƽƇǂǦǃƶǓǦǉƽắǃƼǦǁƾƙǃǦǉƾếǅǦƷƶǦǉǇậǃ!",
    ["罗成武"] = "ƧƶǦǥƽƐǃƽǦƱũ",
    ["哇，成武哥好厉害！"] = "ƪƶ,ǦǥƽƐǃƽǦƱũǦƸƶǦƼƾỏƾǦǆǊƑ!",
    ["哟，终于打赢人家刘小妹从没输过的初等机关偃偶了，可喜和贺！"] = "Ồ,ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦǉƽắǃƼǦđượƸǦƴểǃǦǃƼẫǊǦƸơǦǆǊƶǃǦǈơǦđẳǃƼǦƸƽưƶǦǉừǃƼǦǉƽấǉǦƷạƾǦƸủƶǦƧưǊǦǥƾểǊǦƨǊộƾǦǇồƾ,ǦǀƽảǦƽỉǦǀƽảǦƽạ!",
    ["秦远"] = "ǥầǃǦƱƾễǃ",
    ["穷酸鬼懂什么？！鹤先生说了，大道至简，知道什么意思吗？就是说，越基础的偃偶越难打！"] = "ƞƑƾǦđồǦǃƼƽƘǄǦǀƾếǉǦǍƑƸǦǉƽƔǦƷƾếǉǦƸƑƾǦƼƔ?!ǦƣạƸǦǉƾƙǃǦǈƾǃƽǦđƃǦǃƚƾǦǇồƾ,ǦđạƾǦđạǄǦƸƽƓǦƼƾảǃ,ǦƷƾếǉǦǃƼƽĩƶǦǁƐǦƼƔǦǀƽƇǃƼ?ǦƩƼƽĩƶǦǁƐǦƴểǃǦǃƼẫǊǦƸƐǃƼǦƸơǦƷảǃǦǉƽƔǦƸƐǃƼǦǀƽƚǦđƑǃƽ!",
    ["哎呀，一个偃偶胜过三个契丹人，我连打三个，那就是……打了十三个契丹人！哼，来日去战场上叫大伙瞧瞧，罗大将军杀敌勇，罗小将军也不孬！"] = "ÁƾǦƸƽƐ,ǦǂộǉǦƸǄǃǦƴểǃǦǃƼẫǊǦǉƽắǃƼǦđượƸǦƷƶǦǃƼườƾǦƦƽƾếǉǦĐƶǃ,ǦǉƶǦđƑǃƽǦǉƽắǃƼǦƷƶǦƸǄǃ,ǦǉứƸǦǁƐ……ǦđƑǃƽǦǉƽắǃƼǦǂườƾǦƷƶǦǃƼườƾǦƦƽƾếǉǦĐƶǃ!Ǧƣừ,ǦǃƼƐǓǦǈƶǊǦǇƶǦƸƽƾếǃǦǉǇườǃƼǦƸƽǄǦǂọƾǦǃƼườƾǦǍƺǂ,ǦƧƶǦđạƾǦǉướǃƼǦǆǊƁǃǦǈƑǉǦđịƸƽǦǤũǃƼǦǂƃǃƽ,ǦƧƶǦǉƾểǊǦǉướǃƼǦǆǊƁǃǦƸũǃƼǦƸƽẳǃƼǦǀƗǂǦƸạǃƽ!",
    ["三、三……成武哥，好像是九个吧？"] = "ƝƶǦǁầǃǦƷƶ……ǦǥƽƐǃƽǦƱũǦƸƶ,ǦƽƔǃƽǦǃƽưǦǁƐǦƸƽƓǃǦǃƼườƾǦƸƽứǦǃƽỉ?",
    ["小萝卜，远哥今天教你两句诗：金缕玉衣裹朽木，腹中空有草莽声！"] = "ǥƾểǊǦƧƶǦƝặƸ,ǦƱƾễǃǦƸƶǦƽƇǂǦǃƶǓǦǤạǓǦƺǂǦƽƶƾǦƸƁǊǦǉƽơ:ǦƦƾǂǦǁũǦǃƼọƸǦǓǦǀƽỏƶǦƽủǦǂộƸ,ǦǅƽƕƸǦǉǇǊǃƼǦǀƽƇǃƼǦƽữǊǦǉƽảǄǦǂƃǃƼǦǉƽƶǃƽ!",
    ["穷酸鬼！别以为我听不出来你在骂我，是不是想挨揍了！"] = "ĐồǦǃƼƽƘǄǦǀƾếǉǦǍƑƸ!ǦĐừǃƼǦǉưởǃƼǦǉƶǦǀƽƇǃƼǦǃƼƽƺǦǇƶǦǃƼươƾǦđƶǃƼǦǂắǃƼǦǉƶ,ǦƸƚǦǅƽảƾǦǂǊốǃǦăǃǦđƛǃǦǇồƾǦǀƽƇǃƼ!",
    ["臭纨绔！休要仗势欺人！"] = "ǥƙǃǦƽǄƐǃǦǀƽốǦǉƽốƾǦǉƽƶ!ǦĐừǃƼǦƸƚǦƸậǓǦǉƽếǦƽƾếǅǦǃƼườƾ!",
    ["穷酸鬼！"] = "ĐồǦǃƼƽƘǄǦǀƾếǉǦǍƑƸ!",
    ["臭纨绔！"] = "ǥƙǃǦƽǄƐǃǦǀƽốǦǉƽốƾǦǉƽƶ!",
    ["小妹，小萝卜，磨蹭什么呢？快来吃思农先生的豆菜饭，下月出了山，想吃也没了！"] = "ǥƾểǊǦƨǊộƾ,ǦǥƾểǊǦƧƶǦƝặƸ,ǦǁềǦǂềǦƸƑƾǦƼƔǦđƚ?ǦƨƶǊǦǁạƾǦđƁǓǦăǃǦƸơǂǦđậǊǦƸủƶǦǥưǦƩƇǃƼǦǉƾƙǃǦǈƾǃƽ,ǦǉƽƑǃƼǦǈƶǊǦǇƶǦǀƽỏƾǦǃƕƾ,ǦǂǊốǃǦăǃǦƸũǃƼǦǀƽƇǃƼǦƸƛǃǦǃữƶǦđƁǊ!",
    ["符晓"] = "ƫƽƖǦƣƾểǊ",
    ["符姐姐，你快看大姐头！她刻了好大一篇字！"] = "ƫƽƖǦǉỷǦǉỷ,ǦǉỷǦǂƶǊǦǃƽƔǃǦđạƾǦǉỷǦđầǊǦǀƔƶ!ǦǥỷǦấǓǦǀƽắƸǦǂộǉǦƷƐƾǦǋăǃǦǤƐƾǦǁắǂ!",
    ["封龙山颂……你这又搞得什么名堂？"] = "ƫƽǄǃƼǦƧǄǃƼǦƮơǃǦǥụǃƼ……ǦǃƼươƾǦǁạƾǦƷƐǓǦǇƶǦǉǇƛǦƼƔǦǃữƶǦđƁǓ?",
    ["嘿嘿，怕我下山的时候老头回不来，给他留点惊喜！怎么样，咱这文采，这刀法，还可以吧？"] = "ƣƔǦƽƔ,ǦǈợǦǁƕƸǦǂǊộƾǦǍǊốǃƼǦǃƕƾǦǁƃǄǦđầǊǦǉửǦǋẫǃǦƸƽưƶǦǋề,ǦǃƙǃǦđểǦǁạƾǦƸƽǄǦǃƼườƾǦƸƽƕǉǦǀƾǃƽǦƽỷ!ǦǥƽếǦǃƐǄ,ǦǋăǃǦƸƽươǃƼǦǃƐǓ,ǦđƶǄǦǅƽƑǅǦǃƐǓǦƸủƶǦǉƶ,ǦƸũǃƼǦđượƸǦđấǓǦƸƽứ?",
    ["刘小妹"] = "ƧưǊǦǥƾểǊǦƨǊộƾ",
    ["很可以！谁能想这马匪的刀，也能用来刻碑立传了呢。"] = "ƭấǉǦđượƸ!ǦƜƾǦǂƐǦǃƼờǦđƶǄǦƸủƶǦǂƃǦǅƽỉ,ǦƸũǃƼǦƸƚǦǉƽểǦǤƖǃƼǦđểǦǀƽắƸǦƷƾƶǦǁậǅǦǉǇǊǓềǃǦƸơǦƸƽứ.",
    ["欸，你想好了吗，回去之后打算干什么，还打劫？"] = "Ê,ǦǂǊộƾǦǃƼƽĩǦǀỹǦƸƽưƶ,ǦǈƶǊǦǀƽƾǦǋềǦđịǃƽǦǁƐǂǦƼƔ,ǦǁạƾǦđƾǦđƑǃƽǦƸướǅǦƐ?",
    ["打啊，怎么不打？不过啊，以前打的是倒霉蛋，现在这刀既认字，又挑食，除了伥鬼恶人，不爱吃了！"] = "ĐƑǃƽǦƸƽứ,ǦǈƶǄǦǁạƾǦǀƽƇǃƼ?ǦƞƚǦđƾềǊǦǃƽƶ,ǦǉǇướƸǦǀƾƶǦđƑǃƽǦǂấǓǦǀẻǦđƺǃǦđủƾ,ǦƼƾờǦǉƽƶǃƽǦđƶǄǦǃƐǓǦǋừƶǦƷƾếǉǦƸƽữ,ǦǁạƾǦƸƛǃǦǀƗǃǦăǃ,ǦǃƼǄƐƾǦǁũǦǈƕƸǦǈƾǃƽǦƑƸǦǃƽƁǃǦǇƶ,ǦǃƚǦǀƽƇǃƼǦǉƽƘǂǦăǃǦǃữƶ!",
    ["啧啧，跟刚来的时候真是不一样了。"] = "ƞƽậƸǦƸƽậƸ,ǦǉƽậǉǦǁƐǦǀƽƑƸǦǍƶǦǈǄǦǋớƾǦǁƕƸǦǂớƾǦǉớƾ.",
    ["我知道，院主教过，这叫：玉不琢，不成器；人不学，不知道。"] = "ƨǊộƾǦƷƾếǉǦǂƐ,ǦƱƾệǃǦƸƽủǦǉừǃƼǦǤạǓ,ǦđƁǓǦƼọƾǦǁƐ:ǦƩƼọƸǦƷấǉǦǉǇƑƸ,ǦƷấǉǦǉƽƐǃƽǦǀƽƓ;ǦƩƽƁǃǦƷấǉǦƽọƸ,ǦƷấǉǦǉǇƾǦđạǄ.",
    ["你知道？你知道还天天躲懒，还不快正经来书院念书！"] = "ƩƼươƾǦǂƐǦƸũǃƼǦƷƾếǉ?ǦƝƾếǉǦǂƐǦƸƛǃǦǃƼƐǓǦǃƼƐǓǦǁườƾǦƷƾếǃƼ,ǦǀƽƇǃƼǦǂƶǊǦǂƶǊǦǃƼƽƾƙǂǦǉƕƸǦǉớƾǦǉƽưǦǋƾệǃǦđọƸǦǈƑƸƽǦđƾ!",
    ["明天，哦不，过了年就来！冬天日头都短嘞，春天才好念书嘛。"] = "ƩƼƐǓǦǂƶƾ,ǦƐǦǀƽƇǃƼ,ǦǆǊƶǦǃăǂǦǂớƾǦǂǊộƾǦǈẽǦǉớƾ!ǦƨƖƶǦđƇǃƼǦǃƼƐǓǦǃƼắǃǦǁắǂ,ǦǂƖƶǦǍǊƁǃǦǂớƾǦǁƐǦǁƕƸǦǉốǉǦđểǦđọƸǦǈƑƸƽǦǂƐ.",
    ["这书院里教得杂，收徒的路数……和之前听到的鹤长老的传闻，倒是对得上。"] = "ǥƽưǦǋƾệǃǦǃƐǓǦǤạǓǦǤỗǦǉạǅǦǁǄạǃ,ǦǁộǦǈốǦǉƽǊǦđồǦđệ……ǦǈǄǦǋớƾǦǁờƾǦđồǃǦǋềǦƣạƸǦǉǇưởǃƼǦǁƃǄǦǉǇướƸǦđƁǓ,ǦǆǊảǦǁƐǦǉǇƖǃƼǦǀƽớǅ.",
    ["哼，收徒的路数？他笼络人心的手段，又何止于此……毒烟越来越重了，我们往前走吧。"] = "ƣừ,ǦǁộǦǈốǦǉƽǊǦđồǦđệǦǈƶǄ?ǦǥƽủǦđǄạǃǦǁũǃƼǦđǄạǃǦǁƛǃƼǦǃƼườƾǦƸủƶǦǁƃǄ,ǦđƁǊǦƸƽỉǦƸƚǦƷấǓǦǃƽƾƙǊ……ǦƦƽƚƾǦđộƸǦǃƼƐǓǦƸƐǃƼǦǃồǃƼǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦđƾǦǉƾếǅǦǉƽƇƾ.",
    ["你这边怎样，都装好了吗？"] = "ƝƙǃǦǃƼươƾǦǉƽếǦǃƐǄǦǇồƾ,ǦđƃǦǉƽǊǦǍếǅǦǍǄǃƼǦƸảǦƸƽưƶ?",
    ["梁望"] = "ƧươǃƼǦƱọǃƼ",
    ["你怎在这儿愣着？关先生还没走远呢，快收拾东西跟上！"] = "ƩƼươƾǦǈƶǄǦƸƛǃǦǃƼẩǃǦǇƶǦđƚ?ǦƬǊƶǃǦǉƾƙǃǦǈƾǃƽǦǋẫǃǦƸƽưƶǦđƾǦǍƶǦđƁǊ,ǦǂƶǊǦǉƽǊǦǤọǃǦđồǦđạƸǦđǊổƾǦǉƽƺǄ!",
    ["别怕，去南边玩玩，开了春再回来。"] = "ĐừǃƼǦǈợ,ǦđƾǦǋềǦǅƽƓƶǦƩƶǂǦƸƽơƾǦǂộǉǦƸƽǊǓếǃ,ǦǈƶǃƼǦǍǊƁǃǦǁạƾǦǋề.",
    ["院中可挪动的机关还有多少？"] = "ƞơǦǆǊƶǃǦƸƚǦǉƽểǦǤƾǦđộǃƼǦǉǇǄǃƼǦǋƾệǃǦƸƛǃǦƷƶǄǦǃƽƾƙǊ?",
    ["弩机八架，手甲廿三，偃偶十六，已全部整理妥当，等在门外。"] = "ƩỗǦƸơǦǉƑǂǦƼƾƑ,ǦǉƽủǦƼƾƑǅǦƽƶƾǦǂươƾǦƷƶ,ǦǓểǃǦǃƼẫǊǦǂườƾǦǈƑǊ,ǦđƃǦǉǄƐǃǦƷộǦƸƽỉǃƽǦǁƈǦǉƽỏƶǦđƑǃƼ,ǦđƶǃƼǦđợƾǦǃƼǄƐƾǦƸửƶ.",
    ["唐文耀"] = "ĐườǃƼǦƱăǃǦǝƾệǊ",
    ["还未撤走的老幼杂工，要尽快启程。"] = "ƩƽữǃƼǦǃƼườƾǦƼƾƐǦǉǇẻǦǋƐǦǉạǅǦǤịƸƽǦƸƽưƶǦǇƕǉǦđƾ,ǦƸầǃǦǅƽảƾǦǀƽởƾǦƽƐǃƽǦǈớǂ.",
    ["人数已清点完毕，干粮行囊并弟子们的书稿也都已装车，马上就出发。"] = "ƩƽƁǃǦǈốǦđƃǦǀƾểǂǦǀƙǦǍǄǃƼ,ǦǁươǃƼǦǀƽƇǦƽƐǃƽǦǃƶǃƼǦƸƖǃƼǦƷảǃǦǉƽảǄǦƸủƶǦđệǦǉửǦƸũǃƼǦđƃǦƸƽấǉǦǁƙǃǦǍƺ,ǦǁậǅǦǉứƸǦǍǊấǉǦǅƽƑǉ.",
    ["符晓，你这边呢？"] = "ƫƽƖǦƣƾểǊ,ǦƷƙǃǦǅƽƓƶǦǂǊộƾǦǉƽƔǦǈƶǄ?",
    ["食饮清点了两轮，柴炭、纸墨、送信木鸢……也都确认了数目。六名布阵守院的弟子也已排好班次。"] = "ƧươǃƼǦǉƽựƸǦǃướƸǦǊốǃƼǦđƃǦǀƾểǂǦǀƙǦƽƶƾǦǁượǉ;ǦƸủƾǦǉƽƶǃ,ǦƼƾấǓǦǂựƸ,ǦǂộƸǦǤƾƙǊǦǉǇǊǓềǃǦǉƾǃ……ǦƸũǃƼǦđƃǦǍƑƸǦǃƽậǃǦǈốǦǁượǃƼ.ǦƮƑǊǦđệǦǉửǦƷƐǓǦǉǇậǃǦǉƽủǦǋƾệǃǦƸũǃƼǦđƃǦǈắǅǦǍếǅǦƸƶǦǉǇựƸǦǍǄǃƼ.",
    ["诸位，该出发了，请随我共赴中渡桥！"] = "ƞƽưǦǋị,ǦđếǃǦǁƕƸǦǀƽởƾǦƽƐǃƽǦǇồƾ,ǦǍƾǃǦǉƽƺǄǦǉƶǦƸƖǃƼǦǉớƾǦǥǇǊǃƼǦĐộǦƦƾềǊ!",
    ["好，准备出发！"] = "ĐượƸ,ǦƸƽǊẩǃǦƷịǦǍǊấǉǦǅƽƑǉ!",
    ["赴中渡桥！"] = "ǥớƾǦǥǇǊǃƼǦĐộǦƦƾềǊ!",
    ["桓云"] = "ƣǄƐǃǦƱƁǃ",
    ["鹤！"] = "ƣạƸ!",
    ["关山越"] = "ƬǊƶǃǦƮơǃǦƱƾệǉ",
    ["关师兄？你不是去护送乡邻了吗，怎么……"] = "ƬǊƶǃǦǈưǦƽǊǓǃƽ?ǦƣǊǓǃƽǦǀƽƇǃƼǦǅƽảƾǦđƾǦƽộǦǉốǃƼǦǍƚǂǦƼƾềǃƼǦǇồƾǦǈƶǄ,ǦǉƽếǦǃƐǄǦǁạƾ……",
    ["李昉隋瑛已带他们过丰岁道往南去了，我怕你们缺人手，回来帮忙。"] = "ƧƈǦƫƽưởǃƼǦǋƐǦǥƖǓǦƜǃƽǦđƃǦđưƶǦƽọǦǆǊƶǦƫƽǄǃƼǦǥǊếǦĐạǄǦđƾǦǋềǦǅƽƓƶǦƩƶǂǦǇồƾ,ǦǉƶǦǈợǦƸƑƸǦđệǦǉƽƾếǊǦǃƽƁǃǦǉƽủǦǃƙǃǦǆǊƶǓǦǁạƾǦƼƾƕǅǦǂộǉǦǉƶǓ.",
    ["我行至山腰，看到虏人已经四面合围，正往山上赶来，咱们怕是无路可出了。"] = "ǥƶǦđƾǦđếǃǦǈườǃǦǃƕƾ,ǦǉƽấǓǦǆǊƁǃǦƼƾặƸǦđƃǦǋƁǓǦǀƽốǃǦƷốǃǦǅƽƓƶ,ǦđƶǃƼǦǀƗǄǦǁƙǃǦǃƕƾ,ǦƸƽƕǃƼǦǉƶǦƺǦǁƐǦǀƽƇǃƼǦƸƛǃǦđườǃƼǦǇƶǦǃữƶǦǇồƾ.",
    ["……有多少人？"] = "……ǦƞƚǦƷƶǄǦǃƽƾƙǊǦǃƼườƾ?",
    ["数千之多，想是绕过中渡桥，直取书院而来的。"] = "ƫƽảƾǦđếǃǦǂấǓǦǃƼƐǃ,ǦƸƽắƸǦǁƐǦƸƽƕǃƼǦǋƛǃƼǦǆǊƶǦǥǇǊǃƼǦĐộǦƦƾềǊ,ǦǃƽắǂǦǉƽẳǃƼǦǉƽưǦǋƾệǃǦǂƐǦǉớƾ.",
    ["数千人……虏人倒是看得起咱们。"] = "ƨấǓǦǃƼƐǃǦǃƼườƾ……ǦǆǊƁǃǦƼƾặƸǦǆǊảǦǁƐǦƸǄƾǦǉǇọǃƼǦƸƽƕǃƼǦǉƶ.",
    ["撤回内院，布机关，守！"] = "ƭƕǉǦǋềǦǃộƾǦǋƾệǃ,ǦƷƐǓǦƸơǦǆǊƶǃ,Ǧǉƽủ!",
    ["文耀，遣木鸢给林险生和启昭去信，我们只要坚守到中渡桥脱困，他们定会回援。"] = "ƱăǃǦǝƾệǊ,ǦǉƽảǦǂộƸǦǤƾƙǊǦƼửƾǦǉƽưǦƸƽǄǦƧƁǂǦƣƾểǂǦƮƾǃƽǦǋƐǦƦƽảƾǦƞƽƾƙǊ,ǦƸƽƕǃƼǦǉƶǦƸƽỉǦƸầǃǦǀƾƙǃǦǉƽủǦƸƽǄǦǉớƾǦǀƽƾǦǥǇǊǃƼǦĐộǦƦƾềǊǦǉƽǄƑǉǦǋƁǓ,ǦƽọǦǃƽấǉǦđịǃƽǦǈẽǦǋềǦứǃƼǦƸứǊ.",
    ["契丹立国北疆，强兵壮马，礼贤下士，尚德尚义。今闻书院盛名，愿虚位以待，厚赏以酬……"] = "ƦƽƾếǉǦĐƶǃǦǁậǅǦǆǊốƸǦởǦƝắƸǦƞươǃƼ,ǦƷƾǃƽǦƸườǃƼǦǂƃǦǉǇƑǃƼ,ǦǁễǦƽƾềǃǦƽạǦǈĩ,ǦǉƽượǃƼǦđứƸǦǉƽượǃƼǦǃƼƽĩƶ.ǦƩƶǓǦǃƼƽƺǦǤƶǃƽǦǉƾếǃƼǦǉƽưǦǋƾệǃ,ǦǃƼǊǓệǃǦđểǦǉǇốǃƼǦǋịǦǉǇƓǦƸƽờǦđƚǃ,ǦǉǇọǃƼǦǉƽưởǃƼǦƽậǊǦƽĩǃƽ……",
    ["......哎哟！"] = "......ǦÁƾǦƸƽƐ!",
    ["鹤院主，我乃契丹惕隐耶律屋质。"] = "ƣạƸǦǋƾệǃǦƸƽủ,ǦǉƶǦǁƐǦǝịƸƽǦẨǃǦƦƽƾếǉǦĐƶǃ,ǦǝƶǦƧǊậǉǦỐƸǦƞƽấǉ.",
    ["耶律屋质"] = "ǝƶǦƧǊậǉǦỐƸǦƞƽấǉ",
    ["曾闻院主高论：“染于苍则苍，故凡为丝者，皆慎而染之”深契吾心。"] = "ǥừǃƼǦǃƼƽƺǦƸƶǄǦǁǊậǃǦƸủƶǦǋƾệǃǦƸƽủ:Ǧ\"ƩƽǊộǂǦǍƶǃƽǦǉƽƔǦǉƽƐǃƽǦǍƶǃƽ,ǦƸƽǄǦǃƙǃǦǅƽƐǂǦǁƐǦǉơ,ǦđềǊǦǅƽảƾǦǉƽậǃǦǉǇọǃƼǦǀƽƾǦǃƽǊộǂ\",ǦǉƽậǉǦǈƁǊǦǈắƸǦƽợǅǦǁƛǃƼǦǉƶ.",
    ["唯有一言不明，特来请教。"] = "ǝǊǓǦƸƽỉǦƸƚǦǂộǉǦǁờƾǦƸƽưƶǦǇƅ,ǦđặƸǦƷƾệǉǦǉớƾǦđƁǓǦǉƽỉǃƽǦƼƾƑǄ.",
    ["尔所请何事？"] = "ƩƼươƾǦǂǊốǃǦǉƽỉǃƽǦƼƾƑǄǦƸƽǊǓệǃǦƼƔ?",
    ["晋，缺粮、少兵、百姓苦矣；而我契丹，主明、将勇、兵强。"] = "ǥấǃ,ǦǉƽƾếǊǦǁươǃƼ,ǦǉƽƾếǊǦƷƾǃƽ,ǦƷƑƸƽǦǉƓǃƽǦǀƽổǦƸựƸ;ǦǂƐǦƦƽƾếǉǦĐƶǃǦǉƶ,ǦƸƽủǦǈƑǃƼ,ǦǉướǃƼǦǤũǃƼ,ǦƷƾǃƽǦƸườǃƼ.",
    ["文耀，带人把周遭弩机都移到近前。"] = "ƱăǃǦǝƾệǊ,ǦđƺǂǦǃƼườƾǦǤờƾǦƽếǉǦǃỗǦƸơǦǍǊǃƼǦǆǊƶǃƽǦǉớƾǦƼầǃǦđƁǓ.",
    ["成武，去把水缸装满。"] = "ǥƽƐǃƽǦƱũ,ǦđƾǦđổǦđầǓǦǃướƸǦǋƐǄǦƸƑƸǦǁǊǦƸƽậǊ.",
    ["小妹，去把水车、纺车、能动的机关都启动起来。"] = "ǥƾểǊǦƨǊộƾ,ǦđƾǦǀƽởƾǦđộǃƼǦƽếǉǦƼǊồǃƼǦǃướƸ,ǦǍƺǦǤệǉǦǋƐǦƸƑƸǦƸơǦǆǊƶǃǦƸƚǦǉƽểǦƸửǦđộǃƼǦđƾ.",
    ["此诚为民乎？"] = "ĐƁǓǦǉƽựƸǦǈựǦǁƐǦǋƔǦǤƁǃǦǈƶǄ?",
    ["不若院主示天下以理：于此书院，广纳契丹宗室子弟；"] = "ƞƽƾǦƷằǃƼǦǋƾệǃǦƸƽủǦƽƃǓǦǉƽịǦƽƾệǃǦƸƑƾǦǁƈǦǋớƾǦǉƽƾƙǃǦƽạ:ǦǥạƾǦǉƽưǦǋƾệǃǦǃƐǓ,ǦǇộǃƼǦƸửƶǦđƚǃǦǃƽậǃǦǉửǦđệǦǉƇǃƼǦǉƽấǉǦƦƽƾếǉǦĐƶǃ;",
    ["凡百家经史、韬略机关，咸作契丹文字；"] = "ƫƽƐǂǦǁƐǦǀƾǃƽǦǈửǦƷƑƸƽǦƼƾƶ,ǦǉƽƶǄǦǁượƸǦƸơǦǆǊƶǃ,ǦǉƽảǓǦđềǊǦǋƾếǉǦƷằǃƼǦǋăǃǦǉựǦƦƽƾếǉǦĐƶǃ;",
    ["更邀有志之士共奉明主，化干戈为玉帛，岂不美事？"] = "ƧạƾǦǂờƾǦǃƽữǃƼǦƷậƸǦƸƽƓǦǈĩǦƸƖǃƼǦǅƽụǃƼǦǈựǦǂƾǃƽǦƸƽủ,ǦƽƚƶǦƸƶǃǦǆǊƶǦǉƽƐǃƽǦǃƼọƸǦƷạƸƽ,ǦƸƽẳǃƼǦǅƽảƾǦǁƐǦƸƽǊǓệǃǦǉốǉǦđẹǅǦǈƶǄ?",
    ["我曾听闻，世间有兽，常伪作亲善，伏于浅滩。"] = "ǥƶǦǉừǃƼǦǃƼƽƺǦǃƚƾ,ǦǉƽếǦƼƾƶǃǦƸƚǦǁǄƐƾǦǉƽƕ,ǦǉƽườǃƼǦƼƾảǦƷộǦǉƽƁǃǦǉƽƾệǃ,ǦǅƽụƸǦǈẵǃǦǃơƾǦƷƃƾǦƸạǃ.",
    ["趁人不备便屠戮掠食，及至血足肉饱，又惺惺作态，泪落如珠。"] = "ǥƽừƶǦǁƕƸǦǃƼườƾǦǉƶǦǀƽƇǃƼǦǅƽƛǃƼǦƷịǦǁƾềǃǦđồǦǉểǦǈăǃǦǂồƾ,ǦđợƾǦđếǃǦǀƽƾǦǂƑǊǦǉƽịǉǦǃǄǦǃƙ,ǦǁạƾǦƷƐǓǦǇƶǦǋẻǦđƶǊǦǍƚǉ,ǦǃướƸǦǂắǉǦǇơƾǦǃƽưǦƽạǉǦƸƽƁǊ.",
    ["言，太平为贵，玉帛为美，当惜之哉！"] = "ƩƚƾǦǇằǃƼ,ǦǉƽƑƾǦƷƔǃƽǦǁƐǦǆǊƈ,ǦǃƼọƸǦƷạƸƽǦǁƐǦđẹǅ,ǦǃƙǃǦƷƾếǉǦǉǇƁǃǦǉǇọǃƼǦǉƽƶǓ!",
    ["却不知，既犯我土，何言太平！既起干戈，何来玉帛！"] = "ƩƽưǃƼǦǀƽƇǃƼǦƷƾếǉǦǇằǃƼ,ǦđƃǦǍƁǂǦǅƽạǂǦđấǉǦǉƶ,ǦǈƶǄǦǤƑǂǦƷƐǃǦƸƽǊǓệǃǦǉƽƑƾǦƷƔǃƽ!ǦĐƃǦǤấǓǦǁƙǃǦƸƶǃǦǆǊƶ,ǦǁấǓǦđƁǊǦǇƶǦǃƼọƸǦƷạƸƽ!",
    ["至于什么“广纳契丹宗室子弟”，我弟子有话要说。"] = "ƞƛǃǦǃƽưǦƸƑƾǦƸƽǊǓệǃǦ\"ǇộǃƼǦǃƽậǃǦǉửǦđệǦǉƇǃƼǦǉƽấǉǦƦƽƾếǉǦĐƶǃ\",ǦđệǦǉửǦƸủƶǦǉƶǦƸƚǦǁờƾǦǂǊốǃǦǃƚƾ.",
    ["大家各到临近机关，听我指令。"] = "ƨọƾǦǃƼườƾǦǋềǦǋịǦǉǇƓǦƸơǦǆǊƶǃǦƼầǃǦǃƽấǉ,ǦǃƼƽƺǦǁệǃƽǦƸủƶǦǉƶ.",
    ["成武，我教你一句，大点声喊……"] = "ǥƽƐǃƽǦƱũ,ǦǉƶǦǤạǓǦǃƼươƾǦǂộǉǦƸƁǊ,ǦƽƗǉǦǉƽậǉǦǉǄǦǁƙǃ……",
    ["少——放——屁——咱——不——收——虏——狗——"] = "ƝỚǥ——ƫƣÓƩƢ——ǥƣÍ——ǥƜ——ƦƣƆƩƢ——ǥƣǕ——ƞƣÓ——ƢƤẶƞ——",
    ["千机——齐发！"] = "ǥƽƾƙǃǦƞơ——ǦǥềǦǅƽƑǉ!",
    ["此地已设机关重器“千机万象”，乃我多年心血所成。"] = "ƩơƾǦđƁǓǦđƃǦđặǉǦƸơǦǆǊƶǃǦǉǇọǃƼǦǀƽƓǦ\"ǥƽƾƙǃǦƞơǦƱạǃǦǥượǃƼ\",ǦǁƐǦǉƁǂǦƽǊǓếǉǦǃƽƾềǊǦǃăǂǦƸủƶǦǉƶǦǉạǄǦǉƽƐǃƽ.",
    ["千机万象？"] = "ǥƽƾƙǃǦƞơǦƱạǃǦǥượǃƼ?",
    ["尔等既来请学，自当受此大礼！"] = "ƞƑƸǦǃƼươƾǦđƃǦǉớƾǦǉƽỉǃƽǦƽọƸ,ǦǉựǦǃƽƾƙǃǦǅƽảƾǦǃƽậǃǦđạƾǦǁễǦǃƐǓ!",
    ["什么千机？"] = "ǥƽƾƙǃǦƸơǦƼƔǦƸơ?",
    ["是机关术！中原人的妖术，一人可敌万人！"] = "ƧƐǦƸơǦǆǊƶǃǦǉƽǊậǉ!ǦƴƙǊǦǉƽǊậǉǦƸủƶǦǃƼườƾǦǥǇǊǃƼǦƩƼǊǓƙǃ,ǦǂộǉǦǃƼườƾǦƸƚǦǉƽểǦđịƸƽǦǋạǃǦǃƼườƾ!",
    ["怕什么！杀进去！"] = "ƮợǦƸƑƾǦƼƔ!ǦƢƾếǉǦǋƐǄǦƸƽǄǦǉƶ!",
    ["千机万象……哼，不急，那咱们就熬一熬！"] = "ǥƽƾƙǃǦƞơǦƱạǃǦǥượǃƼ……Ǧƣừ,ǦǀƽƇǃƼǦƼấǅ,ǦǋậǓǦƸƽƕǃƼǦǉƶǦƸứǦǉƽƾǦƼƶǃǦǍƺǂǦƶƾǦǉǇụǦđượƸǦǁƁǊǦƽơǃ!",
    ["咳咳……毒烟熏进来了……"] = "ƦƽụǦǀƽụ……ǦƦƽƚƾǦđộƸǦǍƇǃƼǦǋƐǄǦǇồƾ……",
    ["这处机关倒似牵连甚多，会是鹤院主说的千机万象么？……水渍，连着灌溉的水车？还是水运仪象台？"] = "ƞơǦǆǊƶǃǦǃƐǓǦǤườǃƼǦǃƽưǦǁƾƙǃǦđớƾǦǇấǉǦǃƽƾềǊ,ǦǁƾệǊǦƸƚǦǅƽảƾǦǁƐǦǥƽƾƙǃǦƞơǦƱạǃǦǥượǃƼǦǂƐǦƣạƸǦǋƾệǃǦƸƽủǦǃƚƾǦǀƽƇǃƼ?Ǧ……ǦƱếǉǦǃướƸ,ǦǃốƾǦǋớƾǦƼǊồǃƼǦǃướƸǦǉướƾǦǉƾƙǊ?ǦƣƶǓǦǁƐǦǥƽủǓǦƱậǃǦƩƼƽƾǦǥượǃƼǦĐƐƾ?",
    ["这声响……是那“千机万象”？不，这只是寻常的墨山道机关……"] = "ƀǂǦǉƽƶǃƽǦǃƐǓ……ǦǁƐǦ\"ǥƽƾƙǃǦƞơǦƱạǃǦǥượǃƼ\"ǦǈƶǄ?ǦƦƽƇǃƼ,ǦđƁǓǦƸƽỉǦǁƐǦƸơǦǆǊƶǃǦƨặƸǦƮơǃǦĐạǄǦǉầǂǦǉƽườǃƼǦǉƽƇƾ……",
    ["娘……肚里有虫在咬……"] = "ƩươǃƼ……ǦǉǇǄǃƼǦƷụǃƼǦƸƚǦƸǄǃǦǈƁǊǦđƶǃƼǦƸắǃ……",
    ["圆圆"] = "ƱƾƙǃǦƱƾƙǃ",
    ["圆圆乖，你咽咽口水，就想着……"] = "ƱƾƙǃǦƱƾƙǃǦǃƼǄƶǃ,ǦƸǄǃǦǃǊốǉǦǃướƸǦǂƾếǃƼǦđƾ,ǦƸứǦǉưởǃƼǦǉượǃƼǦǁƐ……",
    ["柔娘"] = "ƩƽǊǦƩươǃƼ",
    ["就想着在吃秧秧饼。虫儿见着秧秧饼，就不咬圆圆了。"] = "ƞứǦǉưởǃƼǦǃƽưǦđƶǃƼǦăǃǦƷƑǃƽǦǂầǂǦǋậǓ.ǦƮƁǊǦǉƽấǓǦƷƑǃƽǦǂầǂǦǇồƾǦǈẽǦǀƽƇǃƼǦƸắǃǦƱƾƙǃǦƱƾƙǃǦǃữƶ.",
    ["……最后一块柴了，这火堆怕是撑不了多久了……"] = "……ǦǥƽƶǃƽǦƸủƾǦƸǊốƾǦƸƖǃƼǦǇồƾ,ǦđốǃƼǦǁửƶǦǃƐǓǦƺǦǁƐǦǀƽƇǃƼǦƸầǂǦƸựǦđượƸǦƷƶǄǦǁƁǊǦǃữƶ……",
    ["丁萍"] = "ĐƾǃƽǦƝƔǃƽ",
    ["没事，不想便不冷。你说，隋师姐他们，现在走到哪儿了？南边，应该会暖和很多吧。我还没去过南边呢。"] = "ƦƽƇǃƼǦǈƶǄ,ǦǀƽƇǃƼǦǃƼƽĩǦđếǃǦǉƽƔǦǈẽǦǀƽƇǃƼǦǉƽấǓǦǁạǃƽ.ǦǥỷǦǃƚƾǦǍƺǂ,ǦƷọǃǦǥƖǓǦǈưǦǉỷǦƷƁǓǦƼƾờǦđƾǦǉớƾǦđƁǊǦǇồƾ?ǦƫƽƓƶǦƩƶǂǦƸƽắƸǦǁƐǦǈẽǦấǂǦƑǅǦƽơǃǦǃƽƾềǊǦǃƽỉ.ǦƨǊộƾǦǋẫǃǦƸƽưƶǦđượƸǦđƾǦǅƽƓƶǦƩƶǂǦƷƶǄǦƼƾờ.",
    ["穆师姐卒业之后就去了江南，原本说好，明年春天要去找她呢。"] = "ƨụƸǦǈưǦǉỷǦǈƶǊǦǀƽƾǦǉốǉǦǃƼƽƾệǅǦđƃǦđƾǦƢƾƶǃƼǦƩƶǂ,ǦǋốǃǦǤĩǦđƃǦƽẹǃǦǍǊƁǃǦǃăǂǦǈƶǊǦǈẽǦđƾǦǉƔǂǦǉỷǦấǓ.",
    ["江南，“画船听雨眠”，多美。诶，听说师姐在那边，收了不少新弟子？"] = "ƢƾƶǃƼǦƩƶǂ,Ǧ\"ƣọƶǦǉƽǊǓềǃǦǉƽƓǃƽǦǋũǦǂƾƙǃ\",ǦǉƽậǉǦđẹǅǦǁƐǂǦǈƶǄ.ǦÊ,ǦǃƼƽƺǦǃƚƾǦǈưǦǉỷǦởǦƷƙǃǦđƚǦǉƽǊǦǃƽậǃǦǀƽƇǃƼǦƓǉǦđệǦǉửǦǂớƾ?",
    ["邵伋"] = "ǥƽƾệǊǦƞấǅ",
    ["嗯，前一阵还差人寄了弟子们的诗集回来，说给符师姐看看。符师姐满脑子都是大家的课业安排、衣食添置……哪有心思看这些？"] = "Ừǂ,ǦǤạǄǦǉǇướƸǦƸƛǃǦǈƶƾǦǃƼườƾǦƼửƾǦǉƽƾǦǉậǅǦƸủƶǦđệǦǉửǦǋề,ǦƷảǄǦđưƶǦƸƽǄǦƫƽƖǦǈưǦǉỷǦǍƺǂ.ǦƫƽƖǦǈưǦǉỷǦǉǇǄǃƼǦđầǊǦƸƽỉǦǉǄƐǃǦǁƐǦǈắǅǦǍếǅǦƷƐƾǦǋở,ǦǈắǂǦǈửƶǦăǃǦǂặƸǦƸƽǄǦǂọƾǦǃƼườƾ……ǦđƁǊǦƸƚǦǉƁǂǦǉǇƓǦǂƐǦǍƺǂǦǂấǓǦǉƽứǦǃƐǓ?",
    ["那穆师姐给你寄什么了？"] = "ǥƽếǦƨụƸǦǈưǦǉỷǦƼửƾǦƼƔǦƸƽǄǦƽǊǓǃƽ?",
    ["她……用桃花、紫阳、菊花、梅花压了花笺寄回来。"] = "ǥỷǦấǓ……ǦǤƖǃƼǦƽǄƶǦđƐǄ,ǦǉửǦǤươǃƼ,ǦƽǄƶǦƸƕƸ,ǦƽǄƶǦǂƶƾǦƗǅǦǋƐǄǦƽǄƶǦǉƾƙǃǦƼửƾǦǋề.",
    ["见过“江南四季”，就当、就当我也去过江南了……"] = "ĐƃǦǉƽấǓǦǆǊƶǦ\"ƢƾƶǃƼǦƩƶǂǦǉứǦǆǊƈ\",ǦǍƺǂǦǃƽư,ǦǍƺǂǦǃƽưǦǂǊộƾǦƸũǃƼǦđƃǦǉừǃƼǦđếǃǦƢƾƶǃƼǦƩƶǂǦǇồƾ……",
    ["哎，别只去江南呀。唐师兄，你看过的书多，给我们讲讲呗，漠北、川蜀……都是什么样的？咱们也去看看。"] = "ƞƽƐ,ǦđừǃƼǦƸƽỉǦƸƚǦƢƾƶǃƼǦƩƶǂǦƸƽứ.ǦĐườǃƼǦǈưǦƽǊǓǃƽ,ǦƽǊǓǃƽǦđọƸǦǃƽƾềǊǦǈƑƸƽ,ǦǀểǦƸƽǄǦƷọǃǦǂǊộƾǦǃƼƽƺǦƸƽƕǉǦđƾ,ǦƨạƸǦƝắƸ,ǦƳǊǓƙǃǦǥƽụƸ……ǦǃƽữǃƼǦǃơƾǦđƚǦǃƽưǦǉƽếǦǃƐǄ?ǦƞƽƕǃƼǦǉƶǦƸũǃƼǦđƾǦǍƺǂǦǉƽử.",
    ["漠北……白天很热，夜晚又很冷。遍地黄沙中缀着小小的绿洲，那儿的人就住在绿洲里。"] = "ƨạƸǦƝắƸ……ǦƷƶǃǦǃƼƐǓǦǇấǉǦǃƚǃƼ,ǦƷƶǃǦđƙǂǦǁạƾǦǇấǉǦǁạǃƽ.ǦƢƾữƶǦǂǊƇǃǦǉǇƖǃƼǦƸƑǉǦǋƐǃƼǦđƾểǂǦǍǊǓếǉǦǃƽữǃƼǦốƸǦđảǄǦǃƽỏǦǃƽǄƾ,ǦǃƼườƾǦởǦđƚǦǈốǃƼǦǉǇǄǃƼǦƸƑƸǦốƸǦđảǄ.",
    ["嗯，漠北，“平沙万里绝人烟”。"] = "Ừǂ,ǦƨạƸǦƝắƸ,Ǧ\"ƝƔǃƽǦǈƶǦǋạǃǦǁƈǦǉǊǓệǉǦǃƽƁǃǦǓƙǃ\".",
    ["绿洲里长着葡萄、蜜瓜……好些中原没有的果子。那边的人歌声很亮，人人都会跳舞。还有骆驼，背上长着驼峰，就和中原的马一样，平日出行可少不了它。"] = "ǥǇǄǃƼǦốƸǦđảǄǦǉǇồǃƼǦǃƽǄ,ǦǂậǉǦǆǊƶ……ǦǃƽƾềǊǦǁǄạƾǦǉǇƑƾǦƸƁǓǦǂƐǦǥǇǊǃƼǦƩƼǊǓƙǃǦǀƽƇǃƼǦƸƚ.ǦƩƼườƾǦởǦđƚǦƽƑǉǦǇấǉǦǋƶǃƼ,ǦƶƾǦƶƾǦƸũǃƼǦƷƾếǉǦǂƕƶ.ǦƞƛǃǦƸƚǦǁạƸǦđƐ,ǦǉǇƙǃǦǁưǃƼǦƸƚǦƷướǊ,ǦƼƾốǃƼǦǃƽưǦǃƼựƶǦởǦǥǇǊǃƼǦƩƼǊǓƙǃǦǋậǓ,ǦđƾǦǁạƾǦƽƐǃƼǦǃƼƐǓǦǀƽƇǃƼǦǉƽểǦǉƽƾếǊǦǃƚǦđượƸ.",
    ["川蜀呢？诗里说“地崩山摧，百步九折；飞湍瀑流，砯崖转石”……真是如此？"] = "ƞƛǃǦƳǊǓƙǃǦǥƽụƸǦǉƽƔǦǈƶǄ?ǦǥǇǄǃƼǦǉƽơǦǃƚƾǦ\"ĐịƶǦƷăǃƼǦǈơǃǦǉồƾ,ǦƷƑƸƽǦƷộǦƸửǊǦƸƽƾếǉ;ǦǅƽƾǦđǄảǃǦƷộƸǦǁưǊ,ǦǅƽƶǃƽǦǃƽƶƾǦƸƽǊǓểǃǦǉƽạƸƽ\"……ǦƸƚǦǉƽậǉǦǃƽưǦǋậǓǦǀƽƇǃƼ?",
    ["是啊，那里山叠着山水连着水，奇而美……"] = "ĐƕǃƼǦǋậǓ,ǦǃơƾǦđƚǦǃƕƾǦƸƽồǃƼǦǁƙǃǦǃƕƾǦǃướƸǦǃốƾǦǁƾềǃǦǃướƸ,ǦǀỳǦǋĩǦǂƐǦǤƾễǂǦǁệ……",
    ["师兄，再说一说荆楚吧！真想看看是何等天地，能写出天问这般极章！"] = "ƮưǦƽǊǓǃƽ,ǦǃƚƾǦǉƽƙǂǦǋềǦƦƾǃƽǦƮởǦđƾ!ǦǥƽậǉǦǂǊốǃǦǍƺǂǦǉƽửǦǃơƾǦđƚǦǁƐǦǉƽƾƙǃǦđịƶǦƽạǃƼǦǃƐǄǦǂƐǦƸƚǦǉƽểǦǋƾếǉǦǇƶǦǃƽữǃƼǦƸƽươǃƼǦǉǊǓệǉǦǉƑƸǦǃƽưǦǥƽƾƙǃǦƱấǃ!",
    ["还有，还有岭南！“两岸荔枝红，万家烟雨中”……"] = "ƞƛǃǦƸƚ,ǦƸƛǃǦƸƚǦƧĩǃƽǦƩƶǂǦǃữƶ!Ǧ\"ƧưỡǃƼǦǃƼạǃǦǁệǦƸƽƾǦƽồǃƼ,ǦǋạǃǦƼƾƶǦǓƙǃǦǋũǦǉǇǊǃƼ\"……",
    ["小妹，再教我两招吧！"] = "ǥƾểǊǦƨǊộƾ,ǦǤạǓǦǂǊộƾǦǉƽƙǂǦƽƶƾǦƸƽƾƙǊǦǃữƶǦđƾ!",
    ["好啊，你就是我弓箭社的开座首徒了！"] = "ĐượƸǦǉƽƇƾ,ǦǂǊộƾǦƸƽƓǃƽǦǁƐǦǀƽƶƾǦǉọƶǦǉƽủǦđồǦƸủƶǦƸǊǃƼǦǉƾễǃǦǍƃǦƸủƶǦǉƶǦǇồƾ!",
    ["到时候我先冲，你别往上凑。虏人到跟前了，就这样斜划十字，让他近不了身。放心，等我来支援就好。"] = "ƧƕƸǦđƚǦǉƶǦǈẽǦǍƇǃƼǦǁƙǃǦǉǇướƸ,ǦǂǊộƾǦđừǃƼǦƸƚǦǃƽƐǄǦǉớƾ.ǦƬǊƁǃǦƼƾặƸǦđếǃǦƼầǃǦǇồƾǦǉƽƔǦƸứǦǇạƸƽǦƽƔǃƽǦƸƽữǦǉƽậǅǦƸƽƗǄǦǃƽưǦǉƽếǦǃƐǓ,ǦǀƽƾếǃǦƽắǃǦǀƽƇǃƼǦƑǅǦǈƑǉǦđượƸ.ǦƴƙǃǦǉƁǂ,ǦđợƾǦǉƶǦǉớƾǦứǃƼǦƸứǊǦǁƐǦđượƸ.",
    ["稻六十，豉六十三……"] = "ĐạǄǦǈƑǊǦǂươƾ,ǦǉƽịǦǈƑǊǦǂươƾǦƷƶ……",
    ["师兄……在做什么？"] = "ƮưǦƽǊǓǃƽ……ǦđƶǃƼǦǁƐǂǦƼƔǦǋậǓ?",
    ["沙信臣"] = "ƮƶǦǥƓǃǦǥƽầǃ",
    ["飱九十……九十……"] = "ƫƽổǦƸƽƓǃǦǂươƾ……ǦƸƽƓǃǦǂươƾ……",
    ["……哦，前些日子试补《算术书>的虫蚀部分，正有了些眉目，我怕……我怕来不及，得再抓紧些……"] = "……Ồ,ǦǂấǓǦǃƼƐǓǦǉǇướƸǦđịǃƽǦƷổǦǈǊǃƼǦǅƽầǃǦǂọǉǦăǃǦƸủƶǦ<ǥǄƑǃǦǥƽǊậǉǦǥƽư>,ǦǋừƶǦǂớƾǦƸƚǦƸƽƕǉǦǂƶǃƽǦǂốƾ,ǦǉƶǦǈợ……ǦǉƶǦǈợǦǀƽƇǃƼǦǀịǅǦǃữƶ,ǦǅƽảƾǦǁƐǂǦǃƽƶǃƽǦƽơǃǦƸƽƕǉ……",
    ["鹤院主，时候不早了，你可想好了？"] = "ƣạƸǦǋƾệǃǦƸƽủ,ǦǉƽờƾǦƼƾƶǃǦǀƽƇǃƼǦƸƛǃǦǈớǂǦǃữƶ,ǦǃƼườƾǦđƃǦǃƼƽĩǦǀỹǦƸƽưƶ?",
    ["直娘贼的契丹杂种！老子干不死你们！我罗成武……"] = "ĐồǦǆǊƁǃǦǉặƸǦƦƽƾếǉǦĐƶǃǦǀƽốǃǦǀƾếǅ!ǦƧƃǄǦǉửǦǀƽƇǃƼǦǁƾềǊǦǂạǃƼǦǋớƾǦƸƑƸǦǃƼươƾǦǀƽƇǃƼǦǍǄǃƼ!ǦǥƶǦƧƶǦǥƽƐǃƽǦƱũ……",
    ["罗成武……你可是罗定方之子？"] = "ƧƶǦǥƽƐǃƽǦƱũ……ǦǃƼươƾǦƸƽƓǃƽǦǁƐǦƸǄǃǦǉǇƶƾǦƸủƶǦƧƶǦĐịǃƽǦƫƽươǃƼ?",
    ["哈，正是！怎的，被你爷爷的大名吓得尿裤子了？"] = "ƣƶ,ǦƸƽƓǃƽǦǁƐǦǉƶ!ǦƮƶǄǦǃƐǄ,ǦƷịǦđạƾǦǤƶǃƽǦƸủƶǦƇǃƼǦǃộƾǦǃƼươƾǦǤọƶǦƸƽǄǦǉƾểǊǦǇƶǦǆǊầǃǦǇồƾǦƐ?",
    ["罗公子果然是将门虎子，英武非凡。"] = "ƧƶǦƸƇǃƼǦǉửǦǆǊảǦǃƽƾƙǃǦǁƐǦƽổǦǉửǦǉướǃƼǦǂƇǃ,ǦƶǃƽǦǋũǦǅƽƾǦǅƽƐǂ.",
    ["院主，木鸢！林险生的信！"] = "ƱƾệǃǦƸƽủ,ǦǂộƸǦǤƾƙǊ!ǦǥƽưǦƸủƶǦƧƁǂǦƣƾểǂǦƮƾǃƽ!",
    ["你父亲托我等好好照看你。此刻，想必他正在契丹国主的帐中喝湩酒呢。"] = "ƫƽụǦǉƽƁǃǦǃƼươƾǦǉƽƑƸǦƸƽƕǃƼǦǉƶǦƸƽăǂǦǈƚƸǦǃƼươƾǦƸƽǄǦǉốǉ.ǦƧƕƸǦǃƐǓ,ǦƸƽắƸǦƽẳǃǦƇǃƼǦấǓǦđƶǃƼǦởǦǉǇǄǃƼǦǉǇướǃƼǦƸủƶǦǆǊốƸǦƸƽủǦƦƽƾếǉǦĐƶǃǦǊốǃƼǦǇượǊǦǈữƶǦđấǓ.",
    ["你、你爹……"] = "ƩƼươƾ,ǦƸƽƶǦǃƼươƾ……",
    ["怎么？罗公子难道还不知？三日前，罗将军已经率部投效了我契丹国，等着你前去团聚呢。"] = "ƮƶǄǦƽả?ǦƧƶǦƸƇǃƼǦǉửǦǁẽǦǃƐǄǦƸƛǃǦƸƽưƶǦƷƾếǉ?ǦƝƶǦǃƼƐǓǦǉǇướƸ,ǦƧƶǦǉướǃƼǦǆǊƁǃǦđƃǦǤẫǃǦƷộǦƽạǦđầǊǦǆǊƁǃǦƸƽǄǦƦƽƾếǉǦĐƶǃǦǆǊốƸǦǉƶ,ǦđƶǃƼǦđợƾǦǃƼươƾǦđếǃǦđǄƐǃǦǉụǦđấǓ.",
    ["我爹……我爹他……不可能……不可能！"] = "ƞƽƶǦǉƶ……ǦƸƽƶǦǉƶǦƇǃƼǦấǓ……ǦǀƽƇǃƼǦǉƽểǦǃƐǄ……ǦǀƽƇǃƼǦǉƽểǦǃƐǄ!",
    ["成武……"] = "ǥƽƐǃƽǦƱũ……",
    ["我太爷爷是羽林军队正，我爷爷是雁子都都头，我爹……我爹乃衙前讨击使，率军镇守阳城，杀虏千余人！我罗家世代将门，绝不做狗！"] = "ƞụǦǃộƾǦǉƶǦǁƐǦƱũǦƧƁǂǦǆǊƁǃǦĐộƾǦƸƽƓǃƽ,ǦƇǃƼǦǃộƾǦǉƶǦǁƐǦƩƽạǃǦǥửǦđƇǦĐƇǦđầǊ,ǦƸƽƶǦǉƶ……ǦƸƽƶǦǉƶǦǁƐǦƩƽƶǦǉƾềǃǦǥƽảǄǦǀƓƸƽǦǈứ,ǦǤẫǃǦǆǊƁǃǦǉǇấǃǦǉƽủǦǝươǃƼǦǥƽƐǃƽ,ǦƼƾếǉǦƽơǃǦǃƼƐǃǦǆǊƁǃǦƼƾặƸ!ǦƧƶǦƼƾƶǦǉƶǦǉƽếǦđạƾǦǉướǃƼǦǂƇǃ,ǦǉǊǓệǉǦǀƽƇǃƼǦǁƐǂǦƸƽƚ!",
    ["鹤院主，你要等人，我便让你等。只是这答案，也该揭晓了。"] = "ƣạƸǦǋƾệǃǦƸƽủ,ǦǃƼườƾǦǂǊốǃǦđợƾǦǃƼườƾ,ǦǉƶǦǁƾềǃǦđểǦǃƼườƾǦđợƾ.ǦƞƽỉǦǁƐǦđƑǅǦƑǃǦǃƐǓ,ǦƸũǃƼǦđếǃǦǁƕƸǦƸƇǃƼǦƷốǦǇồƾ.",
    ["院主，信上说什么？援军何时能至？"] = "ƱƾệǃǦƸƽủ,ǦǉǇǄǃƼǦǉƽưǦǃƚƾǦƼƔ?ǦƱƾệǃǦǆǊƁǃǦǀƽƾǦǃƐǄǦǂớƾǦđếǃ?",
    ["杜重威，已降契丹。中渡桥，全军覆没。"] = "ĐỗǦǥǇọǃƼǦǕǓ,ǦđƃǦƽƐǃƼǦƦƽƾếǉǦĐƶǃ.ǦǥǇǊǃƼǦĐộǦƦƾềǊ,ǦǉǄƐǃǦǆǊƁǃǦƷịǦǤƾệǉ.",
    ["只那么点人能出去……哎……"] = "ƞƽỉǦƸƚǦƷấǓǦǃƽƾƙǊǦǃƼườƾǦƸƚǦǉƽểǦǇƶǦǃƼǄƐƾ……ǦƸƽƶǄǦƇƾ……",
    ["这……这可怎么好……"] = "ƞƽǊǓệǃǦǃƐǓ……ǦƸƽǊǓệǃǦǃƐǓǦƷƾếǉǦǁƐǂǦǈƶǄǦđƁǓ……",
    ["我的也给你吧"] = "ƞủƶǦǉƶǦƸũǃƼǦƸƽǄǦǃƼươƾǦǃƐǓ",
    ["不行，抽到谁就是谁，和平日一样"] = "ƦƽƇǃƼǦđượƸ,ǦǇƕǉǦǉǇƕǃƼǦƶƾǦǉƽƔǦǁƐǦǃƼườƾǦđƚ,ǦƼƾốǃƼǦǃƽưǦǃƼƐǓǦǉƽườǃƼǦǋậǓ",
    ["别哭，留下的也未必就……"] = "ĐừǃƼǦǀƽƚƸ,ǦǃƼườƾǦởǦǁạƾǦƸũǃƼǦƸƽưƶǦƸƽắƸǦđƃ……",
    ["怎么呢？又发呆了？快走吧。"] = "ƮƶǄǦǉƽế?ǦƧạƾǦǃƼẩǃǦǃƼườƾǦǇƶǦƐ?ǦƨƶǊǦđƾǦǉƽƇƾ.",
    ["去……去哪？"] = "Đƾ……ǦđƾǦđƁǊ?",
    ["收签子呀，怎么，院主刚交代的，又忘了？"] = "ǥƽǊǦǍăǂǦƸƽứǦđƁǊ,ǦǈƶǄǦƽả,ǦƱƾệǃǦƸƽủǦǋừƶǦǤặǃǦǤƛ,ǦǃƼươƾǦǁạƾǦǆǊƙǃǦǇồƾ?",
    ["哦，收签子……"] = "Ồ,ǦǉƽǊǦǍăǂ……",
    ["平日里都是抽：谁第一个起头背书，谁负责值勤打扫学堂，谁去给种地先生记“思农要术”……"] = "ƩƼƐǓǦǉƽườǃƼǦđềǊǦǁƐǦǇƕǉ:ǦƶƾǦǁƐǦǃƼườƾǦđầǊǦǉƾƙǃǦƷắǉǦđầǊǦđọƸǦǉƽǊộƸǦǁƛǃƼ,ǦƶƾǦǅƽụǦǉǇƑƸƽǦǉǇựƸǦƸƶǦǆǊƗǉǦǤọǃǦƽọƸǦđườǃƼ,ǦƶƾǦđƾǦƼƾƕǅǦǉƾƙǃǦǈƾǃƽǦǤạǓǦǉǇồǃƼǦǉǇọǉǦƼƽƾǦƸƽƗǅǦ\"ǥưǦƩƇǃƼǦƴếǊǦǥƽǊậǉ\"……",
    ["今日抽的，倒似千钧之重……"] = "ǥƽƶǃƽǦǍăǂǦǇƕǉǦǃƼƐǓǦƽƇǂǦǃƶǓ,ǦǁạƾǦǃƽưǦǃặǃƼǦǃƼƐǃǦƸƁǃ……",
    ["看什么？想偷我签子？"] = "ƩƽƔǃǦƸƑƾǦƼƔ?ǦƨǊốǃǦǉǇộǂǦǍăǂǦƸủƶǦǉƶǦƐ?",
    ["谁偷你？写那么一大串，你名字有那么长？"] = "ƜƾǦǉƽƘǂǦǉǇộǂǦƸủƶǦǃƼươƾ?ǦƱƾếǉǦǂộǉǦǉǇƐǃƼǦǤƐƾǦǉƽếǦǀƾƶ,ǦǉƙǃǦǃƼươƾǦǤƐƾǦǋậǓǦǈƶǄ?",
    ["《秦远的签子，自己的名字划掉了，又写了小萝卜>》罗成武的签子，包裹着一层破布，只看到似乎是很长的一串字>"] = "<ƳăǂǦƸủƶǦǥầǃǦƱƾễǃ,ǦƼạƸƽǦǉƙǃǦǂƔǃƽǦđƾ,ǦǁạƾǦǋƾếǉǦǉƙǃǦǥƾểǊǦƧƶǦƝặƸ><ƳăǂǦƸủƶǦƧƶǦǥƽƐǃƽǦƱũ,ǦƷọƸǦǂộǉǦǁớǅǦǋảƾǦǇƑƸƽ,ǦƸƽỉǦǉƽấǓǦǤườǃƼǦǃƽưǦǁƐǦǂộǉǦƸƽǊỗƾǦƸƽữǦǇấǉǦǤƐƾ>",
    ["种地先生，我来收签子了……"] = "ǥƾƙǃǦǈƾǃƽǦǤạǓǦǉǇồǃƼǦǉǇọǉ,ǦƸǄǃǦđếǃǦǉƽǊǦǍăǂǦđƁǓ……",
    ["《刘思农的签子，写着小萝卜>"] = "<ƳăǂǦƸủƶǦƧưǊǦǥưǦƩƇǃƼ,ǦǋƾếǉǦǉƙǃǦǥƾểǊǦƧƶǦƝặƸ>",
    ["种地先生，你、你写错了……"] = "ǥƾƙǃǦǈƾǃƽ,ǦǃƼườƾ,ǦǃƼườƾǦǋƾếǉǦǈƶƾǦǇồƾ……",
    ["没错，是这个。好孩子，去吧……"] = "ƦƽƇǃƼǦǈƶƾ,ǦǁƐǦƸƑƾǦǃƐǓ.ǦĐứƶǦǉǇẻǦǃƼǄƶǃ,ǦđƾǦđƾ……",
    ["两根，我和唐师兄的。"] = "ƣƶƾǦǉƽƶǃƽ,ǦƸủƶǦǉƶǦǋƐǦĐườǃƼǦǈưǦƽǊǓǃƽ.",
    ["《一根写着符晓，一根写着鹤>"] = "<ƨộǉǦǉƽƶǃƽǦǋƾếǉǦƫƽƖǦƣƾểǊ,ǦǂộǉǦǉƽƶǃƽǦǋƾếǉǦƣạƸ>",
    ["关大叔，我来收签子。"] = "ƬǊƶǃǦđạƾǦǉƽƕƸ,ǦƸǄǃǦđếǃǦǉƽǊǦǍăǂ.",
    ["哎呦，对不住，大叔的签子找不到了，许是前几天丢在山下了，哈哈。"] = "ÁƾǦƸƽƐ,ǦǍƾǃǦǁỗƾǦǃƽƗ,ǦǉƽƕƸǦǀƽƇǃƼǦǉƔǂǦǉƽấǓǦǍăǂǦƸủƶǦǂƔǃƽǦđƁǊǦƸả,ǦƸƽắƸǦǁƐǦǂấǓǦƽƇǂǦǉǇướƸǦđƑǃƽǦǇơƾǦǤướƾǦǃƕƾǦǇồƾ,ǦƽƶǦƽƶ.",
    ["那、那你重新写一个……"] = "ǥƽế,ǦǉƽếǦǉƽƕƸǦǋƾếǉǦǁạƾǦǂộǉǦƸƑƾǦǀƽƑƸǦđƾ……",
    ["大叔一会就写，修完这个灯就写，你先去收别人的，一会大叔写了直接给院主。"] = "ǥƽƕƸǦǋƾếǉǦǃƼƶǓǦđƁǓ,ǦǈửƶǦǍǄǃƼǦƸƑƾǦđƘǃǦǃƐǓǦǈẽǦǋƾếǉ,ǦƸǄǃǦƸứǦđƾǦǉƽǊǦƸủƶǦǃƼườƾǦǀƽƑƸǦǉǇướƸǦđƾ,ǦǁƑǉǦǃữƶǦǉƽƕƸǦǋƾếǉǦǍǄǃƼǦǈẽǦđưƶǦǉƽẳǃƼǦƸƽǄǦƱƾệǃǦƸƽủ.",
    ["《刘小妹的签子，写着鹤老头>"] = "<ƳăǂǦƸủƶǦƧưǊǦǥƾểǊǦƨǊộƾ,ǦǋƾếǉǦƸƽữǦƣạƸǦǁƃǄǦđầǊ>",
    ["大姐头，你……"] = "ĐạƾǦǉỷǦđầǊ,Ǧǉỷ……",
    ["嘘……快去快去！"] = "ƮǊỵǉ……ǦǂƶǊǦđƾǦđƾ!",
    ["对了，往后可得好好念书，别老贪玩知道么？总说什么明天明天的，哪有那么多明天。"] = "ƫƽảƾǦǇồƾ,ǦǈƶǊǦǃƐǓǦǅƽảƾǦƸƽăǂǦƸƽỉǦƽọƸǦƽƐǃƽ,ǦđừǃƼǦƸƚǦƽƶǂǦƸƽơƾǦǂƃƾǦƷƾếǉǦƸƽưƶ?ǦƞứǦǁǊƇǃǦǂƾệǃƼǦǃƚƾǦǃƼƐǓǦǂƶƾǦǃƼƐǓǦǂƶƾ,ǦǁƐǂǦƼƔǦƸƚǦǃƽƾềǊǦǃƼƐǓǦǂƶƾǦđếǃǦǉƽế.",
    ["丁苹"] = "ĐƾǃƽǦƝƔǃƽ",
    ["桑语"] = "ǥƶǃƼǦƩƼữ",
    ["张老太"] = "ǥǇươǃƼǦǁƃǄǦǉƽƑƾ",
    ["林老伯"] = "ƧƁǂǦǁƃǄǦƷƑ",
    ["这是我的。"] = "ĐƁǓǦǁƐǦƸủƶǦǉƶ.",
    ["院主，签子、签子收好了……"] = "ƱƾệǃǦƸƽủ,ǦǍăǂ,ǦǍăǂǦđƃǦǉƽǊǦǍǄǃƼǦǇồƾ……",
    ["呦，这么快？"] = "Ồ,ǦǃƽƶǃƽǦǋậǓǦǈƶǄ?",
    ["可是……可是大家……"] = "ƩƽưǃƼǦǂƐ……ǦǃƽưǃƼǦǂƐǦǂọƾǦǃƼườƾ……",
    ["哦？那咱们一起来检查下大家的课业做得怎么样，好不好？"] = "Ồ?ǦƱậǓǦƸƽƕǃƼǦǉƶǦƸƖǃƼǦǀƾểǂǦǉǇƶǦǍƺǂǦƷƐƾǦǋởǦƸủƶǦǂọƾǦǃƼườƾǦǁƐǂǦǉƽếǦǃƐǄǦǃƽƗ,ǦđượƸǦǀƽƇǃƼ?",
    ["这些家伙……"] = "ƨấǓǦǉƙǃǦǃƽƚƸǦǃƐǓ……",
    ["呦，怎么哭鼻子了？我给你变个戏法怎么样？"] = "ƆǦǀƔƶ,ǦǈƶǄǦǁạƾǦǀƽƚƸǦǃƽƘǦǇồƾ?ǦǥƶǦƷƾếǃǦƸƽǄǦƸǄǃǦǂộǉǦǉǇƛǦảǄǦǉƽǊậǉǦǃƽƗ?",
    ["上回教你的那句书，可还记得？你闭上眼，念一遍。"] = "ƞƁǊǦǈƑƸƽǦǉƶǦǤạǓǦƸǄǃǦǁầǃǦǉǇướƸ,ǦƸƛǃǦǃƽớǦǀƽƇǃƼ?ǦƞǄǃǦǃƽắǂǦǂắǉǦǁạƾ,ǦđọƸǦǂộǉǦǁầǃǦǍƺǂ.",
    ["……玉不琢，不成器；人不学，不知道。"] = "……ƩƼọƸǦƷấǉǦǉǇƑƸ,ǦƷấǉǦǉƽƐǃƽǦǀƽƓ;ǦƩƽƁǃǦƷấǉǦƽọƸ,ǦƷấǉǦǉǇƾǦđạǄ.",
    ["院主，你——！"] = "ƱƾệǃǦƸƽủ,ǦǃƼườƾ——!",
    ["开！"] = "ƨở!",
    ["是秧秧饼！"] = "ƧƐǦƷƑǃƽǦǂầǂ!",
    ["吃吧，吃完，咱们就该办大事了。"] = "ĂǃǦđƾ,ǦăǃǦǍǄǃƼ,ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦǁƐǂǦǋƾệƸǦǁớǃǦǇồƾ.",
    ["圆圆，给你。"] = "ƱƾƙǃǦƱƾƙǃ,ǦƸƽǄǦƸǄǃǦǃƐǓ.",
    ["我们，我们一人一半！"] = "ƞƽƕǃƼǦǉƶ,ǦƸƽƕǃƼǦǉƶǦǂỗƾǦǃƼườƾǦǂộǉǦǃửƶ!",
    ["小萝卜，来，握住签筒，晃一晃。"] = "ǥƾểǊǦƧƶǦƝặƸ,ǦǁạƾǦđƁǓ,ǦƸầǂǦǁấǓǦốǃƼǦǍăǂ,ǦǁắƸǦǂộǉǦƸƑƾ.",
    ["小萝卜……"] = "ǥƾểǊǦƧƶǦƝặƸ……",
    ["小萝卜。"] = "ǥƾểǊǦƧƶǦƝặƸ.",
    ["圆圆。"] = "ƱƾƙǃǦƱƾƙǃ.",
    ["符晓。"] = "ƫƽƖǦƣƾểǊ.",
    ["石顺"] = "ǥƽạƸƽǦǥƽǊậǃ",
    ["张老太太"] = "ǥǇươǃƼǦǁƃǄǦǉƽƑƾǦǉƽƑƾ",
    ["喏，我的看家本事也交给你了！一共三册，我还用油纸包好了，嘿嘿。"] = "ƩƐǓ,ǦƷảǃǦǁĩǃƽǦƽộǦǉƽƁǃǦƸủƶǦǉƶǦƸũǃƼǦƼƾƶǄǦƸƽǄǦǃƼươƾǦđấǓ!ǦǥổǃƼǦƸộǃƼǦƷƶǦƸǊốǃ,ǦǉƶǦƸƛǃǦǤƖǃƼǦƼƾấǓǦǤầǊǦƷọƸǦǀỹǦǇồƾ,ǦƽƔǦƽƔ.",
    ["喂，你出去了，能不能……帮我去看看我娘？她，她常赶早去南门大街，买新鲜果子……"] = "ƩƐǓ,ǦǃƼươƾǦǇƶǦǃƼǄƐƾǦǇồƾ,ǦƸƚǦǉƽể……ǦƼƾƕǅǦǉƶǦđƾǦǉƽăǂǦǂẫǊǦǉƽƁǃǦǉƶǦǀƽƇǃƼ?ǦƝƐǦấǓ,ǦƷƐǦấǓǦǉƽườǃƼǦǤậǓǦǈớǂǦǇƶǦđạƾǦǅƽốǦƩƶǂǦƨƇǃǦǂǊƶǦƽǄƶǦǆǊảǦǉươƾ……",
    ["圆圆，记不住也没关系的. "] = "ƱƾƙǃǦƱƾƙǃ,ǦǀƽƇǃƼǦǃƽớǦđượƸǦƸũǃƼǦǀƽƇǃƼǦǈƶǄǦđƁǊ.",
    ["你和她说我一切都好，最近跟同门游学去了，得空就回去看她。"] = "ƩƼươƾǦǃƚƾǦǋớƾǦƷƐǦấǓǦǁƐǦǉƶǦǂọƾǦƸƽǊǓệǃǦđềǊǦǉốǉ,ǦƼầǃǦđƁǓǦƸƖǃƼǦđồǃƼǦǂƇǃǦđƾǦǤǊǦƽọƸǦǇồƾ,ǦǁƕƸǦǃƐǄǦǇảǃƽǦǈẽǦǋềǦǉƽăǂǦƷƐǦấǓ.",
    ["好……我，我一定……"] = "ĐượƸ……ǦƸǄǃ,ǦƸǄǃǦǃƽấǉǦđịǃƽ……",
    ["给我娘抄的佛经，带给她。……多谢。"] = "ƦƾǃƽǦƫƽậǉǦǉƶǦƸƽƗǅǦƸƽǄǦǂẫǊǦǉƽƁǃ,ǦǂƶǃƼǦƸƽǄǦƷƐǦấǓǦƼƾƕǅǦǉƶ.Ǧ……ĐƶǦǉạ.",
    ["院主，签子抽完了……"] = "ƱƾệǃǦƸƽủ,ǦǍăǂǦđƃǦǇƕǉǦǍǄǃƼǦǇồƾ……",
    ["腊月十一了，小妹，秦远，还有大家，恭喜你们，今日卒业了。"] = "ǥƽƑǃƼǦƞƽạǅǦǂườƾǦǂộǉǦǇồƾ,ǦǥƾểǊǦƨǊộƾ,ǦǥầǃǦƱƾễǃ,ǦƸƛǃǦƸảǦǂọƾǦǃƼườƾǦǃữƶ,ǦƸƽƕƸǦǂừǃƼǦƸƑƸǦƸǄǃ,ǦƽƇǂǦǃƶǓǦǉốǉǦǃƼƽƾệǅǦǇồƾ.",
    ["鹤老头，不说点什么？"] = "ƣạƸǦǁƃǄǦđầǊ,ǦǀƽƇǃƼǦǃƚƾǦƼƔǦǈƶǄ?",
    ["之前每年卒业，你都长篇大论的，听得烦死了!"] = "ǥǇướƸǦđƁǓǦǃăǂǦǃƐǄǦǉốǉǦǃƼƽƾệǅǦǃƼườƾǦƸũǃƼǦǃƚƾǦǉǇƐǃƼǦƼƾƶǃƼǦđạƾǦƽảƾ,ǦǃƼƽƺǦǅƽƑǉǦƸƽƑǃǦđƾǦđượƸ!",
    ["好不容易现在有空了，说点呗？"] = "ƦƽƚǦǀƽăǃǦǁắǂǦǂớƾǦƸƚǦǁƕƸǦǇảǃƽǦǇỗƾǦǉƽếǦǃƐǓ,ǦǃƚƾǦǋƐƾǦƸƁǊǦđƾǦƸƽứ?",
    ["好，那就，再说一点。"] = "ĐượƸ,ǦǋậǓǦǉƽƔ,ǦǃƚƾǦǉƽƙǂǦǂộǉǦƸƽƕǉ.",
    ["书院刚落成时，我和你们师兄师姐也是这样围坐着。符晓还记得吗？"] = "ƧƕƸǦǉƽưǦǋƾệǃǦǂớƾǦǀƽƑǃƽǦǉƽƐǃƽ,ǦǉƶǦǋƐǦƸƑƸǦǈưǦƽǊǓǃƽǦǈưǦǉỷǦƸủƶǦƸƑƸǦƸǄǃǦƸũǃƼǦǃƼồƾǦǆǊƁǓǦǆǊầǃǦǉƽếǦǃƐǓ.ǦƫƽƖǦƣƾểǊǦƸƛǃǦǃƽớǦǀƽƇǃƼ?",
    ["记得，咱们二十来个人喝茶谈天. "] = "ƩƽớǦƸƽứ,ǦƸƽƕǃƼǦǉƶǦƽơǃǦƽƶƾǦǂươƾǦǃƼườƾǦǃƼồƾǦǊốǃƼǦǉǇƐǦđƐǂǦđạǄ.",
    ["徐厌，程春华，谢路……初时大伙还拘束着，待说到各自的研究，各个打开了话匣子。"] = "ǥừǦƴếǂ,ǦǥǇƔǃƽǦƳǊƁǃǦƣǄƶ,ǦǥạǦƧộ……ǦǁƕƸǦđầǊǦǂọƾǦǃƼườƾǦƸƛǃǦƼƾữǦǀẽ,ǦđếǃǦǀƽƾǦǃƚƾǦǋềǦǃƼƽƾƙǃǦƸứǊǦƸủƶǦǂƔǃƽ,ǦƶƾǦǃấǓǦđềǊǦǉƽƶǄǦǉƽƶǄǦƷấǉǦǉǊǓệǉ.",
    ["噢，白师兄说到尽兴处，茶水撒了一身。"] = "Ồ,ǦƝạƸƽǦǈưǦƽǊǓǃƽǦǁƕƸǦǃƚƾǦđếǃǦƸƽỗǦƸƶǄǦƽứǃƼ,ǦǃướƸǦǉǇƐǦđổǦƸảǦǁƙǃǦǃƼườƾ.",
    ["他跳起来查看书稿有没有殃及，不小心又绊了自己一跤。大伙儿笑了许久。"] = "ƣǊǓǃƽǦấǓǦǃƽảǓǦǤựǃƼǦǁƙǃǦǍƺǂǦƷảǃǦǉƽảǄǦƸƚǦƷịǦướǉǦǀƽƇǃƼ,ǦǀƽƇǃƼǦƸẩǃǦǉƽậǃǦǁạƾǦǉựǦǁƐǂǦǂƔǃƽǦǃƼƃǦǂộǉǦƸƕ.ǦƨọƾǦǃƼườƾǦđƃǦƸườƾǦǇấǉǦǁƁǊ.",
    ["哈哈，做学问，哪有不爱惜书稿的。年年岁岁的心血，可都在书稿里了。"] = "ƣƶǦƽƶ,ǦǁƐǂǦƽọƸǦǋấǃǦǉƽƔǦƶƾǦǂƐǦǀƽƇǃƼǦǆǊƈǦǉǇọǃƼǦƷảǃǦǉƽảǄǦƸơǦƸƽứ.ǦǥƁǂǦƽǊǓếǉǦƸủƶǦƷƶǄǦǃƽƾƙǊǦǃăǂǦǉƽƑǃƼǦđềǊǦǃằǂǦƸảǦǉǇǄǃƼǦƷảǃǦǉƽảǄǦǇồƾ.",
    ["小时候大家爱听说书，是吧小萝卜？"] = "ƣồƾǦǃƽỏǦǂọƾǦǃƼườƾǦđềǊǦǉƽƓƸƽǦǃƼƽƺǦǀểǦƸƽǊǓệǃ,ǦđƕǃƼǦǀƽƇǃƼǦǥƾểǊǦƧƶǦƝặƸ?",
    ["嗯！女娲补天，卧薪尝胆，闻鸡起舞，草船借箭……还有好多好多。"] = "ƱƁǃƼǦạ!ǦƩữǦƪƶǦƷổǦǉƽƾƙǃ,ǦƩƼọƶǦǉƁǃǦǉươǃƼǦđảǂ,ǦƱăǃǦǀƙǦǀƽởƾǦǋũ,ǦǥƽảǄǦǉƽǊǓềǃǦǉƑǦǉƾễǃ……ǦƸƛǃǦǃƽƾềǊǦǃƽƾềǊǦǁắǂǦạ.",
    ["待年岁稍长，读书之趣愈深，六艺百家，渐入眼中，亦明了了书中洪荒万千。"] = "ĐợƾǦđếǃǦǀƽƾǦǉǊổƾǦǉƑƸǦǁớǃǦƽơǃǦƸƽƕǉ,ǦƽứǃƼǦǉƽƕǦđọƸǦǈƑƸƽǦƸƐǃƼǦǈƁǊ,ǦƧụƸǦǃƼƽệǦƝƑƸƽǦƼƾƶǦǤầǃǦƽƾệǃǦǇƶǦǉǇướƸǦǂắǉ,ǦƸũǃƼǦǉƽấǊǦƽƾểǊǦđượƸǦǂǊƇǃǦǋƐǃǦǈựǦđờƾǦǉǇǄǃƼǦǈƑƸƽ.",
    ["有人爱诗词，有人擅营造，有人学武术，也有人琢磨百工著述。"] = "ƞƚǦǃƼườƾǦǓƙǊǦǉƽơǦǉừ,ǦƸƚǦǃƼườƾǦƼƾỏƾǦǤǄƶǃƽǦǉạǄ,ǦƸƚǦǃƼườƾǦƽọƸǦǋƅǦǉƽǊậǉ,ǦƸũǃƼǦƸƚǦǃƼườƾǦǃƼƽƾềǃǦǃƼẫǂǦǉǇướƸǦǉƑƸǦƷƑƸƽǦǃƼƽệ.",
    ["大家读过好些书，最喜欢的是哪句话？"] = "ƨọƾǦǃƼườƾǦđƃǦđọƸǦƷƶǄǦǃƽƾƙǊǦǈƑƸƽ,ǦǉƁǂǦđắƸǦǃƽấǉǦǁƐǦƸƁǊǦǃƐǄ?",
    ["我先来！“赴火蹈刃，死不还踵”，就是这股劲儿！"] = "ƞǄǃǦǉǇướƸ!Ǧ\"ƫƽƚǦƽỏƶǦđạǄǦǃƽậǃ,ǦǉửǦƷấǉǦƽǄƐǃǦƸƽủǃƼ\",ǦƸƽƓǃƽǦǁƐǦƸƑƾǦǀƽƓǦǉƽếǦǃƐǓ!",
    ["应是：“有力者疾以助人，有财者勉以分人，有道者劝以教人。”"] = "ƫƽảƾǦǁƐ:Ǧ\"ƣữǊǦǁựƸǦƼƾảǦǉậǉǦǤĩǦǉǇợǦǃƽƁǃ,ǦƽữǊǦǉƐƾǦƼƾảǦǂƾễǃǦǤĩǦǅƽƁǃǦǃƽƁǃ,ǦƽữǊǦđạǄǦƼƾảǦǀƽǊǓếǃǦǤĩǦƼƾƑǄǦǃƽƁǃ.\"",
    ["“捐躯赴国难，视死忽如归！”"] = "\"ƬǊǓƙǃǦǀƽǊǦǅƽƚǦǆǊốƸǦǃạǃ,ǦǉƽịǦǉửǦƽốǉǦǃƽưǦǆǊǓ!\"",
    ["“夫爱人者，人必从而爱之；利人者，人必从而利之。”"] = "\"ƫƽǊǦƑƾǦǃƽƁǃǦƼƾả,ǦǃƽƁǃǦǉấǉǦǉƛǃƼǦǃƽƾǦƑƾǦƸƽƾ;ǦǁợƾǦǃƽƁǃǦƼƾả,ǦǃƽƁǃǦǉấǉǦǉƛǃƼǦǃƽƾǦǁợƾǦƸƽƾ.\"",
    ["“星垂平野阔，月涌大江流。”"] = "\"ǥƾǃƽǦǉƽƖǓǦƷƔǃƽǦǤƃǦǀƽǄƑǉ,ǦǃƼǊǓệǉǦǤũǃƼǦđạƾǦƼƾƶǃƼǦǁưǊ.\"",
    ["“天地玄黄”……"] = "\"ǥƽƾƙǃǦđịƶǦƽǊǓềǃǦƽǄƐǃƼ\"……",
    ["好，好啊。书在我们身上，留下了好些印记。我们又把那些印记咀嚼、琢磨，写成了书。"] = "ǥốǉ,ǦǉốǉǦǁắǂ.ǦƮƑƸƽǦởǦǉǇƙǃǦǃƼườƾǦƸƽƕǃƼǦǉƶ,ǦđểǦǁạƾǦǇấǉǦǃƽƾềǊǦǤấǊǦấǃ.ǦƞƽƕǃƼǦǉƶǦǁạƾǦđƺǂǦǃƽữǃƼǦǤấǊǦấǃǦđƚǦǃƼƽƾềǃǦǃƼẫǂ,ǦƼọǉǦƼƾũƶ,ǦǋƾếǉǦǉƽƐǃƽǦǈƑƸƽ.",
    ["书页那样轻，比铠甲薄，比箭矢脆，经不得风吹雨淋，即便小心保存，不过百年便也朽化。"] = "ǥǇƶǃƼǦǈƑƸƽǦǃƽẹǦǃƽƐǃƼǦǃƽưǦǋậǓ,ǦǂỏǃƼǦƽơǃǦƼƾƑǅǦǉǇụ,ǦƼƾƛǃǦƽơǃǦǂũƾǦǉƙǃ,ǦǀƽƇǃƼǦƸƽịǊǦǃổƾǦǅƽǄǃƼǦƷƶǦƷƃǄǦǉƑǅ,ǦǤƖǦƸƚǦƸẩǃǦǉƽậǃǦƼƾữǦƼƔǃ,ǦƸƽẳǃƼǦǆǊƑǦǉǇăǂǦǃăǂǦƸũǃƼǦǈẽǦǂụƸǦǃƑǉ.",
    ["可千年前的所思所想，却由书到人，又从人到书，一代代传了下来，我们便能吟诵着那些文章，踏在他们的脚印上，再往前去。"] = "ƩƽưǃƼǦǃƽữǃƼǦǈǊǓǦǃƼƽĩǦǉừǦǃƼƐǃǦǃăǂǦǉǇướƸǦǁạƾǦǉƽƇǃƼǦǆǊƶǦǈƑƸƽǦǉǇǊǓềǃǦđếǃǦǃƼườƾ,ǦǇồƾǦǉừǦǃƼườƾǦǁạƾǦǋƐǄǦǈƑƸƽ,ǦđờƾǦđờƾǦǉǇǊǓềǃǦǉƽừƶ,ǦƸƽƕǃƼǦǉƶǦǂớƾǦƸƚǦǉƽểǦǃƼƁǂǦǃƼƶǦǃƽữǃƼǦƑǃƼǦǋăǃǦđƚ,ǦǋữǃƼǦƷướƸǦǉǇƙǃǦǤấǊǦƸƽƁǃǦƸủƶǦǉƾềǃǦǃƽƁǃǦǂƐǦǉƾếǃǦǋềǦǅƽƓƶǦǉǇướƸ.",
    ["往更好的地方去。"] = "ĐƾǦǉớƾǦǃƽữǃƼǦǃơƾǦǉốǉǦđẹǅǦƽơǃ.",
    ["书以载道，道以育人，人复著述，述又成书。传书，便是传火——"] = "ƮƑƸƽǦǤĩǦǉảƾǦđạǄ,ǦđạǄǦǤĩǦǤụƸǦǃƽƁǃ,ǦǃƽƁǃǦǅƽụƸǦǉǇướƸǦǉƽǊậǉ,ǦǉƽǊậǉǦƽựǊǦǉƽƐǃƽǦǉƽư.ǦǥǇǊǓềǃǦǈƑƸƽ,ǦƸƽƓǃƽǦǁƐǦǉǇǊǓềǃǦǁửƶ——",
    ["“鸿鹄高飞，一举千里”"] = "\"ƣồǃƼǦƽộƸǦƸƶǄǦǅƽƾ,ǦǃƽấǉǦƸửǦǉƽƾƙǃǦǁƈ\"",
    ["鹤院主……"] = "ƣạƸǦǋƾệǃǦƸƽủ……",
    ["小萝卜，你最喜欢书里的哪句话？"] = "ǥƾểǊǦƧƶǦƝặƸ,ǦƸǄǃǦǉƽƓƸƽǦǃƽấǉǦƸƁǊǦǃƐǄǦǉǇǄǃƼǦǈƑƸƽ?",
    ["是……是“暖衣饱食，便宁无忧”。"] = "ƧƐ……ǦǁƐǦ\"ƩǄƃǃǦǓǦƷƃǄǦǉƽựƸ,ǦǉƾệǃǦǃƾǃƽǦǋƇǦưǊ\".",
    ["人人都可以吃饱，穿暖，不会吵架，也没有战火，每天都开心……"] = "ƨọƾǦǃƼườƾǦđềǊǦƸƚǦǉƽểǦăǃǦǃǄ,ǦǂặƸǦấǂ,ǦǀƽƇǃƼǦƸƃƾǦǋƃ,ǦƸũǃƼǦǀƽƇǃƼǦƸƚǦǀƽƚƾǦǁửƶǦƸƽƾếǃǦǉǇƶǃƽ,ǦǃƼƐǓǦǃƐǄǦƸũǃƼǦǋǊƾǦǋẻ……",
    ["先生，对不起……我，我太贪玩，总想着以后再念书……"] = "ǥƾƙǃǦǈƾǃƽ,ǦǍƾǃǦǁỗƾǦǃƼườƾ……ǦƸǄǃ,ǦƸǄǃǦǆǊƑǦƽƶǂǦƸƽơƾ,ǦƸứǦǁǊƇǃǦǃƼƽĩǦđểǦǈƶǊǦǃƐǓǦǂớƾǦƽọƸ……",
    ["可是现在，书院要没了……我，我还没……"] = "ƩƽưǃƼǦƼƾờǦđƁǓ,ǦǉƽưǦǋƾệǃǦǈắǅǦǀƽƇǃƼǦƸƛǃǦǃữƶǦǇồƾ……ǦƸǄǃǦǋẫǃǦƸƽưƶ……",
    ["不急，等你出去了，往南边走。"] = "ƦƽƇǃƼǦƼấǅ,ǦđợƾǦƸǄǃǦǇƶǦǃƼǄƐƾǦǇồƾ,ǦƽƃǓǦđƾǦǋềǦǅƽƓƶǦƩƶǂ.",
    ["去墨山道，去文津馆，去青溪……想学什么都可以。"] = "ĐếǃǦƨặƸǦƮơǃǦĐạǄ,ǦđếǃǦƱăǃǦǥƁǃǦƬǊƑǃ,ǦđếǃǦǥƽƶǃƽǦƦƽƙ……ǦǂǊốǃǦƽọƸǦƼƔǦƸũǃƼǦđượƸ.",
    ["若是将来学成，或许还能得授号呢！"] = "ƩếǊǦǈƶǊǦǃƐǓǦƽọƸǦǉƽƐǃƽǦǉƐƾ,ǦƷƾếǉǦđƁǊǦƸƛǃǦđượƸǦƷƶǃǦƽƾệǊǦǃữƶǦđấǓ!",
    ["那我也可以叫鹤吗？"] = "ƱậǓǦƸǄǃǦƸũǃƼǦƸƚǦǉƽểǦƼọƾǦǁƐǦƣạƸǦǈƶǄ?",
    ["苗娃，秋娘……这儿好得很嘞，能吃饱饭、能好好种地嘞……"] = "ƨƾƙǊǦƪƶ,ǦǥƽǊǦƩươǃƼ……ǦǃơƾǦǃƐǓǦǉốǉǦǁắǂ,ǦƸƚǦƸơǂǦăǃǦǃǄ,ǦƸƚǦǉƽểǦǓƙǃǦổǃǦƸƐǓǦƸấǓ……",
    ["臭纨绔，好好识数吧！可别来日进了军营，手下兵卒几人都数不清，丢书院的脸。"] = "ǥƙǃǦƽǄƐǃǦǀƽốǦǉƽốƾǦǉƽƶ,ǦǁǄǦǂƐǦƽọƸǦđếǂǦƸƽǄǦƼƾỏƾǦđƾ!ǦĐừǃƼǦđểǦǂƶƾǦǃƐǓǦǋƐǄǦǆǊƁǃǦǤǄƶǃƽ,ǦǉƽǊộƸǦƽạǦƸƚǦǂấǓǦǉƙǃǦƷƾǃƽǦǉốǉǦƸũǃƼǦđếǂǦǀƽƇǃƼǦǍǄǃƼ,ǦǁƐǂǦǂấǉǦǂặǉǦǉƽưǦǋƾệǃ.",
    ["我可想好了，下山后回曲阳继续当马匪。这回要集个弓箭社，专锥虏人屁股，哈哈哈！"] = "ǥƶǦǃƼƽĩǦǀỹǦǇồƾ,ǦǍǊốǃƼǦǃƕƾǦǈẽǦǋềǦƦƽƕƸǦǝươǃƼǦǉƾếǅǦǉụƸǦǁƐǂǦǂƃǦǅƽỉ.ǦƧầǃǦǃƐǓǦǅƽảƾǦǁậǅǦǂộǉǦƸǊǃƼǦǉƾễǃǦǍƃ,ǦƸƽǊǓƙǃǦƷắǃǦǋƐǄǦǂƇǃƼǦǆǊƁǃǦƼƾặƸ,ǦƽƶǦƽƶǦƽƶ!",
    ["整个大殿……坠下去了……"] = "ƞảǦǉƛƶǦđạƾǦđƾệǃ……ǦǈụǅǦǍǊốǃƼǦǇồƾ……",
    ["屏山兄……他，已经故去了。你的仇……"] = "ƝƔǃƽǦƮơǃǦƽǊǓǃƽ……ǦƽǊǓǃƽǦấǓǦđƃǦǉạǦǉƽếǦǇồƾ.ǦƨốƾǦǉƽƖǦƸủƶǦǃƼươƾ……",
    ["我的仇，不必报了。"] = "ǥƽƖǦƸủƶǦǉƶ,ǦǀƽƇǃƼǦƸầǃǦƷƑǄǦǃữƶ.",
    ["……小时候我跟爹一起讨生活，日子苦，我爹却很爱笑，会给我买点心买糖葫芦，还会收留无家可归的孩子。"] = "……ƣồƾǦǃƽỏǦǉƶǦƸƖǃƼǦƸƽƶǦƷƇǃǦƷƶǦǀƾếǂǦǈốǃƼ,ǦǃƼƐǓǦǉƽƑǃƼǦǉǊǓǦǀƽổǦƸựƸǦǃƽưǃƼǦƸƽƶǦǉƶǦǇấǉǦƽƶǓǦƸườƾ,ǦǉƽườǃƼǦǂǊƶǦđƾểǂǦǉƁǂǦǋƐǦǀẹǄǦƽồǦǁƇǦƸƽǄǦǉƶ,ǦƸƛǃǦǉƽǊǦǃƽậǃǦǃƽữǃƼǦđứƶǦǉǇẻǦǀƽƇǃƼǦǃơƾǦǃươǃƼǦǉựƶ.",
    ["有一天，他出现了……那个叫鹤的家伙，杀了我爹，还说我爹是坏人……我恨他，我说我要杀了他给我爹报仇。"] = "ƨộǉǦǃƼƐǓǦǃọ,ǦƇǃƼǦǉƶǦǍǊấǉǦƽƾệǃ……ǦǀẻǦǉƙǃǦƣạƸǦđƚǦđƃǦƼƾếǉǦƸƽƶǦǉƶ,ǦƸƛǃǦǃƚƾǦƸƽƶǦǉƶǦǁƐǦǃƼườƾǦǍấǊ……ǦǥƶǦƽậǃǦƇǃƼǦǉƶ,ǦǉƶǦǃƚƾǦǉƶǦǈẽǦƼƾếǉǦƇǃƼǦǉƶǦđểǦƷƑǄǦǉƽƖǦƸƽǄǦƸƽƶ.",
    ["他却没有恼，只是把我寄养到一处人家，还留下两本墨门典籍，说待我长大，自可找他寻仇，他会等着我来。"] = "ƩƽưǃƼǦƇǃƼǦǉƶǦǀƽƇǃƼǦƽềǦƼƾậǃǦǤữ,ǦƸƽỉǦƼửƾǦǃǊƇƾǦǉƶǦởǦǂộǉǦǃƽƐǦǤƁǃ,ǦƸƛǃǦđểǦǁạƾǦƽƶƾǦƸǊốǃǦđƾểǃǦǉịƸƽǦƨặƸǦƨƇǃ,ǦǃƚƾǦđợƾǦǉƶǦǀƽƇǃǦǁớǃǦƸƚǦǉƽểǦǉƔǂǦƇǃƼǦǉƶǦƷƑǄǦǉƽƖ,ǦƇǃƼǦǉƶǦǈẽǦđợƾǦǉƶ.",
    ["待 me 学成，也寻到了他的行踪，却听闻世人对他多是褒赏。我不相信……我必须找到他，弄清楚，他究竟是怎样的人。"] = "ĐợƾǦǀƽƾǦǉƶǦƽọƸǦǉƽƐǃƽǦǉƐƾ,ǦƸũǃƼǦǉƔǂǦđượƸǦƽƐǃƽǦǉǊǃƼǦƸủƶǦƇǃƼǦǉƶ,ǦǃƽưǃƼǦǁạƾǦǃƼƽƺǦǃƼườƾǦđờƾǦǅƽầǃǦǁớǃǦǁƐǦǀƽƺǃǦǃƼợƾǦƇǃƼǦǉƶ.ǦǥƶǦǀƽƇǃƼǦǉƾǃ……ǦǉƶǦǅƽảƾǦǉƔǂǦđượƸǦƇǃƼǦǉƶ,ǦǁƐǂǦƸƽǄǦǇƅǦǇƐǃƼǦǇốǉǦƸǊộƸǦƇǃƼǦǉƶǦǁƐǦƽạǃƼǦǃƼườƾǦƼƔ.",
    ["现在，我知道了。"] = "ƢƾờǦđƁǓ,ǦǉƶǦƷƾếǉǦǇồƾ.",
    ["此间诸事，我自会昭之于众。鹤院主与留守封龙的诸位弟子以身著书，誓死未退。"] = "ƨọƾǦƸƽǊǓệǃǦǃơƾǦđƁǓ,ǦǉƶǦǉựǦǈẽǦƸƇǃƼǦǀƽƶƾǦƸƽǄǦǉƽƾƙǃǦƽạǦƷƾếǉ.ǦƣạƸǦǋƾệǃǦƸƽủǦƸƖǃƼǦƸƑƸǦđệǦǉửǦǁưǊǦǉƽủǦƫƽǄǃƼǦƧǄǃƼǦđƃǦǁấǓǦǉƽƁǃǦǁƐǂǦǈƑƸƽ,ǦǉƽềǦƸƽếǉǦǀƽƇǃƼǦǁƖƾ.",
    ["屏山兄！"] = "ƝƔǃƽǦƮơǃǦƽǊǓǃƽ!",
    ["还有何事？"] = "ƞƛǃǦƸƽǊǓệǃǦƼƔǦǃữƶ?",
    ["你的印信。"] = "ẤǃǦǉƓǃǦƸủƶǦǃƼươƾ.",
    ["我吗？我只想待在书院帮帮忙，得闲就当个书虫好了。"] = "ǥƶǦǈƶǄ?ǦǥƶǦƸƽỉǦǂǊốǃǦởǦǁạƾǦǉƽưǦǋƾệǃǦƼƾƕǅǦǂộǉǦǉƶǓ,ǦǁƕƸǦǇảǃƽǦǇỗƾǦǉƽƔǦǁƐǂǦǂộǉǦƸǄǃǦǂọǉǦǈƑƸƽǦǁƐǦđượƸǦǇồƾ.",
    ["穷酸鬼！小爷再待一年，书准念得比你好！"] = "ĐồǦǃƼƽƘǄǦǀƾếǉǦǍƑƸ!ǦǥƾểǊǦƼƾƶǦởǦǁạƾǦǉƽƙǂǦǂộǉǦǃăǂ,ǦƽọƸǦƽƐǃƽǦƸƽắƸǦƸƽắǃǦǈẽǦƼƾỏƾǦƽơǃǦǃƼươƾ!",
    ["书院倒是有些有意思的东西，怎么战场上没看见过？"] = "ǥƽưǦǋƾệǃǦǃƐǓǦƸƚǦǂấǓǦǉƽứǦǀƽƑǦǉƽƕǦǋị,ǦǈƶǄǦǉǇƙǃǦƸƽƾếǃǦǉǇườǃƼǦǁạƾǦƸƽưƶǦǉừǃƼǦǉƽấǓǦǆǊƶǦǃƽỉ?",
    ["有确切消息了吗？"] = "ĐƃǦƸƚǦǉƾǃǦǉứƸǦǍƑƸǦǉƽựƸǦƸƽưƶ?",
    ["耶律起"] = "ǝƶǦƧǊậǉǦƦƽởƾ",
    ["嗐，晋军放军营里吃灰呢，现在也是我们的了。"] = "ƣạƾ,ǦǆǊƁǃǦǥấǃǦǋứǉǦǍăǂǦǍắǅǦǉǇǄǃƼǦǆǊƁǃǦǤǄƶǃƽǦđểǦƷƑǂǦƷụƾǦđấǓǦǉƽƇƾ,ǦƼƾờǦǉƽƔǦđềǊǦǁƐǦƸủƶǦƸƽƕǃƼǦǉƶǦƸảǦǇồƾ.",
    ["他那些古怪木头确实难对付，你死在他手上不冤。"] = "ƨấǓǦǉƽứǦƼỗǦǀỳǦǆǊƑƾǦđƚǦƸủƶǦǁƃǄǦǉƶǦǆǊảǦǉƽựƸǦǀƽƚǦđốƾǦǅƽƚ,ǦǃƼươƾǦƸƽếǉǦǤướƾǦǉƶǓǦǁƃǄǦƸũǃƼǦǀƽƇǃƼǦǄƶǃ.",
    ["契丹勇士"] = "ǝũǃƼǦǈĩǦƦƽƾếǉǦĐƶǃ",
    ["嘶……他死前还给我一刀。呵，中原也是有汉子的……"] = "ƳǊƈǉ……ǦǁƃǄǦǉƶǦǉǇướƸǦǀƽƾǦƸƽếǉǦƸƛǃǦƷồƾǦƸƽǄǦǉƶǦǂộǉǦđƶǄ.Ǧƣừ,ǦǥǇǊǃƼǦƩƼǊǓƙǃǦƸũǃƼǦƸƚǦǃƽữǃƼǦǃƶǂǦǉửǦƽƑǃǦđấǓ……",
    ["……那王清将军，可是天底下顶顶厉害的大英雄！"] = "……ƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃǦđƚ,ǦƸƽƓǃƽǦǁƐǦđạƾǦƶǃƽǦƽƖǃƼǦǁợƾǦƽạƾǦǃƽấǉǦǉƽƾƙǃǦƽạ!",
    ["他克襄州、守邺县、救阳城，打得虏人满地乱爬呢！"] = "ƩƼƐƾǦấǓǦǀƽắƸǦǥươǃƼǦƞƽƁǊ,ǦǉƽủǦƩƼƽƾệǅǦƣǊǓệǃ,ǦƸứǊǦǝươǃƼǦǥƽƐǃƽ,ǦđƑǃƽǦƸƽǄǦǆǊƁǃǦƼƾặƸǦƷƛǦǁƙǦƷƛǦƸƐǃƼǦǉǇƙǃǦđấǉ!",
    ["真、真有这么厉害？"] = "ǥƽậǉ,ǦǉƽậǉǦǁợƾǦƽạƾǦđếǃǦǉƽếǦǈƶǄ?",
    ["那当然！我爹爹亲眼看到的！他还说呀，如今全天下的英雄，都在往这儿赶，要一口气把虏人打回老家去！"] = "ǥấǉǦǃƽƾƙǃǦǇồƾ!ǦƞƽƶǦǉƶǦǉậǃǦǂắǉǦǃƽƔǃǦǉƽấǓǦǂƐ!ǦƩƼườƾǦƸƛǃǦǃƚƾǦǃƽƶ,ǦƽƾệǃǦƼƾờǦƶǃƽǦƽƖǃƼǦǀƽắǅǦǉƽƾƙǃǦƽạǦđềǊǦđƶǃƼǦđổǦǤồǃǦǋềǦđƁǓ,ǦǂǊốǃǦǂộǉǦƽơƾǦđƑǃƽǦđǊổƾǦǆǊƁǃǦƼƾặƸǦǋềǦǉậǃǦǁƃǄǦǈƐǄ!",
    ["哇~真的吗？全天下的英雄呀~"] = "ƪƶ~ǦǉƽậǉǦǈƶǄ?ǦƜǃƽǦƽƖǃƼǦǀƽắǅǦǉƽƾƙǃǦƽạǦǈƶǄ~",
    ["众孩童"] = "ƧũǦǉǇẻ",
    ["那我们是不是也能回家去了？我娘给我做的烧饼，还落在桌上呢……"] = "ƱậǓǦƸƚǦǅƽảƾǦƸƽƕǃƼǦǉƶǦƸũǃƼǦǈắǅǦđượƸǦǋềǦǃƽƐǦǇồƾǦǀƽƇǃƼ?ǦƝƑǃƽǦǃướǃƼǦǃươǃƼǦǁƐǂǦƸƽǄǦƸǄǃǦǋẫǃǦƸƛǃǦđểǦǉǇƙǃǦƷƐǃǦđấǓ……",
    ["小果儿"] = "ǥƾểǊǦƬǊảǦƩƽƾ",
    ["能！烧饼、酥鱼、饸饹，到时候想吃啥就有啥！还能捡虏人的刀子，割驴肉做火烧呢！"] = "ĐượƸǦƸƽứ!ǦƝƑǃƽǦǃướǃƼ,ǦƸƑǦǇƑǃ,ǦǂƔǦǂễ,ǦđếǃǦǁƕƸǦđƚǦǂǊốǃǦăǃǦƼƔǦƸƚǦǃấǓ!ǦƞƛǃǦƸƚǦǉƽểǦǃƽặǉǦđƶǄǦƸủƶǦǆǊƁǃǦƼƾặƸǦđểǦƸắǉǦǉƽịǉǦǁừƶǦǁƐǂǦƷƑǃƽǦƽỏƶǦǉƽƾƙǊǦǃữƶ!",
    ["咕咕咕——"] = "ƢƖǦƼƖǦƼƖ——",
    ["哈哈哈！肚子又叫啦！就你不扛饿！"] = "ƣƶǦƽƶǦƽƶ!ǦƝụǃƼǦǁạƾǦǀƙǊǦǇồƾ!ǦƞƽỉǦƸƚǦǃƼươƾǦǁƐǦǀƽƇǃƼǦƸƽịǊǦǃổƾǦđƚƾ!",
    ["那、那大英雄什么时候来呀？"] = "ƱậǓ,ǦǋậǓǦƷƶǄǦƼƾờǦđạƾǦƶǃƽǦƽƖǃƼǦǂớƾǦǉớƾǦạ?",
    ["喏，那不就来了吗！"] = "ƩƐǓ,ǦƸƽẳǃƼǦǅƽảƾǦǉớƾǦǇồƾǦđƚǦǈƶǄ!",
    ["大侠大侠，你也是来赴约讨虏的吗？"] = "ĐạƾǦƽƾệǅǦđạƾǦƽƾệǅ,ǦǃƼườƾǦƸũǃƼǦǉớƾǦǅƽƚǦướƸǦǉƽảǄǦǅƽạǉǦǆǊƁǃǦƼƾặƸǦǈƶǄ?",
    ["今天来了好几拨嘞！嗯……有佩剑大侠、带刀大侠、盲眼大侠、胡子大侠、木鸟大侠……"] = "ƣƇǂǦǃƶǓǦƸƚǦǂấǓǦǉǄƑǃǦǃƼườƾǦǉớƾǦǇồƾǦđƚ!ǦỪǂ……ǦƸƚǦđạƾǦƽƾệǅǦđƺǄǦǀƾếǂ,ǦđạƾǦƽƾệǅǦǂƶǃƼǦđƶǄ,ǦđạƾǦƽƾệǅǦǂƖ,ǦđạƾǦƽƾệǅǦǇƁǊǦǤƐƾ,ǦđạƾǦƽƾệǅǦǂộƸǦđƾểǊ……",
    ["他们可还在此地？"] = "ƣọǦǋẫǃǦƸƛǃǦởǦǃơƾǦǃƐǓǦƸƽứ?",
    ["就在前面，那棵大树下、篝火旁，就是啦！"] = "ƩƼƶǓǦǅƽƓƶǦǉǇướƸǦǉƽƇƾ,ǦǤướƾǦƼốƸǦƸƁǓǦđạƾǦǉƽụǦƷƙǃǦđốǃƼǦǁửƶǦđƚ!",
    ["杜大帅咱之前是跟过的，人家也是平过叛、驱过虏，打过大胜仗的功臣！"] = "ĐỗǦđạƾǦǈǄƑƾǦǉǇướƸǦǀƾƶǦǉƶǦǉừǃƼǦđƾǦǉƽƺǄ,ǦǃƼườƾǦǉƶǦƸũǃƼǦǁƐǦƸƇǃƼǦǉƽầǃǦǉừǃƼǦƷƔǃƽǦđịǃƽǦǅƽảǃǦǁǄạǃ,ǦǍǊƶǦđǊổƾǦǆǊƁǃǦƼƾặƸ,ǦđƑǃƽǦǉƽắǃƼǦǃƽữǃƼǦǉǇậǃǦǁớǃ!",
    ["哎，听说中渡桥又被虏人毁了？那后续兵马如何去支援王将军？"] = "ƞƽƶǄǦƇƾ,ǦǃƼƽƺǦǃƚƾǦǥǇǊǃƼǦĐộǦƦƾềǊǦǁạƾǦƷịǦǆǊƁǃǦƼƾặƸǦǅƽƑǦƽủǓǦǇồƾ?ǦǥƽếǦǉƽƔǦƷƾǃƽǦǂƃǦǅƽƓƶǦǈƶǊǦǁƐǂǦǈƶǄǦǉớƾǦƸƽƾǦǋƾệǃǦƸƽǄǦƱươǃƼǦǉướǃƼǦǆǊƁǃǦđượƸ?",
    ["从前是从前，现如今他那军营没个动静，要我说，这心思啊，难猜……"] = "ǥǇướƸǦǀƾƶǦǁƐǦǉǇướƸǦǀƾƶ,ǦƽƾệǃǦǃƶǓǦǆǊƁǃǦǤǄƶǃƽǦƸủƶǦǁƃǄǦǉƶǦƸƽẳǃƼǦƸƚǦƸƽƕǉǦđộǃƼǦǉĩǃƽǦƼƔ,ǦǉƶǦǃƚƾǦǃƽƶ,ǦǉƁǂǦǉưǦǃƐǓǦǆǊảǦǉƽậǉǦǀƽƚǦđǄƑǃ……",
    ["我看来了好些墨门弟子，想是被请来修桥的？"] = "ǥƶǦǉƽấǓǦƸƚǦǀƽƑǦǃƽƾềǊǦđệǦǉửǦƨặƸǦƨƇǃǦǉớƾ,ǦƸƽắƸǦǁƐǦđượƸǦǂờƾǦǉớƾǦđểǦǈửƶǦƸầǊ?",
    ["你懂什么，带兵打仗，讲究一个韬光养晦、一击制敌！而今时机未到呢——"] = "ƩƼươƾǦǉƽƔǦƷƾếǉǦƸƑƾǦƼƔ,ǦƸầǂǦǆǊƁǃǦđƑǃƽǦƼƾặƸǦƸốǉǦởǦƸƽỗǦǉƽƶǄǦǆǊƶǃƼǦǤưỡǃƼǦƽốƾ,ǦǃƽấǉǦǀƓƸƽǦƸƽếǦđịƸƽ!ǦƢƾờǦǉƽờƾǦƸơǦƸƽưƶǦǉớƾǦǉƽƇƾ——",
    ["碧老头，可葬下了？"] = "ƝƓƸƽǦǁƃǄǦđầǊ,ǦđƃǦƶǃǦǉƑǃƼǦǍǄǃƼǦƸƽưƶ?",
    ["葬下了，秀姑那丫头，一把野菜接一把野菜地薅啊，抠了满手的血，才总算换了张薄席子。"] = "ƞƽƇǃǦƸấǉǦǇồƾ,ǦƸǄǃǦƷƗǦǥƕǦƞƇǦđƚ,ǦƸứǦƷớƾǦǉừǃƼǦǃắǂǦǇƶǊǦǤạƾǦǂộǉ,ǦđƐǄǦđếǃǦǂứƸǦǂƑǊǦƸƽảǓǦđầǓǦǉƶǓ,ǦǂớƾǦđổƾǦđượƸǦǂộǉǦǉấǂǦƸƽƾếǊǦǂỏǃƼ.",
    ["又有大侠来了，俺们有救了。"] = "ƧạƾǦƸƚǦđạƾǦƽƾệǅǦǉớƾǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦƸƚǦƸứǊǦǇồƾ.",
    ["唉，命苦呦，打小没了娘，如今爹又叫虏人给……"] = "ƞƽƶǄǦƇƾ,ǦǂệǃƽǦǀƽổǦǆǊƑ,ǦǉừǦǃƽỏǦđƃǦǂấǉǦǂẹ,ǦƼƾờǦƸƽƶǦǁạƾǦƷịǦǆǊƁǃǦƼƾặƸǦǈƑǉǦƽạƾ……",
    ["哎，实在是走不动了。虏人再追来，只能就地扯一床席子，当棺材喽。"] = "ƣƶƾǏǏ,ǦǉƽựƸǦǈựǦǁƐǦđƾǦƽếǉǦǃổƾǦǇồƾ.ǦƬǊƁǃǦƼƾặƸǦǂƐǦđǊổƾǦǉớƾ,ǦƸƽỉǦƸƚǦǃướƸǦǋơǦǉạǂǦǂảǃƽǦƸƽƾếǊǦǁƐǂǦǆǊƶǃǦǉƐƾǦǉƽƇƾ.",
    ["娘，这旁边军帐，是杜帅的大营，有他守着，您就放心吧！"] = "ƩươǃƼ,ǦǉǇướǃƼǦǉǇạƾǦƷƙǃǦƸạǃƽǦǃƐǓǦǁƐǦđạƾǦǤǄƶǃƽǦƸủƶǦĐỗǦǈǄƑƾ,ǦƸƚǦǃƼƐƾǦấǓǦǉǇấǃǦǉƽủ,ǦǃƼườƾǦƸứǦǓƙǃǦǉƁǂǦđƾ!",
    ["要说这王清将军抢渡滹沱河，当真是一妙策。"] = "ƫƽảƾǦǃƚƾǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃǦƸưỡǃƼǦđộǦǈƇǃƼǦƣƇǦĐƐǦǆǊảǦǉƽựƸǦǁƐǦǂộǉǦǤƾệǊǦǀế.",
    ["可不是，先遣军跨过中渡桥，撕开一道口子。后面的大军再跟上，一齐挺进恒州城——"] = "ƞƽứǦƸƛǃǦƼƔǦǃữƶ,ǦǉƾềǃǦǆǊƁǃǦǋượǉǦǆǊƶǦǥǇǊǃƼǦĐộǦƦƾềǊ,ǦǍƗǦǇƶǦǂộǉǦǁỗǦƽổǃƼ.ǦĐạƾǦǆǊƁǃǦǅƽƓƶǦǈƶǊǦǉƽƺǄǦđƚǦǉƾếǃǦǁƙǃ,ǦƸƖǃƼǦǃƽƶǊǦǉƾếǃǦđƑǃƽǦƣằǃƼǦƞƽƁǊǦǉƽƐǃƽ——",
    ["那营孤食尽的局面，不就解了！"] = "ƞƑƾǦǉƽếǦǉǇậǃǦǤǄƶǃƽǦƸƇǦǁươǃƼǦǀƾệǉǦƸƽẳǃƼǦǅƽảƾǦǈẽǦđượƸǦƼƾảƾǦǉỏƶǦǈƶǄ!",
    ["封龙那边有消息吗？"] = "ƫƽƓƶǦƫƽǄǃƼǦƧǄǃƼǦƸƚǦǉƾǃǦǉứƸǦƼƔǦƸƽưƶ?",
    ["说鹤长老仍未回院，他们也失了联络。好在近日已派了不少弟子，护送周边流民，往南边的邢州、磁州安置。"] = "ƩƼƽƺǦǃƚƾǦƣạƸǦǉǇưởǃƼǦǁƃǄǦǋẫǃǦƸƽưƶǦǋềǦǋƾệǃ,ǦƽọǦƸũǃƼǦǂấǉǦǁƾƙǃǦǁạƸǦǁǊƇǃǦǇồƾ.ǦƨƶǓǦǂƐǦƼầǃǦđƁǓǦđƃǦǅƽƑƾǦǀƽƇǃƼǦƓǉǦđệǦǉửǦƽộǦǉốǃƼǦǁưǊǦǤƁǃǦǍǊǃƼǦǆǊƶǃƽǦǉớƾǦƣƔǃƽǦƞƽƁǊ,ǦǥừǦƞƽƁǊǦởǦǅƽƓƶǦƩƶǂǦđểǦƶǃǦǉǇƓ.",
    ["大营的内线，可有消息？"] = "ƩộƾǦǉǊǓếǃǦǉǇǄǃƼǦđạƾǦǤǄƶǃƽǦƸƚǦǉƾǃǦƼƔǦǀƽƇǃƼ?",
    ["文津馆的林、萧二位已经入营，想必此时已与杜帅相见了。"] = "ƣƶƾǦǋịǦƧƁǂ,ǦǥƾƙǊǦƸủƶǦƱăǃǦǥƁǃǦƬǊƑǃǦđƃǦǋƐǄǦǤǄƶǃƽ,ǦƸƽắƸǦƽẳǃǦǁƕƸǦǃƐǓǦđƃǦƼặǅǦđượƸǦĐỗǦǈǄƑƾǦǇồƾ.",
    ["只是……军兵列阵多时，王将军的求援信也入了营帐，却总不见发兵的讯号……不知他在等什么……"] = "ƞƽỉǦǁƐ……ǦǆǊƁǃǦƷƾǃƽǦđƃǦǤƐǃǦǉǇậǃǦƽồƾǦǁƁǊ,ǦǉƽưǦƸầǊǦǋƾệǃǦƸủƶǦƱươǃƼǦǉướǃƼǦǆǊƁǃǦƸũǃƼǦđƃǦđưƶǦǋƐǄǦǉǇướǃƼ,ǦǃƽưǃƼǦǂƃƾǦƸƽẳǃƼǦǉƽấǓǦǉƓǃǦƽƾệǊǦǅƽƑǉǦƷƾǃƽ……ǦǀƽƇǃƼǦƷƾếǉǦǁƃǄǦǉƶǦđƶǃƼǦƸƽờǦđợƾǦđƾềǊǦƼƔ……",
    ["这杜重威也是有头有脸的人物，总不至于要当缩头王八吧？"] = "ĐỗǦǥǇọǃƼǦǕǓǦǃƐǓǦƸũǃƼǦǁƐǦǃƽƁǃǦǋậǉǦƸƚǦǂƑǊǦǂặǉ,ǦƸƽẳǃƼǦǁẽǦǁạƾǦǂǊốǃǦǁƐǂǦǇƖƶǦǇụǉǦƸổǦǈƶǄ?",
    ["哼，王八有什么不好，王八活万年呐！"] = "ƣừ,ǦǇƖƶǦǉƽƔǦƸƚǦƼƔǦǀƽƇǃƼǦǉốǉ,ǦǇƖƶǦǈốǃƼǦǋạǃǦǃăǂǦƸơǦđấǓ!",
    ["要说那姓杜的靠不住，林家娃娃想与虎谋皮，难呐。"] = "ǥƶǦǃƚƾǦǃƐǓ,ǦǀẻǦƽọǦĐỗǦđƚǦǀƽƇǃƼǦđƑǃƼǦǉƾǃǦđƁǊ,ǦǂấǓǦđứƶǦǃƽỏǦǃƽƐǦƽọǦƧƁǂǦǂǊốǃǦǂưǊǦǈựǦǋớƾǦƽổ,ǦǀƽƚǦǁắǂǦǉƽƶǓ.",
    ["凡事，还得靠自个儿这把刀。"] = "ƫƽƐǂǦǁƐǦƸƽǊǓệǃǦƼƔ,ǦƸũǃƼǦǅƽảƾǦǤựƶǦǋƐǄǦǉƽƶǃƽǦđƶǄǦƸủƶǦƸƽƓǃƽǦǂƔǃƽǦǉƽƇƾ.",
    ["你那内线，可靠？"] = "ƩộƾǦǉǊǓếǃǦđƚǦƸủƶǦǃƼươƾ,ǦƸƚǦđƑǃƼǦǉƾǃǦǀƽƇǃƼ?",
    ["那小子……是为了他爹。不会骗我。"] = "ǥƽằǃƼǦǃƽƚƸǦđƚ……ǦǁƐǦǋƔǦƸƽƶǦǃƚ.ǦƮẽǦǀƽƇǃƼǦǁừƶǦǉƶǦđƁǊ.",
    ["野菜汤好了，大伙儿快暖暖身子吧。"] = "ƞƶǃƽǦǇƶǊǦǤạƾǦǍǄǃƼǦǇồƾ,ǦǂọƾǦǃƼườƾǦǂƶǊǦǁƐǂǦấǂǦǃƼườƾǦđƾ.",
    ["碧水秀"] = "ƝƓƸƽǦǥƽủǓǦǥƕ",
    ["同道人，去喝一碗吧，今天可有得打呢。"] = "ƩƼườƾǦƸƖǃƼǦđạǄ,ǦđƾǦǊốǃƼǦǂộǉǦƷƑǉǦđƾ,ǦƽƇǂǦǃƶǓǦƸƛǃǦƸƚǦǉǇậǃǦđểǦđƑǃƽǦđấǓ.",
    ["姑娘这野菜汤可真不赖！比朴丐那小子做的强多了！"] = "ƞƶǃƽǦǇƶǊǦǤạƾǦƸủƶǦƸƇǦǃươǃƼǦǉƽậǉǦǀƽƇǃƼǦǉệ!ǦƨạǃƽǦƽơǃǦǃƽƾềǊǦǈǄǦǋớƾǦǉƽứǦǉƽằǃƼǦǃƽƚƸǦƫƽƑƸǦƞƑƾǦǁƐǂ!",
    ["当下没什么好东西，委屈各位大侠了。等打跑了虏人，进了恒州，我给大家做咱本地的花样菜！"] = "ƧƕƸǦǃƐǓǦǀƽƇǃƼǦƸƚǦđồǦƼƔǦǃƼǄǃ,ǦǁƐǂǦủǓǦǀƽǊấǉǦƸƑƸǦǋịǦđạƾǦƽƾệǅǦǇồƾ.ǦĐợƾǦđƑǃƽǦđǊổƾǦđượƸǦǆǊƁǃǦƼƾặƸ,ǦǋƐǄǦđượƸǦƣằǃƼǦƞƽƁǊ,ǦǉƶǦǈẽǦǁƐǂǦǂƚǃǦđặƸǦǈảǃǦđịƶǦǅƽươǃƼǦƸƽǄǦǂọƾǦǃƼườƾǦăǃ!",
    ["恒州、恒州都有些什么吃的？"] = "ƣằǃƼǦƞƽƁǊ,ǦƣằǃƼǦƞƽƁǊǦƸƚǦǂƚǃǦƼƔǦăǃǦǃƼǄǃǦǀƽƇǃƼ?",
    ["有荷包里脊，酱驴肉，缸炉烧饼，水晶鸡片，还有——"] = "ƞƚǦǉƽăǃǦǁợǃǦƷƶǄǦǁụƶ,ǦǉƽịǉǦǁừƶǦǀƽǄǦǉƐǊ,ǦƷƑǃƽǦǃướǃƼǦǁƛǦǁǊ,ǦƼƐǦǁƑǉǦǉƽủǓǦǉƾǃƽ,ǦƸƛǃǦƸƚ——",
    ["那我要吃荷包里脊！"] = "ƱậǓǦǉƶǦǂǊốǃǦăǃǦǉƽăǃǦǁợǃǦƷƶǄǦǁụƶ!",
    ["我要酱驴肉！"] = "ǥƶǦǂǊốǃǦăǃǦǉƽịǉǦǁừƶǦǀƽǄǦǉƐǊ!",
    ["我，还有我……"] = "ǥƶǦǃữƶ,ǦƸƛǃǦƸƚǦǉƶ……",
    ["诶，木头师弟，别老板着个冰块脸，说说，你想吃什么？"] = "Ê,ǦƨộƸǦĐầǊǦǈưǦđệ,ǦđừǃƼǦƸƚǦǁƕƸǦǃƐǄǦƸũǃƼǦǉǇưǃƼǦǇƶǦƸƑƾǦƷộǦǂặǉǦƷăǃƼǦǉảǃƼǦđƚǦǃữƶ,ǦǃƚƾǦǍƺǂ,ǦđệǦǂǊốǃǦăǃǦƼƔ?",
    ["那，那大侠再来一碗汤吧。"] = "ƱậǓ,ǦǋậǓǦđạƾǦƽƾệǅǦǊốǃƼǦǉƽƙǂǦƷƑǉǦƸƶǃƽǦǃữƶǦđƾ.",
    ["不了，谢谢。"] = "ƦƽƇǃƼǦƸầǃǦđƁǊ,ǦđƶǦǉạ.",
    ["这么好喝的汤，也叫大家伙儿过来尝尝。"] = "ƞƶǃƽǦǃƼǄǃǦǉƽếǦǃƐǓ,ǦƸũǃƼǦǃƙǃǦƼọƾǦǂọƾǦǃƼườƾǦǁạƾǦđƁǓǦǃếǂǦǉƽửǦǂộǉǦƸƽƕǉ.",
    ["打仗前还能有碗热的，啧啧，香嘞。"] = "ǥǇướƸǦǀƽƾǦđƑǃƽǦǉǇậǃǦǂƐǦƸƛǃǦƸƚǦƷƑǉǦƸƶǃƽǦǃƚǃƼ,ǦƸƽậƸǦƸƽậƸ,ǦǉƽơǂǦǉƽậǉ.",
    ["他啊……是我兄弟家的小子。我和他爹，是过了几遭命的交情了。"] = "ǥƽằǃƼǦƷƗǦđƚǦƐ……ǦǁƐǦƸǄǃǦǉǇƶƾǦƸủƶǦƽǊǓǃƽǦđệǦǉƶ.ǦǥƶǦǋƐǦƸƽƶǦǃƚǦǁƐǦǉƔǃƽǦƼƾƶǄǦƽữǊǦǋƐǄǦǈƾǃƽǦǇƶǦǉửǦǂấǓǦǅƽƺǃǦǇồƾ.",
    ["打小机灵，原是大好的前程，可惜——"] = "ǥừǦǃƽỏǦđƃǦǁƶǃƽǦǁợƾ,ǦǋốǃǦǤĩǦƸƚǦǉƾềǃǦđồǦǇộǃƼǦǂở,ǦđƑǃƼǦǉƾếƸ——",
    ["哎，欠他爷俩太多，我这辈子，债是难还了。"] = "ƣƶƾǏǏ,ǦǃợǦƽƶƾǦƸƽƶǦƸǄǃǦƽọǦǆǊƑǦǃƽƾềǊ,ǦǀƾếǅǦǃƐǓǦƸủƶǦǉƶ,ǦǂƚǃǦǃợǦǃƐǓǦǀƽƚǦǁƛǃƼǦǉǇảǦǃổƾ.",
    ["磨箭簇。头儿总说，自己的命得自己惜。手里的箭杀不死人，该死的就是自己了。"] = "ƨƐƾǦǂũƾǦǉƙǃ.ǦĐạƾǦƸƶǦǁǊƇǃǦǃƚƾ,ǦǂạǃƼǦƸủƶǦǂƔǃƽǦǉƽƔǦǂƔǃƽǦǅƽảƾǦƷƾếǉǦǆǊƈǦǉǇọǃƼ.ǦǥƙǃǦǉǇǄǃƼǦǉƶǓǦǂƐǦǀƽƇǃƼǦƼƾếǉǦđượƸǦǃƼườƾ,ǦǉƽƔǦǃƼườƾǦǅƽảƾǦƸƽếǉǦƸƽƓǃƽǦǁƐǦǂƔǃƽ.",
    ["你是当兵的？"] = "ƩƼươƾǦǁƐǦǁƓǃƽǦǈƶǄ?",
    ["算是吧，不过是收钱的那种。"] = "ƞũǃƼǦƸǄƾǦǁƐǦǋậǓǦđƾ,ǦǃƽưǃƼǦǁƐǦǁǄạƾǦǉƽǊǦǉƾềǃǦǁƐǂǦǋƾệƸ.",
    ["滹沱，有人雇你？"] = "ƣƇǦĐƐ,ǦƸƚǦǃƼườƾǦǉƽǊƙǦǃƼươƾǦǈƶǄ?",
    ["没。头儿说，这趟是亏本的买卖，愿意来的就跟着来。"] = "ƦƽƇǃƼǦƸƚ.ǦĐạƾǦƸƶǦǃƚƾǦƸƽǊǓếǃǦǃƐǓǦǁƐǦǋụǦǁƐǂǦăǃǦǉƽǊƶǦǁỗ,ǦƶƾǦǃƼǊǓệǃǦƈǦǉƽƔǦđƾǦǉƽƺǄ.",
    ["我的命是他给的，他到哪我到哪。结果，他把自个儿亏这儿了。"] = "ƨạǃƼǦƸủƶǦǉƇƾǦǁƐǦƶǃƽǦấǓǦƸƽǄ,ǦƶǃƽǦấǓǦđƾǦđƁǊǦǉƇƾǦđƾǦđƚ.ǦƦếǉǦƸụƸ,ǦƶǃƽǦấǓǦǁạƾǦƷỏǦǂạǃƼǦởǦǃơƾǦǃƐǓǦǇồƾ.",
    ["小妹妹，去喝一碗吗？"] = "ǥƾểǊǦǂǊộƾǦǂǊộƾ,ǦđƾǦǊốǃƼǦǂộǉǦƷƑǉǦǀƽƇǃƼ?",
    ["思思不饿，还是留给大侠们喝吧。"] = "ǥưǦǥưǦǀƽƇǃƼǦđƚƾ,ǦǋẫǃǦǁƐǦđểǦǤƐǃƽǦƸƽǄǦƸƑƸǦǋịǦđạƾǦƽƾệǅǦǊốǃƼǦđƾǦạ.",
    ["大侠，你到这么远的地方来，会想家人吗？"] = "ĐạƾǦƽƾệǅ,ǦǃƼườƾǦǉừǦǃơƾǦǍƶǦǍƇƾǦǃƽưǦǋậǓǦǉớƾǦđƁǓ,ǦƸƚǦǃƽớǦǃƼườƾǦǉƽƁǃǦǀƽƇǃƼ?",
    ["思思也想，思思已经好几天没见过爹爹了。"] = "ǥưǦǥưǦƸũǃƼǦǃƽớ,ǦǥưǦǥưǦđƃǦǂấǓǦǃƼƐǓǦǇồƾǦƸƽưƶǦđượƸǦƼặǅǦƸƽƶ.",
    ["爹爹在哪？"] = "ƞƽƶǦƸǄǃǦởǦđƁǊ?",
    ["爹爹就在军营里，他是打虏人的英雄，很忙很忙的。"] = "ƞƽƶǦởǦǃƼƶǓǦǉǇǄǃƼǦǆǊƁǃǦǤǄƶǃƽǦǉƽƇƾ,ǦǃƼườƾǦǁƐǦƶǃƽǦƽƖǃƼǦđƑǃƽǦǆǊƁǃǦƼƾặƸ,ǦƷậǃǦǇộǃǦǁắǂǦạ.",
    ["所以，暂时见不到也没关系。"] = "ƞƽǄǦǃƙǃ,ǦǉạǂǦǉƽờƾǦǀƽƇǃƼǦƼặǅǦđượƸǦƸũǃƼǦǀƽƇǃƼǦǈƶǄǦạ.",
    ["等打完仗，他就回家啦。"] = "ĐợƾǦđƑǃƽǦǍǄǃƼǦǉǇậǃ,ǦǃƼườƾǦǈẽǦǋềǦǃƽƐǦǉƽƇƾ.",
    ["同袍。"] = "ĐồǃƼǦƷƐǄ.",
    ["这酒囊里……好香的酒!"] = "ǥǇǄǃƼǦƷầǊǦǇượǊǦǃƐǓ……ǦǇượǊǦǉƽơǂǦǆǊƑ!",
    ["我师父酿的，给。"] = "ƮưǦǅƽụǦǉƶǦủǦđấǓ,ǦƸƽǄǦƽǊǓǃƽǦǃƐǓ.",
    ["咳咳、好烈……"] = "ƦƽụǦǀƽụ,ǦǂạǃƽǦǆǊƑ……",
    ["天泉的酒，越辣，越暖。"] = "ƭượǊǦƸủƶǦǥƽƾƙǃǦǥǊǓềǃ,ǦƸƐǃƼǦƸƶǓ,ǦƸƐǃƼǦấǂ.",
    ["师父的酒，是门里最好的。"] = "ƭượǊǦƸủƶǦǈưǦǅƽụǦǁƐǦǉǊǓệǉǦǃƽấǉǦǉǇǄǃƼǦǂƇǃǦǅƽƑƾ.",
    ["时间差不多了，是不是该出发了？"] = "ǥƽờƾǦƼƾƶǃǦƸũǃƼǦǍấǅǦǍỉǦǇồƾ,ǦƸƚǦǅƽảƾǦǃƙǃǦǍǊấǉǦǅƽƑǉǦǀƽƇǃƼ?",
    ["几时了？"] = "ƢƾờǦǃƐǄǦǇồƾ?",
    ["酉时。按道上的消息，明日卯时河边相会。"] = "ƢƾờǦǝậǊ.ǦǥƽƺǄǦǉƾǃǦǉứƸǦƼƾƶǃƼǦƽồ,ǦƼƾờǦƨƃǄǦǃƼƐǓǦǂƶƾǦƽộƾǦƽọǅǦƷƙǃǦƷờǦǈƇǃƼ.",
    ["江晏……他会来么？"] = "ƢƾƶǃƼǦƴếǃ……ǦƽắǃǦƸƚǦǉớƾǦǀƽƇǃƼ?",
    ["王清师兄还在北岸，他一定会来。"] = "ƱươǃƼǦǥƽƶǃƽǦǈưǦƽǊǓǃƽǦƸƛǃǦởǦƷờǦƝắƸ,ǦƽǊǓǃƽǦấǓǦǃƽấǉǦđịǃƽǦǈẽǦǉớƾ.",
    ["杜帅大帐，不得擅入。"] = "ĐạƾǦǉǇướǃƼǦĐỗǦǈǄƑƾ,ǦǀƽƇǃƼǦđượƸǦǉựǦƈǦǋƐǄ.",
    ["不得擅入？是杜帅不让我进，还是你们不让进？"] = "ƦƽƇǃƼǦđượƸǦǉựǦƈǦǋƐǄ?ǦƧƐǦĐỗǦǈǄƑƾǦǀƽƇǃƼǦƸƽǄǦǉƶǦǋƐǄ,ǦƽƶǓǦǁƐǦƸƑƸǦǃƼươƾǦǀƽƇǃƼǦƸƽǄǦǋƐǄ?",
    ["这……林公子何必为难小人。"] = "ƞƽǊǓệǃǦǃƐǓ……ǦƧƁǂǦƸƇǃƼǦǉửǦƽƐǦǉấǉǦǅƽảƾǦǁƐǂǦǀƽƚǦǉƾểǊǦǃƽƁǃ.",
    ["王将军求援的信使刚被拖下去，你们倒演起尽忠职守的“小人”了？"] = "ǥƓǃǦǈứǦƸầǊǦǋƾệǃǦƸủƶǦƱươǃƼǦǉướǃƼǦǆǊƁǃǦǋừƶǦǂớƾǦƷịǦǁƇƾǦǍǊốǃƼ,ǦƸƑƸǦǃƼươƾǦǁạƾǦǤƾễǃǦǋƶƾǦ\"ǉƾểǊǦǃƽƁǃ\"ǦǉậǃǦǉǇǊǃƼǦƸƽứƸǦǉƽủǦǈƶǄ?",
    ["让开！"] = "ǥǇƑǃƽǦǇƶ!",
    ["杜帅！晚生特来贺喜！王清已夺下北岸要塞，大军生路已开！"] = "ĐỗǦǈǄƑƾ!ǦƱƃǃǦǈƾǃƽǦđặƸǦƷƾệǉǦǉớƾǦđƁǓǦƸƽƕƸǦǂừǃƼ!ǦƱươǃƼǦǥƽƶǃƽǦđƃǦƸƽƾếǂǦđượƸǦǓếǊǦǉắƸǦƷờǦƝắƸ,ǦǈƾǃƽǦǁộǦƸủƶǦđạƾǦǆǊƁǃǦđƃǦǂở!",
    ["只待杜帅发兵，这困锁三军的滹沱之围，顷刻可解！"] = "ƞƽỉǦđợƾǦĐỗǦǈǄƑƾǦǅƽƑǉǦƷƾǃƽ,ǦǋƛǃƼǦǋƁǓǦƣƇǦĐƐǦđƶǃƼǦǋƁǓǦǀƽốǃǦǉƶǂǦǆǊƁǃǦǃƐǓ,ǦǉǇǄǃƼǦƸƽớǅǦǂắǉǦƸƚǦǉƽểǦƼƾảƾ!",
    ["咳，林公子稍安，咱们杜帅运筹帷幄，自有方略·······"] = "Ʀƽụ,ǦƧƁǂǦƸƇǃƼǦǉửǦƽƃǓǦǀƽǄƶǃǦǃƚǃƼǦǃảǓ,ǦĐỗǦǈǄƑƾǦƸủƶǦƸƽƕǃƼǦǉƶǦǋậǃǦǉǇƖǦǤǊǓǦƑƸ,ǦǉựǦƸƚǦǅƽươǃƼǦǁượƸ·······",
    ["谋臣史冕"] = "ƨưǊǦǉƽầǃǦƮửǦƨƾệǃ",
    ["询问出发时间"] = "ƣỏƾǦǋềǦǉƽờƾǦƼƾƶǃǦǍǊấǉǦǅƽƑǉ",
    ["真他么窝囊"] = "ǥƽậǉǦǂẹǦǃƚǦǃƽụƸǦǃƽƃ",
    ["别动肝火"] = "ĐừǃƼǦƸƚǦƷốƸǦƽỏƶ",
    ["酒还没喝呢"] = "ƭượǊǦƸƛǃǦƸƽưƶǦǊốǃƼǦđƁǊ",
    ["喝完"] = "ǕốǃƼǦƸạǃ",
    ["去打个痛快"] = "ĐƾǦđƑǃƽǦǂộǉǦǉǇậǃǦƸƽǄǦǉƽốǃƼǦǀƽǄƑƾ",
    ["天也喝"] = "ǥǇờƾǦƸũǃƼǦǊốǃƼ",
    ["敬献英灵尝此酒"] = "ƦƓǃƽǦǤƁǃƼǦƶǃƽǦǁƾǃƽǦǃếǂǦǇượǊǦǃƐǓ",
    ["地也喝"] = "ĐấǉǦƸũǃƼǦǊốǃƼ",
    ["慰唁生灵誓血仇"] = "ỦǓǦǁạǄǦǈƾǃƽǦǁƾǃƽǦǉƽềǦƽǊǓếǉǦƸừǊ",
    ["剑也喝诶"] = "ƦƾếǂǦƸũǃƼǦǊốǃƼǦǃƐǓ",
    ["闷一口"] = "ƩốƸǦǂộǉǦƽớǅ",
    ["发什么呆"] = "ƩƼẩǃǦǃƼườƾǦǁƐǂǦƼƔǦǉƽế",
    ["说好了"] = "ĐƃǦǃƚƾǦǇồƾǦđấǓ",
    ["下顿酒去你们墨城喝"] = "ƝữƶǦǇượǊǦǉớƾǦđếǃǦƨặƸǦǥƽƐǃƽǦƸủƶǦƸƑƸǦǃƼươƾǦǂƐǦǊốǃƼ",
    ["哦？敢问是何方略？"] = "Ồ?ǦǝƑǂǦƽỏƾǦǁƐǦǅƽươǃƼǦǁượƸǦƼƔ?",
    ["大军被困多日，腹背受敌，若要出击，还须待天时啊……"] = "ĐạƾǦǆǊƁǃǦƷịǦǋƁǓǦǀƽốǃǦǃƽƾềǊǦǃƼƐǓ,ǦƷụǃƼǦǁưǃƼǦǉƽụǦđịƸƽ,ǦǃếǊǦǂǊốǃǦǍǊấǉǦǀƓƸƽ,ǦƸƛǃǦǅƽảƾǦđợƾǦǉƽƾƙǃǦǉƽờƾǦǃƽƶ……",
    ["那这“天时”，何时可至？"] = "ƱậǓǦƸƑƾǦ\"ǉƽƾƙǃǦǉƽờƾ\"ǦǃƐǓ,ǦǀƽƾǦǃƐǄǦǂớƾǦđếǃ?",
    ["这个……王清此战不过小胜，战局尚未明朗，还需……需再一两日？"] = "ƞƑƾǦǃƐǓ……ǦƱươǃƼǦǥƽƶǃƽǦǉǇậǃǦǃƐǓǦƸƽẳǃƼǦǆǊƶǦǁƐǦǉƽắǃƼǦǃƽỏ,ǦƸƽƾếǃǦƸụƸǦǋẫǃǦƸƽưƶǦǂƾǃƽǦƷạƸƽ,ǦƸƛǃǦƸầǃ……ǦƸầǃǦǉƽƙǂǦǂộǉǦƽƶƾǦǃƼƐǓǦǃữƶ?",
    ["妙啊，真是妙算啊。我闻君家三代谋臣，你祖献策而失地，你父进计而折兵，皆因“神机巧断”斩于阵前。"] = "ǝƾệǊǦǉƽƶǓ,ǦǉƽậǉǦǁƐǦǤƾệǊǦǉǄƑǃ.ǦǥƶǦǃƼƽƺǦǤƶǃƽǦǆǊƁǃǦƼƾƶǦƷƶǦđờƾǦǁƐǂǦǂưǊǦǉƽầǃ,ǦǉổǦǅƽụǦǃƼươƾǦƽƾếǃǦǀếǦǂƐǦǂấǉǦđấǉ,ǦǅƽụǦǉƽƁǃǦǃƼươƾǦǉƾếǃǦǀếǦǂƐǦǉƽƾệǉǦǆǊƁǃ,ǦđềǊǦǋƔǦƸƑƾǦƼọƾǦǁƐǦ\"ǉƽầǃǦƸơǦǍảǄǦđǄƑǃ\"ǦǂƐǦƷịǦƸƽƗǂǦǃƼƶǓǦǉǇướƸǦǉǇậǃ.",
    ["至于阁下，面拙识浅，才疏人陋，欲效房谋杜断，以口舌之术求生，岂不徒增笑哉！"] = "ƞƛǃǦǃƽưǦƸƑƸǦƽạ,ǦǂặǉǦǂũƾǦǃƼǊǦǃƼơǦǀƾếǃǦǉƽứƸǦǃƇǃƼǦƸạǃ,ǦǉƐƾǦƽƘǃǦǃƼườƾǦǂọǃ,ǦǁạƾǦǂǊốǃǦƽọƸǦǉƽƺǄǦƫƽƛǃƼǦǂưǊǦĐỗǦđǄƑǃ,ǦǤƖǃƼǦǉƽǊậǉǦǂƇƾǦǁưỡƾǦƸầǊǦǈƾǃƽ,ǦƸƽẳǃƼǦǅƽảƾǦƸƽỉǦƸƽǊốƸǦǉƽƙǂǦǉƾếǃƼǦƸườƾǦƸƽƙǦǈƶǄ!",
    ["哼，黄口小儿，不知兵者、诡道也。若贸然出兵，中了埋伏，岂不殃及三军！"] = "ƣừ,ǦǉƾểǊǦǃƽƾǦǂƾệǃƼǦƸƛǃǦƽƇƾǦǈữƶ,ǦǀƽƇǃƼǦƷƾếǉǦƷƾǃƽǦƼƾảǦǁƐǦǆǊỷǦđạǄǦǈƶǄ.ǦƩếǊǦǂạǄǦǂǊộƾǦǍǊấǉǦƷƾǃƽ,ǦǉǇƕǃƼǦǅƽảƾǦǂƶƾǦǅƽụƸ,ǦƸƽẳǃƼǦǅƽảƾǦǈẽǦǋạǦǁƁǓǦǉƶǂǦǆǊƁǃ!",
    ["谋臣张啸"] = "ƨưǊǦǉƽầǃǦǥǇươǃƼǦƦƽƾếǊ",
    ["若要诱敌，自先示弱。而今契丹断我粮道，擒我柴卒，又以“奉敕不杀”慑我子民，尽是示强之举！"] = "ƩếǊǦǂǊốǃǦǃƽửǦđịƸƽ,ǦǉựǦǅƽảƾǦǉƽịǦǃƽượƸǦǉǇướƸ.ǦƩƶǓǦƦƽƾếǉǦĐƶǃǦđǄạǃǦǁươǃƼǦđạǄǦƸủƶǦǉƶ,ǦƷắǉǦǅƽǊǦƸủƾǦƸủƶǦǉƶ,ǦǁạƾǦǁấǓǦ\"ǅƽụǃƼǦǈắƸǦƷấǉǦǈƑǉ\"ǦđểǦǊǓǦƽƾếǅǦǉửǦǤƁǃǦǉƶ,ǦǉƽảǓǦđềǊǦǁƐǦƽƐǃƽǦǋƾǦǉƽịǦǊǓ!",
    ["要的正是我们心生惧意、自缚手脚！此时更当反客为主、迎锋而上。"] = "ƞƑƾǦƸƽƕǃƼǦǂǊốǃǦƸƽƓǃƽǦǁƐǦƸƽƕǃƼǦǉƶǦǈƾǃƽǦǁƛǃƼǦǀƽƾếǅǦǈợ,ǦǉựǦƷƚǦǉƶǓǦƷƚǦƸƽƁǃ!ǦƧƕƸǦǃƐǓǦƸƐǃƼǦǃƙǃǦǅƽảǃǦǀƽƑƸƽǦǋƾǦƸƽủ,ǦǃƼƽƙǃƽǦǅƽǄǃƼǦǃƽƾǦǉƽượǃƼ.",
    ["呵呵，好一个迎锋而上。当年十相计穷于白马，败弃乎长安，想必便是文津馆的“迎锋而上”了？"] = "ƣƔǦƽƔ,ǦƼƾỏƾǦƸƽǄǦǂộǉǦƸƁǊǦǃƼƽƙǃƽǦǅƽǄǃƼǦǃƽƾǦǉƽượǃƼ.ǦƩăǂǦđƚǦǥƽậǅǦǥướǃƼǦǀếǦƸƖǃƼǦởǦƝạƸƽǦƨƃ,ǦƷạƾǦǉẩǊǦǀƽỏƾǦǥǇườǃƼǦƜǃ,ǦƸƽắƸǦƽẳǃǦƸƽƓǃƽǦǁƐǦƸƑƾǦ\"ǃƼƽƙǃƽǦǅƽǄǃƼǦǃƽƾǦǉƽượǃƼ\"ǦƸủƶǦƱăǃǦǥƁǃǦƬǊƑǃǦǇồƾ?",
    ["十相虽死，书库得存，我文津馆自有星火以炳千秋！反是你张逢源，当年献计弃城，以民为饵，苟活至今仍不知羞耻。"] = "ǥƽậǅǦǥướǃƼǦǉǊǓǦǉử,ǦǉƽưǦǀƽốǦǋẫǃǦƸƛǃ,ǦƱăǃǦǥƁǃǦƬǊƑǃǦǉƶǦǉựǦƸƚǦǂồƾǦǁửƶǦđểǦǇạǃƼǦǤƶǃƽǦǉƽƾƙǃǦƸổ!ǦƩƼượƸǦǁạƾǦǁƐǦǃƼươƾǦǥǇươǃƼǦƫƽƖǃƼǦƩƼǊǓƙǃ,ǦǃăǂǦđƚǦƽƾếǃǦǀếǦƷỏǦǉƽƐǃƽ,ǦǁấǓǦǤƁǃǦǁƐǂǦǂồƾ,ǦƸẩǊǦǉƽảǦǈốǃƼǦđếǃǦǃƶǓǦǂƐǦǋẫǃǦǀƽƇǃƼǦƷƾếǉǦǁƾƙǂǦǈỉ.",
    ["我若为君，当自刎谢罪，跪那数万百姓于黄泉，胜过子孙蒙垢，无颜立足天地间！"] = "ǥƶǦǂƐǦǁƐǦǃƼươƾ,ǦđƃǦǉựǦǋẫǃǦǉạǦǉộƾ,ǦǆǊỳǦǁạǓǦǂấǓǦǋạǃǦƷƑƸƽǦǉƓǃƽǦǃơƾǦƽǄƐǃƼǦǉǊǓềǃ,ǦƸƛǃǦƽơǃǦđểǦƸǄǃǦƸƽƑǊǦƸƽịǊǦǃƽụƸ,ǦǀƽƇǃƼǦǂặǉǦǂũƾǦǃƐǄǦđứǃƼǦƼƾữƶǦđấǉǦǉǇờƾ!",
    ["哼，说得轻巧，契丹兵强马壮，远胜于我，主动迎击岂不是羊入虎口？"] = "ƣừ,ǦǃƚƾǦǉƽƔǦǃƽẹǦǃƽƐǃƼǦǁắǂ,ǦƦƽƾếǉǦĐƶǃǦƷƾǃƽǦƸườǃƼǦǂƃǦǉǇƑǃƼ,ǦǂạǃƽǦƽơǃǦǉƶǦǃƽƾềǊ,ǦƸƽủǦđộǃƼǦǃƼƽƙǃƽǦǀƓƸƽǦƸƽẳǃƼǦǅƽảƾǦǁƐǦƸừǊǦǋƐǄǦǂƾệǃƼǦƽổǦǈƶǄ?",
    ["谋臣贾真"] = "ƨưǊǦǉƽầǃǦƢƾảǦƞƽƁǃ",
    ["上伐谋，下角力！赤壁樯橹何如？淝水鹤唳何如？虎牢独骑又何如？"] = "ǥƽượǃƼǦǅƽạǉǦǂưǊ,ǦƽạǦƼƾƑƸǦǁựƸ!ǦǥườǃƼǦǁỗǦƳƓƸƽǦƝƓƸƽǦǉƽếǦǃƐǄ?ǦƣạƸǦǁệǦƫƽƔǦǥƽủǓǦǉƽếǦǃƐǄ?ǦƣổǦƧƶǄǦđộƸǦǀỵǦǁạƾǦǉƽếǦǃƐǄ?",
    ["君不闻，哀兵必胜。我军今陷死地，恰似弓弦拉满，正是射出之时！只要将帅一心，必将置之死地而后生！"] = "ƩƼươƾǦǀƽƇǃƼǦǃƼƽƺǦǉƽấǓǦǈƶǄ,ǦƶƾǦƷƾǃƽǦǉấǉǦǉƽắǃƼ.ǦƬǊƁǃǦǉƶǦǃƶǓǦƽƃǂǦǋƐǄǦǉửǦđịƶ,ǦƼƾốǃƼǦǃƽưǦǤƁǓǦƸǊǃƼǦđƃǦǀƗǄǦƸăǃƼ,ǦƸƽƓǃƽǦǁƐǦǁƕƸǦƷắǃǦǇƶ!ǦƞƽỉǦƸầǃǦǉướǃƼǦǈǄƑƾǦđồǃƼǦǁƛǃƼ,ǦǉấǉǦǈẽǦǉǇƓǦƸƽƾǦǉửǦđịƶǦǃƽƾǦƽậǊǦǈƾǃƽ!",
    ["你身着甲胄，却未战先怯，自比羔羊。岂不知，从来只有跪者尸积成丘，降者血流浮杵。何曾闻摇尾于豺狼者可得生路？"] = "ƩƼươƾǦǂƔǃƽǦǂặƸǦƼƾƑǅǦǉǇụ,ǦǃƽưǃƼǦƸƽưƶǦƸƽƾếǃǦđƃǦǀƽƾếǅ,ǦǉựǦǋƓǦǂƔǃƽǦǃƽưǦǤƙǦǃǄǃ.ǦƣƑǦƸƽẳǃƼǦƷƾếǉ,ǦǍưƶǦǃƶǓǦƸƽỉǦƸƚǦǀẻǦǆǊỳǦƼốƾǦǉƽƔǦǉƽƁǓǦƸƽấǉǦǉƽƐǃƽǦǃƕƾ,ǦǀẻǦƽƐǃƼǦǅƽụƸǦǉƽƔǦǂƑǊǦƸƽảǓǦǉǇƇƾǦƸƽƐǓ.ǦƩƐǄǦđƃǦǉừǃƼǦǃƼƽƺǦǀẻǦǋẫǓǦđǊƇƾǦǉǇướƸǦǁǄƐƾǦǈƚƾǦǤữǦǂƐǦƸƚǦđượƸǦǈƾǃƽǦǁộ?",
    ["难怪此间数日沉寂，不闻角声，原来皆因这帐中尽是不可糊墙之物！"] = "ǥǇƑƸƽǦǀƽƇǃƼǦđượƸǦǃơƾǦđƁǓǦǂấǓǦǃƼƐǓǦǉǇầǂǦǉịƸƽ,ǦǀƽƇǃƼǦǃƼƽƺǦǉƾếǃƼǦǉƖǦǋƐ,ǦƽƚƶǦǇƶǦđềǊǦǋƔǦǉǇǄǃƼǦǉǇướǃƼǦǃƐǓǦǉǄƐǃǦǁƐǦƽạǃƼǦƷƖǃǦǃƽƃǄǦǀƽƇǃƼǦǉǇƑǉǦǃổƾǦǉườǃƼ!",
    ["三军上下，堪国士者，唯一人耳！如今前线将士敢战，皆因信此人不负——"] = "ǥƶǂǦǆǊƁǃǦǉƽượǃƼǦƽạ,ǦǀẻǦǍứǃƼǦǉầǂǦǆǊốƸǦǈĩ,ǦǤǊǓǦƸƽỉǦƸƚǦǂộǉǦǃƼườƾ!ǦƩƶǓǦǉướǃƼǦǈĩǦǉƾềǃǦǉǊǓếǃǦǤƑǂǦƸƽƾếǃ,ǦđềǊǦǋƔǦǉƾǃǦǃƼườƾǦǃƐǓǦǀƽƇǃƼǦǅƽụ——",
    ["大胆！安敢在此为王清张目——"] = "ƢỗǃǦǍượƸ!ǦƮƶǄǦǤƑǂǦởǦđƁǓǦǉǇươǃƼǦǂụƸǦƸƽǄǦƱươǃƼǦǥƽƶǃƽ——",
    ["此人便是——当年的杜帅！平汜水、定邺城，镇泰州。帅旗所指，无往不胜。"] = "ƩƼườƾǦǃƐǓǦƸƽƓǃƽǦǁƐ——ǦĐỗǦǈǄƑƾǦǃăǂǦđƚ!ǦƝƔǃƽǦǥịǦǥƽủǓ,ǦđịǃƽǦƩƼƽƾệǅǦǥƽƐǃƽ,ǦǉǇấǃǦǥƽƑƾǦƞƽƁǊ.ǦƮǄƑƾǦǀỳǦƸƽỉǦđƁǊ,ǦđƑǃƽǦđƁǊǦǉƽắǃƼǦđƚ.",
    ["今也，敌我已对峙半月。契丹兵多粮足，为何围而不攻？"] = "ƩƶǓ,ǦđịƸƽǦǉƶǦđƃǦđốƾǦǉǇƔǦǃửƶǦǉƽƑǃƼ.ǦƦƽƾếǉǦĐƶǃǦƷƾǃƽǦǃƽƾềǊǦǁươǃƼǦđủ,ǦǋƔǦǈƶǄǦǋƁǓǦǂƐǦǀƽƇǃƼǦđƑǃƽ?",
    ["因……因我军据险而守。故此更不可轻易北上，弃地利之势。"] = "ƱƔ……ǦǋƔǦǆǊƁǃǦǉƶǦƸứǦƽƾểǂǦǂƐǦƼƾữ.ǦƝởƾǦǋậǓǦƸƐǃƼǦǀƽƇǃƼǦǉƽểǦǀƽƾǃƽǦǈǊấǉǦƷắƸǦǉƽượǃƼ,ǦƷỏǦǂấǉǦǉƽếǦđịƶǦǁợƾ.",
    ["错！所惧者非地利，乃是两年前横槊渡河，胡马生寒的杜大将军！"] = "Ʈƶƾ!ǦǥƽứǦƸƽƕǃƼǦǈợǦǀƽƇǃƼǦǅƽảƾǦđịƶǦǁợƾ,ǦǂƐǦǁƐǦǋịǦĐỗǦđạƾǦǉướǃƼǦǆǊƁǃǦƽƶƾǦǃăǂǦǉǇướƸǦƽǄƐǃƽǦǈƚƸǦđộǦƽƐ,ǦǀƽƾếǃǦǃƼựƶǦƣồǦǅƽƑǉǦǀƽƾếǅ!",
    ["“槊杆作篙河当路，帅旗响得胡马哭。”"] = "\"ƮƚƸǦƸƑǃǦǉƑƸǦƸƶǄǦƽƐǦđươǃƼǦǁộ,ǦǈǄƑƾǦǀỳǦƽưởǃƼǦđắƸǦƣồǦǂƃǦǀƽốƸ.\"",
    ["昔日百姓所赞，杜帅可还记得？"] = "ƧờƾǦƷƑƸƽǦǉƓǃƽǦǀƽƺǃǦǉặǃƼǦǃƼƐǓǦǍưƶ,ǦĐỗǦǈǄƑƾǦƸƛǃǦǃƽớǦƸƽăǃƼ?",
    ["既知杜帅威名，还敢在此搅动军心！"] = "ĐƃǦƷƾếǉǦǊǓǦǤƶǃƽǦĐỗǦǈǄƑƾ,ǦƸƛǃǦǤƑǂǦởǦđƁǓǦǁƐǂǦǁǄạǃǦǆǊƁǃǦǉƁǂ!",
    ["军心何在？在河之北！在昔日称颂里！杜帅不出，三军所望何在？在河之南！在今日骂声中！"] = "ƬǊƁǃǦǉƁǂǦởǦđƁǊ?ǦỞǦƷờǦƝắƸǦǈƇǃƼ!ǦỞǦǉǇǄǃƼǦǃƽữǃƼǦǁờƾǦƸƶǦǉụǃƼǦǃăǂǦǍưƶ!ǦĐỗǦǈǄƑƾǦǀƽƇǃƼǦǇƶǦǉǇậǃ,ǦǉƶǂǦǆǊƁǃǦǉǇƇǃƼǦǋọǃƼǦǋƐǄǦđƁǊ?ǦỞǦƷờǦƩƶǂǦǈƇǃƼ!ǦỞǦǉǇǄǃƼǦǃƽữǃƼǦǉƾếǃƼǦƸƽửƾǦǇủƶǦǃƼƐǓǦƽƇǂǦǃƶǓ!",
    ["退，则大晋危亡、天下倾覆！进，则绝处逢生，乾坤可挽！"] = "ƧƖƾ,ǦǉƽƔǦđạƾǦǥấǃǦǃƼǊǓǦǋǄǃƼ,ǦǉƽƾƙǃǦƽạǦǃƼƽƾƙǃƼǦǃƼửƶ!Ǧǥƾếǃ,ǦǉƽƔǦǉǊǓệǉǦǍứǦǅƽƖǃƼǦǈƾǃƽ,ǦƸƐǃǦǀƽƇǃǦƸƚǦǉƽểǦƸứǊǦǋƃǃ!",
    ["中渡桥已陷于敌手，何来生机？你一介袖手书生，动动嘴皮子，便想让我等枉送性命。"] = "ǥǇǊǃƼǦĐộǦƦƾềǊǦđƃǦǇơƾǦǋƐǄǦǉƶǓǦđịƸƽ,ǦǈƾǃƽǦƸơǦởǦđƁǊ?ǦƩƼươƾǦƸƽỉǦǁƐǦƽạǃƼǦǉƽưǦǈƾǃƽǦǀƽǄƶǃƽǦǉƶǓǦđứǃƼǦǃƽƔǃ,ǦǀƽǊƶǦǂƇƾǦǂƕƶǦǂƗǅ,ǦǁạƾǦǂǊốǃǦƸƽƕǃƼǦǉƶǦǊổǃƼǦǂạǃƼǦǈƶǄ.",
    ["杜帅！"] = "ĐỗǦǈǄƑƾ!",
    ["放、放肆！江湖野匪，竟敢行刺大帅！"] = "ƣỗǃ,ǦƽỗǃǦǍượƸ!ǦƢƾƶǃƼǦƽồǦǤƃǦǅƽỉ,ǦƼǊốƸǦǤƑǂǦƽƐǃƽǦǉƽƓƸƽǦĐạƾǦǈǄƑƾ!",
    ["林某愿以项上人头为质——"] = "ƧƁǂǦǂỗǦǃƼǊǓệǃǦǁấǓǦđầǊǦǉǇƙǃǦƸổǦǇƶǦǁƐǂǦǉƾǃ——",
    ["辰时之前中渡桥必通，如若不然，甘受军法！"] = "ǥǇướƸǦƼƾờǦǥƽầǃǦǥǇǊǃƼǦĐộǦƦƾềǊǦǉấǉǦǉƽƇǃƼ,ǦǃếǊǦǀƽƇǃƼǦđượƸǦǃƽưǦǋậǓ,ǦƸƶǂǦƸƽịǊǦǆǊƁǃǦǅƽƑǅ!",
    ["若此战得胜，天下必颂杜帅三破契丹、救江山于将倾。青史所载，杜公今日擎天之功——更胜当年雪夜定叛之勇！"] = "ƩếǊǦǉǇậǃǦǃƐǓǦđắƸǦǉƽắǃƼ,ǦǉƽƾƙǃǦƽạǦǉấǉǦǉụǃƼǦƸƶǦĐỗǦǈǄƑƾǦƷƶǦǁầǃǦǅƽƑǦƦƽƾếǉǦĐƶǃ,ǦƸứǊǦƼƾƶǃƼǦǈơǃǦǁƕƸǦǁƁǂǦǃƼǊǓ.ǦǥƽƶǃƽǦǈửǦƼƽƾǦǁạƾ,ǦƸƇǃƼǦǁƶǄǦǀƔǃƽǦǉƽƾƙǃǦƸủƶǦĐỗǦƸƇǃƼǦƽƇǂǦǃƶǓ——ǦƸƛǃǦǋượǉǦǍƶǦƸƑƾǦǤũǃƼǦđịǃƽǦǅƽảǃǦǃăǂǦǃƐǄǦƼƾữƶǦđƙǂǦǉǊǓếǉ!",
    ["请杜帅发兵！"] = "ƳƾǃǦĐỗǦǈǄƑƾǦǅƽƑǉǦƷƾǃƽ!",
    ["听闻冯道收了南边林家的独子做关门，就是你吧？"] = "ƩƼƽƺǦǃƚƾǦƫƽƖǃƼǦĐạǄǦǉƽǊǦǃƽậǃǦđộƸǦǉửǦƸủƶǦƧƁǂǦƼƾƶǦǅƽươǃƼǦƩƶǂǦǁƐǂǦđệǦǉửǦđƚǃƼǦƸửƶ,ǦƸƽƓǃƽǦǁƐǦǃƼươƾǦǅƽảƾǦǀƽƇǃƼ?",
    ["帐中人"] = "ƩƼườƾǦǉǇǄǃƼǦǉǇướǃƼ",
    ["如今子时已过……你们那位小朋友，也该到军库了。"] = "ƩƶǓǦđƃǦǆǊƶǦƼƾờǦǥƈ……ǦǋịǦǉƾểǊǦƷằǃƼǦƽữǊǦđƚǦƸủƶǦƸƑƸǦǃƼươƾ,ǦƸũǃƼǦǃƙǃǦđếǃǦǆǊƁǃǦǀƽốǦǇồƾ.",
    ["这封信，还是不要留了为好。"] = "ƝứƸǦǉƽưǦǃƐǓ,ǦǉốǉǦǃƽấǉǦǁƐǦđừǃƼǦƼƾữǦǁạƾǦǉƽƔǦƽơǃ.",
    ["丁笑"] = "ĐƾǃƽǦǥƾếǊ",
    ["军库钥匙在杜砌银手上，先回大营再说。"] = "ƞƽƔƶǦǀƽƚƶǦǆǊƁǃǦǀƽốǦǃằǂǦǉǇǄǃƼǦǉƶǓǦĐỗǦƦƽếǦƩƼƁǃ,ǦǋềǦđạƾǦǤǄƶǃƽǦǉǇướƸǦǇồƾǦǉƓǃƽ.",
    ["欸，你说这大帅是什么意思，咱们这兵是出还是不出？"] = "Ê,ǦǃƼươƾǦǃƚƾǦǍƺǂǦĐạƾǦǈǄƑƾǦƸƚǦƈǦƼƔ,ǦƷƾǃƽǦƸủƶǦƸƽƕǃƼǦǉƶǦǇốǉǦƸǊộƸǦǁƐǦƸƚǦǍǊấǉǦƽƶǓǦǀƽƇǃƼ?",
    ["曹鲅"] = "ǥƐǄǦƝạǉ",
    ["瞎操心，大帅的想法是你这种兵蛋子能揣度的？"] = "ƧǄǦƽƃǄ,ǦǈǊǓǦǃƼƽĩǦƸủƶǦĐạƾǦǈǄƑƾǦǂƐǦƽạǃƼǦǁƓǃƽǦǆǊƘǃǦǃƽưǦǃƼươƾǦƸƚǦǉƽểǦǅƽỏǃƼǦđǄƑǃǦđượƸǦǈƶǄ?",
    ["哟，丁哥，外面公干回来了？可又带回点什么打牙祭的，也赏我们一口？"] = "Ồ,ǦĐƾǃƽǦƸƶ,ǦđƾǦƸƇǃƼǦǋụǦƷƙǃǦǃƼǄƐƾǦǋềǦǇồƾǦƐ?ǦƞƚǦǂƶǃƼǦǋềǦƸƑƾǦƼƔǦđểǦƼƾảƾǦǉỏƶǦƸơǃǦǉƽƘǂǦǀƽƇǃƼ,ǦƷƶǃǦƸƽǄǦƷọǃǦđệǦǂộǉǦǂƾếǃƼ?",
    ["呵，你也不看看当下是什么光景，树皮都薅秃了，还想龙肉吃？"] = "ƣừ,ǦǃƼươƾǦƸũǃƼǦǀƽƇǃƼǦǃƽƔǃǦǍƺǂǦǉƔǃƽǦƸảǃƽǦǁƕƸǦǃƐǓǦǉƽếǦǃƐǄ,ǦǋỏǦƸƁǓǦƸũǃƼǦƷịǦƷƚƸǦǉǇụƾǦƸảǦǇồƾ,ǦƸƛǃǦǂǊốǃǦăǃǦǉƽịǉǦǇồǃƼǦǈƶǄ?",
    ["就这两个油饼子，再没别的了。"] = "ƞƽỉǦƸƚǦƽƶƾǦƸƑƾǦƷƑǃƽǦǇƑǃǦǃƐǓǦǉƽƇƾ,ǦǀƽƇǃƼǦƸƛǃǦƼƔǦǀƽƑƸǦđƁǊ.",
    ["我就知道，跟着丁哥准饿不着！"] = "ĐệǦƷƾếǉǦǃƼƶǓǦǂƐ,ǦđƾǦǉƽƺǄǦĐƾǃƽǦƸƶǦǉƽƔǦǀƽƇǃƼǦƷƶǄǦƼƾờǦǈợǦđƚƾ!",
    ["还得是丁哥，谢谢哥！"] = "ƱẫǃǦƸứǦǁƐǦĐƾǃƽǦƸƶ,ǦđƶǦǉạǦƸƶ!",
    ["邓丕"] = "ĐặǃƼǦƫƽƾ",
    ["见着杜砌银没？"] = "ƞƚǦǉƽấǓǦĐỗǦƦƽếǦƩƼƁǃǦǀƽƇǃƼ?",
    ["没、好几天没瞧着他了，孙大墙也正念叨他呢……欸丁哥，你这不还有半拉甜糕——"] = "ƦƽƇǃƼ,ǦǂấǓǦǃƼƐǓǦǇồƾǦƸƽẳǃƼǦǉƽấǓǦƽắǃǦđƁǊ,ǦǥƇǃǦĐạƾǦǥườǃƼǦƸũǃƼǦđƶǃƼǦǃƽắƸǦƽắǃǦǀƔƶ……ǦƠǦĐƾǃƽǦƸƶ,ǦƽǊǓǃƽǦƸƽẳǃƼǦǅƽảƾǦǋẫǃǦƸƛǃǦǃửƶǦǂƾếǃƼǦƷƑǃƽǦǃƼọǉǦǈƶǄ——",
    ["这个啊，谁都不给。"] = "ƞƑƾǦǃƐǓǦƐ,ǦƶƾǦƸũǃƼǦǀƽƇǃƼǦƸƽǄǦđƁǊ.",
    ["妈的，那杜砌银欠的赌钱，就这么打水漂了？"] = "ƨẹǦǀƾếǅ,ǦǉƾềǃǦƷạƸǦĐỗǦƦƽếǦƩƼƁǃǦǃợǦǀƽƾǦđƑǃƽǦƷạƸ,ǦƸứǦǉƽếǦǁƐǦǉǇƇƾǦǈƇǃƼǦđổǦƷƾểǃǦǈƶǄ?",
    ["孙大墙"] = "ǥƇǃǦĐạƾǦǥườǃƼ",
    ["伙长，小点儿声！钱是小事，可别沾上晦气。"] = "ƣỏƶǦǉǇưởǃƼ,ǦǃƽỏǦǉƾếǃƼǦƸƽƕǉ!ǦǥƾềǃǦǁƐǦƸƽǊǓệǃǦǃƽỏ,ǦđừǃƼǦđểǦǋướǃƼǦǋƐǄǦǋậǃǦǍǊƾ.",
    ["温狗儿"] = "ƆǃǦƞẩǊǦƩƽƾ",
    ["要真让人以为咱们和那小子有什么勾当，那就麻烦了。"] = "ƩếǊǦǉƽựƸǦǈựǦđểǦǃƼườƾǦǉƶǦǉưởǃƼǦƷọǃǦǂƔǃƽǦƸƚǦǂờǦƑǂǦƼƔǦǋớƾǦǉƽằǃƼǦǃƽƚƸǦđƚǦǉƽƔǦǅƽƾềǃǦǅƽứƸǦǁắǂ.",
    ["俺就是心疼钱——罢了罢了，不提了。"] = "ǥƶǦƸƽỉǦǁƐǦǉƾếƸǦǉƾềǃǦǉƽƇƾ——ǦǉƽƇƾǦđượƸǦǇồƾ,ǦǀƽƇǃƼǦǃƽắƸǦǉớƾǦǃữƶ.",
    ["来来来，继续，押大还是押小。"] = "ƧạƾǦđƁǓǦǁạƾǦđƁǓ,ǦǉƾếǅǦǉụƸ,ǦđặǉǦǁớǃǦƽƶǓǦđặǉǦǃƽỏǦǃƐǄ.",
    ["我道是谁，这不杜砌银杜库吏的笔杆子，丁文书嘛！怎么，今天有兴致玩两圈？"] = "ǥƶǦƸƛǃǦǉưởǃƼǦǁƐǦƶƾ,ǦƽƚƶǦǇƶǦǁƐǦǉƶǓǦƸƽƁǃǦƸủƶǦĐỗǦƦƽếǦƩƼƁǃǦĐỗǦǀƽốǦǁạƾ,ǦĐƾǃƽǦǋăǃǦǉƽưǦđƁǓǦǂƐ!ǦƮƶǄ,ǦƽƇǂǦǃƶǓǦƸƚǦƽứǃƼǦǉƽƕǦƸƽơƾǦǋƐƾǦǋƑǃǦƐ?",
    ["听说杜兄前些日子欠了孙哥的钱，特来替他还债。"] = "ƩƼƽƺǦǃƚƾǦĐỗǦƽǊǓǃƽǦǂấǓǦƽƇǂǦǉǇướƸǦǃợǦǉƾềǃǦǥƇǃǦƸƶ,ǦđặƸǦƷƾệǉǦǉớƾǦđƁǓǦǉǇảǦǃợǦǉƽƶǓ.",
    ["哎呀，兄弟这就见外了不是，一点小钱嘛，快坐快坐。"] = "ÁƾǦƸƽƐ,ǦƽǊǓǃƽǦđệǦǁƐǂǦǉƽếǦǁƐǦǀƽƑƸƽǦǈƑǄǦǆǊƑǦǇồƾ,ǦƸƽƕǉǦǉƾềǃǦǁẻǦǉƽƇƾǦǂƐ,ǦǂƶǊǦǃƼồƾǦǂƶǊǦǃƼồƾ.",
    ["丁兄弟能来替杜库吏还钱，可是大帅消了气？"] = "ĐƾǃƽǦƽǊǓǃƽǦđệǦƸƚǦǉƽểǦǉớƾǦǉǇảǦǃợǦǉƽƶǓǦĐỗǦǀƽốǦǁạƾ,ǦǅƽảƾǦƸƽăǃƼǦǁƐǦĐạƾǦǈǄƑƾǦđƃǦǃƼǊƇƾǦƼƾậǃ?",
    ["近来奉命在外公干，还不知杜兄那边出了什么事。"] = "ƢầǃǦđƁǓǦǅƽụǃƼǦǂệǃƽǦđƾǦƸƇǃƼǦǋụǦƷƙǃǦǃƼǄƐƾ,ǦǋẫǃǦƸƽưƶǦƷƾếǉǦǅƽƓƶǦĐỗǦƽǊǓǃƽǦđƃǦǍảǓǦǇƶǦƸƽǊǓệǃǦƼƔ.",
    ["哎，说是杜砌银弄丢了军库的钥匙，就前天，被大帅好一顿骂。"] = "ƣƶƾǏǏ,ǦǃƼƽƺǦǃƚƾǦǁƐǦĐỗǦƦƽếǦƩƼƁǃǦǁƐǂǦǂấǉǦƸƽƔƶǦǀƽƚƶǦǆǊƁǃǦǀƽố,ǦǂớƾǦƽƇǂǦǀƾƶǦǉƽƇƾ,ǦƷịǦĐạƾǦǈǄƑƾǦǂắǃƼǦƸƽǄǦǂộǉǦǉǇậǃǦǉơƾǦƷờƾ.",
    ["那孙哥可知杜砌银现在何处？"] = "ƱậǓǦǥƇǃǦƸƶǦƸƚǦƷƾếǉǦĐỗǦƦƽếǦƩƼƁǃǦƽƾệǃǦđƶǃƼǦởǦǃơƾǦǃƐǄǦǀƽƇǃƼ?",
    ["不知道，好像说，给关到哪儿反省去了……"] = "ƦƽƇǃƼǦƷƾếǉ,ǦƽƔǃƽǦǃƽưǦǃƼƽƺǦƷảǄǦƷịǦǃƽốǉǦởǦƸƽỗǦǃƐǄǦđểǦǅƽảǃǦǉỉǃƽǦǇồƾ……",
    ["你说，他一个看管仓库的军需官儿，怎么能把吃饭的家伙都整没了？"] = "ƩƼươƾǦǃƚƾǦǍƺǂ,ǦƽắǃǦǁƐǦǆǊƶǃǦǆǊƁǃǦǃƽǊǦƸǄƾǦƼƾữǦǀƽǄǦǉƐǃƼ,ǦǈƶǄǦƸƚǦǉƽểǦǁƐǂǦǂấǉǦƸƑƾǦƸầǃǦƸƁǊǦƸơǂǦƸủƶǦǂƔǃƽǦđượƸǦƸƽứ?",
    ["杜砌银丢了钥匙……？军库的钥匙，不该无缘无故丢了才对。"] = "ĐỗǦƦƽếǦƩƼƁǃǦǁƐǂǦǂấǉǦƸƽƔƶǦǀƽƚƶ……?ǦƞƽƔƶǦǀƽƚƶǦǆǊƁǃǦǀƽố,ǦǁẽǦǇƶǦǀƽƇǃƼǦǉƽểǦǋƇǦǤǊǓƙǃǦǋƇǦƸớǦǂƐǦǂấǉǦđượƸ.",
    ["钥匙能去哪儿呢……得再打听打听。"] = "ƞƽƔƶǦǀƽƚƶǦƸƚǦǉƽểǦđƾǦđƁǊǦđượƸǦǃƽỉ……ǦǅƽảƾǦǃƼƽƺǦǃƼƚǃƼǦǉƽƙǂǦǂớƾǦđượƸ.",
    ["要我说啊，还是得上头有人。你看那杜砌银，跟大帅沾着亲，犯了事，就骂一顿。"] = "ĐểǦǉƶǦǃƚƾǦƸƽǄǦǂƐǦǃƼƽƺ,ǦǋẫǃǦǁƐǦǅƽảƾǦƸƚǦǃƼườƾǦởǦǉǇƙǃǦƸƽƺǦƸƽở.ǦƩƼươƾǦǃƽƔǃǦǉƙǃǦĐỗǦƦƽếǦƩƼƁǃǦđƚǦǍƺǂ,ǦƸƚǦƸƽƕǉǦƽọǦƽƐǃƼǦǋớƾǦĐạƾǦǈǄƑƾ,ǦǅƽạǂǦǁỗƾǦǉƽƔǦƸũǃƼǦƸƽỉǦƷịǦǂắǃƼǦǂộǉǦǉǇậǃǦǉƽƇƾ.",
    ["张麻子"] = "ǥǇươǃƼǦƨƶǦǥử",
    ["再看那李会五，军功有什么用，脑袋都拴不牢呦……"] = "ƧạƾǦǃƽƔǃǦƧƈǦƣộƾǦƩƼũǦǀƾƶǦǍƺǂ,ǦǆǊƁǃǦƸƇǃƼǦǉƽƔǦƸƚǦƓƸƽǦƼƔ,ǦƸƑƾǦđầǊǦƸƛǃǦƸƽẳǃƼǦƼƾữǦǃổƾǦǉǇƙǃǦƸổǦǀƔƶ……",
    ["不过要说李会五这小子，也真够胆大的，通敌的事儿也干得出来？"] = "ƩƽưǃƼǦǂƐǦǃƚƾǦđƾǦƸũǃƼǦǅƽảƾǦǃƚƾǦǁạƾ,ǦǉƽằǃƼǦǃƽƚƸǦƧƈǦƣộƾǦƩƼũǦđƚǦƸũǃƼǦǉǄǦƼƶǃǦǉƽậǉ,ǦƸƽǊǓệǃǦǉƽƇǃƼǦđịƸƽǦǂƐǦƸũǃƼǦǤƑǂǦǁƐǂ?",
    ["哎呦，连累着十几号人，一个个脑瓜子跟切菜似的，滴溜溜满地乱滚，那血浆子呀，涂得……"] = "ÁƾǦƸƽƐ,ǦǁƾƙǃǦǁụǓǦđếǃǦǂườƾǦǂấǓǦǂạǃƼǦǃƼườƾ,ǦƸƑƾǦđầǊǦǃƐǄǦđầǊǦǃấǓǦƸứǦǃƽưǦǉƽƑƾǦǇƶǊǦấǓ,ǦǁăǃǦǁƇǃƼǦǁốƸǦǀƽắǅǦǂặǉǦđấǉ,ǦǂƑǊǦǂƺǦǉƽƔǦǋươǃƼǦǋƃƾ……",
    ["停停停，麻子哥，可别说了，太吓人了。我、我腿都站不稳了……"] = "ǝừǃƼǦǤừǃƼǦǤừǃƼ,ǦƨƶǦǥửǦƸƶ,ǦđừǃƼǦǃƚƾǦǃữƶ,ǦđƑǃƼǦǈợǦǆǊƑ.ǦĐệ,ǦđệǦđứǃƼǦǀƽƇǃƼǦǋữǃƼǦǃữƶǦǇồƾ……",
    ["好好好，不说了。知道你是个耗子胆。得嘞，我也该歇着了，小小，夜岗该你了。"] = "ĐượƸǦđượƸǦđượƸ,ǦǀƽƇǃƼǦǃƚƾǦǃữƶ.ǦƝƾếǉǦǃƼươƾǦǁƐǦƼƶǃǦǉƽỏǦđếǦǇồƾ.ǦƳǄǃƼ,ǦǉƶǦƸũǃƼǦǅƽảƾǦđƾǦǃƼƽỉǦđƁǓ,ǦǥƾểǊǦǥƾểǊ,ǦđếǃǦƸƶǦǉǇựƸǦđƙǂǦƸủƶǦǃƼươƾǦǇồƾǦđấǓ.",
    ["麻子哥、麻子哥——诶，你别走诶。"] = "ƨƶǦǥửǦƸƶ,ǦƨƶǦǥửǦƸƶ——ǦƠ,ǦƽǊǓǃƽǦđừǃƼǦđƾǦǂƐ.",
    ["李会五，你要索命可别来找我，冤有头债有主……"] = "ƧƈǦƣộƾǦƩƼũ,ǦǃƼươƾǦǂǊốǃǦđƛƾǦǂạǃƼǦǉƽƔǦđừǃƼǦǉƔǂǦǉƶ,ǦǄƶǃǦƸƚǦđầǊǦǃợǦƸƚǦƸƽủ……",
    ["鬼呀——！丁文书！你吓死我了！你怎么走路都不带声的。"] = "ƨƶǦǆǊỷǦƽƾệǃǦƽƔǃƽ——!ǦĐƾǃƽǦǋăǃǦǉƽư!ǦƩƼươƾǦƽƖǦƸƽếǉǦǉƶǦǇồƾ!ǦƮƶǄǦǃƼươƾǦđƾǦđứǃƼǦǂƐǦǀƽƇǃƼǦƸƚǦǉƾếǃƼǦđộǃƼǦǃƐǄǦǉƽế.",
    ["不做亏心事，不怕鬼敲门。王小小，你有什么可怕的。听说营里都在抓通敌的谍子，莫不是你——"] = "ƝấǉǦǉƑƸǦǀƽǊǓǦǉƁǂǦǈự,ǦƷấǉǦǅƽạǦǆǊỷǦǀƽƾƙǊǦǂƇǃ.ǦƱươǃƼǦǥƾểǊǦǥƾểǊ,ǦǃƼươƾǦƸƚǦƼƔǦǂƐǦǅƽảƾǦǈợ?ǦƩƼƽƺǦǃƚƾǦǉǇǄǃƼǦǤǄƶǃƽǦđƶǃƼǦƷắǉǦƼƾƑǃǦđƾệǅǦǉƽƇǃƼǦđịƸƽ,ǦǀƽƇǃƼǦǁẽǦǁƐǦǃƼươƾ——",
    ["丁、丁文书，你胡说什么？我怎么会通敌？！"] = "Đƾǃƽ,ǦĐƾǃƽǦǋăǃǦǉƽư,ǦǃƼươƾǦǃƚƾǦƷậǓǦƼƔǦđƚ?ǦǥƶǦǈƶǄǦƸƚǦǉƽểǦǉƽƇǃƼǦđịƸƽ?!",
    ["是李会五，是他这个煞星！这几日凡跟他有联络的，都倒了霉。"] = "ƧƐǦƧƈǦƣộƾǦƩƼũ,ǦǁƐǦƸƑƾǦǉƙǃǦǈƑǉǦǉƾǃƽǦđƚ!ǦƨấǓǦǃƼƐǓǦǃƶǓǦǅƽƐǂǦǁƐǦƶƾǦƸƚǦǁƾƙǃǦǁạƸǦǋớƾǦƽắǃǦđềǊǦƼặǅǦǍǊƾǦǍẻǄǦƸả.",
    ["都有谁？没事小小，你慢慢说，说清楚就没事了"] = "ƢồǂǦǃƽữǃƼǦƶƾ?ǦƦƽƇǃƼǦǈƶǄǦđƁǊǦǥƾểǊǦǥƾểǊ,ǦǃƼươƾǦƸứǦǉừǦǉừǦǃƚƾ,ǦǃƚƾǦǇƅǦǇƐǃƼǦǇƶǦǁƐǦǈẽǦǀƽƇǃƼǦǈƶǄǦƽếǉ.",
    ["有好多人咧！就连杜库吏，不过和他喝了一趟酒，也被好一顿教训。"] = "ƞƚǦǃƽƾềǊǦǃƼườƾǦǁắǂ!ǦƩƼƶǓǦƸảǦĐỗǦǀƽốǦǁạƾ,ǦƸƽẳǃƼǦǆǊƶǦƸƽỉǦǊốǃƼǦǋớƾǦƽắǃǦǂộǉǦƷữƶǦǇượǊǦǂƐǦƸũǃƼǦƷịǦƼƾƑǄǦƽǊấǃǦƸƽǄǦǂộǉǦǉǇậǃǦǉơƾǦƷờƾ.",
    ["我、我最老实了！从不和这些人往来的！"] = "ǥƶ,ǦǉƶǦǁƐǦǉƽƐǃƽǦǉƽậǉǦǃƽấǉǦǇồƾ!ǦƞƽẳǃƼǦƷƶǄǦƼƾờǦǆǊƶǦǁạƾǦǋớƾǦƽạǃƼǦǃƼườƾǦđƚǦđƁǊ!",
    ["《低声>李会五是王清旧部，与杜砌银并不相熟，怎会一起喝酒？"] = "<ǥƽƔǦǉƽầǂ>ǦƧƈǦƣộƾǦƩƼũǦǁƐǦƸựǊǦƷộǦƽạǦƸủƶǦƱươǃƼǦǥƽƶǃƽ,ǦǀƽƇǃƼǦƽềǦǆǊƺǃǦƷƾếǉǦĐỗǦƦƽếǦƩƼƁǃ,ǦǈƶǄǦƸƚǦǉƽểǦƸƖǃƼǦǃƽƶǊǦǊốǃƼǦǇượǊ?",
    ["去杜砌银帐中看看，也许会有线索。"] = "ĐếǃǦǉǇướǃƼǦƸủƶǦĐỗǦƦƽếǦƩƼƁǃǦǍƺǂǦǉƽử,ǦƸƚǦǁẽǦǈẽǦƸƚǦǂƶǃƽǦǂốƾ.",
    ["那小子，还叫唤呢？"] = "ǥƽằǃƼǦǃƽƚƸǦđƚǦǋẫǃǦƸƛǃǦǀƙǊǦǁƶǦƐ?",
    ["石宾"] = "ǥƽạƸƽǦǥƁǃ",
    ["杜帅！晚生林险生特来贺喜！王清已夺下北岸要塞，大军生路已开！"] = "ĐỗǦǈǄƑƾ!ǦƱƃǃǦǈƾǃƽǦƧƁǂǦƣƾểǂǦƮƾǃƽǦđặƸǦƷƾệǉǦǉớƾǦƸƽƕƸǦǂừǃƼ!ǦƱươǃƼǦǥƽƶǃƽǦđƃǦƸƽƾếǂǦđượƸǦǓếǊǦǉắƸǦƷờǦƝắƸ,ǦǈƾǃƽǦǁộǦƸủƶǦđạƾǦǆǊƁǃǦđƃǦǂở!",
    ["要不说这人就一张嘴呢，赶着个有头有脸的就上杆巴结，如今哭起娘来花样也多着呢！哈哈哈——"] = "ƞƽẳǃƼǦǉǇƑƸƽǦǃƼườƾǦǉƶǦǃƚƾǦǀẻǦǃƐǓǦƸƽỉǦđượƸǦƸƑƾǦǂồǂ,ǦǉƽấǓǦƶƾǦƸƚǦǂƑǊǦǂặǉǦǁƐǦǈƑǅǦǁạƾǦǃịǃƽǦƷợ,ǦƼƾờǦǉƽƔǦǀƽƚƸǦƸƽƶǦƼọƾǦǂẹǦƸũǃƼǦđủǦǀƾểǊǦđủǦǉǇƛ!ǦƣƶǦƽƶǦƽƶ——",
    ["井同"] = "ǥỉǃƽǦĐồǃƼ",
    ["绕着弯子想舔大帅的靴子尖，也不看看自己的斤两。"] = "ƞứǦǋƛǃƼǦǋǄǦǂǊốǃǦǁƾếǂǦǂũƾǦủǃƼǦƸủƶǦĐạƾǦǈǄƑƾ,ǦǂƐǦƸƽẳǃƼǦǃƽƔǃǦǁạƾǦǍƺǂǦǂƔǃƽǦǃặǃƼǦǃƽẹǦƷƶǄǦǃƽƾƙǊ.",
    ["现今又来咱营里当倒爷，围着杜砌银转了两三天了，没讨着好。"] = "ƩƶǓǦǁạƾǦǂƛǦǉớƾǦǤǄƶǃƽǦǉƶǦǁƐǂǦǀẻǦƷǊƇǃǦǁậǊ,ǦǆǊƶǃƽǦǆǊẩǃǦƷƙǃǦĐỗǦƦƽếǦƩƼƁǃǦƽƶƾǦƷƶǦǃƼƐǓǦǇồƾǦǂƐǦƸƽẳǃƼǦǍơǦǂƕƾǦđượƸǦƼƔ.",
    ["落到队正手里，正好趁着李会五这档子事，好好教训教训他！"] = "ƭơƾǦǋƐǄǦǉƶǓǦĐộƾǦƸƽƓǃƽ,ǦǃƽƁǃǦǉƾệǃǦǋụǦƧƈǦƣộƾǦƩƼũǦǃƐǓ,ǦǅƽảƾǦƼƾƑǄǦƽǊấǃǦƽắǃǦǂộǉǦǉǇậǃǦƸƽǄǦǇƶǦǉǇƛ!",
    ["也好叫他知道，想上登云梯，也得一级一级爬，还能叫他乱了次序。"] = "ƞũǃƼǦđểǦƽắǃǦƷƾếǉǦǇằǃƼ,ǦǂǊốǃǦǁƺǄǦǉƽƶǃƼǦǂƁǓǦǉƽƔǦǅƽảƾǦǁƺǄǦǉừǃƼǦƷậƸǦǂộǉ,ǦǈƶǄǦƸƚǦǉƽểǦđểǦƽắǃǦǁƐǂǦǁǄạǃǦǉƽứǦǉựǦđượƸ.",
    ["诶，我听说，他之前连江晏那小子都敢巴结，想进那边的亲兵营呢！"] = "Ê,ǦǉƶǦǃƼƽƺǦǃƚƾ,ǦǉǇướƸǦǀƾƶǦƽắǃǦǃƼƶǓǦƸảǦǉƽằǃƼǦǃƽƚƸǦƢƾƶǃƼǦƴếǃǦđƚǦƸũǃƼǦǤƑǂǦǃịǃƽǦƷợ,ǦǂǊốǃǦǋƐǄǦǉƽƁǃǦƷƾǃƽǦǤǄƶǃƽǦƷƙǃǦǀƾƶǦƸơǦđấǓ!",
    ["差点没让那瘟神给打出来！哈哈哈！"] = "ƮǊƈǉǦǃữƶǦǉƽƔǦƷịǦǋịǦƇǃǦǉƽầǃǦđƚǦđƑǃƽǦđǊổƾǦǇƶǦǃƼǄƐƾǦǇồƾ!ǦƣƶǦƽƶǦƽƶ!",
    ["吾乃汉敬侯费祎费文伟公之后，尔等安敢这般待我？！"] = "ǥƶǦǁƐǦƽậǊǦǤǊệǦƸủƶǦƣƑǃǦƦƓǃƽǦƽầǊǦƫƽƓǦƴǦƫƽƓǦƱăǃǦƱĩǦƸƇǃƼ,ǦƸƑƸǦǃƼươƾǦǈƶǄǦǤƑǂǦđốƾǦǍửǦǋớƾǦǉƶǦǃƽưǦǉƽếǦǃƐǓ?!",
    ["费亦可"] = "ƫƽƓǦǝƾệƸǦƦƽả",
    ["不儿，军爷、军爷，我知错了、知错了！我是您孙子！哎呦——"] = "ƦƽƇǃƼǦạ,ǦǆǊƁǃǦƼƾƶ,ǦǆǊƁǃǦƼƾƶ,ǦƸǄǃǦƷƾếǉǦǁỗƾǦǇồƾ,ǦƷƾếǉǦǁỗƾǦǇồƾ!ǦƞǄǃǦǁƐǦƸƽƑǊǦǃộƾǦƸủƶǦǃƼƐƾ!ǦÁƾǦƸƽƐ——",
    ["那、那李什么五，我是真不认识啊！骗您我就是那啃烂泥的大王八呀！哎呦——"] = "ƞƑƾ,ǦƸƑƾǦǉƙǃǦƧƈǦƼƔǦƩƼũǦđƚ,ǦƸǄǃǦǉƽựƸǦǈựǦǀƽƇǃƼǦǆǊƺǃǦƷƾếǉǦǂƐ!ǦƧừƶǦǃƼƐƾǦǉƽƔǦƸǄǃǦƸƽƓǃƽǦǁƐǦƸǄǃǦǇƖƶǦǇụǉǦƸổǦƼặǂǦƷƖǃǦǁǄƃǃƼǦǃƽƶ!ǦÁƾǦƸƽƐ——",
    ["行了，打这夯货也没啥意思，走，喝几盅去？"] = "ĐượƸǦǇồƾ,ǦđƑǃƽǦƸƑƾǦǁǄạƾǦđầǃǦđộǃǦǃƐǓǦƸũǃƼǦƸƽẳǃƼǦǉƽƕǦǋịǦƼƔ,Ǧđƾ,ǦǁƐǂǦǋƐƾǦƸƽƗǃǦǀƽƇǃƼ?",
    ["裴大壮"] = "ƝƖƾǦĐạƾǦǥǇƑǃƼ",
    ["成，走走走，看见这货便晦气。"] = "ǥƽƐǃƽǦƼƾƶǄ,ǦđƾǦđƾǦđƾ,ǦǃƽƔǃǦǉƽấǓǦǁǄạƾǦǃƐǓǦǁƐǦǉƽấǓǦǍǊƾǦǍẻǄǦǇồƾ.",
    ["商新新"] = "ǥƽươǃƼǦǥƁǃǦǥƁǃ",
    ["这厮倒偏要吊在此处，若是叫他瞧见我进了杜砌银的帐篷，倒是件麻烦事。"] = "ǥƙǃǦǃƐǓǦƸứǦǃƽấǉǦǆǊǓếǉǦǉǇƺǄǦǂƔǃƽǦởǦđƁǓ,ǦǃếǊǦđểǦƽắǃǦǉƽấǓǦǉƶǦǁẻǃǦǋƐǄǦǉǇướǃƼǦƸủƶǦĐỗǦƦƽếǦƩƼƁǃǦǉƽƔǦđƕǃƼǦǁƐǦǅƽƾềǃǦǅƽứƸ.",
    ["军爷，这位军爷一看就面善哪！还请留步呀军爷！"] = "ƬǊƁǃǦƼƾƶ,ǦǋịǦǆǊƁǃǦƼƾƶǦǃƐǓǦǃƽƔǃǦǂặǉǦǂũƾǦǉƽậǉǦǃƽƁǃǦǉừ!ǦƳƾǃǦǤừǃƼǦƷướƸǦǆǊƁǃǦƼƾƶǦơƾ!",
    ["军爷！我、我是忠臣良将之后，我有好大的孝敬要给军爷啊——"] = "ƬǊƁǃǦƼƾƶ!ǦƞǄǃ,ǦƸǄǃǦǁƐǦƽậǊǦǤǊệǦƸủƶǦǉǇǊǃƼǦǉƽầǃǦǁươǃƼǦǉướǃƼ,ǦƸǄǃǦƸƚǦǁễǦǋậǉǦƽậǊǦƽĩǃƽǦǂǊốǃǦƽƾếǊǦǀƓǃƽǦǆǊƁǃǦƼƾƶǦđƁǓǦạ——",
    ["谢军爷松绑之恩。"] = "ǥạǦơǃǦǆǊƁǃǦƼƾƶǦđƃǦƸởƾǦǉǇƚƾ.",
    ["军爷可还有什么需要差遣小的，小的——"] = "ƬǊƁǃǦƼƾƶǦƸƛǃǦƼƔǦƸầǃǦǈƶƾǦƷảǄǦǉƾểǊǦǃƽƁǃǦǀƽƇǃƼ,ǦǉƾểǊǦǃƽƁǃ——",
    ["是是是，这就滚。"] = "ƱƁǃƼǦǋƁǃƼǦǋƁǃƼ,ǦƸǄǃǦƸƕǉǦǃƼƶǓǦđƁǓ.",
    ["钥匙不见的时间，恰在与李会五喝酒之后……"] = "ǥƽờƾǦđƾểǂǦƸƽƔƶǦǀƽƚƶǦƷƾếǃǦǂấǉ,ǦƸƽƓǃƽǦǁƐǦǈƶǊǦǀƽƾǦǊốǃƼǦǇượǊǦǋớƾǦƧƈǦƣộƾǦƩƼũ……",
    ["难道是李会五？只是他已被斩首……"] = "ƧẽǦǃƐǄǦǁƐǦƧƈǦƣộƾǦƩƼũ?ǦƞƽỉǦƸƚǦđƾềǊǦƽắǃǦđƃǦƷịǦǉǇảǂǦǆǊǓếǉ……",
    ["老东西，快点收拾，别偷懒！"] = "ƧƃǄǦƼƾƐǦǀƾƶ,ǦǂƶǊǦǉƽǊǦǤọǃǦđƾ,ǦđừǃƼǦƸƚǦǁườƾǦƷƾếǃƼ!",
    ["莫让这些叛贼脏了咱行营的地。"] = "ĐừǃƼǦđểǦǁũǦǅƽảǃǦǉặƸǦǃƐǓǦǁƐǂǦƷẩǃǦđấǉǦƸủƶǦƽƐǃƽǦǤǄƶǃƽǦǉƶ.",
    ["士兵长"] = "ƮĩǦƷƾǃƽǦǉǇưởǃƼ",
    ["城头换天子，巷陌饿殍骨。圣贤皆蒙尘，英冢生草芜。"] = "ǥƽƐǃƽǦđầǊǦƽǄƑǃǦǥƽƾƙǃǦǉử,ǦƽạǃƼǦǂạƸƽǦǃƼạǦǅƽǊǦƸốǉ.ǦǥƽƑǃƽǦƽƾềǃǦƼƾƶƾǦǂƇǃƼǦǉǇầǃ,ǦƶǃƽǦǉǇủǃƼǦǈƾǃƽǦǉƽảǄǦǋǊ.",
    ["背尸叟"] = "ƧƃǄǦǉẩǊǦǋƑƸǦǍƑƸ",
    ["来来，大鸣子你也喝一口。还有……藏在那边的那位，你喝不喝？"] = "ƧạƾǦđƁǓ,ǦĐạƾǦƨƾǃƽǦǉửǦǃƼươƾǦƸũǃƼǦǊốǃƼǦǂộǉǦǃƼụǂǦđƾ.ǦƞƛǃǦǃữƶ……ǦǋịǦđƶǃƼǦǉǇốǃǦđằǃƼǦǀƾƶ,ǦǃƼươƾǦƸƚǦǊốǃƼǦǀƽƇǃƼ?",
    ["你什么时候发现我的？"] = "ƆǃƼǦǅƽƑǉǦƽƾệǃǦǇƶǦǉƶǦǉừǦǁƕƸǦǃƐǄ?",
    ["老朽只是年纪大了，耳朵不聋，眼睛不花。"] = "ƧƃǄǦƽủǦƸƽỉǦǁƐǦǉǊổƾǦǉƑƸǦđƃǦƸƶǄ,ǦǃƽưǃƼǦǉƶƾǦǀƽƇǃƼǦđƾếƸ,ǦǂắǉǦǀƽƇǃƼǦƽǄƶ.",
    ["李会五，你见过吗？"] = "ƧƈǦƣộƾǦƩƼũ,ǦƇǃƼǦđƃǦƼặǅǦƷƶǄǦƼƾờǦƸƽưƶ?",
    ["怎么，你问他？问他是要掉脑袋的。"] = "ƮƶǄ,ǦǃƼươƾǦƽỏƾǦƽắǃ?ǦƣỏƾǦǋềǦƽắǃǦǁƐǦǈẽǦƷịǦƷƶǓǦđầǊǦđấǓ.",
    ["老儿的头不值钱，你若不信，便割去试试。"] = "ƞƑƾǦđầǊǦƼƾƐǦǃƐǓǦƸƽẳǃƼǦđƑǃƼǦǉƾềǃǦđƁǊ,ǦǃƼươƾǦǃếǊǦǀƽƇǃƼǦǉƾǃǦǉƽƔǦƸứǦƸắǉǦǉƽửǦǍƺǂ.",
    ["你背着的是谁？"] = "ǥǇƙǃǦǁưǃƼǦƇǃƼǦđƶǃƼǦƸƅǃƼǦƶƾǦǋậǓ?",
    ["你问他？他叫樊大鸣，清河人， Thiên Phúc năm thứ sáu tòng quân."] = "ƩƼươƾǦƽỏƾǦƽắǃ?ǦƣắǃǦǉƙǃǦƫƽƐǃǦĐạƾǦƨƾǃƽ,ǦǃƼườƾǦǥƽƶǃƽǦƣƐ,ǦǃăǂǦǥƽƾƙǃǦƫƽƕƸǦǉƽứǦǈƑǊǦǉƛǃƼǦǆǊƁǃ.",
    ["天福七年，于秀谷斩过虏人三首。"] = "ƩăǂǦǥƽƾƙǃǦƫƽƕƸǦǉƽứǦƷảǓ,ǦǉạƾǦǥƕǦƞốƸǦƸƽƗǂǦƷƶǦǉƽủǦƸấǅǦǆǊƁǃǦƼƾặƸ.",
    ["开运二年，又斩虏人骑兵两骑。"] = "ƩăǂǦƦƽƶƾǦƱậǃǦǉƽứǦƽƶƾ,ǦǁạƾǦƸƽƗǂǦƽƶƾǦǀỵǦƷƾǃƽǦƼƾặƸ.",
    ["至三月，随行营军北伐，连克泰州、满城、遂城！"] = "ĐếǃǦǉƽƑǃƼǦƝƶ,ǦǉƽƺǄǦƽƐǃƽǦǤǄƶǃƽǦǆǊƁǃǦƝắƸǦǅƽạǉ,ǦǁƾƙǃǦǉƾếǅǦƽạǦǥƽƑƾǦƞƽƁǊ,ǦƨƃǃǦǥƽƐǃƽ,ǦǥǄạƾǦǥƽƐǃƽ!",
    ["短短几载，倒也算得军功彪炳。可如今，却死在这里。"] = "ƞƽỉǦǉǇǄǃƼǦǂấǓǦǃăǂǦǃƼắǃǦǃƼủƾ,ǦƸũǃƼǦƸǄƾǦǁƐǦǆǊƁǃǦƸƇǃƼǦƽƾểǃǦƽƑƸƽ.ǦƱậǓǦǂƐǦƼƾờǦđƁǓ,ǦǁạƾǦƸƽếǉǦởǦǃơƾǦǃƐǓ.",
    ["瞧瞧，瞧瞧，大鸣子的脸都花了。"] = "ƩƽƔǃǦǍƺǂ,ǦǃƽƔǃǦǍƺǂ,ǦǂặǉǦƸủƶǦĐạƾǦƨƾǃƽǦǉửǦđềǊǦƷƾếǃǦǤạǃƼǦƸảǦǇồƾ.",
    ["这位兄弟，劳你搭把手，老朽给他洗洗。"] = "ƱịǦƽǊǓǃƽǦđệǦǃƐǓ,ǦǁƐǂǦǅƽƾềǃǦǃƼươƾǦƼƾƕǅǦǂộǉǦǉƶǓ,ǦđểǦǁƃǄǦƽủǦǁƶǊǦǇửƶǦƸƽǄǦƽắǃ.",
    ["你不怕我？"] = "ƆǃƼǦǀƽƇǃƼǦǈợǦǉƶǦǈƶǄ?",
    ["为何要怕，老朽这辈子该见的，不该见的，都见过了。"] = "ǥạƾǦǈƶǄǦǅƽảƾǦǈợ,ǦǁƃǄǦƽủǦđờƾǦǃƐǓǦƸƑƾǦǃƙǃǦǉƽấǓ,ǦƸƑƾǦǀƽƇǃƼǦǃƙǃǦǉƽấǓ,ǦđềǊǦđƃǦǉƽấǓǦƸảǦǇồƾ.",
    ["像你这般的痴人，老朽见得最多。"] = "ƣạǃƼǦǃƼườƾǦǈƾǦǃƼốƸǦǃƽưǦǃƼươƾ,ǦǁƃǄǦƽủǦǉƽấǓǦǃƽƾềǊǦǃƽấǉ.",
    ["一个个又轴又硬，骨头从战场上戳到了地底下，埋都埋不住。"] = "ǥừǃƼǦǃƼườƾǦǉừǃƼǦǃƼườƾǦđềǊǦƷướǃƼǦƷỉǃƽǦƸứǃƼǦƸỏƾ,ǦǍươǃƼǦƸốǉǦđƁǂǦǉừǦƸƽƾếǃǦǉǇườǃƼǦǍǊốǃƼǦǉậǃǦǁƛǃƼǦđấǉ,ǦƸƽƇǃǦƸũǃƼǦǀƽƇǃƼǦǁấǅǦƽếǉǦđượƸ.",
    ["能战死沙场，也算荣誉。"] = "ƞƚǦǉƽểǦƸƽƾếǃǦǉửǦǈƶǦǉǇườǃƼ,ǦƸũǃƼǦƸǄƾǦǁƐǦǋƾǃƽǦǤự.",
    ["荣誉？狗屁！"] = "ƱƾǃƽǦǤự?ǦƞƽƚǦǂƑ!",
    ["在大梁的时候，跟各地的军阀打，到了大唐，还是一样。"] = "ǥƽờƾǦđạƾǦƧươǃƼǦǉƽƔǦđƑǃƽǦǋớƾǦǆǊƁǃǦǅƽƾệǉǦƸƑƸǦǃơƾ,ǦđếǃǦǉƽờƾǦđạƾǦĐườǃƼ,ǦǋẫǃǦƸứǦǃƽưǦǋậǓ.",
    ["皇帝、藩镇，明里暗里的争权夺利。俺们这些丘八，从来都是当刀子使！"] = "ƣǄƐǃƼǦđế,ǦǅƽƾƙǃǦǉǇấǃ,ǦǃƼǄƐƾǦǂặǉǦǉǇǄǃƼǦǉốƾǦǉǇƶǃƽǦǆǊǓềǃǦđǄạǉǦǁợƾ.ǦƧũǦǀƽƁǊǦƷƑǉǦƸƽƕǃƼǦǉƶ,ǦǉừǦǉǇướƸǦđếǃǦǃƶǓǦđềǊǦƷịǦđƺǂǦǇƶǦǁƐǂǦǤƶǄǦđểǦǈƶƾǦǀƽƾếǃ!",
    ["一年大大小小打了几十场仗！可结果呢？那城头上的天子，换了一位又一位。"] = "ƨộǉǦǃăǂǦǁớǃǦǃƽỏǦđƑǃƽǦǉớƾǦǂấǓǦƸƽụƸǦǉǇậǃ!ǦƩƽưǃƼǦǀếǉǦƸụƸǦǉƽƔǦǈƶǄ?ǦǥƽƾƙǃǦǉửǦǉǇƙǃǦǉƽƐǃƽǦđầǊǦǉƽƶǓǦƽếǉǦǋịǦǃƐǓǦđếǃǦǋịǦǀƽƑƸ.",
    ["这荒地上的尸首，冻死的，饿死的，还是一堆叠着一堆。"] = "ǥƽƁǓǦǂƶǦǉǇƙǃǦƷƃƾǦđấǉǦƽǄƶǃƼǦǃƐǓ,ǦǀẻǦƸƽếǉǦǇƗǉ,ǦǃƼườƾǦƸƽếǉǦđƚƾ,ǦǋẫǃǦƸứǦƸƽấǉǦǉƽƐǃƽǦđốǃƼǦǃƐǓǦđếǃǦđốǃƼǦǀƽƑƸ.",
    ["刀子……是啊，我的父兄，也曾是刀子……"] = "ƞǄǃǦǤƶǄ……ǦǅƽảƾǦǇồƾ,ǦǅƽụǦƽǊǓǃƽǦƸủƶǦǉƶ,ǦƸũǃƼǦǉừǃƼǦǁƐǦǃƽữǃƼǦƸǄǃǦǤƶǄ……",
    ["丁文书，你不认得老朽，老朽却认得你，认得你的父亲。"] = "ĐƾǃƽǦǋăǃǦǉƽư,ǦǃƼươƾǦǀƽƇǃƼǦǃƽậǃǦǇƶǦǁƃǄǦƽủ,ǦǃƽưǃƼǦǁƃǄǦƽủǦǁạƾǦǃƽậǃǦǇƶǦǃƼươƾ,ǦǃƽậǃǦǇƶǦǅƽụǦǉƽƁǃǦƸủƶǦǃƼươƾ.",
    ["两年前，便是我背着你父亲，到的乱葬岗。朝廷的援军，来得太晚了。"] = "ƣƶƾǦǃăǂǦǉǇướƸ,ǦƸƽƓǃƽǦǁƃǄǦƽủǦđƃǦƸƅǃƼǦǅƽụǦǉƽƁǃǦǃƼươƾǦǉớƾǦƷƃƾǦǉƽƶǦǂƶ.ǦƱƾệǃǦǆǊƁǃǦƸủƶǦǉǇƾềǊǦđƔǃƽǦđếǃǦǆǊƑǦǂǊộǃǦǇồƾ.",
    ["我们……当了那么多年的刀子，可现在该拿这刀子去杀虏人的时候，却又什么都不让做了。"] = "ƞƽƕǃƼǦǉƶ……ǦǁƐǂǦǤƶǄǦƷƶǄǦǃƽƾƙǊǦǃăǂǦǃƶǓ,ǦǃƽưǃƼǦƼƾờǦđƁǓǦǀƽƾǦƸầǃǦƸầǂǦƸǄǃǦǤƶǄǦǃƐǓǦđƾǦƼƾếǉǦǆǊƁǃǦƼƾặƸ,ǦǉƽƔǦǁạƾǦƸƽẳǃƼǦđượƸǦǁƐǂǦƼƔǦƸả.",
    ["因为拿刀的人怕了，他们不顾惜刀子的命，却很爱惜自己的命。他们怕被更快的箭射穿喉咙，于是宁可折刀，也不敢用刀。"] = "ƝởƾǦǋƔǦǀẻǦƸầǂǦǤƶǄǦǈợǦǇồƾ,ǦƸƽƕǃƼǦǀƽƇǃƼǦǂƐǃƼǦđếǃǦǂạǃƼǦƸủƶǦƸǄǃǦǤƶǄ,ǦǃƽưǃƼǦǁạƾǦǇấǉǦǆǊƈǦǂạǃƼǦƸủƶǦǂƔǃƽ.ǦƞƽƕǃƼǦǈợǦƷịǦǂũƾǦǉƙǃǦǃƽƶǃƽǦƽơǃǦǍǊǓƙǃǦǉƽủǃƼǦƸổǦƽọǃƼ,ǦǃƙǃǦǉƽƐǦƷẻǦƼƃǓǦǤƶǄǦƸƽứǦǀƽƇǃƼǦǤƑǂǦǤƖǃƼǦǤƶǄ.",
    ["你知道那个李会五，因何而死吗？来，我来告诉你——"] = "ƩƼươƾǦƸƚǦƷƾếǉǦƧƈǦƣộƾǦƩƼũǦđƚǦǋƔǦǈƶǄǦǂƐǦƸƽếǉǦǀƽƇǃƼ?ǦƧạƾǦđƁǓ,ǦđểǦǉƶǦǃƚƾǦƸƽǄǦǃƼươƾǦƷƾếǉ——",
    ["因为，他知道了一个大帅的秘密，哪怕他曾经得过天大的军功，也得去死的秘密——"] = "ƝởƾǦǋƔ,ǦƽắǃǦđƃǦƷƾếǉǦđượƸǦǂộǉǦƷƓǦǂậǉǦƸủƶǦĐạƾǦǈǄƑƾ,ǦƸƑƾǦƷƓǦǂậǉǦǂƐǦǤƖǦƽắǃǦƸƚǦǉừǃƼǦǁậǅǦǆǊƁǃǦƸƇǃƼǦƽƾểǃǦƽƑƸƽǦđếǃǦđƁǊǦƸũǃƼǦǅƽảƾǦƸƽếǉ——",
    ["不知道。老朽只知道，他很想把那个秘密传出去。"] = "ƦƽƇǃƼǦƷƾếǉ.ǦƧƃǄǦƽủǦƸƽỉǦƷƾếǉ,ǦƽắǃǦǇấǉǦǂǊốǃǦǉǇǊǓềǃǦƸƑƾǦƷƓǦǂậǉǦđƚǦǇƶǦǃƼǄƐƾ.",
    ["可惜啊，老朽背得他出去，那个消息，却传不出去了……"] = "ĐƑǃƼǦǉƾếƸǦǉƽƶǓ,ǦǁƃǄǦƽủǦƸƅǃƼǦđượƸǦƽắǃǦǇƶ,ǦǃƽưǃƼǦƸƑƾǦǉƾǃǦđƚǦǉƽƔǦǀƽƇǃƼǦǉǇǊǓềǃǦǇƶǦđượƸǦǃữƶǦǇồƾ……",
    ["拿着吧，这个东西，或许是他留在这个世上，仅剩的东西了。"] = "ƞầǂǦǁấǓǦđƾ,ǦǉƽứǦǃƐǓǦƸƚǦǁẽǦǁƐǦǋậǉǦǤǊǓǦǃƽấǉǦƽắǃǦƸƛǃǦđểǦǁạƾǦǉǇƙǃǦǉƽếǦƼƾƶǃǦǃƐǓ.",
    ["见着没，大帅招待客人，那端进去的都是大鱼大肉，哪像咱，干馍馍都不够啃。"] = "ǥƽấǓǦƸƽưƶ,ǦĐạƾǦǈǄƑƾǦƸƽƾƙǊǦđƃƾǦǀƽƑƸƽǦǀƽứƶ,ǦƷưǃƼǦǋƐǄǦǉǄƐǃǦǁƐǦƸƑǦǁớǃǦǉƽịǉǦƷƗǄ,ǦđƁǊǦƸƚǦǃƽưǦƷọǃǦǂƔǃƽ,ǦƷƑǃƽǦǀƽƇǦƸƛǃǦƸƽẳǃƼǦđủǦƼặǂ.",
    ["难不成就这么继续窝着，等着被虏人围成一笼包子吗？"] = "ƧẽǦǃƐǄǦƸứǦǉƾếǅǦǉụƸǦƸǄǦǇụǉǦǉƽếǦǃƐǓ,ǦđợƾǦǆǊƁǃǦƼƾặƸǦǋƁǓǦǁạƾǦǉƽƐǃƽǦǂộǉǦǁồǃƼǦƷƑǃƽǦƷƶǄǦǈƶǄ?",
    ["愿意北去的弟兄不少。"] = "ƣǊǓǃƽǦđệǦǃƼǊǓệǃǦƈǦđƾǦǋềǦǅƽƓƶǦƝắƸǦǀƽƇǃƼǦƓǉǦđƁǊ.",
    ["小弟算过，跟着王清将军搏一把，胜算，至少这个数。"] = "ǥƾểǊǦđệǦđƃǦǉƓǃƽǦǉǄƑǃǦǆǊƶ,ǦđƾǦǉƽƺǄǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃǦǁƾềǊǦǂộǉǦǅƽƺǃ,ǦǉƽắǃƼǦǉǄƑǃǦƓǉǦǃƽấǉǦƸũǃƼǦǁƐǦƸǄǃǦǈốǦǃƐǓ.",
    ["可杜帅那边不是——"] = "ƩƽưǃƼǦǅƽƓƶǦĐỗǦǈǄƑƾǦƸƽẳǃƼǦǅƽảƾǦǁƐ——",
    ["童三穗"] = "ĐồǃƼǦǥƶǂǦǥǊế",
    ["不是什么？哥你直说呀。咱们现在，不都是一窝의 兔子，被按在这烂泥里，等着虏人宰？"] = "ƞƽẳǃƼǦǅƽảƾǦǁƐǦƼƔ?ǦƞƶǦƸứǦǃƚƾǦǉƽẳǃƼǦǇƶǦđƾ.ǦƞƽƕǃƼǦǉƶǦƷƁǓǦƼƾờǦƸƽẳǃƼǦǅƽảƾǦđềǊǦǁƐǦǂộǉǦổǦǉƽỏ,ǦƷịǦấǃǦǍǊốǃƼǦǋũǃƼǦƷƖǃǦǃƐǓǦƸƽờǦǆǊƁǃǦƼƾặƸǦǉƽịǉǦǈƶǄ?",
    ["兔子还会蹬鹰呢，咱手里有刀剑，都不扑腾两下，还算什么爷们！"] = "ǥƽỏǦƸƛǃǦƷƾếǉǦđƑǦưǃƼǦƸơǦǂƐ,ǦǉǇǄǃƼǦǉƶǓǦƸƽƕǃƼǦǉƶǦƸƚǦđƶǄǦǀƾếǂ,ǦǃếǊǦǀƽƇǃƼǦǋƖǃƼǦǋẫǓǦǋƐƾǦƸƑƾǦǉƽƔǦƸƛǃǦǉƓǃƽǦǁƐǦǃƶǂǦǃƽƾǦƸƽƾǦǉửǦƼƔǦǃữƶ!",
    ["奶奶的！谁说不是，我也早觉着窝囊了！"] = "ƩƃƾǦǃƃƾǦǃƚǦƸƽứ!ǦƜƾǦƷảǄǦǀƽƇǃƼǦǅƽảƾ,ǦǉƶǦƸũǃƼǦǉƽấǓǦǃƽụƸǦǃƽƃǦǉừǦǁƁǊǦǇồƾ!",
    ["……罢了。萧老弟，你读过书，比我们哥几个会盘算。"] = "……ǥƽƇƾǦđượƸǦǇồƾ.ǦǥƾƙǊǦǁƃǄǦđệ,ǦđệǦǁƐǦǃƼườƾǦƸƚǦƽọƸ,ǦƷƾếǉǦǉƓǃƽǦǉǄƑǃǦƽơǃǦǂấǓǦƶǃƽǦƺǂǦǉƶ.",
    ["韩老五"] = "ƣƐǃǦƧƃǄǦƩƼũ",
    ["我们也不想被乡亲戳脊梁骨，骂我们只敢窝里横，遇到虏人就怂蛋……"] = "ƝọǃǦǉƶǦƸũǃƼǦǀƽƇǃƼǦǂǊốǃǦƷịǦƷƐǦƸǄǃǦǁốƾǦǍƚǂǦđƁǂǦƸƽọƸǦǈƶǊǦǁưǃƼ,ǦƸƽửƾǦƷọǃǦǉƶǦƸƽỉǦƼƾỏƾǦƽǄƐǃƽǦƽƐǃƽǦǉǇǄǃƼǦǃƽƐ,ǦƼặǅǦǆǊƁǃǦƼƾặƸǦǁƐǦǃƽũǃǦǃƽưǦƸƽƾǦƸƽƾ……",
    ["咱们跟你走！只是，就怕家伙什不够。"] = "ƝọǃǦǉƶǦđƾǦǉƽƺǄǦđệ!ǦƞƽỉǦǁƐ,ǦǈợǦǁƐǦǋũǦǀƽƓǦǉǇƶǃƼǦƷịǦǀƽƇǃƼǦđủ.",
    ["兄弟，借口水——哎！萧兄弟，你也在这儿啊……"] = "ƣǊǓǃƽǦđệ,ǦǍƾǃǦƽớǅǦǃướƸ——ǦƠ!ǦǥƾƙǊǦƽǊǓǃƽǦđệ,ǦđệǦƸũǃƼǦởǦđƁǓǦƐ……",
    ["水？我这儿还有口烧刀子，就怕你有借不还。"] = "ƩướƸǦǈƶǄ?ǦǥƶǦởǦđƁǓǦƸƛǃǦƽớǅǦǇượǊǦǥƽƾƙǊǦĐƶǄǦǥử,ǦƸƽỉǦǈợǦǃƼươƾǦǂượǃǦǂƐǦǀƽƇǃƼǦǉǇảǦǉƽƇƾ.",
    ["好酒怎能不还？正好刚做成笔买卖，拿大钱还你。一刻之后，找我来拿。"] = "ƭượǊǦǃƼǄǃǦǈƶǄǦƸƚǦǉƽểǦǀƽƇǃƼǦǉǇả?ǦƱừƶǦƽƶǓǦǂớƾǦǁƐǂǦǍǄǃƼǦǋụǦǁƐǂǦăǃ,ǦǁấǓǦǉƾềǃǦǁớǃǦǉǇảǦǃƼươƾ.ǦƨộǉǦǀƽắƸǦǈƶǊǦǉớƾǦǉƔǂǦǉƶǦǂƐǦǁấǓ.",
    ["那丁笑贴着的人是杜家的穷亲戚，萧老弟你的酒倒河里了哦。"] = "ƦẻǦǂƐǦĐƾǃƽǦǥƾếǊǦƷƑǂǦǉƽƺǄǦǁƐǦƽọǦƽƐǃƼǦǃƼƽƘǄǦƸủƶǦĐỗǦƼƾƶ,ǦǥƾƙǊǦǁƃǄǦđệ,ǦǇượǊǦƸủƶǦđệǦđổǦǍǊốǃƼǦǈƇǃƼǦǇồƾǦđƚ.",
    ["看守军库的人多，在拿到东西前，还是不要打草惊蛇。"] = "ƩƼườƾǦƸƶǃƽǦƼƾữǦǆǊƁǃǦǀƽốǦǇấǉǦđƇǃƼ,ǦǉǇướƸǦǀƽƾǦǁấǓǦđượƸǦđồǦǉƽƔǦđừǃƼǦđƑǃƽǦƸỏǦđộǃƼǦǇắǃ.",
    ["正好试试孟叔送来的东西。"] = "ƱừƶǦƽƶǓǦǉƽửǦǃƼƽƾệǂǦǂấǓǦǉƽứǦƨạǃƽǦǉƽƕƸǦƼửƾǦǉớƾ.",
    ["徐、徐老弟，咱们这也算掏心窝子在卖力。杜库吏不在，这军库不照样看得严严实实，没出半、半点儿褶子。"] = "ǥừ,ǦǥừǦǁƃǄǦđệ,ǦƷọǃǦǂƔǃƽǦǉƽếǦǃƐǓǦƸũǃƼǦƸǄƾǦǁƐǦǤốƸǦƽếǉǦǉƾǂǦƼƶǃǦǇƶǦǁƐǂǦǋƾệƸǦǇồƾ.ǦĐỗǦǀƽốǦǁạƾǦǀƽƇǃƼǦƸƚǦǂặǉ,ǦǆǊƁǃǦǀƽốǦǃƐǓǦƸƽẳǃƼǦǅƽảƾǦǋẫǃǦđượƸǦǉǇƇǃƼǦƸǄƾǦǃƼƽƾƙǂǦǃƼặǉ,ǦǀƽƇǃƼǦđểǦǍảǓǦǇƶǦǃửƶǦđƾểǂǦǈƶƾǦǈƚǉǦđƚǦǈƶǄ.",
    ["高令德"] = "ƞƶǄǦƧệǃƽǦĐứƸ",
    ["是，弟弟敬哥哥一杯。等杜库吏回来，定要夸奖哥哥尽忠尽职。"] = "ƫƽảƾ,ǦđệǦđệǦǀƓǃƽǦƸƶǦƸƶǦǂộǉǦƸƽƗǃ.ǦĐợƾǦĐỗǦǀƽốǦǁạƾǦǋề,ǦǃƽấǉǦđịǃƽǦǈẽǦǀƽƺǃǦǃƼợƾǦƸƶǦƸƶǦǉậǃǦǉǇǊǃƼǦƸƽứƸǦǉƽủ.",
    ["徐苛"] = "ǥừǦƦƽƶ",
    ["嗨，都是些虚、虚名！说起来杜库吏都多久没回来了？"] = "ƣạƾ,ǦǉǄƐǃǦǁƐǦƽưǦǤƶǃƽǦƸảǦǉƽƇƾ!ǦƨƐǦǃƽắƸǦǂớƾǦǃƽớ,ǦĐỗǦǀƽốǦǁạƾǦđƾǦƷƶǄǦǁƁǊǦǇồƾǦƸƽưƶǦǋềǦǃƽỉ?",
    ["可好一阵了，上次见他来，还是大帅发火那天。"] = "ƞũǃƼǦǂộǉǦƽồƾǦǁƁǊǦǇồƾ,ǦǁầǃǦǉǇướƸǦǉƽấǓǦƽắǃǦǉớƾ,ǦǋẫǃǦǁƐǦǋƐǄǦƸƑƾǦǃƼƐǓǦĐạƾǦǈǄƑƾǦǃổƾǦǉǇậǃǦǁƇƾǦđƔǃƽ.",
    ["他娘的，这两天怎么老觉得军库里有怪声儿？"] = "ƨẹǦǀƾếǅ,ǦƽƶƾǦǃƼƐǓǦǃƶǓǦǈƶǄǦƸứǦǉƽấǓǦǉǇǄǃƼǦǆǊƁǃǦǀƽốǦƸƚǦǉƾếǃƼǦđộǃƼǦǁạǦǃƽỉ?",
    ["程林"] = "ǥǇƔǃƽǦƧƁǂ",
    ["老鼠呗。里头不是有个暗道儿通到营外，之前还走过货的？"] = "ǥƽƔǦđƑǂǦƸƽǊộǉǦƸƽứǦđƁǊ.ǦƝƙǃǦǉǇǄǃƼǦƸƽẳǃƼǦǅƽảƾǦƸƚǦǂộǉǦǂậǉǦđạǄǦǉƽƇǃƼǦǇƶǦǃƼǄƐƾǦǤǄƶǃƽ,ǦǉǇướƸǦđƁǓǦƸƛǃǦǤƖǃƼǦđểǦƸƽǊǓểǃǦƽƐǃƼǦǈƶǄ?",
    ["谭宏"] = "ĐƐǂǦƣồǃƼ",
    ["我那天往那门里一看，嚯，耗子安了家了，一只得有一斤重嘞！"] = "ƣƇǂǦđƚǦǉƶǦǃƽƔǃǦǋƐǄǦǉǇǄǃƼǦƸửƶǦǀƾƶ,Ǧƽừǂ,ǦǁũǦƸƽǊộǉǦǁƐǂǦǉổǦởǦđƚǦǇồƾ,ǦǂỗƾǦƸǄǃǦǅƽảƾǦǃặǃƼǦđếǃǦƸảǦƸƁǃǦấǓǦƸƽứ!",
    ["那狗仗人势的家伙，往日净是叔父长叔父短，现在呢？还不是叫人给一脚踢开！"] = "ƞƑƾǦǉƙǃǦƸƽƚǦƸậǓǦƼầǃǦǃƽƐǦƼƐǦƸậǓǦƼầǃǦƸƽǊồǃƼǦđƚ,ǦǃƼƐǓǦǉƽườǃƼǦƸứǦǁǊƇǃǦǂƾệǃƼǦǉƽƕƸǦǅƽụǦǃƐǓǦǉƽƕƸǦǅƽụǦǃọ,ǦƼƾờǦǉƽƔǦǈƶǄ?ǦƞƽẳǃƼǦǅƽảƾǦƷịǦǃƼườƾǦǉƶǦđƑǦǋăǃƼǦđƾǦǇồƾǦđƚǦǉƽƇƾ!",
    ["刘二马"] = "ƧưǊǦƩƽịǦƨƃ",
    ["嗨，除了他自己，谁真拿他当大帅亲戚？八竿子打不着的破落户，我看大帅也不爱搭理他！"] = "ƣạƾ,ǦǃƼǄƐƾǦƷảǃǦǉƽƁǃǦƽắǃǦǇƶ,ǦƶƾǦǉƽƘǂǦƸǄƾǦƽắǃǦǁƐǦǉƽƁǃǦǉƽƓƸƽǦƸủƶǦĐạƾǦǈǄƑƾ?ǦƞƑƾǦƽạǃƼǦǃƼƽƘǄǦǀƾếǉǦǍƑƸǦƷắǃǦđạƾǦƷƑƸǦǂớƾǦǉớƾ,ǦǉƶǦǉƽấǓǦĐạƾǦǈǄƑƾǦƸũǃƼǦƸƽẳǃƼǦƷǊồǃǦđếǂǦǍỉƶǦƼƔǦđếǃǦƽắǃ!",
    ["雷七哥"] = "ƧƇƾǦǥƽấǉǦƞƶ",
    ["诶老刘，你说他犯了事，这库吏的位置，是不是又该回到你头上了？"] = "ÊǦǁƃǄǦƧưǊ,ǦǃƼươƾǦǃƚƾǦǍƺǂǦƽắǃǦǅƽạǂǦǁỗƾǦǇồƾ,ǦƸƑƾǦƸƽứƸǦƦƽốǦǁạƾǦǃƐǓǦƸƚǦǅƽảƾǦǁƐǦǈẽǦǆǊƶǓǦǋềǦǉƶǓǦǃƼươƾǦǀƽƇǃƼ?",
    ["听说他前阵子悄摸帮大帅走了点生意，捞着不少油水呢！你可得……"] = "ƩƼƽƺǦǃƚƾǦǤạǄǦǉǇướƸǦƽắǃǦǁƗǃǦƼƾƕǅǦĐạƾǦǈǄƑƾǦǁƐǂǦăǃǦƸƽƕǉǦđỉǃƽ,ǦǋớǦđượƸǦǀƽƇǃƼǦƓǉǦǤầǊǦǂỡǦđƁǊ!ǦƩƼươƾǦǅƽảƾ……",
    ["到了。想必萧兄弟他们，已在营外的暗道口候着了。"] = "ǥớƾǦǇồƾ.ǦƞƽắƸǦƽẳǃǦƷọǃǦǃƼườƾǦǥƾƙǊǦƽǊǓǃƽǦđệǦđƶǃƼǦđợƾǦởǦƸửƶǦǂậǉǦđạǄǦǃƼǄƐƾǦǤǄƶǃƽǦǇồƾ.",
    ["只消启开暗门，引他们进来，把东西稳妥运出去，便算成了。"] = "ƞƽỉǦƸầǃǦǂởǦǂậǉǦǂƇǃ,ǦǤẫǃǦƽọǦǋƐǄǦǉǇǄǃƼ,ǦđƺǂǦđồǦđạƸǦǋậǃǦƸƽǊǓểǃǦǇƶǦǃƼǄƐƾǦƶǃǦǉǄƐǃ,ǦƸǄƾǦǃƽưǦǁƐǦǉƽƐǃƽǦƸƇǃƼ.",
    ["但愿这批物资，能帮上王清将军……"] = "ƣǓǦǋọǃƼǦǁƇǦǋậǉǦǉưǦǃƐǓǦƸƚǦǉƽểǦƼƾƕǅǦđượƸǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃ……",
    ["……空、空的？怎么会？"] = "……ǥǇốǃƼ,ǦǉǇốǃƼǦǀƽƇǃƼǦǈƶǄ?ǦƮƶǄǦǁạƾǦǉƽếǦǃƐǓ?",
    ["杜砌银，你真是……"] = "ĐỗǦƦƽốǦƩƼƁǃ,ǦǃƼươƾǦǉƽậǉǦǁƐ……",
    ["等等，那儿……留了一个盒子？"] = "ƦƽǄƶǃǦđƃ,ǦđằǃƼǦǀƾƶ……ǦđểǦǁạƾǦǂộǉǦƸƽƾếƸǦƽộǅ?",
    ["杜砌——银？！"] = "ĐỗǦƦƽố——ƩƼƁǃ?!",
    ["天上桫椤是什么人儿栽，地下黄河是什么人儿开？"] = "ǥǇƙǃǦǉǇờƾǦǈƶǦǁƶǦǁƐǦǃƼườƾǦǃƐǄǦǉǇồǃƼ,ǦǤướƾǦđấǉǦƣǄƐǃƼǦƣƐǦǁƐǦǃƼườƾǦǃƐǄǦǀƽơƾ?",
    ["秀姑娘"] = "ǥƕǦƸƇǦǃươǃƼ",
    ["姑娘唱的是什么，真好听。"] = "ƞƇǦǃươǃƼǦƽƑǉǦƷƐƾǦƼƔǦǋậǓ,ǦǃƼƽƺǦƽƶǓǦǆǊƑ.",
    ["是……是我们本地的小曲儿，大伙儿要是喜欢，我就教大家唱一段。"] = "ƧƐ……ǦǁƐǦđƾệǊǦƽƑǉǦǤƁǃǦǤƃǦởǦđịƶǦǅƽươǃƼǦƸƽƕǃƼǦǉƶ,ǦǃếǊǦǂọƾǦǃƼườƾǦǉƽƓƸƽ,ǦǉƶǦǈẽǦǤạǓǦǂọƾǦǃƼườƾǦƽƑǉǦǂộǉǦđǄạǃ.",
    ["那敢情好啊！秀姑娘，你要s能叫我那木头师弟开金口……"] = "ǥƽếǦǉƽƔǦǉốǉǦǆǊƑǦǇồƾ!ǦǥƕǦƸƇǦǃươǃƼ,ǦǃếǊǦƸƇǦƸƚǦǉƽểǦǀƽƾếǃǦƸƽǄǦǋịǦƨộƸǦĐầǊǦǈưǦđệǦǃƐǓǦƸủƶǦǉƶǦƸƽịǊǦǂởǦǂƾệǃƼǦǋƐǃƼ……",
    ["师兄——"] = "ƮưǦƽǊǓǃƽ——",
    ["启昭大哥，不喜欢唱歌么？"] = "ƦƽảƾǦƞƽƾƙǊǦđạƾǦƸƶǦǀƽƇǃƼǦǉƽƓƸƽǦƽƑǉǦǈƶǄ?",
    ["他呀，他喜欢修桥！"] = "ƣǊǓǃƽǦấǓǦấǓǦƐ,ǦƽǊǓǃƽǦấǓǦǉƽƓƸƽǦǉǊǦƷổǦƸầǊǦƸốǃƼǦƸơ!",
    ["桥……那我们这儿还有赵州桥、小石桥，等以后……"] = "ƞầǊ……ǦǋậǓǦởǦƸƽỗǦƸƽƕǃƼǦǉƶǦƸƛǃǦƸƚǦƸầǊǦǥǇƾệǊǦƞƽƁǊ,ǦƸầǊǦǥƾểǊǦǥƽạƸƽ,ǦđợƾǦǈƶǊǦǃƐǓ……",
    ["他什么桥都修过，只没修过鹊桥！"] = "ƞầǊǦƼƔǦƽǊǓǃƽǦấǓǦƸũǃƼǦǉừǃƼǦǉǊǦƷổ,ǦǤǊǓǦƸƽỉǦƸƚǦƸầǊǦƆǦǥƽướƸǦǁƐǦƸƽưƶǦǉừǃƼǦǉǊǦǉƽƇƾ!",
    ["这一路上，同道人还真不少！"] = "ǥǇƙǃǦđườǃƼǦđƾǦǃƐǓ,ǦǃƼườƾǦƸƖǃƼǦƸƽƓǦƽướǃƼǦǆǊảǦǉƽựƸǦǀƽƇǃƼǦƓǉ!",
    ["诸位！"] = "ƞƽưǦǋị!",
    ["诸位可是前去援助王清将军的义士？"] = "ƞƽưǦǋịǦđƁǓǦǅƽảƾǦƸƽăǃƼǦǁƐǦǃƼƽĩƶǦǈĩǦđƾǦƸƽƾǦǋƾệǃǦƸƽǄǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃ?",
    ["在下乃汉敬侯费祎费文伟公之后，特来相助！"] = "ǥạƾǦƽạǦǁƐǦƽậǊǦǤǊệǦƸủƶǦƣƑǃǦƦƓǃƽǦƽầǊǦƫƽƓǦƴǦƫƽƓǦƱăǃǦƱĩǦƸƇǃƼ,ǦđặƸǦƷƾệǉǦǉớƾǦđểǦǉươǃƼǦǉǇợ!",
    ["我有紧要军情要知会小江将军，可知他在何处？"] = "ǥƶǦƸƚǦǆǊƁǃǦǉƔǃƽǦǀƽẩǃǦƸấǅǦǂǊốǃǦƷƑǄǦƸƽǄǦǥƾểǊǦƢƾƶǃƼǦǉướǃƼǦǆǊƁǃ,ǦƸƚǦƷƾếǉǦǃƼƐƾǦấǓǦởǦǃơƾǦǃƐǄǦƸƽăǃƼ?",
    ["什么军情？若要紧，速速说来！"] = "ƬǊƁǃǦǉƔǃƽǦƼƔ?ǦƩếǊǦƽệǦǉǇọǃƼǦǉƽƔǦǂƶǊǦǂƶǊǦǃƚƾǦǇƶ!",
    ["这……事关重大，只可说与小江将军一人！"] = "ƞƽǊǓệǃǦǃƐǓ……ǦƸƶǃǦƽệǦǉǇọǃƼǦđạƾ,ǦƸƽỉǦƸƚǦǉƽểǦǃƚƾǦǋớƾǦǂộǉǦǂƔǃƽǦǥƾểǊǦƢƾƶǃƼǦǉướǃƼǦǆǊƁǃ!",
    ["呵！我当是谁，这不是满街乱窜打洞寻宝的耗儿公，费公费大人么？"] = "ƣừ!ǦǥƶǦƸƛǃǦǉưởǃƼǦǁƐǦƶƾ,ǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǋịǦƣƑǄǦƩƽƾǦƸƇǃƼǦǈǊốǉǦǃƼƐǓǦƸƽạǓǦǇƇǃƼǦđƐǄǦǃƼƑƸƽǦǉƔǂǦƷảǄǦǋậǉ,ǦƫƽƓǦƸƇǃƼǦƫƽƓǦđạƾǦǃƽƁǃǦđƁǓǦǈƶǄ?",
    ["怎么，杜重威의 裤裆不好钻，想换尊佛脚上贡？"] = "ƮƶǄǦƽả,ǦƽƑǃƼǦƸủƶǦĐỗǦǥǇọǃƼǦǕǓǦǀƽƚǦƸƽǊƾǦǆǊƑ,ǦǃƙǃǦǂǊốǃǦđổƾǦǈƶǃƼǦƇǂǦƸƽƁǃǦƫƽậǉǦǀƽƑƸǦđểǦǤƁǃƼǦǁễǦǈƶǄ?",
    ["你、你休要恶语伤人！"] = "ƩƼươƾ,ǦǃƼươƾǦđừǃƼǦƸƚǦƷǊƇǃƼǦǁờƾǦƑƸǦđộƸǦǉƽươǃƼǦǃƼườƾ!",
    ["我今日舍命前来，忠肝义胆，日月可鉴！岂容小人——"] = "ǥƶǦƽƇǂǦǃƶǓǦǁƾềǊǦǂạǃƼǦǉớƾǦđƁǓ,ǦǉǇǊǃƼǦƸƶǃǦǃƼƽĩƶǦđảǂ,ǦǃƽậǉǦǃƼǊǓệǉǦƸƽứǃƼǦƼƾƑǂ!ǦƮƶǄǦƸƚǦǉƽểǦđểǦƽạǃƼǦǉƾểǊǦǃƽƁǃ——",
    ["当心！虏人来了。"] = "ƞẩǃǦǉƽậǃ!ǦƬǊƁǃǦƼƾặƸǦǉớƾǦǇồƾ.",
    ["有弓手埋伏！"] = "ƞƚǦƸǊǃƼǦǉƽủǦǂƶƾǦǅƽụƸ!",
    ["赵虎"] = "ǥǇƾệǊǦƣổ",
    ["勿要停留！往桥边冲！"] = "ĐừǃƼǦǤừǃƼǦǁạƾ!ǦƳƇǃƼǦǋềǦǅƽƓƶǦđầǊǦƸầǊ!",
    ["此间缠斗无益，我等且杀将出去！"] = "ǥǇƾềǃǦǂƾƙǃǦƸƽƾếǃǦđấǊǦởǦđƁǓǦǋƇǦƓƸƽ,ǦƸƽƕǃƼǦǉƶǦƽƃǓǦƼƾếǉǦǇƶǦǂộǉǦƸǄǃǦđườǃƼǦǂƑǊ!",
    ["我没事，我不怕虏人，我、我也能杀敌！"] = "ǥƶǦǀƽƇǃƼǦǈƶǄ,ǦǉƶǦǀƽƇǃƼǦǈợǦǆǊƁǃǦƼƾặƸ,Ǧǉƶ,ǦǉƶǦƸũǃƼǦƸƚǦǉƽểǦƼƾếǉǦđịƸƽ!",
    ["咱们往前走，我、我认识路。"] = "ƞƽƕǃƼǦǉƶǦǉƾếǃǦǋềǦǅƽƓƶǦǉǇướƸǦđƾ,Ǧǉƶ,ǦǉƶǦƷƾếǉǦđườǃƼ.",
    ["姑娘，别怕。"] = "ƞƇǦǃươǃƼ,ǦđừǃƼǦǈợ.",
    ["不，不是害怕……是高兴，爹爹的仇，我终于亲手报了！"] = "ƦƽƇǃƼ,ǦǀƽƇǃƼǦǅƽảƾǦǈợǦƽƃƾ……ǦǂƐǦǁƐǦǋǊƾǦǂừǃƼ,ǦǉƽƖǦƸủƶǦƸƽƶ,ǦƸǊốƾǦƸƖǃƼǦǉƶǦđƃǦđƓƸƽǦǉƽƁǃǦƷƑǄǦđượƸǦǇồƾ!",
    ["渡河要jin，你快护送墨门同袍过去，这里交给我！"] = "ƱượǉǦǈƇǃƼǦǁƐǦƽệǦǉǇọǃƼ,ǦǃƼươƾǦǂƶǊǦƽộǦǉốǃƼǦđồǃƼǦǂƇǃǦƨặƸǦƨƇǃǦǆǊƶǦđƚ,ǦởǦđƁǓǦƸứǦƼƾƶǄǦƸƽǄǦǉƶ!",
    ["直娘的，老子这回下的注太大了，莫不是要折在这儿？"] = "ƨẹǦǀƾếǅ,ǦǁƃǄǦǉửǦǁầǃǦǃƐǓǦđặǉǦƸượƸǦǁớǃǦǆǊƑ,ǦǀƽƇǃƼǦǁẽǦǁạƾǦƷỏǦǂạǃƼǦǉạƾǦđƁǓǦǈƶǄ?",
    ["走这边！我知道这里有条小路！"] = "ĐƾǦǁốƾǦǃƐǓ!ǦǥƶǦƷƾếǉǦởǦđƁǓǦƸƚǦǂộǉǦƸǄǃǦđườǃƼǦǃƽỏ!",
    ["来都来了，可不能半途而废、空手而归！"] = "ĐƃǦǉớƾǦǉƽƔǦǉớƾǦǁǊƇǃ,ǦǀƽƇǃƼǦǉƽểǦƷỏǦǤởǦƼƾữƶǦƸƽừǃƼ,ǦǉƶǓǦǀƽƇǃƼǦǂƐǦǋềǦđượƸ!",
    ["虏狗！你们也来欺我！"] = "ƧũǦƸƽƚǦƼƾặƸ!ǦƞƑƸǦǃƼươƾǦƸũǃƼǦǤƑǂǦǉớƾǦƷắǉǦǃạǉǦǉƶ!",
    ["恩人！恩人快来帮我！"] = "ƀǃǦǃƽƁǃ!ǦƀǃǦǃƽƁǃǦǂƶǊǦǉớƾǦƼƾƕǅǦǉƶ!",
    ["恩人好身手！不知恩人在何方高就？"] = "ƀǃǦǃƽƁǃǦƽảǄǦǉƽƁǃǦǉƽủ!ǦƦƽƇǃƼǦƷƾếǉǦƁǃǦǃƽƁǃǦƽƾệǃǦđƶǃƼǦởǦđƁǊǦƸƶǄǦǀƾếǃ?",
    ["江-小-将-军！等等我！"] = "ǥƾểǊ-ƢƾƶǃƼ-ǉướǃƼ-ǆǊƁǃ!ǦĐợƾǦǉƶǦǋớƾ!",
    ["哈哈哈，打了这么多仗，还是今天最痛快！"] = "ƣƶǦƽƶǦƽƶ,ǦđƑǃƽǦƷƶǄǦǃƽƾƙǊǦǉǇậǃǦǇồƾ,ǦǋẫǃǦǁƐǦƽƇǂǦǃƶǓǦǉƽốǃƼǦǀƽǄƑƾǦǃƽấǉ!",
    ["来啊，再来多一些！"] = "ǥớƾǦđƁǓ,ǦǉớƾǦǉƽƙǂǦǃƽƾềǊǦƸƽƕǉǦǃữƶǦđƾ!",
    ["中渡桥……"] = "ǥǇǊǃƼǦĐộǦƦƾềǊ……",
    ["别发呆。跟上。"] = "ĐừǃƼǦǃƼẩǃǦǃƼườƾ.ǦǥƽƺǄǦǈƑǉǦǋƐǄ.",
    ["老伙计，跟了我几十年，这虏人血，今天叫你喝个饱！"] = "ƧƃǄǦđốƾǦǉƑƸ,ǦǉƽƺǄǦǉƶǦǂấǓǦƸƽụƸǦǃăǂǦǃƶǓ,ǦǂƑǊǦǆǊƁǃǦƼƾặƸǦƽƇǂǦǃƶǓǦƸƽǄǦǃƼươƾǦǊốǃƼǦƸƑƾǦǃǄǦǃƙ!",
    ["鸿飞刀"] = "ƣồǃƼǦƫƽƾǦĐƶǄ",
    ["哈哈哈，又来了几位豪杰。"] = "ƣƶǦƽƶǦƽƶ,ǦǁạƾǦƸƚǦǉƽƙǂǦǂấǓǦǋịǦƽƐǄǦǀƾệǉǦǉớƾǦǇồƾ.",
    ["方教头！桥基换我来守，您且歇一会儿！"] = "ƫƽươǃƼǦƼƾƑǄǦđầǊ!ǦĐểǦƸǄǃǦǉƽủǦƸƽƁǃǦƸầǊǦƸƽǄ,ǦǃƼườƾǦƽƃǓǦǃƼƽỉǦǃƼơƾǦǂộǉǦƸƽƕǉ!",
    ["虏狗！这一剑是峰儿的，这一剑是桃儿的——"] = "ƧũǦƸƽƚǦƼƾặƸ!ǦƩƽƑǉǦǀƾếǂǦǃƐǓǦǁƐǦƸủƶǦƫƽǄǃƼǦƩƽƾ,ǦǃƽƑǉǦǀƾếǂǦǃƐǓǦǁƐǦƸủƶǦĐƐǄǦƩƽƾ——",
    ["只恨我的剑，还不够快！"] = "ƞƽỉǦƽậǃǦǀƾếǂǦƸủƶǦǉƶǦƸƛǃǦƸƽưƶǦđủǦǃƽƶǃƽ!",
    ["肖兄！是战场杀敌痛快，还是做官儿痛快？"] = "ǥƾƙǊǦƽǊǓǃƽ!ǦƧƐǦƸƽƾếǃǦǉǇườǃƼǦǈƑǉǦđịƸƽǦǉƽốǃƼǦǀƽǄƑƾ,ǦƽƶǓǦǁƐǦǁƐǂǦǆǊƶǃǦǉƽốǃƼǦǀƽǄƑƾ?",
    ["和李兄一起杀敌，最痛快！"] = "ƞƖǃƼǦƧƈǦƽǊǓǃƽǦǈƑǉǦđịƸƽǦǁƐǦǉƽốǃƼǦǀƽǄƑƾǦǃƽấǉ!",
    ["我们来时，桥已损毁，只能勉力护住桥基。你们快看看，怎么修？"] = "ƧƕƸǦƸƽƕǃƼǦǉƶǦǉớƾ,ǦƸầǊǦđƃǦƷịǦƽủǓǦƽǄạƾ,ǦƸƽỉǦƸƚǦǉƽểǦƼắǃƼǦƼượǃƼǦƼƾữǦǁấǓǦƸƽƁǃǦƸầǊ.ǦƞƑƸǦǃƼươƾǦǂƶǊǦǍƺǂǦǍƺǂǦǅƽảƾǦǉǊǦƷổǦǉƽếǦǃƐǄ?",
    ["南岸桥基余五座，中段、北段已焚毁，旧料朽坏，修缮需辅以石料。"] = "ƨƚǃƼǦƸầǊǦƷờǦƩƶǂǦƸƛǃǦǤưǦǃăǂǦǉƛƶ,ǦđǄạǃǦƼƾữƶǦǋƐǦđǄạǃǦƝắƸǦđƃǦƷịǦǉƽƾƙǊǦǇụƾ,ǦǋậǉǦǁƾệǊǦƸũǦđƃǦǂụƸǦǃƑǉ,ǦǉǊǦǈửƶǦƸầǃǦƷổǦǈǊǃƼǦǉƽƙǂǦđƑǦǁƾệǊ.",
    ["桥身尽失，缺五十余丈。比预想的……更糟糕……"] = "ǥƽƁǃǦƸầǊǦǂấǉǦǈạƸƽ,ǦǉƽƾếǊǦƽơǃǦǃăǂǦǂươƾǦǉǇượǃƼ.ǦƮǄǦǋớƾǦǤựǦǉƓǃƽ……ǦƸƛǃǦǉồƾǦǉệǦƽơǃ……",
    ["师兄。"] = "ƮưǦƽǊǓǃƽ.",
    ["嗯。墨门弟子，修桥！"] = "Ừǂ.ǦĐệǦǉửǦƨặƸǦƨƇǃ,ǦǉǊǦƸầǊ!",
    ["孟大侠，我们随身携带的物资不够，只能先从附近搜罗用料。"] = "ƨạǃƽǦđạƾǦƽƾệǅ,ǦǋậǉǦǉưǦƸƽƕǃƼǦǉƶǦǂƶǃƼǦǉƽƺǄǦǀƽƇǃƼǦđủ,ǦƸƽỉǦƸƚǦǉƽểǦǉƔǂǦǀƾếǂǦǃƼǊǓƙǃǦǁƾệǊǦǆǊƶǃƽǦđƁǓǦǉǇướƸ.",
    ["只是不知，军资何时能到？"] = "ƞƽỉǦǁƐǦǀƽƇǃƼǦƷƾếǉ,ǦǆǊƁǃǦǃƽǊǦǀƽƾǦǃƐǄǦǂớƾǦǉớƾ?",
    ["军营那边……还没消息。若卯时五刻仍未到——"] = "ƫƽƓƶǦǆǊƁǃǦǤǄƶǃƽ……ǦǋẫǃǦƸƽưƶǦƸƚǦǉƾǃǦǉứƸ.ǦƩếǊǦđếǃǦƼƾờǦƨƃǄǦǀƽắƸǦǃăǂǦǋẫǃǦƸƽưƶǦǉớƾ——",
    ["咱们便只能靠自己，抢渡滹沱。"] = "ƞƽƕǃƼǦǉƶǦƸƽỉǦƸƛǃǦƸƑƸƽǦǤựƶǦǋƐǄǦƸƽƓǃƽǦǂƔǃƽ,ǦƸưỡǃƼǦđộǦǈƇǃƼǦƣƇǦĐƐ.",
    ["杜帅既已谋定，晚生仅余一言——"] = "ĐỗǦǈǄƑƾǦđƃǦǂưǊǦđịǃƽǦǍǄǃƼǦǍǊƇƾ,ǦǋƃǃǦǈƾǃƽǦƸƽỉǦƸƛǃǦǂộǉǦǁờƾǦƸǊốƾ——",
    ["大帅——"] = "ĐạƾǦǈǄƑƾ——",
    ["传信兵"] = "ǥǇǊǓềǃǦǉƾǃǦƷƾǃƽ",
    ["那边的回信。"] = "ǥƽưǦƽồƾǦƁǂǦƷƙǃǦǀƾƶ.",
    ["拿来。"] = "ĐưƶǦđƁǓ.",
    ["杜重威"] = "ĐỗǦǥǇọǃƼǦǕǓ",
    ["人生倥偬，如白驹过隙。少年勇，中年谋，晚年守。最煎熬者莫若晚景，便似行至深冬——天地萧索，万物一空。"] = "ƩƽƁǃǦǈƾǃƽǦǀƽƇǃƼǦǉƛǃƼ,ǦǃƽưǦƷạƸƽǦƸƁǊǦǆǊƑǦǀƽƓƸƽ.ǦǥƽƾếǊǦǃƾƙǃǦǤũǃƼ,ǦǉǇǊǃƼǦǃƾƙǃǦǂưǊ,ǦǋƃǃǦǃƾƙǃǦǉƽủ.ǦƦẻǦƼƾƶǃǦǉǇǊƁǃǦǃƽấǉǦǀƽƇǃƼǦƼƔǦƷằǃƼǦƸảǃƽǦǋềǦƼƾƐ,ǦǉựƶǦǃƽưǦđƾǦǉớƾǦƼƾữƶǦǂƖƶǦđƇǃƼǦǀƽắƸǦǃƼƽƾệǉ——ǦǉƽƾƙǃǦđịƶǦǉƾƙǊǦǉƶǄ,ǦǋạǃǦǋậǉǦǉǇốǃƼǦǇỗǃƼ.",
    ["晚生幼年伴祖父随军出行，于大雪见红梅. 祖父有言，霜寒彻骨之日，亦是天地春来之时。"] = "ƱƃǃǦǈƾǃƽǦǉƽǊởǦǃƽỏǦǉƽƺǄǦǉổǦǅƽụǦǉƛǃƼǦǆǊƁǃ,ǦƼƾữƶǦǉǇờƾǦǉǊǓếǉǦǁớǃǦǉƽấǓǦǃƽƐǃƽǦƽồǃƼǦǂƶƾ.ǦǥổǦǅƽụǦƸƚǦǁờƾǦǇằǃƼ,ǦǃƼƐǓǦǈươǃƼǦǁạǃƽǦǉƽấǊǦǍươǃƼ,ǦƸũǃƼǦƸƽƓǃƽǦǁƐǦǁƕƸǦǉƽƾƙǃǦđịƶǦǍǊƁǃǦǈƶǃƼ.",
    ["如今雪冻三尺，杜帅可听见，冰层下的春水将涌之声？"] = "ƩƶǓǦǉǊǓếǉǦđƚǃƼǦƷăǃƼǦƷƶǦǉƽướƸ,ǦĐỗǦǈǄƑƾǦƸƚǦǃƼƽƺǦǉƽấǓǦǉƾếǃƼǦǍǊƁǃǦǉƽủǓǦđƶǃƼǦǉǇƐǄǦǤƁǃƼǦǤướƾǦǁớǅǦƷăǃƼǦǤƐǓ?",
    ["世间有瑕，何物去之……"] = "ǥƽếǦƼƾƶǃǦƽữǊǦƽƐ,ǦƽƐǦǋậǉǦǀƽứǦƸƽƾ……",
    ["白雪覆野，终有尽时！如若不能，请杜帅取尽林某心头热血，助君沃雪融春！"] = "ǥǊǓếǉǦǉǇắǃƼǦǅƽủǦđồǃƼ,ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦƸƚǦǁƕƸǦǉƶǃ!ǦƩếǊǦǃƽưǦǀƽƇǃƼǦǉƽể,ǦǍƾǃǦĐỗǦǈǄƑƾǦƽƃǓǦǁấǓǦƸạǃǦƷầǊǦǃƽƾệǉǦƽǊǓếǉǦǉǇǄǃƼǦǉƾǂǦƧƁǂǦǂỗǦǃƐǓ,ǦƼƾƕǅǦǃƼườƾǦǃƽǊộǂǦđỏǦǉǊǓếǉǦǁạǃƽǦđƚǃǦǍǊƁǃǦǋề!",
    ["木料还有多少？"] = "ƢỗǦƸƛǃǦǁạƾǦƷƶǄǦǃƽƾƙǊ?",
    ["拼拼凑凑，还能有二十丈。"] = "ƢƚǅǦǃƽặǉǦǁạƾǦǉƽƔǦƸũǃƼǦƸƛǃǦđượƸǦǀƽǄảǃƼǦƽƶƾǦǂươƾǦǉǇượǃƼ.",
    ["不够。得再找，往两侧更远处搜寻。"] = "ƦƽƇǃƼǦđủ.ǦƫƽảƾǦǉƔǂǦǉƽƙǂ,ǦǉƔǂǦǇƶǦǍƶǦƽơǃǦǋềǦƽƶƾǦǅƽƓƶ.",
    ["我知道哪儿有，跟我来！"] = "ǥƶǦƷƾếǉǦởǦđƁǊǦƸƚ,ǦđƾǦǉƽƺǄǦǉƶ!",
    ["秀姑娘，你对这附近很熟悉？"] = "ǥƕǦƸƇǦǃươǃƼ,ǦƸƇǦǇấǉǦǉƽƇǃƼǦǉƽǊộƸǦǋƖǃƼǦǃƐǓǦǈƶǄ?",
    ["嗯。过了河，北岸第一个村子，就是我家。"] = "ƱƁǃƼ.ǦƬǊƶǦǈƇǃƼǦǇồƾ,ǦǃƼƇƾǦǁƐǃƼǦđầǊǦǉƾƙǃǦởǦƷờǦƝắƸǦƸƽƓǃƽǦǁƐǦǃƽƐǦǉƶ.",
    ["一会儿，我就能回家了。"] = "ƨộǉǦǁƑǉǦǃữƶǦǉƽƇƾ,ǦǉƶǦǈẽǦđượƸǦǋềǦǃƽƐǦǇồƾ.",
    ["北岸，会比这里更危险。"] = "ƝờǦƝắƸǦǈẽǦǃƼǊǓǦƽƾểǂǦƽơǃǦởǦđƁǓǦǃƽƾềǊ.",
    ["我不怕。你们都不怕……我也要保护我自己的家。"] = "ǥƶǦǀƽƇǃƼǦǈợ.ǦƨọƾǦǃƼườƾǦđềǊǦǀƽƇǃƼǦǈợ...ǦǥƶǦƸũǃƼǦǅƽảƾǦƷảǄǦǋệǦǃƽƐǦƸủƶǦƸƽƓǃƽǦǂƔǃƽ.",
    ["驾！师姐！傅师姐！"] = "ƢƾƑ!ǦƮưǦǉỷ!ǦƫƽƚǦǈưǦǉỷ!",
    ["高大花"] = "ƞƶǄǦĐạƾǦƣǄƶ",
    ["贼杀才！有胆放了爷爷，待爷爷告到杜帅面前，把你们一个个砍了祭旗！"] = "ǥặƸǦǈƑǉǦǉƐƾ!ǦƞƚǦƼƾỏƾǦǉƽƔǦǉƽảǦƇǃƼǦđƁǓǦǇƶ,ǦđợƾǦƇǃƼǦǉớƾǦǉǇướƸǦǂặǉǦĐỗǦǈǄƑƾǦƸƑǄǦǉǇạǃƼ,ǦǈẽǦƸƽƗǂǦǉừǃƼǦđứƶǦƸƑƸǦǃƼươƾǦđểǦǉếǦƸờ!",
    ["朝九"] = "ǥǇƾềǊǦƞửǊ",
    ["又有人来了。"] = "ƧạƾǦƸƚǦǃƼườƾǦǉớƾ.",
    ["背槽抛粪的畜牲们，再不给爷爷松开，就让你们尝尝我的暴雨流霰针！"] = "ƧũǦǈƕƸǦǈƾǃƽǦƷộƾǦǉƐǄǦǅƽƶǄǦǅƽấǃ,ǦƸƛǃǦǀƽƇǃƼǦǂƶǊǦƸởƾǦǉǇƚƾǦƸƽǄǦƇǃƼ,ǦǁƾềǃǦđểǦƸƑƸǦǃƼươƾǦǃếǂǦǉƽửǦƝạǄǦƱũǦƧưǊǦǥảǃǦƞƽƁǂǦƸủƶǦǉƶ!",
    ["你们平日里就糟践爷爷，今日又忌恨我得杜帅赏识，爷爷杀了你们！"] = "ƞƑƸǦǃƼươƾǦǃƼƐǓǦǉƽườǃƼǦƼƾƐǓǦǋƛǦƇǃƼ,ǦǃƶǓǦǁạƾǦđốǦǀỵǦƇǃƼǦđượƸǦĐỗǦǈǄƑƾǦǉƽưởǃƼǦǉƽứƸ,ǦƇǃƼǦǅƽảƾǦƼƾếǉǦǈạƸƽǦƸƑƸǦǃƼươƾ!",
    ["老实点儿！"] = "ǥƽƐǃƽǦǉƽậǉǦƸƽƕǉǦƸǄƾ!",
    ["王丘"] = "ƱươǃƼǦƦƽƁǊ",
    ["大花，你怎么来了？不是说了让你——"] = "ĐạƾǦƣǄƶ,ǦǈƶǄǦǂǊộƾǦǁạƾǦǉớƾǦđƁǓ?ǦƞƽẳǃƼǦǅƽảƾǦđƃǦƷảǄǦǂǊộƾ——",
    ["师姐！我们也是天泉弟子，救师兄怎能没我们的份！"] = "ƮưǦǉỷ!ǦƞƽƕǃƼǦđệǦƸũǃƼǦǁƐǦđệǦǉửǦǥƽƾƙǃǦǥǊǓềǃ,ǦƸứǊǦǈưǦƽǊǓǃƽǦǈƶǄǦƸƚǦǉƽểǦǉƽƾếǊǦǅƽầǃǦƸƽƕǃƼǦđệǦđượƸ!",
    ["是啊师姐，怎么只许你来，不许我们帮忙？"] = "ƫƽảƾǦđƚǦǈưǦǉỷ,ǦǈƶǄǦƸƽỉǦƸƽǄǦǅƽƗǅǦǉỷǦǉớƾǦǂƐǦǀƽƇǃƼǦƸƽǄǦƷọǃǦđệǦƼƾƕǅǦǈứƸ?",
    ["直娘的杀贼！尔等盗军资，扰军心，看杜帅不剥了你们的皮做鼓！"] = "ƧũǦǈƑǉǦǉặƸǦǉǇựƸǦǃươǃƼǦǀƾƶ!ǦƞƑƸǦǃƼươƾǦǉǇộǂǦǆǊƁǃǦǃƽǊ,ǦǃƽƾễǊǦǆǊƁǃǦǉƁǂ,ǦǍƺǂǦĐỗǦǈǄƑƾǦƸƚǦǁộǉǦǤƶǦƸƑƸǦǃƼươƾǦǁƐǂǦǉǇốǃƼǦǀƽƇǃƼ!",
    ["这满嘴放屁的家伙是谁？"] = "ƞƑƾǦǉƙǃǦǂởǦǂƾệǃƼǦǇƶǦǁƐǦǅƽǊǃǦǅƽƁǃǦǃƐǓǦǁƐǦƶƾǦǉƽế?",
    ["在军营外逮到的，不知从何处偷听到了丁兄弟的计划，嚷嚷着要告密。我们怕他坏事，便一道儿绑了来。"] = "ƝắǉǦđượƸǦởǦǃƼǄƐƾǦǆǊƁǃǦǤǄƶǃƽ,ǦǀƽƇǃƼǦƷƾếǉǦǃƼƽƺǦǁƗǃǦđượƸǦǀếǦƽǄạƸƽǦƸủƶǦĐƾǃƽǦƽǊǓǃƽǦđệǦǉừǦđƁǊ,ǦƸứǦƼƐǄǦǁƙǃǦđƛƾǦđƾǦƸƑǄǦǂậǉ.ǦƞƽƕǃƼǦǉƶǦǈợǦƽắǃǦƽỏǃƼǦǋƾệƸǦǃƙǃǦǉǇƚƾǦǁǊƇǃǦǂƶǃƼǦǉớƾǦđƁǓ.",
    ["来时我见着远处有虏人斥候，再作耽搁，恐怕事有不妙——"] = "ƧƕƸǦǉớƾǦǉƶǦǉƽấǓǦǅƽƓƶǦǍƶǦƸƚǦǉƽƑǂǦƷƑǄǦƸủƶǦǆǊƁǃǦƼƾặƸ,ǦƸƛǃǦǉǇƔǦƽǄƃǃǦǃữƶǦƺǦǁƐǦǈựǦǉƔǃƽǦƸƽẳǃƼǦǁƐǃƽ——",
    ["有马蹄声，是虏人的北马！"] = "ƞƚǦǉƾếǃƼǦǋƚǦǃƼựƶ,ǦǁƐǦƝắƸǦǂƃǦƸủƶǦǆǊƁǃǦƼƾặƸ!",
    ["准备御敌！"] = "ƞƽǊẩǃǦƷịǦǃƼựǦđịƸƽ!",
    ["黑心短命的狗东西们，敢绑着爷爷当靶子！有胆杀了爷爷，爷爷见了阎王也要回来索命——"] = "ƧũǦƸƽƚǦǂƑǦđƺǃǦǉƁǂǦđǄảǃǦǂệǃƽ,ǦǤƑǂǦǉǇƚƾǦƇǃƼǦđƁǓǦǁƐǂǦƷƾƶǦđỡǦđạǃ!ǦƞƚǦƼƾỏƾǦǉƽƔǦƼƾếǉǦƇǃƼǦđƾ,ǦƇǃƼǦǉƽấǓǦǝƾƙǂǦƱươǃƼǦƸũǃƼǦǈẽǦƽƾệǃǦƽồǃǦǋềǦđƛƾǦǂạǃƼ——",
    ["拿着刀！前面就是虏人，去投杜重威也好，去见阎王也好，都要你自己杀出条道来！"] = "ƞầǂǦǁấǓǦđƶǄ!ǦƫƽƓƶǦǉǇướƸǦƸƽƓǃƽǦǁƐǦǆǊƁǃǦƼƾặƸ,ǦđƾǦđầǊǦǆǊƁǃǦƸƽǄǦĐỗǦǥǇọǃƼǦǕǓǦƸũǃƼǦđượƸ,ǦđƾǦƼặǅǦǝƾƙǂǦƱươǃƼǦƸũǃƼǦǉƽế,ǦđềǊǦǅƽảƾǦǉựǦǂƔǃƽǦƼƾếǉǦǇƶǦǂộǉǦƸǄǃǦđườǃƼ!",
    ["小将军，听我一席话，如今局势危如累卵，北岸是决计去不得了！"] = "ǥƾểǊǦǉướǃƼǦǆǊƁǃ,ǦǃƼƽƺǦǉƶǦǂộǉǦǁờƾ,ǦǃƶǓǦƸụƸǦǤƾệǃǦǃƼǊǓǦǃƽưǦǉǇứǃƼǦƸƽồǃƼ,ǦƷờǦƝắƸǦǆǊǓếǉǦǀếǦǀƽƇǃƼǦǉƽểǦđƾǦđượƸǦǃữƶ!",
    ["不如咱们速速南下，另起炉灶！"] = "ƞƽƾǦƷằǃƼǦƸƽƕǃƼǦǉƶǦǂƶǊǦƸƽƚǃƼǦǃƶǂǦƽạ,ǦǁậǅǦǃƙǃǦǃƼƽƾệǅǦǁớǃǦǀƽƑƸ!",
    ["将军慷慨就义，正是成就了您父子二人的威名！"] = "ǥướǃƼǦǆǊƁǃǦǀƽảǃƼǦǀƽƑƾǦǉựǊǦǃƼƽĩƶ,ǦƸƽƓǃƽǦǁƐǦǉƽƐǃƽǦǉǄƐǃǦƸƽǄǦǊǓǦǤƶǃƽǦƸủƶǦƽƶƾǦƸƽƶǦƸǄǃǦǃƼƐƾ!",
    ["咱们以将军部众之名登高一呼，何愁不能东山再起！"] = "ƞƽƕǃƼǦǉƶǦǁấǓǦǤƶǃƽǦǃƼƽĩƶǦƷộǦƽạǦƸủƶǦǉướǃƼǦǆǊƁǃǦƽƇǦƽƐǄǦǂộǉǦǉƾếǃƼ,ǦǁǄǦƼƔǦǀƽƇǃƼǦǉƽểǦđƇǃƼǦǈơǃǦǉƑƾǦǀƽởƾ!",
    ["到时莫说这血海深仇，就算王图霸业也——"] = "ĐếǃǦǁƕƸǦđƚǦđừǃƼǦǃƚƾǦǁƐǦƽǊǓếǉǦƽảƾǦǉƽƁǂǦǉƽƖǦǃƐǓ,ǦǃƼƶǓǦƸảǦǋươǃƼǦđồǦƷƑǦǃƼƽƾệǅǦƸũǃƼ——",
    ["闭嘴，再说杀了你。"] = "ƞƁǂǦǂƾệǃƼ,ǦǃƚƾǦƸƁǊǦǃữƶǦǉƶǦƼƾếǉǦǃƼươƾ.",
    ["小子，你有巧劲，可惜力道欠点。瞧好了，刀把入掌心，虎口近刀盘。"] = "ǥƾểǊǦǉử,ǦǃƼươƾǦƸƚǦǍảǄǦǀƔǃƽ,ǦǉƾếƸǦǁƐǦǁựƸǦđạǄǦƽơƾǦǀƗǂ.ǦƩƽƔǃǦƸƽǄǦǀỹǦđƁǓ,ǦƸƽǊƇƾǦđƶǄǦđặǉǦǋƐǄǦǁƛǃƼǦƷƐǃǦǉƶǓ,ǦƽổǦǀƽẩǊǦǈƑǉǦƽộǦǉƽủ.",
    ["松活以利便——当心左边！"] = "ǥƽảǦǁỏǃƼǦđểǦǁƾǃƽǦƽǄạǉ——ǦƸẩǃǦǉƽậǃǦƷƙǃǦǉǇƑƾ!",
    ["要你管！"] = "ƞầǃǦƇǃƼǦǆǊảǃǦƸƽắƸ!",
    ["若我旭儿悟性能如你一般，倒也无憾了！"] = "ƩếǊǦƣƕƸǦǃƽƾǦǃƽƐǦǉƶǦǃƼộǦǉƓǃƽǦđượƸǦǃƽưǦǃƼươƾ,ǦǉƽƔǦƸũǃƼǦǀƽƇǃƼǦƸƛǃǦƼƔǦƽốƾǦǉƾếƸ!",
    ["老东西的崽子不争气，休要占我便宜！"] = "ĐồǦƸủƶǦǁƃǄǦƼƾƐǦǃƽƐǦƇǃƼǦǂớƾǦǀƽƇǃƼǦǇƶǦƼƔ,ǦđừǃƼǦƸƚǦǂƐǦƸƽƾếǂǦǉƾệǃǦǃƼƽƾǦƸủƶǦǉƶ!",
    ["哈哈哈，我那老来子昨日刚满周岁，不如你，倒也算不得不争气。"] = "ƣƶǦƽƶǦƽƶ,ǦđứƶǦƸǄǃǦƸầǊǦǉựǦƸủƶǦǉƶǦƽƇǂǦǆǊƶǦǋừƶǦǉǇƛǃǦǉƽƇƾǦǃƇƾ,ǦǤƖǦǀƽƇǃƼǦƷằǃƼǦǃƼươƾǦǃƽưǃƼǦƸũǃƼǦǀƽƇǃƼǦđếǃǦǃỗƾǦƼọƾǦǁƐǦǀƽƇǃƼǦǇƶǦƼƔ.",
    ["虏人越聚越多，不能再等了！！"] = "ƬǊƁǃǦƼƾặƸǦǉụǦǉậǅǦǃƼƐǓǦƸƐǃƼǦđƇǃƼ,ǦǀƽƇǃƼǦǉƽểǦđợƾǦǉƽƙǂǦđượƸǦǃữƶ!!",
    ["老子去拆了那狗日的弩箭！"] = "ƧƃǄǦǉửǦđƾǦǤỡǦƸƑƾǦǃỏǦǉƾễǃǦƸƽƚǦƸƽếǉǦǀƾƶ!",
    ["右边归我。"] = "ƝƙǃǦǅƽảƾǦǉƽǊộƸǦǋềǦǉƶ.",
    ["刚是杜帅信使来过了？那援军要到了吗！"] = "ƱừƶǦǇồƾǦǁƐǦǉƓǃǦǈứǦƸủƶǦĐỗǦǈǄƑƾǦǉớƾǦǈƶǄ?ǦƱƾệǃǦǆǊƁǃǦǈắǅǦđếǃǦǇồƾǦǅƽảƾǦǀƽƇǃƼ!",
    ["亲卫甲"] = "ǥƽƁǃǦǋệǦƢƾƑǅ",
    ["怪着呢。"] = "ƬǊƑƾǦǁạǦǉƽậǉ.",
    ["亲卫乙"] = "ǥƽƁǃǦǋệǦẤǉ",
    ["“大军已至，去瑕尽可取用。用之、不竭。”"] = "\"ĐạƾǦǆǊƁǃǦǤĩǦƸƽƓ,ǦǀƽứǦƽƐǦǉậǃǦǀƽảǦǉƽủǦǤụǃƼ.ǦǝụǃƼǦƸƽƾ,ǦƷấǉǦǀƾệǉ.\"",
    ["大军？哪来的大军？"] = "ĐạƾǦǆǊƁǃ?ǦĐạƾǦǆǊƁǃǦởǦđƁǊǦǇƶ?",
    ["全牧"] = "ǥǄƐǃǦƨụƸ",
    ["四周都是虏人，并无我军身影啊！"] = "ƝốǃǦǅƽƓƶǦđềǊǦǁƐǦǆǊƁǃǦƼƾặƸ,ǦƸƽẳǃƼǦǉƽấǓǦƷƚǃƼǦǤƑǃƼǦǆǊƁǃǦǉƶǦđƁǊǦƸả!",
    ["邵仁"] = "ǥƽƾệǊǦƩƽƁǃ",
    ["敌军又攻，两翼失守啦！"] = "ĐịƸƽǦǆǊƁǃǦǁạƾǦƸƇǃƼǦǉớƾ,ǦƽƶƾǦƸƑǃƽǦǉƽấǉǦǉƽủǦǇồƾ!",
    ["前线兵"] = "ǥƾềǃǦǉǊǓếǃǦƷƾǃƽ",
    ["如何是好！"] = "ƝƾếǉǦǁƐǂǦǈƶǄǦđƁǓ!",
    ["请示下！"] = "ƳƾǃǦƸƽỉǦǉƽị!",
    ["小将军！万万不可再往前了！再往前，就真回不去了！"] = "ǥƾểǊǦǉướǃƼǦǆǊƁǃ!ǦƱạǃǦǋạǃǦǁầǃǦǀƽƇǃƼǦđượƸǦǉƾếǃǦǁƙǃǦǃữƶ!ǦǥƾếǃǦǉƽƙǂǦǃữƶǦǁƐǦǉƽựƸǦǈựǦǀƽƇǃƼǦǋềǦđượƸǦđƁǊ!",
    ["我、我实话说了吧，那杜狗早打定了主意，连一应军资都卖光了！"] = "ǥƶ,ǦǉƶǦǃƚƾǦǉƽậǉǦǃƽƗ,ǦǉƙǃǦƸƽƚǦƽọǦĐỗǦđƚǦđƃǦǈớǂǦƽạǦǆǊǓếǉǦǉƁǂǦǇồƾ,ǦǃƼƶǓǦƸảǦǆǊƁǃǦǃƽǊǦƸũǃƼǦƷƑǃǦǈạƸƽǦǈƐǃƽǦǈƶǃƽǦǇồƾ!",
    ["往后，可东山再起，往前，只死路一条！"] = "ƧƖƾǦǁạƾ,ǦƸƚǦǉƽểǦđƇǃƼǦǈơǃǦǉƑƾǦǀƽởƾ,ǦǉƾếǃǦǁƙǃ,ǦƸƽỉǦƸƚǦƸǄǃǦđườǃƼǦƸƽếǉ!",
    ["是，我费亦可是追名逐利的小人， but 只要将军看得起我，我一定尽心辅佐小将军，肝脑涂地也要成就一番伟业！"] = "ƫƽảƾ,ǦƫƽƓǦǝƾệƸǦƦƽảǦǉƶǦǁƐǦǀẻǦǉƾểǊǦǃƽƁǃǦǉǇǊǓǦǤƶǃƽǦǉǇụƸǦǁợƾ,ǦǃƽưǃƼǦƸƽỉǦƸầǃǦǉướǃƼǦǆǊƁǃǦƸǄƾǦǉǇọǃƼǦǉƶ,ǦǉƶǦǃƽấǉǦđịǃƽǦǉậǃǦǉƁǂǦǅƽƛǦǉƑǦǉƾểǊǦǉướǃƼǦǆǊƁǃ,ǦƼƶǃǦƚƸǦđấǉǦƷƖǃǦƸũǃƼǦǅƽảƾǦǉƽƐǃƽǦǉựǊǦǂộǉǦǅƽƺǃǦǋĩǦǃƼƽƾệǅ!",
    ["费亦可！"] = "ƫƽƓǦǝƾệƸǦƦƽả!",
    ["亲卫营令牌！——给你了！"] = "ƧệǃƽǦƷƐƾǦǥƽƁǃǦǋệǦǤǄƶǃƽ!Ǧ——ǦƞƽǄǦǃƼươƾǦđƚ!",
    ["这……给我了？"] = "ƞƑƾǦǃƐǓ……ǦƸƽǄǦǉƶǦǈƶǄ?",
    ["【契丹语]中原人！来啊！"] = "[ǥƾếǃƼǦƦƽƾếǉǦĐƶǃ]ǦƩƼườƾǦǥǇǊǃƼǦƩƼǊǓƙǃ!ǦǥớƾǦđƁǓ!",
    ["霞末"] = "ƣƐǦƨạǉ",
    ["这里交给我，你快去找将军！"] = "ỞǦđƁǓǦƼƾƶǄǦƸƽǄǦǉƶ,ǦǃƼươƾǦǂƶǊǦđƾǦǉƔǂǦǉướǃƼǦǆǊƁǃ!",
    ["到头了……这场仗已经打到头了！走啊！"] = "ƦếǉǦǉƽƕƸǦǇồƾ……ǦǉǇậǃǦƸƽƾếǃǦǃƐǓǦđƃǦđếǃǦƽồƾǦǀếǉǦǇồƾ!ǦĐƾǦǂƶǊ!",
    ["天泉弟子——"] = "ĐệǦǉửǦǥƽƾƙǃǦǥǊǓềǃ——",
    ["吾乃汉敬侯费祎费文伟公之后——"] = "ǥƶǦǁƐǦƽậǊǦǤǊệǦƸủƶǦƣƑǃǦƦƓǃƽǦƽầǊǦƫƽƓǦƴǦƫƽƓǦƱăǃǦƱĩǦƸƇǃƼ——",
    ["在此!"] = "ỞǦđƁǓ!",
    ["走啊！一个个贱骨头，还在这里干什么！都回去！回去！"] = "ĐƾǦǂƶǊ!ǦƧũǦǉƾệǃǦƸốǉǦƸƑƸǦǃƼươƾǦƸƛǃǦởǦđƁǓǦǁƐǂǦƼƔ!ǦĐềǊǦǆǊƶǓǦǋềǦđƾ!ǦƬǊƶǓǦǋềǦđƾ!",
    ["江小将军臂膀，王清将军亲卫营亲卫！费公费亦可是也！"] = "ƞƑǃƽǦǉƶǓǦđắƸǦǁựƸǦƸủƶǦƢƾƶǃƼǦǉƾểǊǦǉướǃƼǦǆǊƁǃ,ǦǉƽƁǃǦǋệǦƸủƶǦǥƽƁǃǦǋệǦǤǄƶǃƽǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃ!ǦƫƽƓǦƸƇǃƼǦƫƽƓǦǝƾệƸǦƦƽảǦƸƽƓǃƽǦǁƐǦǉƶ!",
    ["你们以为剑能砍光敌人吗？你们的功夫能救人的命吗？放屁！你们懂个屁的打仗！"] = "ƞƑƸǦǃƼươƾǦǉưởǃƼǦǀƾếǂǦƸƚǦǉƽểǦƸƽƗǂǦƽếǉǦǀẻǦǉƽƖǦǈƶǄ?ǦƞƇǃƼǦǅƽǊǦƸủƶǦƸƑƸǦǃƼươƾǦƸƚǦǉƽểǦƸứǊǦǂạǃƼǦǃƼườƾǦǈƶǄ?ǦƫƽǊǃǦǅƽƁǃ!ǦƞƑƸǦǃƼươƾǦƽƾểǊǦƸƑƾǦǆǊƑƾǦƼƔǦǋềǦđƑǃƽǦƼƾặƸ!",
    ["打仗就是死！一群群地死！输了的全都得死！"] = "ĐƑǃƽǦƼƾặƸǦƸƽƓǃƽǦǁƐǦƸƽếǉ!ǦƞƽếǉǦǉừǃƼǦƷầǓǦǉừǃƼǦǁũ!ǦƦẻǦǉƽǊƶǦƸǊộƸǦǉấǉǦǉƽảǓǦđềǊǦǅƽảƾǦƸƽếǉ!",
    ["老子打了十五年！看他们死在洛阳，死在邺城，死在鸟名都没有的地方！"] = "ƧƃǄǦǉửǦđƑǃƽǦƼƾặƸǦǂườƾǦǁăǂǦǃăǂǦǇồƾ!ǦƩƽƔǃǦƷọǃǦƽọǦƸƽếǉǦởǦƧạƸǦǝươǃƼ,ǦƸƽếǉǦởǦƩƼƽƾệǅǦǥƽƐǃƽ,ǦƸƽếǉǦởǦǃƽữǃƼǦǃơƾǦđếǃǦƸƑƾǦǉƙǃǦƸƽƾǂǦƸƽƚƸǦƸũǃƼǦǀƽƇǃƼǦƸƚ!",
    ["就他妈剩老子！就剩老子活着！就剩老子……老子就是要死在中渡桥！"] = "ƞƽỉǦƸƛǃǦǂẹǦǃƚǦǂỗƾǦǁƃǄǦǉử!ǦƞƽỉǦƸƛǃǦǂỗƾǦǁƃǄǦǉửǦǈốǃƼǦǈƚǉ!ǦƞƽỉǦƸƛǃǦǁƃǄǦǉử……ǦǁƃǄǦǉửǦƸƽƓǃƽǦǁƐǦǂǊốǃǦƸƽếǉǦởǦǥǇǊǃƼǦĐộǦƦƾềǊ!",
    ["可你们不一样！你们根本不是兵！滚回去！滚回去见你们的师父，见你们的爹妈，滚回家去啊。"] = "ƩƽưǃƼǦƸƑƸǦǃƼươƾǦǀƽƇǃƼǦƼƾốǃƼǦǋậǓ!ǦƞƑƸǦǃƼươƾǦƸăǃǦƷảǃǦǀƽƇǃƼǦǅƽảƾǦǁƐǦƷƾǃƽǦǁƓǃƽ!ǦƞƕǉǦǋềǦđƾ!ǦƞƕǉǦǋềǦƼặǅǦǈưǦǅƽụǦƸủƶǦƸƑƸǦǃƼươƾ,ǦƼặǅǦƸƽƶǦǂẹǦƸƑƸǦǃƼươƾ,ǦƸƕǉǦǋềǦǃƽƐǦđƾ.",
    ["别让他们……背你们的名……"] = "ĐừǃƼǦđểǦƷọǃǦƽọ……ǦǅƽảƾǦƼƑǃƽǦǋƑƸǦƸƑƾǦǉƙǃǦƸủƶǦƸƑƸǦǃƼươƾ……",
    ["太重了。……谢可九，丁献真，孟宽，你们的名，我背不动了……"] = "ƬǊƑǦǃặǃƼǦǇồƾ.Ǧ……ǦǥạǦƦƽảǦƞửǊ,ǦĐƾǃƽǦƣƾếǃǦƞƽƁǃ,ǦƨạǃƽǦƦƽǄƶǃ,ǦǃƽữǃƼǦƸƑƾǦǉƙǃǦƸủƶǦƸƑƸǦǃƼươƾ,ǦǉƶǦƸƅǃƼǦǀƽƇǃƼǦǃổƾǦǃữƶǦǇồƾ……",
    ["将军，我们还要战！"] = "ǥướǃƼǦǆǊƁǃ,ǦƸƽƕǃƼǦǉƶǦƸƛǃǦǂǊốǃǦƸƽƾếǃ!",
    ["我们还能战！"] = "ƞƽƕǃƼǦǉƶǦƸƛǃǦƸƚǦǉƽểǦƸƽƾếǃ!",
    ["跟您一起！"] = "ƞƖǃƼǦǋớƾǦǃƼƐƾ!",
    ["再去战！"] = "ƧạƾǦđƾǦƸƽƾếǃ!",
    ["唔呜呜呜呜呜呜——！"] = "ƯǦƽưǦƽưǦƽưǦƽư——!",
    ["毋归厚土，毋守孤坟"] = "ƱƇǦǆǊǓǦƽậǊǦǉƽổ,ǦǋƇǦǉƽủǦƸƇǦǅƽầǃ",
    ["吾血犹沸，执戈随军"] = "ƩƼƇǦƽǊǓếǉǦǤǄǦǅƽế,ǦđƔǃƽǦƸƽƾếǃǦǉƖǓǦǆǊƁǃ",
    ["同袍同泽，共此晨昏"] = "ĐồǃƼǦƷƐǄǦđồǃƼǦǉǇạƸƽ,ǦƸộǃƼǦǉƽửǦǉƽầǃǦƽƇǃ",
    ["师姐，我、我想喊一声。"] = "ƮưǦǉỷ,Ǧđệ,ǦđệǦǂǊốǃǦƽƗǉǦǁƙǃǦǂộǉǦǉƾếǃƼ.",
    ["仗义——疏财"] = "ǥǇượǃƼǦǃƼƽĩƶ——ǦƮơǦǉƐƾ",
    ["千——"] = "ǥƽƾƙǃ——",
    ["大点声啊高大花！"] = "ƣƗǉǦǁớǃǦǁƙǃǦǍƺǂǦǃƐǄǦƞƶǄǦĐạƾǦƣǄƶ!",
    ["听老子的——千金取义！"] = "ƩƼƽƺǦǁƃǄǦǉửǦđƁǓ——ǦǥƽƾƙǃǦǀƾǂǦǉƽủǦǃƼƽĩƶ!",
    ["师姐——我那刀……"] = "ƮưǦǉỷ——ǦƸƁǓǦđƶǄǦđƚǦƸủƶǦđệ……",
    ["给你了。"] = "ƞƽǄǦđệǦǇồƾǦđƚ.",
    ["在此……"] = "ǥạƾǦđƁǓ……",
    ["什么人骑肩头将手拍？"] = "ƩƼườƾǦǃƐǄǦƸưỡƾǦǋƶƾǦǋỗǦǉƶǓǦƸườƾ?",
    ["天上桫椤是什么人儿栽？"] = "ƮƶǦǁƶǦǉǇƙǃǦǉǇờƾǦǃƼườƾǦǃƐǄǦǉǇồǃƼ?",
    ["地下的黄河是什么人儿开？"] = "ƣǄƐǃƼǦƣƐǦǤướƾǦđấǉǦǃƼườƾǦǃƐǄǦǀƽơƾ?",
    ["什么人，打枣子，把羞儿害？"] = "ƩƼườƾǦǃƐǄ,ǦƽƑƾǦǉƑǄ,ǦǉƽẹǃǦǉƽƖǃƼǦǉƽƶǓ?",
    ["红彤彤，心跳儿快。"] = "ĐỏǦƷừǃƼǦƷừǃƼ,ǦǃƽịǅǦǉƾǂǦǃƽƶǃƽ.",
    ["什么人，骑肩头，将手拍？"] = "ƩƼườƾǦǃƐǄ,ǦƸưỡƾǦǋƶƾ,ǦǋỗǦǉƶǓǦƸườƾ?",
    ["枣儿香后，果核儿栽。"] = "ǥƑǄǦǉƽơǂǦǇồƾ,ǦǃƽƁǃǦƽạǉǦǉǇồǃƼ.",
    ["什么人，缝衣裳，把布裁？"] = "ƩƼườƾǦǃƐǄ,ǦǀƽƁǊǦƑǄ,ǦƸắǉǦǋảƾǦǂƶǓ?",
    ["远行人，向山外。"] = "ƩƼườƾǦǋƾễǃǦƽƐǃƽ,ǦƽướǃƼǦǃƼǄƐƾǦǃƕƾ.",
    ["什么人，望村头，备好菜？"] = "ƩƼườƾǦǃƐǄ,ǦǉǇƇǃƼǦǁƐǃƼ,ǦƸƽǊẩǃǦƷịǦƸơǂ?",
    ["夜夜盼，到天白。"] = "ĐƙǂǦđƙǂǦǂǄǃƼ,ǦǉớƾǦǉǇờƾǦǈƑǃƼ.",
    ["天上桫椤是王母娘娘栽。"] = "ƮƶǦǁƶǦǉǇƙǃǦǉǇờƾǦƱươǃƼǦƨẫǊǦǉǇồǃƼ.",
    ["地下的黄河是老龙王开。"] = "ƣǄƐǃƼǦƣƐǦǤướƾǦđấǉǦƧǄǃƼǦƱươǃƼǦǀƽơƾ.",
    ["什么人，离家去，没回来？"] = "ƩƼườƾǦǃƐǄ,ǦǇờƾǦǃƽƐ,ǦƸƽẳǃƼǦǉƽấǓǦǋề?",
    ["好英雄，守关外。"] = "ƣảǄǦƶǃƽǦƽƖǃƼ,ǦǉƽủǦǆǊƶǃǦǃƼǄạƾ.",
    ["爷娘呀，莫伤怀。"] = "ǝƶǦǃươǃƼǦƐ,ǦƸƽớǦƷƾǦƽǄƐƾ.",
    ["来年啊，太平处，枣花又开。"] = "ƩăǂǦǈƶǊǦǃƽƗ,ǦƸƽốǃǦǉƽƑƾǦƷƔǃƽ,ǦƽǄƶǦǉƑǄǦǁạƾǦǃở.",
    ["咱们快逃吧？"] = "ƞƽƕǃƼǦǉƶǦǂƶǊǦƸƽạǓǦđƾǦǉƽƇƾ?",
    ["往南的路早被虏人围了！逃，逃去哪儿？呵，呵呵……呜……"] = "ĐườǃƼǦǋềǦǅƽƓƶǦƩƶǂǦǈớǂǦđƃǦƷịǦǆǊƁǃǦƼƾặƸǦǋƁǓǦƽƃǂǦǇồƾ!ǦƞƽạǓ,ǦƸƽạǓǦđƾǦđƁǊ?Ǧƣừ,ǦƽừǦƽừ……ǦƽǊ……",
    ["咱不逃，咱等死，那娃儿怎么办啊！"] = "ǥƶǦǀƽƇǃƼǦƸƽạǓ,ǦǉƶǦƸƽờǦƸƽếǉ,ǦǃƽưǃƼǦƸƛǃǦđứƶǦǉǇẻǦđƚǦǉƽƔǦǁƐǂǦǈƶǄǦƷƁǓǦƼƾờ!",
    ["……不若我等再集千余人！"] = "……ƞƽƾǦƷằǃƼǦƸƽƕǃƼǦǉƶǦǉậǅǦƽợǅǦǉƽƙǂǦǃƼƐǃǦǃƼườƾǦǃữƶ!",
    ["对！他娘的，老子死也要死……"] = "ƫƽảƾ!ǦƨẹǦǀƾếǅ,ǦǁƃǄǦǉửǦƸƽếǉǦƸũǃƼǦǅƽảƾǦƸƽếǉ……",
    ["你真当自己这条烂命能有用？你没瞧见北边的京观？想再去添个头吗？！"] = "ƩƼươƾǦǉƽậǉǦǈựǦƸƽǄǦǇằǃƼǦƸƑƾǦǂạǃƼǦǇƑƸƽǦǃƐǓǦƸủƶǦǂƔǃƽǦƸƚǦƓƸƽǦǈƶǄ?ǦƩƼươƾǦǀƽƇǃƼǦǉƽấǓǦđốǃƼǦđầǊǦǃƼườƾǦƸƽấǉǦƸƶǄǦǃƽưǦǃƕƾǦởǦǅƽƓƶǦƝắƸǦƐ?ǦƨǊốǃǦǉớƾǦđƚǦƼƚǅǦǉƽƙǂǦǂộǉǦƸƑƾǦđầǊǦǃữƶǦǈƶǄ?!",
    ["诶，你醒了！是冷脸大侠带你回来嘞。"] = "Ê,ǦǃƼươƾǦǉỉǃƽǦǇồƾ!ǦƧƐǦƧƃǃƽǦǝƾệǃǦđạƾǦƽƾệǅǦđưƶǦǃƼươƾǦǋềǦđấǓ.",
    ["冷脸大侠？江……其他人呢！"] = "ƧƃǃƽǦǝƾệǃǦđạƾǦƽƾệǅ?ǦƢƾƶǃƼ……ǦǃƽữǃƼǦǃƼườƾǦǀƽƑƸǦđƁǊǦǇồƾ!",
    ["嗯……带刀大侠、盲眼大侠、胡子大侠、木鸟大侠……都没见着。"] = "Ừǂ……ǦĐớƾǦĐƶǄǦđạƾǦƽƾệǅ,ǦƨƶǃƽǦƩƽƃǃǦđạƾǦƽƾệǅ,ǦƣồǦǥửǦđạƾǦƽƾệǅ,ǦƨộƸǦĐƾểǊǦđạƾǦƽƾệǅ……ǦđềǊǦǀƽƇǃƼǦǉƽấǓǦđƁǊǦƸả.",
    ["我要跟林哥哥一起去南边了，我爹在南边等咱们呢。大侠，你也一起走吗？"] = "ƨǊộƾǦǈắǅǦƸƖǃƼǦƧƁǂǦƸƶǦƸƶǦđƾǦǋềǦǅƽƓƶǦƩƶǂǦǇồƾ,ǦƸƽƶǦǂǊộƾǦđƶǃƼǦđợƾǦƸƽƕǃƼǦǉƶǦởǦǅƽƓƶǦƩƶǂ.ǦĐạƾǦƽƾệǅ,ǦǃƼườƾǦƸũǃƼǦđƾǦƸƖǃƼǦƸƽứ?",
    ["我……不……你们先走吧……"] = "ǥƶ……ǦǀƽƇǃƼ……ǦƸƑƸǦǃƼươƾǦđƾǦǉǇướƸǦđƾ……",
    ["你之前不是挺狂吗……现在怎么不敢动了？"] = "ƧƕƸǦǉǇướƸǦƸƽẳǃƼǦǅƽảƾǦǃƼươƾǦƸǊồǃƼǦǁắǂǦǈƶǄ……ǦƼƾờǦǈƶǄǦǁạƾǦǀƽƇǃƼǦǤƑǂǦđộǃƼǦđậǓǦǇồƾ?",
    ["对，我就是吃马矢了。对，我还就是卖亲骨肉了。"] = "ƫƽảƾ,ǦǉƶǦƸƽƓǃƽǦǁƐǦƽạǃƼǦăǃǦǅƽƁǃǦǃƼựƶǦđấǓ.Ǧƫƽảƾ,ǦǉƶǦƸƛǃǦƸƽƓǃƽǦǁƐǦǀẻǦƷƑǃǦǇẻǦǂƑǊǦǂủǦƸủƶǦǂƔǃƽǦđấǓ.",
    ["吃马矢我能活，卖老爹老娘我能活！你能打，你有本事，你要面儿，你活不了！"] = "ĂǃǦǅƽƁǃǦǃƼựƶǦǉƶǦǈốǃƼǦđượƸ,ǦƷƑǃǦƸảǦƸƽƶǦƼƾƐǦǂẹǦƽƗǄǦǉƶǦǈốǃƼǦđượƸ!ǦƩƼươƾǦƼƾỏƾǦđƑǃƽǦđấǂ,ǦǃƼươƾǦƸƚǦƷảǃǦǁĩǃƽ,ǦǃƼươƾǦǉǇọǃƼǦǉƽểǦǤƾệǃ,ǦǃƽưǃƼǦǃƼươƾǦǀƽƇǃƼǦǈốǃƼǦǃổƾ!",
    ["现在……现在好了吧……呜……我……"] = "ƢƾờǦǉƽƔ……ǦƼƾờǦǉƽƔǦƽƶǓǦǇồƾǦƸƽứǦƼƔ……ǦƽǊ……Ǧǉƶ……",
    ["我不想死……呜呜……我怕死……我不要死在这里……"] = "ǥƶǦǀƽƇǃƼǦǂǊốǃǦƸƽếǉ……ǦƽǊǦƽǊ……ǦǉƶǦǈợǦƸƽếǉ……ǦǉƶǦǀƽƇǃƼǦǂǊốǃǦƸƽếǉǦởǦǃơƾǦǃƐǓ……",
    ["可是连你都死了，我……我也死定了……呜啊……"] = "ƩƽưǃƼǦđếǃǦƸảǦǃƼươƾǦƸũǃƼǦƸƽếǉǦǇồƾ,Ǧǉƶ……ǦǉƶǦƸũǃƼǦƸƽếǉǦƸƽắƸǦǇồƾ……ǦƽǊǦǄƶ……",
    ["你真不走？"] = "ƩƼươƾǦǉƽựƸǦǈựǦǀƽƇǃƼǦđƾǦǈƶǄ?",
    ["刘铭"] = "ƧưǊǦƨƾǃƽ",
    ["呵，我这腿，往哪儿走？不如就烂在这里，当个绊马脚的麻袋，也算摆虏狗一道。"] = "ƣừ,ǦƸƑƾǦƸƽƁǃǦǃƐǓǦƸủƶǦǉƶǦǉƽƔǦđƾǦđƁǊǦđượƸ?ǦƞƽƾǦƷằǃƼǦƸứǦđểǦǃƚǦǉƽốƾǦǇữƶǦởǦđƁǓ,ǦǁƐǂǦƸƑƾǦƷƶǄǦǉảƾǦǃƼƑǃƼǦƸƽƁǃǦǃƼựƶ,ǦƸũǃƼǦƸǄƾǦǃƽưǦƸƽơƾǦǍỏǦǁũǦƸƽƚǦƼƾặƸǦǂộǉǦǋố.",
    ["天尊呐，败说怪话了。你不是还有个啥书院的信物？给我，我碰碰运气去？要是活着碰头了，让他们想招儿来接你。"] = "ǥƽƾƙǃǦǥƇǃǦơƾ,ǦđừǃƼǦǃƚƾǦǂấǓǦǁờƾǦǆǊƑƾǦƼởǦđƚǦǃữƶ.ǦƦƽƇǃƼǦǅƽảƾǦǃƼươƾǦƸƛǃǦƸƚǦƸƑƾǦǉƓǃǦǋậǉǦƸủƶǦǉƽưǦǋƾệǃǦƼƔǦđƚǦǈƶǄ?ǦĐưƶǦǉƶ,ǦǉƶǦđƾǦǉƽửǦǋậǃǦǂƶǓǦǍƺǂ?ǦƩếǊǦƸƛǃǦǈốǃƼǦǂƐǦƼặǅǦđượƸǦƽọ,ǦǉƶǦǈẽǦƷảǄǦƽọǦǃƼƽĩǦƸƑƸƽǦǉớƾǦđƚǃǦǃƼươƾ.",
    ["书院？呵，鹤院长若能来此地早就来了，只怕封龙山自身难保，已成了瓦砾场了……"] = "ǥƽưǦǋƾệǃ?Ǧƣừ,ǦƣạƸǦǋƾệǃǦǉǇưởǃƼǦǃếǊǦƸƚǦǉƽểǦǉớƾǦđƁǓǦǉƽƔǦđƃǦǉớƾǦǉừǦǁƁǊǦǇồƾ,ǦƸƽỉǦǈợǦǃƕƾǦƫƽǄǃƼǦƧǄǃƼǦǉựǦǉƽƁǃǦƸƛǃǦǀƽƚǦƷảǄǦǉǄƐǃ,ǦđƃǦǉǇởǦǉƽƐǃƽǦđốǃƼǦƼạƸƽǦǋụǃǦǇồƾ……",
    ["啧，别管我了， you 走吧。"] = "ƞƽậƸ,ǦđừǃƼǦǆǊảǃǦǉƶǦǃữƶ,ǦǃƼươƾǦđƾǦđƾ.",
    ["你呢？就搁这儿等死？"] = "ƞƛǃǦǃƼươƾ?ǦƞứǦởǦđƁǓǦƸƽờǦƸƽếǉǦǈƶǄ?",
    ["在哪儿死，不都一样……"] = "ƞƽếǉǦởǦđƁǊǦǂƐǦƸƽẳǃƼǦƼƾốǃƼǦǃƽƶǊ……",
    ["枭骑战斗死，驽马徘徊鸣。梁筑室，何以南？何以北？"] = "ƦƾƙǊǦǀỵǦƸƽƾếǃǦđấǊǦǉử,ǦǃỗǦǂƃǦƷồƾǦƽồƾǦǂƾǃƽ.ǦƧươǃƼǦǉǇƕƸǦǉƽấǉ,ǦƽƐǦǤĩǦǃƶǂ?ǦƣƐǦǤĩǦƷắƸ?",
    ["死了好，死了好，早该死了。"] = "ƞƽếǉǦđƾǦǉƽƔǦǉốǉ,ǦƸƽếǉǦđƾǦǉƽƔǦǉốǉ,ǦǈớǂǦđƃǦǃƙǃǦƸƽếǉǦǇồƾ.",
    ["……朝行出攻，暮不夜归！"] = "……ǥǇƾƙǊǦƽƐǃƽǦǍǊấǉǦƸƇǃƼ,ǦǂộǦƷấǉǦǤạǦǆǊǓ!",
    ["下一批，一个时辰后必须出发了。沈渊师兄都安排好了，这批你来带队。"] = "ĐợǉǦǉƾếǅǦǉƽƺǄ,ǦǂộǉǦƸƶǃƽǦƼƾờǦǃữƶǦǃƽấǉǦđịǃƽǦǅƽảƾǦǍǊấǉǦǅƽƑǉ.ǦǥƽẩǂǦǕǓƙǃǦǈưǦƽǊǓǃƽǦđƃǦǈắǅǦǍếǅǦǍǄǃƼǦƸảǦǇồƾ,ǦđợǉǦǃƐǓǦđệǦǤẫǃǦđộƾ.",
    ["师兄放心，就交给我吧！"] = "ƮưǦƽǊǓǃƽǦǓƙǃǦǉƁǂ,ǦƸứǦƼƾƶǄǦƸƽǄǦđệ!",
    ["等这批也走了，剩下的就都是些行动不便或是不愿南逃的人了……"] = "ĐợƾǦđợǉǦǃƐǓǦđƾǦǃốǉ,ǦǃƽữǃƼǦǃƼườƾǦƸƛǃǦǁạƾǦđềǊǦǁƐǦƽạǃƼǦƽƐǃƽǦđộǃƼǦƷấǉǦǉƾệǃǦƽǄặƸǦǀƽƇǃƼǦǂǊốǃǦƸƽạǓǦǋềǦǅƽƓƶǦƩƶǂ……",
    ["陆师弟平日里最有主意了，他已经在一个个劝了。"] = "ƧụƸǦǈưǦđệǦǃƼƐǓǦǉƽườǃƼǦǁƐǦǃƼườƾǦǃƽƾềǊǦƸƽủǦǀƾếǃǦǃƽấǉ,ǦđệǦấǓǦđƶǃƼǦđƾǦǀƽǊǓƙǃǦƷảǄǦǉừǃƼǦǃƼườƾǦǂộǉǦǇồƾ.",
    ["无妨，若真走不了，也有我们这几个留下殿后。便是同那群虏狗拼了命，也要给他们争取到时间。"] = "ƦƽƇǃƼǦǈƶǄ,ǦǃếǊǦǉƽựƸǦǈựǦǀƽƇǃƼǦđƾǦđượƸ,ǦƸũǃƼǦƸƛǃǦǂấǓǦǃƼườƾǦƸƽƕǃƼǦǉƶǦởǦǁạƾǦđǄạǃǦƽậǊ.ǦƞƽǄǦǤƖǦƸƚǦǅƽảƾǦǁƾềǊǦǂạǃƼǦǋớƾǦǁũǦƸƽƚǦƼƾặƸǦǀƾƶ,ǦƸũǃƼǦǅƽảƾǦǉǇƶǃƽǦǉƽủǦǉƽờƾǦƼƾƶǃǦƸƽǄǦƽọ.",
    ["等我把百姓都送到安全地方去，就回来帮你们！"] = "ĐợƾǦđệǦđưƶǦƷƑǦǉƑǃƽǦǉớƾǦǃơƾǦƶǃǦǉǄƐǃǦǇồƾǦǈẽǦǆǊƶǓǦǁạƾǦƼƾƕǅǦƸƑƸǦƽǊǓǃƽ!",
    ["这附近哪儿还有安生地方……你的任务是带着百姓南逃，一直到方圆十里都看不见一骑虏人骑兵才许离开，听到没？"] = "ƬǊƶǃƽǦđƁǓǦǁƐǂǦƼƔǦƸƛǃǦǃơƾǦǃƐǄǦǓƙǃǦổǃǦǃữƶ……ǦƩƽƾệǂǦǋụǦƸủƶǦđệǦǁƐǦđưƶǦƷƑǦǉƑǃƽǦƸƽạǓǦǋềǦǅƽƓƶǦƩƶǂ,ǦƸƽǄǦǉớƾǦǀƽƾǦǉǇǄǃƼǦǋƛǃƼǦǂườƾǦǤặǂǦǀƽƇǃƼǦǉƽấǓǦƷƚǃƼǦǤƑǃƼǦǂộǉǦǉƙǃǦǀỵǦƷƾǃƽǦƼƾặƸǦǃƐǄǦǂớƾǦđượƸǦǇờƾǦđƾ,ǦǃƼƽƺǦǇƅǦƸƽưƶ?",
    ["你走到哪，便将撤退的消息带到那附近，同其他人一样，都不许回头了。"] = "ĐệǦđƾǦđếǃǦđƁǊ,ǦƽƃǓǦǂƶǃƼǦǉƾǃǦǉứƸǦǇƕǉǦǁǊƾǦǉớƾǦǋƖǃƼǦǁƁǃǦƸậǃǦđƚ,ǦƸũǃƼǦǃƽưǦǃƽữǃƼǦǃƼườƾǦǀƽƑƸ,ǦđềǊǦǀƽƇǃƼǦđượƸǦǆǊƶǓǦđầǊǦǁạƾ.",
    ["这是命令！大帅匆匆赶去了前线，咱在后头听吩咐，可不能乱。"] = "ĐƁǓǦǁƐǦǂệǃƽǦǁệǃƽ!ǦĐạƾǦǈǄƑƾǦđƃǦǋộƾǦǋƃǦǉớƾǦǉƾềǃǦǉǊǓếǃǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦởǦǅƽƓƶǦǈƶǊǦǃƼƽƺǦǈƶƾǦƷảǄ,ǦǀƽƇǃƼǦđượƸǦǁƐǂǦǁǄạǃ.",
    ["逃……还能……呜……逃去哪儿……"] = "ƞƽạǓ……ǦƸƛǃǦƸƚǦǉƽể……ǦƽǊ……ǦƸƽạǓǦđƾǦđƁǊǦđượƸǦǃữƶ……",
    ["大侠……救救我们……"] = "ĐạƾǦƽƾệǅ……ǦƸứǊǦƸứǊǦƸƽƕǃƼǦǉƇƾǦǋớƾ……",
    ["他们一个个地走，上将军那儿去，结果一个个地都没有回来……"] = "ƣọǦǉừǃƼǦǃƼườƾǦǉừǃƼǦǃƼườƾǦǂộǉǦǇƶǦđƾ,ǦđƾǦǉớƾǦƸƽỗǦǥƽượǃƼǦǉướǃƼǦǆǊƁǃ,ǦǀếǉǦǆǊảǦǉừǃƼǦǃƼườƾǦǉừǃƼǦǃƼườƾǦǂộǉǦđềǊǦǀƽƇǃƼǦǉǇởǦǋề……",
    ["这地方就要完了，我们…… we 该往哪里逃？"] = "ƩơƾǦǃƐǓǦǈắǅǦǍǄǃƼǦđờƾǦǇồƾ,ǦƸƽƕǃƼǦǉƶ……ǦƸƽƕǃƼǦǉƶǦǃƙǃǦƸƽạǓǦđƾǦđƁǊ?",
    ["到处都是骑马的虏人，周阿根叫他们踩死了，小福车让他们砍死了，秦阿婆也病倒了，还有好多受伤的人……"] = "ƦƽắǅǦǃơƾǦđềǊǦǁƐǦǆǊƁǃǦƼƾặƸǦƸưỡƾǦǃƼựƶ,ǦƞƽǊǦƜǦƞăǃǦƷịǦƸƽƕǃƼǦƼƾẫǂǦƸƽếǉǦǇồƾ,ǦǥƾểǊǦƫƽƕƸǦƳƶǦƷịǦƸƽƕǃƼǦƸƽƗǂǦƸƽếǉǦǇồƾ,ǦǥầǃǦƜǦƝƐǦƸũǃƼǦƷệǃƽǦǁƾệǉǦƼƾườǃƼǦǇồƾ,ǦƸƛǃǦƷƶǄǦǃƽƾƙǊǦǃƼườƾǦƷịǦǉƽươǃƼǦǃữƶ……",
    ["阿嫂，思思还小，还需要你……你们抓紧跟着下一队走，剩下的交给我们。"] = "ƜǦǉẩǊ,ǦǥưǦǥưǦƸƛǃǦǃƽỏ,ǦǋẫǃǦƸầǃǦƸƚǦǉẩǊ……ǦƨọƾǦǃƼườƾǦǂƶǊǦƸƽƚǃƼǦđƾǦǉƽƺǄǦđộƾǦǉƾếǅǦǉƽƺǄǦđƾ,ǦǅƽầǃǦƸƛǃǦǁạƾǦƸứǦƼƾƶǄǦƸƽǄǦƸƽƕǃƼǦǉƇƾ.",
    ["对了……思思，还有思思。我得带着思思逃走……"] = "ƫƽảƾǦǇồƾ……ǦǥưǦǥư,ǦƸƛǃǦƸƚǦǥưǦǥưǦǃữƶ.ǦǥƶǦǅƽảƾǦđưƶǦǥưǦǥưǦƸƽạǓǦǉǇốǃǦǉƽƇƾ……",
    ["她一直说会有个大哥哥领着大家走，想来是有法子的……"] = "ƞǄǃǦƷƗǦƸứǦǁǊƇǃǦǂƾệǃƼǦǃƚƾǦǈẽǦƸƚǦǂộǉǦǋịǦđạƾǦƸƶǦƸƶǦǤẫǃǦǂọƾǦǃƼườƾǦđƾ,ǦƸƽắƸǦƽẳǃǦǁƐǦƸƚǦƸƑƸƽǦǇồƾ……",
    ["别怕，我们都会帮你。我就是拼上这条命，也定会送你们平安离开。"] = "ĐừǃƼǦǈợ,ǦƸƽƕǃƼǦǉƇƾǦđềǊǦǈẽǦƼƾƕǅǦǉẩǊ.ǦǥƇƾǦǤƖǦƸƚǦǅƽảƾǦǁƾềǊǦƸƑƾǦǂạǃƼǦǃƐǓ,ǦƸũǃƼǦǃƽấǉǦđịǃƽǦǉƾễǃǦǂọƾǦǃƼườƾǦǇờƾǦđƾǦƷƔǃƽǦƶǃ.",
    ["将军……桥……我要……去……"] = "ǥướǃƼǦǆǊƁǃ……ǦƸầǊ……ǦƸǄǃǦǂǊốǃ……Ǧđƾ……",
    ["别乱动……你放心，有人去了……会、会有人的。咱们都能活下来。"] = "ĐừǃƼǦƸửǦđộǃƼǦǁǄạǃ……ǦǃƼươƾǦǓƙǃǦǉƁǂ,ǦƸƚǦǃƼườƾǦđƾǦǇồƾ……Ǧǈẽ,ǦǈẽǦƸƚǦǃƼườƾǦǉƽƇƾ.ǦƞƽƕǃƼǦǉƶǦđềǊǦƸƚǦǉƽểǦǈốǃƼǦǈƚǉ.",
    ["大侠，你见过我师父吗？"] = "ĐạƾǦƽƾệǅ,ǦǃƼườƾǦƸƚǦǉƽấǓǦǈưǦǅƽụǦƸủƶǦƸǄǃǦǀƽƇǃƼ?",
    ["他……或许也往南边去了，你快去寻他吧。"] = "ƩƼườƾ……ǦƸƚǦǁẽǦƸũǃƼǦđƾǦǋềǦǅƽƓƶǦƩƶǂǦǇồƾ,ǦǃƼươƾǦǂƶǊǦđƾǦǉƔǂǦǃƼườƾǦđƾ.",
    ["他上了年纪，走不了太多路，我、我……我还该领他回家去的……了吗？他赶上了吗？"] = "ƩƼườƾǦđƃǦƸƚǦǉǊổƾǦǇồƾ,ǦǀƽƇǃƼǦđƾǦđượƸǦǃƽƾềǊǦđườǃƼǦđƁǊ,ǦƸǄǃ,ǦƸǄǃ……ǦƸǄǃǦƸƛǃǦǅƽảƾǦǤẫǃǦǃƼườƾǦǋềǦǃƽƐǦǃữƶǦǂƐ……Ǧư?ǦƩƼườƾǦƸƚǦǀịǅǦǀƽƇǃƼ?",
    ["……不，我哪儿也不去。师父说过，医术要用来救死扶伤，否则读再多书，也还是废纸一堆。"] = "……ƦƽƇǃƼ,ǦƸǄǃǦƸƽẳǃƼǦđƾǦđƁǊǦƽếǉ.ǦƮưǦǅƽụǦđƃǦǃƚƾ,ǦǓǦǉƽǊậǉǦǁƐǦǤƖǃƼǦđểǦƸứǊǦǃƼườƾǦƼƾƕǅǦđờƾ,ǦǃếǊǦǀƽƇǃƼǦǉƽƔǦǤƖǦƸƚǦđọƸǦƷƶǄǦǃƽƾƙǊǦǈƑƸƽǦƸũǃƼǦƸƽỉǦǁƐǦǂộǉǦđốǃƼǦƼƾấǓǦǋụǃǦǉƽƇƾ.",
    ["这儿受伤的人多，师父若还活着，一定也会到这儿来……"] = "ỞǦđƁǓǦƸƚǦǃƽƾềǊǦǃƼườƾǦƷịǦǉƽươǃƼ,ǦǈưǦǅƽụǦǃếǊǦƸƛǃǦǈốǃƼ,ǦǃƽấǉǦđịǃƽǦƸũǃƼǦǈẽǦǉớƾǦđƁǓ……",
    ["而若师父已经遭遇不测……我也还得继续救人. "] = "ƞƛǃǦǃếǊǦǈưǦǅƽụǦđƃǦƼặǅǦƷấǉǦǉǇắƸ……ǦƸǄǃǦƸũǃƼǦǋẫǃǦǅƽảƾǦǉƾếǅǦǉụƸǦƸứǊǦǃƼườƾ.",
    ["些个到处行侠仗义的臭蛆扒都不见了，这些个红衣服的还想着怎么去拖延时间，也活不了多久了……"] = "ƨấǓǦƸƑƾǦǁũǦǤƛƾǦƷọǦƽƇƾǦƽƑǂǦǈǊốǉǦǃƼƐǓǦƽƐǃƽǦƽƾệǅǦǉǇượǃƼǦǃƼƽĩƶǦđềǊǦƷƾếǃǦǂấǉǦǈạƸƽǦǇồƾ,ǦƸƛǃǦđƑǂǦǂặƸǦƑǄǦđỏǦǃƐǓǦǋẫǃǦƸƛǃǦǃƼƽĩǦƸƑƸƽǦǀƗǄǦǤƐƾǦǉƽờƾǦƼƾƶǃ,ǦƸũǃƼǦƸƽẳǃƼǦǈốǃƼǦđượƸǦƷƶǄǦǁƁǊǦǃữƶǦđƁǊ……",
    ["哼，老子的好日子终于快到了！"] = "ƣừ,ǦǃƼƐǓǦǁƐǃƽǦƸủƶǦǁƃǄǦǉửǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦǈắǅǦǉớƾǦǇồƾ!",
    ["大哥，要是那些虏人杀到这儿来了……"] = "ĐạƾǦƸƶ,ǦǃếǊǦƷọǃǦǆǊƁǃǦƼƾặƸǦđƚǦƼƾếǉǦǉớƾǦǉậǃǦđƁǓ……",
    ["打得过就打，打不过——投降不会吗？"] = "ĐƑǃƽǦđượƸǦǉƽƔǦđƑǃƽ,ǦđƑǃƽǦǀƽƇǃƼǦǁạƾ——ǦƸƽẳǃƼǦǁẽǦǀƽƇǃƼǦƷƾếǉǦđầǊǦƽƐǃƼǦǈƶǄ?",
    ["之前他们都上赶着骂那杜狗、虏狗，夸那王清英勇、义气。结果怎么着？"] = "ƧƕƸǦǉǇướƸǦƷọǃǦƽọǦǉƽƾǦǃƽƶǊǦƸƽửƾǦǉƙǃǦƸƽƚǦƽọǦĐỗ,ǦǁũǦƸƽƚǦƼƾặƸ,ǦǇồƾǦǀƽƺǃǦƱươǃƼǦǥƽƶǃƽǦƶǃƽǦǤũǃƼ,ǦǃƼƽĩƶǦǀƽƓ.ǦƦếǉǦǆǊảǦǉƽƔǦǈƶǄ?",
    ["那王清的人给虏狗剁成了泥，而他们口里的杜狗还活得好好的咧！"] = "ƩƼườƾǦƸủƶǦƱươǃƼǦǥƽƶǃƽǦƷịǦǁũǦƸƽƚǦƼƾặƸǦƷăǂǦǉƽƐǃƽǦƷƖǃǦǇồƾ,ǦƸƛǃǦǉƙǃǦƸƽƚǦƽọǦĐỗǦǉǇǄǃƼǦǂƾệǃƼǦƷọǃǦƽọǦǉƽƔǦǋẫǃǦǈốǃƼǦǃƽăǃǦǇăǃƼǦǀƔƶ!",
    ["你等着吧，要不了几日，那群狗东西保准又过回之前的好日子了。"] = "ƩƼươƾǦƸứǦƸƽờǦǂƐǦǍƺǂ,ǦǀƽƇǃƼǦǆǊƑǦǂấǓǦǃƼƐǓ,ǦđƑǂǦƸƽƚǦǂƑǦđƚǦƸƽắƸǦƸƽắǃǦǁạƾǦǆǊƶǓǦǋềǦǃƽữǃƼǦǃƼƐǓǦǈǊǃƼǦǈướǃƼǦǃƽưǦǉǇướƸǦǉƽƇƾ.",
    ["而那些什么江湖侠客，都烂成了死尸，灰都不留一撮。没个鸟用！"] = "ƞƛǃǦǂấǓǦƸƑƾǦƽạǃƼǦƽƾệǅǦǀƽƑƸƽǦƼƾƶǃƼǦƽồǦƼƔǦđƚ,ǦđềǊǦđƃǦǉƽốƾǦǇữƶǦǉƽƐǃƽǦǍƑƸǦƸƽếǉ,ǦđếǃǦǂộǉǦǃắǂǦǉǇǄǦƸũǃƼǦƸƽẳǃƼǦƸƛǃ.ǦƞƽẳǃƼǦđượƸǦƸƑƾǦǉƓƸƽǦǈựǦƼƔ!",
    ["我就不该让他带到这地方来……这就是个虎狼窝！"] = "ƧẽǦǇƶǦǉƇƾǦǀƽƇǃƼǦǃƙǃǦđểǦƇǃƼǦấǓǦǂƶǃƼǦǉớƾǦǃơƾǦǃƐǓ……ǦĐƁǓǦđƕǃƼǦǁƐǦƽƶǃƼǦƽƖǂǦǃọƸǦǇắǃ!",
    ["敌人在河对岸，却也在窝里头！"] = "ƦẻǦǉƽƖǦởǦƷƙǃǦǀƾƶǦǈƇǃƼ,ǦǃƽưǃƼǦƸũǃƼǦởǦǃƼƶǓǦǉǇǄǃƼǦǉổ!",
    ["他不像我，孤身一人。他家里还有云娘，还有孩子，还有双亲…"] = "ƣǊǓǃƽǦấǓǦǀƽƇǃƼǦƼƾốǃƼǦǉƇƾ,ǦƸƇǦđộƸǦǂộǉǦǂƔǃƽ.ǦƩƽƐǦƽǊǓǃƽǦấǓǦƸƛǃǦƸƚǦƱƁǃǦǃươǃƼ,ǦƸƛǃǦƸƚǦƸǄǃǦǉƽơ,ǦƸƛǃǦƸƚǦǈǄǃƼǦǉƽƁǃ…",
    ["叛徒……他杜重威是最大的叛徒！"] = "ƫƽảǃǦđồ……ǦĐỗǦǥǇọǃƼǦǕǓǦƽắǃǦǁƐǦǉƙǃǦǅƽảǃǦđồǦǁớǃǦǃƽấǉ!",
    ["神行李"] = "ǥƽầǃǦƣƐǃƽǦƧƈ",
    ["足足十二道援信……将军的十二个……十二个信使……"] = "ĐủǦǂườƾǦƽƶƾǦđạǄǦǋƾệǃǦǉƓǃ……ǦǂườƾǦƽƶƾǦǋị……ǦǂườƾǦƽƶƾǦǋịǦǉƓǃǦǈứǦƸủƶǦǉướǃƼǦǆǊƁǃ……",
    ["一个也没活下来！都叫那狗东西杀了！"] = "ƦƽƇǃƼǦǂộǉǦƶƾǦǈốǃƼǦǈƚǉ!ǦĐềǊǦƷịǦǉƙǃǦƸƽƚǦǂƑǦđƚǦƼƾếǉǦǈạƸƽǦǇồƾ!",
    ["我来晚了……来不及了……"] = "ǥƶǦǉớƾǦǂǊộǃǦǇồƾ……ǦǀƽƇǃƼǦǀịǅǦǃữƶǦǇồƾ……",
    ["将军……我……很快来见你……"] = "ǥướǃƼǦǆǊƁǃ……Ǧǉƶ……ǦǈẽǦǈớǂǦǉớƾǦƼặǅǦǃƼƐƾ……",
    ["大侠到了，咱这下可有活路了！"] = "ĐạƾǦƽƾệǅǦǉớƾǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦǅƽƺǃǦǃƐǓǦƸƚǦǁốƾǦǉƽǄƑǉǦǇồƾ!",
    ["娘，我害怕——"] = "ƨẹǦơƾ,ǦƸǄǃǦǈợǦǆǊƑ——",
    ["大侠，快帮帮王清将军吧！"] = "ĐạƾǦƽƾệǅ,ǦǂƶǊǦƼƾƕǅǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃǦđƾ!",
    ["都怪我……怪我告诉他……说北边儿还有野菜挖……"] = "ĐềǊǦǉạƾǦǉƇƾ……ǦǉạƾǦǉƇƾǦƷảǄǦǃƚ……ǦǁƐǦởǦǅƽƓƶǦƝắƸǦƸƛǃǦƸƚǦǇƶǊǦǤạƾǦđểǦƽƑƾ……",
    ["他还那么小，怎么……怎么就去了那么远的地方……"] = "ƩƚǦƸƛǃǦǃƽỏǦǉƽếǦǀƾƶ,ǦǈƶǄ……ǦǈƶǄǦǁạƾǦđƾǦǉớƾǦǃơƾǦǍƶǦǍƇƾǦǃƽưǦǋậǓ……",
    ["……吃点儿吧，刚做的土粑粑。"] = "……ĂǃǦƸƽƕǉǦđƾ,ǦƷƑǃƽǦđấǉǦǂớƾǦǁƐǂǦđấǓ.",
    ["吃了土，人能活。"] = "ĂǃǦđấǉǦǉƽƔǦǃƼườƾǦǂớƾǦǈốǃƼǦđượƸ.",
    ["小福车不吃，小福车活不了. "] = "ǥƾểǊǦƫƽƕƸǦƳƶǦǀƽƇǃƼǦăǃ,ǦǥƾểǊǦƫƽƕƸǦƳƶǦǀƽƇǃƼǦǈốǃƼǦǃổƾ.",
    ["活不了……活不了了…… hu……"] = "ƦƽƇǃƼǦǈốǃƼǦđượƸ……ǦǀƽƇǃƼǦǈốǃƼǦǃổƾǦǃữƶǦǇồƾ……ǦƽǊ……",
    ["奶奶说，吃饱了饭，干啥都有力气了。"] = "ƝƐǦǃộƾǦǃƚƾ,ǦăǃǦǃǄǦƸơǂǦǇồƾǦǁƐǂǦƼƔǦƸũǃƼǦƸƚǦǈứƸǦǁựƸ.",
    ["这些野菜挖了回去给奶奶，奶奶就能好起来"] = "ƣƑƾǦǂấǓǦǉƽứǦǇƶǊǦǤạƾǦǃƐǓǦǂƶǃƼǦǋềǦƸƽǄǦƷƐǦǃộƾ,ǦƷƐǦǈẽǦǀƽỏƺǦǁạƾǦǉƽƇƾ.",
    ["等奶奶好了，大哥哥就能带我们去南边，大家一起去好地方……"] = "ĐợƾǦƷƐǦǀƽỏƺǦǇồƾ,ǦđạƾǦƸƶǦƸƶǦƸƚǦǉƽểǦđưƶǦƸƽƕǃƼǦǉƶǦǋềǦǅƽƓƶǦƩƶǂ,ǦǂọƾǦǃƼườƾǦƸƖǃƼǦđƾǦǉớƾǦǃơƾǦǉốǉǦđẹǅ……",
    ["娘，我们会死吗？"] = "ƨẹǦơƾ,ǦƸƽƕǃƼǦǉƶǦǈẽǦƸƽếǉǦǈƶǄ?",
    ["娘，我好不容易又捡到了一小块碎馍馍……"] = "ƨẹǦơƾ,ǦƸǄǃǦǀƽƚǦǀƽăǃǦǁắǂǦǂớƾǦǃƽặǉǦđượƸǦǂộǉǦǂẩǊǦǂƐǃǦǉƽầǊǦǋụǃ……",
    ["娘，你快吃吧，小豆苗还会去找的。吃了馍馍，就能动弹了……"] = "ƨẹǦơƾ,ǦǂẹǦǂƶǊǦăǃǦđƾ,ǦǥƾểǊǦĐậǊǦƨƾƙǊǦǈẽǦǁạƾǦđƾǦǉƔǂǦǉƾếǅ.ǦĂǃǦǂƐǃǦǉƽầǊǦǇồƾǦǉƽƔǦǈẽǦƸƚǦǈứƸǦđểǦƸửǦđộǃƼǦǉƽƇƾ……",
    ["他们都说，死了好多人，再不跑就命了……"] = "ƣọǦđềǊǦǃƚƾ,ǦƸƽếǉǦǃƽƾềǊǦǃƼườƾǦǁắǂǦǇồƾ,ǦǀƽƇǃƼǦƸƽạǓǦǃƽƶǃƽǦǉƽƔǦǂấǉǦǂạǃƼǦđấǓ……",
    ["可我想带着娘一起跑……娘……你快起来吧……"] = "ƩƽưǃƼǦƸǄǃǦǂǊốǃǦđưƶǦǂẹǦƸƖǃƼǦƸƽạǓ……ǦǂẹǦơƾ……ǦǂẹǦǂƶǊǦǤậǓǦđƾ……",
    ["得快点儿，再快一点儿——"] = "ƫƽảƾǦǃƽƶǃƽǦǁƙǃ,ǦǃƽƶǃƽǦǉƽƙǂǦƸƽƕǉǦǃữƶ——",
    ["好鸟儿，你快飞，飞得快点儿，再快一点儿——"] = "ƞƽƾǂǦǃƼǄƶǃ,ǦǂƐǓǦƷƶǓǦǃƽƶǃƽǦǁƙǃ,ǦƷƶǓǦǃƽƶǃƽǦǁƙǃ,ǦǃƽƶǃƽǦǉƽƙǂǦƸƽƕǉǦǃữƶ——",
    ["你在……送信？"] = "ƩƼươƾǦđƶǃƼ……ǦđưƶǦǉƽưǦǈƶǄ?",
    ["这信最是紧急，这信……这信是师兄他们的希望……"] = "ƧƑǦǉƽưǦǃƐǓǦǁƐǦǀƽẩǃǦƸấǅǦǃƽấǉ,ǦǁƑǦǉƽưǦǃƐǓ……ǦǁƑǦǉƽưǦǃƐǓǦǁƐǦƽǓǦǋọǃƼǦƸủƶǦƷọǃǦǈưǦƽǊǓǃƽ……",
    ["狗将军把师兄师姐们卖给了虏人，列了好长一份名册。"] = "ǥƙǃǦǉướǃƼǦǆǊƁǃǦƸƽƚǦƸƽếǉǦđƃǦƷƑǃǦđứǃƼǦƸƑƸǦǈưǦƽǊǓǃƽǦǈưǦǉỷǦƸƽǄǦǆǊƁǃǦƼƾặƸ,ǦǁƾệǉǦǀƙǦǂộǉǦƷảǃǦǤƶǃƽǦǈƑƸƽǦǉƽậǉǦǤƐƾ.",
    ["师兄们回不来了，我得把这信送到鹏长老手里，不能叫他们再来送死！"] = "ƞƑƸǦǈưǦƽǊǓǃƽǦǀƽƇǃƼǦǋềǦđượƸǦǃữƶǦǇồƾ,ǦǉƶǦǅƽảƾǦđưƶǦǁƑǦǉƽưǦǃƐǓǦǉớƾǦǉƶǓǦƝằǃƼǦǉǇưởǃƼǦǁƃǄ,ǦǀƽƇǃƼǦǉƽểǦđểǦƽọǦǉớƾǦđƁǓǦǃộǅǦǂạǃƼǦǃữƶ!",
    ["游侠，你要是遇见了鹏长老或是其他墨门弟子，就告诉他们——"] = "ǝǊǦƽƾệǅ,ǦǃếǊǦǃƼươƾǦƸƚǦƼặǅǦƝằǃƼǦǉǇưởǃƼǦǁƃǄǦƽƶǓǦđệǦǉửǦƨặƸǦƨƇǃǦǀƽƑƸ,ǦƽƃǓǦƷảǄǦƽọ——",
    ["快回头！带大家回不见山！一定一定要快啊！"] = "ƨƶǊǦǆǊƶǓǦđầǊǦǁạƾ!ǦĐưƶǦǂọƾǦǃƼườƾǦǋềǦǃƕƾǦƝấǉǦƦƾếǃ!ǦƩƽấǉǦđịǃƽǦǃƽấǉǦđịǃƽǦǅƽảƾǦǃƽƶǃƽǦǁƙǃ!",
    ["前往滹沱河畔"] = "ǥƾếǃǦǋềǦƷờǦǈƇǃƼǦƣƇǦĐƐ",
    ["中渡桥？"] = "ǥǇǊǃƼǦĐộǦƦƾềǊ?",
    ["姐姐好帅的刀！"] = "ǥỷǦǉỷǦƽảǄǦǈǄƑƾǦđƶǄ!",
    ["等打完了虏人 咱俩比比"] = "ĐợƾǦđƑǃƽǦǍǄǃƼǦǆǊƁǃǦƼƾặƸ,ǦƽƶƾǦǉƶǦǈǄǦǉƐƾǦǂộǉǦƸƽƕǉ",
    ["大家当心"] = "ƨọƾǦǃƼườƾǦƸẩǃǦǉƽậǃ",
    ["赵大叔"] = "ǥǇƾệǊǦđạƾǦǉƽƕƸ",
    ["一换三"] = "ƨộǉǦđổƾǦƷƶ",
    ["这买卖值"] = "ƱụǦǁƐǂǦăǃǦǃƐǓǦđƑǃƼ",
    ["杀出重围"] = "ƮƑǉǦǍǊấǉǦǉǇọǃƼǦǋƁǓ",
    ["虏狗 来啊"] = "ƧũǦƸƽƚǦƼƾặƸ,ǦǉớƾǦđƁǓ",
    ["与虏将霞末一战"] = "ƨộǉǦǉǇậǃǦƸƽƾếǃǦǋớƾǦǁỗǦǉướǃƼǦƣƐǦƨạǉ",
    ["却矢和翩反"] = "ƦƽướƸǦǥƽỉǦǋƐǦƫƽƾƙǃǦƫƽảǃ",
    ["与虏将萧翰一战"] = "ƨộǉǦǉǇậǃǦƸƽƾếǃǦǋớƾǦǁỗǦǉướǃƼǦǥƾƙǊǦƣƐǃ",
    ["中原人"] = "ƩƼườƾǦǥǇǊǃƼǦƩƼǊǓƙǃ",
    ["真的很喜欢送死啊"] = "ƬǊảǦǃƽƾƙǃǦǁƐǦǇấǉǦǉƽƓƸƽǦǃộǅǦǂạǃƼǦǃƽƶ",
    ["萧翰"] = "ǥƾƙǊǦƣƐǃ",
    ["王清已死"] = "ƱươǃƼǦǥƽƶǃƽǦđƃǦǉử",
    ["大契丹国"] = "ĐạƾǦƦƽƾếǉǦĐƶǃǦƬǊốƸ",
    ["胜 胜 胜 胜"] = "ǥƽắǃƼǦǥƽắǃƼǦǥƽắǃƼǦǥƽắǃƼ",
    ["你的剑"] = "ƦƾếǂǦƸủƶǦǃƼươƾ",
    ["很快"] = "ƭấǉǦǃƽƶǃƽ",
    ["但你们的朝廷"] = "ƩƽưǃƼǦǉǇƾềǊǦđƔǃƽǦƸủƶǦƸƑƸǦǃƼươƾ",
    ["锈了"] = "ĐƃǦǇỉǦǈƗǉǦǇồƾ",
    ["你杀得了我"] = "ƩƼươƾǦƼƾếǉǦđượƸǦǉƶ",
    ["却救不了他们"] = "ƩƽưǃƼǦǁạƾǦƸƽẳǃƼǦƸứǊǦǃổƾǦƷọǃǦƽọ",
    ["战至最后一刻"] = "ƞƽƾếǃǦđếǃǦǀƽắƸǦƸǊốƾǦƸƖǃƼ",
    ["让花朵飞到最后一人身侧"] = "ĐểǦđƚƶǦƽǄƶǦƷƶǓǦđếǃǦƷƙǃǦƸạǃƽǦǃƼườƾǦƸǊốƾǦƸƖǃƼ",
    ["阿沱！你怎么样了？"] = "ƜǦĐƐ!ǦƩƼươƾǦǈƶǄǦǇồƾ?",
    ["怎样？等死的样？嗤，朝廷不管，大侠你又能救多少人呢？"] = "ƮƶǄǦƽả?ǦƞƑƾǦǤạǃƼǦƸƽờǦƸƽếǉǦƸƽứǦǈƶǄ?ǦƳƖǓ,ǦǉǇƾềǊǦđƔǃƽǦđƃǦǂặƸǦǀệ,ǦđạƾǦƽƾệǅǦǃƼươƾǦǁạƾǦƸƚǦǉƽểǦƸứǊǦđượƸǦƷƶǄǦǃƽƾƙǊǦǃƼườƾ?",
    ["能救几个是几个。"] = "ƞứǊǦđượƸǦƶƾǦƽƶǓǦǃƼườƾǦđƚ.",
    ["哈哈，你救得快，还是虏人杀得快？"] = "ƣƶǦƽƶ,ǦǃƼươƾǦƸứǊǦǃƽƶǃƽ,ǦƽƶǓǦǁƐǦǁũǦƼƾặƸǦƼƾếǉǦǃƽƶǃƽ?",
    ["这些剩下的，都是走不远的人。你运气好，手脚都在，倒不如自个儿走，也算救了一人。"] = "ƩƽữǃƼǦǃƼườƾǦƸƛǃǦǁạƾǦǃƐǓǦđềǊǦǁƐǦǀẻǦǀƽƇǃƼǦđƾǦǍƶǦđượƸ.ǦƩƼươƾǦǋậǃǦǀƽƓǦǉốǉ,ǦǉƶǓǦƸƽƁǃǦƸƛǃǦǃƼǊǓƙǃ,ǦƸƽƾǦƷằǃƼǦǉựǦǂƔǃƽǦǇờƾǦđƾ,ǦƸũǃƼǦƸǄƾǦǃƽưǦǁƐǦƸứǊǦđượƸǦǂộǉǦǃƼườƾ.",
    ["不，我还能再战几场，咳咳，他们……也都没有走。"] = "ƦƽƇǃƼ,ǦǉƶǦƸƛǃǦƸƚǦǉƽểǦƸƽƾếǃǦǉƽƙǂǦǋƐƾǦǉǇậǃǦǃữƶ,ǦǀƽụǦǀƽụ...ǦƷọǃǦƽọ...ǦƸũǃƼǦđềǊǦƸƽưƶǦđƾ.",
    ["他们死了，好多人死了！伤的、病的、老的、幼的、倒霉的、还有你们这些送死的！死了就什么都没了！"] = "ƣọǦƸƽếǉǦǇồƾ,ǦǇấǉǦǃƽƾềǊǦǃƼườƾǦƸƽếǉǦǇồƾ!ǦƦẻǦƷịǦǉƽươǃƼ,ǦǃƼườƾǦƷệǃƽǦǉậǉ,ǦǃƼườƾǦƼƾƐ,ǦǉǇẻǦǃƽỏ,ǦǀẻǦǋậǃǦǇủƾ,ǦǋƐǦƸảǦǁũǦǃộǅǦǂạǃƼǦƸƑƸǦǃƼươƾǦǃữƶ!ǦƞƽếǉǦǇồƾǦǁƐǦƸƽẳǃƼǦƸƛǃǦƼƔǦƽếǉ!",
    ["史书、史书会记得虏人挥戈南下，记得杜狗临阵怯敌……但断断不会记得他们，也不会记得你们……"] = "ƮửǦǈƑƸƽ,ǦǈửǦǈƑƸƽǦǈẽǦƼƽƾǦǁạƾǦǁũǦƼƾặƸǦǋǊǃƼǦƼƾƑǄǦǃƶǂǦƽạ,ǦǃƽớǦǀỹǦƸǄǃǦƸƽƚǦƽọǦĐỗǦǁƁǂǦǉǇậǃǦǀƽƾếǅǦǃƽượƸ...ǦǃƽưǃƼǦǉǊǓệǉǦđốƾǦǈẽǦǀƽƇǃƼǦǃƽớǦǀỹǦƽọ,ǦƸũǃƼǦƸƽẳǃƼǦǃƽớǦǀỹǦƸƑƸǦǃƼươƾ...",
    ["敢问中渡桥怎么走？"] = "ǝƑǂǦƽỏƾǦǥǇǊǃƼǦĐộǦƦƾềǊǦđƾǦǉƽếǦǃƐǄ?",
    ["周月恒"] = "ƞƽǊǦƩƼǊǓệǉǦƣằǃƼ",
    ["中渡桥……已经败了……杜重威投降了……"] = "ǥǇǊǃƼǦĐộǦƦƾềǊ...ǦƷạƾǦǇồƾ...ǦĐỗǦǥǇọǃƼǦǕǓǦđầǊǦƽƐǃƼǦǇồƾ...",
    ["多谢，保重！"] = "ĐƶǦǉạ,ǦƷảǄǦǉǇọǃƼ!",
    ["南下，邢州、洺州……虏人去哪，我便杀到哪儿！总有下个战场！"] = "ƩƶǂǦƽạ,ǦƣƔǃƽǦƞƽƁǊ,ǦƨƾǃƽǦƞƽƁǊ...ǦƼƾặƸǦđƾǦđƁǊ,ǦǉƶǦǁƾềǃǦǈƑǉǦđếǃǦđƚ!ǦƧǊƇǃǦƸƚǦƸƽƾếǃǦǉǇườǃƼǦǉƾếǅǦǉƽƺǄ!",
    ["何须劳烦千秋笔，不记得便不记得罢。"] = "ƣƐǦǉấǉǦǁƶǄǦǅƽƾềǃǦǃƼƛƾǦƷƕǉǦǃƼƽƔǃǦǉƽǊ,ǦǀƽƇǃƼǦǃƽớǦǉƽƔǦǉƽƇƾǦǋậǓ.",
    ["图什么……你们图什么呢……"] = "ƨưǊǦƸầǊǦđƾềǊǦƼƔ...ǦƸƑƸǦǃƼươƾǦǇốǉǦƸǊộƸǦǂưǊǦƸầǊǦđƾềǊǦƼƔǦƸƽứ...",
    ["阿沱, 你看，草会发芽，太阳也会升起来的。"] = "ƜǦĐƐ,ǦǃƽƔǃǦǀƔƶ,ǦƸỏǦǈẽǦǃảǓǦǂầǂ,ǦǂặǉǦǉǇờƾǦƸũǃƼǦǈẽǦǁạƾǦǂọƸǦǁƙǃ.",
    ["呃，呜呜……啊啊啊……！"] = "Ư...ǦƽǊǦƽǊ...ǦƶǦƶǦƶ...!",
    ["无名客，侠者无名……我知道了。"] = "ƱƇǦǝƶǃƽǦƦƽƑƸƽ,ǦƽƾệǅǦƼƾảǦǋƇǦǤƶǃƽ...ǦǉƶǦƽƾểǊǦǇồƾ.",
    ["新的名字还未到来，旧的名字铭刻在上。"] = "ǥƙǃǦǂớƾǦƸƽưƶǦǉớƾ,ǦǉƙǃǦƸũǦǀƽắƸǦƼƽƾ.",
    ["新的名字总会到来，旧的名字亦不会忘。"] = "ǥƙǃǦǂớƾǦǇồƾǦǈẽǦđếǃ,ǦǉƙǃǦƸũǦƸũǃƼǦƸƽẳǃƼǦǆǊƙǃ.",
    ["侠行无言，收集到滹沱河畔群侠姓名，可将其刻至碑上。"] = "ƣƾệǅǦƽƐǃƽǦǋƇǦǃƼƇǃ,ǦǉƽǊǦǉƽậǅǦđượƸǦƽọǦǉƙǃǦǆǊầǃǦƽƾệǅǦƷƙǃǦƷờǦǈƇǃƼǦƣƇǦĐƐ,ǦƸƚǦǉƽểǦǀƽắƸǦǁƙǃǦǉǇƙǃǦƷƾƶ.",
    ["小福车不吃，小福车活不了。"] = "ǥƾểǊǦƫƽƕƸǦƳƶǦǀƽƇǃƼǦăǃ,ǦǥƾểǊǦƫƽƕƸǦƳƶǦǀƽƇǃƼǦǈốǃƼǦǃổƾ.",
    ["活不了……活不了了……呜……"] = "ƦƽƇǃƼǦǈốǃƼǦǃổƾ...ǦǀƽƇǃƼǦǈốǃƼǦǃổƾǦǃữƶǦǇồƾ...ǦƽǊ...",
    ["小友想是见过无名客了。"] = "ǥƾểǊǦƽữǊǦƸƽắƸǦǁƐǦđƃǦƼặǅǦǆǊƶǦƱƇǦǝƶǃƽǦƦƽƑƸƽǦǇồƾ.",
    ["嗯，这一路有好多好多的无名客。"] = "ƀǃ,ǦǉǇƙǃǦđườǃƼǦǃƐǓǦƸƚǦǇấǉǦǃƽƾềǊ,ǦǇấǉǦǃƽƾềǊǦƱƇǦǝƶǃƽǦƦƽƑƸƽ.",
    ["如今，你也成了其中一人。当年，我幸为无名客所救，只跛了脚，没烂进泥里……"] = "ƩƶǓǦǃƼươƾǦƸũǃƼǦđƃǦǉǇởǦǉƽƐǃƽǦǂộǉǦǃƼườƾǦǉǇǄǃƼǦǈốǦƽọ.ǦƩăǂǦđƚ,ǦǉƶǦǂƶǓǦǂắǃǦđượƸǦƱƇǦǝƶǃƽǦƦƽƑƸƽǦƸứǊǦƼƾƕǅ,ǦƸƽỉǦǁƐǦǉƽọǉǦƸƽƁǃ,ǦƸƽứǦǀƽƇǃƼǦƷịǦǋƖƾǦǉƽƁǓǦǉǇǄǃƼǦƷƖǃǦđấǉ...",
    ["无意千秋之人，最应被千秋所记。"] = "ƩƼườƾǦǀƽƇǃƼǦǂƐǃƼǦǃƼƽƔǃǦǉƽǊ,ǦǁạƾǦƸƐǃƼǦđƑǃƼǦđượƸǦǃƼƽƔǃǦǉƽǊǦƼƽƾǦǃƽớ.",
    ["滹沱浪涌濯肝胆……"] = "ƣƇǦĐƐǦǈƚǃƼǦƸǊộǃǦƼộǉǦƼƶǃǦđƐƾ...",
    ["“滹沱浪涌濯肝胆，忠魂烈骨千秋垂……”"] = "\"ƣƇǦĐƐǦǈƚǃƼǦƸǊộǃǦƼộǉǦƼƶǃǦđƐƾ,ǦǉǇǊǃƼǦƽồǃǦǁƾệǉǦƸốǉǦǋạǃǦǉƽǊǦǈǄƾ...\"",
    ["长风去，万里遥遥送客归……"] = "ǥǇườǃƼǦǅƽǄǃƼǦǉƾễǃ,ǦǋạǃǦǤặǂǦǍƶǦǍăǂǦđưƶǦǀƽƑƸƽǦǋề...",
    ["你可愿，继续无名客的故事？"] = "ƩƼươƾǦƸƚǦǃƼǊǓệǃǦƈǦǉƾếǅǦǃốƾǦƸƁǊǦƸƽǊǓệǃǦƸủƶǦƱƇǦǝƶǃƽǦƦƽƑƸƽ?",
    ["曾有无名客说， he vô sở图，只愿春草又绿，旭日东升。"] = "ǥừǃƼǦƸƚǦƱƇǦǝƶǃƽǦƦƽƑƸƽǦǃƚƾǦǇằǃƼ,ǦƽắǃǦǀƽƇǃƼǦǂưǊǦƸầǊǦƼƔ,ǦƸƽỉǦǃƼǊǓệǃǦƸỏǦǍǊƁǃǦǁạƾǦǍƶǃƽ,ǦǉƽƑƾǦǤươǃƼǦǁƚǦǇạǃƼ.",
    ["英雄所言所想相若，将军也说过，此树有朝一日……"] = "ƜǃƽǦƽƖǃƼǦǈởǦǃƼƇǃǦǈởǦǉưởǃƼǦǉươǃƼǦǃƽượƸ,ǦǉướǃƼǦǆǊƁǃǦƸũǃƼǦǉừǃƼǦǃƚƾ,ǦƸƑƾǦƸƁǓǦǃƐǓǦƸƚǦǂộǉǦǃƼƐǓ...",
    ["英雄……将军……"] = "ƜǃƽǦƽƖǃƼ...ǦǉướǃƼǦǆǊƁǃ...",
    ["说到英雄，江叔屋子里供奉的牌位、还有祠里的将军像……"] = "ƩƽắƸǦđếǃǦƶǃƽǦƽƖǃƼ,ǦƷƐƾǦǋịǦǉƽờǦǉǇǄǃƼǦǃƽƐǦƢƾƶǃƼǦǉƽƕƸ,ǦǋƐǦƸảǦǉượǃƼǦǉướǃƼǦǆǊƁǃǦǉǇǄǃƼǦǉừǦđườǃƼ...",
    ["……是王清将军。"] = "...ǦƧƐǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃ.",
    ["该回去看看了。"] = "ĐƃǦđếǃǦǁƕƸǦǃƙǃǦǆǊƶǓǦǁạƾǦǍƺǂǦǇồƾ.",
    ["之前江叔总让我来磕头，却从不多说什么。"] = "ǥǇướƸǦđƁǓǦƢƾƶǃƼǦǉƽƕƸǦǁǊƇǃǦƷảǄǦǉƶǦđếǃǦǤậǅǦđầǊ,ǦǃƽưǃƼǦƸƽưƶǦǉừǃƼǦǃƚƾǦƼƔǦǃƽƾềǊ.",
    ["以后，我也都会来的。"] = "ƮƶǊǦǃƐǓ,ǦǉƶǦƸũǃƼǦǈẽǦđềǊǦǉớƾǦƸả.",
    ["我们未曾见过，却有幸，共行了一程。"] = "ƞƽƕǃƼǦǉƶǦƸƽưƶǦǉừǃƼǦƼặǅǦǂặǉ,ǦǃƽưǃƼǦǉƽậǉǦǋƾǃƽǦƽạǃƽǦđượƸǦđồǃƼǦƽƐǃƽǦǂộǉǦǆǊƃǃƼ.",
    ["此番走走停停，算来，离家也快一年了……"] = "ƞƽǊǓếǃǦǃƐǓǦđƾǦđƾǦǤừǃƼǦǤừǃƼ,ǦǉƓǃƽǦǇƶǦǇờƾǦǃƽƐǦƸũǃƼǦƼầǃǦǂộǉǦǃăǂǦǇồƾ...",
    ["之前怎么从未注意到这里？"] = "ǥǇướƸǦđƁǓǦǈƶǄǦƸƽưƶǦǉừǃƼǦǁưǊǦƈǦđếǃǦǃơƾǦǃƐǓǦǃƽỉ?",
    ["这地窟不知是何人所掘，看来也有些年头了……"] = "ĐịƶǦǀƽǊấǉǦǃƐǓǦǀƽƇǃƼǦƷƾếǉǦǤǄǦƶƾǦđƐǄ,ǦǍƺǂǦǇƶǦƸũǃƼǦđƃǦƸƚǦǉừǦǁƁǊǦǇồƾ...",
    ["石柱，还有砖画……？有风蚀痕迹，不似当下所刻。"] = "ǥƽạƸƽǦǉǇụ,ǦƸƛǃǦƸƚǦƽọƶǦƼạƸƽ...?ǦƞƚǦǋếǉǦǉƓƸƽǦǅƽǄǃƼǦƽƚƶ,ǦǀƽƇǃƼǦƼƾốǃƼǦǃƽưǦǂớƾǦǀƽắƸǦƼầǃǦđƁǓ.",
    ["这是——！！"] = "ĐƁǓǦǁƐǦ—!!",
    ["耘丘，栾城，中渡桥，封龙山……天福十一年，这里的人都在挣明日，盼春天。"] = "ƱƁǃǦƦƽƁǊ,ǦƧǄƶǃǦǥƽƐǃƽ,ǦǥǇǊǃƼǦĐộǦƦƾềǊ,ǦƫƽǄǃƼǦƧǄǃƼǦƮơǃ...ǦƩăǂǦǥƽƾƙǃǦƫƽƕƸǦǉƽứǦǂườƾǦǂộǉ,ǦǃƼườƾǦởǦđƁǓǦđềǊǦđƶǃƼǦǉǇƶǃƽǦđấǊǦǋƔǦǃƼƐǓǦǂƶƾ,ǦǂǄǃƼǦǃƼƚǃƼǦǂƖƶǦǍǊƁǃ.",
    ["后来，春天确实来了——"] = "ƮƶǊǦđƚ,ǦǂƖƶǦǍǊƁǃǦǆǊảǦǉƽựƸǦđƃǦđếǃǦ—",
    ["大家冷静！我已写信给南边诸镇转运使，请他们开仓赈济！"] = "ƨọƾǦǃƼườƾǦƷƔǃƽǦǉĩǃƽ!ǦǥƶǦđƃǦǋƾếǉǦǉƽưǦƸƽǄǦƞƽǊǓểǃǦǋậǃǦǈứǦƸƑƸǦǉǇấǃǦǅƽƓƶǦƩƶǂ,ǦǉƽỉǃƽǦƷọǃǦƽọǦǂởǦǀƽǄǦƸƽẩǃǦǉế!",
    ["没粮了！大伙儿快散了吧！"] = "ƣếǉǦǁươǃƼǦǇồƾ!ǦƝƐǦƸǄǃǦǂƶǊǦƼƾảƾǦǉƑǃǦđƾǦǉƽƇƾ!",
    ["虏人眼看就要打过来了，大人为何还不走？"] = "ƢƾặƸǦđƃǦƸậǃǦǀềǦǇồƾ,ǦđạƾǦǃƽƁǃǦǋƔǦǈƶǄǦǋẫǃǦƸƽưƶǦđƾ?",
    ["桥失守了，可这仗还远远没有结束。"] = "ƞầǊǦđƃǦǉƽấǉǦǉƽủ,ǦǃƽưǃƼǦǉǇậǃǦƸƽƾếǃǦǃƐǓǦǋẫǃǦƸƛǃǦǁƁǊǦǂớƾǦǀếǉǦǉƽƕƸ.",
    ["战败的消息刚传到这，仓里就乱了起来。逃跑的，抢粮的，大打出手的……没过多久这儿就空了。"] = "ǥƾǃǦƷạƾǦǉǇậǃǦǋừƶǦǉǇǊǓềǃǦǉớƾǦđƁǓ,ǦǉǇǄǃƼǦǀƽǄǦđƃǦǁǄạǃǦƸảǦǁƙǃ.ǦƦẻǦƷỏǦƸƽạǓ,ǦǃƼườƾǦƸướǅǦǁươǃƼ,ǦǀẻǦđƑǃƽǦǃƽƶǊǦǉƕƾǦƷụƾ...ǦǀƽƇǃƼǦƷƶǄǦǁƁǊǦǈƶǊǦǃơƾǦǃƐǓǦđƃǦǉǇốǃƼǦǀƽƇǃƼ.",
    ["紧接着来了逃难的人，一开始，仓里多少还剩点余粮分给他们。"] = "ƩƼƶǓǦǈƶǊǦđƚǦǁƐǦǤƁǃǦǉịǦǃạǃǦǀƗǄǦđếǃ,ǦǁƕƸǦđầǊǦǉǇǄǃƼǦǀƽǄǦǋẫǃǦƸƛǃǦǈƚǉǦǁạƾǦƸƽƕǉǦǁươǃƼǦǉƽảǄǦƸƽƾƶǦƸƽǄǦƽọ.",
    ["可现在粮没了，后头的人却越来越多，都惦念着这一点救命的谷子。"] = "ƩƽưǃƼǦƼƾờǦǁươǃƼǦđƃǦƽếǉ,ǦǃƼườƾǦǅƽƓƶǦǈƶǊǦǁạƾǦƸƐǃƼǦǁƕƸǦƸƐǃƼǦđƇǃƼ,ǦƶƾǦƸũǃƼǦǂǄǃƼǦǃƼƚǃƼǦƸƽƕǉǦǉƽƚƸǦƸứǊǦǂạǃƼǦǃƐǓ.",
    ["有我俩在这，局面尚且能控制得住。多守一日，也许就能多救一人. "] = "ƞƚǦƽƶƾǦǉƶǦởǦđƁǓ,ǦƸụƸǦǤƾệǃǦǋẫǃǦƸƛǃǦƸƚǦǉƽểǦǀƽốǃƼǦƸƽếǦđượƸ.ǦƢƾữǦǉƽƙǂǦǂộǉǦǃƼƐǓ,ǦƸƚǦǁẽǦǈẽǦƸứǊǦǉƽƙǂǦđượƸǦǂộǉǦǃƼườƾ.",
    ["能跑多远就跑多远吧，指不定虏人哪天就打过去了。"] = "ƞƽạǓǦđượƸǦƷƶǄǦǍƶǦǉƽƔǦƸứǦƸƽạǓǦđƾ,ǦƸƽẳǃƼǦƷƾếǉǦǆǊƁǃǦƼƾặƸǦǃƼƐǓǦǃƐǄǦǈẽǦđƑǃƽǦǉớƾǦđƁǊ.",
    ["咱逃还来不及，咋还有人想往北边跑呢？"] = "ƞƽƕǃƼǦǉƶǦƸƽạǓǦƸƛǃǦǀƽƇǃƼǦǀịǅ,ǦǈƶǄǦǋẫǃǦƸƚǦǃƼườƾǦǂǊốǃǦƸƽạǓǦǋềǦƽướǃƼǦƝắƸǦǃƽỉ?",
    ["可不嘛。沿路见着不少人，和他们说啥也不逃，犟得很。"] = "ƞƽứǦƸƛǃǦƼƔǦǃữƶ.ǦǝọƸǦđườǃƼǦǉƽấǓǦǀƽƇǃƼǦƓǉǦǃƼườƾ,ǦǃƚƾǦǉƽếǦǃƐǄǦƽọǦƸũǃƼǦǀƽƇǃƼǦƸƽịǊǦƸƽạǓ,ǦƷướǃƼǦƷỉǃƽǦǁắǂ.",
    ["你说这会在前头呆着有什么用？就凭他们几个，能把桥夺回来不成？"] = "ƩƼươƾǦǃƚƾǦǍƺǂǦƼƾờǦởǦǁạƾǦǅƽƓƶǦǉǇướƸǦǉƽƔǦƸƚǦƓƸƽǦƼƔ?ǦƞƽỉǦǤựƶǦǋƐǄǦǂấǓǦǃƼườƾǦƷọǃǦƽọǦǂƐǦđƛƾǦđǄạǉǦǁạƾǦƸầǊǦđượƸǦƸƽắƸ?",
    ["说什么混账话呢？！"] = "ƩƚƾǦǁờƾǦƽỗǃǦƸƽướǃƼǦƼƔǦǉƽếǦƽả?!",
    ["谁不想活着？谁不想跟你们似的，坐在这儿动嘴皮子？"] = "ƜƾǦǂƐǦƸƽẳǃƼǦǂǊốǃǦǈốǃƼ?ǦƜƾǦǂƐǦǀƽƇǃƼǦǂǊốǃǦƼƾốǃƼǦƸƑƸǦǃƼườƾ,ǦǃƼồƾǦđƁǓǦǂƐǦǀƽǊƶǦǂƇƾǦǂƕƶǦǂƗǅ?",
    ["外头的侠客，是为了替咱乡里老小报仇. 还有些将士、百姓，是为了拖住那些虏人，给咱们多争来些逃跑的时间！"] = "ƩƽữǃƼǦƽƾệǅǦǀƽƑƸƽǦƷƙǃǦǃƼǄƐƾǦǀƾƶǦǁƐǦđểǦƷƑǄǦǉƽƖǦƸƽǄǦƼƾƐǦǉǇẻǦǉǇǄǃƼǦǁƐǃƼǦǉƶ.ǦƞƛǃǦƸƚǦǃƽữǃƼǦǉướǃƼǦǈĩ,ǦƷƑƸƽǦǉƓǃƽǦđƶǃƼǦƸầǂǦƸƽƁǃǦǁũǦƼƾặƸ,ǦđểǦǉǇƶǃƽǦǉƽủǦǉƽƙǂǦƸƽƕǉǦǉƽờƾǦƼƾƶǃǦƸƽạǓǦǉǇốǃǦƸƽǄǦƸƽƕǃƼǦǉƶ!",
    ["这都是救命的恩情，咱一辈子都得记着！"] = "ĐƁǓǦđềǊǦǁƐǦƁǃǦǉƔǃƽǦƸứǊǦǂạǃƼ,ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦƼƽƾǦǃƽớǦƸảǦđờƾ!",
    ["孩子，你一个人走过来的吗？"] = "ƣƐƾǦǉử,ǦƸǄǃǦđƾǦǉớƾǦđƁǓǦǂộǉǦǂƔǃƽǦǈƶǄ?",
    ["何桐"] = "ƣƐǦĐồǃƼ",
    ["记不记得有什么亲戚？或者认识的邻居？"] = "ƞƚǦǃƽớǦǁƐǦƸƚǦǃƼườƾǦǉƽƁǃǦǃƐǄǦǀƽƇǃƼ?ǦƣǄặƸǦǁƐǦƽƐǃƼǦǍƚǂǦǆǊƺǃǦƷƾếǉ?",
    ["那和姐姐说说，你叫什么名字？"] = "ƱậǓǦǃƚƾǦǋớƾǦǉỷǦǉỷǦǍƺǂ,ǦƸǄǃǦǉƙǃǦǁƐǦƼƔ?",
    ["安安……安安莫看……窗外头……"] = "ƜǃǦƜǃ...ǦƜǃǦƜǃǦđừǃƼǦǃƽƔǃ...ǦǇƶǦǃƼǄƐƾǦƸửƶǦǈổ...",
    ["安安……那姐姐叫你安安好不好？"] = "ƜǃǦƜǃ...ǦƱậǓǦǉỷǦǉỷǦƼọƾǦƸǄǃǦǁƐǦƜǃǦƜǃǦƸƚǦđượƸǦǀƽƇǃƼ?",
    ["这孩子被吓着了，精神头不太好，好在脸色看着还行。"] = "ĐứƶǦǃƽỏǦǃƐǓǦƷịǦǀƾǃƽǦǈợǦǇồƾ,ǦǉƾǃƽǦǉƽầǃǦǀƽƇǃƼǦđượƸǦǉốǉǦǁắǂ,ǦǂƶǓǦǂƐǦǈắƸǦǂặǉǦǉǇƇǃƼǦǋẫǃǦổǃ.",
    ["大伯，安安就有劳您路上多照看着些。"] = "ĐạƾǦƷƑ,ǦƜǃǦƜǃǦǉǇƇǃƼǦƸậǓǦƸảǦǋƐǄǦƷƑƸǦƸƽăǂǦǈƚƸǦǉǇƙǃǦđườǃƼǦđƾ.",
    ["一定，一定。来，安安，跟伯伯来。"] = "ƩƽấǉǦđịǃƽ,ǦǃƽấǉǦđịǃƽ.ǦĐếǃǦđƁǓ,ǦƜǃǦƜǃ,ǦđƾǦǉƽƺǄǦƷƑǦƷƑǦǃƐǄ.",
    ["安安，你……还好吗？"] = "ƜǃǦƜǃ,ǦƸǄǃ...ǦǋẫǃǦổǃǦƸƽứ?",
    ["姐姐说……要往南边走……"] = "ǥỷǦǉỷǦǃƚƾ...ǦǅƽảƾǦđƾǦǋềǦǅƽƓƶǦƩƶǂ...",
    ["去……听不到雷声的地方，去有水的地方……"] = "ĐếǃǦǃơƾ...ǦǀƽƇǃƼǦǃƼƽƺǦǉƽấǓǦǉƾếǃƼǦǈấǂ,ǦđếǃǦǃơƾǦƸƚǦǃướƸ...",
    ["姐姐和阿爹阿娘……会坐着小船……来找 An An ……"] = "ǥỷǦǉỷǦƸƖǃƼǦƜǦƸƽƶǦƜǦǃươǃƼ...ǦǈẽǦǃƼồƾǦǉƽǊǓềǃǦǃƽỏ...ǦđếǃǦǉƔǂǦƜǃǦƜǃ...",
    ["大侠，你也要保重……再见了……"] = "ĐạƾǦƽƾệǅ,ǦǃƼƐƾǦƸũǃƼǦǅƽảƾǦƷảǄǦǉǇọǃƼ...ǦǉạǂǦƷƾệǉ...",
    ["游侠，从前线下来的吧？"] = "ǝǊǦƽƾệǅ,ǦǉừǦǉƾềǃǦǉǊǓếǃǦǍǊốǃƼǦǅƽảƾǦǀƽƇǃƼ?",
    ["邓义"] = "ĐặǃƼǦƩƼƽĩƶ",
    ["告诉这小子，中渡桥那儿还剩点什么？"] = "ƩƚƾǦƸƽǄǦǉƾểǊǦǉửǦǃƐǓǦƷƾếǉ,ǦởǦǥǇǊǃƼǦĐộǦƦƾềǊǦƸƛǃǦǈƚǉǦǁạƾǦǃƽữǃƼǦƼƔ?",
    ["那咋了？俺加入燕北盟，不是为了缩在这后头——"] = "ǥƽƔǦđƃǦǈƶǄ?ǦǥƶǦƼƾƶǦǃƽậǅǦƴếǃǦƝắƸǦƨƾǃƽǦǀƽƇǃƼǦǅƽảƾǦđểǦƸǄǦǇụǉǦởǦǅƽƓƶǦǈƶǊǦǃƐǓǦ—",
    ["林烽"] = "ƧƁǂǦƫƽǄǃƼ",
    ["好，你有骨气，你不怕死，可你问问这些的百姓怕不怕？"] = "ĐượƸ,ǦǃƼươƾǦƸƚǦƸốǉǦƸƑƸƽ,ǦǃƼươƾǦǀƽƇǃƼǦǈợǦƸƽếǉ,ǦǃƽưǃƼǦǃƼươƾǦƽƃǓǦƽỏƾǦǍƺǂǦƷƑƸƽǦǉƓǃƽǦởǦđƁǓǦƸƚǦǈợǦǀƽƇǃƼ?",
    ["先把这些百姓安顿好，至于杀虏人的事，咱们得好好盘算。"] = "ǥǇướƸǦǉƾƙǃǦƽƃǓǦƶǃǦđốǃǦƸƽǄǦǃƽữǃƼǦƷƑƸƽǦǉƓǃƽǦǃƐǓǦđƃ,ǦƸƛǃǦƸƽǊǓệǃǦƼƾếǉǦƼƾặƸ,ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦǉƓǃƽǦǉǄƑǃǦǀỹǦǁưỡǃƼ.",
    ["这仗还有得打呢，燕北盟，不能再失去更多的人了。"] = "ǥǇậǃǦƸƽƾếǃǦǃƐǓǦƸƛǃǦǤƐƾ,ǦƴếǃǦƝắƸǦƨƾǃƽǦǀƽƇǃƼǦǉƽểǦđểǦǂấǉǦǉƽƙǂǦǃƼườƾǦǃữƶ.",
    ["别杀我！别杀我！我知道！附近有个山洞，很隐蔽，他们肯定藏在那儿！"] = "ĐừǃƼǦƼƾếǉǦǉƶ!ǦĐừǃƼǦƼƾếǉǦǉƶ!ǦǥƶǦƷƾếǉ!ǦƢầǃǦđƁǓǦƸƚǦǂộǉǦǈơǃǦđộǃƼǦǇấǉǦǀƓǃǦđƑǄ,ǦƷọǃǦƽọǦƸƽắƸǦƸƽắǃǦǉǇốǃǦởǦđƚ!",
    ["阿淼"] = "ƜǦƨƾểǊ",
    ["要是骗了我，我就亲自来把你的舌头割下来喂狼！"] = "ƩếǊǦǤƑǂǦǁừƶǦǉƶ,ǦǉƶǦǈẽǦđƓƸƽǦǉƽƁǃǦƸắǉǦǁưỡƾǦǃƼươƾǦđƺǂǦƸƽǄǦǈƚƾǦăǃ!",
    ["萧铁奴"] = "ǥƾƙǊǦǥƽƾếǉǦƩƇ",
    ["是真的！那帮人平日里装得清高！怕死的很！肯定就躲在那儿！"] = "ƧƐǦǉƽậǉǦđƚ!ǦĐƑǂǦǃƼườƾǦđƚǦǃƼƐǓǦǉƽườǃƼǦƼƾảǦǋờǦǉƽƶǃƽǦƸƶǄ!ǦƮợǦƸƽếǉǦǁắǂ!ǦƞƽắƸǦƸƽắǃǦǁƐǦǉǇốǃǦởǦđƚǦǇồƾ!",
    ["哼，这些汉人的骨头，果然一敲就碎，滚吧。"] = "ƣừ,ǦǍươǃƼǦƸốǉǦƸủƶǦǁũǦǃƼườƾǦƣƑǃǦǃƐǓǦǆǊảǦǃƽƾƙǃǦƼƅǦǂộǉǦƸƑƾǦǁƐǦǉƶǃǦǃƑǉ,ǦƸƕǉǦđƾ.",
    ["斡朵"] = "ƪƑǉǦĐƚƶ",
    ["别怪我……别怪我！你们逼我的！为几块桂花糕……就说我是贼！还要把我赶出来！"] = "ĐừǃƼǦǉǇƑƸƽǦǉƶ...ǦđừǃƼǦǉǇƑƸƽǦǉƶ!ǦƧƐǦƸƑƸǦǃƼườƾǦƗǅǦǉƶ!ǦƞƽỉǦǋƔǦǂấǓǦǂƾếǃƼǦƷƑǃƽǦǆǊếǦƽǄƶ...ǦǂƐǦǃƚƾǦǉƶǦǁƐǦǉặƸ!ǦƞƛǃǦǂǊốǃǦđǊổƾǦǉƶǦđƾ!",
    ["我……我这只是“以直报怨”，对！我只是为了活着……活着有什么错？"] = "ǥƶ...ǦǉƶǦđƁǓǦƸƽỉǦǁƐǦ\"ǤƖǃƼǦǈựǦǃƼƶǓǦǉƽẳǃƼǦƷƑǄǦđƑǅǦǄƑǃǦǉƽƖ\",ǦđƕǃƼ!ǦǥƶǦƸƽỉǦǁƐǦǋƔǦǂǊốǃǦǈốǃƼ...ǦǈốǃƼǦǉƽƔǦƸƚǦƼƔǦǈƶƾ?",
    ["他们杀了他……他……死了……"] = "ƣọǦƼƾếǉǦƇǃƼǦấǓǦǇồƾ...ǦƇǃƼǦấǓ...ǦƸƽếǉǦǇồƾ...",
    ["你是……谁？"] = "ƩƼươƾǦǁƐ...Ǧƶƾ?",
    ["这些书……我说了，不能拿去当钱花！咳咳，霞丫头……唉……还有那钱……"] = "ƩƽữǃƼǦƸǊốǃǦǈƑƸƽǦǃƐǓ...ǦǉƶǦđƃǦǃƚƾǦǇồƾ,ǦǀƽƇǃƼǦđượƸǦđƺǂǦđƾǦđổƾǦǉƾềǃ!ǦƦƽụǦǀƽụ,ǦƣƐǦǃƽƶǦđầǊ...Ǧƶƾ...ǦƸƛǃǦƸảǦǂƚǃǦǉƾềǃǦđƚǦǃữƶ...",
    ["为什么不能？阿公，你的命重要，还是书重要？再说那契丹钱……本就是她们欠咱们的，难道还用不得？"] = "ǥạƾǦǈƶǄǦǀƽƇǃƼǦǉƽể?ǦƜǦƸƇǃƼ,ǦǂạǃƼǦƸủƶǦƇǃƼǦǆǊƶǃǦǉǇọǃƼǦƽƶǓǦǈƑƸƽǦǆǊƶǃǦǉǇọǃƼ?ǦƣơǃǦǃữƶǦǈốǦǉƾềǃǦƦƽƾếǉǦĐƶǃǦđƚ...ǦǋốǃǦǤĩǦǁƐǦƽọǦǃợǦƸƽƕǃƼǦǉƶ,ǦǁẽǦǃƐǄǦǁạƾǦǀƽƇǃƼǦǤƖǃƼǦđượƸ?",
    ["欠？有人欠了你们，又拿契丹钱作抵？"] = "Ʃợ?ǦƞƚǦǃƼườƾǦǃợǦƸƑƸǦǃƼườƾ,ǦǇồƾǦǤƖǃƼǦǉƾềǃǦƦƽƾếǉǦĐƶǃǦđểǦƼƑǃǦǃợ?",
    ["阿公不说，我说。十年前，我六岁，阿公说晋安寨打完仗了，我爹……没了。那时，村子里逃难来了一对母女，那女儿是个傻子——"] = "ƜǦƸƇǃƼǦǀƽƇǃƼǦǃƚƾǦǉƽƔǦđểǦƸƽƑǊǦǃƚƾ.ǦƨườƾǦǃăǂǦǉǇướƸ,ǦǀƽƾǦƸƽƑǊǦǈƑǊǦǉǊổƾ,ǦƶǦƸƇǃƼǦƷảǄǦǉǇậǃǦƸƽƾếǃǦởǦǉǇạƾǦǥấǃǦƜǃǦđƃǦǍǄǃƼ,ǦƸƽƶǦƸƽƑǊ...ǦǀƽƇǃƼǦƸƛǃǦǃữƶ.ǦƧƕƸǦđƚ,ǦǉǇǄǃƼǦǉƽƇǃǦƸƚǦƽƶƾǦǂẹǦƸǄǃǦǉịǦǃạǃǦǉƔǂǦđếǃ,ǦđứƶǦƸǄǃǦƼƑƾǦđƚǦǁƐǦǂộǉǦǀẻǦǃƼốƸǦ—",
    ["咳咳……唉，那女娃跟霞丫头一样大，却像个小猴，发着烧，一路拖着没治，就烧坏了，人吃人的时候，谁都不容易。"] = "ƦƽụǦǀƽụ...Ǧƶƾ,ǦƸǄǃǦƷƗǦđƚǦƷằǃƼǦǉǊổƾǦƣƐǦǃƽƶǦđầǊ,ǦǃƽưǃƼǦǁạƾǦƼƾốǃƼǦǃƽưǦƸǄǃǦǀƽỉǦǃƽỏ,ǦǅƽƑǉǦǈốǉ,ǦǤọƸǦđườǃƼǦǀƽƇǃƼǦđượƸǦƸƽạǓǦƸƽữƶǦǃƙǃǦƸƽƑǓǦƸảǦǃƃǄ,ǦƸƑƾǦǉƽờƾǦǃƼườƾǦăǃǦǉƽịǉǦǃƼườƾ,ǦƶƾǦƸũǃƼǦƸƽẳǃƼǦǤễǦǤƐǃƼǦƼƔ.",
    ["大家伙，看她们可怜，还是让她们住了下来。就这么过了几年……"] = "ƨọƾǦǃƼườƾǦǉƽấǓǦƽọǦđƑǃƼǦǉƽươǃƼǦǃƙǃǦǋẫǃǦđểǦƽọǦởǦǁạƾ.ǦƞứǦǉƽếǦǆǊƶǦǋƐƾǦǃăǂ...",
    ["那十枚铜钱的束脩，有一枚上头写着……咳咳……后来才知道，她娘俩啊是奚人，千难万难从家乡逃出来的……"] = "ƨườƾǦđồǃƼǦǉƾềǃǦƽọƸǦǅƽƓǦđƚ,ǦƸƚǦǂộǉǦđồǃƼǦƷƙǃǦǉǇƙǃǦƸƚǦǋƾếǉ...ǦǀƽụǦǀƽụ...ǦǈƶǊǦǃƐǓǦǂớƾǦƷƾếǉ,ǦƽƶƾǦǂẹǦƸǄǃǦƽọǦǁƐǦǃƼườƾǦƣề,ǦǂǊƇǃǦǋƐǃǦǀƽƚǦǀƽăǃǦǂớƾǦǉǇốǃǦǉƽǄƑǉǦđượƸǦǀƽỏƾǦǆǊƙǦƽươǃƼ...",
    ["停！那是她们是从虏人那来的！虏人杀了我爹，后来又杀了我娘。她们呢？在我们村子里好好活着……我和她唱采薇，我阿公教她说汉话，凭什么？！她们，她们本就欠……"] = "ǝừǃƼǦǁạƾ!ǦƣọǦǁƐǦǉừǦǅƽƓƶǦǆǊƁǃǦƼƾặƸǦǉớƾ!ǦƢƾặƸǦƼƾếǉǦƸƽƶǦǉƇƾ,ǦǈƶǊǦđƚǦǁạƾǦƼƾếǉǦǂẹǦǉƇƾ.ǦƞƛǃǦƽọǦǉƽƔǦǈƶǄ?ǦỞǦǉǇǄǃƼǦǉƽƇǃǦƸƽƕǃƼǦǉƇƾǦǈốǃƼǦǓƙǃǦổǃ...ǦǥƇƾǦǋƐǦǃƚǦƸƖǃƼǦƽƑǉǦǥƽƑƾǦƱƾ,ǦƶǦƸƇǃƼǦǉƇƾǦǤạǓǦǃƚǦǃƚƾǦǉƾếǃƼǦƣƑǃ,ǦǤựƶǦǋƐǄǦƸƑƾǦƼƔǦƸƽứ?!ǦƣọǦǋốǃǦǤĩǦđƃǦǃợ...",
    ["阿霞！唉……后来她娘俩就搬出了村子，住到了芦苇荡里的船屋。逃难的时候，大家伙喊了她们一起走。"] = "ƜǦƣƐ!ǦƜƾ...ǦǈƶǊǦđƚǦƽƶƾǦǂẹǦƸǄǃǦƽọǦǤờƾǦǀƽỏƾǦǉƽƇǃ,ǦđếǃǦǈốǃƼǦởǦǃƽƐǦǉƽǊǓềǃǦǉǇǄǃƼǦƷƃƾǦǈậǓ.ǦƧƕƸǦƸƽạǓǦǃạǃ,ǦǂọƾǦǃƼườƾǦđƃǦƼọƾǦƽọǦƸƖǃƼǦđƾ.",
    ["可那娘俩，怕契丹人，更怕连累了大家……"] = "ƩƽưǃƼǦƽƶƾǦǂẹǦƸǄǃǦƽọǦǈợǦǃƼườƾǦƦƽƾếǉǦĐƶǃ,ǦǁạƾǦƸƐǃƼǦǈợǦǁƐǂǦǁƾƙǃǦǁụǓǦđếǃǦǂọƾǦǃƼườƾ...",
    ["既找不着了，那这枚天神千万……为何还会夹在李阿公的书里？"] = "ĐƃǦǉƔǂǦǀƽƇǃƼǦǉƽấǓ,ǦǋậǓǦđồǃƼǦǥƽƾƙǃǦǥƽầǃǦǥƽƾƙǃǦƱạǃǦǃƐǓ...ǦǋƔǦǈƶǄǦǁạƾǦǀẹǅǦǉǇǄǃƼǦǈƑƸƽǦƸủƶǦƧƈǦƶǦƸƇǃƼ?",
    ["过了许久，我又在桌缝里找着了。可就算只一枚未还……咳咳……也算收了束脩。我这个先生，自当教书育人……每月有一天，我去教那孩子读书，说汉话，读汉字……"] = "ƮƶǊǦǂộǉǦǉƽờƾǦƼƾƶǃǦǤƐƾ,ǦǉƶǦǁạƾǦǉƔǂǦǉƽấǓǦǃƚǦǉǇǄǃƼǦǀẽǦƷƐǃ.ǦƩƽưǃƼǦǤẫǊǦƸƽỉǦǂộǉǦđồǃƼǦƸƽưƶǦǉǇả...ǦǀƽụǦǀƽụ...ǦǉƽƔǦƸũǃƼǦƸǄƾǦǃƽưǦđƃǦǃƽậǃǦƽọƸǦǅƽƓ.ǦǥƶǦǁƐǦǉƾƙǃǦǈƾǃƽ,ǦǉựǦǃƽƾƙǃǦǅƽảƾǦǤạǓǦƸƽữǦǇƘǃǦǃƼườƾ...ǦƨỗƾǦǉƽƑǃƼǦƸƚǦǂộǉǦǃƼƐǓ,ǦǉƶǦđếǃǦǤạǓǦđứƶǦǉǇẻǦđƚǦđọƸǦǈƑƸƽ,ǦǃƚƾǦǉƾếǃƼǦƣƑǃ,ǦđọƸǦƸƽữǦƣƑǃ...",
    ["阿公……你不是说，以德报怨，何以报德吗？！为何……为何你能放下怨？为何能在爹娘死后、还接受她们……"] = "ƜǦƸƇǃƼ...ǦƸƽẳǃƼǦǅƽảƾǦƇǃƼǦǃƚƾǦ\"ǝƖǃƼǦđứƸǦƷƑǄǦǄƑǃ,ǦǁấǓǦƼƔǦƷƑǄǦđứƸ\"ǦǈƶǄ?!ǦƱƔǦǈƶǄ...ǦǋƔǦǈƶǄǦƇǃƼǦƸƚǦǉƽểǦƷǊƇǃƼǦƷỏǦǄƑǃǦƽậǃ?ǦƱƔǦǈƶǄǦǈƶǊǦǀƽƾǦƸƽƶǦǂẹǦƸƽƑǊǦƸƽếǉ,ǦƇǃƼǦǋẫǃǦƸƽấǅǦǃƽậǃǦƽọ...",
    ["拿着吧，你都把书抵了，那奸商还诓你写欠条。"] = "ƞầǂǦǁấǓǦđƾ,ǦƸǄǃǦđƃǦƼƑǃǦǃợǦƸảǦǈƑƸƽǦǇồƾ,ǦǉƙǃǦƼƾƶǃǦǉƽươǃƼǦđƚǦƸƛǃǦǁừƶǦƸǄǃǦǋƾếǉǦƼƾấǓǦǃợ.",
    ["多谢……我知道他是奸商，只是为了拿药，顾不上那许多。如此，是我欠游侠一个人情。"] = "ĐƶǦǉạ...ǦǉƶǦƷƾếǉǦƽắǃǦǁƐǦƼƾƶǃǦǉƽươǃƼ,ǦƸƽỉǦǁƐǦǋƔǦđểǦǁấǓǦǉƽǊốƸǦǃƙǃǦǀƽƇǃƼǦǂƐǃƼǦđượƸǦǃƽƾềǊǦǃƽưǦǋậǓ.ǦƩƽưǦǋậǓǦǁƐǦǉƶǦǃợǦǤǊǦƽƾệǅǦǂộǉǦǃƽƁǃǦǉƔǃƽ.",
    ["你是……会唱《采薇>吗？"] = "ƩƼươƾ...ǦƷƾếǉǦƽƑǉǦ<ǥƽƑƾǦƱƾ>ǦǈƶǄ?",
    ["你怎么知道？那是我娘教我的词，我爹走后，她日日念，夜夜念。曲子……曲子是芦花教我的，就是……那个奚人姑娘。我们曾经……罢了……"] = "ƮƶǄǦǃƼươƾǦƷƾếǉ?ǦĐƚǦǁƐǦǁờƾǦǉƽơǦǃươǃƼǦǤạǓǦǉƶ,ǦǈƶǊǦǀƽƾǦƸƽƶǦǂấǉ,ǦƷƐǦǃƼƐǓǦǃƐǄǦƸũǃƼǦđọƸ,ǦđƙǂǦǃƐǄǦƸũǃƼǦđọƸ.ǦƦƽƕƸǦǃƽạƸ...ǦǀƽƕƸǦǃƽạƸǦǁƐǦƧƇǦƣǄƶǦǤạǓǦǉƶ,ǦƸƽƓǃƽǦǁƐ...ǦƸƇǦǃươǃƼǦǃƼườƾǦƣềǦđƚ.ǦƞƽƕǃƼǦǉƶǦđƃǦǉừǃƼ...ǦǉƽƇƾǦƷỏǦđƾ...",
    ["那你能不能唱一遍给我听？就算是还了人情。"] = "ƱậǓǦǃƼươƾǦƸƚǦǉƽểǦƽƑǉǦƸƽǄǦǉƶǦǃƼƽƺǦǂộǉǦǁầǃǦđượƸǦǀƽƇǃƼ?ǦƞǄƾǦǃƽưǦǁƐǦǉǇảǦǃƽƁǃǦǉƔǃƽ.",
    ["……好。“采薇采薇，薇亦作止。曰归曰归，岁亦莫止……”"] = "...ǦĐượƸ.Ǧ\"ƣƑƾǦƸỏǦǋƾ,ǦƽƑƾǦƸỏǦǋƾ,ǦƸỏǦǋƾǦđƃǦǃảǓǦǂầǂ.ǦƩƚƾǦǋềǦđƾ,ǦǃƚƾǦǋềǦđƾ,ǦǃăǂǦđƃǦǈắǅǦƽếǉǦǇồƾ...\"",
    ["而若师父已经遭遇不测……我也还得继续救人。"] = "ƨƐǦǃếǊǦǈưǦǅƽụǦđƃǦƼặǅǦƷấǉǦǉǇắƸ...ǦǉƶǦƸũǃƼǦǋẫǃǦǅƽảƾǦǉƾếǅǦǉụƸǦƸứǊǦǃƼườƾ.",
    ["这地方就要完了，我们……我们该往哪里逃？"] = "ƩơƾǦǃƐǓǦǈắǅǦǍǄǃƼǦđờƾǦǇồƾ,ǦƸƽƕǃƼǦǉƶ...ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦǉǇốǃǦđƾǦđƁǊǦđƁǓ?",
    ["太好了，你还……还活着。"] = "ǥốǉǦǆǊƑ,ǦƽǊǓǃƽǦǋẫǃ...ǦǋẫǃǦƸƛǃǦǈốǃƼ.",
    ["那些天泉的侠客……是我错怪他们了……他们都是、都是顶好的大侠……"] = "ƩƽữǃƼǦƽƾệǅǦǀƽƑƸƽǦǥƽƾƙǃǦǥǊǓềǃǦđƚ...ǦǁƐǦǉƶǦđƃǦǉǇƑƸƽǦǁầǂǦƽọǦǇồƾ...ǦƽọǦđềǊǦǁƐ,ǦđềǊǦǁƐǦǃƽữǃƼǦđạƾǦƽƾệǅǦǉốǉǦǃƽấǉ...",
    ["可是现在说什么都晚了……受伤的人太多，谁都逃不了。"] = "ƩƽưǃƼǦƼƾờǦǃƚƾǦƼƔǦƸũǃƼǦǂǊộǃǦǇồƾ...ǦǃƼườƾǦƷịǦǉƽươǃƼǦǆǊƑǦǃƽƾềǊ,ǦǀƽƇǃƼǦƶƾǦǉǇốǃǦǉƽǄƑǉǦđượƸǦđƁǊ.",
    ["但我就是推着、拉着、背着他们，我也要——嘶！"] = "ƩƽưǃƼǦǤƖǦƸƚǦǅƽảƾǦđẩǓ,ǦǀƗǄ,ǦƽƶǓǦƸƅǃƼǦƽọ,ǦǉƶǦƸũǃƼǦǅƽảƾǦ—ǦǍǊƈǉ!",
    ["没、没事……我就是受了点小伤……"] = "ƦƽƇǃƼ,ǦǀƽƇǃƼǦǈƶǄ...ǦǉƶǦƸƽỉǦƷịǦǉƽươǃƼǦǃƽẹǦǉƽƇƾ...",
    ["你先走，我照顾好秦奶奶，就带着他们跟上来。快走，叫大家都走！"] = "ƣǊǓǃƽǦđƾǦǉǇướƸǦđƾ,ǦǉƶǦƸƽăǂǦǈƚƸǦǉốǉǦƸƽǄǦǥầǃǦǃƃƾǦǃƃƾǦǇồƾǦǈẽǦđưƶǦƽọǦǉƽƺǄǦǈƶǊ.ǦƨƶǊǦđƾǦđƾ,ǦƷảǄǦǂọƾǦǃƼườƾǦđềǊǦđƾǦđƾ!",
    ["都死光了，都死光了——"] = "ƞƽếǉǦǈạƸƽǦǇồƾ,ǦƸƽếǉǦǈạƸƽǦƸảǦǇồƾǦ—",
    ["姐，娘去哪儿了，我肚肚饿……"] = "ǥỷ,ǦǃươǃƼǦđƾǦđƁǊǦǇồƾ,ǦđệǦđƚƾǦƷụǃƼǦǆǊƑ...",
    ["别哭别哭，娘很快就回来了。"] = "ĐừǃƼǦǀƽƚƸǦđừǃƼǦǀƽƚƸ,ǦǃươǃƼǦǈẽǦǋềǦǈớǂǦǉƽƇƾ.",
    ["哥……他都快跪下了，一把年纪了，咱们拿的是不是太狠了点？"] = "ƞƶ...ǦƇǃƼǦấǓǦđềǊǦđƃǦǈắǅǦǆǊỳǦǍǊốǃƼǦǇồƾ,ǦǉừǃƼǦấǓǦǉǊổƾǦđầǊǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦǁấǓǦǃƽưǦǋậǓǦƸƚǦǅƽảƾǦǁƐǦƽơƾǦǆǊƑǦǉƶǓǦǀƽƇǃƼ?",
    ["呸！妇人之仁！你忘了杜帅怎么说的？“就地筹粮”！咱们这叫奉命行事！"] = "ƫƽƾ!ǦĐồǦǅƽụǦǃƽƁǃǦƸƽƾǦǃƽƁǃ!ǦƩƼươƾǦǆǊƙǃǦĐỗǦǈǄƑƾǦǃƚƾǦǉƽếǦǃƐǄǦǇồƾǦǈƶǄ?Ǧ\"ǥạƾǦƸƽỗǦǉǇƖǦǁươǃƼ\"!ǦƞƽƕǃƼǦǉƶǦđƁǓǦƼọƾǦǁƐǦǅƽụǃƼǦǂệǃƽǦƽƐǃƽǦǈự!",
    ["王清将军……王清将军怎么会……"] = "ƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃ...ǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃǦǈƶǄǦƸƚǦǉƽể...",
    ["游侠，别往北去了，已经迟了。再去，就是平白无故地去送死了。"] = "ǝǊǦƽƾệǅ,ǦđừǃƼǦđƾǦǋềǦǅƽƓƶǦƝắƸǦǃữƶ,ǦđƃǦǂǊộǃǦǇồƾ.ǦƢƾờǦǂƐǦđƾ,ǦƸƽƓǃƽǦǁƐǦđƾǦǃộǅǦǂạǃƼǦǋƇǦƓƸƽǦǉƽƇƾ.",
    ["死的人我管不了……但这几个还有口气的，我定护着他们从这包围圈里杀出去！"] = "ƩƼườƾǦđƃǦƸƽếǉǦǉƶǦǀƽƇǃƼǦǆǊảǃǦđượƸ...ǦǃƽưǃƼǦǂấǓǦǃƼườƾǦǋẫǃǦƸƛǃǦƽơƾǦǉƽởǦǃƐǓ,ǦǉƶǦǃƽấǉǦđịǃƽǦǈẽǦƽộǦǉốǃƼǦƷọǃǦƽọǦǈƑǉǦǇƶǦǀƽỏƾǦǋƛǃƼǦǋƁǓ!",
    ["俺就知道……俺就知道……"] = "ƧƃǄǦƷƾếǉǦǂƐ...ǦǁƃǄǦƷƾếǉǦǂƐ...",
    ["他们都走了，说契丹人打来了，再不逃就命了……"] = "ƣọǦđƾǦƽếǉǦǇồƾ,ǦǃƚƾǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦđƑǃƽǦǉớƾǦǃơƾǦǇồƾ,ǦǀƽƇǃƼǦǉǇốǃǦǃƽƶǃƽǦǁƐǦǂấǉǦǂạǃƼ...",
    ["可俺还没等到你和孩子，俺哪能走呢？"] = "ƩƽưǃƼǦǁƃǄǦǋẫǃǦƸƽưƶǦđợƾǦđượƸǦƷƐǦǋƐǦƸǄǃ,ǦǁƃǄǦǈƶǄǦƸƚǦǉƽểǦđƾǦƸơǦƸƽứ?",
    ["我从那几个红衣大侠口中得知，有逃兵躲在这地方，人不坏，便叫他们都赶到南边去了。"] = "ǥƶǦǃƼƽƺǦǂấǓǦǋịǦƽồǃƼǦǓǦđạƾǦƽƾệǅǦǃƚƾ,ǦƸƚǦƷạƾǦƷƾǃƽǦǉǇốǃǦởǦƸƽỗǦǃƐǓ,ǦǉƁǂǦǉƓǃƽǦǀƽƇǃƼǦǍấǊ,ǦǃƙǃǦđƃǦƷảǄǦƽọǦƸƽạǓǦƽếǉǦǋềǦǅƽƓƶǦƩƶǂǦǇồƾ.",
    ["我就想……你也是被那狗东西强抓走的……你还说肯定会逃出来寻我……会不会你也在这儿……"] = "ǥƇƾǦƸứǦǃƼƽĩ...ǦƇǃƼǦƸũǃƼǦƷịǦǉƙǃǦƸẩǊǦǉặƸǦđƚǦƷắǉǦđƾ...ǦƇǃƼǦƸƛǃǦƷảǄǦǃƽấǉǦđịǃƽǦǈẽǦǉǇốǃǦǇƶǦǉƔǂǦǉƇƾ...ǦǀƽƇǃƼǦƷƾếǉǦƸƚǦǅƽảƾǦƇǃƼǦƸũǃƼǦởǦđƁǓǦǀƽƇǃƼ...",
    ["呜……我和孩子……呜呜……终于找着了……"] = "Ǖ...ǦǉƇƾǦǋƐǦƸǄǃ...ǦƽǊǦƽǊ...ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦǉƔǂǦđượƸǦǇồƾ...",
    ["那些个人骑着马，四处劫掠，踩死了多少人……我还以为……我和孩子见不到你了……"] = "ĐƑǂǦǃƼườƾǦđƚǦƸưỡƾǦǃƼựƶ,ǦǀƽắǅǦǃơƾǦƸướǅǦƷƚƸ,ǦƼƾẫǂǦƸƽếǉǦƷƾếǉǦƷƶǄǦǃƽƾƙǊǦǃƼườƾ...ǦǉƇƾǦƸƛǃǦǉưởǃƼ...ǦǉƇƾǦǋƐǦƸǄǃǦǀƽƇǃƼǦđượƸǦƼặǅǦǁạƾǦƇǃƼǦǃữƶ...",
    ["还好有那个唐大侠领着我们几个，一路上好惊险……"] = "ƞũǃƼǦǂƶǓǦƸƚǦǋịǦĐườǃƼǦđạƾǦƽƾệǅǦđƚǦǤẫǃǦǂấǓǦǃƼườƾǦƸƽƕǃƼǦǉƇƾǦđƾ,ǦǤọƸǦđườǃƼǦǉƽậǉǦǁƐǦǀƾǃƽǦƽƾểǂ...",
    ["有、有俺在，你放心，俺们都能逃掉的！"] = "ƞƚ,ǦƸƚǦǁƃǄǦởǦđƁǓ,ǦƷƐǦǓƙǃǦǉƁǂ,ǦƸƽƕǃƼǦǉƶǦđềǊǦǈẽǦǉǇốǃǦǉƽǄƑǉǦđượƸǦǉƽƇƾ!",
    ["俺在军营里，也学了些本事的！"] = "ƧƃǄǦởǦǉǇǄǃƼǦǆǊƁǃǦǤǄƶǃƽǦƸũǃƼǦƽọƸǦđượƸǦƸƽƕǉǦƷảǃǦǁĩǃƽǦǇồƾ!",
    ["大侠，王清将军……真的殁了吗？他们是骗我的吧？"] = "ĐạƾǦƽƾệǅ,ǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃ...ǦǉƽựƸǦǈựǦǉửǦǉǇậǃǦǇồƾǦǈƶǄ?ǦƣọǦđƶǃƼǦǁừƶǦǉƇƾǦǅƽảƾǦǀƽƇǃƼ?",
    ["大侠，你说话啊……我听来了好多消息，真的假的，新的旧 of ……"] = "ĐạƾǦƽƾệǅ,ǦǃƼƐƾǦǃƚƾǦƼƔǦđƾǦƸƽứ...ǦǉƇƾǦǃƼƽƺǦđượƸǦǇấǉǦǃƽƾềǊǦǉƾǃǦǉứƸ,ǦǉƽựƸǦǉƽựƸǦƽưǦƽư,ǦƸũǦƸƚǦǂớƾǦƸƚ...",
    ["可是为什么他们都说……王清将军……没了？"] = "ƩƽưǃƼǦǉạƾǦǈƶǄǦƽọǦđềǊǦǃƚƾ...ǦƱươǃƼǦǥƽƶǃƽǦǉướǃƼǦǆǊƁǃ...ǦǀƽƇǃƼǦƸƛǃǦǃữƶ?",
    ["他们……说的是真的……"] = "ƣọ...ǦǃƚƾǦǁƐǦǈựǦǉƽậǉ...",
    ["……你骗我……我知道，你们都骗 me ……"] = "...ǦƩƼƐƾǦƼạǉǦǉƇƾ...ǦǉƇƾǦƷƾếǉ,ǦƸƑƸǦǃƼườƾǦđềǊǦƼạǉǦǉƇƾ...",
    ["还有那个杜将军，他骗大家……骗了所有人……"] = "ƞƛǃǦƸảǦǉƙǃǦĐỗǦǉướǃƼǦǆǊƁǃǦǀƾƶǦǃữƶ,ǦƽắǃǦǁừƶǦǂọƾǦǃƼườƾ...ǦǁừƶǦǉấǉǦƸảǦǂọƾǦǃƼườƾ...",
    ["周阿根，你也骗我！你快起来！"] = "ƞƽǊǦƜǦƞăǃ,ǦƽǊǓǃƽǦƸũǃƼǦǁừƶǦǉƶ!ǦƣǊǓǃƽǦǂƶǊǦǉỉǃƽǦǁạƾǦđƾ!",
    ["我都给你拖到这儿了，不许睡了！"] = "ǥƶǦđƃǦǀƗǄǦƽǊǓǃƽǦǉớƾǦǉậǃǦđƁǓǦǇồƾ,ǦǀƽƇǃƼǦđượƸǦǃƼủǦǃữƶ!",
    ["你不是叫我闭嘴吗？你怎么比我先闭嘴了？"] = "ƞƽẳǃƼǦǅƽảƾǦƽǊǓǃƽǦƷảǄǦǉƶǦƾǂǦǂƾệǃƼǦǈƶǄ?ǦƮƶǄǦƽǊǓǃƽǦǁạƾǦƾǂǦǂƾệǃƼǦǉǇướƸǦǉƶǦǉƽếǦƽả?",
    ["周阿根！你给我起来！"] = "ƞƽǊǦƜǦƞăǃ!ǦƣǊǓǃƽǦđứǃƼǦǁƙǃǦƸƽǄǦǉƶ!",
    ["师兄师姐们说得好听……我哪儿有脸这样回去……"] = "ƮưǦƽǊǓǃƽǦǈưǦǉỷǦǃƚƾǦǉƽƔǦƽƶǓǦǁắǂ...ǦǉƶǦƸƛǃǦǂặǉǦǂũƾǦǃƐǄǦǂƐǦǆǊƶǓǦǋềǦǃƽưǦǉƽếǦǃƐǓǦƸƽứ...",
    ["你怎么一人留在这里？还……带了这大包小包的？"] = "ƮƶǄǦǃƼươƾǦǁạƾǦởǦđƁǓǦǂộǉǦǂƔǃƽ?Ǧƞƛǃ...ǦǂƶǃƼǦǉƽƺǄǦƷƶǄǦǁớǃǦƷƶǄǦǃƽỏǦǉƽếǦǃƐǓ?",
    ["这些是师兄师姐的酒葫芦。"] = "ĐƁǓǦǁƐǦƷầǊǦǇượǊǦƸủƶǦƸƑƸǦǈưǦƽǊǓǃƽǦǈưǦǉỷ.",
    ["他们都上流民营地去了，说是要帮着料理南退之事。但此行凶险，他们需要个人回去传信，外加把他们的宝贝酒葫芦都捎回去。"] = "ƣọǦđềǊǦđếǃǦǤǄƶǃƽǦǉǇạƾǦǁưǊǦǤƁǃǦǇồƾ,ǦǃƚƾǦǁƐǦđểǦƼƾƕǅǦǁǄǦǁƾệǊǦǋƾệƸǦǇƕǉǦǆǊƁǃǦǋềǦǅƽươǃƼǦƩƶǂ.ǦƩƽưǃƼǦƸƽǊǓếǃǦǃƐǓǦƽǊǃƼǦƽƾểǂ,ǦƽọǦƸầǃǦǂộǉǦǃƼườƾǦǆǊƶǓǦǋềǦƷƑǄǦǉƾǃ,ǦǉƾệǃǦǉƽểǦǂƶǃƼǦǉƽƺǄǦđốǃƼǦƷầǊǦǇượǊǦǆǊƈǦƷƑǊǦƸủƶǦƽọǦǋềǦǁǊƇǃ.",
    ["理由倒是说得好听，还说我打不过他们，年纪又小，理所应当……"] = "ƧƈǦǤǄǦǃƚƾǦǃƼƽƺǦǉƽƔǦƽƶǓǦǁắǂ,ǦƸƛǃǦƷảǄǦǉƶǦđƑǃƽǦǀƽƇǃƼǦǁạƾǦƽọ,ǦǉǊổƾǦǁạƾǦǃƽỏ,ǦǃƙǃǦđƚǦǁƐǦǁẽǦđươǃƼǦǃƽƾƙǃ...",
    ["可我也是狂澜的，我们都该同生死才对！"] = "ƩƽưǃƼǦǉƶǦƸũǃƼǦǁƐǦǃƼườƾǦƸủƶǦƞǊồǃƼǦƧạǃ,ǦƸƽƕǃƼǦǉƶǦǅƽảƾǦƸƖǃƼǦǈƾǃƽǦƸƖǃƼǦǉửǦǂớƾǦđƕǃƼǦƸƽứ!",
    ["唉……都怪我那张破嘴……我就不该说那丧气话，现在……现在应验了……"] = "Ɯƾ...ǦđềǊǦǉạƾǦƸƑƾǦǂồǂǦǉƽốƾǦƸủƶǦǁƃǄ...ǦǁƃǄǦƸƽẳǃƼǦǃƙǃǦǃƚƾǦǂấǓǦǁờƾǦǍǊƾǦǍẻǄǦđƚ,ǦƼƾờǦǉƽƔ...ǦƼƾờǦǉƽƔǦứǃƼǦǃƼƽƾệǂǦǇồƾ...",
    ["行了，老张。你那张嘴没那么金贵。是宋虎硬要拉着孟全，说天黑前能摸点吃的回来……他那犟脾气。谁能拦得住？"] = "ǥƽƇƾǦđƾǦǁƃǄǦǥǇươǃƼ.ǦƞƑƾǦǂồǂǦǁƃǄǦƸƽẳǃƼǦđƑǃƼǦƼƾƑǦǉƽếǦđƁǊ.ǦƧƐǦǥốǃƼǦƣổǦǃƽấǉǦǆǊǓếǉǦǁƇƾǦƨạǃƽǦǥǄƐǃǦđƾ,ǦƷảǄǦǁƐǦǉǇướƸǦǀƽƾǦǉǇờƾǦǉốƾǦǈẽǦǀƾếǂǦđượƸǦƸƽƕǉǦƼƔǦđƚǦăǃǦđượƸǦǂƶǃƼǦǋề...ǦƸƑƾǦǉƓǃƽǦƷướǃƼǦƷỉǃƽǦƸủƶǦƽắǃ,ǦƶƾǦǂƐǦƸảǃǦǃổƾ?",
    ["可……可都这个时辰了。我下午看得真真的，那群虏人就打那边过去了，一个个还都在马上大笑……瘆人得很……"] = "ƩƽưǃƼ...ǦǃƽưǃƼǦđƃǦƼƾờǦǃƐǓǦǇồƾ.ǦƞƽƾềǊǦǃƶǓǦǁƃǄǦǃƽƔǃǦǇƅǦǂồǃǦǂộǉ,ǦđƑǂǦƼƾặƸǦđƚǦđƾǦǃƼƶǃƼǦǆǊƶǦǅƽƓƶǦǀƾƶ,ǦđứƶǦǃƐǄǦđứƶǦǃấǓǦđềǊǦƸườƾǦǁớǃǦǉǇƙǃǦǁưǃƼǦǃƼựƶ...ǦđƑǃƼǦǈợǦƸựƸǦǀỳ...",
    ["兴许……兴许他俩只是找地方躲起来了……"] = "ƝƾếǉǦđƁǊ...ǦƷƾếǉǦđƁǊǦƽƶƾǦǃƼườƾǦƷọǃǦƽọǦƸƽỉǦǁƐǦǉƔǂǦƸƽỗǦǉǇốǃǦǇồƾ...",
    ["哈！听见没？跟马厩里受惊的老鼠一样。这些汉人的胆子，真是比兔子还小。一个敢出来让我射着玩的都没有，真没劲！"] = "ƣƶ!ǦƩƼƽƺǦǉƽấǓǦƸƽưƶ?ǦƢƾốǃƼǦƽệǉǦǁũǦƸƽǊộǉǦǃƽắǉǦǀƾǃƽǦƽƃƾǦǉǇǄǃƼǦƸƽǊồǃƼǦǃƼựƶ.ǦƢƶǃǦǤạǦƸủƶǦđƑǂǦǃƼườƾǦƣƑǃǦǃƐǓǦǆǊảǦǉƽựƸǦƸƛǃǦǃƽỏǦƽơǃǦǉƽỏ.ǦƞƽẳǃƼǦƸƚǦǁấǓǦǂộǉǦđứƶǦǤƑǂǦǁƚǦǂặǉǦǇƶǦƸƽǄǦǉƶǦƷắǃǦƸƽơƾ,ǦǉƽậǉǦǂấǉǦƽứǃƼ!",
    ["萧挞凛"] = "ǥƾƙǊǦǥƽƑǅǦƧẫǂ",
    ["你的箭就这么痒？省省吧。这些软骨头不值得你开弓。走，回马庄，上次的酒还没喝完呢。"] = "ƨũƾǦǉƙǃǦƸủƶǦǃƼươƾǦǃƼứƶǦǃƼƑǓǦǉƽếǦǈƶǄ?ǦǥƽƇƾǦđƾ.ǦƧũǦǃƽǊǦǃƽượƸǦǃƐǓǦǀƽƇǃƼǦđƑǃƼǦđểǦǃƼươƾǦƼƾươǃƼǦƸǊǃƼ.ǦĐƾ,ǦǋềǦƨƃǦǥǇƶǃƼ,ǦǇượǊǦǁầǃǦǉǇướƸǦǋẫǃǦƸƽưƶǦǊốǃƼǦƽếǉǦđƁǊ.",
    ["耶律阿古"] = "ƢƾƶǦƧǊậǉǦƜǦƞổ",
    ["还要守在这个鬼地方多久？"] = "ƞƛǃǦǅƽảƾǦǉǇấǃǦǉƽủǦởǦƸƑƾǦǃơƾǦǆǊỷǦǆǊƑƾǦǃƐǓǦƷƶǄǦǁƁǊǦǃữƶ?",
    ["耶律非"] = "ƢƾƶǦƧǊậǉǦƫƽƾ",
    ["吾主没让我们走，就安心守着。"] = "ƞƽủǦǉƽượǃƼǦƸƽưƶǦƸƽǄǦƸƽƕǃƼǦǉƶǦđƾ,ǦƸứǦǓƙǃǦǉƁǂǦǂƐǦǉƽủ.",
    ["萧骨亚"] = "ǥƾƙǊǦƞốǉǦÁ",
    ["将军没让我们走，就安心守着。"] = "ǥướǃƼǦǆǊƁǃǦƸƽưƶǦƸƽǄǦƸƽƕǃƼǦǉƶǦđƾ,ǦƸứǦǓƙǃǦǉƁǂǦǂƐǦǉƽủ.",
    ["呸，破落地方，什么宝贝都没有。早知就让杜狗来此处，听说他光凭这里的消息都换了不少好处。"] = "ƫƽƾ,ǦƸƑƾǦǃơƾǦǃƑǉǦǇượƾ,ǦƸƽẳǃƼǦƸƚǦƷảǄǦǋậǉǦƼƔ.ǦƝƾếǉǦǉƽếǦđƃǦđểǦƸǄǃǦƸƽƚǦƽọǦĐỗǦđếǃǦđƁǓ,ǦǃƼƽƺǦǃƚƾǦƽắǃǦƸƽỉǦǃƽờǦǉƾǃǦǉứƸǦởǦǃơƾǦǃƐǓǦǂƐǦđổƾǦđượƸǦǀƽƇǃƼǦƓǉǦǁợƾǦǁộƸ.",
    ["又来个送死的汉人！"] = "ƧạƾǦǉƽƙǂǦǂộǉǦǉƙǃǦǃƼườƾǦƣƑǃǦǉớƾǦǃộǅǦǂạǃƼ!",
    ["哎，听说早上将军在后院发了好大一通脾气，怪乌卢本火点得太猛，烧毁好些书页子呢！"] = "ƩƐǓ,ǦǃƼƽƺǦǃƚƾǦǈƑǃƼǦǃƶǓǦǉướǃƼǦǆǊƁǃǦởǦƽậǊǦǋƾệǃǦǃổƾǦǉǇậǃǦǁƇƾǦđƔǃƽ,ǦǉǇƑƸƽǦƆǦƧƇǦƝảǃǦđốǉǦǁửƶǦǆǊƑǦǂạǃƽ,ǦǁƐǂǦƸƽƑǓǦƽỏǃƼǦƷƶǄǦǃƽƾƙǊǦǉǇƶǃƼǦǈƑƸƽǦđấǓ!",
    ["也不知这中原人的玩意有什么好，花里胡哨的，遇上咱们的铁骨朵还不是跪地求饶！"] = "ƞƽẳǃƼǦƷƾếǉǦđồǦƸủƶǦǃƼườƾǦǥǇǊǃƼǦƩƼǊǓƙǃǦƸƚǦƼƔǦƽƶǓ,ǦƽǄƶǦƽƛƺǦƽǄƶǦǈƚƾ,ǦƼặǅǦǅƽảƾǦǥƽƾếǉǦƞốǉǦĐƚƶǦƸủƶǦƸƽƕǃƼǦǉƶǦƸƽẳǃƼǦǅƽảƾǦƸũǃƼǦǅƽảƾǦǆǊỳǦǍǊốǃƼǦƸầǊǦǍƾǃǦǉƽƶǦǂạǃƼǦǈƶǄ!",
    ["有确切消息了么？"] = "ĐƃǦƸƚǦǉƾǃǦǉứƸǦƸƽƓǃƽǦǍƑƸǦƸƽưƶ?",
    ["耶律屋质将军已传信，过两日我等便也可启程南下。"] = "ƢƾƶǦƧǊậǉǦỐƸǦƞƽấǉǦǉướǃƼǦǆǊƁǃǦđƃǦǉǇǊǓềǃǦǉƾǃ,ǦǆǊƶǦƽƶƾǦǃƼƐǓǦǃữƶǦƸƽƕǃƼǦǉƶǦƸũǃƼǦƸƚǦǉƽểǦǀƽởƾǦƽƐǃƽǦǃƶǂǦƽạ.",
    ["萧琮"] = "ǥƾƙǊǦǥƖǃƼ",
    ["好！书院里头那些破书，哪有开封城的财宝重要，将我们绊在这里。"] = "ǥốǉ!ǦƨấǓǦƸǊốǃǦǈƑƸƽǦǃƑǉǦǉǇǄǃƼǦǉƽưǦǋƾệǃǦđƚǦǈƶǄǦǆǊƶǃǦǉǇọǃƼǦƷằǃƼǦǉƐƾǦƷảǄǦởǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦđượƸ,ǦƸứǦƼƾữǦƸƽƁǃǦƸƽƕǃƼǦǉƶǦởǦđƁǓǦǂƃƾ.",
    ["又难啃又没油水，将军费这么多心力对付一个破院子做什么？还让那个鹤带教我族子弟，他一个汉人，也配？"] = "ƱừƶǦǀƽƚǦǃƽằǃǦǋừƶǦƸƽẳǃƼǦƸƚǦǁợƾǦǁộƸǦƼƔ,ǦǉướǃƼǦǆǊƁǃǦǅƽƓǦƷƶǄǦƸƇǃƼǦǈứƸǦđốƾǦǅƽƚǦǋớƾǦƸƑƾǦǋƾệǃǦǃƑǉǦǃƐǓǦǁƐǂǦƸƽƾ?ǦƞƛǃǦđểǦǁƃǄǦƣạƸǦđƚǦǤạǓǦǤỗǦƸǄǃǦƺǂǦǉộƸǦǉƶ,ǦǁƃǄǦǁƐǦǃƼườƾǦƣƑǃ,ǦƸũǃƼǦǍứǃƼǦǈƶǄ?",
    ["你懂什么？这次 we 可不是劫掠一番就走……是要这中原天下。"] = "ƩƼươƾǦǉƽƔǦƷƾếǉǦƸƑƾǦƼƔ?ǦƧầǃǦǃƐǓǦƸƽƕǃƼǦǉƶǦǀƽƇǃƼǦǅƽảƾǦƸướǅǦǅƽƑǦǂộǉǦǅƽƺǃǦǇồƾǦđƾ...ǦǂƐǦǁƐǦǂǊốǃǦƸƚǦƸảǦƼƾƶǃƼǦǈơǃǦǥǇǊǃƼǦƩƼǊǓƙǃǦǃƐǓ.",
    ["踏入此地，死！"] = "ƝướƸǦǋƐǄǦǃơƾǦǃƐǓ,Ǧƞƽếǉ!",
    ["一张被反复修改过的布防图，新旧墨迹相叠，似为中渡桥之战寻觅最后生机。"] = "ƨộǉǦǉấǂǦƷốǦǅƽƛǃƼǦđồǦƷịǦǈửƶǦđổƾǦǃƽƾềǊǦǁầǃ,ǦǋếǉǦǂựƸǦǂớƾǦƸũǦƸƽồǃƼǦǁƙǃǦǃƽƶǊ,ǦǉựƶǦǃƽưǦđƶǃƼǦǉƔǂǦǀƾếǂǦǉƾƶǦǈƾǃƽǦƸơǦƸǊốƾǦƸƖǃƼǦƸƽǄǦǉǇậǃǦƸƽƾếǃǦǥǇǊǃƼǦĐộǦƦƾềǊ.",
    ["图卷一角，疑有落款……“三十三”？"] = "ƨộǉǦƼƚƸǦƸǊộǃǦǉǇƶǃƽ,ǦǃƼƽƾǦǁƐǦƸƚǦǁạƸǦǀƽǄảǃ...Ǧ\"ǥƶǂǦǥƽậǅǦǥƶǂ\"?",
    ["侠行无言，收集到与中渡桥一战相关的义士侠名，可将其刻至碑上。"] = "ƣƾệǅǦƽƐǃƽǦǋƇǦǃƼƇǃ,ǦǉƽǊǦǉƽậǅǦđượƸǦƽƾệǅǦǤƶǃƽǦƸủƶǦƸƑƸǦǃƼƽĩƶǦǈĩǦǁƾƙǃǦǆǊƶǃǦđếǃǦǉǇậǃǦƸƽƾếǃǦǥǇǊǃƼǦĐộǦƦƾềǊ,ǦƸƚǦǉƽểǦǀƽắƸǦǁƙǃǦǉǇƙǃǦƷƾƶ.",
    ["过了这么久，风里还飘着桐油和焦麻的味道，都散不掉。"] = "ĐƃǦǆǊƶǦǁƁǊǦǃƽưǦǋậǓ,ǦǉǇǄǃƼǦƼƾƚǦǋẫǃǦƸƛǃǦǅƽảǃƼǦǅƽấǉǦǂƖƾǦǤầǊǦđồǃƼǦǋƐǦǈợƾǦđƶǓǦƸƽƑǓ,ǦǂƃƾǦǀƽƇǃƼǦǉƶǃǦđƾ.",
    ["萧挞图"] = "ǥƾƙǊǦǥƽƑǅǦĐồ",
    ["可不是么？那些汉人的花样真多！这些日子都快把这山翻过来了。"] = "ƞƽẳǃƼǦǅƽảƾǦǈƶǄ?ǦĐƑǂǦǃƼườƾǦƣƑǃǦđƚǦǁắǂǦƸƽƾƙǊǦǉǇƛǦǉƽậǉ!ǦƨấǓǦǃƼƐǓǦǃƶǓǦǈǊƈǉǦƸƽƕǉǦǃữƶǦǁƐǦǁậǉǦǉǊǃƼǦƸảǦǃƼọǃǦǃƕƾǦǃƐǓǦǁƙǃǦǇồƾ.",
    ["阿昆"] = "ƜǦƞƇǃ",
    ["哼，花样再多有什么用？现在指不定缩在哪儿发抖呢！"] = "ƣừ,ǦǁắǂǦƸƽƾƙǊǦǉǇƛǦǉƽƔǦƸƚǦƓƸƽǦƼƔ?ǦƢƾờǦǃƐǓǦƸƽắƸǦƸƽắǃǦđƶǃƼǦƸǄǦǇƖǂǦởǦǍƚǦǍỉǃƽǦǃƐǄǦđƚǦǂƐǦǅƽƑǉǦǇǊǃǦǇồƾ!",
    ["苍格"] = "ǥƽươǃƼǦƞƑƸƽ",
    ["那股势力截断了上山的路……真的不管吗？"] = "ǥƽếǦǁựƸǦđƚǦđƃǦƸƽặǃǦđứǃƼǦđườǃƼǦǁƙǃǦǃƕƾ...ǦǉƽựƸǦǈựǦǀƽƇǃƼǦǆǊảǃǦǈƶǄ?",
    ["游侠、游侠……"] = "ǝǊǦƽƾệǅ,ǦǤǊǦƽƾệǅ...",
    ["外头的那些契丹人在四处找祁家人，我……祁家只剩下了我……"] = "ĐƑǂǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦƷƙǃǦǃƼǄƐƾǦđƶǃƼǦǁƖǃƼǦǈụƸǦǃƼườƾǦǃƽƐǦƽọǦƦỳǦǀƽắǅǦǃơƾ,ǦǉƇƾ...ǦǃƽƐǦƽọǦƦỳǦƸƽỉǦƸƛǃǦǁạƾǦǂƔǃƽǦǉƇƾǦǉƽƇƾ...",
    ["大家都死在庄上了……景梁他为了救我，也和他们同归于尽了……"] = "ƨọƾǦǃƼườƾǦđềǊǦƸƽếǉǦởǦǉǇǄǃƼǦǉǇƶǃƼǦǇồƾ...ǦƞảǃƽǦƧươǃƼǦǋƔǦƸứǊǦǉƇƾ,ǦƸũǃƼǦđƃǦđồǃƼǦǆǊǓǦưǦǉậǃǦǋớƾǦƷọǃǦƸƽƕǃƼǦǇồƾ...",
    ["契丹人知道了我们在暗中做的那些事……他们扬言就是追到天涯海角去，也要把我们祁家全杀光，一个也不留。"] = "ƩƼườƾǦƦƽƾếǉǦĐƶǃǦđƃǦƷƾếǉǦǃƽữǃƼǦǋƾệƸǦƸƽƕǃƼǦǉƇƾǦƁǂǦǉƽầǂǦǁƐǂ...ǦƸƽƕǃƼǦƽǊƙǃƽǦƽǄƶǃƼǦǇằǃƼǦǤƖǦƸƚǦđǊổƾǦđếǃǦǉậǃǦƸƽƁǃǦǉǇờƾǦƼƚƸǦƷƾểǃ,ǦƸũǃƼǦǅƽảƾǦƼƾếǉǦǈạƸƽǦǃƽƐǦƽọǦƦỳǦƸƽƕǃƼǦǉƇƾ,ǦǂộǉǦǂốǃƼǦƸũǃƼǦǀƽƇǃƼǦđểǦǁạƾ.",
    ["景梁还让我去南边找孩子们……可我……我不能害了他们……我不知该去哪儿好了……"] = "ƞảǃƽǦƧươǃƼǦƸƛǃǦƷảǄǦǉƇƾǦđƾǦǋềǦǅƽƓƶǦƩƶǂǦǉƔǂǦđƑǂǦǉǇẻ...ǦǃƽưǃƼǦǉƇƾ...ǦǉƇƾǦǀƽƇǃƼǦǉƽểǦǁƐǂǦƽạƾǦƸƽƕǃƼǦđượƸ...ǦǉƇƾǦǀƽƇǃƼǦƷƾếǉǦǃƙǃǦđƾǦđƁǊǦƷƁǓǦƼƾờǦǃữƶ...",
    ["你先别慌，如今保命最要紧。"] = "ƝƐǦđừǃƼǦƽǄảǃƼǦƽốǉ,ǦǁƕƸǦǃƐǓǦƼƾữǦǂạǃƼǦǁƐǦǆǊƶǃǦǉǇọǃƼǦǃƽấǉ.",
    ["这屋子附近没见到虏人，只消从庄子后面绕过去，暗里悄悄渡了河，再沿着山脚一路往东南，便能到镇戍仓那边。"] = "ƢầǃǦƸăǃǦǃƽƐǦǃƐǓǦǀƽƇǃƼǦǉƽấǓǦƷƚǃƼǦǤƑǃƼǦǆǊƁǃǦƼƾặƸ,ǦƸƽỉǦƸầǃǦǋƛǃƼǦǆǊƶǦǅƽƓƶǦǈƶǊǦǉǇƶǃƼǦǋƾệǃ,ǦƁǂǦǉƽầǂǦǁặǃƼǦǁẽǦǆǊƶǦǈƇǃƼ,ǦǇồƾǦǂƺǃǦǉƽƺǄǦƸƽƁǃǦǃƕƾǦđƾǦǉƽẳǃƼǦǋềǦƽướǃƼǦĐƇǃƼǦƩƶǂǦǁƐǦƸƚǦǉƽểǦđếǃǦƸƽỗǦǥǇấǃǦƨậǊǦǥƽươǃƼ.",
    ["大家都在南逃，还有些江湖人在一路护送，互相都能有个照应。"] = "ƨọƾǦǃƼườƾǦđềǊǦđƶǃƼǦƸƽạǓǦǋềǦǅƽươǃƼǦƩƶǂ,ǦƸũǃƼǦƸƚǦǂộǉǦǈốǦǃƼườƾǦǉǇǄǃƼǦƼƾƶǃƼǦƽồǦƽộǦǉốǃƼǦǤọƸǦđườǃƼ,ǦƸƚǦǉƽểǦƽỗǦǉǇợǦǁẫǃǦǃƽƶǊ.",
    ["多谢游侠指路……我一会儿就动身！"] = "ĐƶǦǉạǦǤǊǦƽƾệǅǦƸƽỉǦđườǃƼ...ǦǉƇƾǦǈẽǦǀƽởƾǦƽƐǃƽǦǃƼƶǓ!",
    ["汪~~~"] = "ƢƁǊ~~~",
    ["莫子莺"] = "ƨạƸǦǥửǦƪƶǃƽ",
    ["一尊正作挡势的侠士石雕，雕工精细，让你想起阿沱先生口中的刻刀主人。经你仔细观察，发现其底部刻有“姚闻”二字。"] = "ƨộǉǦǅƽǄǦǉượǃƼǦđƑǦƽƾệǅǦǈĩǦđƶǃƼǦǉǇǄǃƼǦǉưǦǉƽếǦǅƽƛǃƼǦǉƽủ,ǦǃƗǉǦƸƽạǂǦǀƽắƸǦǉƾǃƽǦǍảǄǦǀƽƾếǃǦǃƼươƾǦǃƽớǦđếǃǦƸƽủǦǃƽƁǃǦƸủƶǦƸǄǃǦǤƶǄǦǀƽắƸǦǂƐǦƜǦĐƐǦǉƾƙǃǦǈƾǃƽǦǉừǃƼǦǃƽắƸǦǉớƾ.ǦƮƶǊǦǀƽƾǦǆǊƶǃǦǈƑǉǦǀỹǦǁưỡǃƼ,ǦǃƼươƾǦǅƽƑǉǦƽƾệǃǦǤướƾǦđƑǓǦǉượǃƼǦƸƚǦǀƽắƸǦƽƶƾǦƸƽữǦ\"ǝƾƙǊǦƱăǃ\".",
    ["之前那帮穷奇师在城外闹得可凶了，最近怎么好像没动静了？"] = "ǥǇướƸǦǀƾƶǦđƑǂǦƞƖǃƼǦƦỳǦƮưǦǀƾƶǦǃƑǄǦǁǄạǃǦǃƼǄƐƾǦǉƽƐǃƽǦǤữǦǤộƾǦǁắǂ,ǦǈƶǄǦƼầǃǦđƁǓǦƽƔǃƽǦǃƽưǦǀƽƇǃƼǦǉƽấǓǦđộǃƼǦǉĩǃƽǦƼƔǦǃữƶ?",
    ["那群穷奇师最近没什么动静了，我看封山派那帮人还怎么神气！"] = "ĐƑǂǦƞƖǃƼǦƦỳǦƮưǦǀƾƶǦǤạǄǦǃƐǓǦƾǂǦƽơƾǦǁặǃƼǦǉƾếǃƼǦǇồƾ,ǦđểǦǉƶǦǍƺǂǦđƑǂǦǃƼườƾǦǅƽƑƾǦƫƽǄǃƼǦƮơǃǦđƚǦƸƛǃǦǋƙǃƽǦǋƑǄǦđượƸǦƷƶǄǦǁƁǊ!",
    ["前些日子不知从哪里冒出来了一批人马，打着穷奇师的名号，笼络了门内那群古板的封山派。"] = "ƞƑƸƽǦđƁǓǦƓǉǦǁƁǊǦƸƽẳǃƼǦƷƾếǉǦǉừǦđƁǊǦǁƛƾǦǇƶǦǂộǉǦǃƽƚǂǦǃƼườƾ,ǦǂượǃǦǤƶǃƽǦƽƾệǊǦƞƖǃƼǦƦỳǦƮưǦđểǦǁƇƾǦǀƗǄǦđƑǂǦǃƼườƾǦƸổǦƽủǦǉƽǊộƸǦǅƽƑƾǦƫƽǄǃƼǦƮơǃǦǉǇǄǃƼǦǂƇǃǦǅƽƑƾ.",
    ["之前他们盘踞在墨城之外行事张扬，寻常人见了都得绕着走，也不知为何，最近忽然就收敛多了。"] = "ǥǇướƸǦđƁǓǦƷọǃǦƽọǦƸƽƾếǂǦƸứǦǃƼǄƐƾǦƨặƸǦǥƽƐǃƽǦƽƐǃƽǦǈựǦǉǇươǃƼǦǤươǃƼ,ǦǃƼườƾǦƷƔǃƽǦǉƽườǃƼǦǉƽấǓǦđềǊǦǅƽảƾǦđƾǦǋƛǃƼ,ǦǀƽƇǃƼǦƷƾếǉǦǉạƾǦǈƶǄǦƼầǃǦđƁǓǦđộǉǦǃƽƾƙǃǦǁạƾǦǉƽǊǦǁƾễǂǦƽơǃǦǃƽƾềǊ.",
    ["哎，之前明明是巨子同意的封山，怎如今又有变动？"] = "ƞƽƶǄǦƇƾ,ǦǇƅǦǇƐǃƼǦǉǇướƸǦđƚǦƞựǦǥửǦđƃǦđồǃƼǦƈǦǅƽǄǃƼǦǈơǃ,ǦǈƶǄǦƼƾờǦǁạƾǦƸƚǦǉƽƶǓǦđổƾǦǇồƾ?",
    ["前些日子，巨子才同意了那群封山派的意见，决定封山。可谁想到，如今又传出消息，说要开山了。"] = "ƨấǓǦǃƼƐǓǦǉǇướƸǦƞựǦǥửǦǂớƾǦđồǃƼǦƈǦƈǦǀƾếǃǦƸủƶǦđƑǂǦǃƼườƾǦǅƽƑƾǦƫƽǄǃƼǦƮơǃ,ǦǆǊǓếǉǦđịǃƽǦǅƽǄǃƼǦǈơǃ.ǦƜƾǦǂƐǦǃƼờǦđượƸ,ǦƼƾờǦǁạƾǦƸƚǦǉƾǃǦđồǃǦǁƐǦǈắǅǦǀƽƶƾǦǈơǃǦǇồƾ.",
    ["唉，先前的封山令还没撤下呢！真不知道他们葫芦里卖的什么药。"] = "ƣƶƾǏǏ,ǦǁệǃƽǦǅƽǄǃƼǦǈơǃǦǉǇướƸǦđƚǦƸƛǃǦƸƽưƶǦƼỡǦƷỏǦđƁǊ!ǦǥƽậǉǦǀƽƇǃƼǦƷƾếǉǦǉǇǄǃƼǦƽồǦǁƇǦƸủƶǦƷọǃǦƽọǦđƶǃƼǦƷƑǃǦǉƽǊốƸǦƼƔǦǃữƶ.",
    ["你可小心点儿，这命令变来变去的，我听说那守崖的鹭师姐，最近脾气可不太好。"] = "ƩƼươƾǦǅƽảƾǦƸẩǃǦǉƽậǃǦǂộǉǦƸƽƕǉ,ǦǂệǃƽǦǁệǃƽǦǃƐǓǦƸứǦǉƽƶǓǦđổƾǦǍǄƐǃƽǦǍǄạƸƽ,ǦǉƶǦǃƼƽƺǦǃƚƾǦǋịǦƧộǦǈưǦǉỷǦǉǇấǃǦƼƾữǦǋƑƸƽǦđƑǦǀƾƶǦǤạǄǦǃƐǓǦǉƓǃƽǦǉƔǃƽǦǀƽƇǃƼǦđượƸǦǉốǉǦǁắǂǦđƁǊ.",
    ["前阵子出趟山，不知要费几多周折！如今撤了封山令，终于出入自如了。"] = "ǝạǄǦǉǇướƸǦǂǊốǃǦǇƶǦǀƽỏƾǦǃƕƾǦǂộǉǦƸƽǊǓếǃǦǀƽƇǃƼǦƷƾếǉǦǅƽảƾǦǉốǃǦƷƶǄǦǃƽƾƙǊǦƸƇǃƼǦǈứƸ!ǦƩƶǓǦđƃǦƼỡǦƷỏǦǁệǃƽǦǅƽǄǃƼǦǈơǃ,ǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦƸƚǦǉƽểǦǇƶǦǋƐǄǦǉựǦǤǄǦǇồƾ.",
    ["唉，怎么又要开山了……依我看，之前那样封着山也没什么不好。"] = "Ɯƾ,ǦǈƶǄǦǁạƾǦǈắǅǦǂởǦǃƕƾǦǇồƾ...ǦǥƽƺǄǦǉƶǦǉƽấǓ,ǦǉǇướƸǦđƚǦƸứǦǅƽǄǃƼǦǈơǃǦǃƽưǦǋậǓǦƸũǃƼǦƸƽẳǃƼǦƸƚǦƼƔǦǀƽƇǃƼǦǉốǉ.",
    ["城外那群穷奇师，来时轰轰烈烈，如今也偃旗息鼓了。"] = "ĐƑǂǦƞƖǃƼǦƦỳǦƮưǦǃƼǄƐƾǦǉƽƐǃƽǦǀƾƶ,ǦǁƕƸǦđếǃǦǉƽƔǦǇầǂǦǇộ,ǦǃƶǓǦƸũǃƼǦđƃǦƾǂǦƽơƾǦǁặǃƼǦǉƾếǃƼǦǇồƾ.",
    ["嗐，总算开了山！前些日子可把我憋坏了，这下终于能下山走动走动了。"] = "ƣạƾ,ǦǇốǉǦƸǊộƸǦƸũǃƼǦǂởǦǃƕƾ!ǦƩƽữǃƼǦǃƼƐǓǦǉǇướƸǦđƚǦǉƽậǉǦǁƐǂǦǉƶǦƷứǉǦǇứǉǦƸƽếǉǦđƾǦđượƸ,ǦǅƽƺǃǦǃƐǓǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦƸƚǦǉƽểǦǍǊốǃƼǦǃƕƾǦđƾǦǤạǄǦǇồƾ.",
    ["哎，你还记不记得，先前那帮封山派的有多嚣张？咱们那位巨子，当时也确实是……唉，压不住他们。"] = "Ê,ǦǃƼươƾǦƸƛǃǦǃƽớǦǀƽƇǃƼ,ǦđƑǂǦǅƽƺǦǅƽǄǃƼǦǈơǃǦǉǇướƸǦđƚǦǀƾƙǊǦǃƼạǄǦǉƽếǦǃƐǄǦƸƽứ?ǦƞựǦǥửǦƸủƶǦƸƽƕǃƼǦǉƶ,ǦǁƕƸǦđƚǦǆǊảǦǉƽựƸǦǁƐ...Ǧƶƾ,ǦǀƽƇǃƼǦǉǇấǃǦƑǅǦǃổƾǦƷọǃǦƽọ.",
    ["何止是压不住。当初她同意那群疯子封山，我还真以为，她要被那帮穷奇师牵着鼻子走到黑了。"] = "ĐƁǊǦƸƽỉǦǁƐǦǀƽƇǃƼǦǉǇấǃǦƑǅǦǃổƾ.ǦƩăǂǦđƚǦǃƐǃƼǦđồǃƼǦƈǦƸƽǄǦđƑǂǦđƾƙǃǦǀƾƶǦǅƽǄǃƼǦǈơǃ,ǦǉƶǦƸƛǃǦǉƽựƸǦǈựǦǉưởǃƼǦǇằǃƼ,ǦǃƐǃƼǦđịǃƽǦđểǦđƑǂǦƞƖǃƼǦƦỳǦƮưǦđƚǦǤắǉǦǂũƾǦđƾǦǋƐǄǦǃƼƅǦƸụǉǦǁǊƇǃǦǇồƾ.",
    ["不过如今，风向好像变了。封山派那几个人，最近都消停了不少。巨子的态度，似乎也……强硬起来了。"] = "ƩƽưǃƼǦƽƾệǃǦǃƶǓ,ǦƼƾƚǦƽƔǃƽǦǃƽưǦđổƾǦƸƽƾềǊǦǇồƾ.ǦƨấǓǦǀẻǦǅƽƺǦǅƽǄǃƼǦǈơǃǦǀƾƶ,ǦƼầǃǦđƁǓǦđềǊǦđƃǦǓƙǃǦắǃƼǦƽơǃǦǃƽƾềǊ.ǦǥƽƑƾǦđộǦƸủƶǦƞựǦǥử,ǦǤườǃƼǦǃƽưǦƸũǃƼ...ǦǉǇởǦǃƙǃǦƸứǃƼǦǇắǃǦƽơǃǦǇồƾ.",
    ["真的？……嘘！这话可不能乱说。不管风向怎么变，咱们看着就是了。慎言，慎言啊！"] = "ǥƽậǉǦǈƶǄ?Ǧ...ƮǊỵǉ!ǦƧờƾǦǃƐǓǦǀƽƇǃƼǦđượƸǦǃƚƾǦƷừƶ.ǦƝấǉǦǀểǦƼƾƚǦđổƾǦƸƽƾềǊǦǉƽếǦǃƐǄ,ǦƸƽƕǃƼǦǉƶǦƸứǦđứǃƼǦǍƺǂǦǁƐǦđượƸ.ǦǥƽậǃǦǉǇọǃƼǦǁờƾǦǃƚƾ,ǦǅƽảƾǦǉƽậǃǦǉǇọǃƼǦđấǓ!",
    ["前阵子那些个封山派，一度拿这事儿做文章，说乱世未平，还是封山为妙……"] = "ǝạǄǦǉǇướƸǦǂấǓǦǀẻǦǉƽǊộƸǦƫƽǄǃƼǦƮơǃǦƫƽƑƾǦǀƾƶ,ǦƸứǦƽởǦǇƶǦǁƐǦǁấǓǦƸƽǊǓệǃǦǃƐǓǦǁƐǂǦđềǦǉƐƾ,ǦǃƚƾǦǁǄạǃǦǉƽếǦƸƽưƶǦƷƔǃƽ,ǦǋẫǃǦǁƐǦǅƽǄǃƼǦǈơǃǦǉƽƔǦƽơǃ...",
    ["不过啊，如今开山是大势所趋，他们那套说辞也没什么人听了。"] = "ƞƚǦđƾềǊǦƐ,ǦǃƶǓǦǀƽƶƾǦǈơǃǦǁƐǦđạƾǦǉƽếǦǈởǦǍǊ,ǦǂấǓǦǁờƾǦǀƾƶǦƸủƶǦƷọǃǦƽọǦƸũǃƼǦƸƽẳǃƼǦƸƛǃǦƶƾǦǂǊốǃǦǃƼƽƺǦǃữƶ.",
    ["你听说没？好像又要开山了……想当年鹤长老那一去……唉！"] = "ƩƼươƾǦǃƼƽƺǦǃƚƾǦƼƔǦƸƽưƶ?ǦƣƔǃƽǦǃƽưǦǁạƾǦǈắǅǦǀƽƶƾǦǈơǃǦǇồƾ...ǦƩƼƽĩǦǁạƾǦǃăǂǦđƚǦƣạƸǦǉǇưởǃƼǦǁƃǄǦǂộǉǦđƾǦǀƽƇǃƼǦǉǇởǦǁạƾ...ǦÁƾǦƸƽƐ!",
    ["哎，如今虽是开山了，但也是几经波折啊！"] = "ƞƽƶǄǦƇƾ,ǦǃƶǓǦǉǊǓǦđƃǦǀƽƶƾǦǈơǃ,ǦǃƽưǃƼǦƸũǃƼǦǁƐǦǉǇảƾǦǆǊƶǦǂấǓǦƽồƾǦǈƚǃƼǦƼƾƚ!",
    ["巨子她……当初就不该对穷奇师那般容忍。放任他们搅弄风雨！"] = "ƞựǦǥửǦǃƐǃƼ...ǦǉƽǊởǦấǓǦǀƽƇǃƼǦǃƙǃǦǤǊǃƼǦǉƕǃƼǦƸƽǄǦđƑǂǦƞƖǃƼǦƦỳǦƮưǦǃƽưǦǋậǓ.ǦĐểǦǂặƸǦƸƽǄǦƷọǃǦƸƽƕǃƼǦǀƽǊấǓǦđộǃƼǦǅƽǄǃƼǦǋƁǃ!",
    ["鄢师侄，你这是何苦呢？"] = "ƴƙǃǦǈưǦđƾệǉ,ǦǃƼươƾǦđƁǓǦǁƐǦƽƐǦǀƽổǦƸƽứ?",
    ["哼，当初那些主张封山的人， injustice 就是太过畏首畏尾了。"] = "ƣừ,ǦđƑǂǦǃƼườƾǦƸƽủǦǉǇươǃƼǦǅƽǄǃƼǦǈơǃǦǃăǂǦđƚ,ǦƸƽƓǃƽǦǁƐǦǆǊƑǦǂứƸǦǈợǦđầǊǦǈợǦđǊƇƾ.",
    ["当初为封山大做文章，连鵙长老都被他们打发出了衡世阁，不再掌机要事务。"] = "ƩăǂǦđƚǦǋƔǦƸƽǊǓệǃǦǅƽǄǃƼǦǈơǃǦǂƐǦǁƐǂǦǇƖǂǦƷƗǃǦǁƙǃ,ǦđếǃǦƸảǦƞƶǄǦǉǇưởǃƼǦǁƃǄǦƸũǃƼǦƷịǦƷọǃǦƽọǦđǊổƾǦǀƽỏƾǦƣƐǃƽǦǥƽếǦƞƑƸ,ǦǀƽƇǃƼǦƸƛǃǦđượƸǦǃắǂǦƼƾữǦƸƑƸǦǈựǦǋụǦƸơǦǂậǉǦǃữƶ.",
    ["我们开山派是争赢了，可我一想到这个，还是替鵙长老不平！"] = "ƦƽƶƾǦƮơǃǦƫƽƑƾǦƸƽƕǃƼǦǉƶǦǁƐǦǉǇƶǃƽǦǉƽắǃƼǦǇồƾ,ǦǃƽưǃƼǦǉƶǦƸứǦǃƼƽĩǦđếǃǦƸƽǊǓệǃǦǃƐǓ,ǦǋẫǃǦǉƽấǓǦƷấǉǦƷƔǃƽǦǉƽƶǓǦƸƽǄǦƞƶǄǦǉǇưởǃƼǦǁƃǄ!",
    ["不过我听同道说，鵙长老用不了多久就会回来。哼，这才像话嘛！"] = "ƩƽưǃƼǦǉƶǦǃƼƽƺǦđồǃƼǦđạǄǦǃƚƾ,ǦƞƶǄǦǉǇưởǃƼǦǁƃǄǦƸƽẳǃƼǦƷƶǄǦǁƁǊǦǃữƶǦǈẽǦǉǇởǦǋề.Ǧƣừ,ǦǉƽếǦǂớƾǦǅƽảƾǦđạǄǦƸƽứ!",
    ["一坛未开封的好酒，肖然离开前寄放于此。若他日有幸从战场回来，定再与你同庆。若无缘，生死不过一醉……"] = "ƨộǉǦǋƛǦǇượǊǦǃƼǄǃǦƸƽưƶǦǂởǦǃắǅ,ǦǥƾƙǊǦƩƽƾƙǃǦǉǇướƸǦǀƽƾǦǇờƾǦđƾǦđƃǦǀƈǦƼửƾǦǉạƾǦđƁǓ.ǦƩếǊǦǃƼƐǓǦǈƶǊǦƸƚǦǅƽƕƸǦǉừǦƸƽƾếǃǦǉǇườǃƼǦǉǇởǦǋề,ǦđịǃƽǦǈẽǦƸƖǃƼǦǃƼươƾǦƸƽǊǃƼǦǋǊƾ.ǦƩếǊǦǋƇǦǤǊǓƙǃ,ǦǈƾǃƽǦǉửǦƸƽẳǃƼǦǆǊƶǦƸũǃƼǦƸƽỉǦǁƐǦǂộǉǦǉǇậǃǦǈƶǓ...",
    ["大侠来了，那伙儿虏人的死期到了！"] = "ĐạƾǦƽƾệǅǦǉớƾǦǇồƾ,ǦǉửǦǀỳǦƸủƶǦǁũǦƷắǉǦǃƼườƾǦǀƾƶǦđếǃǦǇồƾ!",
    ["他们都走了，说契丹人打来了，再不逃就m命了……"] = "ƣọǦđềǊǦđƾǦƸảǦǇồƾ,ǦǃƚƾǦǁƐǦǃƼườƾǦƦƽƾếǉǦĐƶǃǦđƑǃƽǦǉớƾ,ǦƸƛǃǦǀƽƇǃƼǦƸƽạǓǦǁƐǦǂấǉǦǂạǃƼ...",
    ["疼……孙大哥……俺的腿疼……"] = "ĐƶǊ...ǦǥƇǃǦđạƾǦƸƶ...ǦƸƽƁǃǦƸủƶǦđệǦđƶǊǦǆǊƑ...",
    ["俺……俺是不是……再也走不了路了……"] = "Đệ...ǦđệǦƸƚǦǅƽảƾǦǁƐ...ǦǀƽƇǃƼǦƷƶǄǦƼƾờǦđƾǦđườǃƼǦđượƸǦǃữƶǦǀƽƇǃƼ...",
    ["孙大哥，救救俺……求你救救俺……"] = "ǥƇǃǦđạƾǦƸƶ,ǦƸứǊǦđệǦǋớƾ...ǦƸầǊǦǍƾǃǦƽǊǓǃƽǦƸứǊǦđệ...",
    ["你、你别怕。你走不了，俺就背着你跑。"] = "Đệ,ǦđệǦđừǃƼǦǈợ.ǦĐệǦǀƽƇǃƼǦđƾǦđượƸ,ǦƽǊǓǃƽǦǈẽǦƸƅǃƼǦđệǦƸƽạǓ.",
    ["就……就冲你这一声大哥！已经……好多年没人喊过俺大哥了……"] = "ƞƽỉ...ǦƸƽỉǦǋƔǦǂộǉǦǉƾếǃƼǦđạƾǦƸƶǦǃƐǓǦƸủƶǦđệ!ǦĐƃ...ǦƷƶǄǦǃƽƾƙǊǦǃăǂǦǇồƾǦǀƽƇǃƼǦƸƚǦƶƾǦƼọƾǦǉƶǦǁƐǦđạƾǦƸƶǦƸả...",
    ["俺们一起逃，滚着、爬着，总还有活路！"] = "ƞƽƕǃƼǦǉƶǦƸƖǃƼǦǃƽƶǊǦǉǇốǃ,ǦǁăǃǦǁộǃ,ǦƷƛǦǁếǉ,ǦǉƽếǦǃƐǄǦƸũǃƼǦƸƛǃǦđườǃƼǦǈốǃƼ!",
    ["大侠，你说话啊……我听来了好多消息，真的假的，新的旧的……"] = "ĐạƾǦƽƾệǅ,ǦǃƼƐƾǦǃƚƾǦđƾǦƸƽứ...ǦǥƶǦǃƼƽƺǦđượƸǦƷƶǄǦǃƽƾƙǊǦǁƐǦǉƾǃǦǉứƸ,ǦǉƽựƸǦǉƽựƸǦƼƾảǦƼƾả,ǦǂớƾǦǂớƾǦƸũǦƸũ...",
    ["……你骗我……我知道，你们都骗我……"] = "...ƩƼươƾǦǁừƶǦǉƶ...ǦǥƶǦƷƾếǉ,ǦƸƑƸǦǃƼươƾǦđềǊǦǁừƶǦǉƶ...",
    ["张安康，收起你那哑巴德行，我就要你一句话——\n这店你卖不卖？这招牌和我们家，你到底要哪个？"] = "ǥǇươǃƼǦƜǃǦƦƽƶǃƼ,ǦǉƽǊǦǁạƾǦƸƑƾǦđứƸǦƽạǃƽǦƸƁǂǦǃƓǃǦđƚǦƸủƶǦǃƼươƾǦđƾ,ǦǉƶǦƸƽỉǦƸầǃǦǃƼươƾǦǂộǉǦƸƁǊǦǉƽƇƾǦ——\nǥƾệǂǦǃƐǓǦǃƼươƾǦƸƚǦƷƑǃǦƽƶǓǦǀƽƇǃƼ?ǦƞƑƾǦƷảǃƼǦƽƾệǊǦǃƐǓǦǋƐǦƼƾƶǦđƔǃƽǦƸƽƕǃƼǦǉƶ,ǦǇốǉǦƸǊộƸǦǃƼươƾǦǂǊốǃǦƸƑƾǦǃƐǄ?",
    ["都能要。"] = "ĐềǊǦƸƚǦǉƽểǦǂǊốǃ.",
    ["王老爷为富不仁！"] = "ƱươǃƼǦǁƃǄǦƼƾƶǦǋƾǦǅƽƕǦƷấǉǦǃƽƁǃ!",
    ["陆三儿谋财害命！"] = "ƧụƸǦǥƶǂǦǃƽƾǦǂưǊǦǉƐƾǦƽạƾǦǂệǃƽ!",
    ["快快，今年咱买个最新样式的灯，去年那个船灯就挺好的。"] = "ƨƶǊǦǂƶǊ,ǦǃăǂǦǃƶǓǦǉƶǦǂǊƶǦǂộǉǦƸƽƾếƸǦđƘǃǦǀƾểǊǦǤƑǃƼǦǂớƾǦǃƽấǉ,ǦƸƽƾếƸǦđƘǃǦƽƔǃƽǦǉƽǊǓềǃǦǃăǂǦǃƼǄƑƾǦǀƽƑǦǉốǉǦđƚ.",
    ["围观男子"] = "ƩƶǂǦǉửǦǋƁǓǦǍƺǂ",
    ["阿爷，今年有兔儿灯吗？"] = "ƜǦƼƾƶ,ǦǃăǂǦǃƶǓǦƸƚǦđƘǃǦƸǄǃǦǉƽỏǦǀƽƇǃƼǦạ?",
    ["上元安康，心想事成！"] = "ǥƽượǃƼǦǃƼǊǓƙǃǦƶǃǦǀƽƶǃƼ,ǦǉƁǂǦǉưởǃƼǦǈựǦǉƽƐǃƽ!",
    ["围观女子"] = "ƩữǦǉửǦǋƁǓǦǍƺǂ",
    ["今晚还有烟花大会，咱们快点去，占个好位置。"] = "ǥốƾǦǃƶǓǦƸƛǃǦƸƚǦđạƾǦƽộƾǦǅƽƑǄǦƽǄƶ,ǦƸƽƕǃƼǦǉƶǦǂƶǊǦđƾǦǉƽƇƾ,ǦƸƽƾếǂǦǁấǓǦǂộǉǦƸƽỗǦǉốǉ.",
    ["缈缈红尘，繁灯如昼……秃驴兄，你瞧这上元佳节，家家团圆，可谓是人间盛景啊。"] = "ƣồǃƼǦǉǇầǃǦǂịǉǦǂƖ,ǦđƘǃǦƽǄƶǦǇựƸǦǇỡǦǃƽưǦƷƶǃǦǃƼƐǓ...ǦƩƼốƸǦǁăǃƼǦƽǊǓǃƽ,ǦǃƼươƾǦǍƺǂǦǉƾếǉǦǥƽượǃƼǦǃƼǊǓƙǃǦǃƐǓ,ǦǃƽƐǦǃƽƐǦđǄƐǃǦǋƾƙǃ,ǦƸƚǦǉƽểǦǃƚƾǦǁƐǦǃƽƁǃǦƼƾƶǃǦǉƽịǃƽǦƸảǃƽǦǋậǓ.",
    ["烁情真君"] = "ǥƽướƸǦǥƔǃƽǦƞƽƁǃǦƬǊƁǃ",
    ["阿弥陀佛，众生欢享今宵，天下承平，此乃大造化也。"] = "ƜǦǝƾǦĐƐǦƫƽậǉ,ǦƸƽƕǃƼǦǈƾǃƽǦǋǊƾǦƽưởǃƼǦđƙǂǦǃƶǓ,ǦǉƽƾƙǃǦƽạǦǉƽƑƾǦƷƔǃƽ,ǦđƁǓǦƸƽƓǃƽǦǁƐǦđạƾǦǉạǄǦƽƚƶǦǋậǓ.",
    ["灯源尊者"] = "ĐăǃƼǦƩƼǊǓƙǃǦǥƇǃǦƢƾả",
    ["秃驴兄，你我既来此间，何不入乡随俗，也点一盏花灯助助兴？"] = "ƩƼốƸǦǁăǃƼǦƽǊǓǃƽ,ǦǃƼươƾǦǋƐǦǉƶǦđƃǦđếǃǦƸƽốǃǦǃƐǓ,ǦǈƶǄǦǀƽƇǃƼǦǃƽậǅǦƼƾƶǦǉƖǓǦǉụƸ,ǦƸũǃƼǦǉƽắǅǦǂộǉǦǃƼọǃǦƽǄƶǦđăǃƼǦđểǦƼƚǅǦǋǊƾ?",
    ["那边的小友，听闻你前些日子与这花灯有一段机缘，我这恰有些花灯料物，不知能否再助贫道一次？"] = "ǥƾểǊǦƽữǊǦƷƙǃǦǀƾƶ,ǦǃƼƽƺǦǤƶǃƽǦǃƼươƾǦǂấǓǦǃƼƐǓǦǉǇướƸǦƸƚǦǂộǉǦđǄạǃǦƸơǦǤǊǓƙǃǦǋớƾǦƽǄƶǦđăǃƼǦǃƐǓ,ǦǉƶǦđƁǓǦǋừƶǦǀƽƗǄǦƸƚǦƸƽƕǉǦǁƾệǊǦǋậǉǦƽǄƶǦđăǃƼ,ǦǀƽƇǃƼǦƷƾếǉǦƸƚǦǉƽểǦǉǇợǦƼƾƕǅǦƷầǃǦđạǄǦǉƽƙǂǦǂộǉǦǁầǃǦǃữƶ?",
    ["多谢小友。我二人常在山中修行，如今下山云游，正赶上这上元佳节，又遇小友，实乃有缘。"] = "ĐƶǦǉạǦǉƾểǊǦƽữǊ.ǦƣƶƾǦǃƼườƾǦƸƽƕǃƼǦǉƶǦǉƽườǃƼǦǉǊǦƽƐǃƽǦǉǇǄǃƼǦǃƕƾ,ǦǃƶǓǦǍǊốǃƼǦǃƕƾǦǋƁǃǦǤǊ,ǦƸƽƓǃƽǦǁƕƸǦƼặǅǦǉƾếǉǦǥƽượǃƼǦǃƼǊǓƙǃǦǃƐǓ,ǦǁạƾǦƽộƾǦǃƼộǦǉƾểǊǦƽữǊ,ǦǉƽậǉǦǁƐǦƽữǊǦǤǊǓƙǃ.",
    ["道兄，我佛门自古有上元燃灯祀佛之礼，你道家亦有上元斋戒沐浴之规。可为何这佛道的节日，如今却变作人间花灯之夜，团圆之节？"] = "ĐạǄǦƽǊǓǃƽ,ǦƫƽậǉǦǂƇǃǦǉƶǦǉừǦǍưƶǦƸƚǦǁễǦǥƽượǃƼǦǃƼǊǓƙǃǦǃƽƾƙǃǦđăǃƼǦǉựǦƫƽậǉ,ǦĐạǄǦƼƾƶǦǃƼươƾǦƸũǃƼǦƸƚǦǆǊǓǦƸủǦǥƽượǃƼǦǃƼǊǓƙǃǦǉǇƶƾǦƼƾớƾǦǉắǂǦƼộƾ.ǦƩƽưǃƼǦǉạƾǦǈƶǄǦǃƼƐǓǦǁễǦƸủƶǦƫƽậǉǦĐạǄ,ǦǃƶǓǦǁạƾǦƷƾếǃǦǉƽƐǃƽǦđƙǂǦƽǄƶǦđăǃƼǦǃƽƁǃǦƼƾƶǃ,ǦǉƾếǉǦđǄƐǃǦǋƾƙǃ?",
    ["哈哈哈，灯者，明也。燃灯者，何也？那边的小友，你可知道？"] = "ƣƶǦƽƶǦƽƶ,ǦĐăǃƼǦƼƾả,ǦƨƾǃƽǦǤƃ.ǦƩƽƾƙǃǦđăǃƼǦƼƾả,ǦƣƐǦǤƃ?ǦǥƾểǊǦƽữǊǦƷƙǃǦǀƾƶ,ǦǃƼươƾǦƸƚǦƷƾếǉǦƸƽăǃƼ?",
    ["因为……佛道两教信徒众多？家家都信佛修道，时间长了，大家便习惯了在这天点起灯……"] = "ƝởƾǦǋƔ...ǦǉƓǃǦđồǦƽƶƾǦƼƾƑǄǦƫƽậǉǦĐạǄǦđƇǃƼǦđảǄ?ǦƩƽƐǦǃƽƐǦđềǊǦǉƾǃǦƫƽậǉǦǉǊǦĐạǄ,ǦǉƽờƾǦƼƾƶǃǦǤƐƾǦǇồƾ,ǦǂọƾǦǃƼườƾǦǁƾềǃǦǆǊƺǃǦǋớƾǦǋƾệƸǦǉƽắǅǦđƘǃǦǋƐǄǦǃƼƐǓǦǃƐǓ...",
    ["小友不妨去人间看看。若是心有余力，就云游一番，搜集些料物，也为这红尘众生斫木秉烛，燃一盏花灯吧。"] = "ǥƾểǊǦƽữǊǦƸƽƾǦƷằǃƼǦƽƃǓǦđƾǦǍƺǂǦǃƽƁǃǦƼƾƶǃǦǉƽửǦǍƺǂ.ǦƩếǊǦǁƛǃƼǦƸƛǃǦǤưǦǁựƸ,ǦǉƽƔǦƽƃǓǦǋƁǃǦǤǊǦǂộǉǦǅƽƺǃ,ǦǉƽǊǦǉƽậǅǦƸƽƕǉǦǁƾệǊǦǋậǉ,ǦƸũǃƼǦǋƔǦƸƽƕǃƼǦǈƾǃƽǦƽồǃƼǦǉǇầǃǦǃƐǓǦǂƐǦđẽǄǦƼỗǦƸầǂǦǃếǃ,ǦǉƽắǅǦǂộǉǦǃƼọǃǦƽǄƶǦđăǃƼǦđƾ.",
    ["妙哉，妙哉，如此便也算在这红尘中体悟一程。"] = "ǝƾệǊǦǉƽƶǓ,ǦǤƾệǊǦǉƽƶǓ,ǦǃƽưǦǋậǓǦƸũǃƼǦƸǄƾǦǃƽưǦǁƐǦǉƽểǦǃƼƽƾệǂǦǂộǉǦƸƽǊǓếǃǦǉǇǄǃƼǦƽồǃƼǦǉǇầǃǦǃƐǓ.",
    ["哎，且慢。小友前些日子在城中点了些花灯，今日上元，倒是可以看看那灯中可有故人之语？或许也可帮小友略解疑惑。"] = "ƞƽờǦƸƽƕǉ.ǦǥƾểǊǦƽữǊǦǂấǓǦǃƼƐǓǦǉǇướƸǦƸƚǦǉƽắǅǦǋƐƾǦǃƼọǃǦƽǄƶǦđăǃƼǦǉǇǄǃƼǦǉƽƐǃƽ,ǦƽƇǂǦǃƶǓǦǥƽượǃƼǦǃƼǊǓƙǃ,ǦƸƽƾǦƷằǃƼǦƸƚǦǉƽểǦǍƺǂǦǉƽửǦǉǇǄǃƼǦđƘǃǦƸƚǦǁờƾǦƸủƶǦƸốǦǃƽƁǃǦƸƽăǃƼ?ǦƞƚǦǁẽǦƸũǃƼǦƼƾƕǅǦǉƾểǊǦƽữǊǦƼƾảƾǦđƑǅǦđƇƾǦƸƽƕǉǦǃƼƽƾǦƽǄặƸ.",
    ["哇！阿娘，快看，那个游侠的花灯真好看。"] = "ƪƶ!ǦƜǦǃươǃƼ,ǦǂƶǊǦǍƺǂ,ǦƽǄƶǦđăǃƼǦƸủƶǦǋịǦǤǊǦƽƾệǅǦǀƾƶǦǉƽậǉǦđẹǅǦǆǊƑ.",
    ["去年我买的灯，没两天就让雪给淋坏了。今年可要买个结实的。"] = "ĐƘǃǦǃăǂǦǃƼǄƑƾǦǉƶǦǂǊƶ,ǦƸƽưƶǦđượƸǦƽƶƾǦǃƼƐǓǦđƃǦƷịǦǉǊǓếǉǦǁƐǂǦƽỏǃƼ.ǦƩăǂǦǃƶǓǦǅƽảƾǦǂǊƶǦƸƑƾǦǃƐǄǦǉƽậǉǦƸƽắƸǦƸƽắǃǦǂớƾǦđượƸ.",
    ["咱们也点个花灯，来年啊都平平安安的。"] = "ƞƽƕǃƼǦǉƶǦƸũǃƼǦǉƽắǅǦǂộǉǦǃƼọǃǦƽǄƶǦđăǃƼǦđƾ,ǦǂǄǃƼǦǃăǂǦǉớƾǦđềǊǦđượƸǦƷƔǃƽǦƷƔǃƽǦƶǃǦƶǃ.",
    ["哟，这花灯的造型可真别致，是宫里头的样式吗？"] = "Ồ,ǦǉạǄǦƽƔǃƽǦƽǄƶǦđăǃƼǦǃƐǓǦǉƽậǉǦǃƽƃǦǃƽặǃ,ǦǁƐǦǀƾểǊǦǤƑǃƼǦǉǇǄǃƼǦƸǊǃƼǦǈƶǄ?",
    ["花灯一亮，这年就要过完了……希望来年会更顺利的吧！"] = "ƣǄƶǦđăǃƼǦǋừƶǦǈƑǃƼ,ǦǃăǂǦǃƐǓǦƸǄƾǦǃƽưǦǈắǅǦǆǊƶǦǇồƾ...ǦƣǓǦǋọǃƼǦǃăǂǦǉớƾǦǈẽǦǉƽǊậǃǦǁợƾǦƽơǃ!",
    ["这灯可真喜庆，映得人心里都亮堂堂的。"] = "ĐƘǃǦǃƐǓǦǉƽậǉǦƽỉǦǀƽƓ,ǦǈǄƾǦǈƑǃƼǦƸảǦǁƛǃƼǦǃƼườƾ.",
    ["新年顺遂，百病皆消。"] = "ƩăǂǦǂớƾǦǉƽǊậǃǦǁợƾ,ǦƷƑƸƽǦƷệǃƽǦǉƾƙǊǦǉƶǃ.",
    ["怎么说，直接奔南边把他们砍了，谁支持？谁反对？要是怕脏，咱有墨山道的朋友的新物件，保证不脏手！"] = "ƮƶǄǦƽả,ǦǉǇựƸǦǉƾếǅǦǍƇǃƼǦǁƙǃǦǅƽƓƶǦƩƶǂǦƸƽƗǂǦǈạƸƽǦƷọǃǦƸƽƕǃƼ,ǦƶƾǦủǃƼǦƽộ?ǦƜƾǦǅƽảǃǦđốƾ?ǦƩếǊǦǈợǦƷẩǃǦǉƶǓ,ǦǉƶǦƸƚǦǂƚǃǦđồǦǂớƾǦƸủƶǦƷằǃƼǦƽữǊǦƷƙǃǦƨặƸǦƮơǃǦĐạǄ,ǦđảǂǦƷảǄǦǀƽƇǃƼǦƷẩǃǦǉƶǓǦđƁǊ!",
    ["林拂"] = "ƧƁǂǦƫƽấǉ",
    ["此言差矣！此刻开封民生之困，绝不只是城外贼寇之祸。如今已是年节，人流、货运需求极大。"] = "ƩƚƾǦǋậǓǦǁƐǦǈƶƾǦǇồƾ!ǦƧƕƸǦǃƐǓǦƸƑƾǦǀƽƚǦǋềǦǤƁǃǦǈƾǃƽǦởǦƦƽƶƾǦƫƽǄǃƼ,ǦǉǊǓệǉǦđốƾǦǀƽƇǃƼǦƸƽỉǦǁƐǦƽọƶǦƼƾặƸǦǀƽấǊǦǃƼǄƐƾǦǉƽƐǃƽ.ǦƩƶǓǦđƃǦǁƐǦǃƼƐǓǦǥếǉ,ǦǃƽǊǦƸầǊǦǁưǊǦǉƽƇǃƼǦǃƼườƾǦǋƐǦƽƐǃƼǦƽƚƶǦƸựƸǦǁớǃ.",
    ["宋行周"] = "ǥốǃƼǦƣƐǃƽǦƞƽǊ",
    ["听一位孤云朋友讲，除非乘驿轩的车马量翻两番，否则城内百姓民生之苦难以解决！"] = "ƩƼƽƺǦǂộǉǦǋịǦƷằǃƼǦƽữǊǦƷƙǃǦƞƇǦƱƁǃǦǃƚƾ,ǦǉǇừǦǅƽƾǦǁượǃƼǦǍƺǦǃƼựƶǦƸủƶǦǥƽừƶǦƣƾƙǃǦǝịƸƽǦǉăǃƼǦƼấǅǦđƇƾ,ǦǃếǊǦǀƽƇǃƼǦǃỗƾǦǀƽổǦǤƁǃǦǈƾǃƽǦƸủƶǦƷƑƸƽǦǉƓǃƽǦǉǇǄǃƼǦǉƽƐǃƽǦǀƽƚǦǂƐǦƼƾảƾǦǆǊǓếǉ!",
    ["不能只看乘驿轩一处。眼下过年，富者筵席笙歌，贫者只能勉强果腹。"] = "ƦƽƇǃƼǦǉƽểǦƸƽỉǦǃƽƔǃǦǋƐǄǦǂộǉǦƸƽỗǦǥƽừƶǦƣƾƙǃǦǝịƸƽ.ǦƣƾệǃǦǉạƾǦăǃǦǥếǉ,ǦǀẻǦƼƾƐǊǦǉƾệƸǦǉƖǃƼǦƸƶǦƽƑǉ,ǦǃƼườƾǦǃƼƽƘǄǦƸƽỉǦƸƚǦǉƽểǦǂƾễǃǦƸưỡǃƼǦǃǄǦƷụǃƼ.",
    ["近些天角门里多了许多病患，大多都是体虚缺食，长此下去只怕患者越来越多。"] = "ƨấǓǦǃƼƐǓǦƼầǃǦđƁǓǦǉǇǄǃƼǦƢƾƑƸǦƨƇǃǦƧƈǦƸƚǦǉƽƙǂǦǃƽƾềǊǦǃƼườƾǦƷệǃƽ,ǦđƶǦǅƽầǃǦđềǊǦǁƐǦǉƽểǦƽưǦǉƽƾếǊǦăǃ,ǦƸứǦđƐǦǃƐǓǦƺǦǁƐǦǃƼườƾǦƷệǃƽǦǃƼƐǓǦƸƐǃƼǦǃƽƾềǊ.",
    ["这个倒不用担心，在下认识的几位老师傅，从前就在文津馆边上开馆子。"] = "ƞƑƾǦǃƐǓǦǉƽƔǦǀƽƇǃƼǦƸầǃǦǁǄǦǁắǃƼ,ǦǉạƾǦƽạǦǆǊƺǃǦƷƾếǉǦǂấǓǦǋịǦǁƃǄǦǈưǦǅƽụ,ǦǉǇướƸǦǀƾƶǦǉừǃƼǦǂởǦǆǊƑǃǦƷƙǃǦƸạǃƽǦƱăǃǦǥƁǃǦƬǊƑǃ.",
    ["如今他们都在开封！介时请他们帮忙掌勺，做些大菜，送与角门里的百姓。"] = "ƩƶǓǦƽọǦđềǊǦđƶǃƼǦởǦƦƽƶƾǦƫƽǄǃƼ!ǦƧƕƸǦđƚǦǂờƾǦƽọǦƼƾƕǅǦđỡǦǍǊốǃƼǦƷếǅ,ǦǁƐǂǦǋƐƾǦǂƚǃǦđạƾǦǉƽƑƾ,ǦƼửƾǦƸƽǄǦƷƑƸƽǦǉƓǃƽǦởǦƢƾƑƸǦƨƇǃǦƧƈ.",
    ["这几位师傅年轻时也颇有侠心，这种接济百姓的事他们定不会推辞。只是这几位师傅年纪大，手脚倒不似从前麻利……"] = "ƨấǓǦǋịǦǈưǦǅƽụǦǃƐǓǦǁƕƸǦǉǇẻǦƸũǃƼǦǇấǉǦƸƚǦƽƾệǅǦǉƁǂ,ǦǋƾệƸǦǉƾếǅǦǉếǦƷƑƸƽǦǉƓǃƽǦǉƽếǦǃƐǓǦƽọǦđịǃƽǦǈẽǦǀƽƇǃƼǦǉừǦƸƽốƾ.ǦƞƽỉǦǁƐǦǂấǓǦǋịǦǈưǦǅƽụǦǉǊổƾǦđƃǦƸƶǄ,ǦǉƶǓǦƸƽƁǃǦǀƽƇǃƼǦƸƛǃǦǃƽƶǃƽǦǃƽẹǃǦǃƽưǦǉǇướƸ...",
    ["书呆子，你该不会是想趁机解解馋吧？你们那儿的菜那可是出了名的下酒！我上次和天泉的姐们儿就着一盘肘子喝了三壶！"] = "ƨọǉǦǈƑƸƽ,ǦǃƼươƾǦǀƽƇǃƼǦǅƽảƾǦǁƐǦǂǊốǃǦǃƽƁǃǦƸơǦƽộƾǦǃƐǓǦƼƾảƾǦǉƽƘǂǦđấǓǦƸƽứ?ǦƨƚǃǦăǃǦƸƽỗǦƸƑƸǦǃƼươƾǦǃổƾǦǉƾếǃƼǦǁƐǦđưƶǦƸƶǓǦđƚ!ǦƧầǃǦǉǇướƸǦǉƶǦƸƖǃƼǦǂấǓǦǉỷǦǂǊộƾǦǥƽƾƙǃǦǥǊǓềǃǦǋừƶǦǃƽắǂǦđĩƶǦƸƽƁǃǦƼƾƛǦǋừƶǦǊốǃƼǦƽếǉǦƷƶǦǋƛ!",
    ["我……我才没有！我不过是想着要给百姓们尝尝鲜！"] = "ǥƶ...ǦǉƶǦǀƽƇǃƼǦƸƚ!ǦǥƶǦƸƽẳǃƼǦǆǊƶǦǁƐǦǃƼƽĩǦǂǊốǃǦƸƽǄǦƷƑƸƽǦǉƓǃƽǦǃếǂǦǉƽửǦƸƽƕǉǦƽươǃƼǦǋịǦǉươƾǦǃƼǄǃǦǉƽƇƾ!",
    ["若能与诸位携手，解百姓之困，我愿自掏腰包，宴请诸位。"] = "ƩếǊǦƸƚǦǉƽểǦƸƖǃƼǦƸƽưǦǋịǦƸƽǊǃƼǦǉƶǓ,ǦƼƾảƾǦǃỗƾǦǁǄǦƸủƶǦƷƑƸƽǦǉƓǃƽ,ǦǉƶǦǃƼǊǓệǃǦǉựǦƷỏǦǉƾềǃǦǉƕƾ,ǦǓếǃǦǉƽỉǃƽǦƸƽưǦǋị.",
    ["几位，听起来是有麻烦事了？"] = "ƨấǓǦǋị,ǦǃƼƽƺǦƸƽừǃƼǦǁƐǦƸƚǦƸƽǊǓệǃǦǅƽƾềǃǦǅƽứƸǦǇồƾ?",
    ["要我说，把南边那群贼寇都砍了，没人闹事儿，后面的都是小问题！"] = "ĐểǦǉƶǦǃƚƾ,ǦƸứǦƸƽƗǂǦǈạƸƽǦđƑǂǦƼƾặƸǦǀƽấǊǦǅƽƓƶǦƩƶǂǦǀƾƶǦđƾ,ǦǀƽƇǃƼǦƶƾǦƼƁǓǦǈựǦǃữƶǦǉƽƔǦǂấǓǦƸƽǊǓệǃǦǈƶǊǦđƚǦđềǊǦǁƐǦǋấǃǦđềǦǃƽỏ!",
    ["你们那边的大菜……都有什么呢？"] = "ƨƚǃǦđạƾǦǉƽƑƾǦǅƽƓƶǦƷƙǃǦƸƑƸǦǃƼươƾ...ǦđềǊǦƸƚǦǃƽữǃƼǦƼƔǦǋậǓ?",
    ["游侠！我们文津馆面朝大海，又临泰山，好吃的菜那可数不过来！扒鸡，四喜丸子，九转肥肠，油焖虾，葱烧海参……"] = "ǝǊǦƽƾệǅ!ǦƱăǃǦǥƁǃǦƬǊƑǃǦƸƽƕǃƼǦǉƶǦǂặǉǦƽướǃƼǦǇƶǦƷƾểǃǦǁớǃ,ǦǁạƾǦǉựƶǦǃƕƾǦǥƽƑƾǦƮơǃ,ǦǂƚǃǦǃƼǄǃǦđếǂǦǀƽƇǃƼǦǍǊể!ǦƢƐǦƽầǂ,ǦǉứǦƽỷǦƽǄƐǃǦǉử,ǦđạƾǦǉǇƐǃƼǦƸửǊǦƸƽǊǓểǃ,ǦǉƇǂǦǀƽǄǦǤầǊ,ǦƽảƾǦǈƁǂǦǍƐǄǦƽƐǃƽ...",
    ["但这些都不是最顶佳的饭肴！若说最最销魂、最最让人上头的滋味，那一定是——煎饼卷葱！"] = "ƩƽưǃƼǦǃƽữǃƼǦǉƽứǦđƚǦđềǊǦǀƽƇǃƼǦǅƽảƾǦǁƐǦƸƶǄǦǁươǃƼǦǂỹǦǋịǦǃƽấǉ!ǦƩếǊǦǃƚƾǦǋềǦƽươǃƼǦǋịǦǂƙǦđắǂǦǃƽấǉ,ǦǉƽượǃƼǦđầǊǦǃƽấǉ,ǦǉƽƔǦǃƽấǉǦđịǃƽǦǅƽảƾǦǁƐǦ——ǦƝƑǃƽǦǉǇƑǃƼǦƸǊốǃǦƽƐǃƽ!",
    ["还真是……有“滋味”……"] = "ĐƕǃƼǦǁƐ...ǦǇấǉǦƸƚǦ\"ƽươǃƼǦǋị\"...",
    ["游侠也喜欢吗！只是现下这个时节葱都被霜打了，要是等到春夏，一根完整的嫩葱，卷上煎饼，狠狠来一口……"] = "ǝǊǦƽƾệǅǦƸũǃƼǦǉƽƓƸƽǦǈƶǄ!ǦƞƽỉǦǁƐǦǉƾếǉǦǉǇờƾǦǁƕƸǦǃƐǓǦƽƐǃƽǦđềǊǦƷịǦǈươǃƼǦƼƾƑǦƸảǦǇồƾ,ǦǃếǊǦđợƾǦđếǃǦǂƖƶǦƳǊƁǃǦƣạ,ǦǂộǉǦƸọǃƼǦƽƐǃƽǦǃǄǃǦǋẹǃǦǃƼǊǓƙǃ,ǦƸǊốǃǦǋƐǄǦƷƑǃƽǦǉǇƑǃƼ,ǦƸắǃǦǂộǉǦǂƾếǃƼǦǉƽậǉǦǂạǃƽ...",
    ["那你方才说的老师傅们又在哪？需要帮厨打下手吗？"] = "ƱậǓǦǂấǓǦǋịǦǁƃǄǦǈưǦǅƽụǦǃƼươƾǦǋừƶǦǃƚƾǦđƶǃƼǦởǦđƁǊ?ǦƞƚǦƸầǃǦǅƽụǦƷếǅǦƼƾƕǅǦǂộǉǦǉƶǓǦǀƽƇǃƼ?",
    ["哦哦。这几位老师傅虽不再做生意，但烹油料理还是不在话下。到时候他们会把菜肴直接送到角门里。"] = "ỒǦồ.ǦƨấǓǦǋịǦǁƃǄǦǈưǦǅƽụǦǃƐǓǦǉǊǓǦǀƽƇǃƼǦƸƛǃǦǀƾǃƽǦǤǄƶǃƽǦǃữƶ,ǦǃƽưǃƼǦǋƾệƸǦƷếǅǦǃƕƸǦǃấǊǦǃướǃƼǦǋẫǃǦǀƽƇǃƼǦǉƽƐǃƽǦǋấǃǦđề.ǦĐếǃǦǁƕƸǦđƚǦƽọǦǈẽǦƼửƾǦǉǇựƸǦǉƾếǅǦǂƚǃǦăǃǦđếǃǦƢƾƑƸǦƨƇǃǦƧƈ.",
    ["只是他们做菜分量极大，还要麻烦游侠帮忙切分，好送与百姓。"] = "ƞƽỉǦǁƐǦƽọǦǁƐǂǦǂƚǃǦăǃǦǅƽƁǃǦǁượǃƼǦƸựƸǦǁớǃ,ǦƸƛǃǦǅƽảƾǦǅƽƾềǃǦǤǊǦƽƾệǅǦƼƾƕǅǦđỡǦƸắǉǦƸƽƾƶ,ǦđểǦǉƾệǃǦƼửƾǦƸƽǄǦƷƑƸƽǦǉƓǃƽ.",
    ["阁下，你方才说，城南边又有贼寇了？"] = "ƞƑƸǦƽạ,ǦǃƼươƾǦǋừƶǦǃƚƾ,ǦǅƽƓƶǦƩƶǂǦǉƽƐǃƽǦǁạƾǦƸƚǦƼƾặƸǦǀƽấǊǦǈƶǄ?",
    ["是啊，虽然一群杂兵没什么功夫，但势如蝗虫，竟也成了气候。"] = "ƫƽảƾ,ǦǉǊǓǦǁƐǦǂộǉǦǁũǦǉạǅǦƷƾǃƽǦǀƽƇǃƼǦƸƚǦƸƇǃƼǦǅƽǊǦƼƔ,ǦǃƽưǃƼǦǉƽếǦǃƽưǦƸƽƁǊǦƸƽấǊ,ǦǉƽếǦǂƐǦƸũǃƼǦǉạǄǦǉƽƐǃƽǦǀƽƓǦƽậǊ.",
    ["我联系了墨山道的朋友，她送来几件稀罕机巧，抵御贼寇不在话下。怎么说，一起去？"] = "ǥƶǦđƃǦǁƾƙǃǦǁạƸǦǋớƾǦƷằǃƼǦƽữǊǦƷƙǃǦƨặƸǦƮơǃǦĐạǄ,ǦǃƐǃƼǦƼửƾǦǉớƾǦǋƐƾǦǂƚǃǦƸơǦǍảǄǦƽƾếǂǦǁạ,ǦƸƽốǃƼǦǁạƾǦƼƾặƸǦǀƽấǊǦǀƽƇǃƼǦǉƽƐǃƽǦǋấǃǦđề.ǦƮƶǄǦƽả,ǦƸƖǃƼǦđƾǦƸƽứ?",
    ["阁下，方才说的“乘驿轩”的车马，是怎么回事？"] = "ƞƑƸǦƽạ,ǦƸƽǊǓệǃǦǋềǦǍƺǦǃƼựƶǦƸủƶǦ\"ǥƽừƶǦƣƾƙǃǦǝịƸƽ\"ǦǋừƶǦǃƚƾǦǁƐǦǉƽếǦǃƐǄ?",
    ["乘驿轩是开封租赁车马之地，近来需求量大，需得依序取号，城中更是因此有了倒卖排号牟利之事。"] = "ǥƽừƶǦƣƾƙǃǦǝịƸƽǦǁƐǦǃơƾǦƸƽǄǦǉƽǊƙǦǍƺǦǃƼựƶǦởǦƦƽƶƾǦƫƽǄǃƼ,ǦƼầǃǦđƁǓǦǃƽǊǦƸầǊǦǁớǃ,ǦǅƽảƾǦǁấǓǦǈốǦǉƽƺǄǦǉƽứǦǉự,ǦǉǇǄǃƼǦǉƽƐǃƽǦǋƔǦǉƽếǦǂƐǦǃảǓǦǈƾǃƽǦƸƽǊǓệǃǦđầǊǦƸơǦƷƑǃǦǁạƾǦǈốǦǉƽứǦǉựǦđểǦǉǇụƸǦǁợƾ.",
    ["游侠若是想要助开封城缓解车马交通之难，不如前去看看。"] = "ǝǊǦƽƾệǅǦǃếǊǦǂǊốǃǦƼƾƕǅǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦƼƾảǂǦƷớǉǦǀƽƚǦǀƽăǃǦǋềǦƼƾƶǄǦǉƽƇǃƼǦǍƺǦǃƼựƶ,ǦƸƽƾǦƷằǃƼǦƽƃǓǦđếǃǦđƚǦǍƺǂǦǉƽử.",
    ["如何？游侠有何高见？"] = "ǥƽếǦǃƐǄ?ǦǝǊǦƽƾệǅǦƸƚǦƸƶǄǦǀƾếǃǦƼƔǦǀƽƇǃƼ?",
    ["高见谈不上，倒是有了些思路……"] = "ƞƶǄǦǀƾếǃǦǉƽƔǦǀƽƇǃƼǦǤƑǂ,ǦǃƽưǃƼǦƸũǃƼǦđƃǦƸƚǦƸƽƕǉǦǂƶǃƽǦǂốƾ...",
    ["眼下开封城民生之困，说到底就是缺少人力。只要动起来，问题总能解决。"] = "ƞƑƾǦǀƽƚǦǤƁǃǦǈƾǃƽǦƸủƶǦǉƽƐǃƽǦƦƽƶƾǦƫƽǄǃƼǦǁƕƸǦǃƐǓ,ǦǃƚƾǦƸƽǄǦƸƖǃƼǦƸƽƓǃƽǦǁƐǦǉƽƾếǊǦǃƽƁǃǦǁựƸ.ǦƞƽỉǦƸầǃǦƽƐǃƽǦđộǃƼ,ǦǋấǃǦđềǦắǉǦǈẽǦđượƸǦƼƾảƾǦǆǊǓếǉ.",
    ["游侠倒是个麻利的。那就听你的，先干起来再说！"] = "ǝǊǦƽƾệǅǦǆǊảǦǁƐǦǃƼườƾǦǃƽƶǃƽǦǃƽẹǃ.ǦƱậǓǦǉƽƔǦǃƼƽƺǦǉƽƺǄǦǃƼươƾ,ǦƸứǦǁƐǂǦǉǇướƸǦǇồƾǦǉƓǃƽǦǈƶǊ!",
    ["三桩事难分轻重，游侠，还请你来定夺。我等自会从旁协助。"] = "ƝƶǦǋƾệƸǦǃƐǓǦǀƽƚǦǅƽƁǃǦǃặǃƼǦǃƽẹ,ǦǤǊǦƽƾệǅ,ǦƸƛǃǦǅƽƾềǃǦǃƼươƾǦđịǃƽǦđǄạǉ.ǦƞƽƕǃƼǦǉƶǦǉựǦǈẽǦǉừǦƷƙǃǦƸạǃƽǦƽỗǦǉǇợ.",
    ["不如也唤上其他各门的朋友。若能共行侠义，解此困境，那可也算得上是江湖盛举！"] = "ƣƶǓǦǁƐǦƸũǃƼǦƼọƾǦƸảǦƷằǃƼǦƽữǊǦƸƑƸǦǂƇǃǦǅƽƑƾǦǀƽƑƸ.ǦƩếǊǦƸƚǦǉƽểǦƸƖǃƼǦƽƐǃƽǦƽƾệǅǦǉǇượǃƼǦǃƼƽĩƶ,ǦƼƾảƾǦǆǊǓếǉǦǀƽốǃǦƸảǃƽǦǃƐǓ,ǦđƚǦƸũǃƼǦƸƚǦǉƽểǦƸǄƾǦǁƐǦǂộǉǦǈựǦǀƾệǃǦǉǇọǃƼǦđạƾǦǉǇǄǃƼǦƼƾƶǃƼǦƽồ!",
    ["别吵了别吵了，诶诶诶，也别动手啊！"] = "ĐừǃƼǦƸƃƾǦǃữƶǦđừǃƼǦƸƃƾǦǃữƶ,ǦƙǦƙǦƙ,ǦƸũǃƼǦđừǃƼǦđộǃƼǦǉƽủǦǃƽƶ!",
    ["马富贵"] = "ƨƃǦƫƽƕǦƬǊƈ",
    ["莫，莫要过来！再这样，我就，我就报官了啊！"] = "ĐừǃƼ,ǦđừǃƼǦǆǊƶǦđƁǓ!ǦƞƛǃǦǃƽưǦǋậǓ,ǦǉƶǦǈẽ,ǦǉƶǦǈẽǦƷƑǄǦǆǊƶǃǦđƚǦǃƽƶ!",
    ["皮重盖"] = "ƝƔǦǥǇọǃƼǦƞƑƾ",
    ["你还好意思报官？不要脸的家伙，现在倒是知道害怕了？"] = "ƩƼươƾǦƸƛǃǦǂặǉǦǂũƾǦƷƑǄǦǆǊƶǃǦǈƶǄ?ǦĐồǦǀƽƇǃƼǦƷƾếǉǦǍấǊǦƽổ,ǦƼƾờǦǁạƾǦƷƾếǉǦǈợǦǇồƾǦƐ?",
    ["包能干"] = "ƝƶǄǦƩăǃƼǦƞƶǃ",
    ["还要多久才到俺啊……"] = "ƞƛǃǦƷƶǄǦǁƁǊǦǃữƶǦǂớƾǦđếǃǦǁượǉǦǉƶǦđƁǓ...",
    ["麻跳跳"] = "ƨƶǦƦƽƾƙǊǦƦƽƾƙǊ",
    ["郝昊齐"] = "ƣƑƸǦƣạǄǦǥề",
    ["别跑了，回来把钱还给人家。不然……"] = "ĐừǃƼǦƸƽạǓǦǃữƶ,ǦǆǊƶǓǦǁạƾǦǉǇảǦǉƾềǃǦƸƽǄǦǃƼườƾǦǉƶǦđƾ.ǦƩếǊǦǀƽƇǃƼ...",
    ["我错了我错了，我还，我还还不成嘛……"] = "ǥƶǦǈƶƾǦǇồƾǦǉƶǦǈƶƾǦǇồƾ,ǦǉƶǦǉǇả,ǦǉƶǦǉǇảǦǀƽƇǃƼǦđượƸǦǈƶǄ...",
    ["多谢游侠出手相助！只是我眼下似乎没有什么能作为感谢的……"] = "ĐƶǦǉạǦǤǊǦƽƾệǅǦđƃǦǇƶǦǉƶǓǦǉươǃƼǦǉǇợ!ǦƞƽỉǦǁƐǦǁƕƸǦǃƐǓǦǉƶǦǤườǃƼǦǃƽưǦǀƽƇǃƼǦƸƚǦƼƔǦƸƚǦǉƽểǦǁƐǂǦǋậǉǦƸảǂǦǉạ...",
    ["多谢游侠了！我这口恶气总算能发出去了……一、二、三……不对，怎么我前头还有那么多人？！那我怎么赶得及上工？！"] = "ĐƶǦǉạǦǤǊǦƽƾệǅǦǇồƾ!ǦƞơǃǦƼƾậǃǦǃƐǓǦƸủƶǦǉƶǦǇốǉǦƸǊộƸǦƸũǃƼǦǅƽƑǉǦǉƾếǉǦǇƶǦđượƸ...Ǧǂộǉ,Ǧƽƶƾ,ǦƷƶ...ǦǀƽƇǃƼǦđƕǃƼ,ǦǈƶǄǦǅƽƓƶǦǉǇướƸǦǉƶǦǋẫǃǦƸƛǃǦǃƽƾềǊǦǃƼườƾǦǉƽếǦǃƐǓ?!ǦƱậǓǦǈƶǄǦǉƶǦǀịǅǦƼƾờǦǁƐǂǦǋƾệƸǦđƁǓ?!",
    ["“乘轩驿赁马车排号表”？你们这是在排队赁马车？"] = "\"ƝảǃƼǦǍếǅǦƽƐǃƼǦǉƽǊƙǦǍƺǦǃƼựƶǦǥƽừƶǦƣƾƙǃǦǝịƸƽ\"?ǦƞƑƸǦǃƼươƾǦđƶǃƼǦǍếǅǦƽƐǃƼǦǉƽǊƙǦǍƺǦǃƼựƶǦǈƶǄ?",
    ["是啊。城内的马本就不多，这几日又是良宵佳节，大家走街串巷的，送礼送货的，哪哪都得用到马，如今只能紧着来。"] = "ƫƽảƾǦđƚ.ǦƩƼựƶǦǉǇǄǃƼǦǉƽƐǃƽǦǋốǃǦǀƽƇǃƼǦǃƽƾềǊ,ǦǂấǓǦǃƼƐǓǦǃƶǓǦǁạƾǦǁƐǦǁươǃƼǦǉƾƙǊǦƼƾƶƾǦǉƾếǉ,ǦǂọƾǦǃƼườƾǦǤạǄǦǅƽốǦƷăǃƼǦǃƼƅ,ǦǉặǃƼǦǆǊƐǦƼƾƶǄǦƽƐǃƼ,ǦƸƽỗǦǃƐǄǦƸũǃƼǦƸầǃǦǤƖǃƼǦǃƼựƶ,ǦǃƶǓǦƸƽỉǦƸƚǦǉƽểǦǍếǅǦƽƐǃƼǦǉƽƇƾ.",
    ["可是……这儿不是还有几头驴子可赁么？"] = "ƩƽưǃƼ...ǦởǦđƁǓǦǀƽƇǃƼǦǅƽảƾǦǋẫǃǦƸƛǃǦǂấǓǦƸǄǃǦǁừƶǦƸƚǦǉƽểǦǉƽǊƙǦǈƶǄ?",
    ["……我们若是会骑驴子，方便骑驴子，定然早就赁驴出发了！哪还用排那么长的队呢……"] = "……ƞƽƕǃƼǦǉƶǦǃếǊǦƷƾếǉǦƸưỡƾǦǁừƶ,ǦǉƽǊậǃǦǉƾệǃǦƸưỡƾǦǁừƶ,ǦǉƽƔǦđƃǦǈớǂǦǉƽǊƙǦǁừƶǦǍǊấǉǦǅƽƑǉǦǇồƾ!ǦĐƁǊǦƸầǃǦǅƽảƾǦǍếǅǦƽƐǃƼǦǤƐƾǦǉƽếǦǃƐǓǦƸƽứ……",
    ["早知如此，当初就不该没事去逗驴子玩，这样我就不会被驴子撅了，更不会怕驴子，现在也不用白等……"] = "ƮớǂǦƷƾếǉǦǉƽếǦǃƐǓ,ǦƷƶǃǦđầǊǦđƃǦǀƽƇǃƼǦǃƙǃǦǇảǃƽǦǇỗƾǦđƾǦƸƽọƸǦǁừƶǦƸƽơƾ,ǦǃƽưǦǋậǓǦǉƶǦǈẽǦǀƽƇǃƼǦƷịǦǁừƶǦđƑ,ǦƸƐǃƼǦǀƽƇǃƼǦǈợǦǁừƶ,ǦƼƾờǦƸũǃƼǦǀƽƇǃƼǦǅƽảƾǦƸƽờǦǀƽƇǃƼǦƸƇǃƼǦǉƽếǦǃƐǓ……",
    ["小友此行，可曾寻到新的物料？"] = "ǥƾểǊǦƽữǊǦƸƽǊǓếǃǦǃƐǓ,ǦđƃǦǉƔǂǦǉƽấǓǦǃƼǊǓƙǃǦǁƾệǊǦǂớƾǦƸƽưƶ?",
    ["若是有了，且快快拿来，我二人也好略尽绵薄之力，助你为此地众生燃灯照情。"] = "ƩếǊǦđƃǦƸƚǦǇồƾǦǉƽƔǦƽƃǓǦǂƶǊǦđƺǂǦǉớƾ,ǦƽƶƾǦǉƶǦƸũǃƼǦƸƚǦǉƽểǦƼƚǅǦƸƽƕǉǦǈứƸǦǂọǃ,ǦƼƾƕǅǦǃƼươƾǦǋƔǦƸƽƕǃƼǦǈƾǃƽǦǃơƾǦǃƐǓǦǂƐǦǉƽắǅǦđƘǃǦǈǄƾǦǉƔǃƽ.",
    ["灯花未满，时机不至。小友，且再到处走走。"] = "ƣǄƶǦđƘǃǦƸƽưƶǦđầǓ,ǦǉƽờƾǦƸơǦƸƽưƶǦǉớƾ.ǦǥƾểǊǦƽữǊ,ǦƽƃǓǦđƾǦǤạǄǦǍǊǃƼǦǆǊƶǃƽǦǉƽƙǂǦƸƽƕǉǦǃữƶ.",
    ["要我说，这宫里头，就数咱宝慈宫의差事最美。你闻闻，风里都带着一股甜甜的香。"] = "ĐểǦǉƶǦǃƚƾǦƸƽǄǦǃƼƽƺ,ǦởǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓ,ǦǋƾệƸǦởǦƝảǄǦǥừǦƞǊǃƼǦǉƶǦǁƐǦǉốǉǦǃƽấǉ.ǦƩƼươƾǦǃƼửƾǦǍƺǂ,ǦǉǇǄǃƼǦƼƾƚǦƸƛǃǦǂƶǃƼǦǉƽƺǄǦǂộǉǦǂƖƾǦƽươǃƼǦǃƼọǉǦǃƼƐǄ.",
    ["娘子们用的熏香，就是好闻，我喜欢这儿！"] = "ƣươǃƼǦƽǊƁǃǦƸƑƸǦǃươǃƼǦǉửǦǤƖǃƼǦǉƽậǉǦǁƐǦǉƽơǂ,ǦǉƶǦǉƽƓƸƽǦǃơƾǦǃƐǓ!",
    ["好幸福，皇帝의女人陪我当值。"] = "ǥƽậǉǦƽạǃƽǦǅƽƕƸ,ǦǃữǦǃƽƁǃǦƸủƶǦƽǄƐǃƼǦđếǦƸƖǃƼǦǉƶǦǉǇựƸǦƷƶǃ.",
    ["嘘！小声点，别大不敬！不过……嘿嘿……还真是这么回事。"] = "ƮǊỵǉ!ǦƩƽỏǦǉƾếǃƼǦǉƽƇƾ,ǦđừǃƼǦƸƚǦđạƾǦƷấǉǦǀƓǃƽ!ǦƩƽưǃƼǦǂƐ...ǦƽƔǦƽƔ...ǦđƕǃƼǦǁƐǦƸƽǊǓệǃǦǃƽưǦǋậǓǦǉƽậǉ.",
    ["这么一想，这漫长的一天，好像也没那么难熬了。"] = "ƩƼƽĩǦǃƽưǦǋậǓ,ǦǂộǉǦǃƼƐǓǦǤƐƾǦđằǃƼǦđẵǃƼǦǃƐǓǦǤườǃƼǦǃƽưǦƸũǃƼǦǀƽƇǃƼǦǀƽƚǦǋượǉǦǆǊƶǦđếǃǦǉƽế.",
    ["我突然觉得，有咱们这样苦中作乐的心态，干什么都会成功的！"] = "ǥƶǦđộǉǦǃƽƾƙǃǦƸảǂǦǉƽấǓ,ǦƸƚǦǉƁǂǦǉƽếǦǀƽổǦǉǇǊǃƼǦǉƑƸǦǁạƸǦǃƽưǦƸƽƕǃƼǦǉƶ,ǦǁƐǂǦƼƔǦƸũǃƼǦǈẽǦǉƽƐǃƽǦƸƇǃƼǦǉƽƇƾ!",
    ["大人，您来得刚好——"] = "ĐạƾǦǃƽƁǃ,ǦǃƼƐƾǦđếǃǦǉƽậǉǦđƕǃƼǦǁƕƸǦ——",
    ["银筝"] = "ƩƼƁǃǦǥǇƶǃƽ",
    ["有橙一枚，自阁中倒退而出，顷刻间化为甘汁。你猜为何？因为橙退了，这一退便是一杯汁！"] = "ƞƚǦǂộǉǦǆǊảǦƸƶǂ,ǦǉừǦǉǇǄǃƼǦƸƑƸǦǁƖƾǦǇƶǦǃƼǄƐƾ,ǦǉǇǄǃƼǦǃƽƑǓǦǂắǉǦƽƚƶǦǉƽƐǃƽǦǃướƸǦǃƼọǉ.ǦƩƼươƾǦđǄƑǃǦǍƺǂǦǉạƾǦǈƶǄ?ǦƝởƾǦǋƔǦƸƶǂǦđƃǦǁƖƾǦ(ƸƶǂǦǉƽǄƑƾ),ǦƸƑƾǦǁƖƾǦǃƐǓǦƸƽƓǃƽǦǁƐǦǂộǉǦǁǓǦǃướƸǦ(ƸƶǂǦƼƾƑǦǤǊ)!Ǧ",
    ["啊……我还是不够招笑……怎么办，秋招马上就要开始了。"] = "Ɯ...ǦǉƶǦǋẫǃǦƸƽưƶǦđủǦƷǊồǃǦƸườƾ...ǦǅƽảƾǦǁƐǂǦǈƶǄǦđƁǓ,ǦǥƽǊǦƞƽƾƙǊǦǈắǅǦƷắǉǦđầǊǦǇồƾ.",
    ["秋招？"] = "ǥƽǊǦƞƽƾƙǊ?",
    ["宝慈宫招洒扫宫人，秋姐姐的考核是讲笑话……所以我在同时修炼两样技能，努力成为秋姐姐说的复合型人才。"] = "ƝảǄǦǥừǦƞǊǃƼǦǉǊǓểǃǦƸǊǃƼǦǃƽƁǃǦǆǊƗǉǦǤọǃ,ǦǀƽảǄǦƽạƸƽǦƸủƶǦǥƽǊǦǉỷǦǉỷǦǁƐǦǀểǦƸƽǊǓệǃǦƸườƾ...ǦƸƽǄǦǃƙǃǦǉƶǦđƶǃƼǦđồǃƼǦǉƽờƾǦǉǊǦǁǊǓệǃǦƽƶƾǦǀỹǦǃăǃƼ,ǦǃỗǦǁựƸǦǉǇởǦǉƽƐǃƽǦǃƽƁǃǦǉƐƾǦđƶǦǃăǃƼǦǃƽưǦǁờƾǦǥƽǊǦǉỷǦǉỷǦǃƚƾ.",
    ["你讲笑话的本事是差些，不过主要看的是洒扫的本事吧。只要你够会扫地，长板足够长，应该也没问题的。"] = "ƝảǃǦǁĩǃƽǦǀểǦƸƽǊǓệǃǦƸườƾǦƸủƶǦǃƼươƾǦƽơƾǦǀƗǂ,ǦǃƽưǃƼǦƸƽủǦǓếǊǦǋẫǃǦǁƐǦǍƺǂǦƷảǃǦǁĩǃƽǦǆǊƗǉǦǤọǃǦƸƽứ.ǦƞƽỉǦƸầǃǦǃƼươƾǦƷƾếǉǦǆǊƗǉǦǃƽƐ,ǦǈởǦǉǇườǃƼǦđủǦǂạǃƽ,ǦƸƽắƸǦǁƐǦǀƽƇǃƼǦǋấǃǦđềǦƼƔǦđƁǊ.",
    ["大人，您看我扫得怎么样！"] = "ĐạƾǦǃƽƁǃ,ǦǃƼƐƾǦǍƺǂǦǉƶǦǆǊƗǉǦǉƽếǦǃƐǄ!",
    ["不错不错，但我有一招——"] = "ǥốǉ,ǦǉốǉǦǁắǂ,ǦǃƽưǃƼǦǉƶǦƸƚǦǂộǉǦƸƽƾƙǊǦ——",
    ["秋风扫落叶！"] = "ǥƽǊǦƫƽǄǃƼǦǥảǄǦƧạƸǦǝƾệǅ!",
    ["哇——！好快得扫！能教教我吗？"] = "ƪƶǦ——!ǦƬǊƗǉǦǃƽƶǃƽǦǆǊƑ!ǦƞƚǦǉƽểǦǤạǓǦǉƶǦǀƽƇǃƼ?",
    ["我这招，学起来可不容易。"] = "ƞƽƾƙǊǦǃƐǓǦƸủƶǦǉƶ,ǦƽọƸǦđượƸǦǀƽƇǃƼǦǤễǦđƁǊ.",
    ["……秋风扫落叶！"] = "...ǥƽǊǦƫƽǄǃƼǦǥảǄǦƧạƸǦǝƾệǅ!",
    ["风竹，银筝，宝慧，乱红……念到名字的“笑招生”，跟我过来。"] = "ƫƽǄǃƼǦǥǇƕƸ,ǦƩƼƁǃǦǥǇƶǃƽ,ǦƝảǄǦǥǊệ,ǦƧǄạǃǦƣồǃƼ...ǦǃƽữǃƼǦ\"ǉƾếǊǦƸƽƾƙǊǦǈƾǃƽ\"ǦđượƸǦƼọƾǦǉƙǃ,ǦđƾǦǉƽƺǄǦǉƶ.",
    ["秋姐姐"] = "ǥƽǊǦǉỷǦǉỷ",
    ["秋姐姐，您可知如何区分真假大象？"] = "ǥƽǊǦǉỷǦǉỷ,ǦǉỷǦƸƚǦƷƾếǉǦǁƐǂǦǈƶǄǦǅƽƁǃǦƷƾệǉǦǋǄƾǦǉƽậǉǦǋǄƾǦƼƾảǦǀƽƇǃƼ?",
    ["风竹"] = "ƫƽǄǃƼǦǥǇƕƸ",
    ["只需将它们都扔进水中——真相自会浮出水面。"] = "ƞƽỉǦƸầǃǦǃƗǂǦƸƽƕǃƼǦǍǊốǃƼǦǃướƸǦ——ǦƸƽƁǃǦǉướǃƼǦ(ǋǄƾǦǉƽậǉ)ǦǈẽǦǉựǦǃổƾǦǁƙǃǦǂặǉǦǃướƸǦǉƽƇƾ.",
    ["不好笑，下一个。"] = "ƦƽƇǃƼǦƷǊồǃǦƸườƾ,ǦǃƼườƾǦǉƾếǅǦǉƽƺǄ.",
    ["秋姐姐，我倒是听过一个菌橙的故事，说有一日橙出门，偶遇菌菇而亡……因为菌要橙死，橙不得不死。"] = "ǥƽǊǦǉỷǦǉỷ,ǦǂǊộƾǦǁạƾǦǃƼƽƺǦǆǊƶǦǂộǉǦƸƁǊǦƸƽǊǓệǃǦǋềǦǃấǂǦǋƐǦƸƶǂ,ǦǃƚƾǦƸƚǦǂộǉǦǃƼƐǓǦƸƶǂǦđƾǦǇƶǦǃƼǄƐƾ,ǦǉƔǃƽǦƸờǦƼặǅǦǃấǂǦǂƐǦƸƽếǉ...ǦƷởƾǦǋƔǦǃấǂǦǂǊốǃǦƸƶǂǦƸƽếǉǦ(ƬǊƁǃǦǓếǊǦǉƽầǃǦǉử),ǦƸƶǂǦǀƽƇǃƼǦǉƽểǦǀƽƇǃƼǦƸƽếǉǦ(ǉƽầǃǦƷấǉǦđắƸǦƷấǉǦǉử).",
    ["宝慧"] = "ƝảǄǦǥǊệ",
    ["我以为，这笑话的妙处，不在于笑，而在于理。"] = "ƨǊộƾǦǃƼƽĩ,ǦƸƑƾǦƽƶǓǦƸủƶǦƸƽǊǓệǃǦƸườƾǦǃƐǓǦǀƽƇǃƼǦǃằǂǦởǦǉƾếǃƼǦƸườƾ,ǦǂƐǦǃằǂǦởǦđạǄǦǁƈ.",
    ["知规矩，守本分，才是我们宫人该摆在第一位的。"] = "ƣƾểǊǦǆǊǓǦƸủ,ǦƼƾữǦƷổǃǦǅƽậǃ,ǦǂớƾǦǁƐǦđƾềǊǦƸǊǃƼǦǃƽƁǃǦƸƽƕǃƼǦǉƶǦǃƙǃǦđặǉǦǁƙǃǦƽƐǃƼǦđầǊ.",
    ["倒是个机灵的，不错，留下候着吧。"] = "ĐƕǃƼǦǁƐǦǂộǉǦǀẻǦǁƶǃƽǦǁợƾ,Ǧǉốǉ,ǦởǦǁạƾǦƸƽờǦđƾ.",
    ["谢谢姐姐！"] = "ǥạǦơǃǦǉỷǦǉỷ!",
    ["秋姐姐，这个笑话还有后续！说这个橙子，以酱涂身，反而存活，因为酱在外，菌令有所不受。哈哈哈……"] = "ǥƽǊǦǉỷǦǉỷ,ǦƸƽǊǓệǃǦƸườƾǦǃƐǓǦƸƛǃǦƸƚǦƽậǊǦƷảǃ!ǦƩƚƾǦǆǊảǦƸƶǂǦđƚǦǁấǓǦǉươǃƼǦƷƇƾǦǁƙǃǦǉƽƁǃ,ǦǃƼượƸǦǁạƾǦǈốǃƼǦǈƚǉ,ǦƷởƾǦǋƔǦǉươǃƼǦởǦǃƼǄƐƾǦ(ǥướǃƼǦǉạƾǦǃƼǄạƾ),ǦǁệǃƽǦƸủƶǦǃấǂǦ(ƬǊƁǃǦǁệǃƽ)ǦƸƚǦƸƽỗǦǀƽƇǃƼǦǃƽậǃ.ǦƣƶǦƽƶǦƽƶ...",
    ["拾人牙慧，还敢讲“君令有所不受”？下一个！"] = "ƣọƸǦđƛƾǦǋăǃǦǋẻ,ǦƸƛǃǦǤƑǂǦǃƚƾǦ\"ƬǊƁǃǦǁệǃƽǦƽữǊǦǈởǦƷấǉǦǉƽụ\"?ǦƩƼườƾǦǉƾếǅǦǉƽƺǄ!",
    ["你们招的不是洒扫宫女吗，现在是仅凭讲笑话选人，不看洒扫了？"] = "ƞƑƸǦǃƼườƾǦǀƽƇǃƼǦǅƽảƾǦǉǊǓểǃǦƸǊǃƼǦǃữǦǆǊƗǉǦǤọǃǦǈƶǄ,ǦƼƾờǦǁạƾǦƸƽỉǦǤựƶǦǋƐǄǦǀểǦƸƽǊǓệǃǦƸườƾǦđểǦƸƽọǃǦǃƼườƾ,ǦǀƽƇǃƼǦǍƺǂǦǋƾệƸǦǆǊƗǉǦǤọǃǦƐ?",
    ["哦，是武德司的大人啊，头一回见咱们宝慈宫秋选？"] = "Ồ,ǦǁƐǦđạƾǦǃƽƁǃǦƸủƶǦƱƅǦĐứƸǦǥǓǦƐ,ǦǁầǃǦđầǊǦǉƽấǓǦǥƽǊǦǉǊǓểǃǦƸủƶǦƝảǄǦǥừǦƞǊǃƼǦƸƽƕǃƼǦǉƶǦǈƶǄ?",
    ["本次秋选所招的洒扫宫人，虽司洒扫之职，更多时候却要与我一同侍奉娘子左右，做个体己人，这才以笑话论高下。"] = "ǥƽǊǦǉǊǓểǃǦǁầǃǦǃƐǓǦƸƽƾƙǊǦǂộǦƸǊǃƼǦǃƽƁǃǦǆǊƗǉǦǤọǃ,ǦǉǊǓǦƼƾữǦƸƽứƸǦǆǊƗǉǦǤọǃ,ǦǃƽưǃƼǦǅƽầǃǦǁớǃǦǉƽờƾǦƼƾƶǃǦǁạƾǦǅƽảƾǦƸƖǃƼǦǉƶǦƽầǊǦƽạǦƷƙǃǦƸạǃƽǦǃươǃƼǦǉử,ǦǁƐǂǦǃƼườƾǦǉƽƁǃǦƸậǃ,ǦǃƙǃǦǂớƾǦǁấǓǦƸƽǊǓệǃǦƸườƾǦđểǦđịǃƽǦƸƶǄǦǉƽấǅ.",
    ["我老家不是这样的……我家那边招人，看得都是手脚是否麻利，心思是否实在。"] = "ƧƃǄǦƼƾƶǦƸủƶǦǉƶǦǀƽƇǃƼǦǃƽưǦǋậǓ...ǦƸƽỗǦǃƽƐǦǉƶǦǉǊǓểǃǦǃƼườƾ,ǦđềǊǦǍƺǂǦǉƶǓǦƸƽƁǃǦƸƚǦǁƶǃƽǦǁẹǦǀƽƇǃƼ,ǦǁƛǃƼǦǤạǦƸƚǦǉƽƐǃƽǦǉƽậǉǦǀƽƇǃƼ.",
    ["宫里有宫里的规矩，和外面可不一样。在宝慈宫，会不会扫地可不打紧。若是招个能说笑话的，聊天的时候逗娘子开心，那可是天大的本事。"] = "ǥǇǄǃƼǦƸǊǃƼǦƸƚǦǆǊǓǦƸủǦƸủƶǦǉǇǄǃƼǦƸǊǃƼ,ǦǀƽƑƸǦƽẳǃǦƷƙǃǦǃƼǄƐƾ.ǦỞǦƝảǄǦǥừǦƞǊǃƼ,ǦƷƾếǉǦǆǊƗǉǦđấǉǦƽƶǓǦǀƽƇǃƼǦǀƽƇǃƼǦǆǊƶǃǦǉǇọǃƼ.ǦƩếǊǦƸƽƾƙǊǦǂộǦđượƸǦǀẻǦƷƾếǉǦǃƚƾǦƸƽǊǓệǃǦƸườƾ,ǦǁƕƸǦǉǇƛǦƸƽǊǓệǃǦǁƐǂǦǃươǃƼǦǉửǦǋǊƾǦǋẻ,ǦđƚǦǂớƾǦǁƐǦƷảǃǦǈựǦǀƾǃƽǦǉƽƾƙǃǦđộǃƼǦđịƶ.",
    ["你们这招的是宫人吗，还是招瓦子耍猴的？"] = "ƞƑƸǦǃƼườƾǦǉǊǓểǃǦƸǊǃƼǦǃƽƁǃ,ǦƽƶǓǦǁƐǦǉǊǓểǃǦǀƽỉǦǤƾễǃǦǉǇƛǦởǦƩƼƅƶǦǥửǦǋậǓ?",
    ["大人，说句不好听的，在宝慈宫当差，扫的是公家的地，笑话却是自己人听的笑话。我们账算得很清。"] = "ĐạƾǦǃƽƁǃ,ǦǃƚƾǦƸƁǊǦǀƽƚǦǃƼƽƺ,ǦǁƐǂǦǋƾệƸǦởǦƝảǄǦǥừǦƞǊǃƼ,ǦǆǊƗǉǦǁƐǦǆǊƗǉǦđấǉǦƸủƶǦƸƇǃƼ,ǦǃƽưǃƼǦƸƽǊǓệǃǦƸườƾǦǁƐǦƸƽǊǓệǃǦƸƽǄǦǃƼườƾǦǂƔǃƽǦǃƼƽƺ.ǦƞƽƕǃƼǦǉƶǦǉƓǃƽǦǉǄƑǃǦǈổǦǈƑƸƽǦǇấǉǦǇƅǦǇƐǃƼ.",
    ["账算得清？笑不笑可不是能算出来的。"] = "ǥƓǃƽǦǉǄƑǃǦǇƅǦǇƐǃƼ?ǦƞườƾǦƽƶǓǦǀƽƇǃƼǦđƁǊǦƸƚǦǉƓǃƽǦǇƶǦđượƸ.",
    ["姐姐，姐姐您怎么了！"] = "ǥỷǦǉỷ,ǦǉỷǦǉỷǦǉỷǦƷịǦǁƐǂǦǈƶǄǦǋậǓ!",
    ["哈哈哈哈哈哈！不、不可能……哈哈哈哈哈……"] = "ƣƶǦƽƶǦƽƶǦƽƶǦƽƶǦƽƶ!ǦƦƽƇǃƼ,ǦǀƽƇǃƼǦǉƽểǦǃƐǄ...ǦƽƶǦƽƶǦƽƶǦƽƶǦƽƶ...",
    ["我什么都没讲，你却笑了，你能断定娘子也定会开怀？"] = "ǥƶǦƸƽưƶǦǃƚƾǦƼƔǦǂƐǦǃƼươƾǦđƃǦƸườƾ,ǦǃƼươƾǦƸƚǦǉƽểǦǀƽẳǃƼǦđịǃƽǦǃươǃƼǦǉửǦƸũǃƼǦǃƽấǉǦđịǃƽǦǈẽǦǋǊƾǦǁƛǃƼ?",
    ["哈哈哈……你！哈哈哈……伶牙俐齿……哈哈哈！"] = "ƣƶǦƽƶǦƽƶ...ǦǃƼươƾ!ǦƣƶǦƽƶǦƽƶ...ǦǉƽậǉǦǁƐǦǂồǂǦǁǄƶǦǂƗǅǦƼƾảƾ...ǦƽƶǦƽƶǦƽƶ!",
    ["秋娘，$T(5037)说得不错，单以笑选人，确有失偏颇。"] = "ǥƽǊǦƩươǃƼ,Ǧ$T(5037)ǦǃƚƾǦǀƽƇǃƼǦǈƶƾ,ǦƸƽỉǦǤựƶǦǋƐǄǦǃụǦƸườƾǦđểǦƸƽọǃǦǃƼườƾ,ǦđƕǃƼǦǁƐǦƸƚǦǅƽầǃǦǅƽƾếǃǦǤƾệǃ.",
    ["听军士方才所言，似乎对招人之道颇有心得，不知军士有高见？"] = "ƩƼƽƺǦǁờƾǦǆǊƁǃǦǈĩǦǋừƶǦǃƚƾ,ǦǤườǃƼǦǃƽưǦđốƾǦǋớƾǦđạǄǦǉǊǓểǃǦǃƼườƾǦǇấǉǦƸƚǦǉƁǂǦđắƸ,ǦǀƽƇǃƼǦƷƾếǉǦǆǊƁǃǦǈĩǦƸƚǦƸƶǄǦǀƾếǃǦƼƔ?",
    ["我没什么经验……只是从前看过家里人招伙计。"] = "ǥƶǦǀƽƇǃƼǦƸƚǦǀƾǃƽǦǃƼƽƾệǂǦƼƔ...ǦƸƽỉǦǁƐǦǉǇướƸǦǀƾƶǦǉừǃƼǦǉƽấǓǦǃƼườƾǦǃƽƐǦǉǊǓểǃǦƼƾƶǦǃƽƁǃ.",
    ["无论招的是灶上的师傅，还是堂前的帮工，都需当面考较一番，方能定下人选。"] = "ǝƖǦǁƐǦǉǊǓểǃǦđầǊǦƷếǅǦǤướƾǦƷếǅ,ǦƽƶǓǦǁƐǦǃƼườƾǦƼƾƕǅǦǋƾệƸǦǉǇƙǃǦǈảǃƽ,ǦđềǊǦƸầǃǦǅƽảƾǦǀƽảǄǦƽạƸƽǦǉǇựƸǦǉƾếǅǦǂộǉǦǅƽƺǃǦǂớƾǦƸƚǦǉƽểǦđịǃƽǦǇƶǦǃƽƁǃǦǉǊǓểǃ.",
    ["愿入宝慈宫者不计其数，若逐一相见，你想累死娘子不成？"] = "ƩƼườƾǦǂǊốǃǦǋƐǄǦƝảǄǦǥừǦƞǊǃƼǦđếǂǦǀƽƇǃƼǦǍǊể,ǦǃếǊǦƼặǅǦǂặǉǦǉừǃƼǦǃƼườƾǦǂộǉ,ǦǃƼươƾǦǂǊốǃǦǃươǃƼǦǉửǦǂệǉǦƸƽếǉǦǈƶǄ?",
    ["既然如此，何不让她们一同前来，一并考较？"] = "ĐƃǦǋậǓ,ǦǈƶǄǦǀƽƇǃƼǦđểǦƷọǃǦƽọǦƸƖǃƼǦǉớƾ,ǦǀƽảǄǦƽạƸƽǦǂộǉǦǁượǉ?",
    ["一同……考较？你的意思是……将众人齐聚一堂，设下同一道考题，观其应对，择优而录……群面是吧？"] = "ƞƖǃƼ...ǦǀƽảǄǦƽạƸƽ?ǦÝǦƸủƶǦǃƼươƾǦǁƐ...ǦǉậǅǦƽợǅǦǂọƾǦǃƼườƾǦǁạƾǦǂộǉǦƸƽỗ,ǦǇƶǦƸƖǃƼǦǂộǉǦđềǦƷƐƾ,ǦǆǊƶǃǦǈƑǉǦƸƑƸƽǦứǃƼǦđốƾ,ǦƸƽọǃǦǃƼườƾǦưǊǦǉƕǦǂƐǦǃƽậǃ...ǦǅƽỏǃƼǦǋấǃǦǃƽƚǂǦǅƽảƾǦǀƽƇǃƼ?",
    ["群面之法，既省时日，又见真章，秋娘，试试吧。"] = "ƫƽươǃƼǦǅƽƑǅǦǅƽỏǃƼǦǋấǃǦǃƽƚǂǦǃƐǓ,ǦǋừƶǦǉƾếǉǦǀƾệǂǦǉƽờƾǦƼƾƶǃ,ǦǁạƾǦǋừƶǦǉƽấǓǦđượƸǦǉƽựƸǦǁựƸ,ǦǥƽǊǦƩươǃƼ,ǦǉƽửǦǍƺǂǦđƾ.",
    ["娘子圣明，我这便去传话，宝慈宫群面，正式开始——"] = "ƩươǃƼǦǉửǦǉƽƑǃƽǦǂƾǃƽ,ǦǉƶǦđƾǦǉǇǊǓềǃǦǉƾǃǦǃƼƶǓǦđƁǓ,ǦƝảǄǦǥừǦƞǊǃƼǦǅƽỏǃƼǦǋấǃǦǃƽƚǂ,ǦƸƽƓǃƽǦǉƽứƸǦƷắǉǦđầǊǦ——",
    ["秋娘是宫里的旧人了，往年遴选宫人，一向由她操持。"] = "ǥƽǊǦƩươǃƼǦǁƐǦǃƼườƾǦƸũǦǉǇǄǃƼǦƸǊǃƼǦǇồƾ,ǦǃƽữǃƼǦǃăǂǦǉǇướƸǦǉǊǓểǃǦƸƽọǃǦƸǊǃƼǦǃƽƁǃǦǁǊƇǃǦǤǄǦǂộǉǦǉƶǓǦǃƐǃƼǦǁǄǦǁƾệǊ.",
    ["这法子既由军士所创，你不妨留下一起看看群面如何？"] = "ƫƽươǃƼǦǅƽƑǅǦǃƐǓǦđƃǦǤǄǦǆǊƁǃǦǈĩǦǃƼƽĩǦǇƶ,ǦǃƼươƾǦƸƽƾǦƷằǃƼǦởǦǁạƾǦƸƖǃƼǦǍƺǂǦǅƽỏǃƼǦǋấǃǦǃƽƚǂǦǉƽếǦǃƐǄ?",
    ["宝慧、乱红、银筝、花落，都听仔细了——"] = "ƝảǄǦǥǊệ,ǦƧǄạǃǦƣồǃƼ,ǦƩƼƁǃǦǥǇƶǃƽ,ǦƣǄƶǦƧạƸ,ǦđềǊǦǃƼƽƺǦƸƽǄǦǀỹǦđƁǓǦ——",
    ["今日老夫人来访，偏生宝慈宫只备了一杯新茶。此茶，是该奉与娘子，还是该敬与老夫人？"] = "ƣƇǂǦǃƶǓǦǁƃǄǦǅƽǊǦǃƽƁǃǦǉớƾǦǉƽăǂ,ǦƸƽẳǃƼǦǂƶǓǦƝảǄǦǥừǦƞǊǃƼǦƸƽỉǦƸƽǊẩǃǦƷịǦđượƸǦǂộǉǦƸƽƗǃǦǉǇƐǦǂớƾ.ǦƞƽƗǃǦǉǇƐǦǃƐǓ,ǦǃƙǃǦǤƁǃƼǦƸƽǄǦǃươǃƼǦǉử,ǦƽƶǓǦǃƙǃǦǀƓǃƽǦǁƃǄǦǅƽǊǦǃƽƁǃ?",
    ["你们有一炷香의工夫，就此题自行相商，须得拿出个章程来。"] = "ƞƑƸǦǃƼươƾǦƸƚǦǉƽờƾǦƼƾƶǃǦǂộǉǦǃƗǃǦǃƽƶǃƼ,ǦƽƃǓǦǉựǦǂƔǃƽǦǉƽươǃƼǦǁượǃƼǦǋềǦđềǦƷƐƾǦǃƐǓ,ǦǅƽảƾǦđưƶǦǇƶǦđượƸǦǂộǉǦǅƽươǃƼǦƑǃǦǇƅǦǇƐǃƼ.",
    ["茶为解渴之物，而非尊卑之礼。此茶当奉与需要之人，谁更口渴，就将茶奉给谁。"] = "ǥǇƐǦǁƐǦǋậǉǦƼƾảƾǦǀƽƑǉ,ǦƸƽứǦǀƽƇǃƼǦǅƽảƾǦǁễǦǃƼƽƾǦǉƇǃǦǉƾ.ǦƞƽƗǃǦǉǇƐǦǃƐǓǦǃƙǃǦǤƁǃƼǦƸƽǄǦǃƼườƾǦƸầǃǦǃƚ,ǦƶƾǦǀƽƑǉǦƽơǃǦǉƽƔǦǤƁǃƼǦƸƽǄǦǃƼườƾǦđƚ.",
    ["乱红"] = "ƧǄạǃǦƣồǃƼ",
    ["若奉给了娘子，老夫人一路辛劳，宝慈宫却连杯热茶都端不出——传出去，岂不是要让咱们娘子担上一个怠慢长辈、不忠不孝의罪名？"] = "ƩếǊǦǤƁǃƼǦƸƽǄǦǃươǃƼǦǉử,ǦǁƃǄǦǅƽǊǦǃƽƁǃǦđườǃƼǦǍƑǦǋấǉǦǋả,ǦƝảǄǦǥừǦƞǊǃƼǦǁạƾǦđếǃǦǂộǉǦƸƽƗǃǦǉǇƐǦǃƚǃƼǦƸũǃƼǦǀƽƇǃƼǦƷưǃƼǦǇƶǦđượƸǦ——ǦǉǇǊǓềǃǦǇƶǦǃƼǄƐƾ,ǦƸƽẳǃƼǦǅƽảƾǦǀƽƾếǃǦǃươǃƼǦǉửǦǃƽƐǦǉƶǦǅƽảƾǦƼƑǃƽǦǉộƾǦǤƶǃƽǦđƃƾǦǃƼộǦǉǇưởǃƼǦƷốƾǦǀƽƇǃƼǦƸƽǊǦđƑǄ,ǦƷấǉǦǉǇǊǃƼǦƷấǉǦƽƾếǊǦǈƶǄ?",
    ["呀，还真是，那给老夫人？"] = "Ɯ,ǦđƕǃƼǦǉƽậǉ,ǦǋậǓǦđưƶǦƸƽǄǦǁƃǄǦǅƽǊǦǃƽƁǃ?",
    ["花雨"] = "ƣǄƶǦƱũ",
    ["你不管咱们娘子了吗？"] = "ƩƼươƾǦǀƽƇǃƼǦǆǊƶǃǦǉƁǂǦđếǃǦǃươǃƼǦǉửǦǃƽƐǦǉƶǦǃữƶǦǈƶǄ?",
    ["什么话都让你说了呗，那你说说，你奉茶给谁？"] = "ƧờƾǦǃƐǄǦƸũǃƼǦđểǦǃƼươƾǦǃƚƾǦƽếǉǦǇồƾ,ǦǋậǓǦǃƼươƾǦǃƚƾǦǍƺǂ,ǦǃƼươƾǦǤƁǃƼǦǉǇƐǦƸƽǄǦƶƾ?",
    ["秋姐姐让我给谁我就给谁！"] = "ǥƽǊǦǉỷǦǉỷǦƷảǄǦǂǊộƾǦđưƶǦƸƽǄǦƶƾǦǉƽƔǦǂǊộƾǦđưƶǦƸƽǄǦǃƼườƾǦđƚ!",
    ["还、还能这么说？"] = "ƞƛǃ...ǦƸƛǃǦƸƚǦǉƽểǦǃƚƾǦǉƽếǦǈƶǄ?",
    ["这些孩子，瞧着都还机灵，这么一看，倒叫人有些拿不定主意了……不知军士可有人选？"] = "ƩƽữǃƼǦđứƶǦǉǇẻǦǃƐǓǦǃƽƔǃǦđềǊǦǁƶǃƽǦǁợƾ,ǦǃƽƔǃǦǉƽếǦǃƐǓǦǁạƾǦǀƽƾếǃǦǃƼườƾǦǉƶǦǀƽƚǦǁƛǃƼǦǆǊǓếǉǦđịǃƽ...ǦǀƽƇǃƼǦƷƾếǉǦǆǊƁǃǦǈĩǦƸƚǦǃƽƁǃǦǉǊǓểǃǦǃƐǄǦǀƽƇǃƼ?",
    ["方才你们讨论的，我们都听看见了，现在还有一个问题——"] = "ƩƽữǃƼǦƼƔǦƸƑƸǦǃƼươƾǦǉƽảǄǦǁǊậǃǦǋừƶǦǇồƾ,ǦƸƽƕǃƼǦǉƶǦđềǊǦđƃǦǃƼƽƺǦǉƽấǓ,ǦƽƾệǃǦǉạƾǦƸƛǃǦǂộǉǦƸƁǊǦƽỏƾǦǃữƶǦ——",
    ["若眼下你们四人均在宝慈宫里当差，若非得走一人，你们认为谁最该走？"] = "ƩếǊǦƽƾệǃǦǉạƾǦƷốǃǦǃƼườƾǦƸƑƸǦǃƼươƾǦđềǊǦđƶǃƼǦǁƐǂǦǋƾệƸǦởǦƝảǄǦǥừǦƞǊǃƼ,ǦǃếǊǦƷắǉǦƷǊộƸǦǅƽảƾǦƸƚǦǂộǉǦǃƼườƾǦǇờƾǦđƾ,ǦƸƑƸǦǃƼươƾǦǃƼƽĩǦƶƾǦǃƙǃǦđƾǦǃƽấǉ?",
    ["我……我以为，若定要有一人走，或许……或许该是平日里最清闲、干活最少的那一个……"] = "ƨǊộƾ...ǦǂǊộƾǦǃƼƽĩ,ǦǃếǊǦǃƽấǉǦđịǃƽǦǅƽảƾǦƸƚǦǂộǉǦǃƼườƾǦđƾ,ǦƸƚǦǁẽ...ǦƸƚǦǁẽǦǃƙǃǦǁƐǦǃƼườƾǦƷƔǃƽǦǉƽườǃƼǦǉƽƶǃƽǦǉƽảǃǦǃƽấǉ,ǦǁƐǂǦǋƾệƸǦƓǉǦǃƽấǉ...",
    ["银筝！你怎么能这么说！"] = "ƩƼƁǃǦǥǇƶǃƽ!ǦƮƶǄǦǃƼươƾǦƸƚǦǉƽểǦǃƚƾǦǃƽưǦǋậǓ!",
    ["秋姐姐，您听听，宫中差事都是由您指派，她说有人清闲，岂不是在指责秋姐姐您分派不公？这是在质疑您的为人啊！"] = "ǥƽǊǦǉỷǦǉỷ,ǦǉỷǦǃƼƽƺǦǍƺǂ,ǦƸƇǃƼǦǋƾệƸǦǉǇǄǃƼǦƸǊǃƼǦđềǊǦǤǄǦǉỷǦƸƽỉǦđịǃƽ,ǦǉỷǦấǓǦǃƚƾǦƸƚǦǃƼườƾǦǉƽƶǃƽǦǉƽảǃ,ǦƸƽẳǃƼǦǅƽảƾǦđƶǃƼǦƸƽỉǦǉǇƓƸƽǦǥƽǊǦǉỷǦǉỷǦǅƽƁǃǦǅƽƚǦǀƽƇǃƼǦƸƇǃƼǦƷằǃƼǦǈƶǄ?ǦĐƁǓǦǁƐǦđƶǃƼǦǃƼƽƾǦǃƼờǦǃƽƁǃǦƸƑƸƽǦƸủƶǦǉỷǦđƚ!",
    ["我不是！我没有！我说的只是干活的人，并非秋姐姐……"] = "ƦƽƇǃƼǦǅƽảƾ!ǦƨǊộƾǦǀƽƇǃƼǦƸƚ!ǦƨǊộƾǦƸƽỉǦǃƚƾǦǋềǦǃƼườƾǦǁƐǂǦǋƾệƸǦǉƽƇƾ,ǦǀƽƇǃƼǦǅƽảƾǦǃƚƾǦǥƽǊǦǉỷǦǉỷ...",
    ["好大的胆子！连秋姐姐你都不放在眼里。要我说，这宫里最该走的，就是秋姐姐瞧着不舒服的人！"] = "ƢươǃƼǦƼƶǃǦǉƽậǉ!ǦĐếǃǦǥƽǊǦǉỷǦǉỷǦǂƐǦǃƼươƾǦƸũǃƼǦǀƽƇǃƼǦđểǦǋƐǄǦǂắǉ.ǦǥƽƺǄǦǂǊộƾǦǉƽấǓ,ǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦǃƼườƾǦǃƙǃǦđƾǦǃƽấǉǦƸƽƓǃƽǦǁƐǦǀẻǦǀƽƾếǃǦǥƽǊǦǉỷǦǉỷǦǃƽƔǃǦǀƽƇǃƼǦǋừƶǦǂắǉ!",
    ["宝慈宫里，最懂娘子心意、最会办事의便是秋姐姐。我们这点本事，哪能跟秋姐姐比？"] = "ǥǇǄǃƼǦƝảǄǦǥừǦƞǊǃƼ,ǦǃƼườƾǦƽƾểǊǦǉƁǂǦƈǦǃươǃƼǦǉửǦǃƽấǉ,ǦƷƾếǉǦǁƐǂǦǋƾệƸǦǃƽấǉǦƸƽƓǃƽǦǁƐǦǥƽǊǦǉỷǦǉỷ.ǦƞƽƕǉǦƷảǃǦǈựǦǃƐǓǦƸủƶǦƸƽƕǃƼǦǉƶǦǈƶǄǦǈǄǦđượƸǦǋớƾǦǥƽǊǦǉỷǦǉỷ?",
    ["所以，只要能让秋姐姐顺心，就是为娘子、为宝慈宫立下了大功！"] = "ƞƽǄǦǃƙǃ,ǦƸƽỉǦƸầǃǦƸƚǦǉƽểǦǀƽƾếǃǦǥƽǊǦǉỷǦǉỷǦǋừƶǦƈ,ǦƸƽƓǃƽǦǁƐǦǁậǅǦđạƾǦƸƇǃƼǦƸƽǄǦǃươǃƼǦǉử,ǦƸƽǄǦƝảǄǦǥừǦƞǊǃƼ!",
    ["立功……咱们不是来干活的吗？"] = "ƧậǅǦƸƇǃƼ...ǦƸƽƕǃƼǦǉƶǦǀƽƇǃƼǦǅƽảƾǦǉớƾǦđểǦǁƐǂǦǋƾệƸǦǈƶǄ?",
    ["咳咳，宝慧所言，虽有夸大之嫌，但胜在懂规矩，更难得的是，有一份处处为宝慈宫着想的心。"] = "ƦƽụǦǀƽụ,ǦǁờƾǦƝảǄǦǥǊệǦǃƚƾǦǉǊǓǦƸƚǦǅƽầǃǦǀƽǄƶǦǉǇươǃƼ,ǦǃƽưǃƼǦǉƽắǃƼǦởǦƸƽỗǦƽƾểǊǦǆǊǓǦƸủ,ǦƸƐǃƼǦđƑǃƼǦǆǊƈǦƽơǃǦǁƐǦƸƚǦǉấǂǦǁƛǃƼǦǁǊƇǃǦǃƼƽĩǦƸƽǄǦƝảǄǦǥừǦƞǊǃƼ.",
    ["娘子，依我看，本次秋选，不如就定了宝慧？"] = "ƩươǃƼǦǉử,ǦǉƽƺǄǦƈǦǀƾếǃǦƸủƶǦǉƽầǃ,ǦǥƽǊǦǉǊǓểǃǦǁầǃǦǃƐǓǦƽƶǓǦǁƐǦƸƽọǃǦƝảǄǦǥǊệ?",
    ["方才考校，唯有银筝一人在用心思量对策。宫里要의，难道不该是这般脚踏实地、能办实事的人吗？"] = "ƞǊộƸǦǀƽảǄǦƽạƸƽǦǋừƶǦǇồƾ,ǦƸƽỉǦƸƚǦǂộǉǦǂƔǃƽǦƩƼƁǃǦǥǇƶǃƽǦǁƐǦǤụǃƼǦǉƁǂǦǈǊǓǦǃƼƽĩǦđốƾǦǈƑƸƽ.ǦǥƽứǦǉǇǄǃƼǦƸǊǃƼǦƸầǃ,ǦƸƽẳǃƼǦǁẽǦǀƽƇǃƼǦǅƽảƾǦǁƐǦƽạǃƼǦǃƼườƾǦǁƐǂǦǋƾệƸǦǉƽƾếǉǦǉƽựƸ,ǦƸƽắƸǦƸƽắǃǦǃƽưǦǋậǓǦǈƶǄ?",
    ["……银筝是个好孩子，踏实、本分，心也诚，不过秋娘选宝慧，想必亦有她的考量……"] = "...ƩƼƁǃǦǥǇƶǃƽǦǁƐǦǂộǉǦđứƶǦǉǇẻǦǉốǉ,ǦƸƽắƸǦƸƽắǃ,ǦƷổǃǦǅƽậǃ,ǦǁƛǃƼǦƸũǃƼǦǉƽƐǃƽ,ǦǃƽưǃƼǦǥƽǊǦƩươǃƼǦƸƽọǃǦƝảǄǦǥǊệǦƸƽắƸǦƽẳǃǦƸũǃƼǦƸƚǦƸƁǃǦǃƽắƸǦƸủƶǦǃƐǃƼǦấǓ...",
    ["不知娘子您在顾虑什么？"] = "ƦƽƇǃƼǦƷƾếǉǦǃươǃƼǦǉửǦǃƼƐƾǦđƶǃƼǦǁǄǦǃƼạƾǦđƾềǊǦƼƔ?",
    ["娘子！我、我……我有一句话想说！"] = "ƩươǃƼǦǉử!Ǧǥƽầǃ...Ǧǉƽầǃ...ǦǉƽầǃǦƸƚǦǂộǉǦƸƁǊǦǂǊốǃǦǃƚƾ!",
    ["……既是遴选洒扫宫人，却未考校洒扫功夫……我、我在尚功局当差，洒扫活计，已尽心做了三年！"] = "...ĐƃǦǁƐǦǉǊǓểǃǦƸƽọǃǦƸǊǃƼǦǃƽƁǃǦǆǊƗǉǦǤọǃ,ǦǃƽưǃƼǦǁạƾǦƸƽưƶǦǀƽảǄǦƽạƸƽǦƸƇǃƼǦǅƽǊǦǆǊƗǉǦǤọǃ...Ǧǉƽầǃ...ǦǉƽầǃǦǁƐǂǦǋƾệƸǦởǦǥƽượǃƼǦƞƇǃƼǦƞụƸ,ǦǋƾệƸǦǆǊƗǉǦǤọǃǦđƃǦǉậǃǦǉƁǂǦǁƐǂǦǈǊốǉǦƷƶǦǃăǂǦǇồƾ!",
    ["若论洒扫，我、我有自信……！"] = "ƩếǊǦǁǊậǃǦǋềǦǆǊƗǉǦǤọǃ,Ǧǉƽầǃ...ǦǉƽầǃǦƸƚǦǉựǦǉƾǃ...!",
    ["哦？我竟不知，这洒扫之功也有高下之分，既然如此，你便试试吧。"] = "Ồ?ǦǥƶǦǁạƾǦǀƽƇǃƼǦƷƾếǉǦƸƇǃƼǦǅƽǊǦǆǊƗǉǦǤọǃǦǃƐǓǦƸũǃƼǦƸƚǦǅƽƁǃǦƸƶǄǦǉƽấǅ,ǦđƃǦǋậǓǦǉƽƔǦǃƼươƾǦǉƽửǦǍƺǂǦǈƶǄ.",
    ["——秋风扫落叶！"] = "——ǦǥƽǊǦƫƽǄǃƼǦǥảǄǦƧạƸǦǝƾệǅ!",
    ["噗嗤……哈哈哈……秋凤，你快看她，这架势……"] = "ƫƽụǉ...ǦƽƶǦƽƶǦƽƶ...ǦǥƽǊǦƫƽượǃƼ,ǦǂǊộƾǦǂƶǊǦǃƽƔǃǦǃƐǃƼǦǉƶǦǍƺǂ,ǦǉưǦǉƽếǦǃƐǓ...",
    ["原以为你是个实诚의，未曾想也挺机灵，知晓为自己争取。"] = "ƱốǃǦǉưởǃƼǦǃƼươƾǦǁƐǦǀẻǦǉƽƐǃƽǦǉƽậǉ,ǦǀƽƇǃƼǦǃƼờǦƸũǃƼǦǀƽƑǦǁƶǃƽǦǁợƾ,ǦƷƾếǉǦǉựǦǉǇƶǃƽǦǉƽủǦƸƽǄǦǂƔǃƽ.",
    ["这洒扫架势虽然滑稽，但你有份认真的劲儿，地嘛……也扫得很干净。"] = "ǥưǦǉƽếǦǆǊƗǉǦǤọǃǦǃƐǓǦǉǊǓǦǃựƸǦƸườƾ,ǦǃƽưǃƼǦǃƼươƾǦƸƚǦǈựǦǃƼƽƾƙǂǦǉƕƸ,Ǧđấǉ...ǦƸũǃƼǦǆǊƗǉǦǇấǉǦǈạƸƽǦǈẽ.",
    ["是挺滑稽的，没想到能逗娘子您开心……"] = "ĐƕǃƼǦǁƐǦǇấǉǦǃựƸǦƸườƾ,ǦǀƽƇǃƼǦǃƼờǦǁạƾǦƸƚǦǉƽểǦǁƐǂǦǃươǃƼǦǉửǦǋǊƾǦǋẻ...",
    ["她倒让我想起你来了，秋凤，当年你洒扫庭院落叶时，也是这般执拗、一丝不苟。你忘了？"] = "ƩƐǃƼǦǉƶǦǁạƾǦǁƐǂǦǉƶǦǃƽớǦǉớƾǦǂǊộƾǦđƚ,ǦǥƽǊǦƫƽượǃƼ,ǦǃăǂǦđƚǦǀƽƾǦǂǊộƾǦǆǊƗǉǦǁƑǦǇụǃƼǦǉǇǄǃƼǦđƔǃƽǦǋƾệǃ,ǦƸũǃƼǦƸốǦƸƽấǅǦǋƐǦǉỉǦǂỉǦǃƽưǦǉƽếǦǃƐǓ.ǦƨǊộƾǦǆǊƙǃǦǇồƾǦǈƶǄ?",
    ["秋凤不敢……今日本就是笑招，宝慧虽会端水奉茶，但银筝这太极功夫更胜一筹，既能洒扫，又能博您一笑……是银筝胜了。"] = "ǥƽǊǦƫƽượǃƼǦǀƽƇǃƼǦǤƑǂ...ǦƽƇǂǦǃƶǓǦǋốǃǦǁƐǦǉƾếǊǦƸƽƾƙǊ,ǦƝảǄǦǥǊệǦǉǊǓǦƷƾếǉǦƷưǃƼǦǃướƸǦǤƁǃƼǦǉǇƐ,ǦǃƽưǃƼǦƸƇǃƼǦǅƽǊǦǥƽƑƾǦƞựƸǦǃƐǓǦƸủƶǦƩƼƁǃǦǥǇƶǃƽǦǁạƾǦƸƶǄǦƽơǃǦǂộǉǦƷậƸ,ǦǋừƶǦƸƚǦǉƽểǦǆǊƗǉǦǤọǃ,ǦǁạƾǦǋừƶǦƸƚǦǉƽểǦǀƽƾếǃǦǃƼƐƾǦǂỉǂǦƸườƾ...ǦǁƐǦƩƼƁǃǦǥǇƶǃƽǦǉƽắǃƼǦǇồƾ.",
    ["既然如此，那便选银筝吧。"] = "ĐƃǦǋậǓǦǉƽƔǦƸƽọǃǦƩƼƁǃǦǥǇƶǃƽǦđƾ.",
    ["啊？怎会……！"] = "Ɯ?ǦƮƶǄǦƸƚǦǉƽể...!",
    ["我……我入选了？我真的入选了？！谢大人！谢娘子！"] = "ǥƶ……ǦǉƶǦǉǇƕǃƼǦǉǊǓểǃǦǇồƾ?ǦǥƶǦǉƽậǉǦǈựǦǉǇƕǃƼǦǉǊǓểǃǦǇồƾ?!ǦǥạǦơǃǦđạƾǦǃƽƁǃ!ǦǥạǦơǃǦǃươǃƼǦǉử!",
    ["我……我真的入选了……我不是在做梦吧？"] = "ǥƶ……ǦǉƶǦǉƽậǉǦǈựǦǉǇƕǃƼǦǉǊǓểǃǦǇồƾ……ǦǉƶǦǀƽƇǃƼǦǅƽảƾǦđƶǃƼǦǃằǂǦǂơǦƸƽứ?",
    ["都是真的！不过，我这招秋风扫落叶，你怎么看一眼就会了，武学奇才啊！"] = "ĐềǊǦǁƐǦǉƽậǉǦƸả!ǦƞƚǦđƾềǊ,ǦƸƽƾƙǊǦǥƽǊǦƫƽǄǃƼǦǥảǄǦƧạƸǦǝƾệǅǦǃƐǓǦƸủƶǦǉƶ,ǦǈƶǄǦǃƼươƾǦǂớƾǦǃƽƔǃǦǂộǉǦƸƑƾǦđƃǦƷƾếǉǦǃƼƶǓǦǋậǓ,ǦđƕǃƼǦǁƐǦǀỳǦǉƐƾǦǋƅǦƽọƸ!",
    ["我也不知怎地，情急之下就使出来了，好像话本中说的打通了任督二脉似的……"] = "ǥƶǦƸũǃƼǦǀƽƇǃƼǦƷƾếǉǦǉạƾǦǈƶǄ,ǦǉǇǄǃƼǦǁƕƸǦǉƔǃƽǦǉƽếǦƸấǅǦƷƑƸƽǦǁƾềǃǦǉƽƾǦǉǇƾểǃǦǇƶǦđượƸ,ǦƼƾốǃƼǦǃƽưǦǉǇǄǃƼǦǉƽǄạƾǦƷảǃǦƽƶǓǦǃƚƾǦǁƐǦđƃǦđảǦǉƽƇǃƼǦƽƶƾǦǂạƸƽǦƩƽƁǂǦĐốƸǦǋậǓ……",
    ["就像当时看见大人您在堂上为我据理力争的样子，我也觉得自己该站出来说些什么，至少得为自己争一争……"] = "ƢƾốǃƼǦǃƽưǦǁƕƸǦǃƃǓǦǉƽấǓǦđạƾǦǃƽƁǃǦǋƔǦǉƶǦǂƐǦǀƽẩǊǦƸƽƾếǃǦǉǇƙǃǦǈảǃƽ,ǦǉƶǦƸũǃƼǦƸảǂǦǉƽấǓǦǂƔǃƽǦǃƙǃǦđứǃƼǦǇƶǦǃƚƾǦƼƔǦđƚ,ǦƓǉǦǃƽấǉǦǅƽảƾǦǉựǦǉǇƶǃƽǦǉƽủǦƸƽǄǦƷảǃǦǉƽƁǃ……",
    ["……其实，我也只是有样学样，学了大人您的样子罢了。"] = "……ǦǥƽựƸǦǇƶ,ǦǉƶǦƸũǃƼǦƸƽỉǦǁƐǦǇậǅǦǀƽǊƇǃǦǉƽƺǄ,ǦƽọƸǦǉƽƺǄǦǤƑǃƼǦǋẻǦƸủƶǦđạƾǦǃƽƁǃǦǂƐǦǉƽƇƾ.",
    ["这是你自己的本事，它是学不来的，除非它原本就在你的心里。"] = "ĐƁǓǦǁƐǦƷảǃǦǁĩǃƽǦƸủƶǦƸƽƓǃƽǦǃƼươƾ,ǦǉƽứǦđƚǦǀƽƇǃƼǦƽọƸǦǉƽƺǄǦđượƸǦđƁǊ,ǦǉǇừǦǅƽƾǦǃƚǦǋốǃǦđƃǦởǦǉǇǄǃƼǦǁƛǃƼǦǃƼươƾǦǇồƾ.",
    ["我是落叶，您是秋风，您猜为何？"] = "ǥƶǦǁƐǦǁƑǦǇụǃƼ,ǦǃƼƐƾǦǁƐǦƼƾƚǦǉƽǊ,ǦǃƼƐƾǦđǄƑǃǦǍƺǂǦǉạƾǦǈƶǄ?",
    ["因为您只是轻轻地来，就一扫我的阴霾，让我乘风而上！"] = "ƝởƾǦǋƔǦǃƼƐƾǦƸƽỉǦǃƽẹǦǃƽƐǃƼǦǁướǉǦǆǊƶ,ǦđƃǦǆǊƗǉǦǈạƸƽǦǂƁǓǦǂƖǦǉǇǄǃƼǦǉƶ,ǦđểǦǉƶǦƸưỡƾǦƼƾƚǦǂƐǦǁƙǃ!",
    ["……不、不好笑吗？"] = "……ǦƦƽƇǃƼ,ǦǀƽƇǃƼǦƷǊồǃǦƸườƾǦǈƶǄ?",
    ["……银筝啊，要不咱还是放弃说笑话吧，以后好好扫地。"] = "……ǦƩƼƁǃǦǥǇƶǃƽǦƐ,ǦƽƶǓǦǁƐǦǉƽƇƾǦđừǃƼǦǀểǦƸƽǊǓệǃǦƸườƾǦǃữƶ,ǦǈƶǊǦǃƐǓǦǁǄǦǂƐǦǆǊƗǉǦđấǉǦƸƽǄǦǉốǉǦđƾ.",
    ["嘿嘿……大人，多谢！好人一生平安！"] = "ƣƔǦƽƔ……ǦđạƾǦǃƽƁǃ,ǦđƶǦǉạ!ǦƞƽƕƸǦǃƼườƾǦǉốǉǦƸảǦđờƾǦƷƔǃƽǦƶǃ!",
    ["风大起来了，茶水必然要凉，娘子，我来替您换一杯吧！"] = "ƢƾƚǦǁớǃǦǇồƾ,ǦǃướƸǦǉǇƐǦƸƽắƸǦƸƽắǃǦǈẽǦǁạǃƽ,ǦǃươǃƼǦǉử,ǦđểǦǃƇǦǉƔǦđổƾǦƸƽǄǦǃƼườƾǦƸƽƗǃǦǀƽƑƸ!",
    ["巧鹊"] = "ƳảǄǦǥƽướƸ",
    ["其实……"] = "ǥƽựƸǦǇƶ……",
    ["呀！怎的飞来几只小虫？看我不把它扇走——"] = "Ɯ!ǦƮƶǄǦǁạƾǦƸƚǦǂấǓǦƸǄǃǦǈƁǊǦǃƽỏǦƷƶǓǦǉớƾǦǉƽếǦǃƐǓ?ǦƳƺǂǦǉƶǦǆǊạǉǦđǊổƾǦƸƽƕǃƼǦđƾǦđƁǓǦ——",
    ["倒也……"] = "ƞũǃƼǦǀƽƇǃƼǦƽẳǃ……",
    ["外头花开得正美，娘子可要赏花？若是不想走远，我折几枝花送来可好？"] = "ƝƙǃǦǃƼǄƐƾǦƽǄƶǦǃởǦǇấǉǦđẹǅ,ǦǃươǃƼǦǉửǦƸƚǦǂǊốǃǦǉƽưởǃƼǦƽǄƶǦǀƽƇǃƼ?ǦƩếǊǦǀƽƇǃƼǦǂǊốǃǦđƾǦǍƶ,ǦǃƇǦǉƔǦƷẻǦǋƐƾǦƸƐǃƽǦǂƶǃƼǦǉớƾǦǃƽƗ?",
    ["我不饮热茶，不怕虫，不赏花——巧鹊，你近来怎的忽然如此殷勤？"] = "ǥƶǦǀƽƇǃƼǦǊốǃƼǦǉǇƐǦǃƚǃƼ,ǦǀƽƇǃƼǦǈợǦǈƁǊ,ǦǀƽƇǃƼǦǉƽưởǃƼǦƽǄƶǦ——ǦƳảǄǦǥƽướƸ,ǦǤạǄǦǃƐǓǦǈƶǄǦǃƼươƾǦƷỗǃƼǦǃƽƾƙǃǦƁǃǦƸầǃǦǆǊƑǦǋậǓ?",
    ["没，没有啊……哈哈！侍奉好娘子是本分，手脚麻利些，不好么……"] = "ƦƽƇǃƼ,ǦǀƽƇǃƼǦƸƚǦǂƐ……ǦƽƶǦƽƶ!ǦƣầǊǦƽạǦǃươǃƼǦǉửǦǉốǉǦǁƐǦƷổǃǦǅƽậǃ,ǦǉƶǓǦƸƽƁǃǦǁƶǃƽǦǁẹǦƸƽƕǉǦǀƽƇǃƼǦǅƽảƾǦǉốǉǦǈƶǄ……",
    ["这却忙得古怪……到底是因何而起？"] = "ǥƽếǦǃƐǓǦǉƽƔǦƷậǃǦǇộǃǦđếǃǦǀỳǦǆǊƑƾ……ǦǇốǉǦƸǊộƸǦǁƐǦǋƔǦǃƼǊǓƙǃǦƸớǦƼƔ?",
    ["诶？娘子因何愁眉不展？"] = "Ơ?ǦƩươǃƼǦǉửǦǋƔǦǈƶǄǦǁạƾǦƸƶǊǦǂƐǓǦủǦǇũǦǉƽếǦǀƾƶ?",
    ["原是武德司的军士，我本欲在此品茶，却被这丫头忙得不得清静，真真是奇怪……"] = "ƣƚƶǦǇƶǦǁƐǦǆǊƁǃǦǈĩǦƸủƶǦƱƅǦĐứƸǦǥǓ,ǦǉƶǦǋốǃǦǂǊốǃǦởǦđƁǓǦǉƽưởǃƼǦǉǇƐ,ǦǃƽưǃƼǦǁạƾǦƷịǦƸǄǃǦƷƗǦǃƐǓǦǁƐǂǦƸƽǄǦǀƽƇǃƼǦđượƸǦǓƙǃǦǉĩǃƽ,ǦǉƽậǉǦǁƐǦǀỳǦǁạ……",
    ["啊——这个我熟，我老家开酒坊的。每回乡亲们干活突然格外卖力，一问，准是不知打哪来传出了“东家嫌人多，不给饭吃”的风声。"] = "ƜǦ——ǦƸƑƾǦǃƐǓǦǉƶǦǇƐǃƽǦǁắǂ,ǦǆǊƙǦǉƶǦǂởǦǍưởǃƼǦǇượǊǦǂƐ.ǦƨỗƾǦǁầǃǦƷƐǦƸǄǃǦǁốƾǦǍƚǂǦǉựǦǤưǃƼǦǁƐǂǦǋƾệƸǦƽăǃƼǦƽƑƾǦǁạǦǉƽườǃƼ,ǦƸứǦƽỏƾǦǂộǉǦƸƑƾǦǁƐǦǓǦǃƽưǦǇằǃƼǦǀƽƇǃƼǦƷƾếǉǦǉừǦđƁǊǦđồǃǦǇƶǦǉƾǃǦ\"ƇǃƼǦƸƽủǦƸƽƙǦǃƼườƾǦđƇǃƼ,ǦǀƽƇǃƼǦƸƽǄǦăǃǦƸơǂ\"ǦǉƽƇƾ.",
    ["闲不住……是因为怕一犯懒就被赶走了？"] = "ƦƽƇǃƼǦƸƽịǊǦđểǦǉƶǓǦƸƽƁǃǦǃƼƽỉǦǃƼơƾ……ǦǁƐǦǋƔǦǈợǦƽễǦǁườƾǦƷƾếǃƼǦǂộǉǦƸƽƕǉǦǁƐǦƷịǦđǊổƾǦđƾǦǈƶǄ?",
    ["对，我瞧这位姑娘多半也是……"] = "ƫƽảƾ,ǦǉƶǦǉƽấǓǦƸƇǦǃươǃƼǦǃƐǓǦđƶǦǅƽầǃǦƸũǃƼǦǁƐ……",
    ["不是，我没有！娘子……我只是有些怕……一闲着，我就心慌，根本停不下做活！"] = "ƦƽƇǃƼǦǅƽảƾ,ǦǃƇǦǉƔǦǀƽƇǃƼǦƸƚ!ǦƩươǃƼǦǉử……ǦǃƇǦǉƔǦƸƽỉǦǁƐǦƽơƾǦǈợ……ǦƽễǦǇảǃƽǦǇỗƾǦǁƐǦǃƇǦǉƔǦǁạƾǦƽǄảǃƼǦƽốǉ,ǦƸăǃǦƷảǃǦǀƽƇǃƼǦǃƼừǃƼǦǁƐǂǦǋƾệƸǦđượƸ!",
    ["怪道你坐不住，睡不好，这倒有些为难了……"] = "ǥǇƑƸƽǦǀƽƇǃƼǦđượƸǦǃƼươƾǦǃƼồƾǦǀƽƇǃƼǦǓƙǃ,ǦǃƼủǦǀƽƇǃƼǦǃƼǄǃ,ǦƸƽǊǓệǃǦǃƐǓǦđƕǃƼǦǁƐǦƸƚǦƸƽƕǉǦǀƽƚǦǍửǦǇồƾ……",
    ["这有何难？自个儿停不下来，我来助你！"] = "ƞƚǦƼƔǦǀƽƚǦđƁǊ?ǦǥựǦǂƔǃƽǦǀƽƇǃƼǦǤừǃƼǦǁạƾǦđượƸǦǉƽƔǦđểǦǉƶǦƼƾƕǅǦǃƼươƾǦǂộǉǦǉƶǓ!",
    ["什么武功？我进宫数载，历经两朝，倒是第一回见……"] = "ƱƅǦƸƇǃƼǦƼƔǦǉƽếǦǃƐǓ?ǦǥƶǦǋƐǄǦƸǊǃƼǦƷƶǄǦǃăǂ,ǦǉǇảƾǦǆǊƶǦƽƶƾǦǉǇƾềǊǦđạƾ,ǦđƁǓǦđƕǃƼǦǁƐǦǁầǃǦđầǊǦđượƸǦǉƽấǓ……",
    ["正该如此，她总算能暂歇一刻了，也叫我的眼睛歇歇。"] = "ƩƙǃǦǁƐǦǃƽưǦǋậǓ,ǦƸǄǃǦƷƗǦƸǊốƾǦƸƖǃƼǦƸũǃƼǦƸƚǦǉƽểǦǉạǂǦǃƼƽỉǦǂộǉǦǁƑǉ,ǦƸũǃƼǦđểǦǂắǉǦǉƶǦđượƸǦǃƼƽỉǦǃƼơƾ.",
    ["我还有一事不解，娘子脾性温和，不像苛刻之人，巧鹊为何慌得停不下脚？"] = "ǥƶǦƸƛǃǦǂộǉǦƸƽǊǓệǃǦƸƽưƶǦƽƾểǊ,ǦǃươǃƼǦǉửǦǉƓǃƽǦǉƔǃƽǦƇǃǦƽƛƶ,ǦǀƽƇǃƼǦƼƾốǃƼǦǃƼườƾǦƽƐǦǀƽắƸ,ǦǈƶǄǦƳảǄǦǥƽướƸǦǁạƾǦƽǄảǃƼǦǈợǦđếǃǦǂứƸǦǀƽƇǃƼǦǃƼừǃƼǦǉƶǓǦƸƽƁǃǦđượƸ?",
    ["我不喜多事，究竟是为何……"] = "ǥƶǦǀƽƇǃƼǦǉƽƓƸƽǦǃƽƾềǊǦƸƽǊǓệǃ,ǦǇốǉǦƸǊộƸǦǁƐǦǋƔǦǈƶǄ……",
    ["是了，宫里前不久闹出了事。有个姑姑因着与前朝之事有所牵连，被人拖下去了，至今生死不知……这孩子才进宫，怕是被吓坏了。"] = "ƫƽảƾǦǇồƾ,ǦǉǇǄǃƼǦƸǊǃƼǦƸƑƸƽǦđƁǓǦǀƽƇǃƼǦǁƁǊǦǍảǓǦǇƶǦƸƽǊǓệǃ.ǦƞƚǦǂộǉǦǋịǦƸƇǦƸƇǦǋƔǦǁƾƙǃǦǆǊƶǃǦđếǃǦƸƽǊǓệǃǦǉƾềǃǦǉǇƾềǊǦǂƐǦƷịǦǃƼườƾǦǉƶǦǁƇƾǦđƾ,ǦđếǃǦǃƶǓǦǈốǃƼǦƸƽếǉǦƸƽưƶǦǇƅ……ǦƞǄǃǦƷƗǦǃƐǓǦǂớƾǦǋƐǄǦƸǊǃƼ,ǦƸƽắƸǦǁƐǦƷịǦǤọƶǦǈợǦǇồƾ.",
    ["原来如此……可我观娘子容色平静，莫非是有所倚仗？"] = "ƣƚƶǦǇƶǦǁƐǦǋậǓ……ǦǃƽưǃƼǦǉƶǦǉƽấǓǦǈắƸǦǂặǉǦǃươǃƼǦǉửǦƷƔǃƽǦǉƽảǃ,ǦǁẽǦǃƐǄǦǁƐǦƸƚǦƸƽỗǦǤựƶ?",
    ["有何倚仗？她年轻尚轻，我却已在宫中见过数十回落花。"] = "ƞƽỗǦǤựƶǦƼƔǦƸƽứ?ǦƞǄǃǦƷƗǦƸƛǃǦǉǇẻ,ǦƸƛǃǦǉƶǦđƃǦǉƽấǓǦƽǄƶǦǇụǃƼǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦǂấǓǦƸƽụƸǦǁầǃǦǇồƾ.",
    ["喜也一日，忧也一日，喜忧却是由我选择，何不欢喜度日？"] = "ƱǊƾǦƸũǃƼǦǂộǉǦǃƼƐǓ,ǦƷǊồǃǦƸũǃƼǦǂộǉǦǃƼƐǓ,ǦǋǊƾǦƷǊồǃǦǁƐǦǤǄǦǉƶǦƸƽọǃ,ǦǈƶǄǦǀƽƇǃƼǦƸƽọǃǦǈốǃƼǦǋǊƾǦǋẻǦǆǊƶǦǃƼƐǓ?",
    ["娘子果然见地颇深，受教了！"] = "ƩươǃƼǦǉửǦǆǊảǦǃƽƾƙǃǦƸƚǦǀƾếǃǦƼƾảƾǦǈƁǊǦǈắƸ,ǦǉạƾǦƽạǦǉƽụǦƼƾƑǄǦǇồƾ!",
    ["好神奇的武功……方才我什么也没忙，却什么也没想……一点儿也不慌！"] = "ƱƅǦƸƇǃƼǦǉƽậǉǦǉƽầǃǦǀỳ……ǦǋừƶǦǇồƾǦǃƇǦǉƔǦƸƽẳǃƼǦƷậǃǦǇộǃǦƼƔ,ǦǂƐǦƸũǃƼǦƸƽẳǃƼǦǃƼƽĩǦǃƼợƾǦƼƔ……ǦǀƽƇǃƼǦǉƽấǓǦƽǄảǃƼǦǂộǉǦƸƽƕǉǦǃƐǄǦǁǊƇǃ!",
    ["多谢大人！我决定从明日起少忙些事，日复一日，定下心来……"] = "ĐƶǦǉạǦđạƾǦǃƽƁǃ!ǦƩƇǦǉƔǦǆǊǓếǉǦđịǃƽǦǉừǦǃƼƐǓǦǂƶƾǦǈẽǦƷớǉǦƷậǃǦǇộǃǦǁạƾ,ǦǃƼƐǓǦǆǊƶǦǃƼƐǓ,ǦƼƾữǦƸƽǄǦǉƁǂǦǂƔǃƽǦǉĩǃƽǦǁạƾ……",
    ["不必客气！望你早日闲下心来，陪你家娘子饮茶。"] = "ĐừǃƼǦǀƽƑƸƽǦǈƑǄ!ǦƣǓǦǋọǃƼǦǃƼươƾǦǈớǂǦǉƽảǃƽǦǉƽơƾǦđầǊǦƚƸǦđểǦƸƖǃƼǦǃươǃƼǦǉửǦǃƽƐǦǂƔǃƽǦǉƽưởǃƼǦǉǇƐ.",
    ["说，说什么呢……听雨姐姐怕是路上有事耽搁了。"] = "Ʃƚƾ,ǦǃƚƾǦƼƔǦǋậǓǦƸƽứ……ǦǥƽƓǃƽǦƱũǦǉỷǦǉỷǦƸƽắƸǦǁƐǦǉǇƙǃǦđườǃƼǦƸƚǦǋƾệƸǦǃƙǃǦƷịǦǉǇƔǦƽǄƃǃǦǉƽƇƾ.",
    ["好了，既然寻她不见，只能再请一人入局了。"] = "ĐượƸǦǇồƾ,ǦđƃǦǉƔǂǦǀƽƇǃƼǦǉƽấǓǦǉỷǦấǓ,ǦƸƽỉǦđƐǃƽǦǂờƾǦǉƽƙǂǦǂộǉǦǃƼườƾǦǃƽậǅǦƸǊộƸǦǋậǓ.",
    ["素雪，这几日，我这心口总像是压着一块冰，堵得慌。"] = "ǥốǦǥǊǓếǉ,ǦǂấǓǦǃƼƐǓǦǃƶǓǦǁồǃƼǦǃƼựƸǦǉƶǦƸứǦǃƽưǦƷịǦǉảǃƼǦƷăǃƼǦđƘǦǃặǃƼ,ǦƷƓǦƷƑƸƽǦǁắǂ.",
    ["娘子无需忧心。不过是天冷了，宫里风声又紧了些。咱们安分守己，仔细行事，不让人抓了错处，总能安然无恙的。"] = "ƩươǃƼǦǉửǦǀƽƇǃƼǦƸầǃǦǁǄǦǁắǃƼ.ǦƞƽẳǃƼǦǆǊƶǦǁƐǦǉǇờƾǦǁạǃƽ,ǦǉǇǄǃƼǦƸǊǃƼǦǅƽǄǃƼǦǉƽƶǃƽǦǁạƾǦƼắǉǦƼƶǄǦǉƽƙǂǦƸƽƕǉǦǉƽƇƾ.ǦƞƽƕǃƼǦǉƶǦƸứǦƶǃǦǅƽậǃǦǉƽủǦǀỷ,ǦƽƐǃƽǦǈựǦƸẩǃǦǉǇọǃƼ,ǦǀƽƇǃƼǦđểǦǃƼườƾǦǉƶǦǃắǂǦđượƸǦǉƽƚǅ,ǦắǉǦǈẽǦƷƔǃƽǦƶǃǦǋƇǦǈựǦǉƽƇƾ.",
    ["安然无恙？如今人人在说，宫中诸事都要缩减开支，我们又是前朝留下来的人。"] = "ƝƔǃƽǦƶǃǦǋƇǦǈựǦǈƶǄ?ǦƩƶǓǦǃƼườƾǦǃƼườƾǦđềǊǦǃƚƾ,ǦǂọƾǦǋƾệƸǦǉǇǄǃƼǦƸǊǃƼǦđềǊǦǅƽảƾǦƸắǉǦƼƾảǂǦƸƽƾǦǉƾƙǊ,ǦƸƽƕǃƼǦǉƶǦǁạƾǦǁƐǦǃƼườƾǦƸủƶǦǉƾềǃǦǉǇƾềǊǦƸƛǃǦǈƚǉǦǁạƾ.",
    ["我怕的，从来不是日子过得苦。我怕的是，今日缩减的是开支，明日缩减的……会不会是这宫里的人呢？"] = "ĐƾềǊǦǉƶǦǈợǦƸƽưƶǦƷƶǄǦƼƾờǦǁƐǦǃƼƐǓǦǉƽƑǃƼǦǀƽổǦƸựƸ.ǦǥƶǦǈợǦǁƐ,ǦƽƇǂǦǃƶǓǦƸắǉǦƼƾảǂǦƸƽƾǦǉƾƙǊ,ǦǃƼƐǓǦǂƶƾǦƸắǉǦƼƾảǂ……ǦǁƾệǊǦƸƚǦǅƽảƾǦǁƐǦǃƼườƾǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦǀƽƇǃƼ?",
    ["若是头顶的日光，已经不打算照进我们这里了。一棵得不到光的杂草，又能活上几天呢？"] = "ƩếǊǦƑǃƽǦǂặǉǦǉǇờƾǦǉǇƙǃǦđỉǃƽǦđầǊǦđƃǦǀƽƇǃƼǦƸƛǃǦđịǃƽǦǈǄƾǦƸƽƾếǊǦǋƐǄǦǃơƾǦǃƐǓǦƸủƶǦƸƽƕǃƼǦǉƶǦǃữƶ.ǦƨộǉǦǃƼọǃǦƸỏǦǤạƾǦǀƽƇǃƼǦƸƚǦƑǃƽǦǈƑǃƼǦǉƽƔǦƸƛǃǦǈốǃƼǦǉƽƙǂǦđượƸǦǂấǓǦǃƼƐǓǦđƁǓ?",
    ["嘘……你们都小声些，大人可要来一局叶子行饮？"] = "ƮǊỵǉ……ǦƸƑƸǦǃƼươƾǦǃƽỏǦǉƾếǃƼǦƸƽƕǉ,ǦđạƾǦǃƽƁǃǦƸƚǦǂǊốǃǦƸƽơƾǦǂộǉǦǋƑǃǦǝƾệǅǦǥửǦƣƐǃƽǦẨǂǦǀƽƇǃƼ?",
    ["大人想请好友同乐？可以，但宫规如此，尽量动静小些……"] = "ĐạƾǦǃƽƁǃǦǂǊốǃǦǂờƾǦƽảǄǦƽữǊǦƸƖǃƼǦƸƽǊǃƼǦǋǊƾǦǈƶǄ?ǦĐượƸǦǉƽƇƾ,ǦǃƽưǃƼǦƸǊǃƼǦǆǊǓǦǁƐǦǋậǓ,ǦƸốǦƼắǃƼǦƽạǃǦƸƽếǦǉƾếǃƼǦđộǃƼǦǂộǉǦƸƽƕǉ……",
    ["无碍，我们再等一等……"] = "ƦƽƇǃƼǦǈƶǄ,ǦƸƽƕǃƼǦǉƶǦđợƾǦǉƽƙǂǦƸƽƕǉǦǃữƶ……",
    ["茶烫，小心些。"] = "ǥǇƐǦǃƚǃƼ,ǦƸẩǃǦǉƽậǃǦƸƽƕǉ.",
    ["没事儿，毕竟我没有姐姐这样的歌喉，烫伤了也没关系。"] = "ƦƽƇǃƼǦǈƶǄǦđƁǊ,ǦǤƖǦǈƶǄǦǂǊộƾǦƸũǃƼǦǀƽƇǃƼǦƸƚǦƼƾọǃƼǦƽƑǉǦǃƽưǦǉỷǦǉỷ,ǦƸƚǦƷịǦƷỏǃƼǦƸũǃƼǦƸƽẳǃƼǦƽềǦƼƔ.",
    ["就你贫。"] = "ƞƽỉǦǀƽƗǄǦǂồǂ.",
    ["还记得吗？从前咱们俩为了争一支新曲，能明里暗里斗上好几天。那时候，真是针锋相对。"] = "ƞƛǃǦǃƽớǦǀƽƇǃƼ?ǦǥǇướƸǦǀƾƶǦƽƶƾǦǉƶǦǋƔǦǉǇƶǃƽǦǂộǉǦǀƽƕƸǦǃƽạƸǦǂớƾǦǂƐǦƸƚǦǉƽểǦđấǊǦđƑǦǃƼǄƐƾǦǈƑǃƼǦǉǇǄǃƼǦǉốƾǦǈǊốǉǦǂấǓǦǃƼƐǓǦǁƾềǃ.ǦƧƕƸǦđƚǦǉƽậǉǦđƕǃƼǦǁƐǦƸƽƁǂǦǅƽǄǃƼǦǉươǃƼǦđốƾ.",
    ["如何不记得。姐姐你要在御前献唱，妹妹我就非要在那一日献舞。现在想来，姐姐的歌喉确实婉转，是我当年不服输罢了。"] = "ƧƐǂǦǈƶǄǦǀƽƇǃƼǦǃƽớǦƸƽǄǦđượƸ.ǦǥỷǦǉỷǦǂǊốǃǦƽƑǉǦǉǇướƸǦǂặǉǦƽǄƐǃƼǦǉƽượǃƼ,ǦǂǊộƾǦǂǊộƾǦǉƶǦǃƽấǉǦđịǃƽǦǅƽảƾǦǂƕƶǦǋƐǄǦđƕǃƼǦǃƼƐǓǦđƚ.ǦƢƾờǦǃƼƽĩǦǁạƾ,ǦƼƾọǃƼǦƽƑǉǦƸủƶǦǉỷǦǉỷǦđƕǃƼǦǁƐǦǊǓểǃǦƸƽǊǓểǃ,ǦǁƐǦǃăǂǦđƚǦǉƶǦǀƽƇǃƼǦƸƽịǊǦǉƽǊƶǦǂƐǦǉƽƇƾ.",
    ["不，是妹妹你的舞姿更胜一筹……行了，都过去了，还提这些做什么。"] = "ƦƽƇǃƼ,ǦǁƐǦǋũǦđƾệǊǦƸủƶǦǂǊộƾǦǂǊộƾǦƸƶǄǦƽơǃǦǂộǉǦƷậƸ……ǦǥƽƇƾ,ǦđềǊǦđƃǦǆǊƶǦǇồƾ,ǦƸƛǃǦǃƽắƸǦǁạƾǦǁƐǂǦƼƔǦǃữƶ.",
    ["今日叫你来，是为着这份谱子。"] = "ƣƇǂǦǃƶǓǦƼọƾǦǂǊộƾǦǉớƾǦǁƐǦǋƔǦƷảǃǦǃƽạƸǦǅƽổǦǃƐǓ.",
    ["……姐姐还有这份心思。我们如今，不过是前朝旧人，能在这宫墙里苟延残喘，留得一条性命，已是天恩。旁的，哪里还敢奢望……"] = "……ǦǥỷǦǉỷǦǋẫǃǦƸƛǃǦǉƁǂǦǉǇƓǦǃƐǓǦǈƶǄ.ǦƞƽƕǃƼǦǉƶǦƷƁǓǦƼƾờǦƸƽẳǃƼǦǆǊƶǦǁƐǦǃƼườƾǦƸũǦǉƾềǃǦǉǇƾềǊ,ǦƸƚǦǉƽểǦǉƽǄƾǦǉƽƚǅǦǉǇǄǃƼǦƷốǃǦƷứƸǦǉườǃƼǦƸǊǃƼǦƸấǂǦǃƐǓ,ǦƼƾữǦđượƸǦƸƑƾǦǂạǃƼǦđƃǦǁƐǦơǃǦǉǇờƾǦǇồƾ.ǦƩƽữǃƼǦǉƽứǦǀƽƑƸ,ǦđƁǊǦǤƑǂǦǍƶǦǋọǃƼ……",
    ["是啊，不敢想了。从前争的是圣眷，如今争的，是天命。可这日子总要过下去。这谱子，你我一齐合一合，就当是……给自己找个念想吧。"] = "ƫƽảƾǦǇồƾ,ǦǀƽƇǃƼǦǤƑǂǦǃƼƽĩǦǉớƾǦǃữƶ.ǦǥǇướƸǦǀƾƶǦǉǇƶǃƽǦǈủǃƼǦƑƾ,ǦƼƾờǦđƁǓǦǉǇƶǃƽǦǉƽƾƙǃǦǂệǃƽ.ǦƩƽưǃƼǦǃƼƐǓǦǉƽƑǃƼǦǋẫǃǦǅƽảƾǦǈốǃƼǦǉƾếǅǦǉƽƇƾ.ǦƝảǃǦǃƽạƸǦǃƐǓ,ǦǉỷǦǂǊộƾǦǉƶǦƸƖǃƼǦƽợǅǦǉấǊ,ǦƸǄƾǦǃƽưǦǁƐ……ǦǉƔǂǦƸƽǄǦǂƔǃƽǦǂộǉǦƸƽƕǉǦǃƾềǂǦƶǃǦủƾǦǋậǓ.",
    ["娘子！整日沉迷斗蛐蛐又又什么用！得多走出去，走到外面去，和其他娘子说说话啊！"] = "ƩươǃƼǦǉử!ǦƞảǦǃƼƐǓǦđắǂǦđǊốƾǦǋƐǄǦđấǊǦǤếǦǉƽƔǦƸƚǦƓƸƽǦƼƔǦƸƽứ!ǦƫƽảƾǦđƾǦǇƶǦǃƼǄƐƾǦǃƽƾềǊǦƽơǃ,ǦǇƶǦƷƙǃǦǃƼǄƐƾǦǉǇƛǦƸƽǊǓệǃǦǋớƾǦƸƑƸǦǃươǃƼǦǉửǦǀƽƑƸǦđƾǦạ!",
    ["娘子，您也是后周留下来的老人，您看看人家范娘子，每日打打五禽戏，强身健体，多好呀！"] = "ƩươǃƼǦǉử,ǦǃƼườƾǦƸũǃƼǦǁƐǦǃƼườƾǦƸũǦƸủƶǦƣậǊǦƞƽǊǦđểǦǁạƾ,ǦǃƼườƾǦǍƺǂǦƫƽạǂǦǃươǃƼǦǉửǦǀƔƶ,ǦǂỗƾǦǃƼƐǓǦǉậǅǦƩƼũǦƞầǂǦƣƓ,ǦƸườǃƼǦǉƽƁǃǦǀƾệǃǦǉƽể,ǦǉốǉǦƷƾếǉǦƷƶǄ!",
    ["陆娘子都知道逗猫了，高娘子和王娘子都握手言和了，连最多愁善感的李娘子，也知道弹弹琴了。"] = "ƧụƸǦǃươǃƼǦǉửǦđƃǦƷƾếǉǦǉǇƙǊǦǂƘǄǦǇồƾ,ǦƞƶǄǦǃươǃƼǦǉửǦǋƐǦƱươǃƼǦǃươǃƼǦǉửǦđềǊǦđƃǦƷắǉǦǉƶǓǦƼƾảǃƼǦƽƛƶ,ǦđếǃǦƸảǦƧƈǦǃươǃƼǦǉửǦđƶǦǈầǊǦđƶǦƸảǂǦǃƽấǉǦƸũǃƼǦđƃǦƷƾếǉǦƼảǓǦđƐǃǦǇồƾ.",
    ["也就您，一次后苑游船都不去，唉，唉……您真就打算在这里瞧着这片四方天，赏一辈子花，观一辈子鸟，斗一辈子蛐蛐吗？"] = "ƞƽỉǦƸƚǦǃƼườƾǦǁƐǦǂộǉǦǁầǃǦđƾǦǉƽǊǓềǃǦởǦƽậǊǦǊǓểǃǦƸũǃƼǦǀƽƇǃƼǦđƾ,ǦƑƾǦƸƽƐ,ǦƑƾǦƸƽƐ……ǦǃƼườƾǦđịǃƽǦƸứǦởǦđƁǓǦǃƼắǂǦǂảǃƽǦǉǇờƾǦǋǊƇǃƼǦǃƐǓ,ǦǉƽưởǃƼǦƽǄƶǦƸảǦđờƾ,ǦǍƺǂǦƸƽƾǂǦƸảǦđờƾ,ǦđấǊǦǤếǦƸảǦđờƾǦǉƽậǉǦǈƶǄ?",
    ["不、不可以吗……求、求轻喷……"] = "Ʀƽ-ǀƽƇǃƼǦđượƸǦǈƶǄ……ǦƞầǊ,ǦƸầǊǦǃươǃƼǦǉƶǓǦđừǃƼǦǂắǃƼ……",
    ["多日未见，郑王殿下又长高了。"] = "ƩƽƾềǊǦǃƼƐǓǦǀƽƇǃƼǦƼặǅ,ǦǥǇịǃƽǦƱươǃƼǦđƾệǃǦƽạǦǁạƾǦƸƶǄǦǉƽƙǂǦǇồƾ.",
    ["小孩子长得就是快啊！"] = "ǥǇẻǦƸǄǃǦǁớǃǦǃƽƶǃƽǦǉƽậǉǦđấǓ!",
    ["郑王殿下又去踢蹴鞠了？"] = "ǥǇịǃƽǦƱươǃƼǦđƾệǃǦƽạǦǁạƾǦđƾǦđƑǦƸầǊǦ(ǍƕƸǦƸƕƸ)ǦǇồƾǦǈƶǄ?",
    ["那是官家前儿才赏下的新蹴鞠，殿下喜欢，是好事。"] = "ĐƚǦǁƐǦǆǊảǦƸầǊǦǂớƾǦǂƐǦƬǊƶǃǦƼƾƶǦǋừƶǦƷƶǃǦƸƽǄǦƽƇǂǦǃọ,ǦđƾệǃǦƽạǦǉƽƓƸƽǦǁƐǦƸƽǊǓệǃǦǉốǉ.",
    ["也是。小孩子嘛，正是好动的时候。"] = "ƞũǃƼǦđƕǃƼ.ǦǥǇẻǦƸǄǃǦǂƐ,ǦƸƽƓǃƽǦǁƐǦǁƕƸǦƽƾếǊǦđộǃƼǦǃƽấǉ.",
    ["也正是长身体的时候，上面吩咐过了，得好生照料着，可不能短了什么。"] = "ƞũǃƼǦǁƐǦǁƕƸǦđƶǃƼǦǉǊổƾǦăǃǦǉǊổƾǦǁớǃ,ǦƷƙǃǦǉǇƙǃǦđƃǦǤặǃǦǤƛǦǇồƾ,ǦǅƽảƾǦƸƽăǂǦǈƚƸǦƸƽǄǦǉốǉ,ǦǀƽƇǃƼǦđượƸǦđểǦǉƽƾếǊǦǉƽốǃǦǉƽứǦƼƔ.",
    ["吵死了！这屋檐上的鸟雀叽叽喳喳的，叫得人心烦……"] = "ỒǃǦƸƽếǉǦđƾǦđượƸ!ǦƧũǦƸƽƾǂǦƸƽƚƸǦǉǇƙǃǦǂƑƾǦƽƾƙǃǦƸứǦǀƙǊǦǁƓǊǦǁǄǦǁƓǊǦǁǄ,ǦǃƼƽƺǦǂƐǦǅƽƑǉǦǅƽƾềǃ……",
    ["屋檐上啥时候多了个鸟窝？俺去找个梯子把它给捅了。"] = "ǥǇƙǃǦǂƑƾǦƽƾƙǃǦƸƚǦƸƑƾǦǉổǦƸƽƾǂǦǉừǦƷƶǄǦƼƾờǦǉƽế?ǦĐểǦǉƶǦđƾǦǉƔǂǦƸƑƾǦǉƽƶǃƼǦƸƽọƸǦǉƽủǃƼǦǃƚǦđƾ.",
    ["别别别！马哥，你不要命啦？"] = "ĐừǃƼǦđừǃƼǦđừǃƼ!ǦƨƃǦƸƶ,ǦƽǊǓǃƽǦǀƽƇǃƼǦƸầǃǦǂạǃƼǦǃữƶǦƐ?",
    ["为啥？就一个破鸟窝，还动不得它了？"] = "ǥạƾǦǈƶǄ?ǦƞƽỉǦǁƐǦƸƑƾǦǉổǦƸƽƾǂǦǇƑƸƽ,ǦƸƛǃǦǀƽƇǃƼǦđộǃƼǦǋƐǄǦđượƸǦƸƽắƸ?",
    ["过来过来，哎，凑近点……"] = "ƧạƾǦđƁǓǦǁạƾǦđƁǓ,ǦǃƐǓ,ǦƼƽƗǦǈƑǉǦǋƐǄǦǂộǉǦƸƽƕǉ……",
    ["咱们官家，行伍出身，擅长弓射，这你知道吧？"] = "ƬǊƶǃǦƼƾƶǦǃƽƐǦǉƶǦǁƐǦǤƁǃǦǃƽƐǦƷƾǃƽǦ(ƽƐǃƽǦǃƼũ),ǦƼƾỏƾǦǋềǦƸǊǃƼǦǍạ,ǦƸƑƾǦǃƐǓǦƽǊǓǃƽǦƷƾếǉǦƸƽứ?",
    ["天下人都知道啊！这和鸟窝有啥关系？"] = "ǥƽƾƙǃǦƽạǦƶƾǦƸƽẳǃƼǦƷƾếǉ!ǦǥƽếǦǉƽƔǦǁƾƙǃǦǆǊƶǃǦƼƔǦđếǃǦƸƑƾǦǉổǦƸƽƾǂ?",
    ["官家见到鸟雀，兴致上来了，耍了大半天，那可真是百发百中！"] = "ƬǊƶǃǦƼƾƶǦǂƐǦǉƽấǓǦƸƽƾǂǦƸƽƚƸ,ǦǃổƾǦƽứǃƼǦǁƙǃǦǁƐǦƸƽơƾǦđƖƶǦƸảǦƷǊổƾ,ǦǆǊảǦǉƽựƸǦǁƐǦƷƑƸƽǦǅƽƑǉǦƷƑƸƽǦǉǇƕǃƼ!",
    ["你说，要是把这鸟窝掏了，岂不是扫官家的兴嘛。"] = "ƣǊǓǃƽǦƷảǄǦǍƺǂ,ǦǃếǊǦƼƾờǦƽǊǓǃƽǦǅƽƑǦƸƑƾǦǉổǦƸƽƾǂǦǃƐǓ,ǦƸƽẳǃƼǦǅƽảƾǦǁƐǂǦƬǊƶǃǦƼƾƶǦǂấǉǦƽứǃƼǦǈƶǄ.",
    ["得了吧，你可别唬我！"] = "ǥƽƇƾǦđƾ,ǦƽǊǓǃƽǦđừǃƼǦƸƚǦƽƖǦǉƶ!",
    ["千真万确！守这后苑门的禁军胡班头，那是我亲小舅子！这话就跟你说，千万别往外传。"] = "ƩƚƾǦƸƚǦǈƑƸƽǦǂƑƸƽǦƸƚǦƸƽứǃƼ!ǦƣồǦƷƶǃǦđầǊǦƸủƶǦƞấǂǦǆǊƁǃǦƸƶǃƽǦƸổǃƼǦƽậǊǦǊǓểǃǦƸƽƓǃƽǦǁƐǦƺǂǦǋợǦƸủƶǦǉƶ!ǦƞƽǊǓệǃǦǃƐǓǦǉƶǦƸƽỉǦǃƚƾǦǋớƾǦƽǊǓǃƽǦǉƽƇƾ,ǦǃƼƽƔǃǦǋạǃǦǁầǃǦđừǃƼǦƸƚǦǇƛǦǇỉǦǇƶǦǃƼǄƐƾ.",
    ["二哥，我、我给你丢脸了……"] = "ƩƽịǦƸƶ,ǦǂǊộƾ,ǦǂǊộƾǦǁƐǂǦƽǊǓǃƽǦǂấǉǦǂặǉǦǇồƾ……",
    ["有点本事!能赢过我小弟，我允许你和我比试比试了!"] = "ƞũǃƼǦƸƚǦƷảǃǦǁĩǃƽǦđấǓ!ǦǥƽắǃƼǦđượƸǦǉƾểǊǦđệǦƸủƶǦǉƶ,ǦǉƶǦƸƽǄǦǅƽƗǅǦǃƼươƾǦǉỉǦǉƽƓǦǋớƾǦǉƶǦǂộǉǦǉǇậǃ!",
    ["说好了，我赢了你们就从这里让开，你们两个不许再拦住我了!"] = "ƩƚƾǦǇồƾǦǃƽƗ,ǦǉƶǦǉƽắǃƼǦǉƽƔǦƸƑƸǦǃƼươƾǦǅƽảƾǦǉǇƑǃƽǦđườǃƼ,ǦƽƶƾǦǃƼườƾǦǀƽƇǃƼǦđượƸǦƸảǃǦǉƶǦǃữƶ!",
    ["你别得意，等冬天我大哥就回来了！到时候……哼！"] = "ƩƼươƾǦđừǃƼǦƸƚǦđắƸǦƈ,ǦđợƾǦđếǃǦǂƖƶǦđƇǃƼǦđạƾǦƸƶǦǉƶǦǋềǦǇồƾ!ǦĐếǃǦǁƕƸǦđƚ……Ǧƽừ!",
    ["咦，有两下子啊!"] = "Ồ,ǦƸũǃƼǦǀƽƑǦđấǓǦƸƽứ!",
    ["咦，可中，能赶上我了！"] = "Ồ,ǦđượƸǦđấǓ,ǦǈắǅǦđǊổƾǦǀịǅǦǉƶǦǇồƾ!",
    ["侠行无言，收集到封龙书院群侠姓名，可将其刻至碑上。"] = "ƣƾệǅǦƽƐǃƽǦǋƇǦǃƼƇǃ,ǦđƃǦǉƽǊǦǉƽậǅǦđượƸǦǤƶǃƽǦǉƓǃƽǦǆǊầǃǦƽƾệǅǦƸủƶǦƫƽǄǃƼǦƧǄǃƼǦǥƽưǦƱƾệǃ,ǦƸƚǦǉƽểǦǀƽắƸǦǁƙǃǦƷƾƶ.",
    ["这话本子……虽说早几日看过了，可这再看……"] = "ƬǊǓểǃǦǉƽǄạƾǦƷảǃǦǃƐǓ……ǦǉǊǓǦđƃǦǍƺǂǦǉừǦǂấǓǦǃƼƐǓǦǉǇướƸ,ǦǃƽưǃƼǦƼƾờǦǍƺǂǦǁạƾ……",
    ["唉，莫说起承转合，连点文戏也无，尽是些你来我往的拳脚功夫。"] = "ƣƶƾǏǏ,ǦđừǃƼǦǃƚƾǦƸƽƾǦđếǃǦǀƽƶƾǦǉƽừƶǦƸƽǊǓểǃǦƽợǅ,ǦǃƼƶǓǦƸảǦǂộǉǦƸƽƕǉǦǋăǃǦƽƓǦƸũǃƼǦǀƽƇǃƼǦƸƚ,ǦǉǄƐǃǦǁƐǦǃƽữǃƼǦǂƐǃǦǂƕƶǦǉƶǓǦǂƕƶǦƸƽƁǃǦđấǂǦđƑǦǆǊƶǦǁạƾ.",
    ["当真让他试演？不行不行！"] = "ǥƽậǉǦǈựǦđểǦƽắǃǦǤƾễǃǦǉƽửǦǈƶǄ?ǦƦƽƇǃƼǦđượƸ,ǦǀƽƇǃƼǦđượƸǦđƁǊ!",
    ["还是把这话本收起来，让他们没法演算了……"] = "ƣƶǓǦǁƐǦƸấǉǦǆǊǓểǃǦǉƽǄạƾǦƷảǃǦǃƐǓǦđƾ,ǦđểǦƷọǃǦƽọǦǀƽƇǃƼǦƸƚǦƸƑƸƽǦǃƐǄǦǤƾễǃǦǉậǅǦǃữƶ……",
    ["我不服！再来一把！"] = "ǥƶǦǀƽƇǃƼǦǅƽụƸ!ǦƧƐǂǦǋƑǃǦǃữƶ!",
    ["要死了你，小点声！别吵到官家休息！"] = "ƩƼươƾǦǂǊốǃǦƸƽếǉǦƐ,ǦǃƽỏǦǉƾếǃƼǦǉƽƇƾ!ǦĐừǃƼǦǁƐǂǦǅƽƾềǃǦƬǊƶǃǦƼƾƶǦǃƼƽỉǦǃƼơƾ!",
    ["嗯？你是新来的吧，那不知道也正常。“福坤杯”蹴鞠赛即将开赛，我俩正在争官家那队的最后一个名额呢！"] = "ƣử?ǦƩƼươƾǦǁƐǦǃƼườƾǦǂớƾǦđƕǃƼǦǀƽƇǃƼ,ǦǉƽếǦǉƽƔǦǀƽƇǃƼǦƷƾếǉǦƸũǃƼǦǁƐǦƸƽǊǓệǃǦǉƽườǃƼ.ǦƢƾảƾǦǍƕƸǦƸƕƸǦ\"ƫƽƕƸǦƦƽƇǃǦƝƇƾ\"ǦǈắǅǦǀƽƶƾǦǂạƸǦǇồƾ,ǦƽƶƾǦǉƶǦđƶǃƼǦǉǇƶǃƽǦǈǊấǉǦƸǊốƾǦƸƖǃƼǦǉǇǄǃƼǦđộƾǦƸủƶǦƬǊƶǃǦƼƾƶǦđấǓ!",
    ["不知这“福坤杯”是……？"] = "ƞƽẳǃƼǦƽƶǓǦ\"ƫƽƕƸǦƦƽƇǃǦƝƇƾ\"ǦǃƐǓǦǁƐ……?",
    ["是我们福宁殿与坤宁殿的蹴鞠友谊赛，获胜队里每人都能得一杯官家珍藏的陈酿，因此我们将这比赛唤作“福坤杯”。"] = "ƧƐǦǉǇậǃǦǍƕƸǦƸƕƸǦƽữǊǦǃƼƽịǦƼƾữƶǦƫƽƕƸǦƩƾǃƽǦĐƾệǃǦǋƐǦƦƽƇǃǦƩƾǃƽǦĐƾệǃǦƸƽƕǃƼǦǉƶ,ǦǂỗƾǦǃƼườƾǦǉǇǄǃƼǦđộƾǦǉƽắǃƼǦƸǊộƸǦǈẽǦđượƸǦǉƽưởǃƼǦǂộǉǦǁǓǦǇượǊǦǆǊƈǦǂƐǦƬǊƶǃǦƼƾƶǦǉǇƁǃǦǉƐǃƼ,ǦǋƔǦǉƽếǦƸƽƕǃƼǦǉƶǦƼọƾǦƼƾảƾǦđấǊǦǃƐǓǦǁƐǦ\"ƫƽƕƸǦƦƽƇǃǦƝƇƾ\".",
    ["不过，因为前些日子医官劝官家莫再纵饮，也不知，这次还有没有陈酿可品了……"] = "ƞƚǦđƾềǊ,ǦǋƔǦǂấǓǦƽƇǂǦǉǇướƸǦǓǦǆǊƶǃǦǀƽǊǓƙǃǦƬǊƶǃǦƼƾƶǦđừǃƼǦǊốǃƼǦǆǊƑǦƸƽƗǃǦǃữƶ,ǦǃƙǃǦǀƽƇǃƼǦƷƾếǉǦǁầǃǦǃƐǓǦǁƾệǊǦƸƛǃǦǇượǊǦǃƼǄǃǦđểǦǉƽưởǃƼǦǉƽứƸǦǀƽƇǃƼ……",
    ["什么？！不行不行，你赶紧跟我决一胜负，我赢了你之后再去官家！……我还一次没尝到过那陈酿的滋味呢！"] = "ƞƑƾǦƼƔ?!ǦƦƽƇǃƼǦđượƸ,ǦǃƼươƾǦǂƶǊǦǅƽƁǃǦǉƽắǃƼǦƷạƾǦǋớƾǦǉƶǦđƾ,ǦǉƶǦǉƽắǃƼǦǃƼươƾǦǇồƾǦƸƛǃǦđƾǦǉƔǂǦƬǊƶǃǦƼƾƶ!……ǦǥƶǦƸƛǃǦƸƽưƶǦǂộǉǦǁầǃǦđượƸǦǃếǂǦǂƖƾǦǋịǦƸủƶǦǁǄạƾǦǇượǊǦǆǊƈǦđƚǦđƁǊ!",
    ["后头那个一天就知道叨叨鱼的那位，究竟是咋混进咱福宁殿五大高手行列的……"] = "ƞƑƾǦǋịǦđứǃƼǦđằǃƼǦǈƶǊǦǉốƾǦǃƼƐǓǦƸƽỉǦƷƾếǉǦǁảƾǦǃƽảƾǦǋềǦƸƑǦǀƾƶ,ǦǇốǉǦƸǊộƸǦǁƐǦǉǇƐǦǉǇộǃǦǋƐǄǦƽƐǃƼǦǃƼũǦǃăǂǦđạƾǦƸƶǄǦǉƽủǦƸủƶǦƫƽƕƸǦƩƾǃƽǦĐƾệǃǦǉƶǦǀƾểǊǦƼƔǦǋậǓ……",
    ["大哥你可小点声吧！上次质疑他还被他听到了的那位，后来被揍得跟那刚被捞上岸，无能扑腾的胖鱼没啥两样……"] = "ĐạƾǦƸƶǦƽǊǓǃƽǦǃƽỏǦǉƾếǃƼǦƸƽƕǉǦđƾ!ǦƞƑƾǦǋịǦǁầǃǦǉǇướƸǦǃƼƽƾǦǃƼờǦƽắǃǦǂƐǦƷịǦƽắǃǦǃƼƽƺǦǉƽấǓǦấǓ,ǦǈƶǊǦđƚǦƷịǦǉẩǃǦƸƽǄǦǇƶǦƷƃ,ǦƸƽẳǃƼǦǀƽƑƸǦƼƔǦƸǄǃǦƸƑǦƷƗǄǦǋừƶǦƷịǦǋớǉǦǁƙǃǦƷờ,ǦǋƖǃƼǦǋẫǓǦǉǇǄǃƼǦǋƇǦǋọǃƼǦđƁǊ……",
    ["哟，又起风了……也不知官家近日想不想放风筝？"] = "Ồ,ǦƼƾƚǦǁạƾǦǃổƾǦǇồƾ……ǦǀƽƇǃƼǦƷƾếǉǦǤạǄǦǃƐǓǦƬǊƶǃǦƼƾƶǦƸƚǦǂǊốǃǦǉƽảǦǤƾềǊǦǀƽƇǃƼǦǃƽỉ?",
    ["我问申大夫如何才能变得像官家那样强壮，他让我一日吃十只鸡，但只能吃其胸前的肉！"] = "ǥƶǦƽỏƾǦǥƽƁǃǦđạƾǦǅƽǊǦǁƐǂǦǈƶǄǦđểǦǉǇởǦǃƙǃǦƸườǃƼǦǉǇƑǃƼǦǃƽưǦƬǊƶǃǦƼƾƶ,ǦƇǃƼǦấǓǦƷảǄǦǉƶǦǂỗƾǦǃƼƐǓǦăǃǦǂườƾǦƸǄǃǦƼƐ,ǦǃƽưǃƼǦƸƽỉǦđượƸǦăǃǦǅƽầǃǦứƸǦǉƽƇƾ!",
    ["那剩下的部位咋办？留着给兄弟们加餐？要是敢浪费粮食，看官家怎么揍你。"] = "ǥƽếǦǅƽầǃǦƸƛǃǦǁạƾǦǉƽƔǦǈƶǄ?ǦĐểǦǤƐǃƽǦǉƽƙǂǦƷữƶǦƸƽǄǦƶǃƽǦƺǂǦƐ?ǦƩƼươƾǦǂƐǦǤƑǂǦǁƃǃƼǦǅƽƓǦǁươǃƼǦǉƽựƸǦǉƽƔǦǍƺǂǦƬǊƶǃǦƼƾƶǦǃệǃǦǃƼươƾǦǉƽếǦǃƐǄ.",
    ["梅英，你上次给我推荐的话本子我看完了！感觉没有先前我说的那本好看！"] = "ƨƶƾǦƜǃƽ,ǦǆǊǓểǃǦǉƽǄạƾǦƷảǃǦǁầǃǦǉǇướƸǦǉỷǦƼƾớƾǦǉƽƾệǊǦǂǊộƾǦǍƺǂǦǍǄǃƼǦǇồƾ!ǦƞảǂǦƼƾƑƸǦǀƽƇǃƼǦƽƶǓǦƷằǃƼǦǆǊǓểǃǦǁầǃǦǉǇướƸǦǂǊộƾǦǃƚƾ!",
    ["真羡慕你，每次干活都那么快，还有那么多时间可以看书……"] = "ǥƽậǉǦƽƁǂǦǂộǦǉỷǦǆǊƑ,ǦǁầǃǦǃƐǄǦǁƐǂǦǋƾệƸǦƸũǃƼǦǃƽƶǃƽǦǃƽưǦǋậǓ,ǦǁạƾǦƸƛǃǦƸƚǦƷƶǄǦǃƽƾƙǊǦǉƽờƾǦƼƾƶǃǦđểǦđọƸǦǈƑƸƽ……",
    ["这本册子原本是放在哪的来着……罢了罢了，官家最近可能要看的，就放在这边好了。"] = "ƬǊǓểǃǦǈổǦǃƐǓǦǋốǃǦǤĩǦđặǉǦởǦđƁǊǦǃƽỉ……ǦǉƽƇƾǦǉƽƇƾ,ǦƬǊƶǃǦƼƾƶǦǤạǄǦǃƐǓǦƸƽắƸǦǁƐǦǂǊốǃǦǍƺǂ,ǦƸứǦđặǉǦởǦƷƙǃǦǃƐǓǦǋậǓ.",
    ["这边这几册官家许久没翻过了，都收回去好了。"] = "ƨấǓǦǆǊǓểǃǦƷƙǃǦǃƐǓǦƬǊƶǃǦƼƾƶǦđƃǦǁƁǊǦǀƽƇǃƼǦǁậǉǦǉớƾ,ǦƸấǉǦƽếǉǦđƾǦǉƽƇƾ.",
    ["这几册应是新送来的，先前没见过。那便都收到显眼点的位置好了。官家到时一眼就能看到。"] = "ƨấǓǦǆǊǓểǃǦǃƐǓǦƸƽắƸǦǁƐǦǂớƾǦƼửƾǦǉớƾ,ǦǉǇướƸǦǀƾƶǦƸƽưƶǦǉƽấǓǦƷƶǄǦƼƾờ.ǦƱậǓǦǉƽƔǦƸứǦđểǦởǦǋịǦǉǇƓǦǤễǦǃƽƔǃǦǂộǉǦƸƽƕǉ.ǦƬǊƶǃǦƼƾƶǦǉớƾǦǁƕƸǦđƚǦǃƽƔǃǦǂộǉǦƸƑƾǦǁƐǦǉƽấǓǦǃƼƶǓ.",
    ["……方才放在这的柱斧哪去了？噢！我收到盒子里了！"] = "……ǦƞƑƾǦǥǇụǦƫƽủǦǋừƶǦǃƃǓǦđểǦởǦđƁǓǦđƁǊǦǇồƾǦǃƽỉ?ǦỒ!ǦǥƶǦƸấǉǦǋƐǄǦǉǇǄǃƼǦƽộǅǦǇồƾ!",
    ["眼前这些锣鼓旌旗，皆为大典所用，若有闪失，实在担待不起。"] = "ƞƽƾƙǃƼǦǉǇốǃƼǦƸờǦǍƓǦǉǇướƸǦǂắǉǦǃƐǓǦđềǊǦǤƖǃƼǦƸƽǄǦđạƾǦđƾểǃ,ǦǃếǊǦƸƚǦǈƶƾǦǈƚǉǦƼƔ,ǦǉƽựƸǦǈựǦƼƑǃƽǦǋƑƸǦǀƽƇǃƼǦǃổƾ.",
    ["定是，定是我看花了眼……宫中怎会有鬼……"] = "ƞƽắƸǦƸƽắǃǦǁƐ,ǦƸƽắƸǦƸƽắǃǦǁƐǦǉƶǦƽǄƶǦǂắǉǦǇồƾ...ǦǉǇǄǃƼǦƸǊǃƼǦǈƶǄǦƸƚǦǉƽểǦƸƚǦǂƶ...",
    ["仔细听好了——彼时大典，来的皆是头顶青天的人物。洒扫除尘之事，须得地砖照影，断不能留半点尘芥。"] = "ƩƼƽƺǦƸƽǄǦǀỹǦđƁǓǦ——ǦđạƾǦđƾểǃǦǀƽƾǦđƚ,ǦǃƽữǃƼǦǃƼườƾǦđếǃǦđềǊǦǁƐǦƷậƸǦđạƾǦǃƽƁǃǦǋậǉǦǉƽƇǃƼǦǉƽƾƙǃ.ǦƱƾệƸǦǆǊƗǉǦǤọǃǦƷụƾǦƷặǂǦǅƽảƾǦđạǉǦđếǃǦǂứƸǦƼạƸƽǦǁƑǉǦǈǄƾǦƷƚǃƼǦǃƼườƾ,ǦǉǊǓệǉǦđốƾǦǀƽƇǃƼǦđượƸǦđểǦǁạƾǦǃửƶǦƽạǉǦƷụƾ.",
    ["定是唬人的！宫内怎会闹鬼……"] = "ƞƽắƸǦƸƽắǃǦǁƐǦƽƖǦǃƼườƾǦǉƽƇƾ!ǦǥǇǄǃƼǦƸǊǃƼǦǈƶǄǦǂƐǦǃƽƑǉǦǂƶǦđượƸ...",
    ["小的明白，小的一定留意。"] = "ǥƾểǊǦǃƽƁǃǦđƃǦǇƅ,ǦǉƾểǊǦǃƽƁǃǦǃƽấǉǦđịǃƽǦǈẽǦǁưǊǦƈ.",
    ["来人留步！崇元殿乃礼仪重地，素有铁律——为表敬重，任何人等，皆不可携兵刃近前。"] = "ƩƼườƾǦđếǃǦǤừǃƼǦƷướƸ!ǦƮƖǃƼǦƩƼǊǓƙǃǦĐƾệǃǦǁƐǦǉǇọǃƼǦđịƶǦǁễǦǃƼƽƾ,ǦǋốǃǦƸƚǦǉƽƾếǉǦǁǊậǉǦ——ǦđểǦƷƾểǊǦǉƽịǦǈựǦǀƓǃƽǦǉǇọǃƼ,ǦƷấǉǦƸứǦƶƾǦƸũǃƼǦǀƽƇǃƼǦđượƸǦǂƶǃƼǦǉƽƺǄǦƷƾǃƽǦǀƽƓǦđếǃǦƼầǃ.",
    ["还请同袍在此解下兵刃。"] = "ƨờƾǦđồǃƼǦƷƐǄǦǉƽƑǄǦƷỏǦƷƾǃƽǦǀƽƓǦǉạƾǦđƁǓ.",
    ["多谢同袍。接下来，还请配合查验身份。"] = "ĐƶǦǉạǦđồǃƼǦƷƐǄ.ǦǥƾếǅǦǉƽƺǄ,ǦǂờƾǦǅƽốƾǦƽợǅǦǉǇƶǦǃƼƽƾệǂǦǉƽƁǃǦǅƽậǃ.",
    ["$T(2031)，抬头！得瞧瞧你这张脸是不是真的。"] = "$T(2031),ǦǃƼẩǃƼǦđầǊǦǁƙǃ!ǦƫƽảƾǦǍƺǂǦǉƽửǦƸƑƾǦǂặǉǦǃƐǓǦƸủƶǦǃƼươƾǦƸƚǦǅƽảƾǦǁƐǦǉƽậǉǦǀƽƇǃƼ.",
    ["怎么，还怕有人乔装打扮混进去不成？"] = "ƮƶǄǦƽả,ǦƸƛǃǦǈợǦƸƚǦǃƼườƾǦƸảƾǦǉǇƶǃƼǦǉǇƐǦǉǇộǃǦǋƐǄǦƸƽắƸ?",
    ["嘿，上个月还真揪住个贴假胡子的！"] = "ƣƙ,ǦǉƽƑǃƼǦǉǇướƸǦđƕǃƼǦǁƐǦǉƚǂǦđượƸǦǂộǉǦǉƙǃǦǤƑǃǦǇƁǊǦƼƾảǦđấǓ!",
    ["胳膊也得抬起来，往左转转。"] = "ƞƑǃƽǦǉƶǓǦƸũǃƼǦǅƽảƾǦƼƾơǦǁƙǃ,ǦǍǄƶǓǦǈƶǃƼǦǉǇƑƾǦƸƽƕǉ.",
    ["再往右转转。"] = "ƧạƾǦǍǄƶǓǦǈƶǃƼǦǅƽảƾǦƸƽƕǉ.",
    ["再原地蹦蹦？"] = "ƩƽảǓǦǉạƾǦƸƽỗǦǂấǓǦƸƑƾǦǍƺǂǦǈƶǄ?",
    ["万一袖子里藏了兵刃！"] = "ƩƽỡǦđƁǊǦǉǇǄǃƼǦǉƶǓǦƑǄǦƼƾấǊǦƷƾǃƽǦǀƽƓǦǉƽƔǦǈƶǄ!",
    ["验明了？这下能进了吧。"] = "ƩƼƽƾệǂǦǍǄǃƼǦƸƽưƶ?ǦƢƾờǦǉƽƔǦǋƐǄǦđượƸǦǇồƾǦƸƽứ.",
    ["好了，多谢配合。规制如此，不容马虎，多担待啊。"] = "ĐượƸǦǇồƾ,ǦđƶǦǉạǦđƃǦǅƽốƾǦƽợǅ.ǦƬǊǓǦƸƽếǦǁƐǦǋậǓ,ǦǀƽƇǃƼǦđượƸǦǁơǦǁƐ,ǦǂǄǃƼǦǁượǃƼǦǉƽứǦƸƽǄ.",
    ["辛苦大人。那，我便进去了？"] = "ƱấǉǦǋảǦƸƽǄǦđạƾǦǃƽƁǃǦǇồƾ.ǦƱậǓ,ǦǉƶǦǋƐǄǦǃƽƗ?",
    ["且慢，最后提醒一句，崇元殿乃宫中礼仪大殿，殿内器皿皆不可擅动。"] = "ƦƽǄƶǃǦđƃ,ǦǃƽắƸǦǃƽởǦƸƁǊǦƸǊốƾ,ǦƮƖǃƼǦƩƼǊǓƙǃǦĐƾệǃǦǁƐǦđạƾǦđƾệǃǦǁễǦǃƼƽƾǦǉǇǄǃƼǦƸǊǃƼ,ǦǀƽƓǦƸụǦƷƙǃǦǉǇǄǃƼǦđềǊǦǀƽƇǃƼǦđượƸǦǉựǦƈǦđộǃƼǦǋƐǄ.",
    ["嗐，行了！且让$T(30)进去吧。若坏了事，自有人教$T(30)规矩！"] = "ƣạƾ,ǦđượƸǦǇồƾ!ǦƞứǦđểǦ$T(30)ǦǋƐǄǦđƾ.ǦƩếǊǦƽỏǃƼǦǋƾệƸ,ǦǉựǦǀƽắƸǦƸƚǦǃƼườƾǦǤạǓǦƸƽǄǦ$T(30)ǦǆǊǓǦƸủ!",
    ["这儿——还缺个灯架，先记着，回头补上……"] = "ƞƽỗǦǃƐǓǦ——ǦƸƛǃǦǉƽƾếǊǦǂộǉǦƸƑƾǦƼƾƑǦđƘǃ,ǦƸứǦƼƽƾǦǁạƾǦđƃ,ǦǁƑǉǦǃữƶǦƷổǦǈǊǃƼǦǈƶǊ...",
    ["那旧香炉都生锈了，上头怎也不换个新的？"] = "ƞƑƾǦǁưǦƽươǃƼǦƸũǦđƚǦƼỉǦǈƗǉǦƽếǉǦǇồƾ,ǦƷƙǃǦǉǇƙǃǦǈƶǄǦǀƽƇǃƼǦǉƽƶǓǦƸƑƾǦǂớƾǦđƾ?",
    ["哎呦喂，是武德司的老爷呐！什么风把您给吹来了！"] = "ÁƾǦƸƽƐǦƸƽƐ,ǦǁƐǦǁƃǄǦƼƾƶǦƸủƶǦƱƅǦĐứƸǦǥǓǦǃƐ!ǦƢƾƚǦǃƐǄǦǉƽổƾǦǃƼƐƾǦđếǃǦđƁǓǦǋậǓ!",
    ["这儿灰尘大，可不敢脏了您的官靴！"] = "ƞƽỗǦǃƐǓǦƷụƾǦƷặǂǦǁắǂ,ǦǀƽƇǃƼǦǤƑǂǦđểǦƷẩǃǦđƇƾǦủǃƼǦǆǊƶǃǦƸủƶǦǃƼƐƾǦđƁǊ!",
    ["快请外头歇歇，这儿交给小的就行！"] = "ƨờƾǦǃƼƐƾǦǇƶǦǃƼǄƐƾǦǃƼƽỉǦǃƼơƾ,ǦƸƽỗǦǃƐǓǦƸứǦƼƾƶǄǦƸƽǄǦǉƾểǊǦǃƽƁǃǦǁƐǦđượƸ!",
    ["规矩，都记清楚了？届时大典之上，文武百官的眼睛都盯着。若有毫厘差池，轻则扣一月俸禄，重则，仪鸾司也保不住你们。"] = "ƬǊǓǦƸủǦđƃǦǃƽớǦǀỹǦƸƽưƶ?ǦĐếǃǦǁƕƸǦđạƾǦđƾểǃ,ǦǉƶƾǦǂắǉǦƸủƶǦǋăǃǦǋƅǦƷƑǦǆǊƶǃǦđềǊǦđổǦǤồǃǦǋƐǄ.ǦƩếǊǦƸƚǦǈƶƾǦǈƚǉǦǤƖǦƸƽỉǦǂộǉǦǁƾ,ǦǃƽẹǦǉƽƔǦǉǇừǦǂộǉǦǉƽƑǃƼǦƷổǃƼǦǁộƸ,ǦǃặǃƼǦǉƽƔǦƩƼƽƾǦƧǄƶǃǦǥǓǦƸũǃƼǦǀƽƇǃƼǦƷảǄǦǋệǦǃổƾǦƸƑƸǦǃƼươƾǦđƁǊ.",
    ["三十四，三十五支旗……按大典惯例，还得补上些。"] = "ƝƶǦǂươƾǦǉư,ǦƷƶǦǂươƾǦǁăǂǦǁƑǦƸờ...ǦǉƽƺǄǦǆǊƑǃǦǁệǦđạƾǦđƾểǃ,ǦǋẫǃǦǅƽảƾǦƷổǦǈǊǃƼǦǉƽƙǂǦǂộǉǦƓǉ.",
    ["你真见过那白影飘？"] = "ƩƼươƾǦǉƽậǉǦǈựǦǉƽấǓǦƸƑƾǦƷƚǃƼǦǉǇắǃƼǦđƚǦƷƶǓǦǁượǃǦǈƶǄ?",
    ["骗你是孙子！就上月十五……不然你以为，为何今年要驱傩？"] = "ƧừƶǦǃƼươƾǦǁƐǂǦƸƽƑǊǦƸƽắǉǦǁǊƇǃ!ǦƨớƾǦƽƇǂǦǇằǂǦǉƽƑǃƼǦǉǇướƸǦǉƽƇƾ...ǦǃếǊǦǀƽƇǃƼǦǃƼươƾǦǉưởǃƼǦǉạƾǦǈƶǄǦǃăǂǦǃƶǓǦǁạƾǦǅƽảƾǦǉổǦƸƽứƸǦǁễǦƦƽǊǦƩƶ?",
    ["……礼乐之盛……彰显天家……啊！是你啊！"] = "...ƧễǦǃƽạƸǦǉƽịǃƽǦǉǇị...ǦƸƽươǃƼǦƽƾểǃǦǥƽƾƙǃǦƼƾƶ...ǦÁ!ǦƧƐǦǃƼươƾǦƐ!",
    ["此殿乃皇家威严象征，一梁一柱皆合礼度，同袍可有所悟？"] = "ĐƾệǃǦǃƐǓǦǁƐǦǉượǃƼǦǉǇưǃƼǦƸƽǄǦǊǓǦǃƼƽƾƙǂǦƽǄƐǃƼǦƼƾƶ,ǦǂỗƾǦǍƐǦǂỗƾǦƸộǉǦđềǊǦƽợǅǦǁễǦđộ,ǦđồǃƼǦƷƐǄǦƸƚǦƸảǂǦǃƼộǦƼƔǦǀƽƇǃƼ?",
    ["有悟有悟。不过大哥您先前，在那念叨些什么？"] = "ƞƚǦǃƼộ,ǦƸƚǦǃƼộ.ǦƩƽưǃƼǦǂƐǦđạƾǦƸƶ,ǦǋừƶǦǃƃǓǦƽǊǓǃƽǦǁảǂǦǃƽảǂǦƸƑƾǦƼƔǦởǦđƚǦǉƽế?",
    ["念叨？阁下必是听岔了。"] = "ƧảǂǦǃƽảǂ?ǦƞƑƸǦƽạǦƸƽắƸǦƸƽắǃǦǁƐǦǃƼƽƺǦǁầǂǦǇồƾ.",
    ["某值守此殿，当正言行，做表率，使往来者皆感皇家威严——唉呀算了算了，不装了！背得我腮帮子都酸了！"] = "ƨỗǦǉǇựƸǦđƾệǃǦǃƐǓ,ǦǅƽảƾǦđǄƶǃǦƸƽƓǃƽǦǃƼƇǃǦƽƐǃƽ,ǦǁƐǂǦƷƾểǊǦǈǊấǉ,ǦǀƽƾếǃǦǃƼườƾǦǆǊƶǦǁạƾǦđềǊǦƸảǂǦǃƽậǃǦđượƸǦǊǓǦǃƼƽƾƙǂǦƽǄƐǃƼǦƼƾƶǦ——ǦÁƾǦƸƽƐǦǉƽƇƾǦǉƽƇƾ,ǦǀƽƇǃƼǦǤƾễǃǦǃữƶ!ǦƣọƸǦǉƽǊộƸǦǁƛǃƼǦđếǃǦǂứƸǦǂỏƾǦǃƽừǦƸảǦǆǊƶƾǦƽƐǂǦǇồƾ!",
    ["哎呦$T(22001)你是不知道！刚才那段话，我对着家里那口大水缸足足背了五天！"] = "ÁƾǦƸƽƐǦ$T(22001)ǦǃƼươƾǦǀƽƇǃƼǦƷƾếǉǦđƁǊ!ǦĐǄạǃǦƽộƾǦǉƽǄạƾǦǋừƶǦǃƃǓ,ǦǉƶǦǅƽảƾǦđứǃƼǦǉǇướƸǦƸƑƾǦǁǊǦǃướƸǦǁớǃǦởǦǃƽƐǦƽọƸǦǉƽǊộƸǦǈǊốǉǦǃăǂǦǃƼƐǓǦǉǇờƾǦđấǓ!",
    ["什么“恢弘气度”、“礼乐之声”……这些词儿绕得呀！"] = "ƩƐǄǦǁƐǦ\"ǀƽƓǦđộǦƽǊǓǦƽǄƐǃƼ\",Ǧ\"ƁǂǦǉƽƶǃƽǦǁễǦǃƽạƸ\"...ǦǂấǓǦƸƑƾǦǉừǦǃƐǓǦǁắǉǦǁƗǄǦǆǊƑǦđƾ!",
    ["也怪我！进队时，孩儿他娘说，让我说自己“熟读礼经、仪态端正”，好求个不累的岗。"] = "ƞũǃƼǦǉạƾǦǉƶ!ǦƧƕƸǦǋƐǄǦđộƾ,ǦǂẹǦǉụƾǦǃƽỏǦƷảǄǦǉƶǦƽƃǓǦǃƚƾǦǂƔǃƽǦ\"ǉƽƇǃƼǦǉƽạǄǦǁễǦǀƾǃƽ,ǦǃƼƽƾǦǉƽƑƾǦđǄƶǃǦƸƽƓǃƽ\"ǦđểǦǍƾǃǦđượƸǦƸƑƾǦƸƽỗǦǃƽƐǃǦƽạ.",
    ["这不！就这样了！"] = "ǥƽếǦđấǓ!ǦǥƽƐǃƽǦǇƶǦǃƇǃƼǦǃỗƾǦǃƐǓǦđƁǓ!",
    ["不说了不说了，万一有人过来听着了……可不能暴露了！这活计可比那巡逻的轻松不少！"] = "ƦƽƇǃƼǦǃƚƾǦǃữƶǦǀƽƇǃƼǦǃƚƾǦǃữƶ,ǦǁỡǦƸƚǦǃƼườƾǦđƾǦǃƼƶǃƼǦǆǊƶǦǃƼƽƺǦǉƽấǓ...ǦǀƽƇǃƼǦđượƸǦƷạƾǦǁộǦđƁǊ!ǦƱƾệƸǦǃƐǓǦǈǄǦǋớƾǦđƾǦǉǊầǃǦǉǇƶǦǉƽƔǦǃƽẹǦǃƽƐǃƼǦƽơǃǦǃƽƾềǊ!",
    ["大哥可实在是……大哥挺住，我看好您。"] = "ĐạƾǦƸƶǦđƕǃƼǦǁƐǦǉƽậǉǦǈự...ǦđạƾǦƸƶǦƸốǦǁƙǃ,ǦđệǦủǃƼǦƽộǦƽǊǓǃƽ.",
    ["无事无事，我就四处看看。"] = "ƦƽƇǃƼǦƸƚǦƼƔ,ǦǀƽƇǃƼǦƸƚǦƼƔ,ǦǉƶǦƸƽỉǦđƾǦǁǄƶǃƽǦǆǊƶǃƽǦǍƺǂǦǉƽửǦǉƽƇƾ.",
    ["那请自便。"] = "ƱậǓǦǍƾǃǦƸứǦǉựǦǃƽƾƙǃ.",
    ["也不知今年年尾……能不能赶上一场像样的大雪哟……"] = "ƞũǃƼǦǀƽƇǃƼǦƷƾếǉǦƸǊốƾǦǃăǂǦǃƶǓ...ǦƸƚǦđƚǃǦđượƸǦǉǇậǃǦǉǊǓếǉǦǁớǃǦǇƶǦǉǇƛǦǃƐǄǦǀƽƇǃƼǦđƁǓ...",
    ["就这几个铜板——要不一切从简？不行不行，再想想法子……"] = "ƞƽỉǦƸƚǦǂấǓǦđồǃƼǦƷạƸǦǃƐǓǦ——ǦƽƶǓǦǁƐǦǂọƾǦǉƽứǦƸứǦđơǃǦƼƾảǃǦƽƚƶǦđƾ?ǦƦƽƇǃƼǦđượƸǦǀƽƇǃƼǦđượƸ,ǦǅƽảƾǦǃƼƽĩǦƸƑƸƽǦǀƽƑƸǦǉƽƇƾ...",
    ["还好咱提早来！瞧这榫卯不合，吃不住力啊！回头梁要是压下来……"] = "ƨƶǓǦǂƐǦƸƽƕǃƼǦǉƶǦđếǃǦǈớǂ!ǦƩƽƔǃǦǍƺǂǦǂộǃƼǦǂẹǄǦǀƽƇǃƼǦǀƽớǅǦǉƽếǦǃƐǓ,ǦǀƽƇǃƼǦƸƽịǊǦđượƸǦǁựƸǦđƁǊ!ǦƧỡǦǈƶǊǦǃƐǓǦǍƐǦǃƽƐǦđƘǦǍǊốǃƼ...",
    ["听说年前有大傩，那大仪可出不得岔子……桩桩件件都得照老规矩修整妥帖……"] = "ƩƼƽƺǦǃƚƾǦǉǇướƸǦǉếǉǦƸƚǦđạƾǦǁễǦƦƽǊǦƩƶ,ǦđạƾǦǃƼƽƾǦǉƽứƸǦđƚǦǀƽƇǃƼǦđượƸǦǅƽƗǅǦƸƚǦǈƶƾǦǈƚǉ...ǦǉừǃƼǦǂƚǃǦǉừǃƼǦǋƾệƸǦđềǊǦǅƽảƾǦǉǊǦƸƽỉǃƽǦǉƽƺǄǦǆǊǓǦƸủǦƸũǦƸƽǄǦǉƽỏƶǦđƑǃƼ...",
    ["冬至、年尾……还早着呢……"] = "ĐƇǃƼǦƸƽƓ,ǦƸǊốƾǦǃăǂ...ǦƸƛǃǦǈớǂǦƸƽƑǃ...",
    ["谁，谁！"] = "Ɯƾ,ǦƶƾǦđƚ!",
    ["爷明鉴！我我我可没偷懒！"] = "ƢƾƶǦǂƾǃƽǦƼƾƑǂ!ǦƞǄǃ...ǦƸǄǃǦǀƽƇǃƼǦƽềǦǁườƾǦƷƾếǃƼǦđƁǊ!",
    ["抱歉抱歉，无意惊扰，要不——您接着歇息？"] = "ƞƑǄǦǁỗƾǦƸƑǄǦǁỗƾ,ǦǋƇǦƈǦǆǊấǓǦǇầǓ,ǦƽƶǓǦǁƐǦ——ǦǃƼƐƾǦƸứǦǉƾếǅǦǉụƸǦǃƼƽỉǦǃƼơƾǦđƾ?",
    ["哎？原是武德司的大人，您怎有空得闲，上这转悠？"] = "Ơ?ǦƣƚƶǦǇƶǦǁƐǦđạƾǦǃƽƁǃǦƸủƶǦƱƅǦĐứƸǦǥǓ,ǦǈƶǄǦǃƼƐƾǦǁạƾǦƸƚǦǉƽờƾǦƼƾƶǃǦǇảǃƽǦǇỗƾǦƼƽƗǦǆǊƶǦđƁǓǦǤạǄǦƸƽơƾǦǋậǓ?",
    ["没事没事，懂，我都懂！"] = "ƦƽƇǃƼǦǈƶǄǦǀƽƇǃƼǦǈƶǄ,ǦƽƾểǊǦǂƐ,ǦǉƶǦđềǊǦƽƾểǊǦƸả!",
    ["你不说，我也不说，这清闲日子，咱就时时能过得！是不是！"] = "ƩƼươƾǦǀƽƇǃƼǦǃƚƾ,ǦǉƶǦƸũǃƼǦǀƽƇǃƼǦǃƚƾ,ǦǃƼƐǓǦǉƽƑǃƼǦǉƽƶǃƽǦǃƽƐǃǦǃƐǓǦƸƽƕǃƼǦǉƶǦǁƕƸǦǃƐǄǦƸƽẳǃƼǦǉậǃǦƽưởǃƼǦđượƸ!ǦƫƽảƾǦǀƽƇǃƼǦǃƐǄ!",
    ["正是！正是！你且歇着，我再上别处歪一歪。"] = "ƞƽƓǃƽǦǍƑƸ!ǦƞƽƓǃƽǦǍƑƸ!ǦƩƼươƾǦƸứǦǃƼƽỉǦđƾ,ǦǉƶǦǁạƾǦǈƶǃƼǦƸƽỗǦǀƽƑƸǦǃằǂǦǃƼƽƾƙǃƼǦǂộǉǦǁƑǉ.",
    ["左边……不对，右边，再往右一些……不对，感觉还是不对。"] = "ƝƙǃǦǉǇƑƾ...ǦǀƽƇǃƼǦđƕǃƼ,ǦƷƙǃǦǅƽảƾ,ǦǈƶǃƼǦǅƽảƾǦǉƽƙǂǦƸƽƕǉǦǃữƶ...ǦǀƽƇǃƼǦđƕǃƼ,ǦƸảǂǦƼƾƑƸǦǋẫǃǦƸƽưƶǦổǃ.",
    ["哎呀！要不你来！"] = "ÁƾǦƸƽƐ!ǦƣƶǓǦǁƐǦǃƼươƾǦǁƐǂǦđƾ!",
    ["怎叫个不停……这崇元殿，真有鬼？"] = "ƮƶǄǦƸứǦǀƙǊǦǂƃƾǦǀƽƇǃƼǦǃƼừǃƼǦǉƽế...ǦƮƖǃƼǦƩƼǊǓƙǃǦĐƾệǃǦǃƐǓ,ǦƸƚǦǂƶǦǉƽậǉǦǈƶǄ?",
    ["小崽子，老实点！小心爷没收了你的大骨头！"] = "ƞƑƾǦǉƽứǦǇƶǃƽǦƸǄǃ,ǦǉƽƐǃƽǦǉƽậǉǦƸƽƕǉǦđƾ!ǦƞẩǃǦǉƽậǃǦƼƾƶǦǉịƸƽǦǉƽǊǦǁǊƇǃǦƸƑƾǦǍươǃƼǦǁớǃǦƸủƶǦǃƼươƾǦƼƾờ!",
    ["咳咳，这位，面生得很，新来宫里的？莫不是找不着北了？"] = "ƦƽụǦǀƽụ,ǦǋịǦǃƐǓǦǃƽƔǃǦǂặǉǦǁạǦǆǊƑ,ǦǂớƾǦǋƐǄǦƸǊǃƼǦƐ?ǦƞƽẳǃƼǦǁẽǦǁƐǦǁạƸǦđườǃƼǦǇồƾǦǈƶǄ?",
    ["正是。这崇元殿，委实大了些。"] = "ƞƽƓǃƽǦǍƑƸ.ǦƮƖǃƼǦƩƼǊǓƙǃǦĐƾệǃǦǃƐǓǦǆǊảǦǉƽựƸǦƸƚǦƽơƾǦǆǊƑǦǁớǃ.",
    ["嗐，刚来都这样！"] = "ƣạƾ,ǦǂớƾǦđếǃǦđềǊǦǉƽếǦƸả!",
    ["就是这帮认路一流的狗崽子，刚来也认不得道。"] = "ĐếǃǦƸảǦǁũǦƸƽƚǦƸǄǃǦǤẫǃǦđườǃƼǦƽạǃƼǦǃƽấǉǦǃƐǓ,ǦǂớƾǦđếǃǦƸũǃƼǦƸƽẳǃƼǦƷƾếǉǦđườǃƼǦǃƐǄǦǂƐǦǁầǃ.",
    ["对了，它们若哪儿冲撞了，千万多担待。"] = "ĐƕǃƼǦǇồƾ,ǦǃếǊǦƸƽƕǃƼǦǃƚǦƸƚǦǂạǄǦǅƽạǂǦƸƽỗǦǃƐǄ,ǦǂǄǃƼǦǃƼƐƾǦǁượǃƼǦǉƽứǦƸƽǄ.",
    ["大人客气了。"] = "ĐạƾǦǃƽƁǃǦǀƽƑƸƽǦǀƽƓǦǇồƾ.",
    ["东边那档子事儿……你可听闻了？里头真藏了先帝的珠宝匣子？"] = "ƞƽǊǓệǃǦǅƽƓƶǦđƇǃƼǦđƚ...ǦǃƼươƾǦƸƚǦǃƼƽƺǦǅƽǄǃƼǦǉƽƶǃƽǦƼƔǦƸƽưƶ?ǦƝƙǃǦǉǇǄǃƼǦǉƽựƸǦǈựǦƼƾấǊǦǉǇƑǅǦƸƽƁǊǦƷƑǊǦƸủƶǦǉƾƙǃǦđếǦǈƶǄ?",
    ["再有几个时辰……今儿这差事就算混过去喽……"] = "ƞƛǃǦǂấǓǦƸƶǃƽǦƼƾờǦǃữƶǦǉƽƇƾ...ǦǋƾệƸǦƽƇǂǦǃƶǓǦƸǄƾǦǃƽưǦǍǄǃƼǦǍǊƇƾǦǇồƾ...",
    ["咳咳，这位有什么要事？挡着那日头了！"] = "ƦƽụǦǀƽụ,ǦǋịǦǃƐǓǦƸƚǦǋƾệƸǦƼƔǦǉǇọǃƼǦđạƾǦǈƶǄ?ǦƩƼươƾǦƸƽƺǦǂấǉǦƑǃƽǦǂặǉǦǉǇờƾǦƸủƶǦǉƶǦǇồƾ!",
    ["抱歉抱歉，没留意。"] = "ƞƑǄǦǁỗƾǦƸƑǄǦǁỗƾ,ǦǀƽƇǃƼǦđểǦƈ.",
    ["不打紧不打紧——不过，这崇元殿内外的几张脸，我阿吉可都是门儿清。你面生得很嘛，打别处来的？"] = "ƦƽƇǃƼǦǈƶǄǦǀƽƇǃƼǦǈƶǄǦ——ǦƸơǦǂƐ,ǦǂấǓǦƼươǃƼǦǂặǉǦǉǇǄǃƼǦǃƼǄƐƾǦƮƖǃƼǦƩƼǊǓƙǃǦĐƾệǃǦǃƐǓ,ǦƜǦƞƑǉǦǉƶǦđƁǓǦđềǊǦǃƽẵǃǦǂặǉǦƸả.ǦƩƼươƾǦǃƽƔǃǦǁạǦƽǄắƸǦƐ,ǦǉừǦǃơƾǦǀƽƑƸǦǉớƾǦǈƶǄ?",
    ["莫非……是隔壁溜过来的？那头，这几日正紧着守库呐，你怎得了空上我们这溜达？"] = "ƞƽẳǃƼǦǁẽ...ǦǁƐǦǉừǦƷƙǃǦƸạǃƽǦǁƗǃǦǈƶǃƼǦđƁǓ?ǦƝƙǃǦđƚǦǂấǓǦǃƼƐǓǦǃƶǓǦđƶǃƼǦƸƶǃƽǦƼƾữǦǀƽǄǦƼắǉǦƼƶǄǦǁắǂ,ǦǈƶǄǦǃƼươƾǦǁạƾǦǇảǃƽǦǇỗƾǦǈƶǃƼǦđƁǓǦǤạǄǦǂƑǉ?",
    ["守库？守什么库？"] = "ƞƶǃƽǦǀƽǄ?ǦƞƶǃƽǦǀƽǄǦƼƔǦƸƽứ?",
    ["嗯？您也不是那边的……那你是哪头的？"] = "ƣử?ǦƩƼƐƾǦƸũǃƼǦǀƽƇǃƼǦǅƽảƾǦǃƼườƾǦƷƙǃǦđƚ...ǦǋậǓǦǃƼƐƾǦǉƽǊộƸǦƷƙǃǦǃƐǄ?",
    ["我是哪头的另说，您先说说，这库是怎么回事？"] = "ǥƶǦǉƽǊộƸǦƷƙǃǦǃƐǄǦǃƚƾǦǈƶǊ,ǦǃƼƐƾǦǃƚƾǦǉǇướƸǦǍƺǂ,ǦƸƑƾǦǀƽǄǦđƚǦǁƐǦǉƽếǦǃƐǄ?",
    ["嘿！那你可问对人了！这宫里头大大小小的事儿，就没有我阿吉不清楚的！"] = "ƣƙ!ǦǥƽếǦǉƽƔǦǃƼƐƾǦƽỏƾǦđƕǃƼǦǃƼườƾǦǇồƾ!ǦƞƽǊǓệǃǦǁớǃǦƸƽǊǓệǃǦǃƽỏǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓ,ǦǀƽƇǃƼǦƸƚǦƼƔǦǂƐǦƜǦƞƑǉǦǉƶǦǀƽƇǃƼǦƷƾếǉ!",
    ["就隔壁那地方啊，听说立了一仓库，里头藏的都是绝世珍宝！"] = "ƞƽƓǃƽǦǁƐǦƸƽỗǦƷƙǃǦƸạǃƽǦđƚ,ǦǃƼƽƺǦǃƚƾǦǤựǃƼǦǂộǉǦƸƑƾǦǀƽǄ,ǦƷƙǃǦǉǇǄǃƼǦƼƾấǊǦǉǄƐǃǦǉǇƁǃǦƷảǄǦǉǊǓệǉǦǉƽế!",
    ["这可好，引得江湖上那些个 phi檐 tẩu bích đích nhân nhi，都想来见识见识！"] = "ǥƽếǦǁƐǦƽƶǓǦǇồƾ,ǦǉƽǊǦƽƕǉǦđƑǂǦǃƼườƾǦǉƽƁǃǦǅƽƑǅǦǉậǉǦƽƐǃƽǦǉǇƙǃǦƼƾƶǃƼǦƽồ,ǦƶƾǦƸũǃƼǦǂǊốǃǦđếǃǦǂởǦǂƶǃƼǦǉầǂǦǂắǉ!",
    ["再多的，可说不得了！再说下去，我这晒自个儿的正经差事，可就要耽搁了。"] = "ƩƽƾềǊǦƽơǃǦǃữƶǦǉƽƔǦǀƽƇǃƼǦǃƚƾǦđượƸǦđƁǊ!ǦƩƚƾǦǃữƶǦǁƐǦǋƾệƸǦƸƽƓǃƽǦǈựǦǈưởƾǦǃắǃƼǦƸủƶǦǉƶǦƷịǦǉǇƔǦƽǄƃǃǦǂấǉ.",
    ["您要想打听——这殿内外，不少人知情呐。"] = "ƩƼƐƾǦǂǊốǃǦǃƼƽƺǦǃƼƚǃƼǦ——ǦǉǇǄǃƼǦǃƼǄƐƾǦđƾệǃǦǃƐǓ,ǦǀƽốƾǦǃƼườƾǦƷƾếǉǦƸƽǊǓệǃǦđấǓ.",
    ["您请便，请便哈。"] = "ƩƼƐƾǦƸứǦǉựǦǃƽƾƙǃ,ǦǉựǦǃƽƾƙǃǦđƾǦǃƽƶ.",
    ["瞧瞧隔壁队的精神劲儿！再瞧瞧你们的！"] = "ƩƽƔǃǦǉƾǃƽǦǉƽầǃǦƸủƶǦđộƾǦƷƙǃǦƸạǃƽǦǀƔƶ!ǦƭồƾǦǃƽƔǃǦǁạƾǦƸƑƸǦǃƼươƾǦǍƺǂ!",
    ["隔壁也有弟兄偷懒呢……我都瞧见了……"] = "ƝƙǃǦƸạǃƽǦƸũǃƼǦƸƚǦƽǊǓǃƽǦđệǦǁườƾǦƷƾếǃƼǦǂƐ...ǦǉƶǦǉƽấǓǦƽếǉǦǇồƾ...",
    ["这声响敲着奇怪……怕不是鲁班爷嫌香火薄，暗中别着股劲儿？"] = "ǥƾếǃƼǦđộǃƼǦǃƐǓǦǃƼƽƺǦǁạǦǉƽậǉ...ǦƸƽẳǃƼǦǁẽǦƧỗǦƝƶǃǦƼƾƶǦƸƽƙǦƽươǃƼǦƽỏƶǦƓǉ,ǦǃƙǃǦƁǂǦǉƽầǂǦƼƁǓǦƽấǃǦǈƶǄ?",
    ["咦大人，是迷路了吗？"] = "ƠǦđạƾǦǃƽƁǃ,ǦǃƼƐƾǦǁạƸǦđườǃƼǦǈƶǄ?",
    ["随便转转。你倒是个快活人，扫个地还哼小曲儿。"] = "ǝạǄǦǆǊƶǃƽǦƸƽƕǉǦǉƽƇƾ.ǦƩƼươƾǦđƕǃƼǦǁƐǦǃƼườƾǦǋǊƾǦǋẻ,ǦǆǊƗǉǦǇƑƸǦǂƐǦƸũǃƼǦǃƼƁǂǦǃƼƶǦǉƾểǊǦǀƽƕƸ.",
    ["嘻嘻，日子总得过嘛！扫干净了，心里也敞亮！"] = "ƣƾǦƽƾ,ǦǃƼƐǓǦǉƽƑǃƼǦǋẫǃǦǅƽảƾǦǈốǃƼǦǉƾếǅǦǂƐ!ǦƬǊƗǉǦǈạƸƽǦǈẽǦǇồƾ,ǦǁƛǃƼǦƸũǃƼǦǉƽấǓǦǃƽẹǦǃƽƐǃƼ!",
    ["这自在劲儿 —— 你是新入宫的？"] = "ƞƑƾǦǋẻǦǉựǦǉạƾǦǃƐǓǦ——ǦǃƼươƾǦǂớƾǦǋƐǄǦƸǊǃƼǦǈƶǄ?",
    ["别看小的年纪小，小的可是宫里的老人了！"] = "ĐừǃƼǦǉƽấǓǦǉƾểǊǦǃƽƁǃǦǉǊổƾǦǃƽỏ,ǦǉƾểǊǦǃƽƁǃǦǁƐǦǃƼườƾǦƸũǦǉǇǄǃƼǦƸǊǃƼǦǇồƾǦđấǓ!",
    ["早年小的跟着家人逃难，来了皇城脚下，而后就进了宫。"] = "ƩăǂǦǍưƶǦǉƾểǊǦǃƽƁǃǦǉƽƺǄǦƼƾƶǦđƔǃƽǦƸƽạǓǦǃạǃ,ǦđếǃǦƸƽƁǃǦǉƽƐǃƽǦƽǄƐǃƼǦđƇ,ǦǈƶǊǦđƚǦǉƽƔǦǋƐǄǦƸǊǃƼ.",
    ["那会儿，皇帝老爷还不是这一个呐！"] = "ƣồƾǦđƚ,ǦƽǄƐǃƼǦđếǦǁƃǄǦƼƾƶǦǋẫǃǦƸƽưƶǦǅƽảƾǦǋịǦǃƐǓǦđƁǊ!",
    ["这么说，周朝时，你就在这宫内？"] = "ƩƚƾǦǋậǓ,ǦǉƽờƾǦƞƽǊǦǉǇƾềǊ,ǦǃƼươƾǦđƃǦởǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦǇồƾ?",
    ["那是！不过小的不管那些，能挡雨的屋檐，就是好屋檐嘛！"] = "ƞƽứǦǁạƾǦǀƽƇǃƼ!ǦƩƽưǃƼǦǉƾểǊǦǃƽƁǃǦƸƽẳǃƼǦǆǊảǃǦǂấǓǦǉƽứǦđƚ,ǦǂƑƾǦƽƾƙǃǦǃƐǄǦƸƽƺǦđượƸǦǂưƶǦǉƽƔǦǁƐǦǂƑƾǦƽƾƙǃǦǉốǉǦǉƽƇƾ!",
    ["嘶，小昌子没有胡说……这里头确实凉飕飕的……"] = "ƮƔ,ǦǥƾểǊǦƳươǃƼǦǥửǦǀƽƇǃƼǦǃƚƾǦđƾƙǊ...ǦƷƙǃǦǉǇǄǃƼǦǃƐǓǦđƕǃƼǦǁƐǦǁạǃƽǦǁẽǄǦǉƽậǉ...",
    ["大傩时，陛下真会在这歇息？"] = "ƧƕƸǦǁễǦƦƽǊǦƩƶ,ǦƷệǦƽạǦǉƽựƸǦǈựǦǈẽǦǃƼƽỉǦǃƼơƾǦởǦđƁǓǦǈƶǄ?",
    ["陛下의东西，可得收拾稳妥些……"] = "ĐồǦđạƸǦƸủƶǦƷệǦƽạ,ǦǅƽảƾǦǤọǃǦǤẹǅǦƸƽǄǦổǃǦǉƽỏƶ...",
    ["大人请当心脚下！这儿的东西可都金贵得很，万万磕碰不起。"] = "ĐạƾǦǃƽƁǃǦǍƾǃǦƸẩǃǦǉƽậǃǦǤướƾǦƸƽƁǃ!ǦĐồǦđạƸǦởǦđƁǓǦđềǊǦƸựƸǦǀỳǦǆǊƈǦƼƾƑ,ǦǃƼƽƔǃǦǋạǃǦǁầǃǦǀƽƇǃƼǦđượƸǦǋƶǦƸƽạǂǦǋƐǄ.",
    ["都是为陛下大典预备의。稍有差池，咱们谁都吃罪不起。"] = "ĐềǊǦƸƽǊẩǃǦƷịǦƸƽǄǦđạƾǦđƾểǃǦƸủƶǦƷệǦƽạǦƸả.ǦƞƽệƸƽǦǂộǉǦǁƾǦǉƽƇƾǦǁƐǦƶƾǦǉǇǄǃƼǦƸƽƕǃƼǦǉƶǦƸũǃƼǦǀƽƇǃƼǦƼƑǃƽǦǃổƾǦǉộƾǦđƁǊ.",
    ["还请大人见谅。"] = "ƨǄǃƼǦđạƾǦǃƽƁǃǦǁượǃƼǦǉƽứ.",
    ["你怎么还杵在这儿躲清闲？寝殿里头都收拾妥了？角角落落都摸过一遍了？"] = "ƮƶǄǦǃƼươƾǦƸƛǃǦđứǃƼǦđựƸǦởǦđƁǓǦǂƐǦƽưởǃƼǦǃƽƐǃǦǉƽế?ǦǥẩǂǦđƾệǃǦđƃǦǤọǃǦǤẹǅǦǍǄǃƼǦƸƽưƶ?ǦƨọƾǦǃƼƚƸǦǃƼƑƸƽǦđƃǦǁƶǊǦƸƽƖƾǦǆǊƶǦǂộǉǦǁượǉǦƸƽưƶ?",
    ["哎呀，催什么嘛。大典还有几个月呐！况且那点子差事，又不会自个儿长腿跑了。明儿！我定把里里外外都收拾得纤尘不染！"] = "ÁƾǦƸƽƐ,ǦƼƾụƸǦƸƑƾǦƼƔǦƸƽứ.ǦĐạƾǦđƾểǃǦƸƛǃǦǂấǓǦǉƽƑǃƼǦǃữƶǦǂƐ!ǦƣơǃǦǃữƶǦǤăǂǦƷƶǦƸƑƾǦǋƾệƸǦđƚǦƸƚǦǉựǦǂọƸǦƸƽƁǃǦƸƽạǓǦǂấǉǦđƁǊ.Ǧƨƶƾ!ǦƩƽấǉǦđịǃƽǦǉƶǦǈẽǦǤọǃǦǤẹǅǦǉừǦǉǇǄǃƼǦǇƶǦǃƼǄƐƾǦǈạƸƽǦƷǄǃƼǦǀƽƇǃƼǦǂộǉǦƽạǉǦƷụƾ!",
    ["秋风一起，这地上的落叶，扫完一茬又落一茬……怎扫不尽呐。"] = "ƢƾƚǦǉƽǊǦǋừƶǦǉƽổƾ,ǦǁƑǦǇụǃƼǦǉǇƙǃǦđấǉǦǆǊƗǉǦƽếǉǦǁớǅǦǃƐǓǦǁạƾǦǇụǃƼǦǁớǅǦǀƽƑƸ...ǦǈƶǄǦǂƐǦǆǊƗǉǦǀƽƇǃƼǦǍǊểǦǉƽếǦǃƐǓ.",
    ["可不是！好在除了年关大典，平日咱也没什么别的活计。"] = "ƞƽứǦƸƛǃǦƼƔǦǃữƶ!ǦƨƶǓǦǂƐǦǉǇừǦđạƾǦđƾểǃǦƸǊốƾǦǃăǂ,ǦǃƼƐǓǦǉƽườǃƼǦƸƽƕǃƼǦǉƶǦƸũǃƼǦƸƽẳǃƼǦƸƚǦǋƾệƸǦƼƔǦǀƽƑƸ.",
    ["嘘 —— 也有人说，那是钓贼的饵！"] = "ƮǊỵǉǦ——ǦƸũǃƼǦƸƚǦǃƼườƾǦǃƚƾ,ǦđƚǦǁƐǦǂồƾǦǃƽửǦǉǇộǂǦđấǓ!",
    ["你得记着那些被取用의折子书册的样子，还有它们被收起来之前与之后的位置。免得之后官家问起来，你只能跟个木头似的杵着。"] = "ƩƼươƾǦǅƽảƾǦǃƽớǦǀỹǦƽƔǃƽǦǤƑǃƼǦƸủƶǦǃƽữǃƼǦǈớǦǉấǊǦǈƑƸƽǦǋởǦđượƸǦǁấǓǦǤƖǃƼ,ǦƸũǃƼǦǃƽưǦǋịǦǉǇƓǦƸủƶǦƸƽƕǃƼǦǉǇướƸǦǋƐǦǈƶǊǦǀƽƾǦđượƸǦƸấǉǦđƾ.ǦĐểǦǈƶǊǦǃƐǓǦƬǊƶǃǦƼƾƶǦƸƚǦƽỏƾǦđếǃ,ǦǃƼươƾǦǀƽƇǃƼǦǅƽảƾǦđứǃƼǦđựƸǦǇƶǦǃƽưǦǀƽƕƸǦƼỗ.",
    ["多谢常侍提点，我这便一一记下！"] = "ĐƶǦǉạǦǥƽườǃƼǦǉƽịǦƸƽỉǦđƾểǂ,ǦǉƶǦǈẽǦƼƽƾǦǃƽớǦǉừǃƼǦƸƑƾǦǂộǉ!",
    ["不过你也不必太紧张。就算是你到时真的什么都想不起，只要机灵些，说句东西收在里头了得翻翻，官家也不会怪罪的。"] = "ƩƽưǃƼǦǃƼươƾǦƸũǃƼǦđừǃƼǦǆǊƑǦƸăǃƼǦǉƽẳǃƼ.ǦƩƼƶǓǦƸảǦǀƽƾǦǁƕƸǦđƚǦǃƼươƾǦǉƽựƸǦǈựǦǀƽƇǃƼǦǃƽớǦǇƶǦƼƔ,ǦƸƽỉǦƸầǃǦǁƶǃƽǦǁợƾǦǂộǉǦƸƽƕǉ,ǦƷảǄǦǁƐǦđồǦƸấǉǦƷƙǃǦǉǇǄǃƼǦǇồƾǦƸầǃǦǉƔǂǦǁạƾ,ǦƬǊƶǃǦƼƾƶǦƸũǃƼǦǈẽǦǀƽƇǃƼǦǉǇƑƸƽǦǉộƾǦđƁǊ.",
    ["这般好의主意，若是没有常侍提点，我定是想不出的！"] = "ÝǦƽƶǓǦǃƽưǦǋậǓ,ǦǃếǊǦǀƽƇǃƼǦƸƚǦǥƽườǃƼǦǉƽịǦƸƽỉǦđƾểǂ,ǦǉƶǦƸƽắƸǦƸƽắǃǦǀƽƇǃƼǦǃƼƽĩǦǇƶǦđượƸ!",
    ["你这般嘴甜，之后在这宫里，定是不难待下去的。"] = "ƨồǂǦǂƗǅǦǃƼọǉǦǍớǉǦǉƽếǦǃƐǓ,ǦǈƶǊǦǃƐǓǦởǦǉǇǄǃƼǦƸǊǃƼǦƸƽắƸǦƸƽắǃǦǀƽƇǃƼǦǀƽƚǦđểǦǈốǃƼǦǉốǉǦđƁǊ.",
    ["小大人这等绝世轻功，飞檐走壁如闲庭信步，实在是天纵奇才。"] = "ǥƾểǊǦđạƾǦǃƽƁǃǦǋớƾǦǉǊǓệǉǦǉƽếǦǀƽƾǃƽǦƸƇǃƼǦǃƽưǦǉƽếǦǃƐǓ,ǦǉƽƁǃǦǅƽƑǅǦǉậǉǦƽƐǃƽǦǃƽưǦǤạǄǦƸƽơƾǦǉǇǄǃƼǦǈƁǃǦǋắǃƼ,ǦǆǊảǦǉƽựƸǦǁƐǦǉƽƾƙǃǦǉƕǃƼǦǀỳǦǉƐƾ.",
    ["范相公如此、啾！当初、啾！明朝有意抱琴来、啾！"] = "ƫƽạǂǦǉướǃƼǦƸƇǃƼǦǃƽưǦǉƽế,ǦƸƽƓǅ!ǦǥƽǊởǦđƚ,ǦƸƽƓǅ!ǦƮƑǃƼǦǂƶƾǦƸƚǦƈǦƇǂǦđƐǃǦǉớƾ,ǦƸƽƓǅ!",
    ["这好像是上次吵的，上回也听到过这句。"] = "ĐƁǓǦǤườǃƼǦǃƽưǦǁƐǦƸƽǊǓệǃǦƸƃƾǦǃƽƶǊǦǁầǃǦǉǇướƸ,ǦǁầǃǦǉǇướƸǦƸũǃƼǦǉừǃƼǦǃƼƽƺǦǆǊƶǦƸƁǊǦǃƐǓǦǇồƾ.",
    ["每次吵的也都差不多，相公们吵起架也会词穷啊。"] = "ƧầǃǦǃƐǄǦƸƃƾǦƸũǃƼǦǃƶǦǃƑǦǃƽƶǊǦǉƽƇƾ,ǦƸƑƸǦǉướǃƼǦƸƇǃƼǦƸƃƾǦǃƽƶǊǦƸũǃƼǦđếǃǦǁƕƸǦƷƓǦǉừǦǂƐ.",
    ["不怕天下英雄、啾！"] = "ƞƽẳǃƼǦǈợǦƶǃƽǦƽƖǃƼǦǉƽƾƙǃǦƽạ,ǦƸƽƓǅ!",
    ["这句这句，这句是新的！"] = "ƞƁǊǦǃƐǓǦƸƁǊǦǃƐǓ,ǦƸƁǊǦǃƐǓǦǁƐǦǂớƾǦǃƘ!",
    ["聚在这里干什么呢？"] = "ǥụǦǉậǅǦởǦđƁǓǦǁƐǂǦƼƔǦǉƽế?",
    ["嘘……别大声，相公们刚吵完，风声紧着呢。我们呀，来借鹦鹉听听口风。"] = "ƮǊỵǉ...ǦđừǃƼǦǉǄǦǉƾếǃƼ,ǦƸƑƸǦǉướǃƼǦƸƇǃƼǦǋừƶǦƸƃƾǦǍǄǃƼ,ǦǉƔǃƽǦƽƔǃƽǦđƶǃƼǦƸăǃƼǦǁắǂ.ǦƞƽƕǃƼǦǉƶǦấǓǦƐ,ǦđếǃǦǂượǃǦƸǄǃǦǋẹǉǦǃƐǓǦđểǦǃƼƽƺǦǃƼƚǃƼǦƸƽƕǉǦǉƾǃǦǉứƸ.",
    ["大胆、啾！各司要守好自己的职责、啾！"] = "ƢươǃƼǦƼƶǃ,ǦƸƽƓǅ!ǦƞƑƸǦǉǓǦǅƽảƾǦƼƾữǦǋữǃƼǦƸƽứƸǦǉǇƑƸƽǦƸủƶǦǂƔǃƽ,ǦƸƽƓǅ!",
    ["嘿！这都堂门前的鹦鹉，也耍起官威来了！"] = "ƣƙ!ǦƞǄǃǦǋẹǉǦǉǇướƸǦƸửƶǦđƇǦđườǃƼǦǃƐǓǦƸũǃƼǦƷƐǓǦđặǉǦƼƾởǦǉƽƚƾǦǆǊƶǃǦǊǓǦǇƶǦǇồƾ!",
    ["且住手！你可知我是何人？岂容你如此放肆！"] = "ƣƃǓǦǤừǃƼǦǉƶǓ!ǦƩƼươƾǦƸƚǦƷƾếǉǦǉƶǦǁƐǦƶƾǦǀƽƇǃƼ?ǦƮƶǄǦƸƚǦǉƽểǦđểǦǃƼươƾǦǅƽƚǃƼǦǉƕǃƼǦǃƽưǦǉƽế!",
    ["刚才走过去那个，崇文院的，你看到没有？哎哟……眼睛底下能蘸墨了！"] = "ƞƑƾǦǃƼườƾǦǋừƶǦđƾǦǃƼƶǃƼǦǆǊƶǦđƚ,ǦƷƙǃǦƮƖǃƼǦƱăǃǦƱƾệǃǦđấǓ,ǦǃƼươƾǦǉƽấǓǦǀƽƇǃƼ?ǦÁƾǦƸƽƐ...ǦǆǊầǃƼǦǉƽƁǂǦǤướƾǦǂắǉǦđƺǃǦǃƽưǦƸƽấǂǦǂựƸǦđượƸǦǇồƾǦǀƔƶ!",
    ["幸好没被抓去三馆。啧啧啧，连轴转地熬，这哪是人能过的日子哟。"] = "ƨƶǓǦǂƐǦǀƽƇǃƼǦƷịǦƷắǉǦǈƶǃƼǦǥƶǂǦƬǊƑǃ.ǦƞƽậƸǦƸƽậƸǦƸƽậƸ,ǦǉƽứƸǦđƙǂǦǁƐǂǦǋƾệƸǦǆǊầǃǦǆǊậǉǦǉƽếǦǀƾƶ,ǦđƁǊǦǅƽảƾǦǁƐǦǃƼƐǓǦǉƽƑǃƼǦƸƽǄǦǃƼườƾǦǈốǃƼǦƸƽứ.",
    ["聊什么呢？方才我像是听见——"] = "ƩƚƾǦƸƽǊǓệǃǦƼƔǦǉƽế?ǦƱừƶǦǇồƾǦǉƶǦƽƔǃƽǦǃƽưǦǃƼƽƺǦǉƽấǓǦ——",
    ["你是武德司的，还能不知道？殿前司的现在看你们可不顺眼呢！"] = "ƩƼươƾǦǁƐǦǃƼườƾǦƸủƶǦƱƅǦĐứƸǦǥǓǦǂƐǦƸƛǃǦǀƽƇǃƼǦƷƾếǉǦǈƶǄ?ǦĐƑǂǦĐƾệǃǦǥƾềǃǦǥǓǦƷƁǓǦƼƾờǦǃƽƔǃǦƸƑƸǦǃƼươƾǦǃƼứƶǦǂắǉǦǁắǂǦđấǓ!",
    ["装傻了不是？嘿，熙熙攘攘，无非名利来往。"] = "ƢƾảǦǃƼốƸǦǇồƾǦǅƽảƾǦǀƽƇǃƼ?Ǧƣƙ,ǦƽǊǓƙǃǦƽǊǓƙǃǦǃƑǄǦǃƑǄ,ǦƸƽẳǃƼǦǆǊƶǦƸũǃƼǦƸƽỉǦǋƔǦǤƶǃƽǦǁợƾǦǂƐǦđếǃǦǂƐǦđƾǦǉƽƇƾ.",
    ["你们还在这编排上宰相了？"] = "ƞƑƸǦǃƼươƾǦƸƛǃǦởǦđƁǓǦđặǉǦđƾềǊǦǋềǦǉểǦǉướǃƼǦǃữƶǦƐ?",
    ["相公们站得高，看得见他们的人多，评语自然就多。这有什么。"] = "ƞƑƸǦǉướǃƼǦƸƇǃƼǦđứǃƼǦởǦǋịǦǉǇƓǦƸƶǄ,ǦǃƼườƾǦǃƽƔǃǦǉƽấǓǦƽọǦǃƽƾềǊǦǉƽƔǦǁờƾǦƷƔǃƽǦǅƽẩǂǦǉựǦǃƽƾƙǃǦǈẽǦǃƽƾềǊ.ǦƞƚǦƼƔǦđƁǊ.",
    ["就是，事不怕人说，这不是显得咱们相公光明磊落么！"] = "ĐƕǃƼǦǉƽế,ǦǋƾệƸǦƸƽẳǃƼǦǈợǦǃƼườƾǦǉƶǦǃƚƾ,ǦǉƽếǦǃƐǓǦƸƽẳǃƼǦǅƽảƾǦƸƽǄǦǉƽấǓǦǉướǃƼǦƸƇǃƼǦǃƽƐǦǉƶǦǆǊƶǃƼǦǂƾǃƽǦǁỗƾǦǁạƸǦǈƶǄ!",
    ["听说是在编什么……刑统？相公们定的时间太紧！"] = "ƩƼƽƺǦǃƚƾǦđƶǃƼǦƷƾƙǃǦǈǄạǃǦƸƑƾǦƼƔ...ǦƣƔǃƽǦǥƽốǃƼ?ǦƞƑƸǦǉướǃƼǦƸƇǃƼǦđịǃƽǦǉƽờƾǦƼƾƶǃǦƼấǅǦǆǊƑ!",
    ["武德司的来了，想问就直接问我。有什么事？"] = "ƩƼườƾǦƸủƶǦƱƅǦĐứƸǦǥǓǦđếǃǦǇồƾ,ǦǂǊốǃǦƽỏƾǦƼƔǦƸứǦǉǇựƸǦǉƾếǅǦƽỏƾǦǉƶ.ǦƞƚǦǋƾệƸǦƼƔ?",
    ["咳……军士，让你听见了……在下就是想问，武德司戍卫皇城，你四处巡逻之时，有没有听说……上头是怎么看待咱们这些人？"] = "Ʀƽụ...ǦǆǊƁǃǦǈĩ,ǦđểǦǃƼươƾǦǃƼƽƺǦǉƽấǓǦǇồƾ...ǦǉạƾǦƽạǦƸƽỉǦǁƐǦǂǊốǃǦƽỏƾ,ǦƱƅǦĐứƸǦǥǓǦǉǇấǃǦǉƽủǦƽǄƐǃƼǦǉƽƐǃƽ,ǦǁƕƸǦǃƼươƾǦǉǊầǃǦǉǇƶǦǀƽắǅǦǃơƾ,ǦƸƚǦǃƼƽƺǦǃƚƾ...ǦƷƙǃǦǉǇƙǃǦǃƽƔǃǦǃƽậǃǦǃƽữǃƼǦǃƼườƾǦǃƽưǦƸƽƕǃƼǦǉƶǦǉƽếǦǃƐǄǦǀƽƇǃƼ?",
    ["你们这些人？什么人？"] = "ƩƽữǃƼǦǃƼườƾǦǃƽưǦƸƑƸǦǃƼươƾ?ǦƧƐǦƽạǃƼǦǃƼườƾǦƼƔ?",
    ["就是……就是……哎！这哪能明说，就是隔夜的饭，去岁的桃符，放酸了的雪水么！"] = "ǥƽƔǦǁƐ...ǦǉƽƔǦǁƐ...ǦƑƾǦƸƽƐ!ǦƞƽǊǓệǃǦǃƐǓǦǈƶǄǦǃƚƾǦƽǊỵƸƽǦǉẹǉǦǇƶǦđượƸ,ǦƸƽẳǃƼǦǆǊƶǦƸũǃƼǦǃƽưǦƷƑǉǦƸơǂǦǃƼǊộƾǦǆǊƶǦđƙǂ,ǦǉấǂǦƷƖƶǦđƐǄǦǃăǂǦǃƼǄƑƾ,ǦƽƶǓǦƼƑǄǦǃướƸǦǉǊǓếǉǦđƃǦƽƚƶǦƸƽǊƶǦǉƽƇƾǦǂƐ!",
    ["总而言之，言而总之，军士你身份方便，劳你帮帮忙，去都堂那儿听听消息——什么消息都行！"] = "ƩƚƾǦǉƚǂǦǁạƾ,ǦƸƽốǉǦǁạƾǦǁƐ,ǦǆǊƁǃǦǈĩǦǃƼươƾǦƸƚǦǉƽƁǃǦǅƽậǃǦǉƽǊậǃǦǉƾệǃ,ǦǅƽƾềǃǦǃƼươƾǦƼƾƕǅǦđỡǦƸƽƕǉ,ǦđếǃǦƸƽỗǦđƇǦđườǃƼǦđƚǦǃƼƽƺǦǃƼƚǃƼǦǉƾǃǦǉứƸǦ——ǦǉƾǃǦƼƔǦƸũǃƼǦđượƸ!",
    ["快把这弓箭放下，若是一时失手可就不好了。"] = "ƨƶǊǦƽạǦƸǊǃƼǦǉƾễǃǦǍǊốǃƼǦđƾ,ǦǃƽỡǦǉƶǓǦǂộǉǦƸƑƾǦǁƐǦǀƽƇǃƼǦǍǄǃƼǦđƁǊ.",
    ["武德司果然藏龙卧虎，年轻人你这身手，当真是人中龙凤。"] = "ƱƅǦĐứƸǦǥǓǦǆǊảǦǃƽƾƙǃǦǉƐǃƼǦǁǄǃƼǦǃƼọƶǦƽổ,ǦǉƾểǊǦƽữǊǦǉƽƁǃǦǉƽủǦǉƽếǦǃƐǓ,ǦđƕǃƼǦǁƐǦǃƽƁǃǦǉǇǊǃƼǦǁǄǃƼǦǅƽượǃƼ.",
    ["方才你怎么敢上去的？后生，你可知道这是何处？！"] = "ƱừƶǦǇồƾǦǈƶǄǦǃƼươƾǦǤƑǂǦǍƇǃƼǦǁƙǃǦƽả?ǦƣậǊǦǈƾǃƽ,ǦǃƼươƾǦƸƚǦƷƾếǉǦđƁǓǦǁƐǦǃơƾǦǃƐǄǦǀƽƇǃƼ?!",
    ["我自是明白。但是大人，相公们既然有错，如何能不说呢？若你我都不说，何人扶正世道呢？"] = "ǥƶǦǉựǦƷƾếǉǦǇƅ.ǦƩƽưǃƼǦđạƾǦǃƽƁǃǦƐ,ǦƸƑƸǦǋịǦǉướǃƼǦƸƇǃƼǦđƃǦƸƚǦǁỗƾ,ǦǈƶǄǦƸƚǦǉƽểǦǀƽƇǃƼǦǃƚƾ?ǦƩếǊǦǃƼƐƾǦǋƐǦǉƶǦđềǊǦƾǂǦǁặǃƼ,ǦǉƽƔǦƶƾǦǈẽǦǁƐǦǃƼườƾǦǅƽƛǦƸƽƓǃƽǦǉƽếǦđạǄǦđƁǓ?",
    ["你们这帮新科后生……哎哟……"] = "ƞƑƾǦđƑǂǦǉƁǃǦǀƽǄƶǦƽậǊǦǈƾǃƽǦƸƑƸǦǃƼươƾ……ǦƑƾǦƸƽƐ……",
    ["大人您别急，喝水、喝水……"] = "ĐạƾǦǃƽƁǃǦǃƼƐƾǦđừǃƼǦǋộƾ,ǦǊốǃƼǦǃướƸ,ǦǊốǃƼǦǃướƸǦđƾ……",
    ["年轻人，宫中耳目众多，还望谨言慎行，莫给人留下话柄。"] = "ƩƼườƾǦǉǇẻǦǉǊổƾ,ǦǉǇǄǃƼǦƸǊǃƼǦǉƶƾǦǂắǉǦǇấǉǦǃƽƾềǊ,ǦǂǄǃƼǦƽƃǓǦƸẩǃǦǃƼƇǃǦǉƽậǃǦƽƐǃƽ,ǦđừǃƼǦđểǦǃƼườƾǦǉƶǦǃắǂǦđượƸǦǉƽƚǅ.",
    ["武德司之事可不归我们管。"] = "ƞƽǊǓệǃǦƸủƶǦƱƅǦĐứƸǦǥǓǦǀƽƇǃƼǦǉƽǊộƸǦǆǊǓềǃǦǆǊảǃǦǁƈǦƸủƶǦƸƽƕǃƼǦǉƶ.",
    ["听说现在宫里都是武德司了？"] = "ƩƼƽƺǦǃƚƾǦƷƁǓǦƼƾờǦǉǇǄǃƼǦƸǊǃƼǦǉǄƐǃǦǁƐǦǃƼườƾǦƸủƶǦƱƅǦĐứƸǦǥǓǦǈƶǄ?",
    ["还有几撮殿前司的。嘿，要我说，当退则退，真当还是从前的骄横时日呢。"] = "ƞƛǃǦǋƐƾǦǃƽƚǂǦƸủƶǦĐƾệǃǦǥƾềǃǦǥǓǦǃữƶ.Ǧƣƙ,ǦǉƶǦǃƚƾǦǃƽƗ,ǦƷƾếǉǦǉƾếǃǦƷƾếǉǦǁǊƾǦǂớƾǦǁƐǦǉƽứƸǦǉƽờƾ,ǦǉưởǃƼǦđƁǊǦǋẫǃǦƸƛǃǦǁƐǦǃƽữǃƼǦǃƼƐǓǦǀƾƙǊǦƸăǃƼǦǃƼạǄǦǂạǃǦǃƽưǦǍưƶǦǈƶǄ.",
    ["可别这么说！你要是辞官了，那活不就都到我头上了？"] = "ĐừǃƼǦǃƚƾǦǋậǓǦƸƽứ!ǦƩếǊǦƽǊǓǃƽǦǉừǦǆǊƶǃ,ǦđốǃƼǦǋƾệƸǦđƚǦƸƽẳǃƼǦǅƽảƾǦđổǦƽếǉǦǁƙǃǦđầǊǦǉƶǦǈƶǄ?",
    ["这官署里头是热闹哈，还有这等场面能看……"] = "ǥǇǄǃƼǦǆǊƶǃǦǉƽựǦǃƐǓǦǃƑǄǦǃƽƾệǉǦǉƽậǉǦđƚǦǃƽƶ,ǦƸƛǃǦƸƚǦƸảǦƸảǃƽǦǉượǃƼǦǉƽếǦǃƐǓǦđểǦǍƺǂ……",
    ["不错吧？考虑考虑，调职到宣徽院来？"] = "ƦƽƇǃƼǦǉệǦƸƽứ?ǦƞƁǃǦǃƽắƸǦƸƽƕǉǦđƾ,ǦđƾềǊǦƸƽǊǓểǃǦƸƇǃƼǦǉƑƸǦǈƶǃƼǦǥǊǓƙǃǦƣǊǓǦƱƾệǃǦǀƽƇǃƼ?",
    ["嘿你个瘦猴御史，还真要跟我动手？！"] = "ƣƙǦƸƑƾǦǁƃǄǦǃƼựǦǈửǦƼầǓǦǃƽưǦǀƽỉǦǀƾƶ,ǦđịǃƽǦđộǃƼǦǉƽủǦǋớƾǦǉƶǦǉƽậǉǦđấǓǦƐ?!",
    ["呿，少打算盘。我在史馆休息好好的，调职来你这加班加点的，当我是傻子？"] = "ƳƔ,ǦƷớǉǦǉƓǃƽǦǉǄƑǃǦđƾ.ǦǥƶǦđƶǃƼǦởǦƮửǦƬǊƑǃǦǃƼƽỉǦǃƼơƾǦǓƙǃǦǁƐǃƽ,ǦđƾềǊǦǈƶǃƼǦƸƽỗǦǃƼươƾǦǁƐǂǦǉƽƙǂǦƼƾờǦǆǊầǃǦǆǊậǉ,ǦƸǄƾǦǉƶǦǁƐǦǀẻǦǃƼốƸǦƸƽắƸ?",
    ["就是！你敢！"] = "ĐƕǃƼǦǉƽế!ǦƩƼươƾǦǤƑǂǦǀƽƇǃƼ!",
    ["你试试啊！你试试我这笏板能不能抽得动你啊！"] = "ƩƼươƾǦǉƽửǦǍƺǂ!ǦǥƽửǦǍƺǂǦƸƑƾǦƽốǉǦƷảǃǦǃƐǓǦƸủƶǦǉƶǦƸƚǦǆǊấǉǦđượƸǦǃƼươƾǦǀƽƇǃƼ!",
    ["动手就动手！"] = "ĐộǃƼǦǉƽủǦǉƽƔǦđộǃƼǦǉƽủ!",
    ["昨日收好的《会计录》卷之七十三去哪里了？"] = "ƬǊǓểǃǦǉƽứǦƷảǓǦǂươƾǦƷƶǦƸủƶǦ<ƣộƾǦƦếǦƧụƸ>ǦǉƽǊǦǤọǃǦƽƇǂǦǆǊƶǦđƁǊǦǂấǉǦǇồƾ?",
    ["这个升平楼用……这个腊祭用……这个……"] = "ƞƑƾǦǃƐǓǦǥƽăǃƼǦƝƔǃƽǦƧƁǊǦǤƖǃƼ……ǦƸƑƾǦǃƐǓǦƧạǅǦǥếǦǤƖǃƼ……ǦƸƑƾǦǃƐǓ……",
    ["元宵宫宴的酒具放到哪里去了？"] = "ǥửǊǦƸụǦƸủƶǦƸǊǃƼǦǓếǃǦƩƼǊǓƙǃǦǥƾƙǊǦđểǦởǦđƁǊǦǇồƾ?",
    ["在宫内跌跌撞撞成何体统？"] = "ỞǦǉǇǄǃƼǦƸǊǃƼǦǂƐǦđƾǦđứǃƼǦǋƶǦǋấǅǦǉƽếǦǃƐǓǦƸƛǃǦǇƶǦǉƽểǦǉƽốǃƼǦƼƔǦǃữƶ?",
    ["看着点路！"] = "ƩƽƔǃǦđườǃƼǦƸƽƕǉǦđƾ!",
    ["军士身轻如燕，飞檐走壁若等闲，真是让我大开眼界。"] = "ƬǊƁǃǦǈĩǦǉƽƁǃǦǃƽẹǦǃƽưǦǓếǃ,ǦǉƽƁǃǦǅƽƑǅǦǉậǉǦƽƐǃƽǦǃƽưǦđƾǦǉǇƙǃǦđấǉǦƷằǃƼ,ǦđƕǃƼǦǁƐǦǁƐǂǦǉƶǦǂởǦǂƶǃƼǦǉầǂǦǂắǉ.",
    ["你写得怎么样啦？给我看看嘛，你的《宫廷秘史·续》！"] = "ƩƼươƾǦǋƾếǉǦđếǃǦđƁǊǦǇồƾ?ǦƞƽǄǦǉƶǦǍƺǂǦƸƽƕǉǦđƾ,ǦƸǊốǃǦ<ƞǊǃƼǦĐƔǃƽǦƝƓǦƮửǦ·ǦǥụƸ>ǦƸủƶǦǃƼươƾǦấǓ!",
    ["我可没有在摸鱼，我们在实行轮换制呢，刚巧今儿轮到我休息。"] = "ǥƶǦǀƽƇǃƼǦƸƚǦǁườƾǦƷƾếǃƼǦ(ǂƇǦǃƼư)ǦđƁǊǦǃƽƗ,ǦƸƽƕǃƼǦǉƶǦđƶǃƼǦǉƽựƸǦƽƾệǃǦƸƽếǦđộǦǁǊƁǃǦǅƽƾƙǃ,ǦǋừƶǦǀƽƗǄǦƽƇǂǦǃƶǓǦđếǃǦǁượǉǦǉƶǦǃƼƽỉ.",
    ["你怎么不出门玩？"] = "ƮƶǄǦǃƼươƾǦǀƽƇǃƼǦǇƶǦǃƼǄƐƾǦƸƽơƾ?",
    ["说实话，上班的日子太久，偶尔松快一日，我都不知道能干些什么。"] = "ƩƚƾǦǉƽậǉ,ǦǃƼƐǓǦǉƽƑǃƼǦǁƐǂǦǋƾệƸǦǆǊƑǦǁƁǊ,ǦǉƽƾǦǉƽǄảǃƼǦđượƸǦǉƽảǃƽǦǉƽơƾǦǂộǉǦǃƼƐǓ,ǦǉƶǦƸũǃƼǦƸƽẳǃƼǦƷƾếǉǦǃƙǃǦǁƐǂǦƼƔǦǃữƶ.",
    ["瞧，这光泽、这形状……这样好的珍珠，也就在宫里可以见到！"] = "ƩƽƔǃǦǀƔƶ,ǦđộǦƷƚǃƼǦǃƐǓ,ǦƽƔǃƽǦǤƑǃƼǦǃƐǓ……ǦǉǇƁǃǦƸƽƁǊǦǉốǉǦǉƽếǦǃƐǓǦƸƽỉǦƸƚǦởǦǉǇǄǃƼǦƸǊǃƼǦǂớƾǦǉƽấǓǦđượƸ!",
    ["这可是吴越今岁送来的贡品，我还是头一回摸到纱罗……"] = "ĐƁǓǦǁƐǦƸốǃƼǦǅƽẩǂǦƩƼƇǦƱƾệǉǦǂớƾǦƼửƾǦǉớƾǦǃăǂǦǃƶǓǦđƚ,ǦǉƶǦƸũǃƼǦǁƐǦǁầǃǦđầǊǦđượƸǦƸƽạǂǦǋƐǄǦǈƶǦǁƶ……",
    ["高娘子说要给周娘子做件衣裳，当生辰贺礼。"] = "ƞƶǄǦǃươǃƼǦǉửǦƷảǄǦǂǊốǃǦǁƐǂǦƸƽǄǦƞƽǊǦǃươǃƼǦǉửǦǂộǉǦƷộǦǓǦǅƽụƸǦǁƐǂǦǆǊƐǦǂừǃƼǦǈƾǃƽǦǉƽầǃ.",
    ["姑姑说，咱们今儿就是三班倒，也得把这件衣裳按时交上去！"] = "ƞƇǦƸƇǦƷảǄ,ǦƸƽƕǃƼǦǉƶǦƽƇǂǦǃƶǓǦǤƖǦƸƚǦǅƽảƾǦƸƽƾƶǦƷƶǦƸƶǦǉǇựƸǦǁƾƙǃǦǉụƸǦƸũǃƼǦǅƽảƾǦƼƾƶǄǦƷộǦǓǦǅƽụƸǦǃƐǓǦđƕǃƼǦƽạǃ!",
    ["可是，咱们都是同一波人，干三个人的活……"] = "ƩƽưǃƼǦǂƐ,ǦƸƽƕǃƼǦǉƶǦǋẫǃǦƸƽỉǦƸƚǦǃƼầǃǦấǓǦǃƼườƾ,ǦǂƐǦǅƽảƾǦǁƐǂǦǋƾệƸǦƷằǃƼǦƷƶǦǃƼườƾ……",
    ["要我说，这宫里就数尚功和咱们尚最较着劲儿。也不知是得了什么新巧的差事，这么卖力。"] = "ǥƽƺǄǦǉƶǦǉƽấǓ,ǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦǥƽượǃƼǦƞƇǃƼǦǋƐǦǥƽượǃƼǦ[ƞụƸ]ǦƸƽƕǃƼǦǉƶǦǁƐǦƼƶǃƽǦđǊƶǦǃƽƶǊǦǃƽấǉ.ǦƞƽẳǃƼǦƷƾếǉǦǁƐǦǃƽậǃǦđượƸǦǈƶƾǦǅƽƑƾǦǂớƾǦǁạǦƼƔǦǂƐǦǤốƸǦǈứƸǦđếǃǦǉƽế.",
    ["这倒不是，听说尚功和咱们姑姑，是那个！"] = "ƞũǃƼǦǀƽƇǃƼǦƽẳǃ,ǦǃƼƽƺǦǃƚƾǦǥƽượǃƼǦƞƇǃƼǦǋƐǦƸƇǦƸƇǦǃƽƐǦǂƔǃƽ,ǦǁƐǦƸƑƾǦđƚǦđƚ!",
    ["那个……？不会是……挚友吧！每天相约一同下班？"] = "ƞƑƾǦđƚ……?ǦƦƽƇǃƼǦǁẽǦǁƐ……ǦƸƽƓǦƽữǊǦǈƶǄ!ǦƩƼƐǓǦǃƼƐǓǦƽẹǃǦǃƽƶǊǦƸƖǃƼǦǉƶǃǦǁƐǂ?",
    ["哎哟喂，当然不是！不过你这么一说，有道理啊，得好好琢磨琢磨……"] = "ÁƾǦƸƽƐǦƸƽƐ,ǦǉấǉǦǃƽƾƙǃǦǀƽƇǃƼǦǅƽảƾǦǇồƾ!ǦƞơǦǂƐǦǃƼươƾǦǃƚƾǦǉƽếǦƸũǃƼǦƸƚǦǁƈ,ǦđểǦǉƶǦǃƼẫǂǦǁạƾǦǍƺǂǦǈƶǄ……",
    ["好好，我是管不了这档子事了！"] = "ĐượƸǦǇồƾǦđượƸǦǇồƾ,ǦǉƶǦƸƽẳǃƼǦǆǊảǃǦǃổƾǦƸƑƾǦǋƾệƸǦǃƐǓǦǃữƶ!",
    ["我分明是为了大家好，怎么谁也不爱听，莫非真是我错了……"] = "ǥƶǦǇƅǦǇƐǃƼǦǁƐǦǋƔǦǉốǉǦƸƽǄǦǂọƾǦǃƼườƾ,ǦǈƶǄǦƸƽẳǃƼǦƶƾǦǂǊốǃǦǃƼƽƺ,ǦǁẽǦǃƐǄǦǉƶǦǈƶƾǦǉƽậǉǦǇồƾǦǈƶǄ……",
    ["门窗都锁好了？香都熄了？这地方要是走了水，我们都得掉脑袋。"] = "ƞửƶǦǃẻǄǦǀƽƚƶǦǀỹǦƸƽưƶ?ǦƣươǃƼǦđƃǦǉắǉǦƽếǉǦƸƽưƶ?ǦƞƽỗǦǃƐǓǦǂƐǦƽỏƶǦƽǄạǃǦ(ǉẩǊǦǉƽủǓ)ǦǉƽƔǦǉấǉǦƸảǦƸƽƕǃƼǦǉƶǦđềǊǦǂấǉǦđầǊǦǃƽưǦƸƽơƾ.",
    ["你我都是当差的，何必动手？"] = "ƩƼươƾǦǋƐǦǉƶǦđềǊǦǁƐǦǃƼườƾǦǁƐǂǦǈƶƾǦǅƽƑƾ,ǦƽƐǦǉấǉǦǅƽảƾǦđộǃƼǦǉƽủ?",
    ["听说这块闹鬼了？也不知是真是假，近日人心惶惶的。"] = "ƩƼƽƺǦǃƚƾǦƸƽỗǦǃƐǓǦƸƚǦǂƶ?ǦƞƽẳǃƼǦƷƾếǉǦǁƐǦǉƽậǉǦƽƶǓǦƼƾả,ǦǤạǄǦǃƐǓǦǃƽƁǃǦǉƁǂǦƽǄảǃƼǦǁǄạǃǦǆǊƑ.",
    ["都这么说，愣是一个见过的都没有，怕不是哪个胆小鬼吧！哈哈哈……"] = "ƜƾǦƸũǃƼǦǃƚƾǦǉƽế,ǦǂƐǦƸƽẳǃƼǦǉƽấǓǦƶƾǦǉậǃǦǂắǉǦƸƽứǃƼǦǀƾếǃ,ǦƸƽắƸǦǁƐǦǤǄǦǉƙǃǦǃƽƑǉǦƼƶǃǦǃƐǄǦđƚǦǉƽƙǊǦǤệǉǦǉƽƇƾ!ǦƣƶǦƽƶǦƽƶ……",
    ["近日来瞧病的，十之五六都是饮食生冷导致的泄痢之症，你和前头那几个一样，回去莫要再食寒凉之物。"] = "ƢầǃǦđƁǓǦǃƼườƾǦđếǃǦǀƽƑǂǦƷệǃƽ,ǦǂườƾǦǃƼườƾǦǉƽƔǦƽếǉǦǃăǂǦǈƑǊǦǃƼườƾǦǁƐǦǤǄǦăǃǦǊốǃƼǦđồǦǈốǃƼǦǁạǃƽǦǤẫǃǦđếǃǦƸƽứǃƼǦǉƾếǉǦǁị,ǦǃƼươƾǦƸũǃƼǦƼƾốǃƼǦǂấǓǦǃƼườƾǦǉǇướƸǦǉƽƇƾ,ǦǋềǦǃƽƐǦđừǃƼǦăǃǦđồǦƽƐǃǦǁươǃƼǦǃữƶ.",
    ["神清气爽，正是干活的好时候啊！"] = "ǥƽầǃǦǉƽƶǃƽǦǀƽƓǦǈảǃƼ,ǦđƕǃƼǦǁƐǦǁƕƸǦǉốǉǦđểǦǁƐǂǦǋƾệƸǦđƁǓ!",
    ["去哪？我哪也不去啊！我就是怕干着活突然一下死这了……"] = "ĐƾǦđƁǊ?ǦǥƶǦƸƽẳǃƼǦđƾǦđƁǊǦƸả!ǦǥƶǦƸƽỉǦǁƐǦǈợǦđƶǃƼǦǁƐǂǦǋƾệƸǦƷỗǃƼǦǤưǃƼǦǁăǃǦđƖǃƼǦǇƶǦƸƽếǉǦởǦđƁǓǦǉƽƇƾ……",
    ["总觉着还差了点啥，还是不大像……"] = "ƞứǦǉƽấǓǦǉƽƾếǊǦǉƽƾếǊǦƸƑƾǦƼƔǦđƚ,ǦǋẫǃǦƸƽưƶǦƼƾốǃƼǦǁắǂ……",
    ["哥，能跟你换个地方么？我想……正好路过看看我娘。"] = "ƣǊǓǃƽǦƐ,ǦđổƾǦƸƽỗǦǉǇựƸǦƸƽǄǦđệǦđượƸǦǀƽƇǃƼ?ǦĐệǦǂǊốǃ……ǦǉƾệǃǦđườǃƼǦƼƽƗǦǆǊƶǦǉƽăǂǦǂẫǊǦǉƽƁǃ.",
    ["我看看你这眉毛咋画的？我的咋歪了呢……"] = "ĐểǦǉƶǦǍƺǂǦǁƇǃƼǦǂƐǓǦǃƼươƾǦǋẽǦǀƾểǊǦƼƔ?ǦƮƶǄǦƸủƶǦǉƶǦǁạƾǦƷịǦǁệƸƽǦǉƽếǦǃƐǓ……",
    ["说了多少遍了，动作太僵硬！别人一眼就看出来了，要像这样！"] = "ƩƚƾǦƷƶǄǦǃƽƾƙǊǦǁầǃǦǇồƾ,ǦđộǃƼǦǉƑƸǦǆǊƑǦƸứǃƼǦǃƽắƸ!ǦƩƼườƾǦǉƶǦǃƽƔǃǦƸƑƾǦǁƐǦǇƶǦǃƼƶǓ,ǦǅƽảƾǦǃƽưǦǉƽếǦǃƐǓǦǃƐǓ!",
    ["你们几个新来的，若再学不会，大可不必到探事司来，刺探之事，若连自己都骗不过去，怎么让别人信服？成为探事司的一员，就要忘掉自己本来的样子。"] = "ƨấǓǦđứƶǦǂớƾǦǉớƾǦƸƑƸǦǃƼươƾ,ǦǃếǊǦǋẫǃǦǀƽƇǃƼǦƽọƸǦđượƸǦǉƽƔǦđừǃƼǦđếǃǦǥƽƑǂǦƮựǦǥǓǦǃữƶ,ǦǋƾệƸǦǂậǉǦǉƽƑǂǦǂƐǦǃƼƶǓǦƸảǦƸƽƓǃƽǦǂƔǃƽǦƸũǃƼǦǀƽƇǃƼǦǁừƶǦǃổƾǦǉƽƔǦǈƶǄǦǀƽƾếǃǦǃƼườƾǦǀƽƑƸǦǉƾǃǦǅƽụƸ?ǦĐƃǦǉǇởǦǉƽƐǃƽǦǂộǉǦǅƽầǃǦƸủƶǦǥƽƑǂǦƮựǦǥǓǦǉƽƔǦǅƽảƾǦǆǊƙǃǦđƾǦǤƑǃƼǦǋẻǦǋốǃǦƸƚǦƸủƶǦƷảǃǦǉƽƁǃ.",
    ["这几个字大小不一样，打回去重写！"] = "ƨấǓǦƸƽữǦǃƐǓǦǀƓƸƽǦƸỡǦǀƽƇǃƼǦđồǃƼǦđềǊ,ǦǉǇảǦǋềǦƸƽƗǅǦǁạƾ!",
    ["唉，净是些鸡毛蒜皮的小事，写着还麻烦……"] = "ƣƶƾǏǏ,ǦǉǄƐǃǦǁƐǦǂấǓǦƸƽǊǓệǃǦǁƇǃƼǦƼƐǦǋỏǦǉỏƾ,ǦǋƾếǉǦǁƑƸƽǦǉƽậǉǦǅƽƾềǃǦǅƽứƸ……",
    ["粪桶污秽，莫脏了衣角。"] = "ǥƽƖǃƼǦǅƽƁǃǦǊǦǊế,ǦđừǃƼǦđểǦƷẩǃǦǋạǉǦƑǄ.",
    ["康子，蹲坑人少，你一个劲在这排着干啥？"] = "ƦƽƶǃƼǦǥử,ǦƸƽỗǦđƾǦǋệǦǈƾǃƽǦƓǉǦǃƼườƾ,ǦǃƼươƾǦƸứǦđứǃƼǦđƁǓǦǍếǅǦƽƐǃƼǦǁƐǂǦƸƑƾǦƼƔ?",
    ["瞧瞧尚功那帮人，都这个时辰了，还一个个跟不要命了似的，灯火通明地不肯歇。"] = "ƩƽƔǃǦđƑǂǦǃƼườƾǦǥƽượǃƼǦƞƇǃƼǦǀƾƶǦǀƔƶ,ǦƼƾờǦǃƐǓǦǇồƾǦǂƐǦđứƶǦǃƐǄǦđứƶǦǃấǓǦƸứǦǃƽưǦǁƾềǊǦǂạǃƼ,ǦđƘǃǦđǊốƸǦǈƑǃƼǦǉǇưǃƼǦǀƽƇǃƼǦƸƽịǊǦǃƼƽỉ.",
    ["听我口令！起！落！起！落！"] = "ƩƼƽƺǦǀƽẩǊǦǁệǃƽǦƸủƶǦǉƶ!ǦƧƙǃ!ǦƳǊốǃƼ!ǦƧƙǃ!ǦƳǊốǃƼ!",
    ["人生就跟捣练一样大起大落啊……哎呦，胳膊酸了。"] = "ĐờƾǦǃƼườƾǦƸũǃƼǦƼƾốǃƼǦǃƽưǦƼƾặǉǦǁụƶǦ(đảǄǦǁǊǓệǃ)ǦǋậǓ,ǦǁƕƸǦǁƙǃǦǁƕƸǦǍǊốǃƼ……ǦƑƾǦƸƽƐ,ǦǂỏƾǦǉƶǓǦǆǊƑ.",
    ["听说尚食局有宫女打算自请出宫，她们有什么打算呢？要不要去打听一下？"] = "ƩƼƽƺǦǃƚƾǦǥƽượǃƼǦǥƽựƸǦƞụƸǦƸƚǦƸǊǃƼǦǃữǦđịǃƽǦǉựǦǍƾǃǦǍǊấǉǦƸǊǃƼ,ǦƷọǃǦƽọǦƸƚǦǤựǦǉƓǃƽǦƼƔǦǃƽỉ?ǦƞƚǦǂǊốǃǦđƾǦǃƼƽƺǦǃƼƚǃƼǦƸƽƕǉǦǀƽƇǃƼ?",
    ["怪了，我核算这个月的账目，怎么又是香蒲来领了这么多纸笔？"] = "ƧạǦǉƽậǉ,ǦǉƶǦǀƾểǂǦǉǄƑǃǦǈổǦǈƑƸƽǦǉƽƑǃƼǦǃƐǓ,ǦǈƶǄǦǁạƾǦǁƐǦƣươǃƼǦƝồǦđếǃǦǃƽậǃǦǃƽƾềǊǦƼƾấǓǦƷƕǉǦǉƽếǦǃƐǓ?",
    ["香蒲也是个傻的，刚发的月钱，转头就全换成这些。"] = "ƣươǃƼǦƝồǦƸũǃƼǦǃƼốƸǦǉƽậǉ,ǦǉƾềǃǦǉƽƑǃƼǦǋừƶǦǅƽƑǉǦǍǄǃƼ,ǦǃƼǄảǃƽǦđƾǦǃƼǄảǃƽǦǁạƾǦđƃǦđổƾǦƽếǉǦǉƽƐǃƽǦǂấǓǦǉƽứǦǃƐǓǦǇồƾ.",
    ["攒个体己钱不容易，她这又是何苦？"] = "ǥƓƸƽǦƸƚǅǦƸƽƕǉǦǉƾềǃǦǇƾƙǃƼǦ(ǉƽểǦǀỷǦǉƾềǃ)ǦđƁǊǦƸƚǦǤễǦǤƐǃƼ,ǦǂǊộƾǦấǓǦǁƐǂǦǋậǓǦǁƐǦǋƔǦǁẽǦƼƔ?",
    ["姐姐不知道她？宫里有名的“书痴”！听说她呀，每日除了干活，就是在写她那没人看的话本呢！"] = "ǥỷǦǉỷǦǀƽƇǃƼǦƷƾếǉǦǂǊộƾǦấǓǦǈƶǄ?Ǧ\"ǥƽưǦǈƾ\"ǦƸƚǦǉƾếǃƼǦǉǇǄǃƼǦƸǊǃƼǦđƚ!ǦƩƼƽƺǦǃƚƾǦǂǊộƾǦấǓǦấǓǦƐ,ǦǂỗƾǦǃƼƐǓǦǃƼǄƐƾǦǁƐǂǦǋƾệƸǦǇƶǦǁƐǦǁạƾǦǋƾếǉǦǂấǓǦƸǊốǃǦǉƽǄạƾǦƷảǃǦƸƽẳǃƼǦƶƾǦǉƽƘǂǦǍƺǂǦƸủƶǦǂƔǃƽ!",
    ["上回我也瞧了一眼，那话本……怎么说呢，寡淡无味，纯粹是白费力气，不是那块料。"] = "ƧầǃǦǉǇướƸǦǉƶǦƸũǃƼǦǁƾếƸǦǆǊƶǦǂộǉǦƸƑƾ,ǦƸǊốǃǦǉƽǄạƾǦƷảǃǦđƚ……ǦǃƚƾǦǉƽếǦǃƐǄǦǃƽỉ,ǦǃƽạǉǦǃƽưǦǃướƸǦốƸ,ǦǉƽǊầǃǦǉƕǓǦǁƐǦǅƽƓǦƸƇǃƼǦǋƇǦƓƸƽ,ǦǀƽƇǃƼǦǅƽảƾǦƸƑƾǦƸƽấǉǦđƚǦđƁǊ.",
    ["由她去吧，能坚持，本身就是一种天赋。更何况，在这宫里，人总得有个念想才活得下去。"] = "ƞứǦǂặƸǦǀệǦǂǊộƾǦấǓǦđƾ,ǦǀƾƙǃǦǉǇƔǦđượƸǦƸũǃƼǦđƃǦǁƐǦǂộǉǦǁǄạƾǦǉƽƾƙǃǦǅƽƕǦǇồƾ.ǦƣǊốǃƼǦƸƽƾǦởǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓ,ǦƸǄǃǦǃƼườƾǦǉƶǦǁǊƇǃǦǅƽảƾǦƸƚǦǂộǉǦƸƽƕǉǦǉƁǂǦǃƾệǂǦǉƽƔǦǂớƾǦǈốǃƼǦǃổƾ.",
    ["唉，她们怎么都弹得这么好……再听听我这，简直跟锯木头似的。"] = "ƣƶƾǏǏ,ǦǈƶǄǦƷọǃǦƽọǦƶƾǦƸũǃƼǦđƐǃǦƽƶǓǦǉƽếǦǃƽỉ……ǦǃƼƽƺǦǁạƾǦǉƾếǃƼǦđƐǃǦƸủƶǦǉƶǦǃƐǓ,ǦƸƽẳǃƼǦǀƽƑƸǦƼƔǦǉƾếǃƼǦƸưƶǦƼỗ.",
    ["我……我正在练习指法呢！对，就是新学的《春江花月夜》，这曲子最是考验功力，得多花些心思揣摩……我可没有闲着！绝对没有！"] = "ǥƶ……ǦǉƶǦđƶǃƼǦǁǊǓệǃǦƸƽỉǦǅƽƑǅǦǂƐ!ǦĐƕǃƼǦǇồƾ,ǦƸƽƓǃƽǦǁƐǦǀƽƕƸǦ<ƳǊƁǃǦƢƾƶǃƼǦƣǄƶǦƩƼǊǓệǉǦǝạ>ǦǂớƾǦƽọƸ,ǦǀƽƕƸǦǃƐǓǦǉƽửǦǉƽƑƸƽǦƸƇǃƼǦǅƽǊǦǃƽấǉ,ǦǅƽảƾǦǉốǃǦǃƽƾềǊǦǉƁǂǦǉưǦǃƼƽƾềǃǦǃƼẫǂ……ǦǉƶǦǀƽƇǃƼǦƸƚǦǇảǃƽǦǇỗƾǦđƁǊ!ǦǥǊǓệǉǦđốƾǦǀƽƇǃƼ!",
    ["你才练了多久，别心急。我们刚开始的时候，弹得还不如你呢。"] = "ƩƼươƾǦǂớƾǦǁǊǓệǃǦƷƶǄǦǁƁǊǦđƁǊ,ǦđừǃƼǦǃƚǃƼǦǋộƾ.ǦƧƕƸǦƸƽƕǃƼǦǉƶǦǂớƾǦƷắǉǦđầǊ,ǦđƐǃǦƸƛǃǦƸƽẳǃƼǦƷằǃƼǦǃƼươƾǦƷƁǓǦƼƾờ.",
    ["勤练固然重要，可要是能亲耳听听真正的大师是怎么弹的，或许我就能开窍了……比如说，江逸！"] = "ƞƽăǂǦƸƽỉǦǁǊǓệǃǦǉậǅǦǉấǉǦǃƽƾƙǃǦǁƐǦǆǊƶǃǦǉǇọǃƼ,ǦǃƽưǃƼǦǃếǊǦƸƚǦǉƽểǦǉậǃǦǉƶƾǦǃƼƽƺǦđạƾǦǈưǦǉƽựƸǦǉƽụǦđƐǃǦǃƽưǦǉƽếǦǃƐǄ,ǦƷƾếǉǦđƁǊǦǉƶǦǈẽǦǀƽƶƾǦǀƽƾếǊ……ǦǋƓǦǤụǦǃƽưǦƢƾƶǃƼǦǝậǉǦƸƽẳǃƼǦƽạǃ!",
    ["知道你喜欢江逸的琴，但他都退隐了。唉，不知还有没有机会再次听到他的琴声……"] = "ƝƾếǉǦǂǊộƾǦǉƽƓƸƽǦǉƾếǃƼǦƸầǂǦƸủƶǦƢƾƶǃƼǦǝậǉ,ǦǃƽưǃƼǦǃƼườƾǦǉƶǦđƃǦǆǊǓǦẩǃǦǇồƾ.ǦƣƶƾǏǏ,ǦƸƽẳǃƼǦƷƾếǉǦƸƛǃǦƸơǦƽộƾǦǃƐǄǦđượƸǦǃƼƽƺǦǁạƾǦǉƾếǃƼǦđƐǃǦấǓǦǃữƶǦǀƽƇǃƼ……",
    ["咳……军士，撞到了我倒无妨，若是失了体面可不好。"] = "Ʀƽụ……ǦǆǊƁǃǦǈĩ,ǦđụǃƼǦǉǇƕǃƼǦǉƶǦǉƽƔǦǀƽƇǃƼǦǈƶǄ,ǦǃƽưǃƼǦǃếǊǦǂấǉǦđƾǦǉƽểǦǤƾệǃǦǉƽƔǦǀƽƇǃƼǦǉốǉǦđƁǊ.",
    ["谁？我没睡觉……闭目养神……"] = "ƜƾǦđƚ?ǦǥƶǦǀƽƇǃƼǦƸƚǦǃƼủ……ǦƸƽỉǦǁƐǦǃƽắǂǦǂắǉǦǤưỡǃƼǦǉƽầǃǦǉƽƇƾ……",
    ["这日子啥时候是个头哦，老子一身力气没地儿使，憋屈死了。"] = "ƩƼƐǓǦǉƽƑǃƼǦǃƐǓǦƷƶǄǦƼƾờǦǂớƾǦǀếǉǦǉƽƕƸǦđƁǓ,ǦǁƃǄǦǉửǦǂộǉǦǉƽƁǃǦǈứƸǦǁựƸǦǂƐǦƸƽẳǃƼǦƸƚǦƸƽỗǦǤƖǃƼ,ǦǊấǉǦứƸǦƸƽếǉǦđƾǦđượƸ.",
    ["嘿，这不是挺好的嘛！活都让武德司那帮人干了，咱不干活还拿着月俸，舒坦！"] = "ƣƙ,ǦǉƽếǦǃƐǓǦƸƽẳǃƼǦǅƽảƾǦǇấǉǦǉốǉǦǈƶǄ!ǦƱƾệƸǦǉƽƔǦđểǦđƑǂǦƱƅǦĐứƸǦǥǓǦǁƐǂǦƽếǉ,ǦǂƔǃƽǦǃƼồƾǦƸƽơƾǦǍơƾǦǃướƸǦǂƐǦǋẫǃǦƸƚǦǉƾềǃǦǉƽƑǃƼ,ǦǈướǃƼ!",
    ["你咋就这点格局？理想在哪里？抱负又在哪里？！"] = "ƮƶǄǦǉầǂǦǃƽƔǃǦƸủƶǦǃƼươƾǦƸƽỉǦƸƚǦƷấǓǦǃƽƾƙǊǦǉƽƇƾ?ǦƧƈǦǉưởǃƼǦởǦđƁǊ?ǦƣǄƐƾǦƷƃǄǦởǦđƁǊ?!",
    ["还说我呢，你咋这么想不开？都已经没有钱了，总不能还累着吧！"] = "ƞƛǃǦǃƚƾǦǉƶǦƐ,ǦǈƶǄǦƽǊǓǃƽǦƸứǦǃƼƽƘǄǦǂƐǦƽƶǓǦƸƽữǦǉƽế?ǦĐƃǦƸƽẳǃƼǦƸƚǦǉƾềǃǦǇồƾ,ǦƸƽẳǃƼǦǁẽǦǁạƾǦƸƛǃǦđểǦǂƔǃƽǦƸƽịǊǦǂệǉǦǈƶǄ!",
    ["小心点别摔了！"] = "ƞẩǃǦǉƽậǃǦƸƽƕǉǦđừǃƼǦđểǦǃƼƃ!",
    ["得好好清点清点，最近闹耗子，丢了不少东西。"] = "ƫƽảƾǦǀƾểǂǦǀƙǦǁạƾǦƸƽǄǦǀỹ,ǦǤạǄǦǃƐǓǦƸƚǦƸƽǊộǉǦǆǊấǓǦǅƽƑ,ǦǂấǉǦƷƶǄǦǃƽƾƙǊǦđồǦđạƸǦǇồƾ.",
    ["这么认真干啥？丢个几粒米的事，就当喂耗子了。"] = "ƧƐǂǦƼƔǦǂƐǦǃƼƽƾƙǂǦǉǇọǃƼǦǉƽế?ǦƨấǉǦǋƐƾǦƽạǉǦƼạǄǦǉƽƇƾǦǂƐ,ǦƸǄƾǦǃƽưǦƷốǦǉƽƓǦƸƽǄǦƸƽǊộǉǦđƾ.",
    ["这供备库耗子竟这般猖獗？"] = "ƧũǦƸƽǊộǉǦǉǇǄǃƼǦƞǊǃƼǦƝịǦƦƽốǦǃƐǓǦƽǄƐǃƽǦƽƐǃƽǦđếǃǦǂứƸǦấǓǦǈƶǄ?",
    ["可不是！昨个儿还丢了一罐子蜜饯，指不定就是宫里那只最肥的耗子偷吃的，那耗子不光偷吃的，这珠宝银钱它也叼，偷了就藏起来，找都找不着。"] = "ƞƽứǦƸƛǃǦƼƔǦǃữƶ!ǦƣƇǂǦǆǊƶǦƸƛǃǦǂấǉǦǂộǉǦƽũǦǂứǉǦƽǄƶǦǆǊảǦ(ǂậǉǦǉƾễǃ),ǦƸƽắƸǦƸƽắǃǦǁƐǦǤǄǦƸǄǃǦƸƽǊộǉǦƷƗǄǦǃƽấǉǦǉǇǄǃƼǦƸǊǃƼǦǃƐǓǦăǃǦǋụǃƼǦǇồƾ,ǦƸǄǃǦƸƽǊộǉǦđƚǦǀƽƇǃƼǦƸƽỉǦǉǇộǂǦđồǦăǃǦđƁǊ,ǦǃƼƶǓǦƸảǦƸƽƁǊǦƷƑǊǦǉƾềǃǦƷạƸǦǃƚǦƸũǃƼǦǉƽƶǦđƾ,ǦǉǇộǂǦǍǄǃƼǦǁƐǦƼƾấǊǦƷƾệǉ,ǦǉƔǂǦƸƽẳǃƼǦǉƽấǓǦđƁǊǦǁǊƇǃ.",
    ["诶，蜜饯？难不成是昨儿在你桌上的那罐？我寻思是你买的呢……"] = "Ơ,ǦǂậǉǦǉƾễǃǦǈƶǄ?ǦƞƽẳǃƼǦǁẽǦǁƐǦƽũǦđểǦǉǇƙǃǦƷƐǃǦƽǊǓǃƽǦƽƇǂǦǆǊƶ?ǦĐệǦƸứǦǉưởǃƼǦǁƐǦƽǊǓǃƽǦǂǊƶǦƸƽứ……",
    ["这酒……又绵又醇，入口回甘，再闻闻，不，就喝一小口……"] = "ƭượǊǦǃƐǓ……ǦǋừƶǦƙǂǦǋừƶǦǃồǃƼ,ǦǋƐǄǦǂƾệǃƼǦǃƼọǉǦƽậǊ,ǦǃƼửƾǦǉƽƙǂǦƸƽƕǉǦǃữƶ,ǦǀƽƇǃƼ,ǦƸƽỉǦǊốǃƼǦǂộǉǦƽớǅǦǃƽỏǦǉƽƇƾ……",
    ["卉珍姐姐就是在老枯树那边看见鬼了，听姐姐们说，一到晚上就有不干净的东西唱歌……"] = "ƣủǓǦǥǇƁǃǦǉỷǦǉỷǦƸƽƓǃƽǦǁƐǦǉƽấǓǦǂƶǦởǦƸƽỗǦƸƁǓǦǀƽƇǦƼƾƐǦđƚ,ǦǃƼƽƺǦƸƑƸǦǉỷǦǉỷǦǃƚƾ,ǦƸứǦđếǃǦǉốƾǦǁƐǦƸƚǦǉƽứǦǀƽƇǃƼǦǈạƸƽǦǈẽǦƸƶǦƽƑǉ……",
    ["啊！快别说了，怪吓人的，赶紧拿完酒回去，再也不想来这边了！"] = "Á!ǦĐừǃƼǦǃƚƾǦǃữƶ,ǦđƑǃƼǦǈợǦǆǊƑ,ǦǂƶǊǦǁấǓǦǇượǊǦǇồƾǦǋềǦǉƽƇƾ,ǦǀƽƇǃƼǦƷƶǄǦƼƾờǦǂǊốǃǦǉớƾǦđƁǓǦǃữƶǦđƁǊ!",
    ["这批酒可容不得半点马虎，都看仔细了，千万不能混进去脏东西！"] = "ƨẻǦǇượǊǦǃƐǓǦǀƽƇǃƼǦđượƸǦǅƽƗǅǦǁơǦǁƐǦƸƽƕǉǦǃƐǄ,ǦƸƶǃƽǦƸƽừǃƼǦƸƽǄǦǀỹǦǋƐǄ,ǦǉǊǓệǉǦđốƾǦǀƽƇǃƼǦđượƸǦđểǦǉƽứǦƼƔǦƷẩǃǦǉƽỉǊǦǁẫǃǦǋƐǄ!",
    ["这回酿的酒都是给宫里预备着过年用的，可得仔细着，再把粮食筛一遍。"] = "ƭượǊǦủǦǁầǃǦǃƐǓǦđềǊǦǁƐǦđểǦƸǊǃƼǦđƔǃƽǦƸƽǊẩǃǦƷịǦǤƖǃƼǦǉǇǄǃƼǦǤịǅǦǃăǂǦǂớƾ,ǦǅƽảƾǦƸẩǃǦǉƽậǃǦđấǓ,ǦǈƐǃƼǦǁọƸǦǁạƾǦǁươǃƼǦǉƽựƸǦǂộǉǦǁượǉǦđƾ.",
    ["把那个空坛子放远点，碍事。"] = "ĐểǦƸƑƾǦǋƛǦǀƽƇǃƼǦǀƾƶǦǇƶǦǍƶǦƸƽƕǉ,ǦǋướǃƼǦƸƽƁǃǦǆǊƑ.",
    ["松花酒、桂酒……现在正好是喝桂酒的时节。"] = "ǥƖǃƼǦƽǄƶǦǉửǊ,ǦǆǊếǦǉửǊ……ǦƷƁǓǦƼƾờǦđƶǃƼǦǁƐǦǂƖƶǦǉƽưởǃƼǦǇượǊǦǆǊế.",
    ["您在这儿时间长，这儿……真不干净吗？"] = "ƩƼườƾǦởǦđƁǓǦǁƁǊǦǇồƾ,ǦƸƽỗǦǃƐǓ……ǦǉƽựƸǦǈựǦǀƽƇǃƼǦǈạƸƽǦǈẽǦǈƶǄ?",
    ["你们也莫怕，有闹鬼的说法也不是一两天了，这鬼生前都是苦命人，一心想出宫和家人团聚，倒困在这里头了，唉。"] = "ƞƑƸǦǃƼươƾǦƸũǃƼǦđừǃƼǦǈợ,ǦƸƽǊǓệǃǦđồǃǦđạƾǦƸƚǦǂƶǦƸƽẳǃƼǦǅƽảƾǦǃƼƐǓǦǂộǉǦǃƼƐǓǦƽƶƾǦǇồƾ,ǦǃƽữǃƼǦƽồǃǦǂƶǦǃƐǓǦǁƕƸǦǈƾǃƽǦǉƽờƾǦđềǊǦǁƐǦǀẻǦǂệǃƽǦǀƽổ,ǦǂộǉǦǁƛǃƼǦǂǊốǃǦǍǊấǉǦƸǊǃƼǦđǄƐǃǦǉụǦǋớƾǦƼƾƶǦđƔǃƽ,ǦǇốǉǦƸǊộƸǦǁạƾǦƷịǦǋƁǓǦǀƽốǃǦởǦƸƽốǃǦǃƐǓ,ǦƽƶƾǏǏ.",
    ["这新兵发什么疯？"] = "ƞƑƾǦǉƙǃǦǉƁǃǦƷƾǃƽǦǃƐǓǦǅƽƑǉǦđƾƙǃǦƼƔǦǉƽế?",
    ["就是这个荷包，你好厉害！"] = "ƞƽƓǃƽǦǁƐǦƸƑƾǦǉƕƾǦǉƽơǂǦ(ƽƐǦƷƶǄ)ǦǃƐǓ,ǦǃƼươƾǦƼƾỏƾǦǉƽậǉǦđƚ!",
    ["其实，方才你们见到的鬼影并不是鬼。"] = "ǥƽựƸǦǇƶ,ǦƷƚǃƼǦǂƶǦǂƐǦƸƑƸǦǃƼươƾǦǋừƶǦǉƽấǓǦǀƽƇǃƼǦǅƽảƾǦǁƐǦǂƶǦđƁǊ.",
    ["是良酝署的宁姑吧！方才太过害怕，现在想来，那身影好像是她，既然如此，那就没什么好怕的嘛！哎呀，早该想到的，那鬼哭声一定就是淮姑了。"] = "ƧƐǦƩƾǃƽǦƸƇǦƸủƶǦƧươǃƼǦǕẩǃǦǥƽựǦǅƽảƾǦǀƽƇǃƼ!ǦƧƕƸǦǃƃǓǦǈợǦǆǊƑ,ǦƼƾờǦǃƼƽĩǦǁạƾǦǉƽƔǦǤƑǃƼǦǃƼườƾǦđƚǦđƕǃƼǦǁƐǦƼƾốǃƼǦƸƇǦấǓ,ǦǃếǊǦđƃǦǋậǓǦǉƽƔǦƸƽẳǃƼǦƸƚǦƼƔǦđƑǃƼǦǈợǦƸả!ǦÁƾǦƸƽƐ,ǦđƑǃƼǦǁẽǦǅƽảƾǦǃƼƽĩǦǇƶǦǈớǂǦƽơǃ,ǦǉƾếǃƼǦǆǊỷǦǀƽƚƸǦđƚǦƸƽắƸǦƸƽắǃǦǁƐǦƣǄƐƾǦƸƇǦǇồƾ.",
    ["你们……知道？"] = "ƞƑƸǦǃƼươƾ……ǦƷƾếǉǦǈƶǄ?",
    ["宁姑总怕宫里知道了会将淮姑赶走，整日提心胆的，其实，淮姑藏在那里，宫里怎会不知道呢？"] = "ƩƾǃƽǦƸƇǦƸứǦǈợǦǉǇǄǃƼǦƸǊǃƼǦƷƾếǉǦƸƽǊǓệǃǦǈẽǦđǊổƾǦƣǄƐƾǦƸƇǦđƾ,ǦǃƙǃǦǃƼƐǓǦǃƐǄǦƸũǃƼǦǁǄǦǁắǃƼǦƽƃƾǦƽƖǃƼ,ǦǉƽựƸǦǇƶǦƣǄƐƾǦƸƇǦǉǇốǃǦởǦđƚ,ǦǉǇǄǃƼǦƸǊǃƼǦǁƐǂǦǈƶǄǦǂƐǦǀƽƇǃƼǦƷƾếǉǦđượƸǦƸƽứ?",
    ["听姐姐们说，今年冬天眼看着较往常更冷了，要想个办法把淮姑接出来呢。"] = "ƩƼƽƺǦƸƑƸǦǉỷǦǉỷǦƷảǄ,ǦǂƖƶǦđƇǃƼǦǃăǂǦǃƶǓǦǍƺǂǦƸƽừǃƼǦǁạǃƽǦƽơǃǦǉƽườǃƼǦǁệ,ǦǅƽảƾǦǃƼƽĩǦƸƑƸƽǦđưƶǦƣǄƐƾǦƸƇǦǇƶǦǃƼǄƐƾǦǉƽƇƾ.",
    ["你这双眼睛，往左往右往上往下，哪哪的好都看了个遍，就是不往自己身上瞧。旁的我也不说了，单凭你这一颗玲珑心，就不知胜了多少人。"] = "ĐƇƾǦǂắǉǦǃƐǓǦƸủƶǦǃƼươƾ,ǦǃƽƔǃǦǉǇƑƾǦǃƽƔǃǦǅƽảƾǦǃƽƔǃǦǁƙǃǦǃƽƔǃǦǍǊốǃƼ,ǦƸƽỗǦǃƐǄǦǉốǉǦƸũǃƼǦđềǊǦǍƺǂǦǆǊƶǦǂộǉǦǁượǉ,ǦǤǊǓǦƸƽỉǦƸƚǦƷảǃǦǉƽƁǃǦǂƔǃƽǦǁƐǦǀƽƇǃƼǦǃƼƚǦǃƼƐǃƼǦǉớƾ.ǦƩƽữǃƼǦǉƽứǦǀƽƑƸǦǉƶǦǀƽƇǃƼǦƷƐǃǦđếǃ,ǦǃƽưǃƼǦƸƽỉǦǇƾƙǃƼǦǂộǉǦǉấǂǦǁƛǃƼǦǁƾǃƽǦǁǊǃƼǦǃƐǓǦƸủƶǦǃƼươƾ,ǦƸũǃƼǦđƃǦƸƽẳǃƼǦƷƾếǉǦǋượǉǦǍƶǦƷƶǄǦǃƽƾƙǊǦǃƼườƾǦǇồƾ.",
    ["姐姐的舞姿又精进了不少，想必这些日子十分勤勉练习呢。"] = "ƱũǦǉưǦƸủƶǦǉỷǦǉỷǦǁạƾǦǉƾǃƽǦǉƾếǃǦǀƽƇǃƼǦƓǉ,ǦƸƽắƸǦƽẳǃǦǃƽữǃƼǦǃƼƐǓǦǆǊƶǦđƃǦǋƇǦƸƖǃƼǦƸầǃǦǂẫǃǦǁǊǓệǃǦǉậǅǦǃƽỉ.",
    ["勤勉倒是说不上，只是闲着也是闲着，不若多练练。要是有幸能给娘娘解解闷也是好的。"] = "ƞầǃǦǂẫǃǦǉƽƔǦƸũǃƼǦǀƽƇǃƼǦƽẳǃ,ǦƸƽỉǦǁƐǦǇảǃƽǦǇỗƾǦƸũǃƼǦƸƽẳǃƼǦđểǦǁƐǂǦƼƔ,ǦƸƽƾǦƷằǃƼǦǁǊǓệǃǦǉậǅǦǉƽƙǂǦƸƽƕǉ.ǦƩếǊǦƸƚǦǅƽƕƸǦǅƽầǃǦƼƾảƾǦǀƽǊƁǓǦđượƸǦƸƽǄǦǃươǃƼǦǃươǃƼǦǉƽƔǦƸũǃƼǦǉốǉ.",
    ["若是姐姐不嫌弃，我可抚琴为姐姐伴曲。"] = "ƩếǊǦǉỷǦǉỷǦǀƽƇǃƼǦƸƽƙ,ǦǂǊộƾǦƸƚǦǉƽểǦƼảǓǦđƐǃǦǁƐǂǦǃƽạƸǦđệǂǦƸƽǄǦǉỷ.",
    ["妹妹真是与我想到一块儿去了！我正想问妹妹是否肯为我伴曲呢！"] = "ƨǊộƾǦǂǊộƾǦǉƽậǉǦǁƐǦǉƁǂǦđầǊǦƈǦƽợǅǦǋớƾǦǉƶ!ǦǥƶǦƸũǃƼǦđƶǃƼǦđịǃƽǦƽỏƾǦǍƺǂǦǂǊộƾǦƸƚǦǈẵǃǦǁƛǃƼǦđệǂǦǃƽạƸǦƸƽǄǦǉƶǦǀƽƇǃƼǦđƁǓ!",
    ["光是我一人于平地起舞未免枯燥了些，若是能有妹妹的琴曲相和，定能让娘娘尽兴许多！"] = "ƞƽỉǦǂộǉǦǂƔǃƽǦǉƶǦǂƕƶǦǉǇƙǃǦđấǉǦǉǇốǃƼǦƺǦǇằǃƼǦƸƚǦƸƽƕǉǦǉẻǦǃƽạǉ,ǦǃếǊǦƸƚǦǉƾếǃƼǦƸầǂǦƸủƶǦǂǊộƾǦǂǊộƾǦƽƛƶǦƸƖǃƼ,ǦǃƽấǉǦđịǃƽǦǈẽǦǀƽƾếǃǦǃươǃƼǦǃươǃƼǦǉƽƙǂǦǅƽầǃǦƽứǃƼǦǀƽởƾ!",
    ["如此便说定了！待得闲时，我二人可要好好合练一番. "] = "ƱậǓǦǉƽƔǦǆǊǓếǉǦđịǃƽǦǉƽếǦǃƽƗ!ǦĐợƾǦǁƕƸǦǇảǃƽǦǇỗƾ,ǦƽƶƾǦƸƽƕǃƼǦǉƶǦǅƽảƾǦƸƖǃƼǦǃƽƶǊǦƽợǅǦǁǊǓệǃǦǂộǉǦǅƽƺǃǦƸƽǄǦǉƽậǉǦǉốǉ.",
    ["这份章程倒是都合理，也在成本规划范围之内。只是……这几块的预算，报的似乎虚高啊……打回去打回去，重新估算再来！"] = "ƝảǃǦƸƽươǃƼǦǉǇƔǃƽǦǃƐǓǦǍƺǂǦǇƶǦđềǊǦƽợǅǦǁƈ,ǦƸũǃƼǦǃằǂǦǉǇǄǃƼǦǅƽạǂǦǋƾǦǆǊǓǦƽǄạƸƽǦƼƾƑǦǋốǃ.ǦƞƽỉǦǁƐ...ǦǃƼƁǃǦǈƑƸƽǦởǦǂấǓǦƽạǃƼǦǂụƸǦǃƐǓǦƷƑǄǦƼƾƑǦƸƚǦǋẻǦƽơƾǦƸƶǄǦảǄǦǆǊƑ...ǦǉǇảǦǋề,ǦǉǇảǦǋềǦƽếǉ,ǦướƸǦǉƓǃƽǦǁạƾǦǇồƾǦǂƶǃƼǦǉớƾǦđƁǓ!",
    ["这个提议，虽颇为天真，却也无需成本……可以一试！"] = "ĐềǦǃƼƽịǦǃƐǓǦǉǊǓǦǀƽƑǦǃƼƁǓǦǃƼƇ,ǦǃƽưǃƼǦǁạƾǦǀƽƇǃƼǦǉốǃǦǀƗǂ...ǦƸƚǦǉƽểǦǉƽửǦǂộǉǦǁầǃ!",
    ["我每天小投一百次、大投二十次，月投周投日日投——目标就是在宴射的时候能让大人们对我青眼有加！"] = "ƨỗƾǦǃƼƐǓǦǉƶǦđầǊǦǉƾễǃǦǃƽỏǦǉǇăǂǦǁầǃ,ǦǁớǃǦƽƶƾǦǂươƾǦǁầǃ,ǦǉƽƑǃƼǦǃƐǄǦǉǊầǃǦǃƐǄǦǃƼƐǓǦǃƐǄǦƸũǃƼǦǃƗǂǦ——ǦǂụƸǦǉƾƙǊǦǁƐǦǁƕƸǦǓếǃǦǍạǦƸƚǦǉƽểǦǀƽƾếǃǦƸƑƸǦđạƾǦǃƽƁǃǦǅƽảƾǦǃƽƔǃǦǉƶǦƷằǃƼǦƸǄǃǦǂắǉǦǀƽƑƸ!",
    ["你不用做其他的差事吗？"] = "ƩƼươƾǦǀƽƇǃƼǦƸầǃǦǁƐǂǦƸƑƸǦǈƶƾǦǅƽƑƾǦǀƽƑƸǦǈƶǄ?",
    ["你哪来的，这么不会说话，你是谁手底下办事的？"] = "ƩƼươƾǦǉừǦđƁǊǦđếǃǦǂƐǦăǃǦǃƚƾǦǀƗǂǦƸỏƾǦǋậǓ,ǦǃƼươƾǦǁƐǦǃƼườƾǦƸủƶǦƶƾ?",
    ["要是真这么努力，敢不敢跟我比一把？"] = "ƩếǊǦǉƽậǉǦǈựǦǃỗǦǁựƸǦǃƽưǦǋậǓ,ǦƸƚǦǤƑǂǦƸƖǃƼǦǉƶǦǈǄǦǉƐƾǦǂộǉǦǉǇậǃǦǀƽƇǃƼ?",
    ["来！那就拿你练练手！"] = "ĐếǃǦđƁǓ!ǦƱậǓǦǉƽƔǦǁấǓǦǃƼươƾǦǇƶǦđểǦǁǊǓệǃǦǉƶǓǦƸƽƕǉǦǋậǓ!",
    ["官家到是无甚反应，还赦免了王大人的殿前失仪。"] = "ƬǊƶǃǦƼƾƶǦǉǇƑƾǦǁạƾǦƸƽẳǃƼǦƸƚǦǅƽảǃǦứǃƼǦƼƔ,ǦƸƛǃǦǍƑǦǂƾễǃǦǉộƾǦǉƽấǉǦǃƼƽƾǦǉǇướƸǦđƾệǃǦƸƽǄǦƱươǃƼǦđạƾǦǃƽƁǃ.",
    ["但这等妄言，都不用官家做什么，下面人有眼力见的，自己就给处置了。"] = "ƩƽưǃƼǦǁǄạƾǦǋọǃƼǦǃƼƇǃǦǃƐǓ,ǦƸƽẳǃƼǦƸầǃǦƬǊƶǃǦƼƾƶǦǅƽảƾǦǇƶǦǉƶǓ,ǦđƑǂǦǃƼườƾǦǤướƾǦǉǇướǃƼǦƸƚǦǂắǉǦǃƽƔǃǦǉựǦǀƽắƸǦǈẽǦƷƾếǉǦƸƑƸƽǦǍửǦǁƈ.",
    ["听闻此次进封，你有望升为司籍，可有消息？"] = "ƩƼƽƺǦǃƚƾǦđợǉǦǉƾếǃǦǅƽǄǃƼǦǃƐǓ,ǦǂǊộƾǦƸƚǦƽǓǦǋọǃƼǦǉƽăǃƼǦǁƐǂǦǥƾǦǥịƸƽ,ǦđƃǦƸƚǦǉƾǃǦǉứƸǦƼƔǦƸƽưƶ?",
    ["此事还需尚宫定夺，我资历尚浅，不敢抱太大期望。"] = "ƱƾệƸǦǃƐǓǦƸƛǃǦƸƽờǦǥƽượǃƼǦƞǊǃƼǦđịǃƽǦđǄạǉ,ǦǉưǦǁịƸƽǦƸủƶǦǂǊộƾǦƸƛǃǦǃƇǃƼ,ǦǀƽƇǃƼǦǤƑǂǦƇǂǦǀỳǦǋọǃƼǦǆǊƑǦǁớǃ.",
    ["怎么办啊李姐姐……"] = "ƫƽảƾǦǁƐǂǦǈƶǄǦđƁǓǦƧƈǦǉỷǦǉỷ……",
    ["拿来我看看，什么事儿这么拿不定主意。"] = "ĐưƶǦđƁǓǦǉƶǦǍƺǂǦǃƐǄ,ǦƸƽǊǓệǃǦƼƔǦǂƐǦǁạƾǦǀƽƾếǃǦǂǊộƾǦǤǄǦǤựǦǀƽƇǃƼǦǆǊǓếǉǦǉƽếǦǀƾƶ.",
    ["又是遭贼又是闹鬼的，难道真有邪祟作乱？"] = "ƣếǉǦǉǇộǂǦƸắǅǦǁạƾǦđếǃǦǃƽƑǉǦǂƶ,ǦǁẽǦǃƐǄǦǉƽựƸǦǈựǦƸƚǦǉƐǦǉǊếǦǁƐǂǦǁǄạǃǦǈƶǄ?",
    ["小鱼小鱼，你们怎么都不吃东西了呀？官家说了，要吃饱饱才能长得好哦！"] = "ƞƑǦǃƽỏǦƸƑǦǃƽỏ,ǦǈƶǄǦƸƑƸǦƷạǃǦǀƽƇǃƼǦƸƽịǊǦăǃǦƼƔǦƽếǉǦǋậǓ?ǦƬǊƶǃǦƼƾƶǦđƃǦƷảǄǦǇồƾ,ǦǅƽảƾǦăǃǦǉƽậǉǦǃǄǦǉƽƔǦǂớƾǦǂƶǊǦǁớǃǦđượƸǦǃƽƶ!",
    ["做这里的鱼儿真好！每天都能自由自在地游，还有吃不完的吃食，见着了同伴还能互相打个招呼！"] = "ƧƐǂǦƸƑǦởǦđƁǓǦǉƽậǉǦǉƽƓƸƽ!ǦƨỗƾǦǃƼƐǓǦđềǊǦđượƸǦǉựǦǤǄǦǉựǦǉạƾǦƷơƾǦǁộƾ,ǦǁạƾǦƸƚǦǉƽứƸǦăǃǦăǃǦǂƃƾǦǀƽƇǃƼǦƽếǉ,ǦƼặǅǦđượƸǦƷạǃǦƷƘǦƸƛǃǦƸƚǦǉƽểǦƸƽƐǄǦƽỏƾǦǃƽƶǊǦǃữƶ!",
    ["你怎么知道，它们是不是真的乐意被困在这小小的池子里？"] = "ƮƶǄǦǃƼươƾǦƷƾếǉǦđượƸǦƸƽƕǃƼǦƸƚǦǉƽựƸǦǈựǦƸƶǂǦǁƛǃƼǦƷịǦǃƽốǉǦǉǇǄǃƼǦƸƑƾǦƶǄǦƷƗǦǍƓǊǦǃƐǓǦƽƶǓǦǀƽƇǃƼ?",
    ["不论是否乐意，它们也总是活在当下的嘛！当下有饭食、有同伴、有闲暇，就算会有忧愁，那忧愁也已经是那些被送去伙房的鱼儿无法想象的了。"] = "ǝƖǦƸƶǂǦǁƛǃƼǦƽƶǓǦǀƽƇǃƼǦǉƽƔǦƸƽƕǃƼǦǋẫǃǦđƶǃƼǦǈốǃƼǦƸƽǄǦƽƾệǃǦǉạƾǦǂƐ!ǦƣƾệǃǦǉạƾǦƸƚǦǉƽứƸǦăǃ,ǦƸƚǦƷạǃǦƷƘ,ǦƸƚǦǉƽờƾǦƼƾƶǃǦǇảǃƽǦǇỗƾ,ǦǤƖǦƸƚǦưǊǦǅƽƾềǃǦǉƽƔǦƸƑƾǦưǊǦǅƽƾềǃǦđƚǦƸũǃƼǦǁƐǦǉƽứǦǂƐǦǃƽữǃƼǦƸǄǃǦƸƑǦƷịǦđưƶǦǋƐǄǦǃƽƐǦƷếǅǦǀƽƇǃƼǦǉƐƾǦǃƐǄǦǉưởǃƼǦǉượǃƼǦǃổƾǦǇồƾ.",
    ["……你说的也是。"] = "……ƩƼươƾǦǃƚƾǦƸũǃƼǦƸƚǦǁƈ.",
    ["你怎么直接把礼物送给那妹妹了？！官家的兵法上不是这么教的！你应该先隔岸观火、欲擒故纵，必要时配合苦肉计，最后出奇制胜！"] = "ƮƶǄǦǃƼươƾǦǁạƾǦđƺǂǦǁễǦǋậǉǦǉặǃƼǦǉǇựƸǦǉƾếǅǦƸƽǄǦǋịǦǂǊộƾǦǂǊộƾǦđƚǦǉƽế?!ǦƝƾǃƽǦǅƽƑǅǦƸủƶǦƬǊƶǃǦƼƾƶǦđƁǊǦƸƚǦǤạǓǦǃƽưǦǋậǓ!ǦƩƼươƾǦǅƽảƾǦƸƑƸƽǦǃƼạǃǦǆǊƶǃǦƽỏƶ,ǦǤụƸǦƸầǂǦƸốǦǉƕǃƼǦǉǇướƸ,ǦǀƽƾǦƸầǃǦǉƽƾếǉǦǉƽƔǦǅƽốƾǦƽợǅǦǉƽƙǂǦǀƽổǦǃƽụƸǦǀế,ǦƸǊốƾǦƸƖǃƼǦǂớƾǦǍǊấǉǦǀỳǦƸƽếǦǉƽắǃƼ!",
    ["呵，无趣死板的男人。难怪人家一直不来找你。"] = "ƣừ,ǦđồǦǃƶǂǦǉửǦǀƽƇǦǀƽƶǃǦƸứǃƼǦǃƽắƸ.ǦƣƘǃǦƼƔǦǃƼườƾǦǉƶǦƸƽẳǃƼǦƷƶǄǦƼƾờǦǉƽƘǂǦǉƔǂǦđếǃǦǃƼươƾ.",
    ["皮重盖你个不要脸的，赶紧给老子滚过来把你那些假名占的号都删了！不然信不信马老板也护不住你？！"] = "ƝƔǦǥǇọǃƼǦƞƑƾǦđồǦǋƇǦǁƾƙǂǦǈỉǦǃƽƐǦǃƼươƾ,ǦǂƶǊǦƸƕǉǦǆǊƶǦđƁǓǦǍƚƶǦƽếǉǦǂấǓǦƸƑƾǦǉƙǃǦƼƾảǦǂƐǦǃƼươƾǦǤƖǃƼǦđểǦƼƾữǦƸƽỗǦđƾ!ǦƩếǊǦǀƽƇǃƼǦǉƾǃǦƽƶǓǦǀƽƇǃƼǦǁƃǄǦǉửǦđƑǃƽǦƸƽǄǦƨƃǦǁƃǄǦƷảǃǦƸũǃƼǦƸƽẳǃƼǦƷảǄǦǋệǦǃổƾǦǃƼươƾ?!",
    ["我，我也没占几个啊……不也就，皮劳仔、皮劳及、皮安、皮奔仁、皮宰夏……"] = "ǥƶ,ǦǉƶǦƸũǃƼǦđƁǊǦƸƚǦƸƽƾếǂǦƷƶǄǦǃƽƾƙǊǦƸƽỗǦđƁǊ...ǦƸƽẳǃƼǦǆǊƶǦƸũǃƼǦƸƽỉǦƸƚǦƝƔǦƧƶǄǦǥử,ǦƝƔǦƧƶǄǦƞậǅ,ǦƝƔǦƜǃ,ǦƝƔǦƝƇǃǦƩƽƁǃ,ǦƝƔǦǥểǦƣạ...",
    ["马富贵你让开，我今天非得揍他一顿才能睡得着！"] = "ƨƃǦƫƽƕǦƬǊƈǦǃƼươƾǦǉǇƑǃƽǦǇƶ,ǦƽƇǂǦǃƶǓǦǉƶǦǀƽƇǃƼǦǉẩǃǦƽắǃǦǂộǉǦǉǇậǃǦǉƽƔǦǀƽƇǃƼǦǃƼủǦǃƼǄǃǦđượƸ!",
    ["诶，不成不成，皮安这个号他已经转卖给我了，不能删！"] = "Ê,ǦǀƽƇǃƼǦđượƸǦǀƽƇǃƼǦđượƸ,ǦƸƑƾǦǉƙǃǦƝƔǦƜǃǦǃƐǓǦƽắǃǦđƃǦƷƑǃǦǁạƾǦƸƽǄǦǉƶǦǇồƾ,ǦǀƽƇǃƼǦđượƸǦǍƚƶ!",
    ["皮奔仁这个号是我的了，马上就排到了，你们不能清哈！"] = "ƞƑƾǦǉƙǃǦƝƔǦƝƇǃǦƩƽƁǃǦǃƐǓǦǁƐǦƸủƶǦǉƶǦǇồƾ,ǦǈắǅǦđếǃǦǁượǉǦǇồƾ,ǦƸƑƸǦǃƼườƾǦǀƽƇǃƼǦđượƸǦǤọǃǦǤẹǅǦđƁǊǦǃƽƶ!",
    ["还有我还有我，我也买了号的！"] = "ƞƛǃǦƸƚǦǉƶ,ǦƸƛǃǦƸƚǦǉƶǦǃữƶ,ǦǉƶǦƸũǃƼǦǂǊƶǦƸƽỗǦǇồƾ!",
    ["该死的，皮重盖你居然还干起倒卖来了——嗯？人呢？"] = "ƞƽếǉǦǉƾệǉ,ǦƝƔǦǥǇọǃƼǦƞƑƾǦǃƼươƾǦƸưǦǃƽƾƙǃǦƸƛǃǦǤƑǂǦǁƐǂǦǉǇƛǦđầǊǦƸơǦǉǇụƸǦǁợƾǦ——Ǧƽử?ǦƩƼườƾǦđƁǊǦǇồƾ?",
    ["啊，该死的，要是赶不回去上工，雇主答应我的三倍酬劳就要没了……那我娘的药钱……"] = "Ɯ,ǦǉƽậǉǦǁƐǦđƑǃƼǦƸƽếǉ,ǦǃếǊǦǀƽƇǃƼǦǀịǅǦǆǊƶǓǦǋềǦǁƐǂǦǋƾệƸ,ǦƼƾƶǦƸƽủǦƽứƶǦǉǇảǦǉƶǦƷƶǦǁầǃǦǉƽƖǦǁƶǄǦǈẽǦǉƾƙǊǦǉƖǃƼǦǂấǉ...ǦǋậǓǦǉƽƔǦǉƾềǃǦǉƽǊốƸǦƸủƶǦǂẫǊǦǉƽƁǃǦǉƶ...",
    ["……既然马可同乘，驴子也未必不可. 若是你能暂时放下对驴子的恐惧，我倒是能搭你一程。"] = "……ƩếǊǦǃƼựƶǦƸƚǦǉƽểǦƸưỡƾǦƸƖǃƼ,ǦǉƽƔǦǁừƶǦƸũǃƼǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǀƽƇǃƼǦǉƽể.ǦƩếǊǦǃƼươƾǦƸƚǦǉƽểǦǉạǂǦǉƽờƾǦƼạǉǦƷỏǦǃỗƾǦǈợǦƽƃƾǦǋớƾǦǁǄƐƾǦǁừƶ,ǦǉƶǦƸƚǦǉƽểǦƸƽǄǦǃƼươƾǦđƾǦǃƽờǦǂộǉǦđǄạǃ.",
    ["真……真的？游侠可不能反悔！"] = "ǥƽậǉ...ǦǉƽậǉǦǈƶǄ?ǦǝǊǦƽƾệǅǦǀƽƇǃƼǦđượƸǦǃǊốǉǦǁờƾǦđƁǊǦđƚ!",
    ["自然是真的，就是不知，马老板可愿赁驴子于我一用？"] = "ǝĩǦǃƽƾƙǃǦǁƐǦǉƽậǉ,ǦƸƽỉǦǁƐǦǀƽƇǃƼǦƷƾếǉǦƨƃǦǁƃǄǦƷảǃǦƸƚǦǈẵǃǦǁƛǃƼǦƸƽǄǦǉƶǦǉƽǊƙǦƸǄǃǦǁừƶǦǃƐǓǦǂộǉǦƸƽƕǉǦǀƽƇǃƼ?",
    ["可以可以！游侠你直接牵那头驴子去吧，别让包老弟误了时辰！"] = "ĐượƸǦđượƸ!ǦǝǊǦƽƾệǅǦƸứǦǉǇựƸǦǉƾếǅǦǤắǉǦƸǄǃǦǁừƶǦđƚǦđƾǦđƾ,ǦđừǃƼǦđểǦƝƶǄǦǁƃǄǦđệǦǁỡǦǂấǉǦƼƾờǦǁƐǃƽ!",
    ["多谢游侠，这下我的酬劳算是能拿到手了！"] = "ĐƶǦǉạǦǤǊǦƽƾệǅ,ǦǁầǃǦǃƐǓǦǉƽƖǦǁƶǄǦƸủƶǦǉƶǦƸǄƾǦǃƽưǦǃắǂǦƸƽắƸǦǉǇǄǃƼǦǉƶǓǦǇồƾ!",
    ["助人为乐嘛，应该的。"] = "ƢƾƕǅǦǃƼườƾǦǁƐǂǦǃƾềǂǦǋǊƾǦǂƐ,ǦǋƾệƸǦǃƙǃǦǁƐǂǦǉƽƇƾ.",
    ["哟，来了啊？我还以为你嫌弃三倍酬劳太少，舍不得和家里团聚的时间不肯来呢！"] = "Ồ,ǦđếǃǦǇồƾǦƐ?ǦǥƶǦƸứǦǉưởǃƼǦǃƼươƾǦƸƽƙǦƷƶǦǁầǃǦǉƽƖǦǁƶǄǦǁƐǦƓǉ,ǦǀƽƇǃƼǦǃỡǦǇờƾǦƷỏǦǉƽờƾǦƼƾƶǃǦđǄƐǃǦǉụǦǋớƾǦƼƾƶǦđƔǃƽǦǃƙǃǦǀƽƇǃƼǦǉƽƘǂǦđếǃǦƸƽứ!",
    ["你看你说的，这年头，谁会跟钱过不去？"] = "ƩƼƐƾǦǍƺǂǦǃƼƐƾǦǃƚƾǦǀƔƶ,ǦǉƽờƾǦƷǊổƾǦǃƐǓǦƶƾǦǁạƾǦƸƽƙǦǉƾềǃǦƷƶǄǦƼƾờ?",
    ["哟，游侠那么快便回来啦？辛苦了，辛苦了！"] = "Ồ,ǦǤǊǦƽƾệǅǦǆǊƶǓǦǋềǦǃƽƶǃƽǦǋậǓǦǈƶǄ?ǦƱấǉǦǋảǦǇồƾ,ǦǋấǉǦǋảǦǇồƾ!",
    ["方才你们走之后，我琢磨了一下。这赶驴搭客之事，确实可作为我乘轩驿的一项新服务啊！"] = "ƱừƶǦǇồƾǦǈƶǊǦǀƽƾǦƸƑƸǦǃƼườƾǦđƾ,ǦǉƶǦđƃǦǃƼẫǂǦǃƼƽĩǦǂộǉǦƸƽƕǉ.ǦƱƾệƸǦđƑǃƽǦǁừƶǦƸƽởǦǀƽƑƸƽǦǃƐǓǦǉƽựƸǦǈựǦƸƚǦǉƽểǦǉǇởǦǉƽƐǃƽǦǂộǉǦǤịƸƽǦǋụǦǂớƾǦƸủƶǦǥƽừƶǦƣƾƙǃǦǝịƸƽǦǉƶǦđƚ!",
    ["不如便唤为“司驴”罢？"] = "ƣƶǓǦǁƐǦƼọƾǦǁƐǦ\"ǥƾǦƧừƶ\"Ǧđƾ?",
    ["就像那马夫一般，若想当这“司驴”，需得驾驭有道，待客友善，按时准点，且有人愿担保，持有相关凭证，我才能将这驴子赁与他……"] = "ƞũǃƼǦƼƾốǃƼǦǃƽưǦǅƽǊǦđƑǃƽǦǍƺǦǃƼựƶǦǋậǓ,ǦǃếǊǦǂǊốǃǦǁƐǂǦ\"ǥƾǦƧừƶ\"ǦǃƐǓǦǉƽƔǦǅƽảƾǦƷƾếǉǦđƾềǊǦǀƽƾểǃǦđƕǃƼǦƸƑƸƽ,ǦǉƾếǅǦǀƽƑƸƽǦǉƽƁǃǦǉƽƾệǃ,ǦđƕǃƼǦƼƾờǦđƕǃƼǦƼƾấƸ,ǦǁạƾǦǅƽảƾǦƸƚǦǃƼườƾǦđứǃƼǦǇƶǦƷảǄǦǁƃǃƽ,ǦǃắǂǦƼƾữǦƷằǃƼǦƸƽứǃƼǦǁƾƙǃǦǆǊƶǃ,ǦǉƶǦǂớƾǦƸƚǦǉƽểǦƸƽǄǦǃƼườƾǦđƚǦǉƽǊƙǦǁừƶ……",
    ["哎呀，不自觉又唠叨了！总而言之，这张凭证是我新写的，算是一个打版，便赠与游侠了！"] = "ÁƾǦƸƽƐ,ǦǁạƾǦǁảƾǦǃƽảƾǦǉƽƺǄǦƷảǃǦǃăǃƼǦǇồƾ!ǦǥƚǂǦǁạƾǦǁƐ,ǦǉờǦƷằǃƼǦƸƽứǃƼǦǃƐǓǦǁƐǦǉƶǦǂớƾǦǈǄạǃ,ǦƸǄƾǦǃƽưǦƷảǃǦǂẫǊ,ǦǍƾǃǦǉặǃƼǦƸƽǄǦǤǊǦƽƾệǅ!",
    ["就当是方才出手相助的感谢。游侠之后若是有空，随时可凭此证于我乘轩驿赁驴送客！"] = "ƞǄƾǦǃƽưǦǁƐǦǁờƾǦƸảǂǦǉạǦƸƽǄǦǋƾệƸǦǇƶǦǉƶǓǦƼƾƕǅǦđỡǦǋừƶǦǇồƾ.ǦƮƶǊǦǃƐǓǦǃếǊǦǤǊǦƽƾệǅǦƸƚǦǉƽờƾǦƼƾƶǃ,ǦƷấǉǦƸứǦǁƕƸǦǃƐǄǦƸũǃƼǦƸƚǦǉƽểǦǤựƶǦǋƐǄǦƷằǃƼǦƸƽứǃƼǦǃƐǓǦđếǃǦǥƽừƶǦƣƾƙǃǦǝịƸƽǦƸủƶǦǉƶǦǉƽǊƙǦǁừƶǦƸƽởǦǀƽƑƸƽ!",
    ["我乘轩驿在开封也算有名有姓，各个街区内都有我乘轩驿的分驿小驿。只要游侠需要，我们随时可以将驴子送到游侠身边！"] = "ǥƽừƶǦƣƾƙǃǦǝịƸƽǦƸủƶǦǉƶǦởǦƦƽƶƾǦƫƽǄǃƼǦǃƐǓǦƸũǃƼǦƸƚǦƸƽƕǉǦǤƶǃƽǦǉƾếǃƼ,ǦởǦǂỗƾǦǀƽǊǦǅƽốǦđềǊǦƸƚǦǅƽƁǃǦǤịƸƽǦƽǄặƸǦǉǇạǂǦǃƽỏǦƸủƶǦǥƽừƶǦƣƾƙǃǦǝịƸƽ.ǦƞƽỉǦƸầǃǦǤǊǦƽƾệǅǦƸầǃ,ǦƸƽƕǃƼǦǉƶǦƸƚǦǉƽểǦđưƶǦǁừƶǦđếǃǦƷƙǃǦƸạǃƽǦǃƼƐƾǦƷấǉǦƸứǦǁƕƸǦǃƐǄ!",
    ["如此便谢过马老板了！"] = "ƱậǓǦǉƽƔǦǍƾǃǦđƶǦǉạǦƨƃǦǁƃǄǦƷảǃ!",
    ["这位司驴，我能请你帮我个忙吗？"] = "ƱịǦǉưǦǁừƶǦǃƐǓ,ǦǉƶǦƸƚǦǉƽểǦǃƽờǦǃƼươƾǦƼƾƕǅǦǂộǉǦǉƶǓǦǀƽƇǃƼ?",
    ["我认得你！你是我们这儿的第一位司驴！如果，就是如果你现在方便的话，可不可以搭我去个地方？"] = "ǥƶǦǃƽậǃǦǇƶǦƽǊǓǃƽ!ǦƣǊǓǃƽǦƸƽƓǃƽǦǁƐǦǋịǦǥƾǦƧừƶǦđầǊǦǉƾƙǃǦƸủƶǦƸƽƕǃƼǦǉƶ!ǦƩếǊǦƽǊǓǃƽǦǉƽǊậǃǦǉƾệǃ,ǦƸƚǦǉƽểǦƸƽởǦǉƶǦđếǃǦǂộǉǦǃơƾǦđượƸǦǀƽƇǃƼ?",
    ["当然，我会给钱的！我攒的压岁钱，还有这些，都可以给你！不够的话，我还可以打个欠条，最晚……最晚明年拿到压岁钱就能给你了！"] = "ǝĩǦǃƽƾƙǃǦǉƶǦǈẽǦǉǇảǦǉƾềǃ!ǦǥƾềǃǦǂừǃƼǦǉǊổƾǦǉƶǦǉƓƸƽǦƸƚǅ,ǦƸƖǃƼǦǃƽữǃƼǦǉƽứǦǃƐǓǦǃữƶ,ǦđềǊǦƸƚǦǉƽểǦđưƶǦƽǊǓǃƽ!ǦƩếǊǦǀƽƇǃƼǦđủ,ǦǉƶǦƸƛǃǦƸƚǦǉƽểǦǋƾếǉǦƼƾấǓǦǃợ,ǦǂǊộǃǦǃƽấǉ...ǦǂǊộǃǦǃƽấǉǦǁƐǦǃăǂǦǈƶǊǦǃƽậǃǦđượƸǦǉƾềǃǦǂừǃƼǦǉǊổƾǦǁƐǦǉƶǦǉǇảǦƽǊǓǃƽǦđượƸǦǇồƾ!",
    ["那……那，你等我一下，我再去找找……"] = "ƱậǓ...ǦǋậǓ,ǦƽǊǓǃƽǦđợƾǦǉƶǦǂộǉǦƸƽƕǉ,ǦǉƶǦđƾǦǉƔǂǦǉƽƙǂǦǍƺǂ...",
    ["不用啦，逗你的。我可是大侠，不是为了钱才帮忙的。"] = "ƦƽƇǃƼǦƸầǃǦđƁǊ,ǦǉǇƙǊǦƺǂǦǉƽƇƾ.ǦǥƶǦǁƐǦđạƾǦƽƾệǅǦǂƐ,ǦđƁǊǦǅƽảƾǦǋƔǦǉƾềǃǦǂớƾǦƼƾƕǅǦđỡ.",
    ["大侠……真好！那，芳芳想要去百工坊找爹爹，大侠能带芳芳去吗？"] = "ĐạƾǦƽƾệǅ...ǦǉƽậǉǦǉốǉǦǆǊƑ!ǦƱậǓ,ǦƫƽươǃƼǦƫƽươǃƼǦǂǊốǃǦđếǃǦƝƑƸƽǦƞƇǃƼǦƫƽườǃƼǦǉƔǂǦǅƽụǦǉƽƁǃ,ǦđạƾǦƽƾệǅǦƸƚǦǉƽểǦđưƶǦƫƽươǃƼǦƫƽươǃƼǦđƾǦđượƸǦǀƽƇǃƼ?",
    ["这几声“大侠”叫得真好听！来，跟我上驴！"] = "ƨấǓǦǉƾếǃƼǦ\"đạƾǦƽƾệǅ\"ǦǃƐǓǦǃƼƽƺǦǁọǉǦǉƶƾǦǉƽậǉǦđƚ!ǦĐếǃǦđƁǓ,ǦǁƙǃǦǁừƶǦƸƖǃƼǦǉƶ!",
    ["这个不是，那个好像也不是……爹爹到底去哪了呀……"] = "ƞƑƾǦǃƐǓǦǀƽƇǃƼǦǅƽảƾ,ǦƸƑƾǦǀƾƶǦƽƔǃƽǦǃƽưǦƸũǃƼǦƸƽẳǃƼǦǅƽảƾ...ǦǇốǉǦƸǊộƸǦǅƽụǦǉƽƁǃǦđƃǦđƾǦđƁǊǦǇồƾǦǃƽỉ...",
    ["嗯？这不是芳芳么，怎么在这儿？你娘亲呢？"] = "ƣử?ǦĐƁǓǦǀƽƇǃƼǦǅƽảƾǦƫƽươǃƼǦƫƽươǃƼǦǈƶǄ,ǦǈƶǄǦǁạƾǦởǦđƁǓ?ǦƨẫǊǦǉƽƁǃǦƸƽƑǊǦđƁǊ?",
    ["荀叔叔好！我，我是偷偷来的，但我有大侠保护哦，所以没事的！不用告诉我娘亲！"] = "ƞƽƐǄǦǥǊƁǃǦǉƽƕƸǦǉƽƕƸ!ǦƞƽƑǊǦǁƐǦǁƗǃǦđếǃǦđƁǓǦđƚ,ǦǃƽưǃƼǦƸƽƑǊǦƸƚǦđạƾǦƽƾệǅǦƷảǄǦǋệǦǃƽƶ,ǦǃƙǃǦǀƽƇǃƼǦǈƶǄǦđƁǊ!ǦǥƽƕƸǦđừǃƼǦƸƚǦǂƑƸƽǦǂẫǊǦǉƽƁǃǦƸƽƑǊǦǃƽƗ!",
    ["大……大侠？啊，年轻人，真是麻烦你送这小毛孩子来了。"] = "Đạƾ...ǦđạƾǦƽƾệǅ?ǦÀ,ǦǃƼườƾǦǉǇẻǦǉǊổƾ,ǦǉƽậǉǦǅƽƾềǃǦƸậǊǦđƃǦđưƶǦđứƶǦǃƽỏǦǉƾǃƽǦǃƼƽịƸƽǦǃƐǓǦđếǃǦđƁǓ.",
    ["举手之劳。只是我与芳芳这一路来，一直没见到她父亲，你知道她父亲所在么？"] = "ǥƾệǃǦǉƶǓǦǂƐǦǉƽƇƾ.ǦƞƽỉǦǁƐǦǉƶǦǋƐǦƫƽươǃƼǦƫƽươǃƼǦđƾǦǈǊốǉǦǆǊƃǃƼǦđườǃƼǦǃƐǓǦǋẫǃǦƸƽưƶǦǉƽấǓǦǅƽụǦǉƽƁǃǦƸủƶǦƷƗ,ǦǃƼƐƾǦƸƚǦƷƾếǉǦƇǃƼǦấǓǦđƶǃƼǦởǦđƁǊǦǀƽƇǃƼ?",
    ["她爹啊……她爹在前面的棚子里，你们自己去瞧吧。"] = "ƞƽƶǦǃƚǦƐ...ǦƸƽƶǦǃƚǦđƶǃƼǦởǦǉǇǄǃƼǦƸƑƾǦǁƑǃǦǅƽƓƶǦǉǇướƸǦǀƾƶǦǀƔƶ,ǦƸƑƸǦǋịǦǉựǦǆǊƶǦđƚǦǂƐǦǍƺǂ.",
    ["爹……爹爹？！你怎么啦！"] = "ƞƽƶ...ǦƸƽƶǦơƾ?!ǦƞƽƶǦǈƶǄǦǉƽếǦǃƐǓ!",
    ["芳芳？你怎么在这？！……嘶，我的腿……"] = "ƫƽươǃƼǦƫƽươǃƼ?ǦƮƶǄǦƸǄǃǦǁạƾǦởǦđƁǓ?!...ǦƳǊƈǉ,ǦƸƑƾǦƸƽƁǃǦƸủƶǦǉƶ...",
    ["……爹，爹怎么就……呜呜呜……难怪你过节也不回家，原来是腿伤了？"] = "……ƞƽƶ,ǦƸƽƶǦǁƐǂǦǈƶǄǦǉƽếǦǃƐǓ...ǦƽǊǦƽǊǦƽǊ...ǦƽƘǃǦƼƔǦǃƼƐǓǦǁễǦƸƽƶǦƸũǃƼǦǀƽƇǃƼǦǋềǦǃƽƐ,ǦƽƚƶǦǇƶǦǁƐǦƸƽƁǃǦƷịǦǉƽươǃƼǦǇồƾǦǈƶǄ?",
    ["别担心啊，我这伤就看着严重些。没伤筋没动骨的，养养就好了。"] = "ĐừǃƼǦǁǄǦǂƐ,ǦǋếǉǦǉƽươǃƼǦǃƐǓǦƸủƶǦƸƽƶǦǃƽƔǃǦǉƽƔǦǃƼƽƾƙǂǦǉǇọǃƼǦǋậǓǦǉƽƇƾ.ǦƦƽƇǃƼǦǉổǃǦǉƽươǃƼǦđếǃǦƼƁǃǦƸốǉǦđƁǊ,ǦǉẩǂǦƷổǦƸƽƕǉǦǁƐǦǀƽỏƾǦǃƼƶǓǦấǓǦǂƐ.",
    ["爹爹不回去，娘做的浮圆子，就只有我一个人吃了……"] = "ƞƽƶǦǀƽƇǃƼǦǋề,ǦǅƽƖǦǋƾƙǃǦǉửǦǂẫǊǦǉƽƁǃǦǁƐǂǦƸƽỉǦƸƚǦǂộǉǦǂƔǃƽǦƸǄǃǦăǃǦǉƽƇƾ……",
    ["这不好吗？你替爹爹多吃几个就好了。"] = "ƩƽưǦǋậǓǦǀƽƇǃƼǦǉốǉǦǈƶǄ?ǦƞǄǃǦăǃǦǉƽƶǓǦƸƽƶǦǉƽƙǂǦǂấǓǦƸƑƾǦǁƐǦđượƸǦǇồƾ.",
    ["那我还是宁愿爹爹早些好起来，回家同我一起吃圆子！"] = "ƱậǓǦǉƽƔǦƸǄǃǦǉƽƐǦǂǄǃƼǦƸƽƶǦǂƶǊǦǀƽỏƺǦǁạƾ,ǦǋềǦǃƽƐǦƸƖǃƼǦƸǄǃǦăǃǦƷƑǃƽǦǉǇƇƾǦƸƛǃǦƽơǃ!",
    ["坚持……我一定，能坚持……"] = "ƦƾƙǃǦǉǇƔ……ǦǥƶǦǃƽấǉǦđịǃƽ,ǦǅƽảƾǦǀƾƙǃǦǉǇƔ……",
    ["裴老实"] = "ƝƖƾǦƧƃǄǦǥƽựƸ",
    ["这位大哥，你看起来好像需要帮助？"] = "ƱịǦđạƾǦƸƶǦǃƐǓ,ǦǉǇƇǃƼǦƽǊǓǃƽǦƸƚǦǋẻǦǃƽưǦđƶǃƼǦƸầǃǦƼƾƕǅǦđỡ?",
    ["别跟我，说话……一说话，就，难受……"] = "ĐừǃƼǦǃƚƾǦƸƽǊǓệǃǦǋớƾǦǉƶ...ǦƸứǦƽễǦǃƚƾǦƸƽǊǓệǃǦǁƐǦǁạƾǦǉƽấǓǦǀƽƚǦƸƽịǊ...",
    ["呃，茅厕在那边. "] = "Ờ,ǦǃƽƐǦǋệǦǈƾǃƽǦởǦđằǃƼǦǀƾƶǦǀƔƶ.",
    ["……嗯……我知道……"] = "……Ừ……ǦǉƶǦƷƾếǉǦǇồƾ……",
    ["那你怎么往另一头走？"] = "ǥƽếǦǈƶǄǦƽǊǓǃƽǦǁạƾǦđƾǦǋềǦƽướǃƼǦǃƼượƸǦǁạƾ?",
    ["你懂，什么叫，肥水，不，流，外人……"] = "ƩƼươƾǦǉƽƔǦƽƾểǊǦƸƑƾǦƼƔǦƼọƾǦǁƐǦǅƽƖǦǉƽủǓǦƷấǉǦǁưǊǦǃƼǄạƾǦǃƽƁǃǦƸƽứ...",
    ["……你莫不是要憋到回家吧……"] = "……ƦƽƇǃƼǦǁẽǦƽǊǓǃƽǦđịǃƽǦǃƽịǃǦƸƽǄǦǉớƾǦǀƽƾǦǋềǦđếǃǦǃƽƐǦǈƶǄ……",
    ["……田. "] = "……ƭǊộǃƼ.",
    ["要不，你上驴？我帮你一把吧……"] = "ƣƶǓǦǁƐ,ǦƽǊǓǃƽǦǁƙǃǦǁừƶǦđƾ?ǦǥƶǦƼƾƕǅǦƽǊǓǃƽǦǂộǉǦǉƶǓǦǋậǓ……",
    ["终于到了……你还好么？"] = "ƞǊốƾǦƸƖǃƼǦƸũǃƼǦǉớƾǦǃơƾǦǇồƾ...ǦƽǊǓǃƽǦǋẫǃǦổǃǦƸƽứ?",
    ["马上，就要……"] = "ƮắǅǦǍǄǃƼǦǇồƾ……",
    ["哥，你也回来了？你再坚持坚持……我也刚从角门里赶回来……"] = "ƞƶǦƸƶ,ǦƽǊǓǃƽǦƸũǃƼǦǋềǦǇồƾǦǈƶǄ?ǦƣǊǓǃƽǦƼắǃƼǦƼượǃƼǦǉƽƙǂǦƸƽƕǉǦǃữƶǦđƾ...ǦđệǦƸũǃƼǦǋừƶǦǂớƾǦǉừǦƸửƶǦǃƼƑƸƽǦƸƽạǓǦǋềǦđƁǓ……",
    ["裴老在"] = "ƝƖƾǦƧƃǄǦǥạƾ",
    ["不……啊……憋……不……"] = "ƦƽƇǃƼ...Ǧƶ...Ǧǃƽịǃ...ǦǀƽƇǃƼ...",
    ["阿实也回来了？嗯，人呢？……呀，怎么跑隔壁去了？这不浪费么！"] = "ƜǦǥƽựƸǦƸũǃƼǦǋềǦǇồƾǦǈƶǄ?ǦỪǂ,ǦǃƼườƾǦđƁǊǦǇồƾ?Ǧ...ǦƦƔƶ,ǦǈƶǄǦǁạƾǦƸƽạǓǦǈƶǃƼǦǃƽƐǦƽƐǃƼǦǍƚǂǦǇồƾ?ǦǥƽếǦǃƐǓǦƸƽẳǃƼǦǅƽảƾǦǁƐǦǁƃǃƼǦǅƽƓǦǈƶǄ!",
    ["裴母"] = "ƝƖƾǦƨẫǊ",
    ["劳烦司驴了。"] = "ƧƐǂǦǅƽƾềǃǦǥƾǦƧừƶǦǇồƾ.",
    ["温吞男乘客"] = "ƩƶǂǦƽƐǃƽǦǀƽƑƸƽǦƇǃǦƽƛƶ",
    ["还要多久才来啊？"] = "ƞƛǃǦƷƶǄǦǁƁǊǦǃữƶǦǂớƾǦǉớƾǦđƁǓ?",
    ["暴躁男乘客"] = "ƩƶǂǦƽƐǃƽǦǀƽƑƸƽǦǃƚǃƼǦǃảǓ",
    ["这车行得真是稳当！"] = "ƳƺǦǃƐǓǦđƾǦǉƽậǉǦǁƐǦǋữǃƼǦƸƽƃƾ!",
    ["辛苦司驴了。"] = "ƱấǉǦǋảǦƸƽǄǦǥƾǦƧừƶǦǇồƾ.",
    ["好一头前有古人后有来者的小驴！"] = "ĐƕǃƼǦǁƐǦǂộǉǦƸƽƕǦǁừƶǦǃƽỏǦǉƾềǃǦǋƇǦƸổǦǃƽƁǃǦƽậǊǦǋƇǦǁƶƾǦƼƾả!",
    ["讥诮女乘客"] = "ƩữǦƽƐǃƽǦǀƽƑƸƽǦƸƽƁǂǦƸƽọƸ",
    ["我以后怕是乘不惯别人的车咯！"] = "ƮƶǊǦǃƐǓǦƺǦǁƐǦǉƶǦƸƽẳǃƼǦǆǊƺǃǦđƾǦǍƺǦƸủƶǦǃƼườƾǦǀƽƑƸǦǃổƾǦǃữƶǦǇồƾ!",
    ["怎还未来？"] = "ƮƶǄǦǋẫǃǦƸƽưƶǦǉớƾǦǃƽỉ?",
    ["马乘多了，忽地乘乘驴，也是别有一番风味。"] = "ƩƼựƶǦƸưỡƾǦǃƽƾềǊǦǇồƾ,ǦđộǉǦǃƽƾƙǃǦƸưỡƾǦǁừƶǦǂộǉǦƸƽƕǉǦƸũǃƼǦƸƚǦǅƽǄǃƼǦǋịǦǇƾƙǃƼ.",
    ["讥诮男乘客"] = "ƩƶǂǦƽƐǃƽǦǀƽƑƸƽǦƸƽƁǂǦƸƽọƸ",
    ["这车乘得倒是比马车舒坦。"] = "ĐƾǦǍƺǦǃƐǓǦǍƺǂǦǇƶǦƸƛǃǦǉƽǄảƾǦǂƑƾǦƽơǃǦƸảǦǍƺǦǃƼựƶ.",
    ["这车真真治好我乘马车晕眩的旧疾——真是八面通风，呼吸顺畅啊！"] = "ƞƑƾǦǍƺǦǃƐǓǦǉƽựƸǦǈựǦđƃǦƸƽữƶǦǀƽỏƾǦƸăǃǦƷệǃƽǦǀƾǃƽǦǃƾƙǃǦƸƽƚǃƼǦǂặǉǦǀƽƾǦđƾǦǍƺǦǃƼựƶǦƸủƶǦǉƶǦ——ǦǆǊảǦǁƐǦǉƑǂǦǂặǉǦǉƽƇǃƼǦƼƾƚ,ǦƽƇǦƽấǅǦǉƽǊậǃǦǉƾệǃǦǋƇǦƸƖǃƼ!",
    ["不错不错，这车虽然简陋，确是比我想象中舒坦许多！"] = "ƦƽƇǃƼǦǉệǦǀƽƇǃƼǦǉệ,ǦƸƑƾǦǍƺǦǃƐǓǦǉǊǓǦđơǃǦǈơǦǃƽưǃƼǦǉƽựƸǦǈựǦǉƽǄảƾǦǂƑƾǦƽơǃǦǉƶǦǉưởǃƼǦǇấǉǦǃƽƾềǊ!",
    ["哟，赶车的还是个年轻司驴？可稳当些，莫要颠着我了。"] = "Ồ,ǦǃƼườƾǦđƑǃƽǦǍƺǦǁạƾǦǁƐǦǂộǉǦǥƾǦƧừƶǦǉǇẻǦǉǊổƾǦǈƶǄ?ǦƫƽảƾǦǉƽậǉǦǋữǃƼǦǉƶǓǦǋƐǄǦǃƽƗ,ǦđừǃƼǦǁƐǂǦǉƶǦƷịǦǍƚƸǦđƚ.",
    ["暴戾女乘客"] = "ƩữǦƽƐǃƽǦǀƽƑƸƽǦƽǊǃƼǦǤữ",
    ["……应是快到了吧？"] = "……ƞƽắƸǦǁƐǦǈắǅǦǉớƾǦǇồƾǦǃƽỉ?",
    ["温吞女乘客"] = "ƩữǦƽƐǃƽǦǀƽƑƸƽǦƇǃǦƽƛƶ",
    ["这天下司驴都当来找你取取经！"] = "ǥƾǦƧừƶǦǀƽắǅǦǉƽƾƙǃǦƽạǦǃƐǓǦđềǊǦǃƙǃǦđếǃǦǉƔǂǦǃƼươƾǦǂƐǦǉƽỉǃƽǦƼƾƑǄǦǀƾǃƽǦǃƼƽƾệǂ!",
    ["停停停，这是想颠死老娘啊？！"] = "ǝừǃƼǦǤừǃƼǦǤừǃƼ,ǦđịǃƽǦǁƐǂǦƷƐǦđƁǓǦǍƚƸǦƸƽếǉǦƽả?!",
    ["这一路走的都是什么烂路？！司驴你不如去跟驴子学学怎么赶车好了！"] = "ƞƑƾǦđǄạǃǦđườǃƼǦǃƐǓǦđƾǦǀƾểǊǦƼƔǦǂƐǦǃƑǉǦƷƗǉǦǉƽếǦǃƐǓ?!ǦǥƾǦƧừƶ,ǦǃƼươƾǦƸƽƾǦƷằǃƼǦđƾǦǂƐǦƽọƸǦƸǄǃǦǁừƶǦƸƑƸƽǦđƑǃƽǦǍƺǦđƾ!",
    ["车行至哪了……"] = "ƳƺǦđƾǦđếǃǦđƁǊǦǇồƾǦǃƽỉ……",
    ["嚯，你这司驴还挺准时的. "] = "Ồ,ǦǋịǦǥƾǦƧừƶǦǃƐǓǦƸủƶǦǃƼươƾǦƸũǃƼǦđƕǃƼǦƼƾờǦǉƽậǉǦđấǓ.",
    ["车还没来？"] = "ƳƺǦǋẫǃǦƸƽưƶǦǉớƾǦǈƶǄ?",
    ["哈！这驴子好，跑得比好些马都快！"] = "ƣƶ!ǦƞǄǃǦǁừƶǦǃƐǓǦǉốǉǦǉƽậǉ,ǦƸƽạǓǦƸƛǃǦǃƽƶǃƽǦƽơǃǦǀƽốƾǦƸǄǃǦǃƼựƶǦấǓǦƸƽứ!",
    ["这车怎的还没到？莫不是驴在赶车？！"] = "ƞƑƾǦǍƺǦǃƐǓǦǈƶǄǦǋẫǃǦƸƽưƶǦǉớƾ?ǦƦƽƇǃƼǦǁẽǦǁƐǦƸǄǃǦǁừƶǦđƶǃƼǦđƑǃƽǦǍƺǦƸƽắƸ?!",
    ["你这驴赶得不错，下次还找你！"] = "ƩƼươƾǦđƑǃƽǦǁừƶǦǉốǉǦđấǓ,ǦǁầǃǦǈƶǊǦǉƶǦǁạƾǦǉƔǂǦǃƼươƾ!",
    ["这车行得这么慢，莫不是掉坑里了？"] = "ƞƑƾǦǍƺǦǃƐǓǦđƾǦƸƽậǂǦǉƽếǦǀƾƶ,ǦǀƽƇǃƼǦǁẽǦǁƐǦǁọǉǦǍǊốǃƼǦƽốǦǇồƾǦǈƶǄ?",
    ["年轻人，赶车技术确实不赖。回头我就去跟姐妹推荐一番。"] = "ƩƼườƾǦǉǇẻǦǉǊổƾ,ǦǀỹǦǉƽǊậǉǦđƑǃƽǦǍƺǦǉƽựƸǦǈựǦǀƽƇǃƼǦǉệ.ǦƧƑǉǦǃữƶǦǉƶǦǈẽǦđƾǦƼƾớƾǦǉƽƾệǊǦƸƽǄǦƽộƾǦƸƽịǦƺǂǦǂộǉǦǅƽƺǃ.",
    ["噢噢噢你这车有意思！走走走，快让我好好体验一番！"] = "ỒǦồǦồǦƸƑƾǦǍƺǦǃƐǓǦƸủƶǦǃƼươƾǦǉƽƕǦǋịǦđấǓ!ǦĐƾǦđƾǦđƾ,ǦǂƶǊǦđểǦǉƶǦǉǇảƾǦǃƼƽƾệǂǦǂộǉǦƸƽǊǓếǃǦƸƽǄǦǇƶǦǉǇƛǦǃƐǄ!",
    ["亢奋男乘客"] = "ƩƶǂǦƽƐǃƽǦǀƽƑƸƽǦƽưǃƼǦǅƽấǃ",
    ["这车才是真够劲啊！"] = "ƞƑƾǦǍƺǦǃƐǓǦǂớƾǦǉƽựƸǦǈựǦǁƐǦđủǦǅƽƙǦǃƘ!",
    ["舒坦舒坦，这车行得舒坦！下次我定要拉上我兄弟一起来！"] = "ǥƽǄảƾǦǂƑƾǦǉƽǄảƾǦǂƑƾ,ǦƸƑƾǦǍƺǦǃƐǓǦđƾǦǈướǃƼǦǉƽậǉ!ǦƧầǃǦǈƶǊǦǉƶǦǃƽấǉǦđịǃƽǦǅƽảƾǦǀƗǄǦǂấǓǦƼƃǦƽǊǓǃƽǦđệǦƸƖǃƼǦǉớƾǦǂớƾǦđượƸ!",
    ["诶唷，我车呢？"] = "ÁƾǦƸƽƐ,ǦǍƺǦƸủƶǦǉƶǦđƁǊǦǇồƾ?",
    ["恁可得好好学，现在考编制落户，哪个不要官八证？"] = "ƞƑƸǦǃƼươƾǦǅƽảƾǦƽọƸǦƸƽǄǦǉƽậǉǦǉốǉ,ǦǉƽờƾǦƷǊổƾǦǃƐǓǦǉƽƾǦǋƐǄǦƷƾƙǃǦƸƽếǦǃƽậǅǦƽộǦǉịƸƽ,ǦƸƑƾǦǃƐǄǦǂƐǦƸƽẳǃƼǦƸầǃǦǆǊƶǃǦƷƑǉǦƸƽứǃƼ?",
    ["来，跟俺再念——这. "] = "ƩƐǄ,ǦđọƸǦǉƽƺǄǦǁƃǄǦǅƽǊǦǂộǉǦǁầǃǦǃữƶǦ——ǦĐƁǓ.",
    ["这孩儿弄啥哩. "] = "ĐứƶǦǃƽỏǦǃƐǓǦđƶǃƼǦǁƐǂǦƸƑƾǦǉǇƛǦƼƔǦǋậǓ.",
    ["这孩儿弄啥哩，起来一边儿去. "] = "ĐứƶǦǃƽỏǦǃƐǓǦđƶǃƼǦǁƐǂǦƸƑƾǦƼƔǦǉƽế,ǦđứǃƼǦǤậǓǦǉǇƑǃƽǦǈƶǃƼǦǂộǉǦƷƙǃǦđƾ.",
